#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define MCP3008_CH 0
#define SPI_DEVICE 0
#define CE_GPIO 8
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define SCLK_GPIO 11

gpio_context gpio_ctx;
gpio_pin ce_pin = GPIOPIN(CE_GPIO);
gpio_pin mosi_pin = GPIOPIN(MOSI_GPIO);
gpio_pin miso_pin = GPIOPIN(MISO_GPIO);
gpio_pin sclk_pin = GPIOPIN(SCLK_GPIO);

gpio_context spi_ctx;

void spi_init() {
    int ret = gpio_init(&gpio_ctx);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_function(ce_pin, GPIOFUN_OUTPUT_NOPULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set CE pin function\n");
        gpio_exit(&gpio_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_function(mosi_pin, GPIOFUN_OUTPUT_NOPULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set MOSI pin function\n");
        gpio_exit(&gpio_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_function(miso_pin, GPIOFUN_INPUT_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set MISO pin function\n");
        gpio_exit(&gpio_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_function(sclk_pin, GPIOFUN_OUTPUT_NOPULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SCLK pin function\n");
        gpio_exit(&gpio_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpio_open(&spi_ctx, SPI_DEVICE);
    if (ret < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpio_exit(&gpio_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_slave(spi_ctx, CE_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI slave select\n");
        gpio_close(&spi_ctx);
        gpio_exit(&gpio_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_bits(spi_ctx, SCLK_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI clock\n");
        gpio_close(&spi_ctx);
        gpio_exit(&gpio_ctx);
        exit(EXIT_FAILURE);
    }
}

uint16_t spi_transfer(uint8_t cmd, uint8_t *data, size_t len) {
    gpio_clear_bits(spi_ctx, SCLK_PIN);
    for (size_t i = 0; i < len; ++i) {
        gpio_set_bits(spi_ctx, SCLK_PIN);
        gpio_set_bits(spi_ctx, MOSI_PIN);
        gpio_set_bits(spi_ctx, ce_pin);
        gpio_clear_bits(spi_ctx, ce_pin);

        data[i] = gpio_get_bits(spi_ctx, MISO_PIN);
    }
    gpio_clear_bits(spi_ctx, SCLK_PIN);
    gpio_clear_bits(spi_ctx, ce_pin);

    return (uint16_t)(data[1] << 8 | data[0]);
}

void read_moisture() {
    uint8_t cmd = MCP3008_CH;
    uint8_t data[2];

    uint16_t adc_value = spi_transfer(cmd, data, 1);
    printf("Raw ADC value: %d\n", adc_value);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpio_close(&spi_ctx);
    gpio_exit(&gpio_ctx);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    spi_init();

    while (1) {
        read_moisture();
        sleep(1);
    }

    return 0;
}

