#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define MLX91219_ADDR 0x1D
#define ADS1115_ADDR 0x48
#define AIN0 0
#define GAIN_FOUR_POINT_NINE_SIX 0x00
#define MUX_AIN0 0x00
#define SPS_128 0x80

struct timespec last_time;
gpiod_context *ctx;

void i2c_error_handler(const char *str, ...) {
    va_list args;
    va_start(args, str);
    fprintf(stderr, "I2C Error: %s\n", str);
    va_end(args);
}

void sigint_handler(int signum) {
    gpiod_drain(ctx);
    exit(0);
}

int main() {
    int ret;
    ctx = gpiod_new();
    if (!ctx) {
        i2c_error_handler("Failed to create gpiod context");
        return 1;
    }

    ret = gpiod_add_override(ctx, "I2C-1", 0, &gpiod_i2c_params{
        .slave_addr = ADS1115_ADDR,
        .speed_hz = 100000,
    });
    if (ret) {
        i2c_error_handler("Failed to add I2C override");
        gpiod_free(ctx);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_get_chip(ctx, "I2C-1");
    if (!chip) {
        i2c_error_handler("Failed to get I2C chip");
        gpiod_free(ctx);
        return 1;
    }

    struct gpiod_line *scl = gpiod_chip_get_line(chip, "scl");
    struct gpiod_line *sda = gpiod_chip_get_line(chip, "sda");

    if (!scl || !sda) {
        i2c_error_handler("Failed to get SDA/SCL lines");
        gpiod_free(ctx);
        return 1;
    }

    gpiod_export(scl, "I2C-1/scl");
    gpiod_export(sda, "I2C-1/sda");

    signal(SIGINT, sigint_handler);

    // Configure ADS1115
    uint8_t config[2] = {0x01 | MUX_AIN0, GAIN_FOUR_POINT_NINE_SIX | SPS_128};
    ret = gpiod_drain_send(scl, config, sizeof(config));
    if (ret) {
        i2c_error_handler("Failed to write to ADS1115");
        gpiod_unexport(sda, "I2C-1/sda");
        gpiod_unexport(scl, "I2C-1/scl");
        gpiod_free(ctx);
        return 1;
    }

    // Read current
    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if ((now.tv_sec - last_time.tv_sec) * 1000000 + (now.tv_nsec - last_time.tv_nsec) >= 500000000) {
            last_time = now;

            uint8_t buf[2];
            ret = gpiod_drain_receive(sda, buf, sizeof(buf));
            if (ret) {
                i2c_error_handler("Failed to read from ADS1115");
                continue;
            }

            int16_t raw_value = (buf[1] << 8) | buf[0];
            float voltage = raw_value * (5.0 / 65535.0);
            float current = voltage / 1.2; // Assuming 1.2 Ohm resistor

            printf("Current: %.3f A\n", current);
        }
    }

    gpiod_unexport(sda, "I2C-1/sda");
    gpiod_unexport(scl, "I2C-1/scl");
    gpiod_free(ctx);

    return 0;
}

