#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <wiringPiPin.h>

#define FLAME_SENSOR_GPIO 4
#define CE0_GPIO 8
#define MCP3008_SPI_DEV "/dev/spidev0.0"
#define DATA_FILE "flame_data.csv"

struct spi_dev spi;
int spi_fd;
int mcp3008_channel = 0;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int init_spi() {
    spi_fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        return -1;
    }

    if (gpiod_in_init(FLAME_SENSOR_GPIO) < 0) {
        log_error("Failed to initialize GPIO for flame sensor");
        close(spi_fd);
        return -1;
    }

    if (gpiod_in_export(FLAME_SENSOR_GPIO, "flame_sensor") < 0) {
        log_error("Failed to export GPIO for flame sensor");
        close(spi_fd);
        return -1;
    }

    if (gpiod_cmdexe(FLAME_SENSOR_GPIO, "direction", "in") < 0) {
        log_error("Failed to set flame sensor GPIO direction");
        close(spi_fd);
        return -1;
    }

    if (gpiod_in_get_value(FLAME_SENSOR_GPIO) < 0) {
        log_error("Failed to get initial value for flame sensor GPIO");
        close(spi_fd);
        return -1;
    }

    if (gpiod_in_unexport(FLAME_SENSOR_GPIO) < 0) {
        log_error("Failed to unexport GPIO for flame sensor");
        close(spi_fd);
        return -1;
    }

    if (gpiod_out_init(CE0_GPIO) < 0) {
        log_error("Failed to initialize GPIO for MCP3008 CE0");
        close(spi_fd);
        return -1;
    }

    if (gpiod_out_export(CE0_GPIO, "mcp3008_ce0") < 0) {
        log_error("Failed to export GPIO for MCP3008 CE0");
        close(spi_fd);
        return -1;
    }

    if (gpiod_out_direction_set(CE0_GPIO, true) < 0) {
        log_error("Failed to set MCP3008 CE0 direction");
        close(spi_fd);
        return -1;
    }

    return 0;
}

void cleanup() {
    gpiod_out_direction_set(CE0_GPIO, false);
    gpiod_out_unexport(CE0_GPIO);
    gpiod_out_fini();
    gpiod_in_fini();
    close(spi_fd);
}

int main() {
    signal(SIGINT, cleanup);

    if (init_spi() < 0) {
        return 1;
    }

    FILE *fp = fopen(DATA_FILE, "a");
    if (!fp) {
        log_error("Failed to open file for writing");
        cleanup();
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);

        gpiod_trigger(FLAME_SENSOR_GPIO, "falling");
        usleep(1000000); // Wait for 1 second
        gpiod_trigger(FLAME_SENSOR_GPIO, "rising");

        int flame_detected = gpiod_in_get_value(FLAME_SENSOR_GPIO);

        uint16_t adc_value;
        if (spi_transfer(&spi, &mcp3008_channel, 1, NULL, 0) != 1) {
            log_error("SPI transfer failed");
            continue;
        }

        if (spi_transfer(&spi, NULL, 0, &adc_value, sizeof(adc_value)) != 1) {
            log_error("SPI transfer failed");
            continue;
        }

        gpiod_out_set_value(CE0_GPIO, true);
        usleep(1000);
        gpiod_out_set_value(CE0_GPIO, false);

        fprintf(fp, "%ld,%d,%d\n", (int)now, flame_detected, adc_value);
        fflush(fp);
    }

    fclose(fp);
    cleanup();
    return 0;
}

