#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define AIN0_CHANNEL 0
#define DEBOUNCE_DELAY 50
#define POLL_INTERVAL 100
#define FIRE_DURATION 2000
#define TEMP_THRESHOLD 60

static bool running = true;
static volatile bool fire_condition = false;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    running = false;
}

static void setup_gpio(void) {
    struct gpiod_chipchip *chip;
    struct gpiod_chip_config config;
    struct gpiod_chip_line *line;

    if (gpiod_chip_open(&chip, "gpiochip0") < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        goto cleanup;
    }

    memset(&config, 0, sizeof(config));
    config.direction = GPIO_DIR_OUT;

    if (gpiod_chip_config_bulk(chip, &config, 1) < 0) {
        fprintf(stderr, "Failed to configure GPIO lines\n");
        goto close_chip;
    }

    line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        goto config_bulk;
    }

    gpiod_chip_set_value(chip, line, 0);

close_chip:
    gpiod_chip_close(chip);
}

static void setup_i2c(void) {
    if (ads1x15_open(&i2c_handle, I2C_BUS, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to open ADS1x15 on I2C bus %d\n", I2C_BUS);
        goto cleanup;
    }
}

static void setup_flame_sensor(void) {
