#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpio.h>
#include <spidev.h>
#include <stdint.h>

#define FAN_GPIO 18
#define CURRENT_THRESHOLD 100 // Adjust as needed
#define SAMPLE_INTERVAL 1

int spi_fd;
spidev_xfer_t xfer;
char filename[] = "current_log.txt";
FILE *log_file;

void log_current(int adc_value) {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_struct);

    if (log_file == NULL) {
        log_file = fopen(filename, "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%s, %d\n", timestamp, adc_value);
    fflush(log_file);
}

int main() {
    int ret;
    int mlx91219_spi_chip = 0;
    int mlx91219_spi_cs = 0;
    int mlx91219_spi_clk = 1;
    int mlx91219_spi_dio = 2;

    // Initialize GPIO
    ret = gpioInitialize();
    if (ret < 0) {
        perror("gpioInitialize");
        return ret;
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        gpioRelease(ret);
        return spi_fd;
    }

    // Configure SPI
    xfer.cpol = 0;
    xfer.bits_per_word = 8;
    xfer.speed_hz = 1000000;

    if (ioctl(spi_fd, SPI_WRITE, &xfer) < 0) {
        perror("ioctl");
        close(spi_fd);
        gpioRelease(ret);
        return -1;
    }

    // Configure fan GPIO as output
    int fan_gpio = gpioGetByNumber(FAN_GPIO);
    if (fan_gpio < 0) {
        perror("gpioGetByNumber");
        close(spi_fd);
        gpioRelease(ret);
        return fan_gpio;
    }

    ret = gpioSetDirection(fan_gpio, GPIO_OUTPUT);
    if (ret < 0) {
        perror("gpioSetDirection");
        close(spi_fd);
        gpioRelease(ret);
        return ret;
    }

    gpioSetValue(fan_gpio, 0);

    // Open log file
    log_file = fopen("current_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpioRelease(ret);
        return -1;
    }

    while (1) {
        xfer.bits_per_word = 8;
        xfer.delay_usecs = 0;
        xfer.bits = MCP3008_CLOCK | mlx91219_spi_clk;
        xfer.tx_buf = (uint8_t *)&mlx91219_spi_cs;
        xfer.len = 1;
        xfer.rx_buf = (uint8_t *)&mlx91219_spi_cs;
        xfer.count = 1;

        if (ioctl(spi_fd, SPI_IO, &xfer) < 0) {
            perror("SPI_IO");
            break;
        }

        // Read ADC value
        xfer.bits_per_word = 8;
        xfer.delay_usecs = 0;
        xfer.bits = MCP3008_CLOCK | mlx919_spi_clk;
        xfer.tx_buf = (uint8_t *)NULL;
        xfer.len = 0;
        xfer.rx_buf = (uint8_t *)&mlx91219_spi_dio;
        xfer.count = 1;

        if (ioctl(spi_fd, SPI_IO, &xfer) < 0) {
            perror("SPI_IO");
            break;
        }

        int adc_value = (int)xfer.rx_buf[0];

        // Check for sensor absent condition
        if ((adc_value == 0) || (adc_value == 0xFF)) {
            fprintf(stderr, "Sensor absent condition detected\n");
            continue;
        }

        log_current(adc_value);

        // Control fan based on current threshold
        if (adc_value > CURRENT_THRESHOLD) {
            gpioSetValue(fan_gpio, 1);
        } else {
            gpioSetValue(fan_gpio, 0);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    close(spi_fd);
    gpioRelease(ret);

    return 0;
}

