#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR_CO 0x44
#define I2C_ADDR_ADC 0x48
#define RAW_TO_PPM_SLOPE 0.00002222
#define RAW_TO_PPM_OFFSET 0.0

static int co_fd = -1;
static int adc_fd = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_uninit();
    exit(signum);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int init_i2c() {
    int ret;
    ret = gpiod_in_init();
    if (ret < 0) {
        perror("Failed to initialize libgpiod");
        return ret;
    }

    co_fd = gpiod_in_export(gpiod_find_chip("i2c-1", 0), "CO_INT", "CO Sensor Interrupt");
    if (co_fd < 0) {
        perror("Failed to export CO_INT");
        return co_fd;
    }

    adc_fd = gpiod_in_export(gpiod_find_chip("i2c-1", 0), "ADC_INT", "ADC Interrupt");
    if (adc_fd < 0) {
        perror("Failed to export ADC_INT");
        return adc_fd;
    }

    return 0;
}

uint16_t read_adc(int fd) {
    struct gpiod_rigger rigger;
    struct gpiod_line line;
    int ret;

    gpiod_line_get_config(&line, fd);
    gpiod_rigger_configure(&rigger, &line, GPIO_FLAG_NONE, GPIO_FALLING_EDGE);

    ret = gpiod_trigger(&rigger);
    if (ret < 0) {
        perror("Failed to trigger ADC interrupt");
        return -1;
    }

    // Simulate reading 16-bit raw value from ADC
    return rand() % 0x10000;
}

double raw_to_ppm(uint16_t raw_value) {
    return RAW_TO_PPM_SLOPE * raw_value + RAW_TO_PPM_OFFSET;
}

int log_co_value(double ppm) {
    if (log_file == NULL) {
        log_file = fopen("co_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    time_t now = time(NULL);
    fprintf(log_file, "%ld,%f\n", now, ppm);
    fflush(log_file);

    return 0;
}

int main() {
    int ret;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    ret = init_i2c();
    if (ret < 0) {
        return ret;
    }

    while (1) {
        uint16_t adc_raw = read_adc(adc_fd);
        if (adc_raw < 0) {
            break;
        }

        double ppm = raw_to_ppm(adc_raw);
        if (log_co_value(ppm) < 0) {
            break;
        }

        usleep(5000000); // Sleep for 5 seconds
    }

    gpiod_uninit();
    if (co_fd >= 0) {
        gpiod_in_unexport(co_fd);
    }
    if (adc_fd >= 0) {
        gpiod_in_unexport(adc_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

