#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpio.h>

#define I2C_ADDR_1 0x18
#define I2C_ADDR_2 0x19
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define NUM_SAMPLES 10

struct i2c_dev {
    gpio_context *gpio;
    gpio_pininfo pins[2];
    int fd;
};

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    // Add code here to close I2C handles and clean up resources
}

void setup_i2c(struct i2c_dev *dev) {
    dev->gpio = gpio_init();
    if (!dev->gpio) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    memset(dev->pins, 0, sizeof(dev->pins));

    dev->pins[0].line = 2; // GPIO2/BCM2
    dev->pins[0].pull = GPIO_PULL_UP;
    dev->pins[0].value = 0;

    dev->pins[1].line = 3; // GPIO3/BCM3
    dev->pins[1].pull = GPIO_PULL_UP;
    dev->pins[1].value = 0;

    if (gpio_set_wd(dev->gpio, dev->pins, 2) < 0) {
        perror("Failed to set GPIO direction");
        exit(EXIT_FAILURE);
    }

    dev->fd = i2c_open(I2C_ADDR_1);
    if (dev->fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

float read_sample(struct i2c_dev *dev, int addr) {
    uint8_t data[2];
    int ret;

    ret = i2c_rdwr(dev->fd, &addr, 1, data, 2, I2C_MST_RD);
    if (ret < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", ret);
        return -999.0;
    }

    // Assuming data[0] and data[1] contain the 16-bit ADC values
    uint16_t adc_value = (data[0] << 8) | data[1];
    float sound_level = (float)adc_value / 65535 * 100; // Convert to dB

    return sound_level;
}

int main() {
    struct i2c_dev dev1, dev2;

    signal(SIGINT, sigint_handler);

    setup_i2c(&dev1);
    setup_i2c(&dev2);

    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        float samples[NUM_SAMPLES] = {0};
        for (int i = 0; i < NUM_SAMPLES; i++) {
            samples[i] = read_sample(&dev1, I2C_ADDR_1);
            if (samples[i] == -999.0) break; // Stop sampling if an error occurred

            usleep(SAMPLE_INTERVAL);
        }

        if (samples[0] == -999.0) {
            fprintf(log_file, "Error: Sample failed\n");
            continue;
        }

        float avg_sound_level = 0;
        for (int i = 0; i < NUM_SAMPLES; i++) {
            avg_sound_level += samples[i];
        }
        avg_sound_level /= NUM_SAMPLES;

        time_t now = time(NULL);
        fprintf(log_file, "%ld.%03ld: %f dB\n", (long)now, (now % 1000) * 1000, avg_sound_level);

        // Repeat the same process for dev2
    }

    fclose(log_file);
    i2c_close(dev1.fd);
    i2c_close(dev2.fd);
    gpio_free(dev1.gpio);
    gpio_free(dev2.gpio);

    return 0;
}

