void spi_init() {
    spi.spi_fd = spi_open(&spi, "spi0");
    if (spi.spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    spi.mode = SPI_MODE_0;
    spi.bits_per_word = 10;
    spi.max_speed_hz = 1000000;

    if (spi_negotiate(spi.spi_fd, &spi) != 0) {
        fprintf(stderr, "Failed to negotiate SPI parameters\n");
        exit(EXIT_FAILURE);
    }
}

void led_init() {
    const char *led_chip_name = "/dev/gpiod/led";
    const char *led_chip_params[] = {
        "label=LED",
        "export",
        NULL
    };

    if (gpiod_chip_open(&chip, led_chip_name, led_chip_params) < 0) {
        fprintf(stderr, "Failed to open GPIO chip for LED\n");
        exit(EXIT_FAILURE);
    }

    const char *led_line = "LED";
    struct gpiod_line *led = gpiod_chip_get_line(&chip, led_line);
    if (!led) {
        fprintf(stderr, "Failed to get LED line\n");
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(led, NULL);
    gpiod_line_set_direction(led, GPIO_OUT);
    gpiod_line_set_active(led, 0);
}

void mcp3008_read(uint8_t channel, uint16_t *value) {
    spi_transfer(&spi, &channel, 1);
    spi_transfer(&spi, NULL, 0);
    *value = (uint16_t)((spi.buf[0] << 8) | spi.buf[1]);
}

void sample_mic(uint8_t cs, uint16_t *adc_value) {
    gpiod_line_trigger(cs, 0);
    mcp3008_read(0, adc_value);
    gpiod_line_trigger(cs, 1);
}

int main() {
