#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <wiringPiI2C.h>

#define MLX91204_ADDR 0x1D
#define ADS1115_ADDR 0x48
#define BUFFER_SIZE 100
#define SAMPLING_RATE 10
#define LED_PIN 17
#define THRESHOLD 50.0

typedef struct {
    int16_t data[BUFFER_SIZE];
    int index;
    float sum;
} CurrentBuffer;

CurrentBuffer buffer;

void init_buffer(CurrentBuffer *b) {
    b->index = 0;
    b->sum = 0;
    memset(b->data, 0, sizeof(b->data));
}

int i2c_read(uint8_t reg, uint8_t *data, int len) {
    int fd = wiringPiI2CSetup(ADS1115_ADDR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (i2c_rdwr(fd, true, len, (void *) &reg, NULL) != len) {
        perror("Failed to read from I2C device");
        close(fd);
        return -1;
    }

    if (i2c_rdwr(fd, false, len, data, NULL) != len) {
        perror("Failed to read from I2C device");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

float adc_to_current(int16_t adc_value) {
    // Assuming MLX91204 has a sensitivity of 185.5 mV/A
    return (float)adc_value * 185.5 / 65535;
}

void signal_handler(int sig) {
    (void)sig;
    printf("SIGINT received, cleaning up...\n");
    // Turn off LED
    gpioWrite(LED_PIN, 0);
    // Release resources
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to initialize wiringPi\n");
        return 1;
    }

    if (gpioInit() == -1) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 1);

    init_buffer(&buffer);

    while (1) {
        uint8_t data[2];
        if (i2c_read(0x00, data, 2) < 0) {
            continue;
        }

        int16_t adc_value = (data[0] << 8) | data[1];
        float current = adc_to_current(adc_value);
        buffer.sum += current;
        buffer.data[buffer.index] = current;
        buffer.index = (buffer.index + 1) % BUFFER_SIZE;

        if (buffer.index == 0) {
            float avg_current = buffer.sum / BUFFER_SIZE;
            if (avg_current > THRESHOLD) {
                gpioWrite(LED_PIN, 0);
            }
        }

        usleep(100000); // 10 Hz sampling rate
    }

    return 0;
}

