#define TCS34725_ADDR 0x29
#define ID_REG 0x00
#define CLEAR_REG 0x01
#define RED_REG 0x02
#define GREEN_REG 0x03
#define BLUE_REG 0x04
#define REGISTER_COUNT 5

static struct gpiod_chip chip;
static struct gpiod_line i2c_sd_a;
static struct gpiod_line i2c_sd_d;
static struct gpiod_line i2c_scl;
static struct gpiod_line i2c_sda;
static struct gpiod_context *ctx;
static FILE *fp;
static int error_count = 0;
static char header[] = "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n";

void sigint_handler(int signum) {
    gpiod_drain_delete(ctx);
    fclose(fp);
    exit(0);
}

void init_i2c() {
    int ret;

    ret = gpiod_chip_open(&chip, "i2c-1");
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_add_lines(&chip, &i2c_sd_a, &i2c_sd_d, &i2c_scl, &i2c_sda);
    if (ret < 0) {
        fprintf(stderr, "Failed to add I2C lines\n");
        gpiod_chip_close(&chip);
        exit(EXIT_FAILURE);
    }

    ctx = gpiod_chip_get_context(&chip);
    gpiod_chip_start(&chip);
}

void cleanup_i2c() {
    gpiod_chip_stop(&chip);
    gpiod_chip_drain(&chip);
    gpiod_chip_release(&chip);
    gpiod_context_release(ctx);
}

void init_sensor() {
    uint8_t id;
    int ret;

    ret = gpiod_write(&i2c_sd_a, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to start I2C transfer\n");
        error_count++;
        return;
    }

    ret = gpiod_write(&i2c_sd_d, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to start I2C transfer\n");
        error_count++;
        return;
    }

    ret = gpiod_write(&i2c_sda, TCS34725_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to write sensor address\n");
        error_count++;
        return;
    }

    ret = gpiod_read(&i2c_sda, &id, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        error_count++;
        return;
    }

    if (id != TCS34725_ADDR) {
        fprintf(stderr, "Sensor ID mismatch\n");
        error_count++;
        return;
    }

    error_count = 0;
}

void read_color_values(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int ret;

    ret = gpiod_write(&i2c_sd_a, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to start I2C transfer\n");
        error_count++;
        return;
    }

    ret = gpiod_write(&i2c_sd_d, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to start I2C transfer\n");
        error_count++;
        return;
    }

    ret = gpiod_write(&i2c_sda, CLEAR_REG);
    if (ret < 0) {
        fprintf(stderr, "Failed to write clear register\n");
        error_count++;
        return;
    }

    ret = gpiod_read(&i2c_sda, clear, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read clear value\n");
        error_count++;
        return;
    }

    ret = gpiod_write(&i2c_sda, RED_REG);
    if (ret < 0) {
        fprintf(stderr, "Failed to write red register\n");
        error_count++;
        return;
    }

    ret = gpiod_read(&i2c_sda, red, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read red value\n");
        error_count++;
        return;
    }

    ret = gpiod_write(&i2c_sda, GREEN_REG);
    if (ret < 0) {
        fprintf(stderr, "Failed to write green register\n");
        error_count++;
        return;
    }

    ret = gpiod_read(&i2c_sda, green, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read green value\n");
        error_count++;
        return;
    }

    ret = gpiod_write(&i2c_sda, BLUE_REG);
    if (ret < 0) {
        fprintf(stderr, "Failed to write blue register\n");
        error_count++;
        return;
    }

    ret = gpiod_read(&i2c_sda, blue, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read blue value\n");
        error_count++;
        return;
    }
}

void log_color_values() {
    static struct tm tm;
    char timestamp[20];

    time(&tm);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fp == NULL) {
        fp = fopen("color_log.csv", "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open color_log.csv\n");
            exit(EXIT_FAILURE);
        }
        if (fputs(header, fp) < 0) {
            fprintf(stderr, "Failed to write header to color_log.csv\n");
            fclose(fp);
            exit(EXIT_FAILURE);
        }
    }

    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, *clear, *red, *green, *blue);
    fflush(fp);
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    nanosleep(&ts, NULL);

    init_i2c();
    init_sensor();

    if (error_count >= 3) {
        cleanup_i2c();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        uint16_t clear, red, green, blue;
        log_color_values();
        read_color_values(&clear, &red, &green, &blue);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += 1;
        nanosleep(&ts, NULL);
    }

    cleanup_i2c();
    fclose(fp);
    return 0;
}

