#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1
#define SPI_DEVICE "/dev/spidev0.0"
#define CE0_GPIO 8
#define MISO_GPIO 9
#define MOSI_GPIO 10
#define SCLK_GPIO 11

int spi_fd;

void init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_RCSWMODE, 0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

