static gpiod_line *gpio17;
static gpiod_line *ce0;
static gpiod_line *sclk;
static gpiod_line *mosi;
static gpiod_line *miso;

void sigint_handler(int signum) {
    gpiod_drain_delete(gpio17);
    gpiod_drain_delete(ce0);
    gpiod_drain_delete(sclk);
    gpiod_drain_delete(mosi);
    gpiod_drain_delete(miso);
    gpiod_unbind(chip);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    chip = gpiod_chip_open(&gpiod_chip_default, "SPI0");
    if (!chip) {
        fprintf(stderr, "Failed to open SPI0 chip\n");
        return 1;
    }

    gpio17 = gpiod_chip_get_line(chip, "GPIO17");
    if (!gpio17) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_export(gpio17, "GPIO17");
    gpiod_line_set_dir(gpio17, GPIO_DIR_OUT);

    ce0 = gpiod_chip_get_line(chip, "CE0");
    if (!ce0) {
        fprintf(stderr, "Failed to get CE0 line\n");
        gpiod_line_unexport(gpio17);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_export(ce0, "CE0");
    gpiod_line_set_dir(ce0, GPIO_DIR_OUT);

    sclk = gpiod_chip_get_line(chip, "SCLK");
    if (!sclk) {
        fprintf(stderr, "Failed to get SCLK line\n");
        gpiod_line_unexport(ce0);
        gpiod_line_unexport(gpio17);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_export(sclk, "SCLK");
    gpiod_line_set_dir(sclk, GPIO_DIR_OUT);

    mosi = gpiod_chip_get_line(chip, "MOSI");
    if (!mosi) {
        fprintf(stderr, "Failed to get MOSI line\n");
        gpiod_line_unexport(sclk);
        gpiod_line_unexport(ce0);
        gpiod_line_unexport(gpio17);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_export(mosi, "MOSI");
    gpiod_line_set_dir(mosi, GPIO_DIR_OUT);

    miso = gpiod_chip_get_line(chip, "MISO");
    if (!miso) {
        fprintf(stderr, "Failed to get MISO line\n");
        gpiod_line_unexport(mosi);
        gpiod_line_unexport(sclk);
        gpiod_line_unexport(ce0);
        gpiod_line_unexport(gpio17);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_export(miso, "MISO");
    gpiod_line_set_dir(miso, GPIO_DIR_IN);

    if (signal(SIGINT, sigint_handler) == SIG_ERR || signal(SIGTERM, sigterm_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open current_log.csv\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (fgets(log_file, sizeof(log_file), "Current (A),Timestamp\n") == NULL) {
        fprintf(log_file, "Current (A),Timestamp\n");
    }
    fclose(log_file);
    open(log_file, "a");

    while (true) {
        int retries = 0;
        int adc_value = -1;

        ce0_value(ce0, 1);
        sclk_value(sclk, 1);
        mosi_value(mosi, 0);

        for (int i = 0; i < 8; i++) {
            mosi_value(mosi, (MLX91211_CHANNEL & (1 << i)) >> i);
        }

        for (int j = 0; j < MAX_RETRIES; j++) {
            if (gpiod_batch_process(chip) < 0) {
                fprintf(stderr, "SPI communication failed, retrying...\n");
                continue;
            }
            adc_value = miso_value(miso);
            if (adc_value != -1) {
                break;
            }
        }

        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
            break;
        }

        double voltage = (double)adc_value * 3.3 / 1023;
        double current = voltage / 2; // MLX91211 has a sensitivity of 187.5 mV/A

        if (current > CURRENT_THRESHOLD) {
            gpiod_line_set_value(gpio17, 0);
            fprintf(log_file, "%.2f,%lu\n", current, time(NULL));
            fprintf(log_file, "OVERCURRENT EVENT\n");
            sleep(1);
            gpiod_line_set_value(gpio17, 1);
        } else {
            fprintf(log_file, "%.2f,%lu\n", current, time(NULL));
        }

        ce0_value(ce0, 0);
        sclk_value(sclk, 0);
    }

    gpiod_drain_delete(gpio17);
    gpiod_drain_delete(ce0);
    gpiod_drain_delete(sclk);
    gpiod_drain_delete(mosi);
    gpiod_drain_delete(miso);
    gpiod_unbind(chip);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

