#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define MLX90817_ADDR 0x5A
#define I2C_BUS "0"
#define LOG_FILE "pressure_log.csv"

struct mlx90817_data {
    int fd;
    int reg_addr;
};

static int mlx90817_read(struct mlx90817_data *data, uint8_t *buf, size_t len) {
    int ret;
    ret = ioctl(data->fd, I2C_SLAVE, MLX90817_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C slave address: %d\n", ret);
        return -1;
    }

    ret = ioctl(data->fd, I2C_RDWR, buf);
    if (ret < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", data->reg_addr, ret);
        return -1;
    }

    return 0;
}

int main() {
    struct mlx90817_data mlx90817;
    int fd;
    char timestamp[32];
    uint8_t pressure_data[3];
    FILE *log_file;

    gpiod_init();
    if (gpiod_request_available_device(0, &gpiod_chip) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90817_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C slave address\n");
        close(fd);
        return 1;
    }

    mlx90817.fd = fd;
    mlx90817.reg_addr = 0x00; // Replace with the correct register address for pressure data

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        return 1;
    }

    fprintf(log_file, "Timestamp,Pressure (kPa)\n");
    fflush(log_file);

    while (1) {
        time_t now = time(NULL);
        struct tm *time_struct = localtime(now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_struct);

        if (mlx90817_read(&mlx90817, pressure_data, sizeof(pressure_data)) == 0) {
            uint16_t pressure = (pressure_data[0] << 8) | pressure_data[1];
            fprintf(log_file, "%s,%.3f\n", timestamp, pressure * 0.01); // Convert to kPa
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read pressure data, skipping this iteration\n");
            continue;
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    close(fd);
    gpiod_cleanup();

    return 0;
}

