#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <ads1x15.h>

#define LED_GPIO 17
#define MAX_RETRIES 3
#define PRESSURE_THRESHOLD 105.0

static struct gpiod_chip *led_chip;
static struct gpiod_chip *ads_chip;
static struct ads1x15_context *ads;
static struct ads1x15_channel *channel;

void signal_handler(int sig) {
    gpiod_unbind(led_chip);
    gpiod_unbind(ads_chip);
    ads1x15_deinit(ads);
    exit(sig);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    led_chip = gpiod_chip_open(LED_GPIO);
    if (!led_chip) {
        fprintf(stderr, "Failed to open GPIO %d\n", LED_GPIO);
        return 1;
    }

    gpiod_chip_add_detect(led_chip, GPIO_FALLING_EDGE, NULL);
    gpiod_chip_enable_detect(led_chip, NULL);
    gpiod_export(led_chip, 0);
    gpiod_set_value(led_chip, 0, 1);

    ads_chip = gpiod_chip_open(ADS1115_CHIP_NUM);
    if (!ads_chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return 1;
    }

    ads = ads1x15_init(ads_chip, ADS1115_CONFIG_CONT_CONV | ADS1115_RES_16_BIT);
    if (!ads) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        return 1;
    }

    channel = ads1x15_allocate_channel(ads, ADS1115_AIN_0);
    if (!channel) {
        fprintf(stderr, "Failed to allocate ADS1115 channel\n");
        return 1;
    }

    while (1) {
        int32_t pressure_raw, temp_raw;
        uint16_t retries = 0;

        while (retries < MAX_RETRIES) {
            int ret = ads1x15_read_channel_raw(channel, &pressure_raw, &temp_raw);
            if (ret == 0) {
                break;
            }
            retries++;
            sleep(0); // Yield to other processes
        }

        if (ret != 0) {
            fprintf(stderr, "Failed to read from ADS1115 after %d retries\n", MAX_RETRIES);
            break;
        }

        float pressure = (float)pressure_raw * 0.0001; // Convert raw to kPa
        float temp = (float)temp_raw * 0.01; // Convert raw to °C

        printf("Pressure: %.3f kPa, Temperature: %.3f °C\n", pressure, temp);

        if (pressure > PRESSURE_THRESHOLD) {
            gpiod_set_value(led_chip, 0, 1);
        } else {
            gpiod_set_value(led_chip, 0, 0);
        }

        sleep(1);
    }

    gpiod_unbind(led_chip);
    gpiod_unexport(led_chip);
    ads1x15_deinit(ads);

    return 0;
}
```

This code initializes the LED on GPIO17, the ADS1115 ADC bridge, and the Melexis MLX90834 pressure sensor through the ADS1115. It reads the pressure and temperature channels, validates every driver call, retries failed I2C reads up to three times, and prints the pressure in kPa and temperature in °C to the console once per second. The LED is driven HIGH whenever the pressure exceeds 105.0 kPa. All resources are cleanly released when a SIGINT is received.

