#include <gpiod.h>
#include <mcp3008.h>

#define MELEXIS_CHANNEL 0
#define CURRENT_THRESHOLD 1000 // 10 A
#define SAMPLE_INTERVAL 100000 // 100 ms
#define LOG_FILE "current_log.txt"

static FILE *log_file = NULL;
static mcp3008_t mcp3008;
static gpiod_chip *chip;
static gpiod_line *gpio27_line;

void log_current(double current) {
    if (log_file == NULL) {
        return;
    }

    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    fprintf(log_file, "%02d:%02d:%02d, Current: %.2f A\n",
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec, current);
    fflush(log_file);
}

void shutdown_motor() {
    if (gpio27_line != NULL) {
        gpiod_line_set_value(gpio27_line, 1);
        gpio27_line = NULL;
    }
}

void init_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        exit(EXIT_FAILURE);
    }

    gpio27_line = gpiod_chip_get_line(chip, "GPIO27");
    if (gpio27_line == NULL) {
        fprintf(stderr, "Failed to get GPIO27 line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_add(gpio27_line, GPIO_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO27 line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio27_line_set_value(gpio27_line, 0);
}

void cleanup_gpio() {
    if (gpio27_line != NULL) {
        gpiod_line_release(gpio27_line);
        gpio27_line = NULL;
    }

    gpiod_chip_close(chip);
}

void init_mcp3008() {
    int ret;

    ret = mcp3008_init(&mcp3008, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_mcp3008() {
    mcp3008_deinit(&mcp3008);
}

void signal_handler(int signum) {
    cleanup_mcp3008();
    cleanup_gpio();
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_gpio();
    init_mcp3008();

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_mcp3008();
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (true) {
        double current;
        ret = mcp3008_read(&mcp3008, MELEXIS_CHANNEL, &current);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }

        if (current > CURRENT_THRESHOLD) {
            shutdown_motor();
            fprintf(stderr, "OVERCURRENT: Current %.2f A\n", current);
            break;
        }

        log_current(current);

        usleep(SAMPLE_INTERVAL);
    }

    cleanup_mcp3008();
    cleanup_gpio();
    fclose(log_file);

    return EXIT_SUCCESS;
}

