#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpio.h>

#define CO_CHANNEL 0
#define CO_THRESHOLD 2.5
#define SPI_DEVICE 0
#define CE0_GPIO 8
#define SCLK_GPIO 11
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define ALARM_GPIO 4
#define MAX_RETRIES 5

static FILE *log_file = NULL;
static gpiod_chip *chip;
static gpiod_line *ce0_line;
static gpiod_line *sclk_line;
static gpiod_line *mosi_line;
static gpiod_line *miso_line;
static gpiod_line *alarm_line;
static spi_device *spi;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        exit(0);
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    gpiod_line_release(ce0_line);
    gpiod_line_release(sclk_line);
    gpiod_line_release(mosi_line);
    gpiod_line_release(miso_line);
    gpiod_line_release(alarm_line);

    spi_close(spi);
    gpiod_chip_unref(chip);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    ce0_line = gpiod_chip_get_line(chip, "CE0");
    sclk_line = gpiod_chip_get_line(chip, "SCLK");
    mosi_line = gpiod_chip_get_line(chip, "MOSI");
    miso_line = gpiod_chip_get_line(chip, "MISO");
    alarm_line = gpiod_chip_get_line(chip, "ALARM");

    if (!ce0_line || !sclk_line || !mosi_line || !miso_line || !alarm_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    gpiod_line_export(ce0_line, NULL);
    gpiod_line_export(sclk_line, NULL);
    gpiod_line_export(mosi_line, NULL);
    gpiod_line_export(miso_line, NULL);
    gpiod_line_export(alarm_line, NULL);

    spi = spi_device_open(SPI_DEVICE, 1000000);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    if (spi_device_configure(spi, 0, 0, SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to configure SPI device\n");
        return 1;
    }

    log_file = fopen("co_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        double voltage;
        int retries = 0;

        gpiod_line_set_value(alarm_line, 0);

        while (retries < MAX_RETRIES) {
            int ret = spi_transfer(spi, &CO_CHANNEL, NULL, 2);
            if (ret >= 0) {
                voltage = (double)((ret >> 16) & 0xFF) * 2.5 / 1023.0;
                break;
            } else {
                fprintf(stderr, "SPI transfer failed, retrying...\n");
                retries++;
                sleep(1);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, exiting\n");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,Voltage: %.2f V\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, voltage);

        fclose(log_file);
        log_file = fopen("co_log.txt", "a");

        if (voltage > CO_THRESHOLD) {
            gpiod_line_set_value(alarm_line, 1);
        } else {
            gpiod_line_set_value(alarm_line, 0);
        }

        sleep(1);
    }

    return 0;
}

