#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <mcp3008.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define VDD_PIN 1
#define DGND_PIN 26
#define CLK_PIN 11
#define DOUT_PIN 9
#define DIN_PIN 10
#define CS_PIN 8

int spi_fd;
MCP3008_t mcp3008;
FILE *log_file;

void spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (gpiod_export(&mcp308_pins, NULL) < 0) {
        perror("Failed to export GPIOs");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    mcp308_chans[SPI_CHANNEL] = gpiod_chip_get_chip(&mcp308_pins, "spi-bus-cs");
    if (!mcp308_chans[SPI_CHANNEL]) {
        fprintf(stderr, "Failed to get SPI chip\n");
        close(spi_fd);
        gpiod_unexport(&mcp308_pins);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_set_owner(mcp308_chans[SPI_CHANNEL], GET_GPIO_LINE(CS_PIN));
    gpiod_chip_set_direction(mcp308_chans[SPI_CHANNEL], GPIO_DIR_OUT);

    if (ioctl(spi_fd, SPI_WRITER_DUART, &mcp3008) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_unexport(&mcp308_pins);
        exit(EXIT_FAILURE);
    }
}

void spi_cleanup() {
    gpiod_chip_release_ownership(mcp308_chans[SPI_CHANNEL]);
    close(spi_fd);
    gpiod_unexport(&mcp308_pins);
}

uint16_t read_mcp3008() {
    uint8_t cmd[2] = {MCP3008_START_CONV, SPI_MODE_0};
    uint8_t data[3];

    if (write(spi_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    if (read(spi_fd, data, sizeof(data)) != sizeof(data)) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return (data[1] << 8) | data[2];
}

void log_reading(uint16_t reading) {
    time_t now;
    char timestamp[20];

    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    log_file = fopen("methane_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "%s, %d ppm\n", timestamp, reading);
    fclose(log_file);
}

int main() {
    spi_init();
    log_file = fopen("methane_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spi_cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t reading = read_mcp3008();
        if (reading < 0) {
            spi_cleanup();
            fclose(log_file);
            return EXIT_FAILURE;
        }

        log_reading(reading);

        if (reading > 1000) {
            fprintf(stderr, "Leak alarm: Methane concentration %d ppm\n", reading);
        }

        usleep(1000000);
    }

    spi_cleanup();
    fclose(log_file);
    return EXIT_SUCCESS;
}

