#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpio.h>

#define TMP36_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL 1
#define VREF 3300 // Vref for MCP3208

int spi_fd;
int gpio_ce0;

void signal_handler(int signum) {
    printf("Signal %d received, cleaning up...\n", signum);
    close(spi_fd);
    gpio_release(gpio_ce0);
    if (log_file != NULL) {
        fclose(log_file);
        remove(LOG_FILE);
    }
    exit(0);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (gcpio_init() < 0) {
        perror("Failed to initialize GPIO");
        close(spi_fd);
        return -1;
    }

    gpio_ce0 = gcpio_request(4, 8);
    if (gpio_ce0 < 0) {
        perror("Failed to request GPIO for CE0");
        close(spi_fd);
        return -1;
    }

    gcpio_set_wd(gpio_ce0, 0);
    gcpio_set_dir(gpio_ce0, GPIO_DIR_OUT);

    return 0;
}

void cleanup_spi() {
    gcpio_free(gpio_ce0);
    gcpio_exit();
    close(spi_fd);
}

int transfer_adc_reading() {
    uint8_t data[2];
    struct spi_ioc_transfer tr;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long) &TMP36_CHANNEL;
    tr.rx_buf = (unsigned long) data;
    tr.len = 1;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return data[0];
}

float adc_to_voltage(int adc_value) {
    return (float) adc_value * VREF / 1024;
}

float voltage_to_celsius(float voltage) {
    return (voltage - 0.5) * 100;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *log_file = NULL;
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (init_spi() < 0) {
        return -1;
    }

    while (1) {
        uint8_t adc_value = transfer_adc_reading();
        if (adc_value < 0) {
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float temperature_celsius = voltage_to_celsius(voltage);

        if (temperature_celsius < -40 || temperature_celsius > 125) {
            fprintf(stderr, "Invalid temperature reading: %f\n", temperature_celsius);
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f\n", now, temperature_celsius);

        fflush(log_file);
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    cleanup_spi();
    fclose(log_file);
    return 0;
}

