#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>
#include <si1172.h>

#define I2C_BUS 1
#define SAMPLE_INTERVAL 1
#define LOG_FILE "biometric_log.csv"

struct sample_t {
    double timestamp;
    uint16_t ir_adc;
    uint16_t red_adc;
    int error_flag;
};

FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpiod_uninit();
    exit(signum == SIGINT);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO library");
        return 1;
    }

    if (si1172_init(I2C_BUS) < 0) {
        perror("Failed to initialize Si1172 sensor");
        return 1;
    }

    fprintf(log_file, "Timestamp,IR_ADC,Red_ADC,Error_Flag\n");

    while (1) {
        struct sample_t sample;
        sample.error_flag = 0;

        int ir_adc_result = si1172_read_ir_adc(&sample.ir_adc);
        int red_adc_result = si1172_read_red_adc(&sample.red_adc);

        if (ir_adc_result < 0 || red_adc_result < 0) {
            sample.error_flag = (ir_adc_result < 0) ? 1 : 2;
        }

        sample.timestamp = time(NULL);

        fprintf(log_file, "%f,%u,%u,%d\n",
                sample.timestamp,
                sample.ir_adc,
                sample.red_adc,
                sample.error_flag);

        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    if (log_file) {
        fclose(log_file);
    }

    gpiod_uninit();
    return 0;
}

