#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <stdint.h>
#include <mcp3008.h>

#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "flow_log.csv"
#define MAX_LINE_LENGTH 100

static int spi_fd;
static CHIP_TYPE chip = MCP3008_CHIP_A;
static uint8_t channel = 0;
static mcp3008_t adc;
FILE *log_file = NULL;

void log_measurement(double flow_rate) {
    static struct timespec last_timestamp;
    struct timespec current_timestamp;
    double seconds;

    if (log_file == NULL)
        return;

    clock_gettime(CLOCK_MONOTONIC, &current_timestamp);
    seconds = (current_timestamp.tv_sec - last_timestamp.tv_sec)
              + (current_timestamp.tv_nsec - last_timestamp.tv_nsec) / 1e9;
    last_timestamp = current_timestamp;

    if (seconds < 1)
        return;

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%06d,%f\n",
            1900 + (current_timestamp.tv_sec / 31536000),
            (current_timestamp.tv_sec / 86400) % 12,
            (current_timestamp.tv_sec / 31557600) % 7,
            current_timestamp.tv_hour,
            current_timestamp.tv_min,
            current_timestamp.tv_sec % 60,
            (current_timestamp.tv_nsec / 1000000000),
            flow_rate);

    fflush(log_file);
}

int main() {
    int ret;
    int sigint_fd = SIGINT;
    int sigterm_fd = SIGTERM;

    // Initialize GPIO for CE0
    gpiod_chip_remove_all();
    gpiod_chip_register_override(0, "SPI0-CE0", "GPIO8_8", "input");
    gpiod_chip_remove_all();

    // Initialize SPI
    spi_fd = open(MCP3008_SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (mcp3008_init(&adc, spi_fd, chip) < 0) {
        perror("Failed to initialize MCP3008");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        mcp3008_terminate(&adc);
        return 1;
    }

    // Register signal handlers
    if (sigint_fd != SIGINT || sigterm_fd != SIGTERM) {
        struct sigaction sa;
        sa.sa_handler = signal_handler;
        sigaction(SIGINT, &sa, NULL);
        sigaction(SIGTERM, &sa, NULL);
    }

    while (1) {
        double adc_value;
        double flow_rate;

        adc_value = mcp3008_read(&adc, channel);

        if (adc_value == MCP3008_ERROR) {
            fprintf(stderr, "Error reading ADC value\n");
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent condition detected\n");
            continue;
        }

        flow_rate = (adc_value / 1023.0) * 5.0; // Assuming linear relationship

        if (flow_rate < 0.0 || flow_rate > 5.0) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
        } else {
            log_measurement(flow_rate);
        }

        sleep(1);
    }

    // Clean up
    fclose(log_file);
    mcp3008_terminate(&adc);
    close(spi_fd);
    return 0;
}

static void signal_handler(int signum) {
    (void)signum;
    fprintf(stderr, "Signal %d received, cleaning up and exiting\n", signum);
    if (log_file != NULL)
        fclose(log_file);
    mcp3008_terminate(&adc);
    close(spi_fd);
    exit(0);
}

