#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define DEVICE_ADDR 0x68 // ICP-10125 I2C address
#define I2C_BUS 1         // I2C bus number
#define SAMPLE_INTERVAL 5 // seconds

// Calibration coefficients
#define T_COEFF 0.01
#define P_COEFF 0.00002

static int i2c_fd = -1;
static FILE *log_file = NULL;

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

int i2c_open() {
    struct i2c_client *client;
    int ret;

    client = i2c_get_client(DEVICE_ADDR, I2C_BUS);
    if (!client) {
        log_error("Failed to get I2C client\n");
        return -1;
    }

    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus\n");
        i2c_put_client(client);
        return -1;
    }

    return 0;
}

void i2c_close() {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
        i2c_fd = -1;
    }
}

int i2c_read_reg(uint8_t reg, uint8_t *data, size_t len) {
    if (i2c_master_write(i2c_fd, DEVICE_ADDR, NULL, 0) < 0) {
        return -1;
    }

    if (i2c_master_read(i2c_fd, DEVICE_ADDR, data, len) < 0) {
        return -1;
    }

    return 0;
}

void i2c_log_error_and_retry(const char *msg) {
    log_error(msg);
    sleep(5);
}

int main() {
    struct timespec ts;
    int ret;
    uint8_t pressure_msb, pressure_lsb, temp_msb, temp_lsb, crc_high, crc_low;
    float pressure, temperature;

    if (i2c_open() < 0) {
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("environmental_data.csv", "w")) == NULL) {
        log_error("Failed to open log file\n");
        i2c_close();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Temperature (°C),Pressure (Pa)\n");

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        temperature = (float)(temp_msb << 8 | temp_lsb) * T_COEFF;
        pressure = (float)(pressure_msb << 8 | pressure_lsb) * P_COEFF;

        printf("Temp: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        fprintf(log_file, "%ld,%.2f,%.2f\n", ts.tv_sec, temperature, pressure);

        sleep(SAMPLE_INTERVAL);
    }

    i2c_close();
    fclose(log_file);

    return EXIT_SUCCESS;
}

