        printf("Temp: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        fprintf(log_file, "%ld,%.2f,%.2f\n", ts.tv_sec, temperature, pressure);

        sleep(SAMPLE_INTERVAL);
    }

    i2c_close();
    fclose(log_file);

    return EXIT_SUCCESS;
}
