#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>

#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60

struct spi_dev spi;
FILE *log_file = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        exit(0);
    }
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    if (gpiod_is_initialized()) {
        gpiod_uninit();
    }

    if (spik_close(&spi) < 0) {
        perror("Error closing SPI device");
    }
}

int init_spi() {
    spi.fd = open(MCP3008_SPI_DEVICE, O_RDWR);
    if (spi.fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    spi.speed_hz = 1000000;
    spi.bits_per_word = 8;
    spi.mode = 0;

    if (ioctl(spi.fd, SPI_IOC_WR_FRAMES, &spi.frames) < 0) {
        perror("Error setting SPI transfer frames");
        return -1;
    }

    if (ioctl(spi.fd, SPI_IOC_RD_FRAMES, &spi.frames) < 0) {
        perror("Error reading SPI transfer frames");
        return -1;
    }

    return 0;
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx_buf[2] = {0x01, channel};
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = tx_buf,
        .rx_buf = rx_buf,
        .len = sizeof(rx_buf),
        .speed_hz = spi.speed_hz,
        .bits_per_word = spi.bits_per_word,
        .delay_usecs = 0,
        .circ_buf_len = 0,
        .bits_per_frame = spi.bits_per_word,
        .pad_zero_bits = 0,
        .pad_zero_bytes = 0,
        .ignorecs_bit = 0,
        .lsb_first = 0,
        .byteorder = SPI_IOC_Little,
    };

    if (ioctl(spi.fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error transferring SPI data");
        return -1;
    }

    return (uint16_t)(rx_buf[1] << 8) | rx_buf[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    if (init_spi()) {
        return -1;
    }

    while (1) {
        uint16_t adc_value = read_adc(0);
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now));

        fprintf(log_file, "%s,%d\n", timestamp, adc_value);

        fflush(log_file);
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

