}

int spi_transfer(uint8_t tx_byte) {
    struct spi_txn txn;
    spi_txn_init(&txn);
    txn.tx_buf = &tx_byte;
    txn.rx_buf = NULL;
    txn.len = 1;
    txn.speed_hz = SPI_SPEED_HZ;
    txn.mode = SPI_MODE;

    int ret = gpiod_spi_transfer(spi_fd, &txn);
    if (ret < 0) {
        perror("SPI transfer failed");
        log_message("SPI transfer failed: %s\n", strerror(errno));
    }

    return ret;
}

int main() {
    int ret;
    struct gpiod_chip chip;
    struct gpiod_line line;

    ret = gpiod_chip_open(&chip, "SPI0");
    if (ret < 0) {
        perror("Failed to open SPI chip");
        return ret;
    }

    ret = gpiod_chip_get_lines(&chip, &line, 1, NULL);
    if (ret < 0) {
        perror("Failed to get SPI lines");
        gpiod_chip_close(&chip);
        return ret;
    }

    spi_fd = gpiod_chip_get_fd(&chip);
    if (spi_fd < 0) {
        perror("Failed to get SPI file descriptor");
        gpiod_chip_put_line(&chip, line.line, 0);
        gpiod_chip_close(&chip);
        return spi_fd;
    }

