            if (spi_ret == 3) {
                raw_adc = (tx_byte[1] << 8) | tx_byte[2];
                break;
            } else if (spi_ret < 3) {
                retries++;
                sleep(1);
            } else {
                log_message("SPI transfer failed after %d retries\n", retries);
                retries = MAX_RETRIES;
            }
