        float compensated_voltage = compensate_voltage(voltage, ambient_temp);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        char message[256];
        snprintf(message, sizeof(message), "%04d-%02d-%02d %02d:%02d:%02d, %d, %.3f, %.3f, %s",
                 tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                 tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                 raw_adc, voltage, compensated_voltage,
                 compensated_voltage > 0.5 ? "flame_detected" : "no_flame_detected");

        log_message("%s\n", message);

        if (compensated_voltage > 0.5) {
            gpiod_chip_open(&chip, "GPIO");
            ret = gpiod_chip_get_lines(&chip, &line, 1, NULL);
            if (ret < 0) {
                perror("Failed to get GPIO lines");
                close(spi_fd);
                gpiod_chip_close(&chip);
                return ret;
            }

            gpiod_chip_put_line(&chip, line.line, 1);
            sleep(SAMPLE_INTERVAL_MS / 1000);

            gpiod_chip_put_line(&chip, line.line, 0);
            sleep(SAMPLE_INTERVAL_MS / 1000);
        } else {
            gpiod_chip_put_line(&chip, line.line, 0);
            sleep(SAMPLE_INTERVAL_MS / 1000);
        }
    }

    gpiod_chip_close(&chip);
    close(spi_fd);
    return 0;
