            gpiod_chip_put_line(&chip, line.line, 1);
            sleep(SAMPLE_INTERVAL_MS / 1000);

            gpiod_chip_put_line(&chip, line.line, 0);
            sleep(SAMPLE_INTERVAL_MS / 1000);
        } else {
            gpiod_chip_put_line(&chip, line.line, 0);
            sleep(SAMPLE_INTERVAL_MS / 1000);
        }
    }

    gpiod_chip_close(&chip);
    close(spi_fd);
    return 0;
}
