        exit(EXIT_FAILURE);
    }

    while (running) {
        char timestamp[32];
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
        timestamp[strcspn(timestamp, "\0")] = '\0';
        timestamp[sizeof(timestamp) - 1] = 'Z'; // ISO 8601

        int adc_value = read_mcp3008(CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        int level_percentage = (adc_value / 1024.0) * 100;

        printf("%s: %d%%\n", timestamp, level_percentage);
        write_json(timestamp, level_percentage);

        if (level_percentage > HIGHER_THRESHOLD) {
            gpiod_line_trigger(led_line, true);
        } else if (level_percentage < LOWER_THRESHOLD) {
            gpiod_line_trigger(led_line, false);
        }

        usleep(SLEEP_INTERVAL);
    }

    cleanup_gpio();
    gpiod_spi_close(spi_fd);
    close(json_file_fd);

    return 0;
}

