#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define MCP3008_CHANNEL 0
#define SAMPLING_INTERVAL 100000 // 100 milliseconds in microseconds
#define CSV_HEADER "timestamp,airflow_lpm\n"

struct spi_dev spi;
FILE *airflow_log;

void sigint_handler(int signum) {
    gpiod_unbind(gpio);
    gpiod_drain(gpio);
    gpiod_uninit();
    exit(0);
}

void init_spi() {
    if (spidev_open(&spi, "/dev/spidev0.0", SPI_MODE0) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(1);
    }
}

void cleanup_spi() {
    spidev_close(&spi);
}

uint16_t read_mcp3008_channel(int channel) {
    uint8_t data[3];
    data[0] = 0x01; // Start bit
    data[1] = (channel << 4) | 0x08; // Channel selection and single-ended bit

    if (spidev_transfer(spi, data, NULL) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        exit(1);
    }

    uint16_t adc_value = (data[2] << 8) | data[1];
    return adc_value;
}

double convert_adc_to_lpm(uint16_t adc_value) {
    // Honeywell AWM7300V calibration factor (from datasheet)
    const double CALIBRATION_FACTOR = 0.0012417;

    return (double)adc_value * CALIBRATION_FACTOR;
}

void log_airflow_reading(double airflow_lpm) {
    char timestamp[24];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    if (airflow_log == NULL) {
        airflow_log = fopen("airflow_log.csv", "w");
        if (airflow_log == NULL) {
            fprintf(stderr, "Failed to open airflow_log.csv for writing\n");
            exit(1);
        }
        fprintf(airflow_log, "%s,%.2f\n", CSV_HEADER);
    }

    fprintf(airflow_log, "%s,%.2f\n", timestamp, airflow_lpm);
    fflush(airflow_log);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpio = gpiod_in_setup(0, 24, true);
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    init_spi();

    if ((airflow_log = fopen("airflow_log.csv", "a")) == NULL) {
        fprintf(stderr, "Failed to open airflow_log.csv for appending\n");
        return 1;
    }

    while (true) {
        uint16_t adc_value = read_mcp3008_channel(MCP3008_CHANNEL);
        double airflow_lpm = convert_adc_to_lpm(adc_value);
        log_airflow_reading(airflow_lpm);

        usleep(SAMPLING_INTERVAL);
    }

    cleanup_spi();
    gpiod_unbind(gpio);
    gpiod_drain(gpio);
    gpiod_uninit();
    fclose(airflow_log);

    return 0;
}

