#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <wiringPiSPI.h>
#include <msp430.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_CALIBRATION 0
#define MAX_CALIBRATION 1023
#define MOISTURE_THRESHOLD 30
#define LOGGING_INTERVAL 60

int spi_fd;
int adc_channel;
uint16_t min_calibration;
uint16_t max_calibration;
uint16_t moisture_threshold;
int logging_interval;
char *email_address;
char *msmtp_config;

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

uint16_t read_adc(int channel) {
    uint8_t data[2];
    int ret = wiringPiSPIDataRGB(spi_fd, &data, 2);
    if (ret < 0) {
        log_error("SPI transfer failed\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

double get_moisture_percentage(uint16_t adc_value) {
    return (adc_value - min_calibration) * 100.0 / (max_calibration - min_calibration);
}

void send_email_alert(const char *moisture_percent) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "echo \"Moisture level is low: %s%%\" | msmtp -t %s", moisture_percent, msmtp_config);
    int status = system(cmd);
    if (WEXITSTATUS(status) != 0) {
        log_error("Failed to send email alert\n");
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    // ...

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_BUS, SPI_CHANNEL);
    if (spi_fd < 0) {
        log_error("Failed to initialize SPI\n");
        return 1;
    }

    // Initialize GPIO
    gpiod_chip_init(0);
    gpiod_chip_handle_create_from_desc(0, "SPI0-CE0", &chip);
    gpiod_chip_get_line(chip, 0, &line);
    gpiod_line_export(line, NULL);
    gpiod_line_set_direction(line, GPIO_DIR_OUT);

    // Set calibration values
    min_calibration = atoi(argv[3]);
    max_calibration = atoi(argv[4]);
    moisture_threshold = atoi(argv[5]);
    logging_interval = atoi(argv[6]);

    // Open log file
    FILE *log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file\n");
        return 1;
    }

    while (1) {
        uint16_t adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            continue;
        }

        double moisture_percent = get_moisture_percentage(adc_value);

        if (moisture_percent < moisture_threshold) {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            fprintf(log_file, "%s, %f\n", timestamp, moisture_percent);

            send_email_alert(sprintf(moisture_percent));
        }

        sleep(logging_interval);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_unref(line);
    gpiod_chip_unref(chip);
    wiringPiSPIClose(spi_fd);

    return 0;
}

