#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpio.h>

#define SPI_DEV "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define MOISTURE_FACTOR 100.0

int spi_fd;

void spi_cleanup() {
    if (spi_fd > 0) {
        close(spi_fd);
    }
}

void sigint_handler(int signum) {
    spi_cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    gpioSetMode(8, GPIO_OUTPUT);
    gpioSetMode(9, GPIO_OUTPUT);
    gpioSetMode(10, GPIO_OUTPUT);
    gpioSetMode(11, GPIO_OUTPUT);
    gpioWrite(8, 0);
    gpioWrite(9, 0);
    gpioWrite(10, 0);
    gpioWrite(11, 0);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART_ENABLE) < 0) {
        perror("Failed to enable SPI writer duart");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct spi_transfer trans;
    trans.bits_per_word = 8;
    trans.delay_usecs = 0;
    trans.speed_hz = 1000000;
    trans.bits_per_frame = 8;
    trans.frame_bits[0] = (MCP3008_CHANNEL << 3) | 0x01; // Single-ended conversion on channel 0

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (read(spi_fd, &trans, sizeof(struct spi_transfer)) != sizeof(struct spi_transfer)) {
            perror("Failed to read from SPI device");
            break;
        }

        if (read(spi_fd, &trans, sizeof(struct spi_transfer)) != (size_t)(2 * sizeof(uint16_t))) {
            perror("Failed to read from SPI device");
            break;
        }

        uint16_t adc_raw = (trans.bits[0] << 8) | trans.bits[1];
        float moisture_percentage = (adc_raw * MOISTURE_FACTOR) / 1023.0;

        printf("Raw ADC reading: %d, Moisture percentage: %.2f%%\n", adc_raw, moisture_percentage);

        usleep(5000000);
    }

    spi_cleanup();
    return EXIT_SUCCESS;
}

