#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_GPIO 8
#define SCLK_GPIO 11
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL 5

int spi_fd;
int ce_gpio;
int sclk_gpio;
int mosi_gpio;
int miso_gpio;

void cleanup() {
    close(spi_fd);
    gpiod_unprepare_irq(ce_gpio);
    gpiod_unprepare_irq(sclk_gpio);
    gpiod_unprepare_irq(mosi_gpio);
    gpiod_unprepare_irq(miso_gpio);
}

int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    if (write(spi_fd, tx_buf, len) != len) {
        perror("SPI write");
        return -1;
    }

    if (read(spi_fd, rx_buf, len) != len) {
        perror("SPI read");
        return -1;
    }

    return 0;
}

uint16_t read_adc() {
    uint8_t tx_buf[2] = {MCP3008_CHANNEL << 4 | 0x01, 0};
    uint8_t rx_buf[3];

    if (spi_transfer(tx_buf, rx_buf, sizeof(tx_buf)) < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    uint16_t adc_value = (rx_buf[1] << 8) | rx_buf[2];

    if (adc_value == 0xFFFF || adc_value == 0) {
        fprintf(stderr, "Sensor or wiring fault detected\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    return adc_value;
}

int main() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI open");
        return EXIT_FAILURE;
    }

    ce_gpio = gpiod_find_line("GPIO" STRINGIFY(CE_GPIO));
    if (!ce_gpio) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    sclk_gpio = gpiod_find_line("GPIO" STRINGIFY(SCLK_GPIO));
    if (!sclk_gpio) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    mosi_gpio = gpiod_find_line("GPIO" STRINGIFY(MOSI_GPIO));
    if (!mosi_gpio) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    miso_gpio = gpiod_find_line("GPIO" STRINGIFY(MISO_GPIO));
    if (!miso_gpio) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_export(ce_gpio, NULL) || gpiod_export(sclk_gpio, NULL) ||
      gpiod_export(mosi_gpio, NULL) || gpiod_export(miso_gpio, NULL)) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpiod_set_value(ce_gpio, 1);
    gpiod_set_value(sclk_gpio, 1);

    struct spi_ioc_transfer spi_transfer_req;
    spi_transfer_req.tx_buf = (unsigned long)tx_buf;
    spi_transfer_req.rx_buf = (unsigned long)rx_buf;
    spi_transfer_req.len = sizeof(tx_buf);
    spi_transfer_req.speed_hz = 1000000;
    spi_transfer_req.bits_per_word = 8;
    spi_transfer_req.delay_usecs = 0;
    spi_transfer_req.bits_per_frame = 8;
    spi_transfer_req.frame_length = sizeof(tx_buf);
    spi_transfer_req.speed_hz = 1000000;
    spi_transfer_req.lane_mask = 0x7;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer_req) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc();
        time_t now = time(NULL);
        printf("Timestamp: %ld, ADC Value: %d\n", now, adc_value);
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

