    struct spi_ioc_transfer spi_transfer_req;
    spi_transfer_req.tx_buf = (unsigned long)tx_buf;
    spi_transfer_req.rx_buf = (unsigned long)rx_buf;
    spi_transfer_req.len = sizeof(tx_buf);
    spi_transfer_req.speed_hz = 1000000;
