    spi_transfer_req.bits_per_frame = 8;
    spi_transfer_req.frame_length = sizeof(tx_buf);
    spi_transfer_req.speed_hz = 1000000;
    spi_transfer_req.lane_mask = 0x7;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer_req) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc();
        time_t now = time(NULL);
        printf("Timestamp: %ld, ADC Value: %d\n", now, adc_value);
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}
