    if (spiBusOpen(&spi, moisture_fd) != 0) {
        perror("Failed to open SPI bus");
        spiBusFree(&spi);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (spiBusConfigure(&spi, SPI_MODE, SPI_BITS_PER_WORD, SPI_FREQ_HZ) != 0) {
        perror("Failed to configure SPI bus");
        spiBusClose(&spi);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_moisture_value(void) {
    uint8_t cmd[3] = {0x01, (MOISTURE_CHANNEL << 3), 0x00};
