    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_init_error_check();

    while (1) {
        uint16_t moisture_value = read_moisture_value();
        float moisture_percent = (float)moisture_value * 100 / 1023;
        moisture_percent = fmin(moisture_percent, 100.0f);
        moisture_percent = fmax(moisture_percent, 0.0f);

        printf("Soil moisture: %.2f%%\n", moisture_percent);

        sleep(LOG_INTERVAL_SEC);
    }

    return 0;
}

