#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define CSV_FILE "environmental_data.csv"
#define SAMPLES_PER_SECOND 1
#define SPI_BAUD_RATE (1000000)
#define MCP3008_CHANNELS 4

struct sensor_data {
    double voltage;
    time_t timestamp;
};

int main() {
    int spi_fd = -1;
    struct sensor_data sensor_data[MCP3008_CHANNELS];
    FILE *csv_file = NULL;
    int ret;

    spi_fd = open(MCP3008_SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART_ENABLE) < 0) {
        fprintf(stderr, "Failed to enable SPI writer duart: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART_DISABLE) < 0) {
        fprintf(stderr, "Failed to disable SPI writer duart: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ftruncate(open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644), 0) < 0) {
        fprintf(stderr, "Failed to truncate CSV file: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file for appending: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_export(NULL) < 0) {
        fprintf(stderr, "Failed to export GPIOs: %s\n", strerror(errno));
        close(spi_fd);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    chip = gpiod_chip_find("gpioexpander");
    if (!chip) {
        fprintf(stderr, "Failed to find gpioexpander chip\n");
        close(spi_fd);
        fclose(csv_file);
        gpiod_unexport(NULL);
        return EXIT_FAILURE;
    }

    struct gpiod_line *ce0 = gpiod_chip_get_line(chip, 8);
    if (!ce0) {
        fprintf(stderr, "Failed to find CE0 line\n");
        gpiod_unexport(NULL);
        close(spi_fd);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    gpiod_line_export(ce0, true);
    if (ce0->active_low) {
        gpiod_line_set_value(ce0, 0);
    }

    while (true) {
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            struct sensor_data *data = &sensor_data[i];

            // Set CE0 low
            gpiod_line_set_value(ce0, 0);
            ret = spi_transfer(spi_fd, &i, 1);
            if (ret < 0) {
                fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
                break;
            }

            // Read MSB and LSB
            ret = spi_transfer(spi_fd, NULL, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
                break;
            }

            data->voltage = ((i << 4) | (ret[0] & 0x0F)) / 1024.0;

            // Set CE0 high
            gpiod_line_set_value(ce0, 1);

            // Write timestamped voltage to CSV
            time_t now = time(NULL);
        fprintf(csv_file, "%ld,%.3f\n", now, data->voltage);
        }

        usleep_range(500000, 600000); // Sleep for 0.5 - 0.6 seconds
    }

    gpiod_line_unref(ce0);
    gpiod_unexport(NULL);
    fclose(csv_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

