void init_gpio() {
    gpio_init();
    gpio_set_direction(17, GPIO_OUTPUT);
    gpio_export(17);
    gpio_set_value(17, 1); // Set initial pump state to off
}

void cleanup_gpio() {
    gpio_unexport(17);
    gpio_uninit();
}

void init_spi() {
    spi_context ctx;
    int fd = spi_open(&ctx, 0);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    spi_set_mode(fd, SPI_MODE0);
    spi_set_bits_per_word(fd, 8);
    spi_set_max_speed(fd, 1000000);
}

