    uint8_t cmd[3] = {0x01, channel, 0x00};
    uint8_t data[3];

    if (spi_transfer(ctx, cmd, data, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        exit(EXIT_FAILURE);
    }

    return (data[1] << 8) | data[0];
}

void log_sample(Sample s) {
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
    }
    memcpy(&buffer[buffer_index], &s, sizeof(Sample));
    buffer_index++;
}

