        if (moisture < LOW_THRESHOLD && !gpio_get_value(17)) {
            gpio_set_value(17, 1);
            s.pump_on = true;
        } else if (moisture > HIGH_THRESHOLD && gpio_get_value(17)) {
            gpio_set_value(17, 0);
            s.pump_on = false;
        }

        log_sample(s);

        printf("Sample: timestamp=%lu, moisture=%d, pump_on=%s\n",
               s.timestamp, s.moisture_level, s.pump_on ? "true" : "false");

        // Print the buffer after each sample
        for (int i = 0; i < BUFFER_SIZE; i++) {
            printf("Buffer[%d]: timestamp=%lu, moisture=%d, pump_on=%s\n",
                   i, buffer[i].timestamp, buffer[i].moisture_level,
                   buffer[i].pump_on ? "true" : "false");
        }
        printf("\n");

        sleep(5);
    }

    cleanup_spi(spi_context);
    cleanup_gpio();
    return 0;
}

