#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/i2c_rdd.h>

#define MAX30102_ADDR 0x5A
#define PART_ID_REG 0x00
#define SP02_REG 0x01
#define HR_REG 0x02
#define LOG_FILE "health_log.txt"

struct i2c_dev i2c;
FILE *log_file;

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", msg);
        fclose(log_file);
    }
}

int init_i2c() {
    int ret;

    ret = i2c_open(&i2c, 1);
    if (ret < 0) {
        log_error("Failed to open I2C bus 1\n");
        return ret;
    }

    ret = i2c_set_slave(&i2c, MAX30102_ADDR);
    if (ret < 0) {
        log_error("Failed to set MAX30102 slave address\n");
        i2c_close(&i2c);
        return ret;
    }

    return 0;
}

uint8_t read_part_id(void) {
    uint8_t part_id;
    int ret;

    ret = i2c_rdwr(&i2c, &part_id, 1, I2C_RD);
    if (ret < 0) {
        log_error("Failed to read Part ID register\n");
        return 0;
    }

    if (part_id != 0x5A) {
        log_error("MAX30102 sensor not detected\n");
        return 0;
    }

    return part_id;
}

void close_i2c(void) {
    i2c_close(&i2c);
}

void init_log_file(void) {
    struct tm tm;
    char timestamp[20];

