#define MCP3008_SPI_DEVICE 0
#define MCP3008_CE0_GPIO 17
#define SPI_MODE 0
#define SPI_CLOCK_HZ (1000000)
#define CHANNELS 3
#define INTERVAL_MS 500

struct spi_dev spi;
struct gpiod_chip chip;
FILE *csv_file = NULL;

void spi_init() {
    spi_open(MCP3008_SPI_DEVICE, SPI_MODE);
    spi_set_mode(SPI_MODE);
    spi_set_clock(SPI_CLOCK_HZ);
    spi_chip_select(MCP3008_CE0_GPIO, 0);
}

uint16_t spi_read(uint8_t channel) {
    uint8_t cmd[2] = {1, channel};
    uint8_t data[3];

    for (int attempt = 0; attempt < 3; attempt++) {
        int ret = spi_transfer(cmd, data);
        if (ret == 3) {
            return (data[1] << 8) | data[2];
        } else if (ret < 0) {
            fprintf(stderr, "SPI error: %s\n", strerror(errno));
            if (attempt < 2) {
                continue;
            } else {
                return -1;
            }
        }
    }
    return -1;
}

void csv_header() {
    if (csv_file != NULL) {
        fprintf(csv_file, "Timestamp,Channel,Voltage\n");
    } else {
        fprintf(stderr, "Error: CSV file is not open.\n");
    }
}

void csv_log(uint32_t timestamp, uint16_t voltage, uint8_t channel) {
    if (csv_file != NULL) {
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%FT%T%z", localtime(&timestamp));
        fprintf(csv_file, "%s,%d,%d\n", time_str, channel, voltage);
    } else {
        fprintf(stderr, "Error: CSV file is not open.\n");
    }
}

int main() {
    spi_init();
    gpiod_chip_init(&chip, MCP3008_CE0_GPIO);
    gpiod_chip_set_owner(&chip, __FILE__, __LINE__, GPIO_DIR_OUT);
    gpiod_chip_set_value(&chip, 0);

    csv_file = fopen("analog_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Error: Unable to open CSV file.\n");
        return 1;
    }
    csv_header();

    while (1) {
        uint32_t timestamp = time(NULL);
        for (uint8_t i = 0; i < CHANNELS; i++) {
            uint16_t voltage = spi_read(i);
            if (voltage != -1) {
                csv_log(timestamp, voltage, i + 1);
            }
        }
        sleep(INTERVAL_MS / 1000);
    }

    fclose(csv_file);
    gpiod_chip_close(&chip);
    spi_close(&spi);

    return 0;
}

