#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpio.h>

#define THRESHOLD 500
#define CHANNEL 0
#define CE_PIN 8
#define BUZZER_PIN 24

gpio_context ctx;
spi_handle spi;

void cleanup(int signum) {
    if (spi) {
        spi_close(&spi);
    }
    gpio_free(&ctx);
    exit(signum);
}

int main() {
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    ctx = gpio_create();
    if (!ctx) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return 1;
    }

    spi = spi_open(&ctx, "SPI0");
    if (!spi) {
        fprintf(stderr, "Failed to open SPI handle\n");
        return 1;
    }

    gpio_set_function(CE_PIN, GPIO_FUNCTION_SPI);
    gpio_set_function(BUZZER_PIN, GPIO_FUNCTION_OUTPUT);
    gpio_set(BUZZER_PIN, 0);

    while (1) {
        int adc_value;
        if (spi_read(spi, &adc_value, sizeof(adc_value), 0x00) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        if (adc_value >= THRESHOLD) {
            gpio_set(BUZZER_PIN, 1);
        } else {
            gpio_set(BUZZER_PIN, 0);
        }

        usleep(500000);
    }

    signal(SIGINT, cleanup);

    return 0;
}

