#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPiI2C.h>
#include <time.h>

#define RELAY_PIN 17
#define REED_PIN 27
#define ADS1115_ADDR 0x48
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_INTERVAL_MS 50
#define SAMPLE_INTERVAL_MS 200
#define THRESHOLD 500 // Adjust this value based on your sensor readings

int i2c_fd = -1;
int relay_state = 0;
int reed_state = 1;
float calibration_values[CALIBRATION_SAMPLES];
unsigned long last_calibration_time = 0;
unsigned long last_sample_time = 0;

void log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    FILE *log_file = fopen("/var/log/door_events.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fclose(log_file);
    }
}

int i2c_read(unsigned char reg, unsigned char *data, int len) {
    if (i2c_fd < 0) {
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        return -1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, len) < 0) {
        return -1;
    }

    if (len != read(i2c_fd, data, len)) {
        return -1;
    }

    return 0;
}

int main() {
    if (wiringPiSetup() != 1) {
        fprintf(stderr, "Failed to initialize wiringPi\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    pinMode(REED_PIN, INPUT);
    pinMode(RELAY_PIN, OUTPUT);

    // Calibration phase
    for (int i = 0; i < CALIBRATION_SAMPLES; ++i) {
        unsigned char buffer[2];
        i2c_read(0, buffer, 2);
        calibration_values[i] = (float)(buffer[1] << 8 | buffer[0]);
        usleep(CALIBRATION_INTERVAL_MS * 1000);
    }

    float avg_calibration_value = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; ++i) {
        avg_calibration_value += calibration_values[i];
    }
    avg_calibration_value /= CALIBRATION_SAMPLES;

    // Main loop
    while (1) {
        unsigned char buffer[2];
        i2c_read(1, buffer, 2);
        int adc_value = (int)(buffer[1] << 8 | buffer[0]);

        if (last_sample_time + SAMPLE_INTERVAL_MS * 1000 < time(NULL)) {
            // Sample taken
            float distance = (float)adc_value * (5.0 / 1023.0);
            if (distance < avg_calibration_value - THRESHOLD) {
                relay_state = 1;
                digitalWrite(RELAY_PIN, HIGH);
                sleep(3);
                digitalWrite(RELAY_PIN, LOW);
                relay_state = 0;

                if (reed_state == 0) {
                    log_event("Door opened");
                } else {
                    log_event("Door not opened");
                }
            }

            last_sample_time = time(NULL);
        }

        if (time(NULL) - last_calibration_time > CALIBRATION_INTERVAL_MS * 1000) {
            // Take another calibration sample
            unsigned char buffer[2];
            i2c_read(0, buffer, 2);
            calibration_values[last_calibration_time % CALIBRATION_SAMPLES] = (float)(buffer[1] << 8 | buffer[0]);
            last_calibration_time++;
        }

        reed_state = digitalRead(REED_PIN);

        if (kill(getppid(), SIGINT) || kill(getppid(), SIGTERM)) {
            break;
        }

        sleep(100);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

