void configure_gpio(int pump_gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(0, "GPIO");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, "GPIO18");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO18 line\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    ret = gpiod_line_export(line, &pump_gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO18\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    gpiod_line_set_direction(line, GPIO_DIR_OUT);
}

int read_moisture() {
    int retries = 3;
    int value;

    while (retry_count < retries) {
        if (mcp3008_read_adc(CHANNEL) == MCP3008_SUCCESS) {
            value = mcp3008_get_adc_result();
            break;
        }
        retry_count++;
        if (retry_count >= retries) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", retries);
            return -1;
        }
        printf("Retrying SPI communication...\n");
        sleep(1);
    }

    return value;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *pump_gpio;
    FILE *log_file = fopen("irrigation.log", "w");
