    int moisture_value;

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        return 1;
    }

    while (1) {
        spi_fd = spi_open(0, O_RDWR);
        if (spi_fd < 0) {
            fprintf(stderr, "Failed to open SPI bus\n");
            break;
        }

        configure_gpio(18);

        moisture_value = read_moisture();
        if (moisture_value < threshold * 1023 / 100) {
            gpiod_trigger(pump_gpio, 1);
            printf("Pump activated\n");
            fprintf(log_file, "%d:%d: Pump activated\n", time(NULL), moisture_value);
            sleep(pump_duration);
            gpiod_trigger(pump_gpio, 0);
            printf("Pump deactivated\n");
            fprintf(log_file, "%d:%d: Pump deactivated\n", time(NULL), moisture_value);
        }

        if (ferror(log_file)) {
            fprintf(stderr, "Error writing to log file\n");
            break;
        }

        spi_close(spi_fd);
        sleep(sleep_interval);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return 0;
}

