#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>
#include <mcp3008.h>

#define MIC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 10
#define PEAK_THRESHOLD 500

static volatile sig_atomic_t running = 1;
static gpio_context *gpio;
static mcp3008_context *mcp;
FILE *log_file;

void signal_handler(int signum) {
    running = 0;
}

void init_gpio() {
    int ret;

    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpio = gpio_context_new();
    ret = gpio_setup(gpio, 8, GPIO_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set up GPIO for CE0\n");
        gpio_free(gpio);
        exit(EXIT_FAILURE);
    }
    ret = gpio_set_value(gpio, 8, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set CE0 high\n");
        gpio_free(gpio);
        exit(EXIT_FAILURE);
    }

    ret = mcp3008_init(SPI0_BUS, SPI0_DEVICE, gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        gpio_free(gpio);
        exit(EXIT_FAILURE);
    }
    mcp = mcp3008_context_new(mcp3008_init_result_t(*mcp));
}

uint16_t read_microphone_value() {
    uint16_t adc_value;
    int ret;

    ret = mcp3008_read(mcp, MIC_CHANNEL, &adc_value);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from MCP3008\n");
        return -1;
    }

    return adc_value;
}

void log_peak(uint16_t value) {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *localtime_result = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime_result);

    if (log_file == NULL) {
        log_file = fopen("/var/log/sound_events.log", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            return;
        }
    }

    if (fprintf(log_file, "%s, %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        fclose(log_file);
        log_file = NULL;
    }

    fclose(log_file);
    log_file = NULL;
}

int main() {
    int ret;
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    init_gpio();
    log_file = fopen("/var/log/sound_events.log", "w");

    while (running) {
        uint16_t adc_value = read_microphone_value();
        if (adc_value != -1) {
            if (adc_value > PEAK_THRESHOLD) {
                log_peak(adc_value);
            }
        }

        gpio_delay_ms(gpio, 8, SAMPLE_INTERVAL_MS);
    }

    gpio_free(gpio);
    mcp3008_free(mcp);
    return 0;
}

