#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define PCF8591_ADDR 0x48
#define AIN0_REG 0x00

int main() {
    int fd;
    char *dev_name = "/dev/i2c-1";
    struct gpiod_chip chip;
    struct gpiod_line line;
    int ret;

    fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus\n");
        close(fd);
        return 1;
    }

    if (gpiod_chip_register_create(&chip, "pcf8591_int", NULL) < 0) {
        fprintf(stderr, "Failed to register GPIO chip\n");
        close(fd);
        return 1;
    }

    line = gpiod_chip_get_line(&chip, "pcf8591_int");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        close(fd);
        gpiod_chip_unregister(&chip);
        return 1;
    }

    if (gpiod_line_export(line, NULL) < 0) {
        fprintf(stderr, "Failed to export GPIO\n");
        close(fd);
        gpiod_chip_unregister(&chip);
        return 1;
    }

    if (gpiod_line_request_add(line, &gpiod_gpio_direction_input) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        close(fd);
        gpiod_chip_unregister(&chip);
        return 1;
    }

    struct i2c_rdwr_ioctl_data rdwr_data;
    rdwr_data.u8 = &AIN0_REG;
    rdwr_data.u8_cnt = 1;
    rdwr_data.u32 = 0;
    rdwr_data.u32_cnt = 1;

    while (1) {
        if (ioctl(fd, I2C_RDWR, &rdwr_data) < 0) {
            fprintf(stderr, "Failed to perform I2C read\n");
            break;
        }

        rdwr_data.u8 = NULL;
        if (ioctl(fd, I2C_RDWR, &rdwr_data) < 0) {
            fprintf(stderr, "Failed to perform I2C read\n");
            break;
        }

        printf("%d\n", rdwr_data.u8[0]);

        usleep(100000);
    }

    if (gpiod_line_unref(line) < 0) {
        fprintf(stderr, "Failed to release GPIO line\n");
    }

    if (gpiod_chip_unregister(&chip) < 0) {
        fprintf(stderr, "Failed to unregister GPIO chip\n");
    }

    close(fd);
    return 0;
}

void sigint_handler(struct gpiod_chip *chip, struct gpiod_line *line, uint32_t flags) {
    gpiod_line_unref(line);
    gpiod_chip_unregister(&chip);
    close(fd);
    exit(0);
}

