#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <ads1x15.h>

#define BUFFER_SIZE 10
#define THRESHOLD 500
#define SAMPLE_RATE 1

typedef struct {
    float buffer[BUFFER_SIZE];
    int index;
} CircularBuffer;

CircularBuffer cb;

void sigint_handler(int signum) {
    gpiod_uninit();
    closelog();
    exit(0);
}

int main(void) {
    syslog_openlog(LOG_LOCAL0, LOG_CONS);

    gpiod_init();
    if (gpiod_export(gpiod_chip_get_first(), "gpio27") < 0) {
        syslog(LOG_ERR, "Failed to export GPIO27");
        return 1;
    }
    gpiod_cmdexe(gpiod_get_chip("gpio27"), "direction=out");

    ads1x15_init(ADS1115_I2C_ADDR_REG0, ADS1X15_REG_CONFIG_SINGLEENDED0, ADS1X15_REG_PGA_6_144, ADS1X15_REG_SAMPRATE_13_75);
    if (ads1x15_read(0, &cb.buffer[cb.index]) < 0) {
        syslog(LOG_ERR, "Failed to read ADC");
    }

    cb.index = (cb.index + 1) % BUFFER_SIZE;

    while (1) {
        sleep(SAMPLE_RATE);

        float voltage = cb.buffer[cb.index] * 3.3 / 65535.0;
        if (voltage < 0 || voltage > 3.3) {
            syslog(LOG_ERR, "Voltage out of range: %f V", voltage);
            continue;
        }

        int gauss = voltage * 125.0; // Assuming linear relationship between 0-3.3V and 0-1500Gauss
        cb.buffer[cb.index] = gauss;

        if (gauss > THRESHOLD) {
            gpiod_cmdexe(gpiod_get_chip("gpio27"), "value=1");
            syslog(LOG_INFO, "Threshold exceeded: %d Gauss", gauss);
        } else {
            gpiod_cmdexe(gpiod_get_chip("gpio27"), "value=0");
            syslog(LOG_INFO, "Within threshold: %d Gauss", gauss);
        }
    }

    gpiod_uninit();
    closelog();
    return 0;
}

signal(SIGINT, sigint_handler);
signal(SIGTERM, sigint_handler);

