#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define VH400_CHANNEL 0
#define PUMP_GPIO 18
#define THRESHOLD 300
#define READ_INTERVAL 60000000 // 60 seconds in nanoseconds
#define PUMP_ON_TIME 10000000 // 10 seconds in nanoseconds

gpio_init();
gpio_set_mode(PUMP_GPIO, GPIO_OUTPUT);

int adc_channel = VH400_CHANNEL;
int adc_spi_mode = 0;
int adc_spi_freq = 1000000; // 1 MHz

void signal_handler(int signum) {
    gpio_uninit(PUMP_GPIO);
    gpio_free();
    exit(signum);
}

uint16_t read_adc(uint8_t channel) {
    uint16_t adc_value = 0;
    struct spi_dev spi;
    spi_init(&spi);
    spi_set_mode(&spi, adc_spi_mode);
    spi_set_speed(&spi, adc_spi_freq);

    if (gpio_get_value(SPI0_CE0) == 0) {
        gpio_set_value(SPI0_CE0, 1);
        spi_transfer(&spi, &channel, &adc_value, 1);
        gpio_set_value(SPI0_CE0, 0);
    } else {
        fprintf(stderr, "SPI CE0 is already active, cannot proceed.\n");
        return -1;
    }

    return adc_value;
}

void water_plant() {
    gpio_set_value(PUMP_GPIO, 1);
    usleep(PUMP_ON_TIME);
    gpio_set_value(PUMP_GPIO, 0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpio_init();
    gpio_set_mode(PUMP_GPIO, GPIO_OUTPUT);
    if (gpio_failed()) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return -1;
    }

    FILE *log_file = fopen("watering_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return -1;
    }

    while (true) {
        uint16_t adc_value = read_adc(adc_channel);
        if (adc_value == -1) {
            continue;
        }

        if (adc_value < THRESHOLD) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Moisture level %d below threshold, activating pump.\n", now, adc_value);
            water_plant();
        }

        fflush(log_file);
        nanosleep(reinterpret_cast<struct timespec*>(&(const struct timespec[]){ {.tv_sec = 0, .tv_nsec = READ_INTERVAL / 1000 } }), NULL);
    }

    fclose(log_file);
    gpio_uninit(PUMP_GPIO);
    gpio_free();
    return 0;
}

