#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define MCP3008_CHANNEL 0
#define VDD 3300 // 3.3V
#define FULL_SCALE 1023

struct spi_dev {
    GPIOD_CHIP chip;
    GPIOD_LINE ce0;
};

static int spi_init(struct spi_dev *dev) {
    int ret;

    ret = gpiod_chip_load_organization(dev->chip.id, "spi0", "ce0");
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize CE0\n");
        return ret;
    }

    ret = gpiod_chip_set_owner(dev->chip.id, __NR_USER, __NAME__);
    if (ret < 0) {
        fprintf(stderr, "Failed to claim CE0\n");
        return ret;
    }

    dev->ce0 = gpiod_chip_get_line(dev->chip.id, "ce0");
    if (!dev->ce0) {
        fprintf(stderr, "Failed to get CE0 line\n");
        return -ENOENT;
    }

    return 0;
}

static void spi_deinit(struct spi_dev *dev) {
    gpiod_chip_release_owner(dev->chip.id);
}

static int spi_transfer(struct spi_dev *dev, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    int ret;

    ret = gpiod_batch_add(&dev->ce0->batch, gpiod_line_set_value, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set CE0 low\n");
        return ret;
    }

    ret = spi_transfer_bytes_ioctl(dev->chip.fd, tx_buf, rx_buf, len);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return ret;
    }

    ret = gpiod_batch_add(&dev->ce0->batch, gpiod_line_set_value, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set CE0 high\n");
        return ret;
    }

    return ret;
}

static uint16_t read_adc(struct spi_dev *dev) {
    uint8_t tx_buf[2] = {0x01, MCP3008_CHANNEL};
    uint8_t rx_buf[3];
    uint16_t adc_value;

    if (spi_transfer(dev, tx_buf, rx_buf, sizeof(tx_buf)) < 0) {
        return 0;
    }

    adc_value = (rx_buf[1] << 8) | rx_buf[2];
    return adc_value;
}

static float map_adc_to_intensity(uint16_t adc_value) {
    return (float)adc_value / FULL_SCALE * (VDD / 2);
}

int main(int argc, char *argv[]) {
    struct spi_dev dev;
    int spi_fd;
    uint16_t adc_value;
    float intensity;
    char timestamp[32];

    if (spi_init(&dev) < 0) {
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        adc_value = read_adc(&dev);
        if (adc_value == 0) {
            continue;
        }

        intensity = map_adc_to_intensity(adc_value);
        printf("%s: ADC=%d, Intensity=%.2f\n", timestamp, adc_value, intensity);

        usleep(1000000);
    }

    spi_deinit(&dev);
    close(spi_fd);
    return 0;
}

