#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define PUMP_GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP "pump_control"

struct spi_data {
    int fd;
    struct gpiod_chip chip;
};

static struct spi_data spi;
static GPIO pinPump = GPIO_UNUSED;
static MQTTClient mqttClient;

static void spi_init(struct spi_data *spi) {
    spi->fd = open(SPI_DEVICE, O_RDWR);
    if (spi->fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return;
    }

    spi->chip.fd = gpioInit();
    if (gpioInit() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        close(spi->fd);
        return;
    }

    if (gpioSetMode(pinPump, GPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d mode", pinPump);
        gpioTerminate();
        close(spi->fd);
        return;
    }

    if (gpioSetOutput(pinPump) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d output", pinPump);
        gpioTerminate();
        close(spi->fd);
        return;
    }
}

static void spi_cleanup(struct spi_data *spi) {
    gpioTerminate();
    close(spi->fd);
}

static int read_adc(struct spi_data *spi, uint8_t *data) {
    struct spi_xfer spi_txfd;
    spi_txfd.tx_buf = (uint8_t[]){0x01};
    spi_txfd.rx_buf = (uint8_t*)data;
    spi_txfd.len = 1;
    spi_txfd.delay_usecs = 0;
    spi_txfd.speed_hz = 1000000;
    spi_txfd.bits_per_word = 10;

    int ret = spiTransfer(spi->fd, &spi_txfd);
    if (ret < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void mqtt_callback(mqtt_message_t *msg) {
    if (strcmp(msg->topic, MQTT_TOPIC_PUMP) == 0) {
        if (strcmp(msg->payload, "pump_on") == 0) {
            gpioWrite(pinPump, 1);
        } else if (strcmp(msg->payload, "pump_off") == 0) {
            gpioWrite(pinPump, 0);
        }
    } else if (strcmp(msg->topic, MQTT_TOPIC_MOISTURE) == 0) {
        float moisture = (float)msg->payload[0] / 100 * 100;
        syslog(LOG_INFO, "Moisture: %f%%", moisture);
    }
}

static void mqtt_init(MQTTClient *client, const char *broker, int port) {
    mqtt_loop_opts_t loop_opts = {0};
    loop_opts.callback = mqtt_callback;

    mqtt_client_init(&mqttClient, broker, port, mqtt_loop_opts_init(&loop_opts));
    if (mqtt_connect(&mqttClient, "client_id", "username", "password") != MQTT_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed");
    }

    mqtt_subscribe(&mqttClient, MQTT_TOPIC_PUMP, 0);
    mqtt_subscribe(&mqttClient, MQTT_TOPIC_MOISTURE, 0);
}

static void mqtt_cleanup(MQTTClient *client) {
    mqtt_disconnect(&mqttClient, 1000);
    mqtt_destroy(&mqttClient);
}

int main() {
    spi_init(&spi);
    pinPump = 17;

    mqtt_init(&mqttClient, MQTT_BROKER, MQTT_PORT);

    while (1) {
        uint8_t adc_data[3];
        int ret = read_adc(&spi, adc_data);
        if (ret < 0) {
            syslog(LOG_ERR, "ADC read failed");
            break;
        }

        float moisture = (float)adc_data[0] / 100 * 100;
        if (moisture < MOISTURE_THRESHOLD_LOW && moisture > 0) {
            gpioWrite(pinPump, 1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
            gpioWrite(pinPump, 0);
        }

        sleep(60);
        mqtt_publish(&mqttClient, MQTT_TOPIC_MOISTURE, (unsigned char*) &moisture, strlen(cast_to_char_p(&moisture)));
    }

    spi_cleanup(&spi);
    mqtt_cleanup(&mqttClient);
    return 0;
}

