        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_dev.mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    if (gpio_export(8, 0) < 0) {
        fprintf(stderr, "Failed to export GPIO8: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    gpio_direction_output(8, 0);

    while (1) {
        uint8_t cmd[3] = {0x01, MCP3008_CHANNEL, 0x00};
