#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define MCP3008_CHAN_0 0
#define MCP3008_CHAN_1 1
#define MCP3008_CHAN_2 2
#define VREF 3.3
#define SPI_DEVICE "/dev/spidev0.0"
#define CSV_FILE "sensor_data.csv"

struct timespec ts;
FILE *csv_file;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Signal %d received, cleaning up...\n", signum);
        close(SPI_DEVICE);
        gpioTerminate();
        exit(0);
    }
}

int spi_init() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioctl_msgs ioctl_msg;
    ioctl_msg.cmd = SPI_IOC_WR_FRAMESIZE;
    ioctl_msg.arg = sizeof(int16_t) * 3;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &ioctl_msg) < 0) {
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int mcp3008_read(int spi_fd, int channel) {
    int16_t data[3];
    struct spi_ioc_transfer spi_transf[] = {
        {
            .tx_buf = (unsigned long) &channel,
            .len = 1,
            .bits_per_word = 8,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .lsb_first = 0,
            .bits = 0,
            .dummy = 0,
            .rx_buf = (unsigned long) data,
            .len = sizeof(int16_t)
        },
        {
            .tx_buf = NULL,
            .len = 0,
            .bits_per_word = 0,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .lsb_first = 0,
            .bits = 0,
            .dummy = 0,
            .rx_buf = (unsigned long) data + 1,
            .len = sizeof(int16_t)
        }
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), spi_transf) < 0) {
        return -1;
    }

    return data[1];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        return -1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        close(spi_fd);
        gpioTerminate();
        return -1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(csv_file, "%ld,%d,%d,%d\n", ts.tv_sec, mcp3008_read(spi_fd, MCP3008_CHAN_0), mcp3008_read(spi_fd, MCP3008_CHAN_1), mcp3008_read(spi_fd, MCP3008_CHAN_2));
        sleep(5);
    }

    fclose(csv_file);
    close(spi_fd);
    gpioTerminate();
    return 0;
}

