#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define NOISE_THRESHOLD 500
#define PWM_FREQ 100
#define SAMPLE_INTERVAL 10000 // 10 ms
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "vibration_log.txt"

struct motor {
    int gpio;
    int state;
};

struct motor motors[2] = {
    {GPIO_CHIRP_1, 0},
    {GPIO_CHIRP_2, 0}
};

int spi_fd;
int spi_resource;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s - %s\n", message, strerror(errno));
}

void init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (gpiod_export(&spi_resource, "spi0") < 0) {
        log_error("Failed to export SPI chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    const struct gpiod_chip_params params = {
        .devm = NULL,
        .label = "spi0",
        .direction = GPIO_DIR_OUT,
    };

    if (gpiod_chip_add_override(&spi_resource, &params) < 0) {
        log_error("Failed to add SPI chip override");
        gpiod_unexport(&spi_resource);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_spi() {
    gpiod_unexport(&spi_resource);
    close(spi_fd);
}

uint16_t read_adc(void) {
    uint8_t tx_buf[2] = {0x01, 0x00};
    uint8_t rx_buf[3];
    int ret;

    ret = write(spi_fd, tx_buf, sizeof(tx_buf));
    if (ret != sizeof(tx_buf)) {
        log_error("Failed to write to SPI device");
        return -1;
    }

    ret = read(spi_fd, rx_buf, sizeof(rx_buf));
    if (ret != sizeof(rx_buf)) {
        log_error("Failed to read from SPI device");
        return -1;
    }

    return (rx_buf[1] << 8) | rx_buf[0];
}

void modulate_motors(uint16_t noise_level) {
    for (int i = 0; i < 2; i++) {
        if (noise_level > NOISE_THRESHOLD) {
            motors[i].state = !motors[i].state;
            if (motors[i].state) {
                gpio_set_value_cansend(motors[i].gpio, 1);
            } else {
                gpio_set_value_cansend(motors[i].gpio, 0);
            }
        } else {
            motors[i].state = 0;
            gpio_set_value_cansend(motors[i].gpio, 0);
        }
    }
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s - %ld\n", ctime(&now), now);
    fclose(log_file);
}

void sigint_handler(int signum) {
    cleanup_spi();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_spi();

    // Initialize GPIOs
    motors[0].gpio = gpiod_export_get_device(spi_resource, "GPIO17");
    motors[1].gpio = gpiod_export_get_device(spi_resource, "GPIO27");

    // Set up PWM
    // (Note: Hardware PWM setup is not covered in this example due to the complexity)

    while (1) {
        uint16_t noise_level = read_adc();
        if (noise_level != -1) {
            modulate_motors(noise_level);
            if (noise_level > NOISE_THRESHOLD * 1.5) {
                log_event("Significant vibration event");
            }
        }

        usleep(SAMPLE_INTERVAL);
    }

    cleanup_spi();
    return 0;
}

