    if (wiringPiI2CSetup(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Initialize MCP3008
    if (mcp_beeker_init(&mcp, i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen("tamper_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open tamper_log.csv\n");
        return 1;
    }

    while (1) {
        data.timestamp = time(NULL);

        // Read sound level
        if (gpiod_trigger_callback(chip_reg.pin, 0, read_mcp3008_callback, &mcp) < 0) {
            data.error_code = -1;
        } else {
            data.sound_level_db = mcp.adc_result;
            data.error_code = 0;
        }

        // Read light level
        if (wiringPiI2CReadRegInt(&i2c_fd, I2C_ADDR_BH1750, 0x02, 2, buffer, 2) != 2) {
            data.error_code = -2;
        } else {
            data.light_level_lux = (buffer[0] << 8) | buffer[1];
            data.error_code = 0;
        }

        // Write to CSV
        if (fprintf(csv_file, "%ld,%d,%d,%d\n", data.timestamp, data.sound_level_db, data.light_level_lux, data.error_code) < 0) {
            fprintf(stderr, "Failed to write to CSV file\n");
            break;
        }

        // Sleep
        usleep(5000000);
    }

    // Clean up
    fclose(csv_file);
    mcp_beeker_deinit(&mcp);
    close(i2c_fd);
    gpiod_chip_close(&reg_handler);

    return 0;
}

static int read_mcp3008_callback(const struct gpiod_chip_reg *reg, uint32_t event, void *user_data) {
    mcp_beeker_read(&mcp, (uint8_t *)user_data);
    return 0;
}
