                int spi_ret = spi_transfer(spi_fd, transfers, 1);
                if (spi_ret == 1) {
                    valid_read = true;
                } else {
                    retries++;
                }
            }

            if (valid_read) {
                float moisture_percent = (moisture_value / 1023.0) * 100;
                printf("Moisture: %.2f%%\n", moisture_percent);

                if (moisture_percent < MOISTURE_THRESHOLD) {
                    gpiod_line_set_value(relay_gpio, 1);
                } else {
                    gpiod_line_set_value(relay_gpio, 0);
                }
            } else {
                fprintf(stderr, "Failed to read moisture after %d retries\n", MAX_RETRIES);
            }

            clock_gettime(CLOCK_MONOTONIC, &next_read);
            next_read.tv_sec += READ_INTERVAL;
        }

        // Handle SIGINT and SIGTERM
        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);
    }

    return 0;
}

