#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpio.h>

#define CHANNEL 0
#define SPI_DEVICE 0
#define SPI_CHANNEL 0
#define FAN_GPIO 18
#define MAX_RETRIES 3
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD 700

float adc_to_voltage(int adc_value) {
    return (float)adc_value / 1024.0 * 3.3;
}

float voltage_to_ppm(float voltage) {
    // This conversion factor is highly dependent on the specific MQ-135 sensor used.
    // Adjust this value according to your sensor's datasheet or calibration.
    return 250.0 * voltage - 1250.0;
}

void log_data(const char *format, ...) {
    time_t now = time(NULL);
    struct tm tm_struct;
    localtime_r(&now, &tm_struct);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_struct);

    va_list args;
    va_start(args, format);
    vsprintf(timestamp + strlen(timestamp), format, args);
    va_end(args);

    FILE *file = fopen("air_quality.log", "a");
    if (file) {
        fprintf(file, "%s, %f, %d\n", timestamp, voltage_to_ppm(adc_to_voltage(1023)), FAN_GPIO);
        fclose(file);
    }
}

void spi_init() {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO library");
        exit(EXIT_FAILURE);
    }

    if (gpio_request_devices(1) < 0) {
        perror("Failed to request SPI devices");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_device_mode(SPI_DEVICE, GP_MODE_SPI_MASTER) < 0) {
        perror("Failed to set SPI device mode");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_spi_mode(SPI_DEVICE, SPI_MODE0) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_spi_frequency(SPI_DEVICE, 1000000) < 0) {
        perror("Failed to set SPI frequency");
        exit(EXIT_FAILURE);
    }
}

int spi_read(uint8_t *data, size_t len) {
    int retries = MAX_RETRIES;
    while (retries--) {
        int rc = gpio_xfer(SPI_DEVICE, SPI_CHANNEL, data, len);
        if (rc >= 0) {
            return rc;
        }
        fprintf(stderr, "SPI communication error, retrying...\n");
    }
    return -1;
}

void spi_cleanup() {
    gpio_free_devices();
}

void fan_control(float co2_ppm) {
    if (co2_ppm > CO2_THRESHOLD) {
        gpio_set_func(FAN_GPIO, GP_PUSHPULL_OUTPUT);
        gpio_set_level(FAN_GPIO, 1);
    } else {
        gpio_set_func(FAN_GPIO, GP_INPUT);
        gpio_set_level(FAN_GPIO, 0);
    }
}

void sigint_handler(int signum) {
    gpio_cleanup();
    exit(0);
}

int main() {
    spi_init();
    gpio_set_func(FAN_GPIO, GP_OUTPUT);
    gpio_set_level(FAN_GPIO, 0);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    uint8_t adc_value;
    while (1) {
        spi_read(&adc_value, 1);
        if (adc_value < 0) {
            fprintf(stderr, "Continuous SPI errors, exiting...\n");
            break;
        }

        float voltage = adc_to_voltage(adc_value);
        float co2_ppm = voltage_to_ppm(voltage);
        log_data("%f, %d", voltage, gpio_get_level(FAN_GPIO));
        fan_control(co2_ppm);

        sleep(5);
    }

    spi_cleanup();
    gpio_cleanup();
    return 0;
}

