        log_file = NULL;
    }
    exit(0);
}

int main() {
    struct gpiod_chipchip *chip;
    struct gpiod_chipline *line;
    struct gpiod_chipline *ce0;
    struct gpiod_chipline *spi_mosi;
    struct gpiod_chipline *spi_miso;
    struct gpiod_chipline *spi_sclk;
    struct gpiod_chipline *relay;
    struct gpiod_chipline *sensor_channel;
    int fd;
    char errbuf[256];

    // Initialize gpiod
    if (gpiod_chip_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_get_error_string());
        return EXIT_FAILURE;
    }

    // Open SPI device
    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Configure SPI
    if (ioctl(fd, SPI_IOC_WR_FRAMESIZE, &BUS_SPEED) < 0) {
        perror("Failed to set SPI bus speed");
        close(fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO pins
    chip = gpiod_chip_find("spi0");
    if (!chip) {
        fprintf(stderr, "Failed to find SPI0 chip\n");
        close(fd);
        return EXIT_FAILURE;
    }

    ce0 = gpiod_chip_get_line(chip, "CE0");
    spi_mosi = gpiod_chip_get_line(chip, "MOSI");
    spi_miso = gpiod_chip_get_line(chip, "MISO");
    spi_sclk = gpiod_chip_get_line(chip, "SCLK");
    relay = gpiod_chip_get_line(chip, "GPIO" GPIOD_EXPORT_PIN(RELAY_PIN));
    sensor_channel = gpiod_chip_get_line(chip, "GPIO" GPIOD_EXPORT_PIN(SENSOR_CHANNEL));

    if (!ce0 || !spi_mosi || !spi_miso || !spi_sclk || !relay || !sensor_channel) {
        fprintf(stderr, "Failed to find required GPIO pins\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set direction for SPI and relay pins
    gpiod_line_export(ce0, "CE0");
    gpiod_line_export(spi_mosi, "MOSI");
    gpiod_line_export(spi_miso, "MISO");
    gpiod_line_export(spi_sclk, "SCLK");
    gpiod_line_export(relay, "GPIO" GPIOD_EXPORT_PIN(RELAY_PIN));
    gpiod_line_export(sensor_channel, "GPIO" GPIOD_EXPORT_PIN(SENSOR_CHANNEL));

    gpiod_line_set_dir(ce0, GPIO_PUD_UP);
    gpiod_line_set_dir(spi_mosi, GPIO_PUD_UP);
    gpiod_line_set_dir(spi_miso, GPIO_PUD_UP);
    gpiod_line_set_dir(spi_sclk, GPIO_PUD_UP);
    gpiod_line_set_dir(relay, GPIO_PUD_UP);
    gpiod_line_set_dir(sensor_channel, GPIO_PUD_UP);

    // Initialize log file
    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    while (true) {
        // Activate sensor
        gpiod_line_set_value(ce0, 1);
        usleep(10); // Short delay to allow sensor to stabilize
        gpiod_line_set_value(ce0, 0);

        // Read ADC value
        uint16_t adc_value = read_adc(fd, SENSOR_CHANNEL);

        // Debounce delay
        if (!relay_active) {
            if (adc_value < DISTANCE_THRESHOLD) {
                log_event("Distance detected below threshold");
                gpiod_line_set_value(relay, 1); // Activate relay
                relay_active = true;
                sleep(DEBOUNCE_DELAY / 1000000); // 1 second delay
            }
        } else {
            // Enforce debounce delay
            sleep(DEBOUNCE_DELAY / 1000000);
            if (adc_value < DISTANCE_THRESHOLD) {
                log_event("Distance still detected below threshold");
                gpiod_line_set_value(relay, 1); // Keep relay active
            } else {
                log_event("Distance returned to normal, deactivating relay");
                gpiod_line_set_value(relay, 0);
                relay_active = false;
            }
        }

        usleep(100000); // Poll every 100 ms
    }

    // Clean up
    gpiod_line_release(ce0);
    gpiod_line_release(spi_mosi);
    gpiod_line_release(spi_miso);
    gpiod_line_release(spi_sclk);
    gpiod_line_release(relay);
    gpiod_line_release(sensor_channel);
    close(fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

uint16_t read_adc(int spi_fd, int channel) {
    uint8_t cmd[2] = {0x01, channel};
    uint8_t data[2];

    if (write(spi_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write to SPI device");
        return -1;
    }

    if (read(spi_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from SPI device");
        return -1;
    }

    return (data[0] << 8) | data[1];
}
