#define SPI_READ_INTERVAL_SEC 5

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "soil_data.txt"

struct spi_data {
    int spi_fd;
    int retries;
};

void spi_init(struct spi_data *data) {
    data->spi_fd = open(SPI_DEVICE, O_RDWR);
    if (data->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialize() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE_FAILURE);
    }

    gpioSetMode(8, PI_OUTPUT); // CE0 (GPIO8)
}

void spi_cleanup(struct spi_data *data) {
    close(data->spi_fd);
    gpioTerminate();
}

int spi_read(struct spi_data *data, uint8_t *result) {
    int retries = 0;
    int ret;

    while (retries < MAX_SPI_RETRIES) {
        ret = ioctl(data->spi_fd, SPI_IOC_MESSAGE(3), result);
        if (ret >= 0) {
            return ret;
        }

        retries++;
        if (retries < MAX_SPI_RETRIES) {
            // Exponential backoff
            usleep(SPI_READ_INTERVAL_SEC * 1e6);
        } else {
            // Skip this sample and record an error
            return -1;
        }
    }

    return -1;
}

float adc_to_moisture(uint16_t adc_value) {
    return (float)adc_value * 56.25 / 1024.0;
}

