    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: ADC value = %d, Moisture (%) = %.2f\n", timestamp, adc_value, adc_to_moisture(adc_value));
        fclose(log_file);
    }
}

void handle_sigint(int signum) {
    spi_cleanup(&spi_data);
    exit(0);
}

