    struct spi_data spi_data;
    uint8_t cmd[3] = {1, 0, MCP3008_CHANNEL};
    uint16_t adc_value;

    spi_init(&spi_data);

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

