#include <gpiod.h>
#include <mcp3008.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define PWM_GPIO 18
#define LDR_GPIO 17
#define MAX_DISTANCE 200
#define MIN_DISTANCE 3
#define MAX_VOLUME 100
#define MIN_VOLUME 0

struct theremin_config {
    int last_valid_distance;
    int last_valid_volume;
};

static struct theremin_config config;
static int spi_fd;
static int mcp_fd;

void load_config() {
    FILE *file = fopen("theremin_config.txt", "r");
    if (file != NULL) {
        fscanf(file, "%d %d", &config.last_valid_distance, &config.last_valid_volume);
        fclose(file);
    }
}

void save_config() {
    FILE *file = fopen("theremin_config.txt", "w");
    if (file != NULL) {
        fprintf(file, "%d %d", config.last_valid_distance, config.last_valid_volume);
        fclose(file);
    }
}

int read_ldr(int *value) {
    int ret;
    *value = mcp_read(mcp_fd, LDR_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Error reading LDR: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int calculate_frequency(int distance) {
    return MAX_DISTANCE - distance;
}

int calculate_volume(int ldr_value) {
    return (ldr_value / 1023.0) * (MAX_VOLUME - MIN_VOLUME) + MIN_VOLUME;
}

void generate_tone(int frequency, int volume) {
    char pwm_path[32];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm%d/enable", PWM_GPIO);
    if (write(open(pwm_path, O_WRONLY), "1", 1) < 0) {
        perror("Failed to enable PWM");
        return;
    }

    pwm_path[0] = '\0';
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm%d/period", PWM_GPIO);
    FILE *period_file = fopen(pwm_path, "w");
    if (period_file == NULL) {
        perror("Failed to open period file");
        return;
    }
    fprintf(period_file, "%d", 1000000); // 1 MHz
    fclose(period_file);

    pwm_path[0] = '\0';
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_GPIO);
    FILE *duty_cycle_file = fopen(pwm_path, "w");
    if (duty_cycle_file == NULL) {
        perror("Failed to open duty cycle file");
        return;
    }
    fprintf(duty_cycle_file, "%d", frequency);
    fclose(duty_cycle_file);

    // Adjust volume by changing duty cycle range
    pwm_path[0] = '\0';
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle_ns", PWM_GPIO);
    duty_cycle_file = fopen(pwm_path, "w");
    if (duty_cycle_file == NULL) {
        perror("Failed to open duty cycle ns file");
        return;
    }
    fprintf(duty_cycle_file, "%d", (frequency * (volume / 100)));
