#define SPI_RETRY_DELAY 1000000 // 1 second in microseconds
#define LOG_FILE "air_quality.log"

struct spi_dev spi;
FILE *log_file = NULL;
bool fan_on = false;

void spi_init() {
    spi.mosi = open("/dev/spidev0.0", O_RDWR);
    spi.miso = open("/dev/spidev0.1", O_RDWR);
    spi.cs = open("/dev/spidev0.2", O_RDWR);
    spi.mode = 0;
    spi.bits_per_word = 16;
    spi.max_speed_hz = 1000000;

    if (spi.cs < 0 || spi.mosi < 0 || spi.miso < 0) {
        perror("Error opening SPI devices");
        exit(EXIT_FAILURE);
    }
}

void spi_cleanup() {
    close(spi.cs);
    close(spi.miso);
    close(spi.mosi);
}

uint16_t read_mcp3008(int channel) {
    uint16_t data = 0;
    int retries = 0;

    while (retries < MAX_SPI_RETRIES) {
        if (gpiod_export(&spi.cs_gpio, gpiod_new()) < 0) {
            perror("Error exporting GPIO for SPI CS");
            return 0;
        }

        gpiod_set_value(&spi.cs_gpio, 0);
        spi_transfer(&spi, &data, sizeof(data));
        gpiod_set_value(&spi.cs_gpio, 1);

        if (data != 0) {
            return data;
        }

        retries++;
        usleep(SPI_RETRY_DELAY);
    }

    spi_cleanup();
    spi_init(); // Re-initialize SPI interface

    return 0;
}

double compute_aqi(uint16_t adc_value) {
    // Implement your AQI computation logic here
    return (double)adc_value / 65535 * 100;
}

void log_air_quality(double aqi) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Error opening log file");
            exit(EXIT_FAILURE);
        }
    }

    time_t now = time(NULL);
    fprintf(log_file, "%ld %f\n", now, aqi);
    fflush(log_file);
}

void toggle_fan(double aqi) {
    if (aqi > 100) {
        if (!fan_on) {
            gpiod_set_value(FAN_GPIO, 1);
            fan_on = true;
        }
    } else {
        if (fan_on) {
            gpiod_set_value(FAN_GPIO, 0);
            fan_on = false;
        }
    }
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    spi_init();

    chip = gpiod_chip_open(FAN_GPIO);
    if (!chip) {
        perror("Error opening GPIO for fan");
        return EXIT_FAILURE;
    }

    gpiod_chip_set_direction(chip, "direction", GPIO_DIR_OUT);

    while (1) {
        uint16_t adc_value = read_mcp3008(MCP3008_CHANNEL);
        double aqi = compute_aqi(adc_value);
        log_air_quality(aqi);
        toggle_fan(aqi);

        sleep(5);
    }

    gpiod_chip_close(chip);
    spi_cleanup();
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    gpiod_unexport(&spi.cs_gpio);
    spi_cleanup();
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main_wrapper() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    return main();
}

int main() { return main_wrapper(); }

