#include <fcntl.h>
#include <errno.h>
#include <gpio.h>

#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_FREQ 8000000
#define MCP3008_SPI_BITS 8
#define MCP3008_CHANNEL 0
#define MCP3008_CE_GPIO 8
#define MAX_RETRIES 3
#define RETRY_DELAY 100000 // 100 ms

int adc_fd = -1;
int ce_gpio = -1;

void sigint_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    gpio_stop();
    close(adc_fd);
    remove("alcohol_log.txt");
    exit(0);
}

uint16_t read_adc(int retries) {
    uint16_t adc_value = 0;
    int ret;

    for (int i = 0; i < retries; ++i) {
        ret = gpio_spi_transfer(adc_fd, NULL, 0, NULL, 1);
        if (ret == 1) {
            adc_value = (gpio_spi_rx_buf[0] << 8) | gpio_spi_rx_buf[1];
            if (adc_value != 0 && adc_value != 1023) {
                return adc_value;
            }
        } else {
            printf("SPI transfer failed, retrying in %d ms...\n", RETRY_DELAY);
            sleep(RETRY_DELAY / 1000);
        }
    }

    printf("Failed to read ADC after %d retries.\n", retries);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    adc_fd = gpio_spi_open(0, 0);
    if (adc_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    ce_gpio = gpio_request(MCP3008_CE_GPIO);
    if (ce_gpio < 0) {
        perror("Failed to request GPIO");
        gpio_spi_close(adc_fd);
        return EXIT_FAILURE;
    }
    gpio_set_func(ce_gpio, GPIO_FUNC_GENERAL);
    gpio_set_level(ce_gpio, 0);

    FILE *log_file = fopen("alcohol_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpio_free(ce_gpio);
        gpio_spi_close(adc_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc(MAX_RETRIES);

        time_t now = time(NULL);
        char timestamp[22];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));

        switch (adc_value) {
            case 0:
                printf("Sensor absent condition detected.\n");
                break;
            case 1023:
                printf("Sensor absent condition detected.\n");
                break;
            default:
                if (adc_value > 50) {
                    printf("Alcohol detected! Limit exceeded.\n");
                } else if (adc_value < 20) {
                    printf("Sobriety confirmed.\n");
                } else {
                    printf("Alcohol level within acceptable range.\n");
                }
                break;
        }

        fprintf(log_file, "%s - %d ppm\n", timestamp, adc_value);
        fflush(log_file);

        sleep(1);
    }

    gpio_free(ce_gpio);
    gpio_spi_close(adc_fd);
    fclose(log_file);
    return EXIT_SUCCESS;
}

