#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <gpio.h>

#define MCP3008_CHANNEL 0
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define LOG_FILE "irrigation.log"

struct timespec start_time;

void signal_handler(int signum) {
    (void)signum;
    gpio_stop();
    fclose(log_file);
    spi_close();
    exit(0);
}

int main() {
    gpio_context gpio;
    spi_context spi;
    FILE *log_file;
    int moisture_value;

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure SPI
    if (spi_open(&spi, "spi0", SPI_MODE0, SPI_BITS_8, 1000000) < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        gpio_exit();
        return 1;
    }

    // Configure PUMP_GPIO as output
    if (gpio_request(&gpio, PUMP_GPIO, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request PUMP_GPIO\n");
        spi_close();
        gpio_exit();
        return 1;
    }
    gpio_set_value(PUMP_GPIO, 1); // Pump OFF by default

    // Open log file
    log_file = fopen("irrigation.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spi_close();
        gpio_exit();
        return 1;
    }

    // Get current time for the first entry
    clock_gettime(CLOCK_REALTIME, &start_time);
    fprintf(log_file, "Timestamp,Moisture,Pump Status\n");

    while (1) {
        // Read moisture value from MCP3008
        if (spi_write_read(&spi, &moisture_value, MCP3008_CHANNEL) < 0) {
            fprintf(stderr, "Failed to read moisture value\n");
            continue;
        }

        // Calculate elapsed time
        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed_seconds = (current_time.tv_sec - start_time.tv_sec) +
            (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        // Activate pump if moisture is below threshold
        if (moisture_value < MOISTURE_THRESHOLD) {
            gpio_set_value(PUMP_GPIO, 1); // Pump ON
        } else {
            gpio_set_value(PUMP_GPIO, 0); // Pump OFF
        }

        // Append data to log file
        fprintf(log_file, "%ld,%d,%d\n",
            (long)elapsed_seconds, moisture_value, gpio_get_value(PUMP_GPIO));

        // Sleep for 60 seconds
        if (elapsed_seconds >= 60) {
            clock_gettime(CLOCK_REALTIME, &start_time);
        }
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    spi_close();
    gpio_exit();
    return 0;
}

