#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <spi.h>
#include <linux/spi/spidev.h>

#define MCP3008_SPI_DEV "/dev/spidev0.0"
#define MOTOR_1_ENABLE_GPIO 18
#define MOTOR_2_ENABLE_GPIO 24
#define MOTOR_1_DIR_GPIO 23
#define MOTOR_2_DIR_GPIO 25
#define POTENTIOMETER_1_GPIO 3
#define POTENTIOMETER_2_GPIO 5

#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define ACCELERATION_TIME 1
#define HOLD_TIME 2
#define DECELERATION_TIME 1
#define PAUSE_TIME 5

struct motor_state {
    int speed;
    int direction;
    bool active;
};

struct motor_state motors[2];

void signal_handler(int signum) {
    printf("Signal %d received, cleaning up resources.\n", signum);
    cleanup();
    exit(signum);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *gpio;
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(ret));
        exit(EXIT_FAILURE);
    }

    motors[0].enable_gpio = gpiod_chip_get_line(chip, MOTOR_1_ENABLE_GPIO);
    motors[0].dir_gpio = gpiod_chip_get_line(chip, MOTOR_1_DIR_GPIO);
    motors[1].enable_gpio = gpiod_chip_get_line(chip, MOTOR_2_ENABLE_GPIO);
    motors[1].dir_gpio = gpiod_chip_get_line(chip, MOTOR_2_DIR_GPIO);

    if (!motors[0].enable_gpio || !motors[0].dir_gpio || !motors[1].enable_gpio || !motors[1].dir_gpio) {
        fprintf(stderr, "Failed to get required GPIO lines.\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(motors[0].enable_gpio, "motor1_enable");
    gpiod_line_export(motors[0].dir_gpio, "motor1_dir");
    gpiod_line_export(motors[1].enable_gpio, "motor2_enable");
    gpiod_line_export(motors[1].dir_gpio, "motor2_dir");

    gpiod_line_direction_set(motors[0].enable_gpio, GPIO_DIR_OUT);
    gpiod_line_direction_set(motors[0].dir_gpio, GPIO_DIR_OUT);
    gpiod_line_direction_set(motors[1].enable_gpio, GPIO_DIR_OUT);
    gpiod_line_direction_set(motors[1].dir_gpio, GPIO_DIR_OUT);

    gpiod_line_set_value(motors[0].enable_gpio, 0);
    gpiod_line_set_value(motors[1].enable_gpio, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
}

void cleanup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *gpio;

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0 for cleanup.\n");
        return;
    }

    gpio = gpiod_chip_get_line(chip, MOTOR_1_ENABLE_GPIO);
    if (gpio) gpiod_line_unset(gpio);
    gpio = gpiod_chip_get_line(chip, MOTOR_1_DIR_GPIO);
    if (gpio) gpiod_line_unset(gpio);
    gpio = gpiod_chip_get_line(chip, MOTOR_2_ENABLE_GPIO);
    if (gpio) gpiod_line_unset(gpio);
    gpio = gpiod_chip_get_line(chip, MOTOR_2_DIR_GPIO);
    if (gpio) gpiod_line_unset(gpio);

    gpiod_chip_close(chip);
}

void setup_spi() {
    int fd;

    fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_FRAMES, 1) < 0) {
        perror("Failed to set SPI frame size");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_RD_FRAMES, &spi_frames) < 0) {
        perror("Failed to read SPI frame size");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &spi_bits_per_word) < 0) {
        perror("Failed to read SPI bits per word");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_speed_hz) < 0) {
        perror("Failed to read SPI speed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &spi_mode) < 0) {
        perror("Failed to read SPI mode");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

uint16_t read_mcp3008(int channel) {
    uint8_t cmd[2] = {0x01, channel};
    uint8_t data[3];
    int fd;
    ssize_t bytes_read;

    fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 0;
    }

    if (write(fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write to SPI device");
        close(fd);
        return 0;
    }

    if ((bytes_read = read(fd, data, 3)) != 3) {
        perror("Failed to read from SPI device");
        close(fd);
        return 0;
    }

    close(fd);

    return (data[1] << 8) | data[2];
}

void map_reading_to_speed(uint16_t reading, struct motor_state *motor) {
    float voltage = (float)reading / 1023.0 * 5.0;
    motor->speed = (int)(voltage * 255);
}

void drive_motor(struct motor_state *motor) {
    if (motor->active) {
        if (motor->speed > 0) {
            motor->speed += ACCELERATION_TIME;
            if (motor->speed > 255) motor->speed = 255;
        } else if (motor->speed < 0) {
            motor->speed -= DECELERATION_TIME;
            if (motor->speed < -255) motor->speed = -255;
        }

        if (motor->direction) {
            gpiod_line_set_value(motor->enable_gpio, 1);
            gpiod_line_set_value(motor->dir_gpio, 1);
        } else {
            gpiod_line_set_value(motor->enable_gpio, 0);
            gpiod_line_set_value(motor->dir_gpio, 0);
        }
    } else {
        gpiod_line_set_value(motor->enable_gpio, 0);
        gpiod_line_set_value(motor->dir_gpio, 0);
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *gpio;
    int fd;
    uint16_t pot1_reading, pot2_reading;
    uint8_t cmd[2];
    uint8_t data[3];
    int ret;

    setup_gpio();
    setup_spi();

    while (true) {
        pot1_reading = read_mcp3008(POTENTIOMETER_1_GPIO);
        pot2_reading = read_mcp3008(POTENTIOMETER_2_GPIO);

        map_reading_to_speed(pot1_reading, &motors[0]);
        map_reading_to_speed(pot2_reading, &motors[1]);

        drive_motor(&motors[0]);
        drive_motor(&motors[1]);

        usleep(SPI_SPEED_HZ * ACCELERATION_TIME);

        // Hold phase
        usleep(SPI_SPEED_HZ * HOLD_TIME);

        usleep(SPI_SPEED_HZ * DECELERATION_TIME);

        usleep(SPI_SPEED_HZ * PAUSE_TIME);

        // Reverse direction
        motors[0].direction = !motors[0].direction;
        motors[1].direction = !motors[1].direction;

        usleep(SPI_SPEED_HZ * ACCELERATION_TIME);
        usleep(SPI_SPEED_HZ * HOLD_TIME);
        usleep(SPI_SPEED_HZ * DECELERATION_TIME);
    }

    cleanup();
    return 0;
}

