#define MCP3008_CHANNEL 0
#define CALIBRATION_DURATION 5000 // milliseconds
#define DEBOUNCE_TIME 10000 // microseconds
#define LED_GPIO 17

static struct gpiod_chip *chip;
static struct gpiod_line *spi_cs;
static struct gpiod_line *spi_mosi;
static struct gpiod_line *spi_miso;
static struct gpiod_line *spi_sclk;
static struct gpiod_line *led;

static uint16_t calibration_baseline = 0;
static uint64_t calibration_start_time = 0;
static bool calibrating = true;

void spi_init() {
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_device spi_dev = {
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .max_speed_hz = 1000000,
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_dev.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        perror("Failed to open gpiod chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    spi_cs = gpiod_chip_get_line(chip, "spi-cs", "output");
    spi_mosi = gpiod_chip_get_line(chip, "spi-mosi", "output");
    spi_miso = gpiod_chip_get_line(chip, "spi-miso", "input");
    spi_sclk = gpiod_chip_get_line(chip, "spi-sclk", "output");
    led = gpiod_chip_get_line(chip, "led", "output");

    if (!spi_cs || !spi_mosi || !spi_miso || !spi_sclk || !led) {
        fprintf(stderr, "Failed to get gpiod lines\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(spi_cs, NULL);
    gpiod_line_export(spi_mosi, NULL);
    gpiod_line_export(spi_miso, NULL);
    gpiod_line_export(spi_sclk, NULL);
    gpiod_line_export(led, NULL);

    gpiod_line_set_value(spi_cs, 1);
    gpiod_line_set_value(spi_mosi, 0);
    gpiod_line_set_value(spi_miso, 0);
    gpiod_line_set_value(spi_sclk, 0);
    gpiod_line_set_value(led, 0);
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx_buf[2] = {0x01, channel};
    uint8_t rx_buf[3];
    int ret = ioctl(spi_fd, SPI_IOC_MSG_SEND, &tx_buf);
    if (ret < 0) {
        perror("SPI write failed");
        return -1;
    }

    ret = read(spi_fd, rx_buf, 3);
    if (ret < 3) {
        perror("SPI read failed");
        return -1;
    }

    return (rx_buf[1] << 8) | rx_buf[2];
}

void calibrate() {
    calibrating = true;
    calibration_start_time = get_current_time();

    while (calibrating && get_current_time() - calibration_start_time < CALIBRATION_DURATION) {
        uint16_t sample = read_adc(MCP3008_CHANNEL);
        if (sample > calibration_baseline) {
            calibration_baseline = sample;
        }
        usleep(1000000); // Sleep for 1 second
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);

    spi_init();
    calibrate();

    while (1) {
        if (calibrating) {
            calibrate();
            calibrating = false;
        }

        uint16_t sample = read_adc(MCP3008_CHANNEL);
        if (sample > calibration_baseline) {
            gpiod_line_set_value(led, 1);
            gpiod_line_set_value(led, 0); // Debounce
            usleep(DEBOUNCE_TIME);
        } else {
            gpiod_line_set_value(led, 0);
        }

        usleep(10000); // Sample every 10 ms
    }

    cleanup();
    return 0;
}

void cleanup() {
    gpiod_line_unset_value(led, 0);
    gpiod_line_unset_value(spi_cs, 1);
    gpiod_line_unset_value(spi_mosi, 0);
    gpiod_line_unset_value(spi_miso, 0);
    gpiod_line_unset_value(spi_sclk, 0);

    gpiod_chip_close(chip);
    close(spi_fd);
}

