#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <mcp3008.h>

#define CALIBRATION_FACTOR 0.0000000048
#define SPI_CHANNEL 0
#define CHIP_SELECT 0
#define SAMPLE_INTERVAL_MS 100

static struct mcp3008 *mcp;
static FILE *log_file;

static int init_spi(void) {
    int ret;
    ret = mcp3008_init(SPI_CHANNEL, CHIP_SELECT);
    if (ret < 0) {
        fprintf(stderr, "ERROR: Failed to initialize SPI\n");
        return ret;
    }
    return 0;
}

static void cleanup_spi(void) {
    mcp3008_deinit();
}

static int open_log_file(void) {
    log_file = fopen("airflow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        return -1;
    }
    return 0;
}

static void close_log_file(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int sample_and_log(void) {
    int16_t adc_value;
    double voltage;
    time_t now;
    struct tm *time_struct;

    if (mcp3008_read(&mcp->fd, &adc_value) < 0) {
        fprintf(stderr, "ERROR: ADC read failed\n");
        return -1;
    }

    voltage = (double)adc_value * 3.3 / 1023.0;
    time(&now);
    time_struct = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %f\n",
            1900 + time_struct->tm_year / 100,
            1 + time_struct->tm_mon,
            time_struct->tm_mday,
            time_struct->tm_hour,
            time_struct->tm_min,
            time_struct->tm_sec,
            voltage * CALIBRATION_FACTOR);

    return 0;
}

static void sigint_handler(int signum) {
    cleanup_spi();
    close_log_file();
    exit(0);
}

int main(void) {
    int ret;

    signal(SIGINT, sigint_handler);

    if (init_spi() < 0) {
        return 1;
    }

    if (open_log_file() < 0) {
        cleanup_spi();
        return 1;
    }

    while (1) {
        if (sample_and_log() < 0) {
            cleanup_spi();
            close_log_file();
            return 1;
        }
        gpiod_timer_start(&timer, SAMPLE_INTERVAL_MS * 1000);
        gpiod_timer_wait(&timer);
    }

    cleanup_spi();
    close_log_file();
    return 0;
}

