#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>

#define MCP3008_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CE0 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define SAMPLE_RATE 1000
#define SAMPLE_INTERVAL (1000000 / SAMPLE_RATE)
#define LOG_FILE "audio_log.txt"

int spi_fd;
int gpio_ce0;

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_RCSWMODE, 0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    gpio_ce0 = gpiod_open_from_fd(open("/dev/gpiomem", O_RDWR), 0);
    if (!gpio_ce0) {
        perror("Failed to open GPIO memory");
        exit(EXIT_FAILURE);
    }

    gpiod_chip_config ce0_cfg = {
        .pin_count = 1,
        .pins = {
            [0] = { .line = GPIO_CE0, .direction = GPIO_DIR_OUT, },
        },
    };

    if (gpiod_chip_add(gpio_ce0, &ce0_cfg, NULL) < 0) {
        perror("Failed to add GPIO chip");
        gpiod_close(gpio_ce0);
        exit(EXIT_FAILURE);
    }
}

uint16_t spi_transfer(uint8_t cmd, uint8_t *data, size_t len) {
    struct spi_transfer t = {
        .tx_buf = data,
        .tx_buf_len = len,
        .bits_per_word = 8,
        .speed_hz = 1000000,
    };

    if (write(spi_fd, &t, sizeof(struct spi_transfer)) != sizeof(struct spi_transfer)) {
        perror("Failed to perform SPI transfer");
        return 0;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    struct timespec ts;
    int log_fd;
    char line[32];

    spi_init();
    gpio_init();

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        gpiod_close(gpio_ce0);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        uint16_t adc_value = spi_transfer(MCP3008_CHANNEL, &ts, sizeof(ts));

        snprintf(line, sizeof(line), "%ld|%d\n", (long)ts.tv_sec * 1000000 + ts.tv_nsec, adc_value);

        if (write(log_fd, line, strlen(line)) != strlen(line)) {
            perror("Failed to write to log file");
            break;
        }

        usleep(SAMPLE_INTERVAL);
    }

    gpiod_close(gpio_ce0);
    close(spi_fd);
    close(log_fd);

    return 0;
}

