#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.int.h>
#include <libgpio.h>

#define MCP3008_SPI_CLOCK_DIV 8
#define DELAY_MS 100000
#define RETRY_DELAY_MS 100000
#define SPI_BUS 0
#define CE0_PIN 7
#define CHANNEL 0

gpio_context *gpio;
int spi_fd;

void sigint_handler(int signum) {
    printf("Ctrl+C detected, cleaning up...\n");
    gpiod_unstack(gpio);
    close(spi_fd);
    printf("SPI interface and driver library terminated gracefully.\n");
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpio = gpiod_new();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    spi_fd = spi_open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_free(gpio);
        return 1;
    }

    gpiod_export(gpio, CE0_PIN, GPIOF_INOUT);
    gpiod_set_value(CE0_PIN, 0);

    while (1) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        int voltage;
        if (mcp3008_read_voltage(spi_fd, CHANNEL, &voltage) != 0) {
            printf("ADC read failed, retrying...\n");
            sleep(RETRY_DELAY_MS / 1000);
            continue;
        }

        printf("%s: Voltage = %.2f V, PPM = PlaceholderPPM\n", timestamp, voltage);

        FILE *log_file = fopen("gas_log.txt", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            break;
        }
        fprintf(log_file, "%s, %.2f, PlaceholderPPM\n", timestamp, voltage);
        fclose(log_file);

