#define SPI_MODE 0
#define CHANNEL_COUNT 3
#define SAMPLES_PER_SECOND 10
#define SPI_BAUDRATE 1000000
#define KALMAN_ALPHA 0.5
#define KALMAN_BETA  0.001

// Kalman filter state variables
float x, p, k;

// SPI device and GPIO definitions
#define SPI_DEVICE "/dev/spidev0.0"
#define CHIP_SELECT_GPIO 8
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define SCLK_GPIO 11

// ADXL335 sensitivity in mV/g
#define ADXL335_SENSITIVITY 163.84

// Conversion factor from 10-bit ADC value to volts
#define ADC_VOLTS_PER_UNIT (3.3 / 1024)

// Conversion factor from volts to g
#define VOLTS_PER_G (ADXL335_SENSITIVITY / 3.3)

// Kalman filter constants
#define KALMAN_Q_NOISE 0.001

void kalman_filter_init() {
    x = 0;
    p = 1;
    k = (KALMAN_ALPHA / (KALMAN_BETA + 1)) * p;
}

void kalman_filter_predict(float measurement) {
    float l;
    l = x + KALMAN_BETA * (measurement - x);
    p *= (1 - KALMAN_ALPHA);
    p += KALMAN_Q_NOISE;
    x = l;
}

void kalman_filter_update(float measurement) {
    float y, l, k_temp;
    y = measurement - x;
    k_temp = k * p;
    l = x + k_temp;
    k = k_temp / (1 + p);
    x = l;
    p *= (1 - k);
}

float read_adc(int channel) {
    int fd;
    int value;
    char buffer[12];

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (gpiod_export(gpiochip, "cs") < 0 ||
        gpiod_cmdexe(gpiochip->cs, "direction", "out") < 0 ||
        gpiod_cmdexe(gpiochip->cs, "value", "0") < 0) {
        perror("Failed to configure chip select GPIO");
        close(fd);
        return -1;
    }

    if (gpiod_cmdexe(gpiochip->mosi, "direction", "out") < 0 ||
        gpiod_cmdexe(gpiochip->miso, "direction", "in") < 0 ||
        gpiod_cmdexe(gpiochip->sclk, "direction", "out") < 0) {
        perror("Failed to configure SPI lines");
        close(fd);
        return -1;
    }

    spi_transfer(fd, &channel, sizeof(channel), buffer, sizeof(buffer));

    value = (buffer[0] << 8) | buffer[1];

    close(fd);

    return value;
}

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    kalman_filter_cleanup();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("\nReceived SIGTERM, cleaning up...\n");
    kalman_filter_cleanup();
    exit(0);
}

void kalman_filter_cleanup() {
    // Cleanup code for Kalman filter state variables
    // (if any necessary)
}

