        float x_raw, y_raw, z_raw;
        float x_filtered, y_filtered, z_filtered;

        x_raw = (read_adc(0) - 512) * ADC_VOLTS_PER_UNIT * VOLTS_PER_G;
        y_raw = (read_adc(1) - 512) * ADC_VOLTS_PER_UNIT * VOLTS_PER_G;
        z_raw = (read_adc(2) - 512) * ADC_VOLTS_PER_UNIT * VOLTS_PER_G;

        kalman_filter_predict(x_raw);
        kalman_filter_update(x_raw);
        x_filtered = x;

        kalman_filter_predict(y_raw);
        kalman_filter_update(y_raw);
        y_filtered = x;

        kalman_filter_predict(z_raw);
        kalman_filter_update(z_raw);
        z_filtered = x;

        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        usleep(1000000 / SAMPLES_PER_SECOND);
    }

    kalman_filter_cleanup();
    gpiod_chip_close(gpiochip);

    return EXIT_SUCCESS;
}

