#define SENSOR_PINS  {4, 17, 27}
#define MAGNETIC_FIELD_SCALE 100.0
#define LOG_FILE "magnetic_log.txt"

float get_magnetic_field(bool state) {
    return state ? MAGNETIC_FIELD_SCALE : -MAGNETIC_FIELD_SCALE;
}

void log_magnetic_fields(float s1, float s2, float s3) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Unable to open log file.\n");
        return;
    }

    if (s1 > 100 || s1 < -100 || s2 > 100 || s2 < -100 || s3 > 100 || s3 < -100) {
        fprintf(stderr, "Warning: Magnetic field value out of range.\n");
        fclose(log_file);
        return;
    }

    fprintf(log_file, "%.2f,%.2f,%.2f\n", s1, s2, s3);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    struct gpiod_chipchip *chip;
    struct gpiod_chip_line *lines[3];
    int r;

    // Initialize libgpiod
    r = gpiod_chip_open(&chip, "GPIO");
    if (r < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO access.\n");
        return r;
    }

    // Setup signal handler for graceful shutdown
    if (signal(SIGINT, [](int) {
        gpiod_chip_close(chip);
        exit(0);
    }) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to install SIGINT handler.\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO pins
    for (size_t i = 0; i < ARRAY_SIZE(SENSOR_PINS); ++i) {
        char pin_path[10];
        snprintf(pin_path, sizeof(pin_path), "GPIO%d", SENSOR_PINS[i]);
        lines[i] = gpiod_chip_line_get(chip, pin_path);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get line for GPIO %d.\n", SENSOR_PINS[i]);
            gpiod_chip_close(chip);
            return 1;
        }

        r = gpiod_chip_line_setup(lines[i], "out");
        if (r < 0) {
            fprintf(stderr, "Error: Failed to configure GPIO %d as output.\n", SENSOR_PINS[i]);
            gpiod_chip_line_free(lines[i]);
            gpiod_chip_close(chip);
            return r;
        }
    }

    while (true) {
        bool states[3] = {false, false, false};

        for (size_t i = 0; i < ARRAY_SIZE(SENSOR_PINS); ++i) {
            r = gpiod_chip_line_read(lines[i], &states[i]);
            if (r < 0) {
                fprintf(stderr, "Error: Failed to read GPIO %d.\n", SENSOR_PINS[i]);
                gpiod_chip_line_free(lines[i]);
                gpiod_chip_close(chip);
                return r;
            }
        }

        float fields[3] = {get_magnetic_field(states[0]), get_magnetic_field(states[1]), get_magnetic_field(states[2])};
        log_magnetic_fields(fields[0], fields[1], fields[2]);

        sleep(0.1);
    }

    // Clean up
    for (size_t i = 0; i < ARRAY_SIZE(SENSOR_PINS); ++i) {
        gpiod_chip_line_free(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

