            (rawtime / (60 * 60)) % 28, (rawtime / 60) % 60, rawtime % 60,
            (rawtime / 1) % 60, (rawtime / 1) % 60);
    fprintf(stderr, "[%s] ", asctime(now));
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");
    va_end(args);
}

void sigint_handler(int signum) {
    log("Received SIGINT, turning off pump and exiting...\n");
    gpio_put(PUMP_GPIO, 0);
    pump_on = false;
    exit(0);
}

void sigterm_handler(int signum) {
    log("Received SIGTERM, turning off pump and exiting...\n");
    gpio_put(PUMP_GPIO, 0);
    pump_on = false;
    exit(0);
}

int main() {
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Initialize GPIO
    if (gpio_init() < 0) {
        log("Failed to initialize GPIO, exiting...\n");
        return EXIT_FAILURE;
    }
    gpio_set_mode(PUMP_GPIO, GPIO_OUTPUT);
    gpio_put(PUMP_GPIO, 0); // Ensure pump is off initially

    // Initialize SPI
    if (gpio_spi_init(0, 50000000, 0) < 0) {
        log("Failed to initialize SPI, exiting...\n");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log("Failed to open log file, exiting...\n");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (true) {
        current_time.tv_sec = start_time.tv_sec + 60;
        if (current_time.tv_sec < start_time.tv_sec) {
            current_time.tv_sec += 24 * 60 * 60; // Wrap around to next day
        }
        current_time.tv_nsec = 0;

        int moisture_value = read_moisture_sensor(MOISTURE_CHANNEL);
        if (moisture_value < 0) {
            log("Failed to read moisture sensor, skipping...\n");
            continue;
        }

        double moisture_level = (double)moisture_value / 1023 * 100;
        log("Moisture level: %.2f%%\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD && !pump_on) {
            log("Moisture level below threshold, turning on pump...\n");
            gpio_put(PUMP_GPIO, 1);
            pump_on = true;
        } else if (moisture_level >= MOISTURE_THRESHOLD && pump_on) {
            log("Moisture level above threshold, turning off pump...\n");
            gpio_put(PUMP_GPIO, 0);
            pump_on = false;
        }

        // Write to log file
        fprintf(log_file, "Moisture level: %.2f%%, Pump state: %s\n", moisture_level,
            pump_on ? "ON" : "OFF");
        fflour(log_file);

        // Sleep for 60 seconds
        clock_nanosleep(CLOCK_MONOTONIC, 0, &current_time - get_monotonic_time(), NULL);
    }

    // Clean up
    fclose(log_file);
    gpio_cleanup();
    return EXIT_SUCCESS;
}

int read_moisture_sensor(int channel) {
    uint16_t adc_value;
    if (gpio_spi_transfer(0, &channel, 1, &adc_value, 1) != 1) {
        log("SPI transfer failed, returning error code...\n");
        return -1;
    }
    return adc_value;
}
```

This code initializes the GPIO and SPI, sets up signal handlers for SIGINT and SIGTERM, and continuously reads the soil moisture sensor every 60 seconds. It drives a pump relay connected to GPIO17 based on the moisture level, logging all events to "watering.log". The code handles errors and ensures a clean shutdown by releasing resources on all exit paths.

