struct spi_data {
    int fd;
    int cs0_gpio;
};

void sigint_handler(int signum) {
    printf("Ctrl+C detected, cleaning up...\n");
    spi_cleanup(spi_data);
    exit(0);
}

int spi_init(struct spi_data *spi_data) {
    spi_data->fd = spi_open(SPI_DEVICE, SPI_MODE);
    if (spi_data->fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    spi_data->cs0_gpio = gpio_request(3); // CE0 is GPIO 3
    if (gpio_set_func(spi_data->cs0_gpio, GPIO_FUNC_GPIO) < 0) {
        perror("Failed to set GPIO function");
        return -1;
    }
    gpio_direction_output(spi_data->cs0_gpio);
    gpio_set_value(spi_data->cs0_gpio, 1);

    return 0;
}

void spi_cleanup(struct spi_data *spi_data) {
    gpio_set_value(spi_data->cs0_gpio, 0);
    gpio_free(spi_data->cs0_gpio);
    spi_close(spi_data->fd);
}

int mcp3008_read(struct spi_data *spi_data, int channel) {
    uint8_t cmd[2] = {0x01, channel};

    if (spi_xfer(spi_data->fd, cmd, NULL, 2) != 2) {
        perror("SPI transfer failed");
        return -1;
    }

    uint8_t data[2];
    if (spi_xfer(spi_data->fd, NULL, data, 2) != 2) {
        perror("SPI transfer failed");
        return -1;
    }

    return (data[1] << 8) | data[0];
}

int main() {
    struct spi_data spi_data;
    signal(SIGINT, sigint_handler);

    if (spi_init(&spi_data) < 0) {
        return -1;
    }

    FILE *fp = fopen(CSV_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s for writing: %s\n", CSV_FILE, strerror(errno));
        spi_cleanup(&spi_data);
        return -1;
    }

    fprintf(fp, "Time,Channel0,Channel1,Channel2\n");

    while (1) {
        uint32_t values[CHANNELS];
        for (int i = 0; i < CHANNELS; i++) {
            values[i] = mcp3008_read(&spi_data, i);
        }

        fprintf(fp, "%lu,%lu,%lu,%lu\n", (unsigned long)time(NULL), values[0], values[1], values[2]);

        usleep(DELAY_BETWEEN_READINGS * 1000000);
    }

    fclose(fp);
    spi_cleanup(&spi_data);

    return 0;
}

