#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60000000 // 60 seconds

mqtt_context_t *mqtt_ctx = NULL;
int reconnect_delay = 1000000; // 1 second

void sigint_handler(int signum) {
    mqtt_disconnect(mqtt_ctx);
    gpio_unclaim(LED_GPIO);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void start_mqtt_loop(void) {
    mqtt_loop_start(mqtt_ctx);
}

void stop_mqtt_loop(void) {
    mqtt_loop_stop(mqtt_ctx);
}

void mqtt_callback(mqtt_context_t *mqtt_ctx, mqtt_event_t event, void *context) {
    switch (event) {
        case MQTT_EVENT_CONNECTED:
            printf("MQTT Connected\n");
            break;
        case MQTT_EVENT_DISCONNECTED:
            printf("MQTT Disconnected\n");
            reconnect();
            break;
        case MQTT_EVENT_SUBACK:
            printf("MQTT Suback\n");
            break;
        case MQTT_EVENT_UNSUBACK:
            printf("MQTT Unsuback\n");
            break;
        case MQTT_EVENT_PUBLISHED:
            if (mqtt_message_topic(mqtt_ctx, mqtt_message_get(mqtt_ctx))) {
                if (strcmp(mqtt_message_topic(mqtt_ctx, mqtt_message_get(mqtt_ctx)), "home/led_control") == 0) {
                    parse_json(mqtt_message_payload(mqtt_ctx, mqtt_message_get(mqtt_ctx)));
                }
            }
            break;
        default:
            break;
    }
}

void reconnect(void) {
    sleep(reconnect_delay / 1000);
    reconnect_delay = reconnect_delay * 2;
    if (reconnect_delay > MAX_RECONNECT_DELAY) {
        reconnect_delay = MAX_RECONNECT_DELAY;
    }
    mqtt_reconnect(mqtt_ctx);
}

void parse_json(const char *json_payload) {
    char *key, *value;
    long retn;

    if (json_parse(json_payload, &key, &value) != JSON_OK) {
        fprintf(stderr, "Error: Invalid JSON format\n");
        return;
    }

    if (strcmp(key, "led_state") != 0) {
        fprintf(stderr, "Error: Invalid key in JSON payload\n");
        return;
    }

    if (value[0] != 't' || value[1] != 'r' || value[2] != 'u' || value[3] != 'e') {
        fprintf(stderr, "Error: led_state value is not a boolean\n");
        return;
    }

    int led_state = (value[4] == '1');

    if (led_state) {
        gpio_set(LED_GPIO);
    } else {
        gpio_clear(LED_GPIO);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    mqtt_ctx = mqtt_context_init();
    if (!mqtt_ctx) {
        fprintf(stderr, "Error: Failed to initialize MQTT context\n");
        return EXIT_FAILURE;
    }

    mqtt_context_set_host(mqtt_ctx, "mqtt.eclipseprojects.io");
    mqtt_context_set_port(mqtt_ctx, 1883);
    mqtt_context_set_client_id(mqtt_ctx, "rpi_led_control");
    mqtt_context_set_keepalive(mqtt_ctx, 60);
    mqtt_context_set_clean_session(mqtt_ctx, 1);
    mqtt_context_set_qos(mqtt_ctx, 0);
    mqtt_context_set_callback(mqtt_ctx, mqtt_callback);

    if (mqtt_context_loop(mqtt_ctx, 0) < 0) {
        fprintf(stderr, "Error: MQTT loop failed\n");
        return EXIT_FAILURE;
    }

    gpio_init();
    gpio_claim(LED_GPIO);
    gpio_set_direction(LED_GPIO, GPIO_OUTPUT);
    gpio_set(LED_GPIO); // Turn off LED at startup

    start_mqtt_loop();

    // Wait for SIGINT or SIGTERM
    while (1);

    stop_mqtt_loop();
    gpio_unclaim(LED_GPIO);
    mqtt_disconnect(mqtt_ctx);
    mqtt_context_deinit(mqtt_ctx);

    return EXIT_SUCCESS;
}

