#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DO_PIN 17
#define LED_PIN 18
#define THRESHOLD 100 // ms

void sigint_handler(int signum) {
    gpiod_unrequest_all();
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *do_line;
    struct gpiod_line *led_line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    do_line = gpiod_chip_get_line(chip, "17");
    if (!do_line) {
        fprintf(stderr, "Failed to get DO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, "18");
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_direction(do_line, GPIO_DIR_IN) < 0) {
        fprintf(stderr, "Failed to set DO line direction\n");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_direction(led_line, GPIO_DIR_OUT) < 0) {
        fprintf(stderr, "Failed to set LED line direction\n");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_export(do_line) < 0) {
        fprintf(stderr, "Failed to export DO line\n");
        gpiod_line_unrequest(do_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_export(led_line) < 0) {
        fprintf(stderr, "Failed to export LED line\n");
        gpiod_line_unrequest(do_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        ret = gpiod_line_read(do_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read DO line\n");
            break;
        }

        if (ret == 0) {
            printf("Sound event detected\n");
            gpiod_line_write(led_line, 1);
            sleep(1);
            gpiod_line_write(led_line, 0);
        }

        usleep(THRESHOLD);
    }

    gpiod_line_release(do_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

