#define GPIO_PIN 17
#define CHIP_LABEL "vibration-monitor"
#define SIG_ATOMIC_FLAG_NAME sig_atomic_t cleanup_flag

volatile sig_atomic_t cleanup_flag = 0;

static int log_file_fd = -1;
static int gpio_chip_fd = -1;
static int gpio_line_fd = -1;

void sigint_handler(int signum) {
    cleanup_flag = 1;
}

void sigterm_handler(int signum) {
    cleanup_flag = 1;
}

void init_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

int open_gpio_chip() {
    gpio_chip_fd = gpiod_open_chip(NULL, CHIP_LABEL);
    if (gpio_chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    return 0;
}

int get_gpio_line(int *line_fd) {
    *line_fd = gpiod_chip_get_line(gpio_chip_fd, CHIP_LABEL);
    if (*line_fd < 0) {
        perror("Failed to get GPIO line");
        return -1;
    }
    return 0;
}

int request_events(int line_fd) {
    int ret = gpiod_line_request_events(line_fd, GPIO_FALLING_EDGE);
    if (ret < 0) {
        perror("Failed to request events");
        return -1;
    }
    return 0;
}

int wait_for_event(int line_fd) {
    int ret = gpiod_line_event_read(line_fd);
    if (ret < 0) {
        perror("Failed to read event");
        return -1;
    }
    return 0;
}

int read_event(int line_fd, int *value) {
    int ret = gpiod_line_get_value(line_fd, value);
    if (ret < 0) {
        perror("Failed to read value");
        return -1;
    }
    return 0;
}

int open_log_file() {
    log_file_fd = open(LOG_FILE, O_WRONLY | O_APPEND, 0644);
    if (log_file_fd < 0) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

void log_message(const char *message) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *localtime_result = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime_result);

    char full_message[256];
    snprintf(full_message, sizeof(full_message), "[%s] %s\n", timestamp, message);

    write(log_file_fd, full_message, strlen(full_message));
    write(STDOUT_FILENO, full_message, strlen(full_message));
}

int main(int argc, char *argv[]) {
    init_signals();
    if (open_gpio_chip() < 0) {
        return EXIT_FAILURE;
    }

    if (get_gpio_line(&gpio_line_fd) < 0) {
        return EXIT_FAILURE;
    }

    if (request_events(gpio_line_fd) < 0) {
        return EXIT_FAILURE;
    }

    while (!cleanup_flag) {
        if (wait_for_event(gpio_line_fd) < 0) {
            return EXIT_FAILURE;
        }

        int value;
        if (read_event(gpio_line_fd, &value) < 0) {
            return EXIT_FAILURE;
        }

        if (value == 0) { // Falling edge detected
            log_message("Vibration detected!");
            system("sudo shutdown -h now");
        }
    }

    if (request_events(gpio_line_fd) < 0) {
        perror("Failed to release events");
    }

    if (gpio_line_fd >= 0) {
        gpiod_line_free(gpio_line_fd);
        gpio_line_fd = -1;
    }

    if (gpio_chip_fd >= 0) {
        gpiod_chip_close(gpio_chip_fd);
        gpio_chip_fd = -1;
    }

    if (log_file_fd >= 0) {
        close(log_file_fd);
        log_file_fd = -1;
    }

    return EXIT_SUCCESS;
}

