        gpiod_chip_set_direction(MISO_GPIO, 0, GPIO_DIR_IN) < 0) {
        fprintf(stderr, "Failed to initialize GPIO MISO\n");
        close(fd);
        return;
    }

    if (gpiod_export(MOSI_GPIO, NULL) < 0 ||
        gpiod_chip_create_chip(MOSI_GPIO, NULL) < 0 ||
        gpiod_chip_export(MOSI_GPIO, NULL) < 0 ||
        gpiod_chip_get_line(MOSI_GPIO, 0) < 0 ||
        gpiod_chip_set_direction(MOSI_GPIO, 0, GPIO_DIR_OUT) < 0) {
        fprintf(stderr, "Failed to initialize GPIO MOSI\n");
        close(fd);
        return;
    }

    if (gpiod_export(SCLK_GPIO, NULL) < 0 ||
        gpiod_chip_create_chip(SCLK_GPIO, NULL) < 0 ||
        gpiod_chip_export(SCLK_GPIO, NULL) < 0 ||
        gpiod_chip_get_line(SCLK_GPIO, 0) < 0 ||
        gpiod_chip_set_direction(SCLK_GPIO, 0, GPIO_DIR_OUT) < 0) {
        fprintf(stderr, "Failed to initialize GPIO SCLK\n");
        close(fd);
        return;
    }

    if (write(fd, tx_buf, len) != len) {
        fprintf(stderr, "SPI transfer failed\n");
        close(fd);
        return;
    }

    close(fd);
}

void log_to_file(const float *data, int size) {
    int fd = open("temp_log.dat", O_WRONLY | O_APPEND | O_BINARY);
    if (fd < 0) {
        perror("Failed to open temp_log.dat");
        return;
    }

    if (write(fd, data, size * sizeof(float)) != size * sizeof(float)) {
        fprintf(stderr, "Failed to write to temp_log.dat\n");
    }

    close(fd);
}

void signal_handler(int signum) {
    printf("Signal %d received, cleaning up...\n", signum);
    gpiod_unexport(CE_GPIO);
    gpiod_unexport(MISO_GPIO);
    gpiod_unexport(MOSI_GPIO);
    gpiod_unexport(SCLK_GPIO);
    close(spi_fd);
    exit(0);
}

int main() {
    struct timespec ts;
    ts.tv_sec = 5;
    ts.tv_nsec = 0;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t tx_buf[2] = {0x01};
    uint8_t rx_buf[3];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (gpiod_chip_trigger(CE_GPIO, 0, GPIO_FALLING_EDGE) < 0) {
            fprintf(stderr, "Failed to trigger CE0\n");
            continue;
        }

        spi_transfer(tx_buf, rx_buf, 2);

        if (rx_buf[0] == 0x48) { // Check for successful conversion
            float temp = (rx_buf[1] << 8) | rx_buf[2];
            buffer[buffer_index] = temp;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            printf("Temperature: %.2f °C\n", temp);

            log_to_file(&buffer[buffer_index - (BUFFER_SIZE - 1)], BUFFER_SIZE);
        } else {
            fprintf(stderr, "SPI transfer failed, skipping this reading\n");
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}
