#define BH1750_ADDR 0x23
#define MCP3008_ADDR 0x20
#define MCP3008_CHANNEL 0

int i2c_fd = -1;
int spi_fd = -1;

void i2c_init(const char *bus) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_bh1750_light() {
    uint8_t data[2];
    if (write(i2c_fd, "R", 1) < 0) {
        handle_i2c_error("Failed to initiate BH1750 read");
        return 0;
    }

    if (read(i2c_fd, data, 2) != 2) {
        handle_i2c_error("Failed to read BH1750 data");
        return 0;
    }

    return (data[1] << 8) | data[0];
}

int read_mcp3008_adc() {
    uint8_t cmd[2];
    cmd[0] = MCP3008_ADDR << 5 | MCP3008_CHANNEL;
    cmd[1] = 0;

    if (write(spi_fd, cmd, 2) != 2) {
        handle_spi_error("Failed to initiate MCP3008 read");
        return -1;
    }

    uint8_t data[3];
    if (read(spi_fd, data, 3) != 3) {
        handle_spi_error("Failed to read MCP3008 data");
        return -1;
    }

    return (data[1] << 8) | data[2];
}

void handle_i2c_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void handle_spi_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

int main() {
    struct tm *now;
    time(&now);
    char filename[32];
    strftime(filename, sizeof(filename), "environmental_log_%Y-%m-%d.txt", now);

    int log_fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    i2c_init("/dev/i2c-1");
    spi_init();

    while (1) {
        uint16_t light = read_bh1750_light();
        int sound = read_mcp3008_adc();

        if (light == 0 || sound == -1) {
            fprintf(stderr, "Sensor absent or error occurred, skipping sample.\n");
            continue;
        }

        time_t now_time = time(NULL);
        struct tm tm_now = *localtime(&now_time);

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_now);

        char line[128];
        snprintf(line, sizeof(line), "%s, Light: %d, Sound: %d\n", timestamp, light, sound);

        if (write(log_fd, line, strlen(line)) != strlen(line)) {
            handle_error("Failed to write to log file");
            break;
        }

        usleep(1000000);
    }

    close(log_fd);
    close(i2c_fd);
    close(spi_fd);

    return EXIT_SUCCESS;
}

