#include <string.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define FLAME_SENSOR_PULL_DOWN

struct timespec get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file = NULL;

    ret = gpiod_new(&chip);
    if (ret) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_strerror(ret));
        return 1;
    }

    ret = gpiod_chip_find(chip, "GPIO1-RCB17");
    if (ret) {
        fprintf(stderr, "Failed to find GPIO1-RCB17: %s\n", gpiod_strerror(ret));
        gpiod_free(chip);
        return 1;
    }

    ret = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN, &line);
    if (ret) {
        fprintf(stderr, "Failed to get line %d: %s\n", FLAME_SENSOR_PIN, gpiod_strerror(ret));
        gpiod_free(chip);
        return 1;
    }

    if (line->direction != GPIOD_IN) {
        fprintf(stderr, "Failed to set line %d direction to input\n", FLAME_SENSOR_PIN);
        gpiod_free(chip);
        return 1;
    }

    if (FLAME_SENSOR_PULL_DOWN) {
        if (gpiod_line_set_pull(line, GPIO_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on line %d\n", FLAME_SENSOR_PIN);
            gpiod_free(chip);
            return 1;
        }
    }

    log_file = fopen("flame_events.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_free(chip);
        return 1;
    }

    fprintf(log_file, "Timestamp,Pin,State\n");

    while (1) {
        struct timespec ts = get_timestamp();
        uint32_t state = gpiod_line_get_value(line);

        fprintf(log_file, "%ld,%d,%u\n", ts.tv_sec, FLAME_SENSOR_PIN, state);

        if (state == 1) {
            fprintf(stdout, "ALARM: Flame detected!\n");
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_free(line);
    gpiod_chip_free(chip);

    return 0;
}

