#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <errno.h>
#include <gpiod.h>

#define TMP36_ADC_CHANNEL 0
#define MCP4725_I2C_ADDR 0x62
#define TEMP_LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 0.5

struct spi_dev {
    int spi_fd;
    struct gpiod_chip *chip;
};

struct i2c_dev {
    int i2c_fd;
    struct gpiod_chip *chip;
};

static int spi_init(struct spi_dev *dev) {
    dev->spi_fd = spi_open("/dev/spidev0.0", O_RDWR);
    if (dev->spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    dev->chip = gpiod_chip_open(GPIOD_CHIP_SPI0_MOSI, true);
    if (!dev->chip) {
        close(dev->spi_fd);
        dev->spi_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_init(struct i2c_dev *dev) {
    dev->i2c_fd = i2c_open_device(0x68, true); // I2C bus address of MCP3008
    if (dev->i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    dev->chip = gpiod_chip_open(GPIOD_CHIP_I2C0_SDA, true);
    if (!dev->chip) {
        close(dev->i2c_fd);
        dev->i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(struct spi_dev *dev, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    return spi_xfer(dev->spi_fd, tx_buf, rx_buf, len);
}

static int i2c_write(struct i2c_dev *dev, uint8_t reg, uint16_t value) {
    if (i2c_write_byte_data(dev->i2c_fd, reg, value >> 8) < 0)
        return -1;
    if (i2c_write_byte_data(dev->i2c_fd, reg + 1, value & 0xFF) < 0)
        return -1;
    return 0;
}

static uint16_t read_tmp36_adc(struct spi_dev *dev) {
    uint8_t tx_buf[2] = {MCP3008_START_CONV | TMP36_ADC_CHANNEL, 0};
    uint8_t rx_buf[3];
    int ret = spi_transfer(dev, tx_buf, rx_buf, sizeof(rx_buf));
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return (rx_buf[1] << 8) | rx_buf[2];
}

static double adc_to_temp_celsius(uint16_t adc_value) {
    return (adc_value * 5.0 / 1024.0) - 0.5;
}

static int dac_set_voltage(struct i2c_dev *dev, double voltage) {
    uint16_t dac_value = (uint16_t)(voltage * 4095);
    return i2c_write(dev, MCP4725_REG_DAC_VALUE, dac_value);
}

static void log_temperature_reading(double temp_celsius, double dac_voltage) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_file = fopen(TEMP_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, Raw ADC: %d, Temperature (°C): %.2f, DAC Voltage (V): %.3f\n",
            timestamp, adc_value, temp_celsius, dac_voltage);
    fclose(log_file);
}

int main() {
    struct spi_dev spi_dev;
    struct i2c_dev i2c_dev;

    if (spi_init(&spi_dev) < 0)
        return 1;

    if (i2c_init(&i2c_dev) < 0) {
        spi_close(spi_dev.spi_fd);
        return 1;
    }

    while (1) {
        uint16_t adc_value = read_tmp36_adc(&spi_dev);
        if (adc_value < 0)
            continue;

        double temp_celsius = adc_to_temp_celsius(adc_value);
        double dac_voltage = temp_celsius * 5.0; // Assuming a linear relationship

        log_temperature_reading(temp_celsius, dac_voltage);
        printf("Raw ADC: %d, Temperature (°C): %.2f, DAC Voltage (V): %.3f\n",
               adc_value, temp_celsius, dac_voltage);

        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    // Clean up on SIGINT
    signal(SIGINT, (void (*)(int))cleanup);

    return 0;

cleanup:
    if (i2c_dev.i2c_fd >= 0) {
        i2c_close(i2c_dev.i2c_fd);
    }

    if (spi_dev.spi_fd >= 0) {
        spi_close(spi_dev.spi_fd);
    }

    gpiod_chip_close(i2c_dev.chip);
    gpiod_chip_close(spi_dev.chip);

    return 0;
}

