struct sensor_data {
    int adc_value;
    char timestamp[20];
};

struct sensor_data sensor_readings[NUM_SENSORS];
FILE *log_file;

void signal_handler(int signum) {
    gpio_stop();
    fclose(log_file);
    exit(0);
}

int spi_init() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct gpio_config spi_config = {
        .fd = fd,
        .mode = 0,
        .bits_per_word = 16,
        .max_speed_hz = 1000000,
    };

    if (gpio_setup(&spi_config) < 0) {
        close(fd);
        return -1;
    }

    return 0;
}

int adc_read(int channel) {
    uint16_t adc_data;
    if (gpio_xfer(&adc_data) < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    if (channel < 0 || channel > NUM_SENSORS - 1) {
        fprintf(stderr, "Invalid channel number\n");
        return -1;
    }

    sensor_readings[channel].adc_value = adc_data;
    return 0;
}

void log_data() {
    time_t now;
    struct tm *time_struct;
    time(&now);
    time_struct = localtime(&now);

    strftime(sensor_readings[0].timestamp, sizeof(sensor_readings[0].timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_file, "%s, Sensor %d: %d\n", sensor_readings[i].timestamp, i + 1, sensor_readings[i].adc_value);
    }

    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (spi_init() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpio_stop();
        return 1;
    }

    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_read(i);
        }
        log_data();
        sleep(60);
    }

    gpio_stop();
    fclose(log_file);
    return 0;
}

