#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpio.h>

#define RELAY_PINS 4
#define DELAY_MS 1000

gpio_context ctx;

void sigint_handler(int signum) {
    gpio_stop(&ctx);
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    gpio_init(&ctx);

    if (gpio_request_available(&ctx) < RELAY_PINS) {
        fprintf(stderr, "Error: Not enough GPIO pins available.\n");
        gpio_free(&ctx);
        return EXIT_FAILURE;
    }

    const gpio_pin relay_pins[RELAY_PINS] = {
        .pin = 17,
        .pull = GPIO_PULL_DOWN,
    }, {
        .pin = 22,
        .pull = GPIO_PULL_DOWN,
    }, {
        .pin = 23,
        .pull = GPIO_PULL_DOWN,
    }, {
        .pin = 24,
        .pull = GPIO_PULL_DOWN,
    };

    for (size_t i = 0; i < RELAY_PINS; ++i) {
        int rc = gpio_set(ctx, relay_pins + i);
        if (rc) {
            fprintf(stderr, "Error setting GPIO %d\n", relay_pins[i].pin);
            gpio_free(&ctx);
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    size_t index = 0;
    while (1) {
        gpio_set(ctx, relay_pins + index, 1);
        sleep(DELAY_MS / 1000);
        gpio_set(ctx, relay_pins + index, 0);
        sleep(DELAY_MS / 1000);

        index = (index + 1) % RELAY_PINS;
    }

    gpio_free(&ctx);
    return EXIT_SUCCESS;
}

