#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define CHANNEL 0
#define LED_GPIO 16
#define SPI_CE0_GPIO 8
#define THRESHOLD 500
#define DEBOUNCE_DELAY 500000 // 500 ms
#define SAMPLE_INTERVAL 10000 // 10 ms
#define SPI_MODE 0
#define SPI_BAUDRATE 1000000

static struct gpiod_chip *chip;
static struct gpiod_line *spi_ce0;
static struct gpiod_line *led;
int spi_fd;

void sigint_handler(int signum) {
    gpiod_batch_submit();
    close(spi_fd);
    pigpio_terminate(NULL);
    exit(0);
}

void setup_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    spi_ce0 = gpiod_chip_get_line(chip, SPI_CE0_GPIO);
    if (!spi_ce0) {
        fprintf(stderr, "Failed to get SPI CE0 line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(spi_ce0, "SPI_CE0");
    gpiod_line_export(led, "LED");

    ret = ioctl(spi_ce0->fd, GPIO_REQUEST_USE, spi_ce0->line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request SPI CE0 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(led->fd, GPIO_REQUEST_USE, led->line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
}

void cleanup_gpio() {
    gpiod_line_release(spi_ce0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
}

int main() {
    setup_gpio();

    spi_fd = spi_open(SPI_CE0_GPIO, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    pigpio_initialise();
    pigpio_set_mode(LED_GPIO, PI_OUTPUT);
    pigpio_set_pull_up_down(LED_GPIO, 1);

    FILE *log_file = fopen("sound_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_gpio();
        spi_close(spi_fd);
        pigpio_terminate(NULL);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value;
        int ret = spi_transfer(spi_fd, &adc_value);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            break;
        }

        if (adc_value > THRESHOLD) {
            pigpio_write(LED_GPIO, 1);
            sleep_ms(DEBOUNCE_DELAY);
            pigdio_write(LED_GPIO, 0);

            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            fprintf(log_file, "%s: Sound sensor triggered\n", timestamp);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup_gpio();
    spi_close(spi_fd);
    pigpio_terminate(NULL);
    fclose(log_file);
    return 0;
}

