#define GPIO_MCP3008_CS 23
#define GPIO_L298N_IN1 17
#define GPIO_L298N_IN2 18
#define GPIO_L298N_ENA 27
#define LOG_FILE "rain_log.txt"

volatile sig_atomic_t stop_flag = 0;

struct spi_dev spi;
struct gpiod_chip chip;
FILE *log_file = NULL;

void spi_init() {
    if (gpiod_chip_open(&chip, "/dev/spidev0.0") < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }
    spi.fd = fileno(stdout);
    spi.speed_hz = 1000000;
    spi.mode = 0;
    spi.bits_per_word = 10;
    spi.max_speed_hz = 1000000;
}

void motor_init() {
    gpio_init(GPIO_L298N_IN1);
    gpio_init(GPIO_L298N_IN2);
    gpio_init(GPIO_L298N_ENA);
    gpio_set_dir(GPIO_L298N_IN1, GPIO_OUTPUT);
    gpio_set_dir(GPIO_L298N_IN2, GPIO_OUTPUT);
    gpio_set_dir(GPIO_L298N_ENA, GPIO_OUTPUT);
    gpio_set_value(GPIO_L298N_IN1, 0);
    gpio_set_value(GPIO_L298N_IN2, 0);
    gpio_set_pwm_duty(GPIO_L298N_ENA, MOTOR_PWM);
}

uint16_t read_mcp3008() {
    uint8_t data[3];
    if (gpiod_chip_write(chip.id, GPIO_MCP3008_CLK, 0) < 0 ||
        gpiod_chip_write(chip.id, GPIO_MCP3008_CLK, 1) < 0 ||
        gpiod_chip_read(chip.id, GPIO_MCP3008_DOUT, data, 3) != 3) {
        fprintf(stderr, "SPI transfer error\n");
        return 0;
    }
    return (data[1] << 8) | data[0];
}

void log_rain_level(uint16_t level) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            exit(EXIT_FAILURE);
        }
    }
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%d\n", now, level);
    fflush(log_file);
}

void close_window() {
    gpio_set_value(GPIO_L298N_IN1, 1);
}

void open_window() {
    gpio_set_value(GPIO_L298N_IN1, 0);
}

void motor_control(bool forward) {
    if (forward) {
        open_window();
        gpio_set_value(GPIO_L298N_IN1, 0);
    } else {
        close_window();
        gpio_set_value(GPIO_L298N_IN1, 1);
    }
    gpio_set_pwm_duty(GPIO_L298N_ENA, 0);
    sleep(3);
    gpio_set_pwm_duty(GPIO_L298N_ENA, MOTOR_PWM);
}

void sigint_handler(int signum) {
    stop_flag = 1;
}

void sigterm_handler(int signum) {
    stop_flag = 1;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    spi_init();
    motor_init();

    if (gpiod_chip_write(chip.id, GPIO_MCP3008_CS, 0) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        uint16_t level = read_mcp3008();
        log_rain_level(level);

        if (level > RAIN_THRESHOLD) {
            motor_control(true);
        } else {
            motor_control(false);
        }

        sleep(1);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpiod_chip_close(chip.id);
    gpio_free();

    return 0;
}
