#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define MIC_PIN 26
#define LED_PIN 16
#define SAMPLE_COUNT 100
#define DEBOUNCE_INTERVAL_MS 50
#define CLAP_THRESHOLD 500

typedef struct {
    int pin;
    int state;
    struct timespec last_change;
} GPIO_Pin;

GPIO_Pin mic_pin = {MIC_PIN, 0, {0, 0}};
GPIO_Pin led_pin = {LED_PIN, 0, {0, 0}};

void sigint_handler(int signum) {
    gpioTerminate();
    printf("SIGINT received, cleaning up...\n");
    exit(0);
}

uint16_t read_adc(int pin) {
    gpioSetMode(pin, GPIO_OUTPUT);
    gpioWrite(pin, 1);
    gpioSetMode(pin, GPIO_INPUT);
    uint16_t adc_value = gpioRead(pin);
    gpioWrite(pin, 0);
    return adc_value;
}

bool is_clap(uint16_t adc_value) {
    return adc_value > CLAP_THRESHOLD;
}

void toggle_led(GPIO_Pin *led_pin) {
    gpioWrite(led_pin->pin, !led_pin->state);
    led_pin->state = !led_pin->state;
}

void debounce_check(GPIO_Pin *pin) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (difftime(now.tv_sec, pin->last_change.tv_sec) > 1.0 / DEBOUNCE_INTERVAL_MS) {
        pin->last_change = now;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialize() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(MIC_PIN, GPIO_INPUT) < 0 || gpioSetMode(LED_PIN, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint16_t adc_value = read_adc(MIC_PIN);
        debounce_check(&mic_pin);

        if (is_clap(adc_value)) {
            printf("Clap detected at %ld.%09ld\n", mic_pin.last_change.tv_sec, mic_pin.last_change.tv_nsec);
            toggle_led(&led_pin);
            delay(500 * 1000000);
            toggle_led(&led_pin);
        }

        clock_gettime(CLOCK_MONOTONIC, &mic_pin.last_change);
    }

    gpioTerminate();
    return 0;
}

