#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define MAX_RETRIES 5
#define MIN_DISTANCE 200

static int retry_count = 0;
static FILE *log_file = NULL;

void log_message(const char *message) {
    static char timestamp[20];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    if (log_file == NULL) {
        log_file = fopen("distance_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Unable to open log file.\n");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    struct gpiod_chip_params params =GPIOD_CHIP_OPEN_FIRST;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(&params);
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip.\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Unable to get GPIO line %d.\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_export(line, &params);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to export GPIO line %d.\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int distance = gpiod_line_get_value(line);
        char *message;

        if (distance) {
            message = "Feeder Idle";
        } else {
            message = "Feeder Activated";
        }

        log_message(message);
        printf("%s\n", message);

        if (distance < MIN_DISTANCE) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        if (retry_count++ >= MAX_RETRIES) {
            fprintf(stderr, "Error: Maximum retries reached.\n");
            break;
        }

        if (signal(SIGINT, cleanup) != SIG_ERR && signal(SIGTERM, cleanup) != SIG_ERR) {
            fprintf(stderr, "Error: Signal handlers not properly set.\n");
            break;
        }

        sleep(1);
    }

    cleanup:
    if (log_file) {
        fclose(log_file);
    }

    gpiod_line_unexport(line);
    gpiod_chip_close(chip);

    return 0;
}

