#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpio.h>
#include <gpiod.h>

#define MOISTURE_THRESHOLD 30
#define SAMPLE_INTERVAL 60
#define SPI_DEVICE 0
#define ADC_CHANNEL 0
#define RELAY_PIN 17
#define LOG_FILE "soil_moisture.log"

static const char *log_format = "%s, Moisture: %d%%, Pump: %s\n";

static int spi_fd;
static int adc_fd;
static int log_fd;
static FILE *log_file;

void init_gpio() {
    int ret;

    ret = gpioInitialize();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RELAY_PIN, GPIO_OUTPUT);
    gpioExport(RELAY_PIN);
    gpioSetDirection(RELAY_PIN, GPIO_SET);
    gpioSetValue(RELAY_PIN, 0); // Pump OFF
}

void init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void init_adc() {
    adc_fd = open("/dev/mem", O_RDWR | O_CLOEXEC);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Map ADC memory to address space
    struct spi_device *dev = malloc(sizeof(struct spi_device));
    dev->fd = spi_fd;
    dev->mode = 0;
    dev->bits_per_word = 16;
    dev->speed_hz = 1000000;
    dev->delay_usecs = 0;
    dev->circle_buffer = 0;
    dev->lsb_first = 1;
    dev->shares_spd = 0;
    dev->max_speed_hz = 10000000;
    dev->flags = 0;
    dev->user_data = NULL;

    if (gpiod_cmnd_add_override(gpio, adc_fd, 0, dev) < 0) {
        fprintf(stderr, "Failed to add ADC override\n");
        exit(EXIT_FAILURE);
    }
}

void init_log_file() {
    log_file = fopen("soil_moisture.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc(int channel) {
    uint16_t adc_value;
    struct spi_transfer spi_tx_buf, spi_rx_buf;

    spi_tx_buf.bits = (channel << 4) | 0x00; // Single-ended, channel 0
    spi_rx_buf.bits = 0;

    spi_transfer(spi_fd, &spi_tx_buf, &spi_rx_buf);
    adc_value = spi_rx_buf.bits & 0x00FF;

    return adc_value;
}

float adc_to_percentage(uint16_t adc_value) {
    // Assuming Vref = 3.3V and Vout = 1.1V for VH400
    return (float)adc_value * (3300.0 / 4095.0) * 100.0;
}

void log_sample(float moisture_percentage) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Moisture: %d%%, Pump: %s\n",
            1900 + local_time->tm_year,
            1 + local_time->tm_mon,
            local_time->tm_mday,
            local_time->tm_hour,
            local_time->tm_min,
            local_time->tm_sec,
            (int)moisture_percentage,
            gpioGetValue(RELAY_PIN) == 1 ? "ON" : "OFF");

    fflush(log_file);
}

void cleanup() {
    fclose(log_file);
    gpioUnexport(RELAY_PIN);
    gpioRelease(RELAY_PIN);
    gpioUninitialize();
    close(spi_fd);
    close(adc_fd);
}

int main() {
    int ret;
    struct gpiod_chip_params params = {
        .gpio_chip_type = GPIO_CHIP_TYPE_PERIPH,
        .gpios = {RELAY_PIN},
        .count = 1,
    };

    ret = gpiod_chip_init(gpio, &params);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    init_gpio();
    init_spi();
    init_adc();
    init_log_file();

    while (1) {
        uint16_t adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == 0xFFFF) {
            fprintf(stderr, "ADC read error\n");
            continue;
        }

        float moisture_percentage = adc_to_percentage(adc_value);
        log_sample(moisture_percentage);

        if (moisture_percentage < MOISTURE_THRESHOLD) {
            gpioSetValue(RELAY_PIN, 1); // Pump ON
        } else {
            gpioSetValue(RELAY_PIN, 0); // Pump OFF
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

