        }

        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            break;
        }
    }

    fclose(log_fd);
    gpiod_chip_unexport(gpio_chip);
    close(spi_fd);

    return 0;
}

