#include <signal.h>
#include <gpio.h>

#define MCP3008_CS_PIN 10
#define MCP3008_CLK_PIN 9
#define MCP3008_DOUT_PIN 8
#define MCP3008_DOIN_PIN 7
#define MCP3008_CHANNEL 0
#define MOISTURE_SENSOR_PIN 13

#define LOG_FILE "moisture_log.txt"

static FILE *log_file = NULL;

void init_spi(void) {
    int ret;

    ret = gpioInitialize();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_CLK_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_DOUT_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_DOIN_PIN, PI_INPUT);

    gpioWrite(MCP3008_CS_PIN, 1);
    gpioWrite(MCP3008_CLK_PIN, 0);
}

uint16_t read_adc(void) {
    uint16_t adc_value = 0;
    uint8_t data[3];

    gpioWrite(MCP3008_CS_PIN, 0);
    data[0] = gpioRead(MCP3008_DOIN_PIN);
    gpioWrite(MCP3008_CS_PIN, 1);

    data[1] = gpioRead(MCP3008_DOUT_PIN);
    gpioWrite(MCP3008_CS_PIN, 0);
    data[2] = gpioRead(MCP3008_DOIN_PIN);
    gpioWrite(MCP3008_CS_PIN, 1);

    adc_value = ((data[1] << 8) | data[0]);

    return adc_value;
}

void cleanup(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    time_t current_time;
    struct tm *time_struct;
    char timestamp[20];

    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);

    init_spi();

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        current_time = time(NULL);
        time_struct = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

        uint16_t adc_value = read_adc();

        if (adc_value == 65535) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            fprintf(log_file, "%s -1\n", timestamp);
        } else {
            fprintf(log_file, "%s %d\n", timestamp, adc_value);
        }

        sleep(60);
    }

    return 0;
}

