    close(spi_fd);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up and exiting...\n");
    cleanup();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up and exiting...\n");
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_chip_list *list;
    struct gpiod_chip *chip_tmp;
    struct gpiod_line *gpio_en_tmp;

    // Initialize GPIO
    if (gpiod_chip_list_get_first(&list) == 0) {
        chip_tmp = list->chips[0];
        gpio_en_tmp = gpiod_chip_get_line(chip_tmp, "GPIO" STR(SENSOR_GPIO));
        if (gpio_en_tmp == NULL) {
            fprintf(stderr, "Failed to get GPIO%d line\n", SENSOR_GPIO);
            return 1;
        }
