#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <gpio.h>

#define MLX91211_CHANNEL 0
#define SPI_MODE 0
#define SPI_BAUDRATE 1000000
#define SPI_CS_GPIO 8
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define SPI_SCLK_GPIO 11

volatile sig_atomic_t stop_sampling = 0;
FILE *log_file = NULL;

void spi_transfer_error(void) {
    gpio_transfer_error();
    fprintf(stderr, "Warning: SPI transfer error, skipping sample.\n");
}

void sample_current(void) {
    uint16_t adc_reading;
    float voltage, current;

    gpio_init();
    if (gpio_request(SPI_MOSI_GPIO, SPI_MISO_GPIO, SPI_SCLK_GPIO, SPI_CS_GPIO, SPI_BAUDRATE, SPI_MODE) < 0) {
        fprintf(stderr, "Error: Failed to initialize SPI.\n");
        gpio_terminate();
        exit(1);
    }

    while (!stop_sampling) {
        if (gpio_transfer(&adc_reading, 1, NULL, 0) < 0) {
            spi_transfer_error();
            continue;
        }

        voltage = adc_reading * (5.0 / 1023.0);
        if (voltage < 0 || voltage > 5) {
            fprintf(stderr, "Warning: Measured voltage outside 0-5V, skipping sample.\n");
            continue;
        }

        current = voltage * 1.5; // Assuming a gain of 1.5 for the MLX91211
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        if (log_file == NULL) {
            log_file = fopen("current_log.txt", "w");
            if (!log_file) {
                fprintf(stderr, "Error: Failed to open log file.\n");
                gpio_terminate();
                exit(1);
            }
        }

        fprintf(log_file, "%s %.2f\n", timestamp, current);
        fflush(log_file);

        usleep(100000);
    }

    gpio_terminate();
}

void sigint_handler(int signum) {
    stop_sampling = 1;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sample_current();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

