#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_READS 5
#define LOG_INTERVAL_MS 1000

volatile bool gpio_cleanup = false;

static void sigint_handler(int signum) {
    gpio_cleanup = true;
}

static int read_sensor(int sensor_gpio) {
    int value = GPIO_INPUT(sensor_gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return value;
}

static bool majority_voting(int *reads) {
    int count_ones = 0;
    for (int i = 0; i < DEBOUNCE_READS; i++) {
        if (reads[i] == 0) {
            count_ones++;
        }
    }
    return count_ones > DEBOUNCE_READS / 2;
}

int main() {
    struct signal_frame frame;
    frame.sf_signum = SIGINT;
    frame.sf_handler = sigint_handler;
    sigaction(SIGINT, &frame, NULL);

    gpio_init();

    if (gpio_export(SENSOR1_GPIO, "Sensor 1") < 0 || gpio_export(SENSOR2_GPIO, "Sensor 2") < 0) {
        fprintf(stderr, "Error exporting GPIOs\n");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    gpio_set_direction(SENSOR1_GPIO, GPIO_OUTPUT);
    gpio_set_direction(SENSOR2_GPIO, GPIO_OUTPUT);

    int sensor1_reads[DEBOUNCE_READS];
    int sensor2_reads[DEBOUNCE_READS];

    while (!gpio_cleanup) {
        for (int i = 0; i < DEBOUNCE_READS; i++) {
            sensor1_reads[i] = read_sensor(SENSOR1_GPIO);
            sensor2_reads[i] = read_sensor(SENSOR2_GPIO);
            gpio_poll_for_changes(SENSOR1_GPIO, 2);
            gpio_poll_for_changes(SENSOR2_GPIO, 2);
            usleep(2000 * 1000);
        }

        bool sensor1_state = majority_voting(sensor1_reads);
        bool sensor2_state = majority_voting(sensor2_reads);

        if (sensor1_state && sensor2_state) {
            printf("ALERT: Both sensors detect object\n");
        } else if (sensor1_state) {
            printf("0\n");
        } else {
            printf("1\n");
        }

        fflush(stdout);
        sleep(LOG_INTERVAL_MS / 1000);
    }

    gpio_unexport(SENSOR1_GPIO);
    gpio_unexport(SENSOR2_GPIO);
    gpio_cleanup();

    return 0;
}

