#include <driver/gpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t sigint_flag = 0;

int spi_fd;

int read_mcp3008(int channel) {
    gpio_set_direction(GPIO_NUM_18, GPIO_MODE_OUTPUT);
    gpio_put_level(GPIO_NUM_18, 0);
    usleep(1);
    gpio_put_level(GPIO_NUM_18, 1);
    usleep(10);

    uint8_t tx_buf[2] = {1 << channel};
    uint8_t rx_buf[3];
    int len = spi_transfer(spi_fd, tx_buf, rx_buf, 2, 3);

    if (len != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        sleep(5);
        return -1;
    }

    return ((rx_buf[1] << 8) | rx_buf[2]);
}

double calculate_moisture_level(int adc_value) {
    return (adc_value - MIN_ADC) * 100.0 / (MAX_ADC - MIN_ADC);
}

void log_data(double moisture_level) {
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

void signal_handler(int signal) {
    sigint_flag = 1;
}

int spi_setup(spi_config_t config) {
    spi_device_init(config);
    spi_fd = spi_device_open(SPI_CHANNEL, 0);
    if (!spi_fd) {
        spi_device_close(spi_fd);
        pigpio_terminate();
        exit(EXIT_FAILURE);
    }
    return 0;
}

int main() {
    gpio_init();
    pigpio_init();

    spi_config_t spi_config;
    spi_config.mode = SPI_MODE_0;
    spi_config.bits_per_word = 8;
    spi_config.max_speed_hz = SPI_BAUD;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return EXIT_FAILURE;
    }

    if (spi_setup(spi_config) < 0) {
        return EXIT_FAILURE;
    }

    while (!sigint_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
            fprintf(stderr, "Invalid ADC value\n");
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    pigpio_terminate();
    spi_device_close(spi_fd);
    gpio_deinit();

    return 0;
}

