#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>
#include <libgpiod.h>

#define PIR_GPIO 17
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_MS 200
#define CAPTURE_DIR "/home/pi/security_cam"
#define LOG_TAG "PIR_SENSOR"

int gpio_initialized = 0;
gpiod_chip *chip;
gpiod_line *line;

void log_event(const char *event) {
    syslog(LOG_INFO, "%s: %s", LOG_TAG, event);
}

void init_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "GPIO17");
    if (ret < 0) {
        log_event("Failed to open GPIO chip");
        return;
    }

    ret = gpiod_chip_get_line(chip, &line, "GPIO17", gpiod_line_in);
    if (ret < 0) {
        log_event("Failed to get line for GPIO17");
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        log_event("Failed to export line");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    gpio_initialized = 1;
    log_event("GPIO initialized");
}

void cleanup_gpio() {
    if (gpio_initialized) {
        gpiod_line_unexport(line);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        gpio_initialized = 0;
        log_event("GPIO cleaned up");
    }
}

void capture_image() {
    char cmd[256];
    int child_status;

    snprintf(cmd, sizeof(cmd), "libcamera-still --format jpg --size full --output %s/motion_%d_%s.jpg", CAPTURE_DIR, getpid(), get_iso8601_timestamp());
    if (fork() == 0) {
        execvp(cmd, (char *const []){cmd, NULL});
        fprintf(stderr, "Error: libcamera-still failed to execute\n");
        _exit(1);
    }

    waitpid(getppid(), &child_status, 0);
    if (WIFEXITED(child_status) && WEXITSTATUS(child_status) != 0) {
        log_event("Image capture failed");
    } else {
        log_event("Image captured");
    }
}

char *get_iso8601_timestamp() {
    time_t now = time(NULL);
    char *dt = ctime(&now);
    dt[strlen(dt) - 1] = '\0'; // Remove newline character
    return dt;
}

int main() {
    struct timespec poll_interval, debounce_delay;
    clock_getres(CLOCK_MONOTONIC, &poll_interval);
    clock_getres(CLOCK_MONOTONIC, &debounce_delay);

    init_gpio();

    if (!gpio_initialized) {
        log_event("Exiting due to GPIO initialization failure");
