    ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        log_event("Failed to export line");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    gpio_initialized = 1;
    log_event("GPIO initialized");
}

void cleanup_gpio() {
