#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <gpiod.h>
#include <time.h>

#define BUFFER_SIZE 3840 * 2160 * 2 // 1080p, 2 bytes per pixel
#define LOG_FILE "frame_log.txt"

int video_fd = -1;
void *video_buffer = NULL;

void usage_and_exit() {
    fprintf(stderr, "Usage: %s\n", argv[0]);
    exit(EXIT_FAILURE);
}

void cleanup() {
    if (video_fd != -1) {
        munmap(video_buffer, BUFFER_SIZE);
        close(video_fd);
    }
}

int init_video_device(const char *device) {
    video_fd = open(device, O_RDWR);
    if (video_fd == -1) {
        perror("Failed to open video device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(video_fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query video device capability");
        goto err_close_fd;
    }

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        struct v4l2_fmtdesc fmt;
        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(video_fd, VIDIOC_ENUM_FMT, &fmt) == -1) {
            perror("Failed to enumerate video formats");
            goto err_close_fd;
        }

        if (fmt.pixelformat == V4L2_PIX_FMT_MJPG) {
            struct v4l2_fract fract;
            fract.numerator = 1;
            fract.denominator = 1000000;
            if (ioctl(video_fd, VIDIOC_S_FRAC, &fract) == -1) {
                perror("Failed to set frame rate");
                goto err_close_fd;
            }

            size_t buffer_size = BUFFER_SIZE;
            video_buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, 0);
            if (video_buffer == MAP_FAILED) {
                perror("Failed to mmap video buffer");
                goto err_close_fd;
            }

            return 0;
        } else {
            fprintf(stderr, "Unsupported pixel format: %d\n", fmt.pixelformat);
            return -1;
        }
    } else {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

err_close_fd:
    cleanup();
    return -1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        usage_and_exit();
    }

    if (init_video_device(argv[1]) == -1) {
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[24];
    strftime(timestamp, sizeof(timestamp), "%.6f", &ts.tv_sec + ts.tv_nsec * 1e-9);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(video_fd, &fds);

        int select_result = select(video_fd + 1, NULL, NULL, NULL, NULL);
        if (select_result == -1) {
            perror("select");
            cleanup();
            return EXIT_FAILURE;
        } else if (select_result == 0) {
            fprintf(stderr, "Timeout\n");
            continue;
        }

        if (FD_ISSET(video_fd, &fds)) {
            struct v4l2_buffer buf;
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = 0;

            if (ioctl(video_fd, VIDIOC_DQBUF, &buf) == -1) {
                perror("Failed to dequeue buffer");
                continue;
            }

            if (buf.length > 0) {
                // Process MJPEG frame here
                // ...

                fprintf(log_file, "%s\n", timestamp);
                buf.index = -1; // Signal to queue buffer for reuse
                if (ioctl(video_fd, VIDIOC_QBUF, &buf) == -1) {
                    perror("Failed to queue buffer");
                }
            }

            munmap(buf.address, buf.length);
        }
    }

    cleanup();
    fclose(log_file);
    return EXIT_SUCCESS;
}

