#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define BUFFER_COUNT 4
#define MAX_FRAME_SIZE 65000
#define TARGET_IP "127.0.0.1"
#define TARGET_PORT 5000

struct buffer {
    void *addr;
    size_t len;
};

static int setup_camera(int *fd) {
    *fd = open("/dev/video0", O_RDWR);
    if (*fd < 0) {
        perror("Failed to open video device");
        return -1;
    }

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        close(*fd);
        return -1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set buffer size and format");
        close(*fd);
        return -1;
    }

    buffers = malloc(BUFFER_COUNT * sizeof(struct buffer));
    if (!buffers) {
        perror("Failed to allocate memory for buffers");
        close(*fd);
        return -1;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        buffers[i].addr = mmap(NULL, fmt.fmt.pix.sizeimage, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, fmt.fmt.index);
        if (buffers[i].addr < 0) {
            perror("Failed to mmap buffer");
            for (int j = 0; j < i; j++) {
                munmap(buffers[j].addr, fmt.fmt.pix.sizeimage);
            }
            free(buffers);
            close(*fd);
            return -1;
        }
        buffers[i].len = fmt.fmt.pix.sizeimage;
    }

    return 0;
}

