#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>

#define BUFFER_COUNT 4

int main() {
    int fd, ret, i;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers rb;
    struct v4l2_memories mem;
    struct v4l2_control control;
    mhd_file *file;
    unsigned char *map;

    fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query video device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support video capture or streaming\n");
        close(fd);
        return 1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 192;
    fmt.fmt.pix.height = 1;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set video format");
        close(fd);
        return 1;
    }

    rb.count = BUFFER_COUNT;
    rb.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &rb) == -1) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    map = (unsigned char *)mmap(NULL, rb.count * rb.memory_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("Failed to mmap buffers");
        close(fd);
        return 1;
    }

    file = fopen("image.jpg", "wb");
    if (!file) {
        perror("Failed to open image.jpg for writing");
        munmap(map, rb.count * rb.memory_size);
        close(fd);
        return 1;
    }

    while (1) {
        buf.index = 0;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.bytesused = 0;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("Failed to dequeue buffer");
            break;
        }

        if (buf.bytesused <= 0) {
            fprintf(stderr, "Dequeued buffer bytesused is zero\n");
            break;
        }

        fwrite(map + buf.m.planes[0].data, 1, buf.bytesused, file);
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer");
            break;
        }
    }

    munmap(map, rb.count * rb.memory_size);
    fclose(file);
    ioctl(fd, VIDIOC_FREEBUFS, &rb);
    close(fd);

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Caught signal %d, stopping...\n", signum);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    // Rest of the main function remains the same
}

