#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define PAN_SERVO_GPIO 4
#define TILT_SERVO_GPIO 5
#define TILT_UP_BUTTON_GPIO 6
#define TILT_DOWN_BUTTON_GPIO 7
#define PAN_LEFT_BUTTON_GPIO 8
#define PAN_RIGHT_BUTTON_GPIO 9

#define PWM_PERIOD_US 20000
#define PWM_MIN_US 1000
#define PWM_MAX_US 2000
#define POSITION_MIN 25
#define POSITION_MAX 125

struct servo_state {
    int gpio;
    int position;
    gpiod_chip *chip;
    gpiod_line *line;
};

struct button_state {
    int gpio;
    gpiod_chip *chip;
    gpiod_line *line;
};

struct servo_state servos[2];
struct button_state buttons[4];

void pwm_set_duty(struct servo_state *servo, int duty) {
    uint32_t period = PWM_PERIOD_US * 1000;
    uint32_t pulse_width = (duty * period) / 100;

    if (gpiod_set_value_generic(servo->line, pulse_width) ||
        gpiod_set_value_generic(servo->line, 0)) {
        fprintf(stderr, "Failed to set PWM duty cycle for servo %d\n", servo->gpio);
        exit(EXIT_FAILURE);
    }
}

void init_servo(struct servo_state *servo) {
    servo->chip = gpiod_chip_open(servo->gpio);
    if (!servo->chip) {
        fprintf(stderr, "Failed to open GPIO %d\n", servo->gpio);
        exit(EXIT_FAILURE);
    }

    servo->line = gpiod_chip_get_line(servo->chip, "PWM");
    if (!servo->line) {
        fprintf(stderr, "Failed to get PWM line for GPIO %d\n", servo->gpio);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_cookied(servo->line, GPIO_DIR_OUT);

    servo->position = POSITION_MIN + (POSITION_MAX - POSITION_MIN) / 2;
}

void init_buttons(struct button_state *button) {
    button->chip = gpiod_chip_open(button->gpio);
    if (!button->chip) {
        fprintf(stderr, "Failed to open GPIO %d\n", button->gpio);
        exit(EXIT_FAILURE);
    }

    button->line = gpiod_chip_get_line(button->chip, "IRQ");
    if (!button->line) {
        fprintf(stderr, "Failed to get IRQ line for GPIO %d\n", button->gpio);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_cookied(button->line, GPIO_DIR_IN | GPIO_EV_RISING | GPIO_EV_FALLING);
}

void handle_button_press(struct button_state *button) {
    if (gpiod_trigger_cooked(button->line, button->gpio)) {
        fprintf(stderr, "Failed to trigger IRQ for button %d\n", button->gpio);
        exit(EXIT_FAILURE);
    }
}

void update_servo_position(struct servo_state *servo, int delta) {
    servo->position = std::clamp(servo->position + delta, POSITION_MIN, POSITION_MAX);

    uint32_t pulse_width = (servo->position - POSITION_MIN) * (PWM_PERIOD_US - PWM_MIN_US) / (POSITION_MAX - POSITION_MIN) + PWM_MIN_US;
    pwm_set_duty(servo, pulse_width / PWM_PERIOD_US * 1000);
}

void cleanup() {
    for (int i = 0; i < 2; i++) {
        gpiod_line_release(servos[i].line);
        gpiod_chip_close(servos[i].chip);
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_release(buttons[i].line);
        gpiod_chip_close(buttons[i].chip);
    }
}

void sigint_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_servo(&servos[0], PAN_SERVO_GPIO);
    init_servo(&servos[1], TILT_SERVO_GPIO);

    init_buttons(&buttons[0], TILT_UP_BUTTON_GPIO);
    init_buttons(&buttons[1], TILT_DOWN_BUTTON_GPIO);
    init_buttons(&buttons[2], PAN_LEFT_BUTTON_GPIO);
    init_buttons(&buttons[3], PAN_RIGHT_BUTTON_GPIO);

    while (true) {
        for (int i = 0; i < 4; i++) {
            handle_button_press(&buttons[i]);
        }

        update_servo_position(&servos[0], (rand() % 10 - 5) / 10);
        update_servo_position(&servos[1], (rand() % 10 - 5) / 10);

        usleep(50000);
    }

    cleanup();
    return 0;
}

