        fprintf(stderr, "Failed to get IRQ line for GPIO %d\n", button->gpio);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_cookied(button->line, GPIO_DIR_IN | GPIO_EV_RISING | GPIO_EV_FALLING);
}

void handle_button_press(struct button_state *button) {
    if (gpiod_trigger_cooked(button->line, button->gpio)) {
        fprintf(stderr, "Failed to trigger IRQ for button %d\n", button->gpio);
        exit(EXIT_FAILURE);
    }
}

void update_servo_position(struct servo_state *servo, int delta) {
    servo->position = std::clamp(servo->position + delta, POSITION_MIN, POSITION_MAX);

    uint32_t pulse_width = (servo->position - POSITION_MIN) * (PWM_PERIOD_US - PWM_MIN_US) / (POSITION_MAX - POSITION_MIN) + PWM_MIN_US;
    pwm_set_duty(servo, pulse_width / PWM_PERIOD_US * 1000);
}

void cleanup() {
    for (int i = 0; i < 2; i++) {
        gpiod_line_release(servos[i].line);
        gpiod_chip_close(servos[i].chip);
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_release(buttons[i].line);
        gpiod_chip_close(buttons[i].chip);
    }
}

void sigint_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_servo(&servos[0], PAN_SERVO_GPIO);
    init_servo(&servos[1], TILT_SERVO_GPIO);

    init_buttons(&buttons[0], TILT_UP_BUTTON_GPIO);
    init_buttons(&buttons[1], TILT_DOWN_BUTTON_GPIO);
    init_buttons(&buttons[2], PAN_LEFT_BUTTON_GPIO);
    init_buttons(&buttons[3], PAN_RIGHT_BUTTON_GPIO);

    while (true) {
        for (int i = 0; i < 4; i++) {
            handle_button_press(&buttons[i]);
        }

        update_servo_position(&servos[0], (rand() % 10 - 5) / 10);
        update_servo_position(&servos[1], (rand() % 10 - 5) / 10);

        usleep(50000);
    }

    cleanup();
    return 0;
}
