#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <media/v4l2-controls.h>
#include <media/v4l2-device.h>
#include <media/v4l2-common.h>
#include <media/v4l2-videodev.h>

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    int ret;

    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        goto out;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query V4L2 capabilities");
        close(fd);
        goto out;
    }

    if (!((cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) &&
          (cap.capabilities & V4L2_CAP_TUNER))) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    struct v4l2_frmsizeenum fs_enum;
    fs_enum.pixel_format = V4L2_PIX_FMT_SBGGR8;
    fs_enum.type = V4L2_FRMINF_TYPE_DISCRETE;

    ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs_enum);
    if (ret < 0) {
        fprintf(stderr, "Failed to enumerate frame sizes\n");
        close(fd);
        return 1;
    }

    printf("Supported frame sizes:\n");
    for (int i = 0; i < fs_enum.numframes; ++i) {
        printf("  %d x %d\n", fs_enum.discrete.width, fs_enum.discrete.height);
    }

    struct v4l2_frmivalenum iv_enum;
    iv_enum.pixel_format = V4L2_PIX_FMT_SBGGR8;
    iv_enum.type = V4L2_FRMINF_TYPE_DISCRETE;
    iv_enum.stepwise.min = 1;
    iv_enum.stepwise.max = 100;
    iv_enum.stepwise.step = 1;

    struct v4l2_control focus_ctrl;
    focus_ctrl.id = V4L2_CID_FOCUS_AUTO;

    ret = ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &iv_enum);
    if (ret < 0) {
        fprintf(stderr, "Failed to enumerate frame intervals\n");
        close(fd);
        return 1;
    }

    printf("\nSupported frame rates:\n");
    for (int i = iv_enum.stepwise.min; i <= iv_enum.stepwise.max; ++i) {
        printf("  %d fps\n", i);
    }

    ret = ioctl(fd, VIDIOC_QUERYCTRL, &focus_ctrl);
    if (ret < 0) {
        fprintf(stderr, "Failed to query focus control\n");
        close(fd);
        return 1;
    }

    if (focus_ctrl.flags & V4L2_CTRL_FLAG_SLIDER) {
        printf("\nAutofocus is supported.\n");
    } else {
        printf("\nAutofocus is not supported.\n");
    }

out:
    close(fd);
    return ret;
}

