#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

#define PWM_FREQ 50
#define PWM_INCREMENT 10
#define PWM_DELAY 50
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

gpio_init();
gpio_set_mode(PAN_SERVO_PIN, GPIO_OUTPUT);
gpio_set_mode(TILT_SERVO_PIN, GPIO_OUTPUT);
gpio_set_mode(UP_BUTTON, GPIO_INPUT);
gpio_set_pull(UP_BUTTON, GPIO_PUD_UP);
gpio_set_mode(DOWN_BUTTON, GPIO_INPUT);
gpio_set_pull(DOWN_BUTTON, GPIO_PUD_UP);
gpio_set_mode(LEFT_BUTTON, GPIO_INPUT);
gpio_set_pull(LEFT_BUTTON, GPIO_PUD_UP);
gpio_set_mode(RIGHT_BUTTON, GPIO_INPUT);
gpio_set_pull(RIGHT_BUTTON, GPIO_PUD_UP);

gpio_pwm_setup(PAN_SERVO_PIN, 0, PWM_FREQ);
gpio_pwm_setup(TILT_SERVO_PIN, 0, PWM_FREQ);

int pan_pulse_width = CENTER_PULSE_WIDTH;
int tilt_pulse_width = CENTER_PULSE_WIDTH;

void servo_update(int pin, int pulse_width) {
    pulse_width = constrain(pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
    gpio_pwm_set(pin, pulse_width);
}

void button_callback(gpio_signal_info_t *info) {
    if (info->value == 0) {
        switch (info->pin) {
            case UP_BUTTON:
                pan_pulse_width = constrain(pan_pulse_width + PWM_INCREMENT, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
                break;
            case DOWN_BUTTON:
                pan_pulse_width = constrain(pan_pulse_width - PWM_INCREMENT, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
                break;
            case LEFT_BUTTON:
                tilt_pulse_width = constrain(tilt_pulse_width + PWM_INCREMENT, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
                break;
            case RIGHT_BUTTON:
                tilt_pulse_width = constrain(tilt_pulse_width - PWM_INCREMENT, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
                break;
        }
    }
}

void signal_handler(int signum) {
    gpio_stop_pwm(PAN_SERVO_PIN);
    gpio_stop_pwm(TILT_SERVO_PIN);
    gpio_free();
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    printf("Starting pan-tilt servo control with the following pin assignments:\n");
    printf("Pan servo: GPIO%d\n", PAN_SERVO_PIN);
    printf("Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("Buttons: UP - GPIO%d, DOWN - GPIO%d, LEFT - GPIO%d, RIGHT - GPIO%d\n", UP_BUTTON, DOWN_BUTTON, LEFT_BUTTON, RIGHT_BUTTON);

    gpio_set_callback(UP_BUTTON, GPIO_FALLING_EDGE, button_callback);
    gpio_set_callback(DOWN_BUTTON, GPIO_FALLING_EDGE, button_callback);
    gpio_set_callback(LEFT_BUTTON, GPIO_FALLING_EDGE, button_callback);
    gpio_set_callback(RIGHT_BUTTON, GPIO_FALLING_EDGE, button_callback);

    while (true) {
        servo_update(PAN_SERVO_PIN, pan_pulse_width);
        servo_update(TILT_SERVO_PIN, tilt_pulse_width);
        usleep(PWM_DELAY * 1000);
    }

    gpio_free();
    return 0;
}

