    gpio_set_callback(LEFT_BUTTON, GPIO_FALLING_EDGE, button_callback);
    gpio_set_callback(RIGHT_BUTTON, GPIO_FALLING_EDGE, button_callback);

    while (true) {
        servo_update(PAN_SERVO_PIN, pan_pulse_width);
        servo_update(TILT_SERVO_PIN, tilt_pulse_width);
        usleep(PWM_DELAY * 1000);
    }

    gpio_free();
    return 0;
