#include <time.h>
#include <gpiod.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_TIME_MS 2000
#define IMAGE_QUALITY 85

static volatile sig_atomic_t sigint_received = 0;

static void signal_handler(int signum) {
    sigint_received = signum;
}

static int motion_detected = 0;
static time_t last_motion_time = 0;

static GPioDevice *pir_dev;
static CURL *curl;
static struct curl_slist *headers = NULL;

static char *upload_url;

static void cleanup(int signum) {
    if (sigint_received == SIGINT || sigint_received == SIGTERM) {
        gpiod_uninit();
        curl_multi_cleanup(curl);
        curl_easy_cleanup(curl);
        exit(0);
    }
}

static void init_gpio() {
    int ret;

    ret = gpiod_in_setup(&pir_dev, PIR_GPIO, GPIOD_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", PIR_GPIO);
        exit(EXIT_FAILURE);
    }

    gpiod_add_watch(pir_dev, PIR_GPIO, GPIOD_EVENT_RISING, cleanup);
}

static void init_curl() {
    curl = curl_easy_init();
    if (curl) {
        headers = curl_slist_append(NULL, "Content-Type: image/jpeg");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
    }
}

static void post_image(const char *filename) {
    struct curl_httppost *post = NULL;
    struct curl_httppost *last = NULL;
    char *filename_str = strdup(filename);
    char *timestamp_str = strdup(ctime_r(&last_motion_time, NULL));

    curl_easy_setopt(curl, CURLOPT_URL, upload_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);

    post = curl_formadd(post,
                       curl_formadd_array(post,
                                          curl_formadd_simple(post, "image", filename_str),
                                          curl_formadd_simple(post, "timestamp", timestamp_str),
                                          curl_formadd_simple(post, "motion", "true"),
                                          curl_formadd_simple(post, "gpio", "17"),
                                          last));
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        curl_formfree(post);
        free(filename_str);
        free(timestamp_str);
        return;
    }

    curl_easy_perform(curl);
    fclose(file);
    curl_formfree(post);
    free(filename_str);
    free(timestamp_str);
}

static void poll_loop() {
    struct timespec timeout;
    clock_gettime(CLOCK_MONOTONIC, &timeout);
    timeout.tv_sec += POLL_INTERVAL_MS / 1000;

    while (!sigint_received) {
        int event_count;
        gpiod_event_wait(pir_dev, PIR_GPIO, &timeout);

        event_count = gpiod_event_get_count(pir_dev);
        if (event_count > 0) {
            if (time(NULL) - last_motion_time > DEBOUNCE_TIME_MS / 1000) {
                last_motion_time = time(NULL);
                motion_detected = 1;

                char filename[256];
                snprintf(filename, sizeof(filename), "motion_captures/motion_%ld.jpg", (long)time(NULL));

                raspicam_capture_image(filename, IMAGE_QUALITY);
                post_image(filename);
            }
        }

        timeout.tv_sec = 0;
        timeout.tv_nsec = 0;
        gpiod_event_wait(pir_dev, PIR_GPIO, &timeout);
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    upload_url = argv[1];
    upload_url = strcat(upload_url, ":");
    upload_url = strcat(upload_url, argv[2]);

    init_gpio();
    init_curl();

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod\n");
        exit(EXIT_FAILURE);
    }

    pir_dev = gpiod_in_get_device_by_name("GPIO17");
    if (!pir_dev) {
        fprintf(stderr, "Failed to get GPIO17 device\n");
        exit(EXIT_FAILURE);
    }

    atexit(gpiod_uninit);

    poll_loop();

    return 0;
}

