#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <unistd.h>

#define DEBOUNCE_TIMEOUT_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define CAPTURE_CMD "raspistill -o " IMAGE_DIR "/%s -w 640 -h 480 -q 85 -t 2000 -nopreview"

static int gpio_chip;
static int gpio_line;
static struct gpiod_chip_line line_config;
static char filename[32];

void log_message(const char *message) {
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp != NULL) {
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fp, "[%s] %s\n", timestamp, message);
        fclose(log_fp);
    }
}

void create_filename(const char *format, ...) {
    struct tm *tm_info;
    time_t current_time;
    char buffer[80];

    tm_info = localtime(&current_time);
    strftime(buffer, sizeof(buffer), format, tm_info);
    strncpy(filename, buffer, sizeof(filename));
}

int main(int argc, char *argv[]) {
    int ret;
    int fd;

    gpio_chip = gpiod_chip_open(&ret, "GPIO17");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return ret;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, "GPIO17");
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    line_config = gpiod_line_from_number(gpio_line, "input");
    if (!line_config) {
        fprintf(stderr, "Failed to get line configuration\n");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    gpiod_line_set_pull_up_down(line_config, GPIO_PUD_OFF);
    gpiod_line_set_direction(line_config, GPIO_IN);

    ret = gpiod_line_start_capture(line_config, DEBOUNCE_TIMEOUT_MS * 1000, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to start capture\n");
        gpiod_line_stop_capture(line_config);
        gpiod_chip_close(gpio_chip);
        return ret;
    }

    while (1) {
        ret = gpiod_line_wait_for_edge(line_config, -1);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for edge\n");
            break;
        }

        create_filename("%s_%s_%03d.jpg",
            ctime(localtime(NULL)),
            __func__,
            rand() % 1000);

        fd = execle("/usr/bin/raspistill", "raspistill", "-o", IMAGE_DIR "/" filename, "-w", "640", "-h", "480", "-q", "85", "-t", "2000", "-nopreview", (char *)NULL);
        if (fd < 0) {
            log_message("Failed to execute raspistill command");
        }

        gpiod_line_stop_capture(line_config);
    }

    gpiod_line_stop_capture(line_config);
    gpiod_chip_close(gpio_chip);

    return 0;
}

