#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <gpiod.h>

#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query video device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        struct v4l2_fmtdesc fmt;
        struct v4l2_cropcap crop;
        struct v4l2_crop crop_set;
        struct v4l2_fract res;
        struct v4l2_requestbuffers rb;
        struct v4l2_buffer buf;
        int mem_fd;
        void *ptr;

        memset(&fmt, 0, sizeof(fmt));
        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.pixel_format = V4L2_PIX_FMT_YUYV;

        if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == -1) {
            perror("Failed to enumerate formats");
            close(fd);
            return EXIT_FAILURE;
        }

        memset(&crop, 0, sizeof(crop));
        crop.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        crop.c.width = WIDTH;
        crop.c.height = HEIGHT;

        if (ioctl(fd, VIDIOC_CROPCAP, &crop) == -1) {
            perror("Failed to query crop capabilities");
            close(fd);
            return EXIT_FAILURE;
        }

        memset(&crop_set, 0, sizeof(crop_set));
        crop_set.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        crop_set.c.top_left_hpos = crop_set.c.top_left_vpos = 0;
        crop_set.c.width = CROP_WIDTH;
        crop_set.c.height = CROP_HEIGHT;

        if (ioctl(fd, VIDIOC_S_CROP, &crop_set) == -1) {
            perror("Failed to set crop area");
            close(fd);
            return EXIT_FAILURE;
        }

        memset(&rb, 0, sizeof(rb));
        rb.count = 1;
        rb.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        rb.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_REQBUFS, &rb) == -1) {
            perror("Failed to request buffers");
            close(fd);
            return EXIT_FAILURE;
        }

        mem_fd = mmap(NULL, rb.count * rb.memory_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (mem_fd == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        ptr = mem_fd;

        fdset fs;
        FD_ZERO(&fs);
        FD_SET(fd, &fs);

        struct timeval tv = {2, 0};
        int ret;

        while (1) {
            ret = select(fd + 1, NULL, &fs, NULL, &tv);
            if (ret == -1 && errno != EINTR) {
                perror("select");
                break;
            }
            else if (ret == 0) {
                continue;
            }

            if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
                perror("Failed to dequeue buffer");
                break;
            }

            if (buf.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
                if (buf.memory != V4L2_MEMORY_MMAP || buf.address != (unsigned long)ptr) {
                    fprintf(stderr, "Unexpected buffer\n");
                    break;
                }

                if (buf.bytesused != WIDTH * HEIGHT * 1.5) {
                    fprintf(stderr, "Unexpected buffer size\n");
                    break;
                }

                FILE *fp = fopen("cropped.yuv", "ab");
                if (!fp) {
                    perror("Failed to open file");
                    break;
                }

                for (int y = 0; y < CROP_HEIGHT; y++) {
                    for (int x = 0; x < CROP_WIDTH; x++) {
                        unsigned char *yuv = (unsigned char *)ptr;
                        yuv += y * WIDTH * 1.5 + x * 1.5;

                        fwrite(&yuv[0], 1, 1, fp);
                        fwrite(&yuv[1], 1, 1, fp);
                        fwrite(&yuv[2], 1, 1, fp);
                        fwrite(&yuv[3], 1, 1, fp);
                    }
                }

                fclose(fp);
            }

            if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
                perror("Failed to queue buffer");
                break;
            }
        }

        munmap(mem_fd, rb.memory_size);
        close(fd);
    }
    else {
        fprintf(stderr, "Device does not support video capture\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

