#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define PAN_SERVO_GPIO 17
#define TILT_SERVO_GPIO 18
#define PWM_FREQ 50
#define DEGREE_STEP 5
#define NEUTRAL_ANGLE 90

struct gpiod_chip *chip;
struct gpiod_line *pwm_line;
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

void pwm_callback(const struct gpiod_line *line, uint64_t flags) {
    if (flags & GPIO_EVENT_FALLING_EDGE) {
        update_servo_position(PAN_SERVO_GPIO, pan_angle);
        update_servo_position(TILT_SERVO_GPIO, tilt_angle);
    }
}

void update_servo_position(int gpio, int angle) {
    int duty_cycle = (angle - NEUTRAL_ANGLE) * 10 + 10; // 0-100 duty cycle
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    struct gpiod_pwm_params params = {
        .base.pin = gpio,
        .frequency = PWM_FREQ,
        .duty_cycle = duty_cycle,
    };

    if (gpiod_pwm_enable(&params) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for servo\n");
        exit(1);
    }
}

void handle_arrow_keys(int c) {
    switch (c) {
        case 'a': // Left arrow (pan left)
            pan_angle = (pan_angle > 0) ? pan_angle - DEGREE_STEP : 0;
            break;
        case 'd': // Right arrow (pan right)
            pan_angle = (pan_angle < 180) ? pan_angle + DEGREE_STEP : 180;
            break;
        case 'w': // Up arrow (tilt up)
            tilt_angle = (tilt_angle > 0) ? tilt_angle - DEGREE_STEP : 0;
            break;
        case 's': // Down arrow (tilt down)
            tilt_angle = (tilt_angle < 180) ? tilt_angle + DEGREE_STEP : 180;
            break;
        default:
            return;
    }

    update_servo_position(PAN_SERVO_GPIO, pan_angle);
    update_servo_position(TILT_SERVO_GPIO, tilt_angle);
}

void cleanup() {
    if (pwm_line) {
        gpiod_line_disable_callback(pwm_line, NULL);
        gpiod_line_free(pwm_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
        gpiod_chip_free(chip);
    }
}

int main() {
    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PAN_SERVO_GPIO);
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line for pan servo\n");
        cleanup();
        return 1;
    }

    gpiod_line_export(pwm_line, NULL);

    gpiod_line_add_callback(pwm_line, &pwm_callback);

    update_servo_position(PAN_SERVO_GPIO, NEUTRAL_ANGLE);
    update_servo_position(TILT_SERVO_GPIO, NEUTRAL_ANGLE);

    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    char c;
    while (read(STDIN_FILENO, &c, 1) == 1) {
        handle_arrow_keys(c);
        usleep(100000);
    }

    return 0;
}

