#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <wiringPiI2C.h>
#include <adafruit_gfx.h>
#include <adafruit_ssd1306.h>

#define OLED_ADDR 0x3C
#define OLED_WIDTH 128
#define OLED_HEIGHT 64

int main() {
    int cpu_temp_fd, cpu_usage_fd;
    char cpu_temp_str[20];
    char cpu_usage_str[20];
    struct stat cpu_stat;
    int ret;
    int cpu_temp_val;
    double cpu_usage;
    GPIOD *cpu_int_gpio;
    struct gpiod_chip_params params;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Initialize GPIO for SIGINT
    if (gpiod_chip_get_from_number(0, &params, &chip) < 0) {
        fprintf(stderr, "Failed to get GPIO chip\n");
        return 1;
    }

    cpu_int_gpio = gpiod_chip_alloc(chip);
    if (!cpu_int_gpio) {
        fprintf(stderr, "Failed to allocate GPIO\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, "interrupt");
    if (!line) {
        fprintf(stderr, "Failed to get interrupt line\n");
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_add_callback(line, 1, SIGINT, NULL);

    // Initialize OLED
    if (!wiringPiI2CInit()) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpiod_chip_put(chip);
        return 1;
    }

    if (!adafruit_ssd1306_begin(OLED_WIDTH, OLED_HEIGHT, OLED_ADDR)) {
        fprintf(stderr, "Failed to initialize OLED\n");
        gpiod_chip_put(chip);
        return 1;
    }

    // Read CPU temperature
    cpu_temp_fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (cpu_temp_fd < 0) {
        fprintf(stderr, "Failed to open CPU temperature file\n");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = read(cpu_temp_fd, cpu_temp_str, sizeof(cpu_temp_str));
    if (ret < 0) {
        fprintf(stderr, "Failed to read CPU temperature\n");
        close(cpu_temp_fd);
        gpiod_chip_put(chip);
        return 1;
    }

    cpu_temp_str[strcspn(cpu_temp_str, " \n")] = 0;
    cpu_temp_val = atoi(cpu_temp_str);

    // Read CPU usage
    cpu_usage_fd = open("/proc/stat", O_RDONLY);
    if (cpu_usage_fd < 0) {
        fprintf(stderr, "Failed to open CPU usage file\n");
        close(cpu_temp_fd);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = fstat(cpu_usage_fd, &cpu_stat);
    if (ret < 0) {
        fprintf(stderr, "Failed to stat CPU usage file\n");
        close(cpu_temp_fd);
        gpiod_chip_put(chip);
        return 1;
    }

    cpu_usage = (double)(cpu_stat.st_size - (double)lseek(cpu_usage_fd, 0, SEEK_SET)) /
        ((double)cpu_stat.st_size / 100);

    close(cpu_usage_fd);

    sprintf(cpu_usage_str, "%.2f%%", cpu_usage * 100);

    // Clear the display
    adafruit_ssd1306_clearDisplay(0);

    // Render CPU temperature and usage
    adafruit_ssd1306_drawPixel(0, 0);
    adafruit_ssd1306_setTextSize(2);
    adafruit_ssd1306_setTextColor(WHITE);
    adafruit_ssd1306_setCursor(0, 0);
    adafruit_ssd1306_print("CPU Temp:");
    adafruit_ssd1306_setCursor(0, 10);
    adafruit_ssd1306_print(cpu_temp_str);
    adafruit_ssd1306_print("\nCPU Usage:");
    adafruit_ssd1306_setCursor(0, 30);
    adafruit_ssd1306_print(cpu_usage_str);
    adafruit_ssd1306_display();

    // Wait for SIGINT and clean up
    gpiod_wait_for_interrupt(line);
    adafruit_ssd1306_clearDisplay(1);
    close(cpu_temp_fd);
    gpiod_chip_put(chip);
    return 0;
}

