code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpio.h>
#include <wiringPiI2C.h>
#include <stdbool.h>

#define FLOW_SENSOR_GPIO 17
#define LCD_ADDR 0x27

volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void cleanup(void) {
    gpioTerminate();
    wiringPiI2CRelease(0);
}

static void setup_gpio(void) {
    if (gpioInit() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(FLOW_SENSOR_GPIO, GPIO_OUTPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, GPIO_PULL_UP);
}

static void setup_lcd(void) {
    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        exit(EXIT_FAILURE);
    }
}

static void update_lcd(float flow_rate, float total_volume) {
    char buffer[32];
    sprintf(buffer, "Flow Rate: %.2f L/min, Total Volume: %.2f L", flow_rate, total_volume);
    wiringPiI2CWriteReg8(0x27, 0x40, (uint8_t)strlen(buffer));
    for (int i = 0; i < strlen(buffer); i++) {
        wiringPiI2CWriteReg8(0x27, 0x41 + i, buffer[i]);
    }
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_gpio();
    setup_lcd();

    float flow_rate = 0.0;
    float total_volume = 0.0;
    unsigned long last_time = 0;

    while (running) {
        unsigned long current_time = millis();
        if (current_time - last_time >= 1000) {
            last_time = current_time;
            gpioRead(FLOW_SENSOR_GPIO) ? flow_rate = 0.015 : flow_rate = 0.0; // Assuming 0.015 L/pulse
            total_volume += flow_rate;

            printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate * 60, total_volume);
            update_lcd(flow_rate * 60, total_volume);
        }
    }

    cleanup();
    return 0;
}

