    gpiod_token_set_config(token, GPIOD_EVENT_RISING);
    gpiod_token_add_callback(token, &anemometer_callback, NULL);

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end_time) && (end_time.tv_sec - start_time.tv_sec) >= SAMPLE_WINDOW_MS / 1000) {
            wind_speed = (float)pulse_count / ((end_time.tv_sec - start_time.tv_sec) * 1000);
