            update_lcd(wind_speed, wind_direction);
        }

        if (gpiod_poll(token, NULL) & GPIOD_EVENT_RISING) {
            pulse_count++;
        }
    }

    gpiod_unbind_device(chip);
    i2c_close(fd);
    spi_close(file);

    return EXIT_SUCCESS;
