#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <wiringPiI2C.h>

#define SENSOR_GPIO 17
#define LCD_ADDR 0x27
#define BUFFER_SIZE 2

struct timespec start_time, end_time;
int pulse_count = 0;
int last_pulse_count = 0;
int idle_timeout = 0;

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpiod_uninit();
    wiringPiI2CClose(LCD_ADDR);
    exit(0);
}

void setup_gpio(int gpio) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line(chip, gpio, &line);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_export(line, "YF_S201_Pulse");
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO line: %s\n", strerror(errno));
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_direction(line, GPIO_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_free(line);
    gpiod_chip_close(chip);
}

void setup_lcd() {
    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void display_flow_rate(int flow_rate) {
    char buffer[BUFFER_SIZE][20];
    sprintf(buffer[0], "Flow Rate:");
    sprintf(buffer[1], "%.2f L/min", flow_rate);

    for (int i = 0; i < 2; i++) {
        wiringPiI2CWriteReg8(LCD_ADDR, i, (unsigned char)buffer[i][0]);
        for (int j = 1; j < strlen(buffer[i]); j++) {
            wiringPiI2CWriteReg8(LCD_ADDR, i, buffer[i][j]);
        }
        usleep(1000);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_gpio(SENSOR_GPIO);
    setup_lcd();

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        while (1) {
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            if (end_time.tv_sec - start_time.tv_sec >= 1 ||
                (end_time.tv_sec - start_time.tv_sec == 0 && end_time.tv_nsec - start_time.tv_nsec >= 1000000000)) {
                break;
            }
        }

        pulse_count = 0;
        while (gpiod_trigger(SENSOR_GPIO, NULL, GPIO_FALLING_EDGE) == 0) {
            pulse_count++;
        }

        if (pulse_count - last_pulse_count > 0) {
            idle_timeout = 0;
        } else {
            idle_timeout += (end_time.tv_sec - start_time.tv_sec);
            if (idle_timeout > 60) {
                fprintf(stderr, "Warning: No pulses for more than a minute, assuming sensor absent.\n");
                exit(EXIT_SUCCESS);
            }
        }

        last_pulse_count = pulse_count;
        double flow_rate = (double)pulse_count / 10; // Assuming 10ml per pulse
        display_flow_rate(flow_rate);
    }

    gpiod_uninit();
    wiringPiI2CClose(LCD_ADDR);
    return 0;
}

