#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define LED_ROWS_GPIO {17, 18, 27, 22, 23, 24, 25, 4}
#define LED_COLS_GPIO {5, 6, 12, 13, 19, 16, 26, 20}
#define DELAY_US 800

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static void setup_gpio(int *gpio_pins, int size) {
    for (int i = 0; i < size; i++) {
        if (gpio_export(gpio_pins[i]) < 0) {
            fprintf(stderr, "Failed to export GPIO %d\n", gpio_pins[i]);
            exit(EXIT_FAILURE);
        }
    }
}

static void cleanup_gpio(int *gpio_pins, int size) {
    for (int i = 0; i < size; i++) {
        if (gpio_unexport(gpio_pins[i]) < 0) {
            fprintf(stderr, "Failed to unexport GPIO %d\n", gpio_pins[i]);
            exit(EXIT_FAILURE);
        }
    }
}

static void set_led(int row_gpio, int col_gpio, bool state) {
    if (gpio_direction_output(row_gpio) < 0) {
        fprintf(stderr, "Failed to set row GPIO %d as output\n", row_gpio);
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(col_gpio) < 0) {
        fprintf(stderr, "Failed to set column GPIO %d as output\n", col_gpio);
        exit(EXIT_FAILURE);
    }

    gpio_set(row_gpio, state);
    gpio_set(col_gpio, !state);
}

static void render_wave(int *led_cols_gpio, int size, bool (*wave_func)(int)) {
    for (int frame = 0; frame < 8; frame++) {
        for (int col = 0; col < size; col++) {
            int state = wave_func(col);
            for (int row_gpio : LED_ROWS_GPIO) {
                set_led(row_gpio, led_cols_gpio[col], state);
                usleep(DELAY_US);
            }
        }
    }
}

bool left_to_right_wave(int col) {
    return col < 4 ? true : false;
}

bool right_to_left_wave(int col) {
    return col >= 4 ? true : false;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    setup_gpio(LED_ROWS_GPIO, sizeof(LED_ROWS_GPIO) / sizeof(int));
    setup_gpio(LED_COLS_GPIO, sizeof(LED_COLS_GPIO) / sizeof(int));

    int led_cols_gpio[] = LED_COLS_GPIO;

    while (!sigint_received) {
        render_wave(led_cols_gpio, sizeof(LED_COLS_GPIO) / sizeof(int), left_to_right_wave);
        render_wave(led_cols_gpio, sizeof(LED_COLS_GPIO) / sizeof(int), right_to_left_wave);
    }

    cleanup_gpio(LED_ROWS_GPIO, sizeof(LED_ROWS_GPIO) / sizeof(int));
    cleanup_gpio(LED_COLS_GPIO, sizeof(LED_COLS_GPIO) / sizeof(int));

    return 0;
}

