#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define MLX75031_ADDR 0x2D
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define LOG_FILE "depth_log.csv"

struct mlx75031_data {
    int fd;
    int reg_addr;
    uint16_t distance;
};

static int mlx75031_read(struct mlx75031_data *data) {
    char buf[3];
    int ret;

    buf[0] = (data->reg_addr & 0x30) >> 4;
    buf[1] = (data->reg_addr & 0x0F) | 0x40;
    buf[2] = 0;

    ret = write(data->fd, buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Error writing to I2C bus\n");
        data->distance = -1;
        return -1;
    }

    ret = read(data->fd, &data->distance, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C bus\n");
        data->distance = -1;
        return -1;
    }

    return 0;
}

int main() {
    int ret;
    struct mlx75031_data mlx;
    int i2c_fd;
    char header[] = "Timestamp,Distance\n";
    FILE *log_file;
    struct gpiod_chip chip;
    struct gpiod_line *line;

    // Initialize GPIO
    ret = gpiod_chip_open(&chip, "i2c-1");
    if (ret) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return ret;
    }

    line = gpiod_chip_get_line(&chip, "i2c-1", MLX75031_ADDR, "input");
    if (!line) {
        fprintf(stderr, "Failed to get I2C line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_export(line, NULL);
    if (ret) {
        fprintf(stderr, "Failed to export I2C line\n");
        gpiod_chip_close(chip);
        return ret;
    }

    i2c_fd = fileno(gpiod_line_get_file(line));
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to get file descriptor for I2C line\n");
        gpiod_line_unexport(line);
        gpiod_chip_close(chip);
        return -1;
    }

    mlx.fd = i2c_fd;
    mlx.reg_addr = MLX75031_ADDR << 1; // Register address with read bit set

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_unexport(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Write CSV header if file is newly created
    if (fseek(log_file, 0, SEEK_END) == 0) {
        fputc('\0', log_file);
        fseek(log_file, -strlen(header), SEEK_CUR);
        fputs(header, log_file);
        fputc('\n', log_file);
    }

    while (1) {
        mlx.distance = -1;
        ret = mlx75031_read(&mlx);
        if (ret == 0) {
            // Write timestamped distance value to log file
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            fprintf(log_file, "%s,%d\n", timestamp, mlx.distance);
        }

        usleep(SAMPLE_INTERVAL);
    }

    // Graceful shutdown
    gpiod_line_unexport(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

