#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>
#include <si1145.h>

#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 500

static FILE *log_file = NULL;
static Si1145_t *si1145 = NULL;

void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (si1145 != NULL) {
        si1145_deinit(si1145);
    }
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    if (si1145_init(&si1145, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        si1145_deinit(si1145);
        return EXIT_FAILURE;
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now));

        int proximity, ambient_light;
        if (si1145_read(si1145, &proximity, &ambient_light) < 0) {
            fprintf(stderr, "Failed to read from Si1145 sensor\n");
            continue;
        }

        fprintf(log_file, "%s: Proximity=%d, AmbientLight=%d\n", timestamp, proximity, ambient_light);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    fclose(log_file);
    si1145_deinit(si1145);
    gpio_exit();

    return EXIT_SUCCESS;
}

