#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_IR_SENSOR 4
#define GPIO_LED 17
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_MS 100

static int ir_sensor_state = 0;
static int led_state = 0;

static int init_gpio(void) {
    struct gpiod_chip *chip;
    int ret;

    ret = gpiod_chip_open_r("/dev/gpiod", &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return ret;
    }

    ret = gpiod_chip_add_request(chip, "IR_Sensor", GPIO_IR_SENSOR,
                                GPIOD_IN | GPIOD_ACTIVE_HIGH, NULL);
    if (ret < 0) {
        gpiod_chip_close(chip);
        return ret;
    }

    ret = gpiod_chip_add_request(chip, "LED", GPIO_LED, GPIOD_OUT, NULL);
    if (ret < 0) {
        gpiod_chip_remove_request(chip, "IR_Sensor");
        gpiod_chip_close(chip);
        return ret;
    }

    return 0;
}

static void cleanup_gpio(void) {
    struct gpiod_chip *chip;

    gpiod_chip_close(chip);
}

static int check_ir_sensor(void) {
    int ir_value;

    ir_value = gpiod_get_value(GPIO_IR_SENSOR);
    if (ir_value < 0) {
        fprintf(stderr, "Failed to read IR sensor value\n");
        return -1;
    }

    ir_sensor_state = ir_value;
    return 0;
}

static void blink_led(void) {
    static struct timespec last_blink_time;
    struct timespec current_time;

    if (ir_sensor_state == 0) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        if (ir_sensor_state != 0 || (current_time.tv_sec - last_blink_time.tv_sec) >= 1 ||
            (current_time.tv_nsec - last_blink_time.tv_nsec) >= POLL_INTERVAL_MS * 1000000) {
            gpiod_set_value(GPIO_LED, 1);
            nanosleep(&last_blink_time, NULL);
            gpiod_set_value(GPIO_LED, 0);
            last_blink_time = current_time;
        }
    }
}

static int log_detection(const char *timestamp) {
    FILE *file = fopen("proximity.log", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    if (fprintf(file, "%s Object detected\n", timestamp) < 0) {
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int main(void) {
    int ret;
    struct timespec poll_interval;

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    poll_interval.tv_sec = 0;
    poll_interval.tv_nsec = POLL_INTERVAL_MS * 1000000;

    while (1) {
        ret = gpiod_poll(NULL, &poll_interval);
        if (ret < 0) {
            fprintf(stderr, "GPIO poll failed\n");
            break;
        }

        check_ir_sensor();
        blink_led();

        if (ir_sensor_state == 0) {
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&poll_interval.tv_sec));
            if (log_detection(timestamp) < 0) {
                break;
            }
        }
    }

    cleanup_gpio();
    return 0;
}

