    struct gpiod_line line;
    struct si1145_data data;
    struct si1145_init init;
    int ret;

    // Register I2C bus
    ret = gpiod_chip_register_bus(&chip, I2C_BUS);
    if (ret < 0) {
        fprintf(stderr, "Failed to register I2C bus\n");
        return ret;
    }

    // Get I2C line
    ret = gpiod_chip_get_line(&chip, "i2c-" I2C_BUS "-sd[a-z]", &line);
    if (ret < 0) {
        fprintf(stderr, "Failed to get I2C line\n");
        gpiod_chip_unregister(&chip);
        return ret;
    }

    // Open I2C file descriptor
    i2c_fd = gpiod_line_to_fd(&line);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C file descriptor\n");
        gpiod_line_free(&line);
        gpiod_chip_unregister(&chip);
        return i2c_fd;
    }

    // Initialize Si1145 sensor
    si1145_init_default(&init);
    si1145_init(&init, i2c_fd);
    if (si1145_read_part_id(i2c_fd, &data) < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        si1145_cleanup();
        gpiod_line_free(&line);
        gpiod_chip_unregister(&chip);
        return -1;
    }

    // Register SIGINT handler
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        si1145_cleanup();
        gpiod_line_free(&line);
        gpiod_chip_unregister(&chip);
        return -1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        si1145_cleanup();
        gpiod_line_free(&line);
        gpiod_chip_unregister(&chip);
        return -1;
    }

    // Infinite loop
