#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 27
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define TRIG_PULSE_US 10
#define ECHO_TIMEOUT_US 30
#define LOG_INTERVAL_SEC 60

gpio_context *gpio_ctx;
FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpio_deinit(gpio_ctx);
        fclose(log_file);
        exit(0);
    }
}

void setup_gpio() {
    gpio_ctx = gpio_init();
    if (!gpio_ctx) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }

    if (gpio_request_available(gpio_ctx, TRIG_GPIO) < 0) {
        fprintf(stderr, "Failed to request TRIG_GPIO (%d)\n", TRIG_GPIO);
        gpio_deinit(gpio_ctx);
        exit(1);
    }

    if (gpio_request_available(gpio_ctx, ECHO_GPIO) < 0) {
        fprintf(stderr, "Failed to request ECHO_GPIO (%d)\n", ECHO_GPIO);
        gpio_deinit(gpio_ctx);
        exit(1);
    }

    gpio_config(gpio_ctx, TRIG_GPIO, GPIO_OUT);
    gpio_config(gpio_ctx, ECHO_GPIO, GPIO_IN);

    if (gpio_add_edge_detect(gpio_ctx, ECHO_GPIO) < 0) {
        fprintf(stderr, "Failed to add edge detection for ECHO_GPIO\n");
        gpio_deinit(gpio_ctx);
        exit(1);
    }
}

uint32_t measure_distance() {
    gpio_set_value(gpio_ctx, TRIG_GPIO, 1);
    delay_us(TRIG_PULSE_US);
    gpio_set_value(gpio_ctx, TRIG_GPIO, 0);

    uint32_t start_time = gpio_get_timestamp(gpio_ctx, ECHO_GPIO);
    while (gpio_get_value(gpio_ctx, ECHO_GPIO) == 0 && start_time + ECHO_TIMEOUT_US > gpio_get_timestamp(gpio_ctx, ECHO_GPIO)) {
        delay_us(1);
    }

    if (gpio_get_value(gpio_ctx, ECHO_GPIO) == 0) {
        return 0; // Sensor absent
    }

    uint32_t echo_end_time = gpio_get_timestamp(gpio_ctx, ECHO_GPIO);
    uint32_t distance_us = (echo_end_time - start_time) * 1000000 / 343000;

    if (distance_us < 10000 || distance_us > 4000000) {
        return 0; // Out of range
    }

    return distance_us / 29; // cm
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    log_file = fopen("distance_log.txt", "a");

    while (1) {
        uint32_t distance_cm = measure_distance();

        if (distance_cm) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

            fprintf(log_file, "%s, Distance: %u cm\n", timestamp, distance_cm);

            if (distance_cm < 15) {
                fprintf(log_file, "Time to water the plant!\n");
            }
        }

        delay_ms(LOG_INTERVAL_SEC * 1000);
    }

    gpio_deinit(gpio_ctx);
    fclose(log_file);
    return 0;
}

