#include <signal.h>
#include <gpio.h>

#define I2C_BUS 1
#define TRIG_GPIO 27
#define ECHO_GPIO 22
#define SAMPLE_INTERVAL_MS 200
#define TRIG_DELAY_MS 50
#define BUFFER_SIZE 32

static FILE *log_file = NULL;
static gpio *gpio_handle = NULL;

void sigint_handler(int signum) {
    if (log_file) fclose(log_file);
    if (gpio_handle) gpio_free(gpio_handle);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    gpio_handle = gpio_init();
    if (!gpio_handle) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    if (gpio_request(TRIG_GPIO, "user") || gpio_request(ECHO_GPIO, "user")) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        gpio_free(gpio_handle);
        return 1;
    }

    gpio_set_direction(TRIG_GPIO, GPIO_OUT);
    gpio_set_direction(ECHO_GPIO, GPIO_IN);

    if (i2c_open(I2C_BUS) || i2c_init(I2C_BUS)) {
        fprintf(stderr, "Failed to open or initialize I2C bus\n");
        gpio_free(gpio_handle);
        return 1;
    }

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(I2C_BUS);
        gpio_free(gpio_handle);
        return 1;
    }

    char timestamp[BUFFER_SIZE];
    time_t now;
    struct tm *timeinfo;
    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", timeinfo);

    while (1) {
        gpio_write(TRIG_GPIO, 1);
        sleep_ms(TRIG_DELAY_MS);
        gpio_write(TRIG_GPIO, 0);

        uint8_t data[3];
        int r = i2c_rdwr(I2C_BUS, 0x29, &data, 3, NULL, 0);
        if (r < 0) {
            fprintf(stderr, "I2C error: %s\n", i2c_get_error(I2C_BUS));
            continue;
        }

        int duration = data[1];
        int distance_mm = duration * 0.0000343 / 2;

        char message[100];
        snprintf(message, sizeof(message), "%s, %d\n", timestamp, distance_mm);

        fprintf(log_file, "%s", message);
        fprintf(stdout, "%s", message);
    }

    i2c_close(I2C_BUS);
    gpio_free(gpio_handle);
    fclose(log_file);
    return 0;
}

