#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define LOG_FILE "obstacle_log.txt"
#define READ_INTERVAL 100000 // 100 milliseconds

gpio_context ctx;
FILE *log_file;

void sigint_handler(int signum) {
    gpio_uninit(&ctx);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

void setup_gpio() {
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpio_request_available(&ctx, SENSOR1_GPIO) < 0 || gpio_request_available(&ctx, SENSOR2_GPIO) < 0) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        gpio_uninit(&ctx);
        exit(1);
    }

    if (gpio_set_wd(&ctx, SENSOR1_GPIO, GPIO_PUD_UP) < 0 || gpio_set_wd(&ctx, SENSOR2_GPIO, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpio_uninit(&ctx);
        exit(1);
    }

    if (gpio_set_dir(&ctx, SENSOR1_GPIO, GPIO_OUT) < 0 || gpio_set_dir(&ctx, SENSOR2_GPIO, GPIO_IN) < 0) {
        fprintf(stderr, "Failed to set GPIO direction\n");
        gpio_uninit(&ctx);
        exit(1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpio_uninit(&ctx);
        exit(1);
    }
}

bool read_sensor(int sensor_gpio) {
    uint32_t value;
    if (gpio_get_level(&ctx, sensor_gpio, &value) < 0) {
        fprintf(stderr, "Failed to read sensor value\n");
        return false;
    }
    return value != 0;
}

void log_reading(bool sensor1, bool sensor2, const char *timestamp) {
    fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1, sensor2);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    setup_gpio();

    while (true) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        bool sensor1 = read_sensor(SENSOR1_GPIO);
        bool sensor2 = read_sensor(SENSOR2_GPIO);

        log_reading(sensor1, sensor2, timestamp);

        usleep(READ_INTERVAL * 1000);
    }

    gpio_uninit(&ctx);
    fclose(log_file);
    return 0;
}

