#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>

#define LED_GPIO 17
#define I2C_BUS 1
#define DISTANCE_THRESHOLD 20

static struct gpiod_chip *chip;
static struct gpiod_chip_vq *vq;
static struct gpiod_chip_line *led_line;
static int16_t distance;
static FILE *log_file = NULL;

void cleanup() {
    gpiod_chip_put(chip);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void sigint_handler(int signum) {
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

void sigterm_handler(int signum) {
    cleanup();
    exit(0);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup();
        exit(1);
    }

    led_line = gpiod_chip_line_get(chip, "GPIO", LED_GPIO, "out");
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup();
        exit(1);
    }

    if (gpiod_chip_line_set_direction(led_line, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to set LED line direction\n");
        cleanup();
        exit(1);
    }

    if (gpiod_chip_line_request_output_signal(led_line, NULL) < 0) {
        fprintf(stderr, "Failed to request LED line output\n");
        cleanup();
        exit(1);
    }
}

void setup_i2c() {
    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        cleanup();
        exit(1);
    }

    chip = gpiod_chip_open("/dev/i2c-1", O_RDWR);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open I2C chip\n");
        cleanup();
        exit(1);
    }

    vq = gpiod_chip_vq_get(chip, "i2c");
    if (vq == NULL) {
        fprintf(stderr, "Failed to get I2C VQ\n");
        cleanup();
        exit(1);
    }
}

void setup_logging() {
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        exit(1);
    }
}

void read_distance() {
    uint8_t buffer[2];
    int ret;

    ret = wiringPiI2CReadReg16(I2C_BUS, 0x12); // Replace 0x12 with the actual register address of the ICU-20201 sensor
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C sensor\n");
        return;
    }

    distance = (int16_t)(buffer[0] << 8 | buffer[1]);

    if (distance < DISTANCE_THRESHOLD) {
        gpiod_chip_line_set_value(led_line, 1);
    } else {
        gpiod_chip_line_set_value(led_line, 0);
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    fprintf(log_file, "%s, Distance: %d cm\n", timestamp, distance);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    setup_gpio();
    setup_i2c();
    setup_logging();

    while (true) {
        read_distance();
        sleep(0.1);
    }

    cleanup();
    return 0;
}

