#define I2C_BUS 1
#define I2C_ADDR 0x18 // ICU-20201 I2C address
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100

struct timespec poll_interval = {50, 0}; // 50 ms

volatile int running = 1;

// Function prototypes
void signal_handler(int sig);
void read_tof_sensor(int *distance);
void log_reading(int distance);
void cleanup();

int main(int argc, char *argv[]) {
    int distance, threshold = DEFAULT_THRESHOLD;
    gpio_init();
    gpio_set_direction(LED_GPIO, GPIO_OUTPUT);
    gpio_set_value(LED_GPIO, 0);

    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        read_tof_sensor(&distance);
        log_reading(distance);

        if (distance < threshold) {
            gpio_set_value(LED_GPIO, 1);
        } else {
            gpio_set_value(LED_GPIO, 0);
        }

        usleep(50000); // Sleep for 50 ms
    }

    cleanup();
    return 0;
}

void signal_handler(int sig) {
    running = 0;
}

void read_tof_sensor(int *distance) {
    int i2c_fd = gpio_get_i2c_fd(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to get I2C file descriptor.\n");
        return;
    }

    struct i2c_rdwr_ioctl_data rdwr_data;
    rdwr_data.u8 = &distance;
    rdwr_data.u8_len = sizeof(*distance);

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr_data) < 0) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return;
    }

    // Verify WHO_AM_I register
    if (distance & 0xFF00) {
        fprintf(stderr, "Error: Sensor not detected or WHO_AM_I register mismatch.\n");
        return;
    }
}

