    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return;
    }

    fprintf(log_file, "%s: Distance = %d mm\n", timestamp, distance);
    fclose(log_file);
}

void cleanup() {
    gpio_set_value(LED_GPIO, 0);
    gpio_put();
    gpio_free();
}

