#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SENSOR_ADDR 0x22
#define HEADER 0x42
#define SAMPLE_COUNT 10
#define CYCLE_DELAY 100000 // 100 ms in microseconds
#define MIN_DISTANCE 1000 // 1000 mm

int i2c_fd = -1;
char filename[] = "intrusion_log.txt";
FILE *log_file = NULL;

void sigint_handler(const struct gpiod_chip *chip, uint32_t flags,
        uint32_t *rval) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

int initialize_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void send_command_and_read_response(uint8_t *command, uint8_t *response) {
    write(i2c_fd, command, 4);

    // Wait at least 10 ms
    usleep(CYCLE_DELAY);

    if (read(i2c_fd, response, 15) != 15) {
        fprintf(stderr, "Failed to read response from sensor\n");
        return;
    }

    if (response[0] != HEADER) {
        fprintf(stderr, "Invalid header from sensor\n");
        return;
    }
}

uint16_t extract_distance(uint8_t *response) {
    return (response[1] << 8) | response[2];
}

int main() {
    struct gpiod_chip chip;
    gpiod_chip_init(&chip, "GPIO0");
    chip.event_type = GPIO_EVENT_TYPE_INTR;
    chip.handler = sigint_handler;
    gpiod_add_override(&chip);

    if (initialize_i2c() < 0) {
        return -1;
    }

    log_file = fopen("intrusion_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return -1;
    }

    while (1) {
        uint8_t command[4] = {0x01, 0x00, 0x00, 0x00};
        uint8_t response[15];
        int total_distance = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            send_command_and_read_response(command, response);
            total_distance += extract_distance(response + 1);
        }

        double average_distance = (double)total_distance / SAMPLE_COUNT;
        if (average_distance < MIN_DISTANCE) {
            fprintf(log_file, "%lu\t%d\n", time(NULL), (int)average_distance);
        }

        fflush(log_file);
        sleep(CYCLE_DELAY / 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_put(&chip);

    return 0;
}

