#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/i2c_amd.h>

#define VL53L0X_ADDR 0x29
#define MODEL_ID_REG 0xFE80

struct i2c_dev i2c;
struct gpiod_chip chip;

int main(int argc, char *argv[])
{
    int ret;
    struct timespec ts;
    struct timespec ts_poll;

    // Initialize I2C bus
    ret = i2c_open(&i2c, "i2c-1");
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Verify VL53L0X sensor presence
    uint8_t model_id;
    ret = i2c_rdwr(&i2c, MODEL_ID_REG, &model_id, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        i2c_close(&i2c);
        return 1;
    }

    if (model_id != 0x53) {
        fprintf(stderr, "Invalid model ID: 0x%02X\n", model_id);
        i2c_close(&i2c);
        return 1;
    }

    // Initialize GPIO for interrupt
    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        i2c_close(&i2c);
        return 1;
    }

    // Configure GPIO for interrupt (assuming VL53L0X uses GPIO0)
    ret = gpiod_chip_add_line(&chip, "GPIO0", NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to add GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(&chip);
        i2c_close(&i2c);
        return 1;
    }

    gpiod_chip_set_value(&chip, "GPIO0", 1);

    // Initialize time structures
    clock_gettime(CLOCK_REALTIME, &ts);
    ts_poll.tv_sec = 0;
    ts_poll.tv_nsec = 100 * 1000 * 1000;

    while (1) {
        // Poll RESULT_INTERRUPT_STATUS
        ret = i2c_rdwr(&i2c, 0x80, NULL, 0, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }

        // Get distance measurement
        uint16_t range;
        ret = i2c_rdwr(&i2c, 0x10, &range, 2);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }

        // Print distance
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        printf("%s Distance: %u mm\n", time_str, range);

        // Sleep for 500 ms
        nanosleep(&ts_poll, NULL);
    }

    // Handle SIGINT and SIGTERM
    gpiod_chip_close(&chip);
    i2c_close(&i2c);

    return 0;
}

