        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        i2c_close(&i2c);
        return 1;
    }

    // Configure GPIO for interrupt (assuming VL53L0X uses GPIO0)
    ret = gpiod_chip_add_line(&chip, "GPIO0", NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to add GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(&chip);
        i2c_close(&i2c);
        return 1;
    }

    gpiod_chip_set_value(&chip, "GPIO0", 1);

    // Initialize time structures
    clock_gettime(CLOCK_REALTIME, &ts);
    ts_poll.tv_sec = 0;
    ts_poll.tv_nsec = 100 * 1000 * 1000;

    while (1) {
        // Poll RESULT_INTERRUPT_STATUS
        ret = i2c_rdwr(&i2c, 0x80, NULL, 0, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }

        // Get distance measurement
        uint16_t range;
        ret = i2c_rdwr(&i2c, 0x10, &range, 2);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            continue;
        }

        // Print distance
        char time_str[32];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        printf("%s Distance: %u mm\n", time_str, range);

        // Sleep for 500 ms
        nanosleep(&ts_poll, NULL);
    }

    // Handle SIGINT and SIGTERM
    gpiod_chip_close(&chip);
    i2c_close(&i2c);

    return 0;
}
