int i2c_fd = -1;

static int mlx75030_read_distance(int fd) {
    uint8_t reg_addr = READ_DISTANCE_REG;
    uint16_t distance;

    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error: Failed to write register address\n");
        return -1;
    }

    if (read(fd, &distance, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance value\n");
        return -1;
    }

    return distance;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip chip;
    struct gpiod_line line;
    struct gpiod_chip_data chip_data;
    int ret;

    ret = gpiod_chip_register_parse(&chip, "GPIO0", NULL);
    if (ret) {
        fprintf(stderr, "Error: Failed to register GPIO chip\n");
        return 1;
    }

    ret = gpiod_chip_get_lines(&chip, &line, 1, NULL);
    if (ret) {
        fprintf(stderr, "Error: Failed to get GPIO line\n");
        return 1;
    }

    ret = gpiod_chip_enable_line(&chip, &line, 1);
    if (ret) {
        fprintf(stderr, "Error: Failed to enable GPIO line\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address\n");
        close(i2c_fd);
        return 1;
    }

    if (mlx75030_read_distance(i2c_fd) < 0) {
        fprintf(stderr, "Error: MLX75030 sensor not detected\n");
        close(i2c_fd);
        return 1;
