    while (1) {
        uint16_t distance = mlx75030_read_distance(i2c_fd);
        if (distance >= 0) {
            printf("Distance: %u mm\n", distance);
        }

        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    gpiod_chip_disable_line(&chip, &line, 1);
    gpiod_chip_put(&chip);

    return 0;
}

