#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>

#define OPT3101_ADDR 0x44
#define LOG_INTERVAL 500000 // 500 ms in microseconds

struct gpiod_chip *chip;
struct gpiod_line *i2c_sd_a;
struct gpiod_line *i2c_sd_d;

void sigint_handler(int signum) {
    gpiod_chip_unclaim(chip);
    printf("SIGINT received, cleaning up and exiting.\n");
    exit(0);
}

int main() {
    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        perror("Failed to open gpiod chip");
        return EXIT_FAILURE;
    }

    int ret = gpiod_chip_claim_expanding(chip, 2, NULL, &i2c_sd_a, &i2c_sd_d);
    if (ret) {
        fprintf(stderr, "Failed to claim I2C lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_get_direction(i2c_sd_a) != GPIO_DIR_OUT ||
        gpiod_line_get_direction(i2c_sd_d) != GPIO_DIR_OUT) {
        fprintf(stderr, "I2C lines not configured as outputs\n");
        gpiod_chip_release(chip, 2, NULL);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_export(i2c_sd_a, "I2C-SDA");
    gpiod_line_export(i2c_sd_d, "I2C-SDA");

    signal(SIGINT, sigint_handler);

    while (1) {
        uint8_t buf[12];
        uint16_t distance, ambient_light;
        uint8_t error_flags;

        ret = gpiod_line_write(i2c_sd_a, 0);
        if (ret) {
            fprintf(stderr, "Failed to initiate I2C transfer\n");
            sleep(1);
            continue;
        }

        ret = gpiod_line_write(i2c_sd_d, 0);
        if (ret) {
            fprintf(stderr, "Failed to initiate I2C transfer\n");
            sleep(1);
            continue;
        }

        usleep(LOG_INTERVAL);

        ret = i2c_read(OPT3101_ADDR, buf, 12);
        if (ret < 0) {
            fprintf(stderr, "I2C read error\n");
            sleep(1);
            continue;
        }

        distance = (buf[1] << 8) | buf[2];
        ambient_light = (buf[3] << 8) | buf[4];
        error_flags = (buf[5] << 8) | buf[6];

        printf("Distance: %d, Ambient Light: %d, Error Flags: %d\n", distance, ambient_light, error_flags);
    }

    gpiod_line_unexport(i2c_sd_a);
    gpiod_line_unexport(i2c_sd_d);
    gpiod_chip_release(chip, 2, NULL);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

