#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_RANGE 200 /* ms */
#define MIN_RANGE 0 /* µs */
#define TIMEOUT 200 /* ms */
#define TRIG_PULSE_WIDTH 10 /* µs */

gpio_init();
gpio_set_mode(TRIG_PIN, GPIO_OUTPUT);
gpio_set_mode(ECHO_PIN, GPIO_INPUT);
gpio_pull_up(ECHO_PIN);

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static int read_distance(uint32_t *pulse_start, uint32_t *pulse_end) {
    gpio_set_value(TRIG_PIN, 1);
    delay_us(TRIG_PULSE_WIDTH);
    gpio_set_value(TRIG_PIN, 0);

    uint32_t start_time = gpio_get_value_us(ECHO_PIN);
    uint32_t end_time;

    while ((end_time = gpio_get_value_us(ECHO_PIN)) == 0 && start_time + TIMEOUT > gpio_get_value_us(ECHO_PIN)) {}

    if (end_time == 0 || end_time - start_time <= MIN_RANGE || end_time - start_time >= MAX_RANGE) {
        return -1; // Invalid measurement
    }

    *pulse_start = start_time;
    *pulse_end = end_time;
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (!sigint_received) {
        uint32_t pulse_start, pulse_end;
        if (read_distance(&pulse_start, &pulse_end) < 0) {
            fprintf(stderr, "Invalid measurement\n");
            continue;
        }

        double distance_cm = (pulse_end - pulse_start) / 29.0; // 34300 cm/s (speed of sound) / 1000

        printf("Distance: %.2f cm\n", distance_cm);
        fflush(stdout);

        delay_ms(1000);
    }

    gpio_call(TRIG_PIN, 0);
    gpio_call(ECHO_PIN, 0);
    gpio_cleanup();

    return 0;
}

