#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"

static volatile sig_atomic_t sigint_received = 0;
static volatile sig_atomic_t sigterm_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static void sigterm_handler(int signum) {
    sigterm_received = 1;
}

static int setup_gpio(void) {
    int ret;

    ret = gpioInitialize();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return ret;
    }

    ret = gpioSetMode(SENSOR_PIN, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set sensor GPIO mode\n");
        gpioTerminate();
        return ret;
    }

    ret = gpioSetMode(BUZZER_PIN, GPIO_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set buzzer GPIO mode\n");
        gpioTerminate();
        return ret;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

static int read_sensor(bool *sensor_state) {
    int ret;

    *sensor_state = gpioGetLevel(SENSOR_PIN);
    if (*sensor_state == GPIO_HIGH) {
        *sensor_state = GPIO_LOW;
    }

    return gpioGetLevel(BUZZER_PIN);
}

static void log_state(bool state) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    now = time(NULL);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] Obstacle detected: %s\n", timestamp, state ? "true" : "false");
        fclose(log_file);
    }
}

int main(void) {
    bool sensor_state = GPIO_HIGH;
    bool previous_state = GPIO_HIGH;
    bool buzzer_state = false;
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    ret = setup_gpio();
    if (ret < 0) {
        return ret;
    }

    gpioSetLine(BUZZER_PIN, 0); // Ensure buzzer is off initially

    while (1) {
        if (sigint_received || sigterm_received) {
            break;
        }

        ret = read_sensor(&sensor_state);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor\n");
            break;
        }

        if (sensor_state != previous_state) {
            buzzer_state = !buzzer_state;
            gpioWrite(BUZZER_PIN, buzzer_state);
            log_state(buzzer_state);
        }

        previous_state = sensor_state;
        usleep(100000);
    }

    cleanup_gpio();
    return 0;
}

