#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <fcntl.h>
#include <unistd.h>

#define SENSOR_ADDR 0x29
#define GPIO_ALERT 17
#define DIST_THRESHOLD 10.0
#define LOG_FILE "distance_log.txt"

struct sensor_data {
    double distance;
    time_t timestamp;
};

static int i2c_fd;
static GPIODev *gpio_dev;
static FILE *log_file;

static ssize_t i2c_read(void *buf, size_t length) {
    return i2c_xfer(i2c_fd, SENSOR_ADDR, I2C_RD, buf, length);
}

static int i2c_write(const void *buf, size_t length) {
    return i2c_xfer(i2c_fd, SENSOR_ADDR, I2C_WR, buf, length);
}

static int init_i2c() {
    int ret;
    struct i2c_board_info *info;

    ret = i2c_get_board_info(&info);
    if (ret) {
        fprintf(stderr, "Failed to get I2C board info: %d\n", ret);
        return ret;
    }

    if (info->bus_num != 1) {
        fprintf(stderr, "Sensor not found on I2C bus 1\n");
        return -ENODEV;
    }

    i2c_fd = open(i2c_get_device_filename(info->bus_num, info->addr), O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -errno;
    }

    return 0;
}

static int init_gpio() {
    int ret;

    ret = gpiod_init();
    if (ret) {
        fprintf(stderr, "Failed to initialize libgpiod: %d\n", ret);
        return ret;
    }

    gpio_dev = gpiod_in_setup(17, "GPIO17", GPIOD_IN);
    if (!gpio_dev) {
        fprintf(stderr, "Failed to setup GPIO17\n");
        return -ENOMEM;
    }

    return 0;
}

static void cleanup_gpio() {
    gpiod_unbind(gpio_dev);
    gpiod_free(gpio_dev);
    gpiod_exit();
}

static void cleanup_i2c() {
    close(i2c_fd);
}

static int log_distance(struct sensor_data *data) {
    char timestamp[20];
    struct tm *time_info;

    time_info = localtime(&data->timestamp);
    if (!time_info) {
        fprintf(stderr, "Failed to get localtime\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
            return -errno;
        }
    }

    if (fprintf(log_file, "%s, %f\n", timestamp, data->distance) < 0) {
        fclose(log_file);
        log_file = NULL;
        return -errno;
    }

    fclose(log_file);
    log_file = NULL;

    return 0;
}

static void assert_alert() {
    gpiod_trigger(gpio_dev, 1);
}

int main() {
    int ret;
    struct sensor_data data;
    int timeout_ms = 100;

    ret = init_i2c();
    if (ret) {
        return ret;
    }

    ret = init_gpio();
    if (ret) {
        cleanup_i2c();
        return ret;
    }

    while (1) {
        ret = i2c_read(&data.distance, sizeof(data.distance));
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %d\n", ret);
            break;
        }

        if (ret != sizeof(data.distance)) {
            fprintf(stderr, "I2C read error: incorrect data length\n");
            break;
        }

        data.timestamp = time(NULL);

        if (data.distance < DIST_THRESHOLD) {
            assert_alert();
        }

        ret = log_distance(&data);
        if (ret) {
            break;
        }

        usleep(timeout_ms * 1000);
    }

    cleanup_gpio();
    cleanup_i2c();

    return 0;
}

