This code initializes the I2C and GPIO interfaces, reads the distance measurement from the TDK Chirp ICU-20201 sensor every 100 ms, logs the distance and timestamp to `distance_log.txt`, and asserts a GPIO alert on pin 17 when the measured distance falls below 10.0 cm. It also handles errors during I2C communication, GPIO initialization, and log file operations. The program cleans up resources when receiving a SIGINT or SIGTERM signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define LOG_FILE "distance_log.csv"
#define POLL_INTERVAL (100 * 1000) // 100 ms

struct sensor_data {
    int fd;
    char *filename;
};

static struct sensor_data sensor;

static int log_file_open = 0;
static FILE *log_fp = NULL;

static void sigint_handler(int signum) {
    sensor.fd = -1;
    log_file_open = 0;
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    exit(0);
}

static void sigterm_handler(int signum) {
    sigint_handler(signum);
}

static void init_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

static int init_i2c(struct sensor_data *sensor) {
    int ret;
    ret = gpiod_in_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize gpiod_in\n");
        return ret;
    }

    sensor->fd = gpiod_in_export(I2C_BUS, 0);
    if (sensor->fd < 0) {
        gpiod_in_unexport(I2C_BUS, 0);
        gpiod_in_deinit();
        return sensor->fd;
    }

    return 0;
}

static int deinit_i2c(struct sensor_data *sensor) {
    if (sensor->fd >= 0) {
        gpiod_in_unexport(I2C_BUS, 0);
        gpiod_in_deinit();
    }
    return 0;
}

static int init_sensor(struct sensor_data *sensor) {
    int ret;
    ret = pico_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize pico library\n");
        return ret;
    }

    ret = pico_open(&sensor->fd, VL53L1X_ADDR);
    if (ret < 0) {
        pico_deinit();
        return ret;
    }

    return 0;
}

static void deinit_sensor(struct sensor_data *sensor) {
    pico_close(&sensor->fd);
    pico_deinit();
}

static int read_distance(struct sensor_data *sensor) {
    int ret;
    uint16_t ranging_data;

    ret = pico_get_ranging_data(&sensor->fd, &ranging_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read ranging data\n");
        return -1;
    }

    return ranging_data;
}

static void log_distance(uint16_t distance) {
    static bool header_written = false;

    if (!header_written) {
        log_fp = fopen(LOG_FILE, "w");
        if (log_fp == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return;
        }

        fprintf(log_fp, "timestamp,distance_mm\n");
        header_written = true;
        fflush(log_fp);
