#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define LED_GPIO 18
#define I2C_BUS 1
#define I2C_ADDR 0x29 // CH201 default I2C address
#define MAX_RETRIES 3
#define DELAY_MS 10

struct chip_data chip;
struct gpio_dev *led_gpio;

static int led_state = 0;
static int i2c_fd = -1;

void sigint_handler(int signum) {
    printf("SIGINT received, cleaning up...\n");
    gpiod_unbind(led_gpio);
    close(i2c_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("SIGTERM received, cleaning up...\n");
    gpiod_unbind(led_gpio);
    close(i2c_fd);
    exit(0);
}

void setup_led() {
    int ret;
    led_gpio = gpiod_in_export(NULL, "led_gpio", LED_GPIO, GPIOD_IN_ACTIVE_LOW);
    if (!led_gpio) {
        perror("Failed to export GPIO");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_add_callback(led_gpio, &chip, NULL);
    if (ret < 0) {
        perror("Failed to add callback");
        exit(EXIT_FAILURE);
    }
    gpiod_set_value(led_gpio, 0); // Initially turn off the LED
}

void cleanup_led() {
    gpiod_unbind(led_gpio);
}

int read_distance(int retries) {
    int ret;
    struct i2c_rdwr_ioctl_data rd_wr;
    struct i2c_msg messages[1];

    if (retries >= MAX_RETRIES)
        return -1;

    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    messages[0].addr = I2C_ADDR;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = (unsigned char *) &ret;

    ret = ioctl(i2c_fd, I2C_RDWR, &rd_wr);
    if (ret < 0) {
        printf("I2C transaction failed\n");
        close(i2c_fd);
        return -1;
    }

    rd_wr.buf = (unsigned char *)&ret;
    rd_wr.len = sizeof(ret);
    rd_wr.flags = 0;

    ret = ioctl(i2c_fd, I2C_RDWR, &rd_wr);
    if (ret < 0) {
        if (retries < MAX_RETRIES) {
            printf("I2C transaction failed, retrying...\n");
            sleep(DELAY_MS / 1000);
            return read_distance(retries + 1);
        } else {
            printf("Max retries reached, failed to read distance\n");
            return -1;
        }
    }

    close(i2c_fd);
    return ret;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    setup_led();

    while (1) {
        int distance = read_distance(0);
        if (distance == -1) {
            printf("Failed to read distance, skipping this iteration\n");
            continue;
        }

        double frequency = 1.0 / (distance * 0.00000291); // Approximate frequency calculation
        printf("Distance: %d, Frequency: %.2f Hz\n", distance, frequency);

        led_state = !led_state;
        gpiod_set_value(led_gpio, led_state);
        sleep(0.1);
    }

    cleanup_led();
    return 0;
}

