int i2c_read_reg(uint8_t reg_addr, uint16_t *data) {
    int ret;
    for (int i = 0; i < RETRY_COUNT; i++) {
        ret = gpio_i2c_read_reg(&gpio, MLX75030_ADDR, reg_addr, data, 2);
        if (ret == 2)
            return 0;
        else if (ret < 0) {
            fprintf(stderr, "I2C read error: %d\n", ret);
            if (i < RETRY_COUNT - 1)
                delay_ms(10);
        }
    }
    return -1;
}

