    gpio = gpio_init();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    gpio_set_output(gpio, 0, 0); // SDA
    gpio_set_output(gpio, 1, 0); // SCL
    gpio_set_pull(gpio, 0, 1);
    gpio_set_pull(gpio, 1, 1);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    FILE *fp = fopen("distance_log.csv", "w");
