#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY 50000 // 50 ms
#define POLL_DELAY 10000 // 10 ms

enum sensor_id { SENSOR_1, SENSOR_2 };
enum event_type { DETECTED, CLEARED };

void log_event(enum sensor_id sensor, enum event_type event) {
    static FILE *log_file = NULL;
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);

    if (!log_file) {
        log_file = fopen("proximity_log.txt", "w");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%s %d %s\n", timestamp, (int)sensor, (event == DETECTED) ? "DETECTED" : "CLEARED");
    fflush(log_file);
}

int main() {
    struct gpio sensor_pins[2];
    gpio_init();
    gpio_set_direction(&sensor_pins[SENSOR_1], SENSOR_1_GPIO, GPIO_OUT);
    gpio_set_direction(&sensor_pins[SENSOR_2], SENSOR_2_GPIO, GPIO_OUT);
    gpio_set_value(&sensor_pins[SENSOR_1], SENSOR_1_GPIO, 0);
    gpio_set_value(&sensor_pins[SENSOR_2], SENSOR_2_GPIO, 0);

    int prev_state_1 = 0, prev_state_2 = 0;
    enum sensor_id sensor;
    enum event_type event;

    signal(SIGINT, [](int) { gpio_shutdown(); });
    signal(SIGTERM, [](int) { gpio_shutdown(); });

    while (true) {
        sensor = (gpio_get_value(&sensor_pins[SENSOR_1]) == 1) ? SENSOR_1 : SENSOR_2;
        int current_state = gpio_get_value(&sensor_pins[sensor - SENSOR_1]);

        if (current_state != prev_state_1) {
            if (current_state == 1 && prev_state_1 == 0) {
                event = DETECTED;
            } else {
                event = CLEARED;
            }
            prev_state_1 = current_state;
            log_event(sensor, event);
        }

        if (current_state != prev_state_2) {
            if (current_state == 1 && prev_state_2 == 0) {
                event = DETECTED;
            } else {
                event = CLEARED;
            }
            prev_state_2 = current_state;
            log_event(sensor + 1, event);
        }

        usleep(POLL_DELAY);
    }

    gpio_shutdown();
    fclose(log_file);
    return 0;
}

