void log_distance(int distance_mm) {
    FILE *fp;
    if (!(fp = fopen(CSV_FILE, "a"))) {
        perror("Failed to open CSV file");
        return;
    }
    time_t now;
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(fp, "%s,%d\n", timestamp, distance_mm);
    fclose(fp);
}

int i2c_write_then_read(int fd, uint8_t reg_addr, uint16_t value) {
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_msg messages[] = {
        { .addr = TDK_CH101_ADDR, .flags = 0, .len = 1, .buf = &reg_addr },
        { .addr = TDK_CH101_ADDR, .flags = I2C_M_RD, .len = 2, .buf = NULL }
    };

    rdwr.fr.addr = fd;
    rdwr.fr.len = sizeof(messages) / 2;
    rdwr.fm.addr = TDK_CH101_ADDR;
    rdwr.fm.len = sizeof(messages) / 2;
    rdwr.data = messages;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        perror("I2C transaction failed");
        return -1;
    }

    return *(uint16_t *)rdwr.fm.buf;
}

