#define MLX75030_ADDR 0x29
#define RETRY_COUNT 3
#define RETRY_DELAY 10000 // 10 ms

struct mlx75030_ctx {
    I2C_CLIENT *client;
    uint8_t reg_addr;
};

static int read_mlx75030(struct mlx75030_ctx *ctx, uint16_t *distance) {
    int ret;
    uint8_t data[3];

    for (int i = 0; i < RETRY_COUNT; ++i) {
        ret = i2c_xfer(ctx->client, &data[0], 1, &data[1], 1, &data[2], 1);
        if (ret >= 0) {
            *distance = (data[1] << 8) | data[2];
            return 0;
        }

        if (i < RETRY_COUNT - 1) {
            msleep(RETRY_DELAY);
        }
    }

    return -1;
}

static void sigint_handler(int signum) {
    printf("SIGINT received, cleaning up...\n");
    i2c_put(ctx->client);
    gpiod_unprepare(dev);
    exit(0);
}

int main() {
    struct mlx75030_ctx ctx;
    int ret;
    uint16_t distance;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    ctx.client = i2c_open_device(MLX75030_ADDR);
    if (!ctx.client) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    ctx.reg_addr = MLX75030_ADDR << 1; // Register address for distance data

    if ((ret = gpiod_in_init()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        i2c_close(ctx.client);
        return 1;
    }

    dev = gpiod_in_export(NULL, "mlx75030_interrupt");
    if (!dev) {
        fprintf(stderr, "Failed to export GPIO for interrupt\n");
        i2c_close(ctx.client);
        gpiod_unprepare(NULL);
        return 1;
    }

    // Configure interrupt GPIO pin here...

    while (1) {
        struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t milliseconds = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    if ((ret = read_mlx75030(&ctx, &distance)) < 0) {
        fprintf(stderr, "Failed to read from MLX75030 after %d retries\n", RETRY_COUNT);
        break;
    }

    printf("Distance: %u mm at %lu ms\n", distance, milliseconds);

    usleep(100000); // Sleep for 100 ms
    }

    i2c_close(ctx.client);
    gpiod_unprepare(dev);
    return 0;
}

