#define VL53L4CX_I2C_ADDR 0x29
#define VL53L4CX_REG_INTERRUPT_STATUS 0x01
#define VL53L4CX_REG_PART_ID 0x00

struct vl53l4cx_i2c_handle {
    gpioi2c_context i2c;
    int fd;
};

static struct vl53l4cx_i2c_handle i2c_handle;

static int vl53l4cx_read_reg(struct vl53l4cx_i2c_handle *handle, uint8_t reg_addr, uint8_t *data, size_t len) {
    int ret;
    ret = gpioi2c_xfer(handle->fd, VL53L4CX_I2C_ADDR << 1, &reg_addr, 1, data, len);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(ret));
        return ret;
    }
    return 0;
}

static uint8_t vl53l4cx_get_interrupt_status(struct vl53l4cx_i2c_handle *handle) {
    uint8_t data;
    if (vl53l4cx_read_reg(handle, VL53L4CX_REG_INTERRUPT_STATUS, &data, 1) != 0) {
        return 0;
    }
    return data & 0x01;
}

static uint8_t vl53l4cx_get_part_id(struct vl53l4cx_i2c_handle *handle) {
    uint8_t data;
    if (vl53l4cx_read_reg(handle, VL53L4CX_REG_PART_ID, &data, 1) != 0) {
        return 0;
    }
    return data;
}

static void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpioi2c_close(&i2c_handle.i2c);
    exit(0);
}

static void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up...\n");
    gpioi2c_close(&i2c_handle.i2c);
    exit(0);
}

int main() {
    int ret;
    struct timespec ts;

    i2c_handle.fd = gpioi2c_open(VL53L4CX_I2C_ADDR, 0);
    if (i2c_handle.fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR || signal(SIGTERM, sigterm_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install signal handlers\n");
        goto cleanup;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint8_t interrupt_status = vl53l4cx_get_interrupt_status(&i2c_handle);
        if (interrupt_status) {
            uint8_t part_id = vl53l4cx_get_part_id(&i2c_handle);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            printf("%s.%06llu, Distance: %u mm\n", timestamp, (unsigned long long) (ts.tv_nsec / 1000), part_id);
        }
        usleep(500000);
    }

cleanup:
    if (i2c_handle.fd >= 0) {
        gpioi2c_close(&i2c_handle.i2c);
    }
    return 0;
}

