#include <i2c/i2c.h>
#include <vl53l1x.h>

#define DISTANCE_THRESHOLD 100
#define READING_INTERVAL 500000 // 500 ms in µs

static struct gpiod_chip *buzzer_chip;
static struct gpiod_chip_vq *buzzer_vq;
static struct gpiod_line *buzzer_line;

static struct i2c_dev_id dev_id = {
    .vendor = 0x53,
    .device = 0xa130,
};

static struct i2c_client *i2c_client;

static void buzzer_callback(const struct gpiod_line *line, uint32_t events) {
    if (events & (1 << GPIO_EVENT_FALLING)) {
        // Activate buzzer
    }
}

static int init_buzzer(void) {
    int ret;

    ret = gpiod_chip_open(&buzzer_chip, "GPIO22");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO22\n");
        return ret;
    }

    ret = gpiod_chip_add_vq(buzzer_chip, &buzzer_vq, GPIOD_LINE_INACTIVE, buzzer_callback);
    if (ret < 0) {
        fprintf(stderr, "Failed to add virtual queue for GPIO22\n");
        gpiod_chip_close(buzzer_chip);
        return ret;
    }

    ret = gpiod_vq_export(buzzer_vq, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO22\n");
        gpiod_chip_remove_vq(buzzer_chip, buzzer_vq);
        return ret;
    }

    buzzer_line = gpiod_vq_get_line(buzzer_vq);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get line for GPIO22\n");
        gpiod_vq_unexport(buzzer_vq);
        gpiod_chip_remove_vq(buzzer_chip, buzzer_vq);
        gpiod_chip_close(buzzer_chip);
        return ret;
    }

    return 0;
}

static void cleanup_buzzer(void) {
    gpiod_vq_unexport(buzzer_vq);
    gpiod_chip_remove_vq(buzzer_chip, buzzer_vq);
    gpiod_chip_close(buzzer_chip);
}

static int init_i2c(void) {
    int ret;

    ret = i2c_alloc_device(&i2c_client);
    if (ret < 0) {
        fprintf(stderr, "Failed to allocate I2C device\n");
        return ret;
    }

    ret = i2c_set_devid(i2c_client, &dev_id);
    if (ret < 0) {
        fprintf(stderr, "Failed to set device ID\n");
        i2c_free_device(i2c_client);
        return ret;
    }

    ret = i2c_open(i2c_client);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        i2c_free_device(i2c_client);
        return ret;
    }

    return 0;
}

static void cleanup_i2c(void) {
    i2c_close(i2c_client);
    i2c_free_device(i2c_client);
}

static int vl53l1x_init(struct i2c_client *client) {
    // Initialize VL53L1X sensor
    // ...
    return 0;
}

static void vl53l1x_read_distance(struct i2c_client *client) {
    // Read distance from VL53L1X
    // ...

    if (distance < DISTANCE_THRESHOLD) {
        // Activate buzzer
        gpiod_trigger(buzzer_line, 1);
    }
}

static void sigint_handler(int signum) {
    printf("SIGINT received, cleaning up and exiting...\n");
    cleanup_buzzer();
    cleanup_i2c();
    exit(0);
}

int main(int argc, char *argv[]) {
    struct timespec next_reading;
    struct i2c_rdwr_hdr wr_hdr;
    struct i2c_rdwr_data data;
    int ret;

    signal(SIGINT, sigint_handler);

    if (init_buzzer() < 0) {
        fprintf(stderr, "Failed to initialize buzzer\n");
        return 1;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        cleanup_buzzer();
        return 1;
    }

    if (vl53l1x_init(i2c_client) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        cleanup_i2c();
        cleanup_buzzer();
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &next_reading);
    next_reading.tv_sec += READING_INTERVAL / 1000;
    next_reading.tv_nsec = 0;

    while (1) {
        clock_nanosleep(CLOCK_MONOTONIC, 0, &next_reading, NULL);

        ret = i2c_msg_begin(client, 0x29);
        if (ret < 0) {
            fprintf(stderr, "Failed to start I2C transaction\n");
            continue;
        }

        wr_hdr.addr = 0x29;
        wr_hdr.flags = 0;
        wr_hdr.len = 1;
        data.len = 1;
        data.buffer = &ret;

        ret = i2c_transfer(client, &wr_hdr, &data);
        if (ret < 0) {
            fprintf(stderr, "Failed I2C transfer\n");
            continue;
        }

        vl53l1x_read_distance(i2c_client);
    }

    cleanup_buzzer();
    cleanup_i2c();
    return 0;
}

