#define MIN_DISTANCE 2
#define TIMEOUT_MS 50
#define TRIG_PULSE_US 10
#define LOOP_INTERVAL_MS 200

gpio_init();
gpio_set_mode(TRIG_GPIO, GPIO_OUTPUT);
gpio_set_mode(ECHO_GPIO, GPIO_INPUT);
gpio_set_mode(SERVO_GPIO, GPIO_OUTPUT);

if (gpio_failed()) {
    fprintf(stderr, "Failed to initialize GPIO library\n");
    return 1;
}

void sigint_handler(int signum) {
    gpio_stop_output(SERVO_GPIO);
    gpio_free();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

double map_distance_to_angle(double distance) {
    return ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 90 - 90;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    FILE *log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (true) {
        gpio_set_value(TRIG_GPIO, 1);
        usleep(TRIG_PULSE_US);
        gpio_set_value(TRIG_GPIO, 0);

        double start_time = gpio_get_value_cb(ECHO_GPIO, GPIO_FALLING, 0);
        if (start_time < 0) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        double end_time = gpio_get_value_cb(ECHO_GPIO, GPIO_RISING, 0);
        if (end_time < 0) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        double distance = (end_time - start_time) * 17100 / 29;
        if (distance <= 0) {
            fprintf(stderr, "Invalid distance\n");
            continue;
        }

        double angle = map_distance_to_angle(distance);
        gpio_set_value(SERVO_GPIO, (int)angle);

        time_t now = time(NULL);
        fprintf(log_file, "%ld: Distance = %.2f cm, Angle = %.2f degrees\n", now, distance, angle);

        usleep(LOOP_INTERVAL_MS * 1000);
    }

    gpio_stop_output(SERVO_GPIO);
    gpio_free();
    fclose(log_file);
    return 0;
}

