#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <i2c/i2c.h>
#include <i2c/bus.h>

#define DISTANCE_QUEUE_KEY 1234
#define DISTANCE_THRESHOLD 100

struct distance_data {
    uint16_t distance;
};

GPIOD *gpio;
int msg_queue_id;

void sigint_handler(int signum) {
    gpiod_unbind(gpio);
    close(msg_queue_id);
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    gpio = gpiod_new();
    if (!gpio) {
        fprintf(stderr, "Failed to create gpiod instance\n");
        return 1;
    }

    if (gpiod_add_dev_known(gpio, "BCM23")) {
        gpiod_export(gpio, 23);
    } else {
        fprintf(stderr, "Failed to export GPIO23\n");
        return 1;
    }

    if (gpiod_set_value(gpio, 23, 0)) {
        fprintf(stderr, "Failed to set GPIO23 low\n");
        return 1;
    }

    msg_queue_id = msgget(DISTANCE_QUEUE_KEY, 0666 | IPC_CREAT);
    if (msg_queue_id == -1) {
        fprintf(stderr, "Failed to create message queue\n");
        return 1;
    }

    struct i2c_board_info *bi = i2c_get_board_info();
    if (!bi || bi->type != I2C_BOARD_INFO_VL53L1X) {
        fprintf(stderr, "VL53L1X not detected on I2C bus\n");
        return 1;
    }

    int fd = open_i2c(bi->bus);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C bus\i2c_get_board_info\n");
        return 1;
    }

    if (i2c_write_byte_data(fd, bi->addr, VL53L0X_REG_START_RNG_AND_CONT_CFG, 0x00)) {
        fprintf(stderr, "Failed to write to VL53L1X register\n");
        close(fd);
        return 1;
    }

    while (1) {
        struct distance_data data;
        if (i2c_read_word_data(fd, bi->addr, VL53L0X_REG_RANGE_STATUS, &data.distance)) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        if (data.distance < DISTANCE_THRESHOLD) {
            gpiod_set_value(gpio, 23, 1);
        } else {
            gpiod_set_value(gpio, 23, 0);
        }

        if (msgsnd(msg_queue_id, &data, sizeof(data), 0) == -1) {
            fprintf(stderr, "Failed to send message to queue\n");
            break;
        }

        usleep(50000);
    }

    gpiod_unbind(gpio);
    close(msg_queue_id);
    close(fd);
    return 0;
}

