#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define CHECK_INTERVAL 100

static volatile bool buzzer_on = false;
static volatile bool sensor_working = true;

static void signal_handler(int signum) {
    sensor_working = false;
}

static uint32_t last_echo_time = 0;
static uint32_t current_echo_time = 0;
static uint16_t distance_cm = 0;

static void trigger_interrupt_cb(uint32_t pin, uint32_t edge, uint32_t cpu, void *user_data) {
    gpio_set_value(TRIG_PIN, 1);
    gpio_set_value(TRIG_PIN, 0);
}

static void echo_interrupt_cb(uint32_t pin, uint32_t value, uint32_t cpu, void *user_data) {
    current_echo_time = gpio_get_value(ECHO_PIN);

    if (current_echo_time == 0) {
        // Timeout or no echo
        printf("Sensor absent condition (timeout or no echo)\n");
        sensor_working = false;
        return;
    }

    uint32_t elapsed_time = current_echo_time - last_echo_time;
    last_echo_time = current_echo_time;

    // Handle 32-bit tick wraparound
    if (elapsed_time > 0xffffffff) {
        elapsed_time -= 0x100000000;
    }

    distance_cm = (uint16_t)((elapsed_time * 17150) / 29);

    if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
        printf("Invalid reading (out-of-range)\n");
        distance_cm = 0;
    }

    if (distance_cm < 30) {
        buzzer_on = true;
    } else {
        buzzer_on = false;
    }
}

int main() {
    gpioInit();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0 || gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioCleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set pull-up/pull-down for ECHO_PIN\n");
        gpioCleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlert(ECHO_PIN, echo_interrupt_cb, true) < 0) {
        fprintf(stderr, "Failed to register echo interrupt callback\n");
        gpioCleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlert(TRIG_PIN, trigger_interrupt_cb, false) < 0) {
        fprintf(stderr, "Failed to register trigger interrupt callback\n");
        gpioCleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (sensor_working) {
        if (buzzer_on) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        if ((clock() % CHECK_INTERVAL) == 0) {
            printf("Distance: %.2f cm\n", distance_cm);
        }

        usleep(10000);
    }

    gpioCleanup();
    return EXIT_SUCCESS;
}

