#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>
#include <libgpiod.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define SAMPLE_INTERVAL_MS 200
#define TRIG_PULSE_US 10
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define TIMEOUT_US 60000
#define LOG_FILE "distance_log.txt"

typedef struct {
    uint64_t rising_tick;
    uint64_t falling_tick;
} EdgeTimestamp;

static uint64_t get_tick_count(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

static void edge_callback(const gpio_ctx *ctx, uint32_t event_type, uint32_t value, void *user_data) {
    EdgeTimestamp *timestamps = (EdgeTimestamp *)user_data;

    if (event_type & GPIO_EVENT_FALLING_EDGE) {
        timestamps->falling_tick = get_tick_count();
    } else if (event_type & GPIO_EVENT_RISING_EDGE) {
        timestamps->rising_tick = get_tick_count();
    }
}

int main(void) {
    gpio_init();
    gpio_request(TRIG_GPIO, "TRIG");
    gpio_request(ECHO_GPIO, "ECHO");

    gpio_set_direction(TRIG_GPIO, GPIO_DIR_OUT);
    gpio_set_direction(ECHO_GPIO, GPIO_DIR_IN);
    gpio_set_pull(ECHO_GPIO, GPIO_PULL_DOWN);

    gpiod_chip_handle chip;
    int r = gpiod_chip_open(&chip, "gpiochip0");
    if (r < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    gpiod_line_request lines[] = {{.which = GPIO_LINE_INPUT, .pin = ECHO_GPIO, .debounce = 0}};
    r = gpiod_chip_add_request_set(chip, lines, ARRAY_SIZE(lines));
    if (r < 0) {
        fprintf(stderr, "Failed to add request for ECHO line\n");
        goto chip_close;
    }

    EdgeTimestamp timestamps;
    r = gpiod_line_request_set_event(lines, ARRAY_SIZE(lines), &timestamps, edge_callback);
