    }
}

int main() {
    struct gpiod_chip_params params;
    struct gpiod_chip *chip;
    struct gpiod_line *shutdown;
    struct gpiod_line *interrupt;
    struct gpiod_pwm *servo;

    if (gpiod_chip_register_get("i2c-1", &params) < 0) {
        fprintf(stderr, "Failed to get I2C chip\n");
        return 1;
    }

    chip = gpiod_chip_new_from_params(params);
    if (!chip) {
        fprintf(stderr, "Failed to create I2C chip\n");
        return 1;
    }

    if (gpiod_chip_add_line(chip, "shutdown", &shutdown, SHUTDOWN_PIN) < 0 ||
        gpiod_chip_add_line(chip, "interrupt", &interrupt, INTERRUPT_PIN) < 0) {
        fprintf(stderr, "Failed to add lines to chip\n");
        gpiod_chip_free(chip);
        return 1;
    }

    if (gpiod_chip_add_pwm(chip, "servo", &servo, SERVO_PIN, 1000, 500, 2000) < 0) {
        fprintf(stderr, "Failed to add PWM line to chip\n");
        gpiod_chip_free(chip);
        return 1;
    }

    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpiod_chip_free(chip);
        return 1;
    }

    if (wiringPiI2CBeginTransmission(0x2D) < 0) {
        fprintf(stderr, "Failed to begin I2C transmission\n");
        gpiod_chip_free(chip);
        return 1;
    }

    if (wiringPiI2CWriteReg8(0x2D, 0x80, 0x06) < 0) {
        fprintf(stderr, "Failed to write to VL53L1X register\n");
        gpiod_chip_free(chip);
        return 1;
    }

    uint8_t model_id;
    if (wiringPiI2CReadReg8(0x2D, 0x00) < 0) {
        fprintf(stderr, "Failed to read from VL53L1X register\n");
        gpiod_chip_free(chip);
        return 1;
    } else {
        model_id = wiringPiI2CReadReg8(0x2D, 0x00);
        if (model_id != 0x53) {
            fprintf(stderr, "Invalid VL53L1X model ID\n");
            gpiod_chip_free(chip);
            return 1;
        }
    }

    // Continue with servo control and distance measurement logic...

    // Install signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = (void (*)(int))cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read distance, control servo, and log events...
    }

    cleanup();
    gpiod_chip_free(chip);
    return 0;
}

void cleanup() {
    // Release resources here
    servo->free();
    shutdown->deinit();
    interrupt->deinit();
    gpiod_chip_free(chip);
    wiringPiI2CFinish();
}

