#define LOG_FILE "gate_events.log"
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MAX_DISTANCE 200

static struct i2c *bus;
static struct gpiod_chip *gpio_chip;
static struct gpiod_chip_iqr *gpio_iqr;
static VL53L1X_DEV dev;
FILE *log_file;

void sigint_handler(int signum) {
    VL53L1X_stop(&dev);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    exit(0);
}

void init_i2c() {
    bus = i2c_open(I2C_BUS);
    if (!bus) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }
}

void init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiod", "vl53l1x-gpio");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    gpio_iqr = gpiod_chip_get_iqr(gpio_chip, "gate");
    if (!gpio_iqr) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        exit(1);
    }

    gpiod_chip_add_iqr_listener(gpio_chip, gpio_iqr, NULL, NULL);

    if (gpiod_iqr_direction_input(gpio_iqr, 18) < 0 ||
        gpiod_iqr_direction_output(gpio_iqr, 19) < 0) {
        fprintf(stderr, "Failed to set GPIO directions\n");
        exit(1);
    }
}

void init_vl53l1x() {
    if (VL53L1X_init(&dev, VL53L1X_ADDR, bus) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        exit(1);
    }

    VL53L1X_set_timing_budget(&dev, 15);
    VL53L1X_start_ranging(&dev);
}

