            gpiod_iqr_write(gpio_iqr, 19, false);
            log_event("Gate opened");
        } else {
            gpiod_iqr_write(gpio_iqr, 18, false);
            gpiod_iqr_write(gpio_iqr, 19, true);
            log_event("Gate closed");
        }

        sleep(0.5);
    }

    VL53L1X_stop(&dev);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    return 0;
}

