#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <pigio.h>

#define VL53L1X_I2C_ADDR 0x29
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_TRIGGER 24

#define MIN_DISTANCE 100
#define MAX_DISTANCE 300

static pigio_context *gpio;
static int i2c_fd;

void motor_control(int distance);
void distance_measurement_isr();
void cleanup_resources();

int main() {
    int ret;
    gpio = pigio_init();
    if (!gpio) {
        fprintf(stderr, "pigio_init failed\n");
        return 1;
    }

    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "i2c_open failed\n");
        pigio_exit(gpio);
        return 1;
    }

    if (i2c_rdwr_setup(i2c_fd, 0x70, 7, NULL, 0, NULL, 0, 0) < 0) {
        fprintf(stderr, "i2c_rdwr_setup failed\n");
        i2c_close(i2c_fd);
        pigio_exit(gpio);
        return 1;
    }

    signal(SIGINT, cleanup_resources);
    signal(SIGTERM, cleanup_resources);

    pigio_set_mode(gpio, GPIO_TRIGGER, PI_INPUT);
    pigio_set_pull(gpio, GPIO_TRIGGER, PI_PULL_UP);
    pigio_set_edge_detect(gpio, GPIO_TRIGGER, PI_RISING_EDGE);
    pigio_set_callback(gpio, GPIO_TRIGGER, distance_measurement_isr);

    while (1) {
        motor_control(read_distance());
        usleep(1000000);
    }

