static int i2c_fd = -1;
static int gpio_chip = -1;
static int led_pins[4];

void init_gpio() {
    struct gpiod_chip *chip;
    int ret;

    ret = gpiod_chip_open(&gpio_chip, "GPIO");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        goto init_gpio_cleanup;
    }

    chip = gpiod_chip_get(gpio_chip);
    for (int i = 0; i < 4; i++) {
        led_pins[i] = gpiod_chip_get_line(chip, LED_PINS[i]);
        if (led_pins[i] < 0) {
            fprintf(stderr, "Failed to get line for LED pin %d\n", LED_PINS[i]);
            ret = -errno;
            goto init_gpio_cleanup;
        }
        gpiod_line_export(led_pins[i], "user/led");
    }

init_gpio_cleanup:
    return;
}

void cleanup_gpio() {
    struct gpiod_chip *chip;

    chip = gpiod_chip_get(gpio_chip);
    for (int i = 0; i < 4; i++) {
        gpiod_line_unexport(led_pins[i]);
    }
    gpiod_chip_close(gpio_chip);
}

int init_i2c() {
    int ret;
    char filename[] = "/dev/i2c-1";

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void cleanup_i2c() {
    close(i2c_fd);
    i2c_fd = -1;
}

void reset_mpr121() {
    uint8_t cmd = 0x00;

    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to send reset command to MPR121\n");
    }
}

uint8_t read_mpr121(uint8_t reg) {
    uint8_t data;

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write register address to MPR121\n");
        return 0;
    }

    if (read(i2c_fd, &data, 1) != 1) {
        fprintf(stderr, "Failed to read data from MPR121\n");
        return 0;
    }

    return data;
}

void drive_leds(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(led_pins[i], pattern & (1 << i) ? 1 : 0);
    }
}

int main() {
    struct timespec poll_ts;
    clock_gettime(CLOCK_MONOTONIC, &poll_ts);
    poll_ts.tv_sec += POLL_INTERVAL_MS / 1000;
    poll_ts.tv_nsec += (POLL_INTERVAL_MS % 1000) * 1000000;

    init_i2c();
    init_gpio();
    reset_mpr121();

    while (1) {
        uint8_t touch_data = read_mpr121(0x00);

        if (touch_data & 0x01) {
            printf("[%lu] Proximity detected on electrode\n", (unsigned long)timespec_to_msec(&poll_ts));
            drive_leds(touch_data);
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    cleanup_gpio();
    cleanup_i2c();

    return 0;
}

