#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 0.0343
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TRIG_LOW_TIME 5000
#define TRIG_PULSE_TIME 10000
#define ECHO_TIMEOUT 30000

volatile sig_atomic_t sigint_flag = 0;

static int gpio_init(void) {
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return ret;
    }

    ret = gpiod_export(NULL);
    if (ret < 0) {
        gpiod_unexport(NULL);
        return ret;
    }

    return 0;
}

static void gpio_cleanup(void) {
    gpiod_unexport(NULL);
    gpiod_exit();
}

static int gpio_setup(void) {
    struct gi10 gi;
    int ret;

    ret = gpiod_get_controller(0, &gi);
    if (ret < 0) {
        return ret;
    }

    ret = gpiod_chip_open(gi, 0, &gi);
    if (ret < 0) {
        gpiod_chip_close(gi);
        return ret;
    }

    ret = gpiod_chip_get_line(&gi, TRIG_PIN, &gi);
    if (ret < 0) {
        gpiod_chip_close(gi);
        return ret;
    }

    ret = gpiod_chip_set_value(&gi, TRIG_PIN, 0);
    if (ret < 0) {
        gpiod_chip_close(gi);
        return ret;
    }

    ret = gpiod_chip_get_line(&gi, ECHO_PIN, &gi);
    if (ret < 0) {
        gpiod_chip_close(gi);
        return ret;
    }

    ret = gpiod_chip_set_pull(&gi, ECHO_PIN, GPIO_PULL_UP);
    if (ret < 0) {
        gpiod_chip_close(gi);
        return ret;
    }

    gpiod_chip_close(gi);
    return 0;
}

static int measure_distance(void) {
    struct timespec ts;
    int64_t start_time, end_time;
    int64_t pulse_width;
    int ret;

    ret = clock_gettime(CLOCK_MONOTONIC, &ts);
    if (ret < 0) {
        return -1;
    }

    gpiod_trigger(ECHO_PIN, 0);
    gpiod_trigger(TRIG_PIN, TRIG_LOW_TIME);
    gpiod_trigger(TRIG_PIN, TRIG_PULSE_TIME);
    gpiod_trigger(TRIG_PIN, 0);

    ret = gpiod_wait_for(ECHO_PIN, 0);
    if (ret < 0) {
        return -1;
    }

    start_time = ts.tv_sec * 1000000 + ts.tv_nsec;
    ret = gpiod_trigger(ECHO_PIN, 1);
    if (ret < 0) {
        return -1;
    }

    while (!gpiod_triggered(ECHO_PIN)) {
        if (sigint_flag) {
            break;
        }
        ret = gpiod_wait_for(ECHO_PIN, ECHO_TIMEOUT);
        if (ret < 0) {
            return -1;
        }
    }

    end_time = ts.tv_sec * 1000000 + ts.tv_nsec;
    pulse_width = end_time - start_time;

    gpiod_trigger(ECHO_PIN, 0);

    if (pulse_width < 10000 || pulse_width > 30000) {
        return -1;
    }

    float distance = (pulse_width / 2) * SPEED_OF_SOUND;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }

    return (int)(distance);
}

static void log_distance(int distance) {
    FILE *fp;
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));

    fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(fp, "%sZ, %d\n", timestamp, distance);
    fflush(fp);
    fclose(fp);
}

static void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(void) {
    int ret;

    signal(SIGINT, sigint_handler);

    ret = gpio_init();
    if (ret < 0) {
        return ret;
    }

    ret = gpio_setup();
    if (ret < 0) {
        gpio_cleanup();
        return ret;
    }

    while (!sigint_flag) {
        int distance = measure_distance();
        if (distance >= 0) {
            log_distance(distance);
        }
        sleep(1);
    }

    ret = gpio_cleanup();
    if (ret < 0) {
        return ret;
    }

    fclose(fopen("distance_log.txt", "a"));
    return 0;
}

