#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <gpio.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 1
#define TRIG_PULSE_NS 10000

static FILE *log_file = NULL;
static gpio_context *ctx = NULL;
static gpio_signal_handler_t isr_cb = NULL;

void sigint_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        disable_isr();
        fclose(log_file);
        gpio_cleanup(ctx);
        exit(0);
    }
}

void disable_isr() {
    if (isr_cb) {
        gpio_unregister_event(ctx, isr_cb);
        isr_cb = NULL;
    }
}

void init_gpio() {
    int ret;

    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    ctx = gpio_context_new();
    ret = gpio_request_available(ctx, TRIG_GPIO, GPIOD_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG GPIO\n");
        gpio_free(ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpio_request_available(ctx, ECHO_GPIO, GPIOD_IN);
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO GPIO\n");
        gpio_free(ctx);
        exit(EXIT_FAILURE);
    }

    gpio_set_line_direction(ctx, TRIG_GPIO, GPIOD_HIGH);
    gpio_set_line_direction(ctx, ECHO_GPIO, GPIOD_IN);
}

void setup_isr() {
    int ret;

    ret = gpio_add_event(ctx, ECHO_GPIO, GPIOD_FALLING | GPIOD_RISING, isr_cb, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to add ISR event\n");
        gpio_free(ctx);
        exit(EXIT_FAILURE);
    }
}

void isr_callback(gpio_context *ctx, uint32_t id, uint32_t event, void *user_data) {
    static uint64_t last_time = 0;
    static uint64_t distance_us = 0;
    uint64_t current_time;
    uint16_t pulse_width;

    current_time = gpio_time(ctx);
    pulse_width = current_time - last_time;
    last_time = current_time;

    if (pulse_width < 0 || pulse_width > 10000000) {
        return;
    }

    distance_us = pulse_width * 1000000 / 2; // Convert to microseconds
    if (distance_us < 10000 || distance_us > 2500000) {
        return;
    }

    distance_us = distance_us * 0.0343 / 2; // Convert to meters
    fprintf(log_file, "%lu\t%lu\n", (unsigned long)(time(NULL) - TIME_INIT), (unsigned long)distance_us);
}

int main() {
    struct sigaction sa;
    TIME_TYPE time_init = 0;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_init = time(NULL);

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    init_gpio();
    setup_isr();

    while (1) {
        gpio_poll(ctx, -1);
        sleep(1);
    }

    gpio_free(ctx);
    fclose(log_file);
    return 0;
}

