#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <syslog.h>
#include <stdarg.h>

#define VL53L1X_ADDR 0x29
#define GPIO_PIN 27

struct i2c_dev i2c;
struct gpiod_chip chip;

static int i2c_open(struct i2c_dev *dev)
{
    int ret;

    ret = i2c_allocate();
    if (ret < 0)
        return ret;

    i2c->bus = ret;
    i2c->addr = VL53L1X_ADDR;

    return 0;
}

static void i2c_close(struct i2c_dev *dev)
{
    i2c_free(dev->bus);
}

static ssize_t i2c_xfer(struct i2c_dev *dev, uint8_t *buf, uint8_t *cnt, uint8_t direction)
{
    return i2c_transfer(dev->bus, dev->addr, buf, cnt, direction);
}

static int init_gpio(void)
{
    int ret;

    ret = gpiod_chip_open(&chip, "GPIO27");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip\n");
        return ret;
    }

    ret = gpiod_chip_add_line(&chip, "xshut", GPIO_PIN);
    if (ret < 0) {
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_value(&chip, "xshut", 0);
    if (ret < 0) {
        gpiod_chip_del_line(&chip, "xshut");
        gpiod_chip_close(&chip);
        return ret;
    }

    return 0;
}

static void cleanup(void)
{
    gpiod_chip_close(&chip);
    i2c_close(&i2c);
}

static void sigint_handler(int signum)
{
    syslog(LOG_INFO, "Received SIGINT, cleaning up and exiting\n");
    cleanup();
    exit(0);
}

static void sigterm_handler(int signum)
{
    syslog(LOG_INFO, "Received SIGTERM, cleaning up and exiting\n");
    cleanup();
    exit(0);
}

int main(void)
{
    struct timespec ts;
    int ret;
    uint8_t data[16];
    uint8_t len;

    syslog_openlog(LOG_CONS | LOG_PID, LOG_DAEMON, LOG_LOCAL0);

    ret = init_gpio();
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO\n");
        return ret;
    }

    ret = i2c_open(&i2c);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open I2C device\n");
        return ret;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        syslog(LOG_INFO, "Starting measurement at %ld ms since boot\n", (long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000));

        ret = i2c_xfer(&i2c, data, &len, I2C_RD);
        if (ret < 0) {
            syslog(LOG_ERR, "I2C transfer failed\n");
            continue;
        }

        if (len < 16) {
            syslog(LOG_ERR, "Invalid data length from VL53L1X\n");
            continue;
        }

        // Process the data here, e.g., extract distance in mm

        ret = gpiod_chip_set_value(&chip, "xshut", 1);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set XSHUT pin high\n");
            continue;
        }

        clock_nanosleep(CLOCK_MONOTONIC, 0, 100000000, NULL);
    }

    cleanup();
    return 0;
}

