#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define VL53L1X_ADDR 0x29
#define DIST_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define I2C_BUS 1

struct gate_state {
    bool open;
    bool active;
};

static struct gate_state gate_status = {false, false};
static gpiod_chip *chip;
static int fd;

void sigint_handler(int signum) {
    gate_status.active = false;
    gpiod_unclaim(chip);
    fclose(log_file);
    exit(0);
}

void init_gate_log() {
    log_file = fopen("gate_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ",
            1900 + local_time->tm_year,
            1 + local_time->tm_mon,
            local_time->tm_mday,
            local_time->tm_hour,
            local_time->tm_min,
            local_time->tm_sec);

    fprintf(log_file, "%s\n", message);
    fflush(log_file);
}

void cleanup_gate_log() {
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_gate_log();

    chip = gpiod_chip_open(I2C_BUS, 0);
    if (!chip) {
        perror("Failed to open I2C chip");
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_line(chip, 24, &fd, NULL) < 0) {
        perror("Failed to claim GPIO24");
        gpiod_chip_close(chip);
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    gpiod_chip_set_value(chip, fd, 0); // Gate closed initially

    if (gpiod_chip_open_export(chip) < 0) {
        perror("Failed to export GPIOs");
        gpiod_chip_close(chip);
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(&fd) < 0) {
        log_message("VL53L1X initialization failed\n");
        gpiod_chip_close(chip);
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    while (gate_status.active) {
        uint16_t distance_mm;
        if (vl53l1x_read_distance(&fd, &distance_mm) < 0) {
            log_message("Failed to read distance\n");
            continue;
        }

        double distance_cm = distance_mm / 10.0;
        log_message("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < DIST_THRESHOLD) {
            if (!gate_status.open) {
                gate_status.open = true;
                gpiod_chip_set_value(chip, fd, 1);
                log_message("Gate opened\n");
            }
        } else {
            if (gate_status.open) {
                gate_status.open = false;
                gpiod_chip_set_value(chip, fd, 0);
                log_message("Gate closed\n");
            }
        }

        usleep(100000); // 100 ms delay
    }

    gpiod_chip_close(chip);
    cleanup_gate_log();
    return 0;
}

