    chip = gpiod_chip_open(I2C_BUS, 0);
    if (!chip) {
        perror("Failed to open I2C chip");
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_line(chip, 24, &fd, NULL) < 0) {
        perror("Failed to claim GPIO24");
        gpiod_chip_close(chip);
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    gpiod_chip_set_value(chip, fd, 0); // Gate closed initially

    if (gpiod_chip_open_export(chip) < 0) {
        perror("Failed to export GPIOs");
        gpiod_chip_close(chip);
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(&fd) < 0) {
        log_message("VL53L1X initialization failed\n");
        gpiod_chip_close(chip);
        cleanup_gate_log();
        return EXIT_FAILURE;
    }

    while (gate_status.active) {
        uint16_t distance_mm;
        if (vl53l1x_read_distance(&fd, &distance_mm) < 0) {
            log_message("Failed to read distance\n");
            continue;
        }

        double distance_cm = distance_mm / 10.0;
        log_message("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < DIST_THRESHOLD) {
            if (!gate_status.open) {
                gate_status.open = true;
                gpiod_chip_set_value(chip, fd, 1);
                log_message("Gate opened\n");
            }
        } else {
            if (gate_status.open) {
                gate_status.open = false;
                gpiod_chip_set_value(chip, fd, 0);
                log_message("Gate closed\n");
            }
        }

        usleep(100000); // 100 ms delay
    }

    gpiod_chip_close(chip);
    cleanup_gate_log();
    return 0;
}
```

Please note that this code assumes the existence of a `vl53l1x_init()` and `vl53l1x_read_distance()` functions, which you would need to implement or find appropriate libraries for VL53L1X sensor communication. Additionally, you need to include the necessary header files for these functions.

This code also assumes that the VL53L1X sensor is connected to I2C bus 1 at address 0x29. Make sure to adjust the address if necessary.

Lastly, ensure that the Raspberry Pi Zero W has the required libraries installed (`libgpiod`, `libgpiod-dev`, and any VL53L1X sensor library).

