        fprintf(stderr, "Failed to enumerate gpiod chips\n");
        gpiod_chip_uninitialize();
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_find(&trig_chip, TRIG_PIN, &trig_chip);
