        }
        distance = sum / MOVING_AVERAGE_SIZE;

        // Pan servo based on distance
        update_servo(distance);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    pigpio_terminate();
    fclose(fopen("distance_log.csv", "a"));

    return EXIT_SUCCESS;
}

