#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <string.h>

#define BUFFER_SIZE 10
#define I2C_ADDR 0x29
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 200

typedef struct {
    int16_t data[BUFFER_SIZE];
    int head, tail;
} CircularBuffer;

void cb_handler(const struct gpiod_chip *chip,
                struct gpiod_event event,
                void *user_data) {
    if (event.type == GPIO_EVENT_OUT_HIGH) {
        printf("Warning: Distance below threshold!\n");
    } else {
        printf("Distance normal.\n");
    }
}

int init_i2c(const char *bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

void deinit_i2c(int fd) {
    close(fd);
}

int init_led(int gpio) {
    struct gpiod_chip chip;
    int ret;

    ret = gpiod_chip_from_phandle(&chip, gpio, "led");
    if (ret < 0) {
        fprintf(stderr, "Failed to find GPIO chip\n");
        return ret;
    }

    struct gpiod_line line = gpiod_chip_get_line(chip.id, 0);
    if (line.pin < 0) {
        fprintf(stderr, "Failed to get line from chip\n");
        return line.pin;
    }

    struct gpiod_gpio_params params = {
        .direction = GPIO_DIR_OUT,
        .initial_value = 0,
    };

    ret = gpiod_chip_set_params(chip.id, line.pin, &params);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line direction and initial value\n");
        return ret;
    }

    return 0;
}

void cleanup_led(int gpio) {
    struct gpiod_chip chip;
    int ret;

    ret = gpiod_chip_from_phandle(&chip, gpio, "led");
    if (ret < 0) {
        fprintf(stderr, "Failed to find GPIO chip\n");
        return;
    }

    struct gpiod_line line = gpiod_chip_get_line(chip.id, 0);
    if (line.pin < 0) {
        fprintf(stderr, "Failed to get line from chip\n");
        return;
    }

    gpiod_chip_eject(chip.id, line.pin);
}

int main(int argc, char *argv[]) {
    int i2c_fd = init_i2c("/dev/i2c-1", I2C_ADDR);
    if (i2c_fd < 0) {
        return -1;
    }

    CircularBuffer cb;
    cb.head = cb.tail = 0;

    init_led(LED_GPIO);
    gpiod_add_callback(&cb.led_gpio, LED_GPIO, GPIO_EVENT_OUT_HIGH, cb_handler, NULL);

    while (1) {
        int16_t distance;
        if (i2c_read(i2c_fd, I2C_ADDR, &distance) < 0) {
            fprintf(stderr, "Failed to read from VL53L1X\n");
            continue;
        }

        cb.data[cb.head] = distance;
        cb.head = (cb.head + 1) % BUFFER_SIZE;

        if (distance < DISTANCE_THRESHOLD) {
            gpiod_trigger(&cb.led_gpio, 1);
        } else {
            gpiod_trigger(&cb.led_gpio, 0);
        }

        usleep(50000);
    }

    deinit_i2c(i2c_fd);
    cleanup_led(LED_GPIO);

    return 0;
}

