#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define PWM_GPIO 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define PWM_FREQ 1000000
#define TIMEOUT_MS 200

struct context *ctx;
int freq;

void sigint_handler(int signum) {
    gpiod_unregister_event(ctx->echogpio, NULL);
    gpiod_unregister_event(ctx->triggpio, NULL);
    gpiod_unpoll(ctx->pwmgpio);
    exit(0);
}

void setup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(0, "rpi");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", gpio);
        gpiod_chip_put(chip);
        exit(1);
    }

    ret = gpiod_line_export(line, "my_project");
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO line %d\n", gpio);
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        exit(1);
    }

    ctx->gpio = line;
}

void cleanup_gpio(int gpio) {
    gpiod_line_free(ctx->gpio);
    gpiod_chip_put(ctx->chip);
}

void trigger_pulse(void) {
    gpiod_trigger_output(ctx->triggpio, 1);
    usleep(10000);
    gpiod_trigger_output(ctx->triggpio, 0);
}

uint64_t measure_distance(void) {
    uint64_t duration;
    gpiod_trigger_output(ctx->triggpio, 1);
    gpiod_get_value(ctx->echogpio, &duration);
    gpiod_trigger_output(ctx->triggpio, 0);
    return duration;
}

void set_frequency(int distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE)
        return;

    double log_distance = log10((double)distance / MIN_DISTANCE + 1);
    freq = round(200 + 1800 * log_distance);
    gpiod_set_value(ctx->pwmgpio, 1);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *triggpio, *echogpio, *pwmgpio;
    int ret;

    ctx = malloc(sizeof(struct context));

    chip = gpiod_chip_open(0, "rpi");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    triggpio = gpiod_chip_get_line(chip, TRIG_GPIO);
    echogpio = gpiod_chip_get_line(chip, ECHO_GPIO);
    pwmgpio = gpiod_chip_get_line(chip, PWM_GPIO);

    if (!triggpio || !echogpio || !pwmgpio) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_put(chip);
        return 1;
    }

    ctx->triggpio = triggpio;
    ctx->echogpio = echogpio;
    ctx->pwmgpio = pwmgpio;
    ctx->chip = chip;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_gpio(TRIG_GPIO);
    setup_gpio(ECHO_GPIO);
    setup_gpio(PWM_GPIO);

    gpiod_add_event(ctx->echogpio, GPIOD_EVENT_FALLING, 0,
        (void *)main, ctx, NULL);

    while (1) {
        uint64_t duration = measure_distance();
        int distance = (duration / 29) * 17; // Assuming 29 cm/us
        set_frequency(distance);

        // PWM setup
        struct gpiod_pwm_config pwm_config = {
            .freq = PWM_FREQ,
            .duty_cycle = 50,
        };
        ret = gpiod_pwm_configure(ctx->pwmgpio, &pwm_config);
        if (ret < 0) {
            fprintf(stderr, "Failed to configure PWM\n");
            cleanup_gpio(PWM_GPIO);
            gpiod_chip_put(chip);
            return 1;
        }

        usleep(TIMEOUT_MS * 1000);
    }

    cleanup_gpio(PWM_GPIO);
    gpiod_chip_put(chip);
    return 0;
}

