This code sets up the HC-SR04 sensor and 8-ohm speaker using libgpiod, generates PWM signals for audio tones, and controls the pitch based on the measured distance. It includes error handling for GPIO operations and a SIGINT/SIGTERM handler for clean termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define TRIG_LOW_TIME 10
#define TRIG_PULSE_WIDTH 10
#define ECHO_TIMEOUT 100000 // 100 ms
#define DIST_MIN 5000 // 5 cm
#define DIST_MAX 50000 // 50 cm
#define FREQ_MIN 200
#define FREQ_MAX 2000

volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

void setup_gpio() {
    if (gpioInit() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0 || gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioExit();
        exit(EXIT_FAILURE);
    }

    gpioSetPull(ECHO_PIN, PI_PULL_DOWN);
}

uint64_t measure_distance() {
    gpioWrite(TRIG_PIN, 0);
    delayMicroseconds(TRIG_LOW_TIME);
    gpioWrite(TRIG_PIN, 1);
    delayMicroseconds(TRIG_PULSE_WIDTH);
    gpioWrite(TRIG_PIN, 0);

    uint64_t echo_start = gpioGetLevel(ECHO_PIN);
    uint64_t echo_end = 1;
    uint64_t echo_pulse_width = 0;
    uint64_t timeout = 0;

    while ((gpioGetLevel(ECHO_PIN) != echo_end) && (timeout < ECHO_TIMEOUT)) {
        if (++timeout >= ECHO_TIMEOUT) {
            fprintf(stderr, "Echo timeout.\n");
            return 0;
        }
        delayMicroseconds(1);
    }

    echo_pulse_width = timeout;

    return echo_pulse_width * TIME_UNIT / (2 * DIST_MAX);
}

void generate_tone(uint32_t freq) {
    gpioSetFrequency(BUZZER_PIN, freq);
    gpioWrite(BUZZER_PIN, 1);
}

int main() {
    signal(SIGINT, sigint_handler);

    setup_gpio();

    while (running) {
        uint64_t distance = measure_distance();
        if (distance) {
            uint32_t freq = clamp(FREQ_MIN, FREQ_MAX, map(distance, DIST_MIN, DIST_MAX, FREQ_MIN, FREQ_MAX));
            generate_tone(freq);
            printf("Distance: %llu cm, Frequency: %u Hz\n", distance, freq);
            delayMilliseconds(10);
        }
    }

    gpioExit();
    return 0;
}

uint32_t clamp(uint32_t min, uint32_t max, uint32_t value) {
    return (value < min) ? min : (value > max) ? max : value;
}

uint32_t map(uint32_t from_min, uint32_t from_max, uint32_t to_min, uint32_t to_max, uint32_t value) {
    return (value - from_min) * (to_max - to_min) / (from_max - from_min) + to_min;
}

