#define ECHO_GPIO 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define TRIG_PULSE_US 10
#define ECHO_TIMEOUT_MS 50
#define LOOP_INTERVAL_MS 500

volatile sig_atomic_t sigint_flag = 0;

static int trigger_setup(gpiod_chip *chip, uint trigger_gpio, bool direction) {
    struct gpiod_line_request req;
    gpiod_line_request_init(&req);
    req.line.gpio = trigger_gpio;
    req.flags = GPIOD_LINE_REQUEST_OUTPUT;
    if (direction)
        req.flags |= GPIOD_LINE_REQUEST_ACTIVE_HIGH;
    gpiod_line_request_add(&req, &chip->lines[trigger_gpio]);
    return 0;
}

static int echo_setup(gpiod_chip *chip, uint echo_gpio, bool direction) {
    struct gpiod_line_request req;
    gpiod_line_request_init(&req);
    req.line.gpio = echo_gpio;
    req.flags = GPIOD_LINE_REQUEST_INPUT;
    gpiod_line_request_add(&req, &chip->lines[echo_gpio]);
    return 0;
}

static int measure_distance(gpiod_chip *chip, uint trigger_gpio, uint echo_gpio) {
    int distance = -1;
    gpiod_trigger_consume(chip->lines[trigger_gpio].trigger);
    gpiod_acknowledge(chip->lines[trigger_gpio].trigger);
    gpiod_acknowledge(chip->lines[echo_gpio].trigger);

    gpiod_set_value(chip->lines[trigger_gpio].trigger, 0);
    gpiod_set_value(chip->lines[trigger_gpio].trigger, 1);
    delay_us(TRIG_PULSE_US);
    gpiod_set_value(chip->lines[trigger_gpio].trigger, 0);

    gpiod_wait_for_edge(chip->lines[echo_gpio].trigger, GPIO_FALLING_EDGE);
    struct timespec timeout;
    timeout.tv_sec = 0;
    timeout.tv_nsec = ECHO_TIMEOUT_MS * 1000000;
    distance = gpiod_wait_for_signal(chip->lines[echo_gpio].trigger, timeout);

    if (distance == -1)
        return -1;

    return distance;
}

static void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main() {
    gpiod_chip chip;
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return ret;
    }

    ret = gpiod_chip_request_lines(&chip, &trigger_setup, TRIG_GPIO, true);
    if (ret) {
        fprintf(stderr, "Failed to configure trigger pin\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_request_lines(&chip, &echo_setup, ECHO_GPIO, false);
    if (ret) {
        fprintf(stderr, "Failed to configure echo pin\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    signal(SIGINT, sigint_handler);

    while (!sigint_flag) {
        int distance = measure_distance(&chip, TRIG_GPIO, ECHO_GPIO);
        if (distance == -1)
            printf("Timeout\n");
        else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE)
            printf("Invalid reading\n");
        else
            printf("Distance: %.2f cm", distance / 29.1);

        if (distance < 10)
            printf(" Too close!\n");

        sleep(LOOP_INTERVAL_MS / 1000);
    }

    gpiod_chip_close(&chip);
    return 0;
}

