#include <signal.h>
#include <gpio.h>
#include <gpiod.h>

#define I2C_ADDR_ICU_20201 0x1D
#define SPI_CLOCK_HZ 1000000
#define SPI_MODE 0
#define GPIO_CE0 8
#define LOG_FILE "distance_log.csv"

struct spi_dev {
    gpiod_chip *chip;
    gpiod_line *cs;
    gpiod_line *sclk;
    gpiod_line *mosi;
    gpiod_line *miso;
};

static struct spi_dev spi_dev;
FILE *log_file = NULL;

static void spi_init(struct spi_dev *dev) {
    int ret;

    dev->chip = gpiod_chip_open(NULL, "spi0");
    if (!dev->chip) {
        fprintf(stderr, "Failed to open SPI chip\n");
        return;
    }

    dev->cs = gpiod_chip_get_line(dev->chip, "CE0");
    if (!dev->cs) {
        fprintf(stderr, "Failed to get CE0 line\n");
        gpiod_chip_close(dev->chip);
        return;
    }
    gpiod_line_export(dev->cs, "user");

    dev->sclk = gpiod_chip_get_line(dev->chip, "SCLK");
    if (!dev->sclk) {
        fprintf(stderr, "Failed to get SCLK line\n");
        gpiod_line_unexport(dev->cs);
        gpiod_chip_close(dev->chip);
        return;
    }
    gpiod_line_export(dev->sclk, "user");

    dev->mosi = gpiod_chip_get_line(dev->chip, "MOSI");
    if (!dev->mosi) {
        fprintf(stderr, "Failed to get MOSI line\n");
        gpiod_line_unexport(dev->sclk);
        gpiod_chip_close(dev->chip);
        return;
    }
    gpiod_line_export(dev->mosi, "user");

    dev->miso = gpiod_chip_get_line(dev->chip, "MISO");
    if (!dev->miso) {
        fprintf(stderr, "Failed to get MISO line\n");
        gpiod_line_unexport(dev->mosi);
        gpiod_chip_close(dev->chip);
        return;
    }
    gpiod_line_export(dev->miso, "user");

    ret = gpiod_line_set_dir(dev->cs, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set CE0 direction\n");
        gpiod_line_unexport(dev->miso);
        gpiod_line_unexport(dev->mosi);
        gpiod_line_unexport(dev->sclk);
        gpiod_chip_close(dev->chip);
        return;
    }

    gpiod_line_set_value(dev->cs, 1);

    ret = gpiod_line_set_params(dev->sclk, SPI_CLOCK_HZ);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SCLK params\n");
        gpiod_line_unexport(dev->miso);
        gpiod_line_unexport(dev->mosi);
        gpiod_line_unexport(dev->sclk);
        gpiod_chip_close(dev->chip);
        return;
    }
}

static void spi_cleanup(struct spi_dev *dev) {
    gpiod_line_unexport(dev->miso);
    gpiod_line_unexport(dev->mosi);
    gpiod_line_unexport(dev->sclk);
    gpiod_line_unexport(dev->cs);
    gpiod_chip_close(dev->chip);
}

static void sigint_handler(int signum) {
    spi_cleanup(&spi_dev);
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct spi_dev *dev = &spi_dev;
    gpio_init();
    gpio_set_direction(GPIO_CE0, GPIO_OUTPUT);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    spi_init(dev);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spi_cleanup(dev);
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(dev->cs, 0);
        usleep(10);
        gpiod_line_set_value(dev->cs, 1);

        uint8_t tx_buf[2] = {0x80, 0x00};
        uint8_t rx_buf[3];
        size_t len = gpiod_batch_process(NULL, 1000);

        if (len < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        if (len == 0) {
            fprintf(stderr, "No data received\n");
            continue;
        }

        // Assuming the sensor returns 3 bytes: timestamp (16 bits) and distance (16 bits)
        uint16_t timestamp = (rx_buf[0] << 8) | rx_buf[1];
        uint16_t distance = (rx_buf[1] << 8) | rx_buf[2];

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);

        fprintf(log_file, "%ld,%d\n", now, distance);

        fflush(log_file);
        usleep(100 * 1000);
    }

    spi_cleanup(dev);
    fclose(log_file);
    gpio_cleanup();

    return EXIT_SUCCESS;
}

