#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define SI1175_ADDR 0x60
#define SAMPLE_INTERVAL 5

int main() {
    int fd;
    uint8_t reg_addr = 0x00;
    uint16_t als_visible;
    char filename[] = "proximity_log.csv";
    int log_fd;
    struct timespec ts;
    char timestamp[26];

    // Initialize GPIO
    gpiod_context ctx = gpiod_new();
    const char *i2c_bus = "/dev/i2c-1";
    int ret = gpiod_in_open(ctx, i2c_bus, GPIOD_IN_OPEN_FLAGS_NONE, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return ret;
    }

    // Open I2C device
    fd = open(i2c_bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_out_close(ctx);
        return fd;
    }

    // Write to register to start measurement
    reg_addr = 0x2C;
    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device\n");
        close(fd);
        gpiod_out_close(ctx);
        return -1;
    }

    // Prepare log file
    log_fd = fopen(filename, "w");
    if (!log_fd) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        gpiod_out_close(ctx);
        return -1;
    }

    // Write header
    if (fprintf(log_fd, "timestamp,als_visible\n") < 0) {
        fprintf(stderr, "Failed to write header to log file\n");
        fclose(log_fd);
        close(fd);
        gpiod_out_close(ctx);
        return -1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));

        if (read(fd, &als_visible, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        // Wait for sampling interval
        nanosleep(&ts, NULL);

        // Write data to log file
        if (fprintf(log_fd, "%s,%u\n", timestamp, als_visible) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            break;
        }
    }

    // Clean up
    fclose(log_fd);
    close(fd);
    gpiod_out_close(ctx);

    return 0;
}

