#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define SI1120_ADDR 0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_HIGH 0x01
#define SI1120_REG_ALS_LOW 0x02
#define SI1120_REG_PROX_HIGH 0x03
#define SI1120_REG_PROX_LOW 0x04
#define SI1120_REG_RESET 0x05
#define SI1120_PART_ID 0x1120

struct si1120_data {
    uint16_t als;
    uint16_t prox;
};

static int si1120_read(struct i2c_client *client, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_rdwr_ioctl_data rdwr = {0};
    rdwr.dx = data;
    rdwr.nbytes = len;
    rdwr.flags = 0;

    if (ioctl(client->fd, I2C_RDWR, &rdwr) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    return 0;
}

static int si1120_init(struct i2c_client *client) {
    if (si1120_read(client, SI1120_REG_PART_ID, &si1120_part_id, 1) < 0)
        return -1;

    if (si1120_part_id != SI1120_PART_ID) {
        fprintf(stderr, "Invalid part ID\n");
        return -1;
    }

    return 0;
}

static struct si1120_data si1120_read_data(struct i2c_client *client) {
    struct si1120_data data;
