#include <gpiod.h>

#define SI1182_ADDR 0x68
#define MEAS_RATE_REG 0x0C
#define PART_ID_REG 0x00

int i2c_fd = -1;
int log_fd = -1;

void sigint_handler(int signum, siginfo_t *info, void *context) {
    gpiod_put(gpio);
    close(i2c_fd);
    close(log_fd);
    exit(signum == SIGINT ? 0 : 1);
}

void sigterm_handler(int signum, siginfo_t *info, void *context) {
    sigint_handler(signum, info, context);
}

void setup_signals() {
    struct sigaction sa;
    sa.sa_sigaction = sigint_handler;
    sa.sa_flags = SA_SIGINFO;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_sigaction = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

int i2c_init(const char *dev) {
    i2c_fd = open(dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void i2c_cleanup() {
    if (i2c_fd >= 0) {
        ioctl(i2c_fd, I2C_SLAVE, 0);
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int i2c_read(uint8_t reg, uint8_t *data, int len) {
    if (len > 1) {
        if (ioctl(i2c_fd, I2C_RDWR, reg) < 0) {
            perror("Failed to read from I2C device");
            return -1;
        }

        if (len == 1) {
            if (read(i2c_fd, data, 1) != 1) {
                perror("Failed to read from I2C device");
                return -1;
            }
        } else {
            if (read(i2c_fd, data, len) != len) {
                perror("Failed to read from I2C device");
                return -1;
            }
        }
    }
    return 0;
}

int i2c_write(uint8_t reg, const uint8_t *data, int len) {
    if (len > 0) {
        if (ioctl(i2c_fd, I2C_RDWR, reg | 1) < 0) {
            perror("Failed to write to I2C device");
            return -1;
        }

        if (write(i2c_fd, data, len) != len) {
            perror("Failed to write to I2C device");
            return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    setup_signals();

    if (i2c_init("/dev/i2c-1") < 0) {
        return 1;
    }

    uint8_t part_id[3];
    if (i2c_read(PART_ID_REG, part_id, 3) < 0) {
        i2c_cleanup();
        return 1;
    }

    if (part_id[0] != 0x11 || part_id[1] != 0x82) {
        fprintf(stderr, "Invalid part ID: 0x%02X%02X\n", part_id[0], part_id[1]);
        i2c_cleanup();
        return 1;
    }

    uint8_t meas_rate = 0x06; // 100ms measurement rate
    if (i2c_write(MEAS_RATE_REG, &meas_rate, 1) < 0) {
        i2c_cleanup();
        return 1;
    }

    log_fd = open("biometric_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        i2c_cleanup();
        return 1;
    }

    while (1) {
        time_t now_sec = time(NULL);
        struct tm *now_tm = localtime(&now_sec);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        uint16_t proximity;
        if (i2c_read(0x0F, &proximity, 2) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            break;
        }

        uint16_t lux;
        if (i2c_read(0x0E, &lux, 2) < 0) {
            fprintf(stderr, "Failed to read lux data\n");
            break;
        }

        char line[100];
        sprintf(line, "%s,%d,%d\n", timestamp, lux, proximity);

        if (write(log_fd, line, strlen(line)) != strlen(line)) {
            perror("Failed to write to log file");
            break;
        }

        printf("%s", line);

        usleep(100000);
    }

    i2c_cleanup();
    close(log_fd);
    return 0;
}

