#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpio.h>

#define SI1145_ADDR 0x60
#define MAX_RETRIES 3

struct si1145_data {
    int fd;
    int i2c_handle;
    FILE *log_file;
};

static int si1145_read_reg(struct si1145_data *data, uint8_t reg, uint16_t *value) {
    int ret;
    uint8_t tx_buf[2] = {reg, 0};
    uint8_t rx_buf[3];

    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = gpiod_iomap(data->fd);
        if (ret < 0) {
            fprintf(stderr, "Error mapping GPIO: %s\n", strerror(errno));
            return ret;
        }

        ret = gpiod_i2c_write(data->i2c_handle, tx_buf, sizeof(tx_buf), 0);
        if (ret < 0) {
            fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
            continue;
        }

        ret = gpiod_i2c_read(data->i2c_handle, rx_buf, sizeof(rx_buf), 0);
        if (ret < 0) {
            fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
            continue;
        }

        *value = (rx_buf[1] << 8) | rx_buf[2];
        return 0;
    }

    fprintf(stderr, "Exhausted retries for I2C communication\n");
    return -1;
}

static void si1145_init(struct si1145_data *data) {
    int ret;

    data->fd = gpiod_iomap(NULL);
    if (data->fd < 0) {
        fprintf(stderr, "Error mapping GPIO: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    data->i2c_handle = gpiod_i2c_open(data->fd, SI1145_ADDR);
    if (!data->i2c_handle) {
        fprintf(stderr, "Error opening I2C device\n");
        exit(EXIT_FAILURE);
    }

    data->log_file = fopen("proximity_log.txt", "a");
    if (!data->log_file) {
        fprintf(stderr, "Error opening log file\n");
        exit(EXIT_FAILURE);
    }
}

static void si1145_cleanup(struct si1145_data *data) {
    fclose(data->log_file);
    gpiod_i2c_close(data->i2c_handle);
    gpiod_iomunmap(data->fd);
}

static void sigint_handler(int signum) {
    printf("SIGINT received, cleaning up and exiting...\n");
    si1145_cleanup(data);
    exit(EXIT_SUCCESS);
}

static void sigterm_handler(int signum) {
    printf("SIGTERM received, cleaning up and exiting...\n");
    si1145_cleanup(data);
    exit(EXIT_SUCCESS);
}

int main() {
    struct si1145_data data;
    uint16_t proximity;
    char timestamp[20];

    si1145_init(&data);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&now));

        if (si1145_read_reg(&data, 0x2C, &proximity) < 0) {
            continue;
        }

        fprintf(data.log_file, "%s: %u\n", timestamp, proximity);
        fflush(data.log_file);

        sleep(1);
    }

    si1145_cleanup(&data);
    return 0;
}

