#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MAX_DISTANCE 200
#define MIN_DISTANCE 20
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

#define TRY_COUNT 3

static volatile int running = 1;
static float distance;
static int servo_angle;

static void sigint_handler(int signum) {
    running = 0;
}

static int measure_distance(int trig_pin, int echo_pin) {
    struct gpiod_chipchip *chip;
    struct gpiod_line *line;
    int timeout_us = 1000000;
    int ret;

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, trig_pin);
    if (!line) {
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to get line for trigger pin\n");
        return -1;
    }

    ret = gpiod_line_export(line, "user");
    if (ret < 0) {
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to export trigger line\n");
        return -1;
    }

    gpiod_line_set_value(line, 1);
    gpiod_line_set_value(line, 0);

    line = gpiod_chip_get_line(chip, echo_pin);
    if (!line) {
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to get line for echo pin\n");
        return -1;
    }

    ret = gpiod_line_request_buffers(line, &timeout_us);
    if (ret < 0) {
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to request buffers for echo line\n");
        return -1;
    }

    distance = -1.0;
    while (distance == -1.0) {
        gpiod_line_trigger(line, 0);
        if (gpiod_line_get_value(line)) {
            distance = (float)timeout_us / 58000;
        } else {
            timeout_us *= 2;
            if (timeout_us > 10000000) {
                distance = -1.0;
                break;
            }
        }
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);

    return distance;
}

static void set_servo_angle(int servo_pin, int angle) {
    struct gpiod_chipchip *chip;
    struct gpiod_line *line;
    int pulse_width;

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return;
    }

    line = gpiod_chip_get_line(chip, servo_pin);
    if (!line) {
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to get line for servo pin\n");
        return;
    }

    ret = gpiod_line_export(line, "user");
    if (ret < 0) {
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to export servo line\n");
        return;
    }

    pulse_width = (angle == 0) ? SERVO_MIN_PULSE :
                   (angle == 90) ? SERVO_MAX_PULSE :
                   SERVO_MIN_PULSE + (angle - 45) * 1000;

    gpiod_line_set_value(line, 0);
    usleep(pulse_width / 10);
    gpiod_line_set_value(line, 1);
    usleep((1000000 - pulse_width) / 10);
    gpiod_line_set_value(line, 0);

    gpiod_line_release(line);
    gpiod_chip_put(chip);
}

int main() {
    struct sigaction sa;
    int ret;

    sa.sa_handler = sigint_handler;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret == -1) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        distance = measure_distance(TRIG_PIN, ECHO_PIN);
        if (distance == -1.0) {
            fprintf(stderr, "Echo timeout, retrying...\n");
            continue;
        }

        servo_angle = (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * 150);
        set_servo_angle(SERVO_PIN, servo_angle);

        printf("Distance: %.2fcm\n", distance);
        usleep(100000);
    }

    return 0;
}

