    dev->msg_buffer.fr.fr_flags = 0;
    dev->msg_buffer.fr.fr_len = 3;
    dev->msg_buffer.fx.fx_addr = VL53L1X_ADDR;
    dev->msg_buffer.fx.fx_flags = I2C_M_RD;
    dev->msg_buffer.fx.fx_len = 3;
    i2c_transfer(dev->fd, &dev->msg, 2);

    if (i2c_transfer(dev->fd, &dev->msg, 2) != 2) {
        perror("Failed to read model ID");
        close(dev->fd);
        return -1;
    }

    dev->model_id[0] = dev->msg_buffer.fx.fx_buf[0];
    dev->model_id[1] = dev->msg_buffer.fx.fx_buf[1];
    dev->model_id[2] = dev->msg_buffer.fx_buf[2];

