        return -1;
    }

    pwm->chip = gpiod_chip_get(pwm->fd);
    if (!pwm->chip) {
        fprintf(stderr, "Failed to get GPIO chip\n");
        gpiod_close(pwm->fd);
        return -1;
    }

    pwm->line = gpiod_chip_get_line(pwm->chip, "PWM");
    if (!pwm->line) {
        fprintf(stderr, "Failed to get PWM line\n");
        gpiod_close(pwm->fd);
        return -1;
    }

    gpiod_add_line_event(pwm->line, true, GPIO_EVENT_FALL | GPIO_EVENT_RISING, 0);

