    gpiod_drain(pwm->line);
    gpiod_close(pwm->fd);
    close(dev->fd);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    cleanup(dev, pwm);
    exit(0);
}

int main() {
    struct vl53l1x_dev dev;
    struct pwm_data pwm;

