    if (init_i2c(&dev) < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return -1;
    }

    if (init_pwm(&pwm) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        cleanup(&dev, &pwm);
        return -1;
    }

    while (1) {
