#include <libgpiod.h>
#include <wiringPiI2C.h>

#define SI7005_ADDR 0x40
#define CONFIG_REG 0xF6
#define TEMP_HUM_REG 0x07

static gpiod_chip *chip;
static int i2c_fd;

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    close(i2c_fd);
    gpiod_uninit();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiod-si7005", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    i2c_fd = wiringPiI2CSetup(SI7005_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_uninit();
        return 1;
    }

    if (gpiod_chip_write(chip, 0, 0, CONFIG_REG) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        close(i2c_fd);
        gpiod_uninit();
        return 1;
    }

    sleep(10);

    while (1) {
        if (gpiod_chip_write(chip, 0, 0, SI7005_ADDR) < 0) {
            fprintf(stderr, "Failed to write to register address\n");
            close(i2c_fd);
            gpiod_uninit();
            return 1;
        }

        sleep(10);

        uint8_t data[3];
        int bytes_read = wiringPiI2CReadReg8(i2c_fd, TEMP_HUM_REG, &data, 3);
        if (bytes_read != 3) {
            fprintf(stderr, "Failed to read from sensor\n");
            close(i2c_fd);
            gpiod_uninit();
            return 1;
        }

        printf("Temperature: %d.C Humidity: %d%%\n", data[0], data[1]);

        close(i2c_fd);
        i2c_fd = wiringPiI2CSetup(SI7005_ADDR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to reopen I2C bus\n");
            gpiod_uninit();
            return 1;
        }
    }

    gpiod_uninit();
    return 0;
}

