#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <stdbool.h>
#include <libgpiod/libgpiod.h>

#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75

#define ACCEL_X_OUT_H_REG 0x3B
#define ACCEL_X_OUT_L_REG 0x3C
#define ACCEL_Y_OUT_H_REG 0x3D
#define ACCEL_Y_OUT_L_REG 0x3E
#define ACCEL_Z_OUT_H_REG 0x3F
#define ACCEL_Z_OUT_L_REG 0x40

#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x44
#define GYRO_YOUT_H_REG 0x45
#define GYRO_YOUT_L_REG 0x46
#define GYRO_ZOUT_H_REG 0x47
#define GYRO_ZOUT_L_REG 0x48

#define TEMP_OUT_REG 0x41

#define I2C_ADDR_LEN 2
#define I2C_REG_LEN 2
#define I2C_DATA_LEN 2

#define CHECK_ERROR(call) \
    do { \
        int err = (call); \
        if (err < 0) { \
            fprintf(stderr, "Error: %s\n", gpiod_strerror(err)); \
            exit(EXIT_FAILURE); \
        } \
    } while (0)

struct mpu6050_data {
    int fd;
    bool running;
};

static int mpu6050_read_reg(struct mpu6050_data *mpu, uint8_t reg, int16_t *val) {
    CHECK_ERROR(gpiod_transfer(mpu->fd, I2C_ADDR_LEN, MPU6050_ADDR, I2C_REG_LEN, &reg, NULL));
    CHECK_ERROR(gpiod_transfer(mpu->fd, I2C_DATA_LEN, NULL, I2C_REG_LEN, NULL, (uint8_t *)val));
    return 0;
}

static int mpu6050_init(struct mpu6050_data *mpu) {
    mpu->fd = gpiod_i2c_open(1, MPU6050_ADDR);
    if (!mpu->fd) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -1;
    }

    int16_t who_am_i;
    CHECK_ERROR(mpu6050_read_reg(mpu, WHO_AM_I_REG, &who_am_i));
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU-6050 not found\n");
        gpiod_i2c_close(mpu->fd);
        return -1;
    }

    mpu->running = true;
    return 0;
}

static void mpu6050_cleanup(struct mpu6050_data *mpu) {
    if (mpu->running) {
        mpu->running = false;
        gpiod_i2c_close(mpu->fd);
    }
}

static void sigint_handler(int signum) {
    mpu6050_cleanup(mpu);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct mpu6050_data mpu;
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (mpu6050_init(&mpu) < 0) {
        return EXIT_FAILURE;
    }

    while (mpu.running) {
        int16_t data[14];
        CHECK_ERROR(mpu6050_read_reg(&mpu, 0x32, data));

        printf("Accelerometer:\n");
        printf("  X: %d\n", data[ACCEL_X_OUT_L_REG]);
        printf("  Y: %d\n", data[ACCEL_Y_OUT_L_REG]);
        printf("  Z: %d\n", data[ACCEL_Z_OUT_L_REG]);

        printf("Gyroscope:\n");
        printf("  X: %d\n", data[GYRO_XOUT_L_REG]);
        printf("  Y: %d\n", data[GYRO_YOUT_L_REG]);
        printf("  Z: %d\n", data[GYRO_ZOUT_L_REG]);

        printf("Temperature: %d\n", data[TEMP_OUT_REG]);
        printf("\n");

        sleep(0);
    }

    mpu6050_cleanup(&mpu);
    printf("Clean shutdown.\n");

    return EXIT_SUCCESS;
}

