#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>

#define SHT40_ADDR 0x44
#define CRC_POLY 0x31
#define CRC_INIT 0xFFFF

typedef struct {
    int fd;
    gpiod_chip *chip;
} sht40_context;

static int sht40_read_crc8(const uint8_t *data, size_t len, uint8_t crc) {
    uint8_t expected_crc = crc;
    for (size_t i = 0; i < len; ++i) {
        expected_crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (expected_crc & 0x8000) {
                expected_crc = (expected_crc << 1) ^ CRC_POLY;
            } else {
                expected_crc <<= 1;
            }
        }
    }
    return expected_crc == crc;
}

static int sht40_measure(sht40_context *ctx, uint8_t *buf, size_t len) {
    if (write(ctx->fd, SHT40_MEASURE_CMD, 1) != 1) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    if (wiringPiI2CReadReg8(ctx->fd, SHT40_REG_DATA) != 6) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    memcpy(buf, wiringPiI2CReadReg8(ctx->fd, SHT40_REG_DATA), len);
    return 0;
}

static void sht40_signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        gpiod_unclaim(ctx->chip);
        close(ctx->fd);
        libgpiod_terminate();
        exit(0);
    }
}

int main() {
    sht40_context ctx;
    ctx.fd = open("/dev/i2c-1", O_RDWR);
    if (ctx.fd < 0) {
        perror("Failed to open I2C bus 1");
        return 1;
    }

    if (ioctl(ctx.fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to acquire I2C bus 1");
        close(ctx.fd);
        return 1;
    }

    ctx.chip = gpiod_chip_open(gpiod_in_get_chip_by_label(NULL, "I2C-1"), "I2C-1");
    if (!ctx.chip) {
        fprintf(stderr, "Failed to get gpiod chip for I2C-1\n");
        close(ctx.fd);
        return 1;
    }

    gpiod_chip_add_listener(ctx.chip, NULL, sht40_signal_handler);

    uint8_t buf[6];
    while (1) {
        if (sht40_measure(&ctx, buf, 6) < 0) {
            continue;
        }

        if (!sht40_read_crc8(buf, 2, buf[1]) || !sht40_read_crc8(buf + 2, 2, buf[3])) {
            fprintf(stderr, "CRC failure, re-opening I2C bus\n");
            close(ctx.fd);
            ctx.fd = open("/dev/i2c-1", O_RDWR);
            if (ctx.fd < 0) {
                perror("Failed to open I2C bus 1");
                return 1;
            }
            if (ioctl(ctx.fd, I2C_SLAVE, SHT40_ADDR) < 0) {
                perror("Failed to acquire I2C bus 1");
                close(ctx.fd);
                return 1;
            }
        }

        int16_t temp = (int16_t) (buf[0] << 8 | buf[1]);
        uint16_t humidity = (uint16_t) (buf[2] << 8 | buf[3]);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp / 10.0, humidity);

        sleep(5);
    }

    gpiod_unclaim(ctx.chip);
    close(ctx.fd);
    libgpiod_terminate();

    return 0;
}

