    struct gpiod_chip chip;
    struct gpiod_line line;
    int fd;
    FILE *log_file = NULL, *error_log_file = NULL;
    char timestamp[20];
    int ret;

    // Initialize GPIO
    ret = gpiod_chip_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        goto cleanup;
    }

    // Open log and error log files
    log_file = fopen(LOG_FILE, "a");
    error_log_file = fopen(ERROR_FILE, "a");
    if (!log_file || !error_log_file) {
        fprintf(stderr, "Failed to open log or error log files\n");
        ret = -1;
        goto cleanup;
    }

    // Initialize I2C
    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd < 0) {
        fprintf(error_log_file, "Error: Failed to initialize I2C\n");
    }

    // Read temperature
    while (1) {
        // Prepare timestamp
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        // Read from sensor
        if (wiringPiI2CReadReg8(fd, 0x00) == -1) {
            fprintf(error_log_file, "Error: Failed to read from sensor at %s\n", timestamp);
            continue;
        }

        // Convert raw data to temperature (assuming linear conversion for simplicity)
        int16_t raw_temp = (int16_t)wiringPiI2CReadReg8(fd, 0x00);
        double temp_celsius = (raw_temp - 512) * 0.05;

        // Log temperature
        fprintf(log_file, "%s: %f\n", timestamp, temp_celsius);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

cleanup:
    // Close log and error log files
    if (log_file) fclose(log_file);
    if (error_log_file) fclose(error_log_file);

    // Finalize GPIO
    gpiod_chip_uninit();

    return ret;
}

