struct sdp810_data {
    uint16_t pres_raw;
    uint16_t temp_raw;
    uint8_t pres_scale;
    uint8_t temp_scale;
};

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = SDP810_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x83;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void convert_raw_to_value(uint16_t raw, uint8_t scale, float *value) {
    *value = (float)raw / (1 << scale);
}

int main() {
    struct gpiod_chip chip;
    struct i2c_dev i2c;
    struct sdp810_data data;
    FILE *log_file = NULL;

    gpiod_chip_init(0);
    if (gpiod_chip_open(&chip, "i2c-1") < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

