        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    if (i2c_rdwr(&i2c, SDP810_CMD_CONTINUOUS_MEAS, 1, NULL, 0) < 0) {
        fprintf(stderr, "Failed to configure continuous measurement\n");
        i2c_close(&i2c);
        gpiod_chip_close(&chip);
        return 1;
    }

    log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(&i2c);
        gpiod_chip_close(&chip);
        return 1;
    }

    if (fprintf(log_file, "timestamp,pressure,temperature\n") < 0) {
        fclose(log_file);
        i2c_close(&i2c);
        gpiod_chip_close(&chip);
        return 1;
    }

    while (1) {
        uint8_t pres_raw_buf[3];
        uint8_t temp_raw_buf[3];
        uint8_t pres_scale_buf[1];
        uint8_t temp_scale_buf[1];

        if (i2c_rdwr(&i2c, SDP810_CMD_MEASURE, 1, pres_raw_buf, sizeof(pres_raw_buf)) < 0) {
