        if (i2c_rdwr(&i2c, 0x00, 2, pres_scale_buf, sizeof(pres_scale_buf)) < 0) {
            fprintf(stderr, "Failed to read pressure scale\n");
            sleep(1);
            continue;
        }

        if (i2c_rdwr(&i2c, 0x00, 2, temp_scale_buf, sizeof(temp_scale_buf)) < 0) {
            fprintf(stderr, "Failed to read temperature scale\n");
            sleep(1);
            continue;
        }

        data.pres_raw = (pres_raw_buf[0] << 8) | pres_raw_buf[1];
        data.temp_raw = (temp_raw_buf[0] << 8) | temp_raw_buf[1];
        data.pres_scale = pres_scale_buf[0];
        data.temp_scale = temp_scale_buf[0];

        if (crc8(pres_raw_buf, 3) != pres_raw_buf[2]) {
            fprintf(stderr, "Invalid CRC for pressure data\n");
            continue;
