        if (crc8(temp_raw_buf, 3) != temp_raw_buf[2]) {
            fprintf(stderr, "Invalid CRC for temperature data\n");
            continue;
        }

        float pres, temp;
        convert_raw_to_value(data.pres_raw, data.pres_scale, &pres);
        convert_raw_to_value(data.temp_raw, data.temp_scale, &temp);

        char timestamp[24];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&errno));

        fprintf(log_file, "%s,%.6f,%.2f\n", timestamp, pres, temp);
        fclose(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2c_close(&i2c);
    gpiod_chip_close(&chip);

    return 0;
