volatile sig_atomic_t sigint_received = 0;

static FILE *log_file = NULL;
static gpiod_chip *chip;
static gpiod_line *i2c_sdat;
static gpiod_line *i2c_scl;

void sigint_handler(int signum) {
    sigint_received = 1;
