void setup_i2c(void) {
    chip = gpiod_chip_open("/dev/i2c-1", NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    i2c_sdat = gpiod_chip_get_line(chip, "SDA");
    i2c_scl = gpiod_chip_get_line(chip, "SCL");

    if (!i2c_sdat || !i2c_scl) {
        fprintf(stderr, "Failed to get I2C lines\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(i2c_sdat, "i2c-sdat");
    gpiod_line_export(i2c_scl, "i2c-scl");

    if (gpio_direction_input(i2c_sdat) || gpio_direction_input(i2c_scl)) {
        fprintf(stderr, "Failed to set I2C lines as input\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("airflow.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c(void) {
    fclose(log_file);
    gpiod_chip_put(chip);
}

uint16_t read_i2c_byte(uint8_t addr, uint8_t reg) {
    uint8_t data = 0;
    uint8_t retry = RETRY_COUNT;

    while (retry > 0) {
        gpio_set_value(i2c_sdat, 1);
        gpio_set_value(i2c_scl, 1);
        delay_ms(1);
        gpio_set_value(i2c_scl, 0);
        delay_ms(1);
        gpio_set_value(i2c_sdat, 0);
        delay_ms(1);

        if (gpio_get_value(i2c_sdat)) {
            data = gpio_get_value(i2c_scl);
            retry = 0;
        } else {
            delay_ms(1000 * (1 << retry));
        }
    }

    return data;
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_i2c();

    while (!sigint_received) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
                1900 + tm_info->tm_year, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                (read_i2c_byte(SENS_I2C_ADDR, TRIGGER_CMD) >> 4) * 16.53,
                (read_i2c_byte(SENS_I2C_ADDR, TRIGGER_CMD) & 0x0F) * 175 / 1000);
        fflush(log_file);

        delay_ms(100);
    }

    cleanup_i2c();
    return 0;
}

