#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpio.h>

#define SI7015_ADDR 0x44
#define I2C_BUS 1

struct si7015_data {
    int fd;
    int i2c_fd;
};

static int si7015_init(struct si7015_data *data) {
    int ret;

    ret = gpiod_in_init();
    if (ret < 0) {
        perror("Failed to initialize GPIO library");
        return ret;
    }

    ret = gpiod_chip_open(GPIOD_CHIP_I2C1, "i2c-1", 0);
    if (ret < 0) {
        gpiod_in_exit();
        perror("Failed to open I2C bus");
        return ret;
    }

    data->i2c_fd = ret;
    return 0;
}

static void si7015_cleanup(struct si7015_data *data) {
    gpiod_chip_close(data->i2c_fd);
    gpiod_in_exit();
}

static int si7015_read_data(struct si7015_data *data, uint8_t *buf, size_t len) {
    int ret;

    ret = gpiod_i2c_xfer(data->i2c_fd, SI7015_ADDR, NULL, 0, buf, len);
    if (ret < 0) {
        perror("Failed to perform I2C read");
        return ret;
    }

    return 0;
}

static int si7015_poll_ready(struct si7015_data *data) {
    uint8_t buf[2];
    int ret;

    ret = si7015_read_data(data, buf, 2);
    if (ret < 0)
        return ret;

    // Check the status register to see if the measurement is ready
    if ((buf[0] & 0x01) == 0)
        return 0;

    // Poll until ready
    while ((ret = si7015_read_data(data, buf, 2)) == 0) {
        if ((buf[0] & 0x01) != 0)
            break;
    }

    return ret;
}

static void sigint_handler(int signum) {
    si7015_cleanup(&si7015_data);
    exit(0);
}

int main() {
    struct si7015_data si7015_data;
    FILE *log_file;
    char timestamp[20];
    int ret;

    signal(SIGINT, sigint_handler);

    if (si7015_init(&si7015_data) < 0)
        return 1;

    log_file = fopen("sensor_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        si7015_cleanup(&si7015_data);
        return 1;
    }

    while (1) {
        gettimeofday(timestamp, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(timestamp));

        printf("%s: ", timestamp);

        ret = si7015_poll_ready(&si7015_data);
        if (ret < 0)
            break;

        uint8_t temp[2], humidity[2];
        ret = si7015_read_data(&si7015_data, temp, 2);
        if (ret < 0)
            break;

        ret = si7015_read_data(&si7015_data, humidity, 2);
        if (ret < 0)
            break;

        int16_t t = (int16_t)((temp[0] << 8) | temp[1]);
        int16_t h = (int16_t)((humidity[0] << 8) | humidity[1]);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", t / 10.0, h / 10.0);

        fprintf(log_file, "%s: Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, t / 10.0, h / 10.0);

        fflush(log_file);
        sleep(5);
    }

    si7015_cleanup(&si7015_data);
    fclose(log_file);
    return 0;
}

