#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define SDP800_I2C_ADDR 0x18
#define SDP800_CMD_TRIGGER 0x01
#define SDP800_REG_PRESS_LOW 0x28
#define SDP800_REG_PRESS_HIGH 0x29
#define SDP800_REG_TEMP_LOW 0x2A
#define SDP800_REG_TEMP_HIGH 0x2B
#define SDP800_REG_SF_LOW 0x2C
#define SDP800_REG_SF_HIGH 0x2D
#define SDP800_CRC_POLY 0x07
#define SDP800_CRC_INIT 0xFF
#define SDP800_DELAY_MS 45
#define SDP800_LOG_INTERVAL_MS 100

FILE *log_file = NULL;

void init_i2c(const char *dev) {
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("airflow_data.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
}

void cleanup() {
    fclose(log_file);
    close(fd);
}

uint8_t crc8(uint8_t *data, int len) {
    uint8_t crc = SDP800_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP800_CRC_POLY;
            } else {
                crc <<= 1;
            }
