#include <errno.h>

#define SENS_ADDR 0x44
#define CRC_POLY 0x31
#define CRC_INIT 0xFFFF

#define I2C_BUS "0"
#define TEMP_LOG "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

int i2c_fd = -1;
FILE *temp_log = NULL;
FILE *error_log = NULL;

void log_error(const char *msg) {
    if (error_log) {
        time_t now = time(NULL);
        fprintf(error_log, "%s: %s - %ld\n", asctime(localtime(&now)), msg, errno);
        fflush(error_log);
    }
}

uint8_t crc8(uint8_t *data, size_t len, uint8_t init_val, uint8_t poly) {
    uint8_t crc = init_val;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_temp_i2c(uint8_t *temp_data) {
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus\n");
        return -1;
    }

    if (write(i2c_fd, "S", 1) != 1) {
        log_error("Failed to send command to sensor\n");
        return -1;
    }

    if (ntohs(poll(i2c_fd, 150000, 0)) < 0) {
        log_error("Timeout waiting for conversion\n");
        return -1;
    }

    if (read(i2c_fd, temp_data, 3) != 3) {
        log_error("Failed to read from sensor\n");
        return -1;
    }

    uint8_t crc = temp_data[0] ^ temp_data[1] ^ temp_data[2];
    if (crc != crc8(temp_data, 3, CRC_INIT, CRC_POLY)) {
        log_error("CRC mismatch\n");
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip chip;
    gpiod_chip_init(&chip);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENS_ADDR) < 0) {
        close(fd);
        log_error("Failed to acquire bus access and/or talk to slave\n");
        return 1;
    }

    i2c_fd = fd;

    if ((temp_log = fopen(TEMP_LOG, "a")) == NULL) {
        log_error("Failed to open temperature log file\n");
        close(i2c_fd);
        return 1;
    }

    if ((error_log = fopen(ERROR_LOG, "a")) == NULL) {
        fclose(temp_log);
        log_error("Failed to open error log file\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t temp_data[3];
        if (read_temp_i2c(temp_data) < 0) {
            continue;
        }

        time_t now = time(NULL);
        fprintf(temp_log, "%s: %d.%03d - %d.%02d\n", asctime(localtime(&now)),
            temp_data[1] / 100, temp_data[1] % 100, temp_data[0], temp_data[2]);
        fflush(temp_log);
    }

    fclose(temp_log);
    fclose(error_log);
    close(i2c_fd);

    return 0;
}

