#include <libgpiod.h>
#include <wiringPiI2C.h>

#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define BUFFER_SIZE 60
#define I2C_RETRY_COUNT 3

typedef struct {
    float temp;
    time_t timestamp;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

void fan_control(float temp) {
    if (temp > TEMP_THRESHOLD_ON) {
        gpiod_device_apply_voltage(gpio, FAN_GPIO, 1);
    } else if (temp < TEMP_THRESHOLD_OFF) {
        gpiod_device_apply_voltage(gpio, FAN_GPIO, 0);
    }
}

int i2c_read(uint8_t reg, uint8_t *data, int count) {
    int retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        int ret = wiringPiI2CReadReg8(SI7021_ADDR, reg);
        if (ret >= 0) {
            for (int i = 0; i < count; i++) {
                data[i] = ret >> (8 * i);
            }
            return 0;
        }
        retries--;
        _delay_ms(10);
    }
    return -1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_chip_pq *pq;
    int ret;

    gpiod_chip_init(0);
    chip = gpiod_chip_find("GPIO18");
    if (!chip) {
        fprintf(stderr, "Failed to find GPIO18\n");
        return 1;
    }
    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO18\n");
        return 1;
    }
    pq = gpiod_line_to_pq(line);
    gpiod_chip_put(chip);

    ret = gpiod_add_override(pq, "fan_control", 0);
    if (ret) {
        fprintf(stderr, "Failed to add override for fan_control\n");
        return 1;
    }

    wiringPiI2CInit();
    wiringPiI2CSetBus(1);

    while (1) {
        uint8_t temp_msb, temp_lsb;
        int ret = i2c_read(0xF, &temp_msb, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            break;
        }
        ret = i2c_read(0xE, &temp_lsb, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            break;
        }

        float temp = (temp_msb << 8) | temp_lsb;
        temp *= 0.01; // Convert to Celsius

        fan_control(temp);

        buffer[buffer_index].temp = temp;
        buffer[buffer_index].timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        printf("%lu: %f\n", (unsigned long)buffer[buffer_index].timestamp, buffer[buffer_index].temp);

        _delay_ms(2000);
    }

    gpiod_remove_override(pq);
    gpiod_chip_uninit();
    wiringPiI2CClose();

    return 0;
}

