#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c.h>
#include <linux/i2c-dev.h>
#include <crc8.h>

#define SCD40_ADDR 0x60
#define SCD40_REG_CO2_RAW 0x80
#define SCD40_REG_TEMP_MSB 0x90
#define SCD40_REG_HUM_MSB 0xA0
#define SCD40_DATA_LEN 9
#define CRC_POLYNOMIAL 0x05
#define CRC_INIT 0xFFFF

static int i2c_fd = -1;
static struct gpiod_chip chip;

void log_data(const char *timestamp, uint16_t co2_ppm, float temperature, float humidity) {
    char line[100];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);

    strftime(line, sizeof(line), "%F %T", time_struct);
    sprintf(line + strlen(line), ",%u,%.2f,%.1f\n", co2_ppm, temperature, humidity);

    if (write(STDOUT_FILENO, line, strlen(line)) != strlen(line)) {
        perror("Failed to write to stdout");
    }
}

uint16_t read_word(const uint8_t *data, int index) {
    return (data[index] << 8) | data[index + 1];
}

uint8_t crc8(const uint8_t *data, size_t length) {
    return crc8_calc(CRC_INIT, CRC_POLYNOMIAL, data, length);
}

int main() {
    struct gpiod_chip_params params = {
        .gpio_chip_class = "i2c",
        .gpios = {GPIO_I2C_SCL, GPIO_I2C_SDA},
    };

    int ret;

    ret = gpiod_chip_new(&chip, "i2c", &params);
    if (ret) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return ret;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus for SCD40\n");
        close(i2c_fd);
        return -1;
    }

    uint8_t cmd[2] = {0x06, 0x00}; // Start periodic measurement

    if (write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send command to SCD40\n");
        close(i2c_fd);
        return -1;
    }

    sleep(1);

    FILE *log_file = fopen("air_quality.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        return -1;
    }

    while (1) {
        uint8_t data[SCD40_DATA_LEN];
        int data_ready = 0;

        if (ioctl(i2c_fd, I2C_RDWR, NULL) < 0) {
            fprintf(stderr, "Failed to initiate I2C read\n");
            break;
        }

        data_ready = ioctl(i2c_fd, I2C_RDWR, data);

        if (data_ready < 0) {
            fprintf(stderr, "Failed to read from SCD40\n");
            break;
        }

        if (data_ready != SCD40_DATA_LEN) {
            fprintf(stderr, "Unexpected data length from SCD40\n");
            break;
        }

        if (crc8((const uint8_t *)data, SCD40_DATA_LEN - 2) != data[SCD40_DATA_LEN - 2]) {
            fprintf(stderr, "CRC check failed\n");
            break;
        }

        uint16_t co2_ppm = read_word(data, SCD40_REG_CO2_RAW);
        float temperature = (float)read_word(data, SCD40_REG_TEMP_MSB) / 100.0;
        float humidity = (float)read_word(data, SCD40_REG_HUM_MSB) / 100.0;

        log_data(asctime(localtime(NULL)), co2_ppm, temperature, humidity);

        if (sigismember(&{.sa_mask = {SIGINT}}, &{.sa_mask = {SIGINT}})) {
            break;
        }
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_put(chip);

    return 0;
}

