#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define SCD40_ADDR 0x60
#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000
#define CHECKSUM_POLYNOMIAL 0x31

typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

void sigint_handler(int signum, siginfo_t *info, void *context) {
    printf("Received SIGINT or SIGTERM, cleaning up...\n");
    gpiod_unbind(led_chip, led_id);
    i2c_close(i2c_fd);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_sigaction = sigint_handler;
    sa.sa_flags = SA_SIGINFO;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = i2c_open(0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    int led_fd = gpiod_export(NULL, "GPIO17");
    if (!led_fd) {
        perror("Failed to export GPIO17");
        i2c_close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_export_get_chip(led_fd);
    if (!chip) {
        perror("Failed to get chip for GPIO17");
        gpiod_unexport(led_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, 0);
    if (!led_line) {
        perror("Failed to get line for GPIO17");
        gpiod_unexport(led_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    gpiod_add_event(led_line, true, GPIO_FALLING_EDGE, 0, sigint_handler);

    if (i2c_slave_address_slave(i2c_fd, SCD40_ADDR) < 0) {
        perror("Failed to set slave address");
        gpiod_unexport(led_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t data[6];
        int bytes_read;

        if ((bytes_read = i2c_rdwr(i2c_fd, &data, 6, NULL, 0)) < 0) {
            if (errno == EBUSY) {
                printf("I2C bus error, trying again in 5 seconds...\n");
                sleep(5);
                continue;
            }
            perror("Failed to read from I2C bus");
            break;
        }

        if (bytes_read != 6) {
            fprintf(stderr, "Unexpected number of bytes read: %d\n", bytes_read);
            break;
        }

