#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define TMP05_GPIO 4
#define SAMPLE_INTERVAL_SEC 5
#define EDGE_WAIT_TIMEOUT_MS 50
#define ERROR_THRESHOLD 3

struct TempReading {
    time_t timestamp;
    float temperature;
};

static bool log_file_opened = false;
static int error_count = 0;

static int init_tmp05_sensor() {
    struct gpiod_chip_params params;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    ret = gpiod_chip_params_new(&params);
    if (ret < 0) {
        fprintf(stderr, "Failed to create gpiod_chip_params\n");
        return ret;
    }

    params.line_type = GPIOD_LINE_OUTPUT;
    params.request_type = GPIO_REQUEST_OUTPUT;
    params.flags = GPIO_LINE_OPEN_DRAIN;
    params.pin = TMP05_GPIO;

    ret = gpiod_chip_new(&chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to create gpiod_chip\n");
        gpiod_chip_params_free(&params);
        return ret;
    }

    ret = gpiod_chip_add_params(chip, &params);
    gpiod_chip_params_free(&params);

    if (ret < 0) {
        fprintf(stderr, "Failed to add line to chip\n");
        gpiod_chip_put(chip);
        return ret;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        fprintf(stderr, "Failed to get line from chip\n");
        gpiod_chip_put(chip);
        return -1;
    }

    ret = gpiod_line_request_add(line, "tmp05_temp_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line\n");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return ret;
    }

    return 0;
}

static void cleanup_tmp05_sensor(void) {
    struct gpiod_line *line;
    struct gpiod_chip *chip;

    line = gpiod_line_from_name(gpiod_chip_get_name(gpiod_chip_get_parent(gpiod_chip_get_line_parent(gpiod_line_get_line(gpiod_line_get_request_source()))), TMP05_GPIO), "tmp05_temp_sensor");
    if (!line) {
        fprintf(stderr, "Failed to get line from name\n");
        return;
    }

    chip = gpiod_line_get_chip(line);
    gpiod_line_release(line);
    gpiod_chip_put(chip);
}

static int read_temperature(struct TempReading *reading) {
    struct gpiod_timestamp ts_high, ts_low;
    uint64_t cycle_width_us;
    uint32_t high_pulse_width_ns;
    int ret;

    ret = gpiod_timestamp_init(&ts_high, &ts_low);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize timestamps\n");
        return ret;
    }

    ret = gpiod_read(line, &ts_high, &ts_low);
    if (ret < 0) {
        fprintf(stderr, "Failed to read timestamps\n");
        gpiod_timestamp_free(&ts_high);
        gpiod_timestamp_free(&ts_low);
        return ret;
    }

    high_pulse_width_ns = (uint32_t)((ts_high.tv_sec - ts_low.tv_sec) * 1000000000 + (ts_high.tv_nsec - ts_low.tv_nsec));
    cycle_width_us = (uint64_t)(high_pulse_width_ns / 1000);

    gpiod_timestamp_free(&ts_high);
    gpiod_timestamp_free(&ts_low);

    // TMP05 temperature calculation
    // Assuming a 13-bit resolution and a 1.8V reference voltage
    reading->temperature = (float)(cycle_width_us * 1.8 / 4096) * 100;

    return 0;
}

static void log_reading(const struct TempReading *reading) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    if (!log_file_opened) {
        log_file_opened = true;
        fprintf(log_file, "Timestamp,Temperature\n");
    }

    fprintf(log_file, "%ld,%.2f\n", (long)(reading->timestamp.tv_sec * 1000000 + reading->timestamp.tv_nsec / 1000), reading->temperature);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    struct gpiod_line *line;
    struct TempReading reading;
    int ret;

    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    ret = init_tmp05_sensor();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize TMP05 sensor\n");
        return ret;
    }

    line = gpiod_line_from_name(gpiod_chip_get_name(gpiod_chip_get_parent(gpiod_line_get_line_parent(gpiod_line_get_request_source())), TMP05_GPIO), "tmp05_temp_sensor");
    if (!line) {
        fprintf(stderr, "Failed to get line from name\n");
        cleanup_tmp05_sensor();
        return -1;
    }

    while (true) {
        ret = read_temperature(&reading);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            break;
        }

        log_reading(&reading);

        if (reading.temperature < -40 || reading.temperature > 150) {
            error_count++;
            if (error_count >= ERROR_THRESHOLD) {
                fprintf(stderr, "SENSOR MALFUNCTION\n");
                break;
            }
        } else {
            error_count = 0;
        }

        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup_handler(SIGINT);
    cleanup_handler(SIGTERM);
    cleanup_tmp05_sensor();

    return 0;
}

static void cleanup_handler(int signum) {
    cleanup_tmp05_sensor();
    if (log_file_opened) {
        fclose("temperature_log.txt");
        log_file_opened = false;
    }
}

