#define RETRY_DELAY 1

struct sht35_data {
    int fd;
    int retry_count;
};

static int sht35_read(struct sht35_data *data, uint8_t *buf, size_t len) {
    int ret;
    for (size_t i = 0; i < len; ++i) {
        ret = gpiod_iomap(data->fd);
        if (ret < 0) {
            fprintf(stderr, "Failed to iomap: %s\n", strerror(errno));
            return -1;
        }

        ret = gpiod_bulk_read(data->fd, buf + i, len - i);
        if (ret < 0) {
            fprintf(stderr, "Failed to read: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static uint16_t sht35_crc(const uint8_t *data, size_t len) {
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i] << 0;
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ SHT35_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static float sht35_temp_humidity(uint16_t temp, uint16_t hum) {
    float t = (float)temp * 0.01 - 45.0;
    float h = (float)hum * 0.01;
    return t + sin(M_PI * 2 * time(NULL) / 3600) * 2, h + sin(M_PI * 2 * time(NULL) / 3600) * 5;
}

static void signal_handler(int signum) {
    (void)signum;
    if (data.fd != -1) {
        gpiod_unmap(data.fd);
        data.fd = -1;
    }
}

int main() {
    struct sht35_data data = {0};
    int ret;
    int log_fd;
    char timestamp[32];

    ret = gpiod_new(&data.fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to create gpiod handle: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_add_override(data.fd, "I2C1_SDA", "value", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to add I2C1_SDA override: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_add_override(data.fd, "I2C1_SCL", "value", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to add I2C1_SCL override: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_iomap(data.fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to iomap: %s\n", strerror(errno));
        return 1;
    }

    if ((log_fd = open(SENSORS_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(NULL));

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        data.retry_count = 0;
        uint8_t buf[6];

        if (sht35_read(&data, buf, sizeof(buf)) < 0) {
            for (int i = 0; i < RETRY_COUNT; ++i) {
                if (sleep(RETRY_DELAY) == 0) {
                    fprintf(stderr, "Interrupted while waiting\n");
                    return 1;
                }
            }
            fprintf(stderr, "Failed to read from SHT35 after retries\n");
            for (size_t i = 0; i < sizeof(buf); ++i) {
                printf("%02X ", buf[i]);
            }
            printf("\n");
            fprintf(stderr, "Logging NaN values\n");
            printf("NaN,NaN\n");
            fflush(stdout);
            continue;
        }

        if (sht35_crc(&buf[1], 5) != buf[0]) {
            for (int i = 0; i < RETRY_COUNT; ++i) {
                if (sleep(RETRY_DELAY) == 0) {
                    fprintf(stderr, "Interrupted while waiting\n");
                    return 1;
                }
            }
            fprintf(stderr, "CRC check failed after retries\n");
            for (size_t i = 0; i < sizeof(buf); ++i) {
                printf("%02X ", buf[i]);
            }
            printf("\n");
            fprintf(stderr, "Logging NaN values\n");
            printf("NaN,NaN\n");
            fflush(stdout);
            continue;
        }

        uint16_t temp = (buf[1] << 8) | buf[2];
        uint16_t hum = (buf[3] << 8) | buf[4];

        float t, h;
        t = sht35_temp_humidity(temp, hum);

        if (fputs(timestamp, stdout) != 1 || fputc('\n', stdout) != '\n') {
            fprintf(stderr, "Failed to print timestamp\n");
            return 1;
        }

        if (fputs(sprintf("%.2f,%.2f\n", t, h), stdout) != 2) {
            fprintf(stderr, "Failed to print temperature and humidity\n");
            return 1;
        }

        if (fputs(sprintf("%.2f,%.2f\n", t, h), stderr) != 2) {
            fprintf(stderr, "Failed to print temperature and humidity to stderr\n");
            return 1;
        }

        if (write(log_fd, sprintf("%.2f,%.2f\n", t, h), strlen(sprintf("%.2f,%.2f\n", t, h))) != strlen(sprintf("%.2f,%.2f\n", t, h))) {
            fprintf(stderr, "Failed to write to log file\n");
            return 1;
        }

        data.retry_count = 0;
    }

    gpiod_unmap(data.fd);
    close(log_fd);
    return 0;
}
