        perror("Failed to open file");
        close(fd);
        gpiod_unexport(NULL);
        return 1;
    }

    while (1) {
        // Send command to start continuous measurement
        write(fd, &SDP810_REG_MEAS_CONT, 1);

        // Wait for approximately 45 ms
        usleep(45000);

        // Read 9-byte block including CRC
        read(fd, &data, 9);

        // Validate CRC
        if (crc8(&data, 8) != data[8]) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        convert_raw_to_pressure_temp(&data);

        // Get timestamp
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log to CSV
        fprintf(fp, "%s,%d,%d\n", timestamp, data.pressure, data.temp);
        fflour(fp);

        // Sleep for 1 second
        sleep(1);
    }

    fclose(fp);
    close(fd);
    gpiod_unexport(NULL);

    return 0;
}

