#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define SHT35_I2C_ADDR 0x44
#define SHT35_CMD_MEASURE 0xF5
#define SHT35_CRC8_POLY 0x05
#define SHT35_CRC8_INIT 0xFF
#define SHT35_MEAS_DELAY_US 15000
#define SHT35_SAMPLE_INTERVAL_S 5
#define FILE_NAME "environment.csv"

struct sht35_data {
    gpiod_chip chip;
    gpiod_context *ctx;
    int fd;
};

bool write_header(FILE *file) {
    if (fputs("Timestamp,Temperature (C),Relative Humidity (%)\n", file) == EOF) {
        fprintf(stderr, "Error writing header to file\n");
        return false;
    }
    return true;
}

bool read_crc8(uint8_t *data, int len) {
    uint8_t crc = SHT35_CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc ^= SHT35_CRC8_POLY;
            }
            crc >>= 1;
        }
    }
    return crc == 0;
}

int main() {
    struct sht35_data sht35;
    FILE *file = fopen(FILE_NAME, "a");

    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiod_in_init() < 0) {
        fprintf(stderr, "Error initializing gpiod\n");
        fclose(file);
        return EXIT_FAILURE;
    }

    sht35.ctx = gpiod_in_get_default_context();
    sht35.fd = gpiod_in_open(sht35.ctx, "i2c-1", 0, 0);
    if (!sht35.fd) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpiod_in_free(sht35.ctx);
        fclose(file);
        return EXIT_FAILURE;
    }

    if (gpiod_in_export(sht35.ctx, sht35.fd) < 0) {
        fprintf(stderr, "Error exporting I2C device\n");
        gpiod_in_unexport(sht35.ctx, sht35.fd);
        gpiod_in_free(sht35.ctx);
        fclose(file);
        return EXIT_FAILURE;
    }

    sht35.chip = gpiod_chip_get(sht35.ctx, sht35.fd);
    if (!sht35.chip) {
        fprintf(stderr, "Error getting chip\n");
        gpiod_in_unexport(sht35.ctx, sht35.fd);
        gpiod_in_free(sht35.ctx);
        fclose(file);
        return EXIT_FAILURE;
    }

    gpiod_chip_set_owner(sht35.chip, GPIOD_IN_OUT, 1);

    signal(SIGINT, [](int) {
        gpiod_in_unexport(sht35.ctx, sht35.fd);
        gpiod_in_free(sht35.ctx);
        fclose(file);
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int) {
        gpiod_in_unexport(sht35.ctx, sht35.fd);
        gpiod_in_free(sht35.ctx);
        fclose(file);
        exit(EXIT_SUCCESS);
    });

    while (1) {
        uint8_t cmd[2] = {SHT35_CMD_MEASURE, 0x00};
        gpiod_batch_begin();
        gpiod_chip_write(sht35.chip, cmd, sizeof(cmd));
        gpiod_batch_end();

        sleep(SHT35_SAMPLE_INTERVAL_S);

        uint8_t data[6];
        gpiod_batch_begin();
        gpiod_chip_read(sht35.chip, data, sizeof(data));
        gpiod_batch_end();

        if (!read_crc8(data, sizeof(data))) {
            fprintf(stderr, "Error: CRC validation failed\n");
            continue;
        }

        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));

        fprintf(file, "%s,%.2f,%.2f\n", timestamp, data[1] / 10.0, data[2] * 16.0);
        fflush(file);
    }

    gpiod_in_unexport(sht35.ctx, sht35.fd);
    gpiod_in_free(sht35.ctx);
    fclose(file);

    return EXIT_SUCCESS;
}

