#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define SI7021_ADDR 0x40
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

struct si7021_data {
    uint8_t humidity_msb;
    uint8_t humidity_lsb;
    uint8_t humidity_crc;
    uint8_t temperature_msb;
    uint8_t temperature_lsb;
    uint8_t temperature_crc;
};

static int si7021_i2c_read(int fd, struct si7021_data *data) {
    uint8_t buf[3];

    if (gpiod_iomap(get_default(), "i2c-1")) {
        perror("Failed to map I2C bus 1");
        return -1;
    }

    if (gpiod_pullup(get_default(), 2)) {
        perror("Failed to enable pull-up on SDA");
        return -1;
    }

    if (gpiod_pullup(get_default(), 3)) {
        perror("Failed to enable pull-up on SCL");
        return -1;
    }

    if (write(fd, &SI7021_ADDR, 1) != 1) {
        perror("Failed to write SI7021 address");
        return -1;
    }

    if (read(fd, buf, 3) != 3) {
        perror("Failed to read SI7021 data");
        return -1;
    }

    if (buf[0] != 0x06 || buf[1] != 0x20) {
        fprintf(stderr, "ERROR: Incorrect response from sensor\n");
        return -1;
    }

    data->humidity_msb = buf[1];
    data->humidity_lsb = buf[2];
    data->humidity_crc = buf[0];

    if (crc8((uint8_t *)data->humidity_msb, 1, CRC_POLY, CRC_INIT) != data->humidity_crc) {
        fprintf(stderr, "ERROR: Humidity CRC mismatch\n");
        return -1;
    }

    if (read(fd, buf, 3) != 3) {
        perror("Failed to read SI7021 data");
        return -1;
    }

    data->temperature_msb = buf[1];
    data->temperature_lsb = buf[2];
    data->temperature_crc = buf[0];

    if (crc8((uint8_t *)data->temperature_msb, 1, CRC_POLY, CRC_INIT) != data->temperature_crc) {
        fprintf(stderr, "ERROR: Temperature CRC mismatch\n");
        return -1;
    }

    return 0;
}

