#include <gpiod.h>

#define SDP810_I2C_ADDR 0x77
#define SDP810_CMD_MEASURE 0x01
#define SDP810_CRC_POLYNOMIAL 0x07
#define SDP810_PRESSURE_MSB_INDEX 0
#define SDP810_PRESSURE_LSB_INDEX 1
#define SDP810_TEMP_MSB_INDEX 2
#define SDP810_TEMP_LSB_INDEX 3
#define SDP810_SCALE_FACTOR_INDEXES {0x04, 0x05, 0x06}
#define SDP810_CRC_SIZE 1
#define SDP810_DATA_SIZE (9 - SDP810_CRC_SIZE)

struct sdp810_sample {
    float pressure;
    float temperature;
};

int i2c_fd = -1;
int file_fd = -1;
FILE *file_handle = NULL;

void sigint_handler(int signum, siginfo_t *info, void *context) {
    gpiod_put(gpio);
    close(i2c_fd);
    close(file_fd);
    exit(signum == SIGINT ? 0 : 1);
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

uint8_t sdp810_crc8(uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

bool validate_crc(uint8_t *data, size_t length) {
    uint8_t crc = sdp810_crc8(data, length - SDP810_CRC_SIZE);
    for (size_t i = 0; i < SDP810_CRC_SIZE; i++) {
        if (data[length - SDP180_CRC_SIZE + i] != crc) {
            return false;
        }
    }
    return true;
}

float sdp810_raw_to_pressure(uint16_t raw_pressure) {
    // Implement conversion formula based on SDP810 datasheet
    return (float)raw_pressure / 16.0;
}

float sdp810_raw_to_temperature(int16_t raw_temperature) {
    // Implement conversion formula based on SDP810 datasheet
    return (float)raw_temperature / 100.0;
}

int main() {
    struct sigaction sa;
    sa.sa_sigaction = sigint_handler;
    sa.sa_flags = SA_SIGINFO;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return 1;
    }

    if (init_i2c() < 0) {
        return 1;
    }

    file_fd = open("airflow.dat", OMF_BINARY | O_CREAT | O_TRUNC, 0644);
    if (file_fd < 0) {
        perror("Failed to open airflow.dat");
        close(i2c_fd);
        return 1;
    }

    file_handle = fdopen(file_fd, "wb");
    if (!file_handle) {
        perror("Failed to fdopen airflow.dat");
        close(i2c_fd);
        close(file_fd);
        return 1;
    }

    uint8_t buffer[SDP810_DATA_SIZE];
    while (1) {
        // Initiate measurement
        write(i2c_fd, &SDP810_CMD_MEASURE, 1);

        // Wait for conversion
        usleep(1000000); // Wait 1 second

        // Read response
        if (read(i2c_fd, buffer, SDP810_DATA_SIZE) != SDP810_DATA_SIZE) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            break;
        }

        // Validate CRC
        if (!validate_crc(buffer, SDP810_DATA_SIZE)) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        struct sdp810_sample sample;
        sample.pressure = sdp810_raw_to_pressure(
            (buffer[SDP810_PRESSURE_MSB_INDEX] << 8) | buffer[SDP810_PRESSURE_LSB_INDEX]
        );
        sample.temperature = sdp810_raw_to_temperature(
            (int16_t)(
                (buffer[SDP810_TEMP_MSB_INDEX] << 8) | buffer[SDP810_TEMP_LSB_INDEX]
            )
        );

        // Write sample to file
        if (fwrite(&sample, sizeof(struct sdp810_sample), 1, file_handle) != 1) {
            fprintf(stderr, "Failed to write to airflow.dat\n");
            break;
        }
    }

    fclose(file_handle);
    close(i2c_fd);
    close(file_fd);

    return 0;
}

