#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpio.h>

#define SDP800_I2C_ADDR 0x48
#define SDP800_REG_MEASURE 0x00
#define SDP800_REG_CTRL_A 0x01
#define SDP800_REG_CTRL_B 0x02
#define SDP800_CONVERSION_TIME 45
#define CRC_POLYNOMIAL 0x31

#define LOG_FILE "pressure_log.txt"

struct sdp800_data {
    int16_t pressure_pa;
    uint8_t crc;
};

static FILE *log_file = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerminate();
        fclose(log_file);
    }
}

int i2c_read(uint8_t reg, struct sdp800_data *data) {
    int ret;
    uint8_t buf[9];
    uint8_t i;

    ret = gpio_i2c_read_reg(SDP800_I2C_ADDR, reg, buf, 9);
    if (ret < 0) {
        fprintf(stderr, "I2C read error\n");
        return ret;
    }

    for (i = 0; i < 8; i++) {
        data->pressure_pa = (data->pressure_pa << 8) | buf[i];
        if (i < 7) {
            data->crc = buf[i + 1];
        }
    }

    if (crc_calc(data->pressure_pa, 8, data->crc) != data->crc) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    return 0;
}

uint8_t crc_calc(uint8_t *data, uint8_t len, uint8_t crc) {
    uint8_t i;
    crc = 0;
    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc >>= 1;
                crc ^= CRC_POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    gpio_context *ctx;
    struct sdp800_data data;
    int ret;

    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    ctx = gpio_init();
    if (!ctx) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    log_file = fopen("pressure_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        ret = gpio_i2c_init(ctx, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to initialize I2C bus 1\n");
            gpioTerminate();
            fclose(log_file);
            return 1;
        }

        gpio_i2c_write_reg(ctx, SDP800_I2C_ADDR, SDP800_REG_CTRL_A, 0x80);
        gpio_i2c_write_reg(ctx, SDP800_I2C_ADDR, SDP800_REG_CTRL_B, 0x00);

        gpio_i2c_write_reg(ctx, SDP800_I2C_ADDR, SDP800_REG_MEASURE, 0x01);

        usleep(SDP800_CONVERSION_TIME * 1000);

        ret = i2c_read(SDP800_REG_MEASURE, &data);
        if (ret < 0) {
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d\n", now, data.pressure_pa);
        fflush(log_file);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

