#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <stdatomic.h>
#include <libgpiod.h>
#include <lps33hw.h>

volatile sig_atomic_t running = 1;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip_params params = {
        .gpiochip_fd = -1,
        .gpiod_chip_flags = 0,
    };

    struct gpiod_chip *chip;
    int r = gpiod_chip_open(&params, "i2c-1");
    if (r < 0) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return r;
    }

    chip = gpiod_chip_get(params.gpiochip_fd);
    if (!chip) {
        fprintf(stderr, "Failed to get I2C chip\n");
        gpiod_chip_put(params.gpiochip_fd);
        return -1;
    }

    struct lps33hw_dev dev;
    r = lps33hw_init(&dev, chip);
    if (r < 0) {
        fprintf(stderr, "Failed to initialize LPS33HW\n");
        gpiod_chip_put(params.gpiochip_fd);
        return r;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        lps33hw_deinit(&dev);
        gpiod_chip_put(params.gpiochip_fd);
        return -1;
    }

    signal(SIGINT, sigint_handler);

    struct timespec last_time = {0, 0};
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    while (running) {
        if (current_time.tv_sec - last_time.tv_sec >= 1) {
            last_time = current_time;

            int pressure_valid, temp_valid;
            int r = lps33hw_read(&dev, &pressure_valid, &temp_valid);
            if (r < 0) {
                fprintf(stderr, "Failed to read from LPS33HW\n");
                fflush(log_file);
                continue;
            }

            if (pressure_valid && temp_valid) {
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa, Temperature: %.2f °C\n",
                        current_time.tv_sec / 31536000,
                        current_time.tv_sec % 31536000 / 86400,
                        current_time.tv_sec % 86400 / 3600,
                        current_time.tv_sec % 3600 / 60,
                        current_time.tv_sec % 60,
                        dev.pressure / 100.0,
                        dev.temperature / 100.0);
                fflush(log_file);
            }
        }

        sleep(1);
    }

    fclose(log_file);
    lps33hw_deinit(&dev);
    gpiod_chip_put(params.gpiochip_fd);

    return 0;
}

