#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <libiio.h>

#define BUFFER_SIZE 10
#define LED_GPIO 17
#define TEMP_THRESHOLD 28.0

struct temp_data {
    float temp;
    float avg;
};

struct temp_data buffer[BUFFER_SIZE];
int buffer_index = 0;
float running_avg = 0.0;

int led_state = 0;

void led_init() {
    int ret;
    ret = gpiod_in_init(LED_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize LED GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpiod_chip *chip = gpiod_in_get_chip(LED_GPIO);
    gpiod_line *line = gpiod_chip_get_line(chip, 0);
    gpiod_set_value(line, 0);
}

float read_temperature(struct iio_dev *dev) {
    struct iio_trigger *trigger;
    int ret;

    trigger = iio_trigger_find(dev, "on_change");
    if (!trigger) {
        fprintf(stderr, "Failed to find 'on_change' trigger\n");
        return -1;
    }

    ret = iio_trigger_start(trigger);
    if (ret < 0) {
        fprintf(stderr, "Failed to start 'on_change' trigger\n");
        return -1;
    }

    sleep(1);

    ret = iio_trigger_stop(trigger);
    if (ret < 0) {
        fprintf(stderr, "Failed to stop 'on_change' trigger\n");
        return -1;
    }

    return iio_read_reg_u32(dev, "temp_value");
}

void update_buffer(float temp) {
    buffer[buffer_index].temp = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    running_avg = (running_avg * (BUFFER_SIZE - 1) + temp) / BUFFER_SIZE;
}

void toggle_led() {
    led_state = !led_state;
    gpiod_set_value(led_line, led_state);
}

int main() {
    struct iio_dev *dev;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;

    led_init();
    chip = gpiod_in_get_chip(LED_GPIO);
    led_line = gpiod_chip_get_line(chip, 0);

    dev = iio_get_device_by_type(NULL, IIO_TYPE_TEMP);
    if (!dev) {
        fprintf(stderr, "Failed to find temperature device\n");
        return EXIT_FAILURE;
    }

    if (iio_device_is_ready(dev) < 0) {
        fprintf(stderr, "Temperature device is not ready\n");
        return EXIT_FAILURE;
    }

    while (1) {
        float temp = read_temperature(dev);
        if (temp >= 0) {
            update_buffer(temp);
            if (running_avg > TEMP_THRESHOLD) {
                toggle_led();
            } else {
                toggle_led();
            }
        }

        usleep(1000000);
    }

    gpiod_drain(led_line);
    iio_device_put(dev);
    return EXIT_SUCCESS;
}

