#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_ADDR_SCD30 0x60
#define SAMPLE_INTERVAL 5000000 // 5 seconds

struct sensor_data {
    double co2;
    float temp;
    float hum;
};

FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <i2c-bus>\n", argv[0]);
        return 1;
    }

    const char *i2c_bus = argv[1];
    if (strstr(i2c_bus, "mock")) {
        fprintf(stderr, "No hardware detected, exiting gracefully.\n");
        return 0;
    }

    int i2c_fd = gpiod_i2c_open(i2c_bus);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (pigpio_initialise() < 0) {
        gpiod_i2c_close(i2c_fd);
        perror("Failed to initialize pigpio library");
        return 1;
    }

    log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        gpiod_i2c_close(i2c_fd);
        perror("Failed to open log file");
        return 1;
    }

    while (true) {
        struct sensor_data data;
        int rc;

        // Read CO2, temperature, and humidity from SCD30
        rc = pigpio_i2c_read_reg_uint16(i2c_fd, I2C_ADDR_SCD30, 0x00, &data.co2);
        if (rc < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        rc = pigpio_i2c_read_reg_uint16(i2c_fd, I2C_ADDR_SCD30, 0x01, &data.temp);
        if (rc < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        rc = pigpio_i2c_read_reg_uint16(i2c_fd, I2C_ADDR_SCD30, 0x02, &data.hum);
        if (rc < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Ventilation control logic
        char *vent_state;
        if (data.co2 < 800) {
            vent_state = "OFF";
        } else if (data.co2 < 1200) {
            vent_state = "LOW";
        } else {
            vent_state = "HIGH";
        }

        // Write data to log file
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now));

        fprintf(log_file, "%s,%.2f,%.1f,%.1f\n", timestamp, data.co2, data.temp, data.hum);
        fflush(log_file);

        // Sleep for the sample interval
        struct timespec ts;
        ts.tv_sec = SAMPLE_INTERVAL / 1000;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    gpiod_i2c_close(i2c_fd);
    pigpio_terminate();
    fclose(log_file);

    return 0;
}

