#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define SDP32_ADDR 0x5C
#define SAMPLING_INTERVAL_DEFAULT 1000

struct sdp32_data {
    uint16_t pressure_msb;
    uint16_t pressure_lsb;
    uint8_t pressure_crc8;
    uint16_t temperature_msb;
    uint16_t temperature_lsb;
    uint8_t temperature_crc8;
    uint16_t scale_factor_msb;
    uint16_t scale_factor_lsb;
    uint8_t scale_factor_crc8;
};

struct sdp32_data read_sdp32(int fd);
uint8_t crc8(uint8_t *data, size_t len);

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    struct sdp32_data data;
    int fd;
    int sampling_interval = SAMPLING_INTERVAL_DEFAULT;

    // Initialize signal handlers
    if (signal(SIGINT, sigint_handler) == SIG_ERR || signal(SIGTERM, sigterm_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install signal handlers\n");
        return 1;
    }

    // Parse command-line argument for sampling interval
    if (argc > 1) {
        sampling_interval = atoi(argv[1]);
        if (sampling_interval <= 0) {
            fprintf(stderr, "Invalid sampling interval: %s\n", argv[1]);
            return 1;
        }
    }

    // Initialize GPIO for I2C
    struct gpiod_chip *chip;
    struct gpiod_line *i2c_sdat;
    struct gpiod_line *i2c_scl;
    int ret = gpiod_chip_open(&chip, "i2c-0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return ret;
    }

    i2c_sdat = gpiod_chip_get_line(chip, "i2c-0", 2);
    i2c_scl = gpiod_chip_get_line(chip, "i2c-0", 3);

    if (!i2c_sdat || !i2c_scl) {
        fprintf(stderr, "Failed to get I2C lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_export(i2c_sdat, "i2c-0") < 0 || gpiod_line_export(i2c_scl, "i2c-0") < 0) {
        fprintf(stderr, "Failed to export I2C lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    fd = open("/dev/i2c-0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_line_unexport(i2c_sdat);
        gpiod_line_unexport(i2c_scl);
        gpiod_chip_close(chip);
        return 1;
    }

    // Wait for sensor connection
    if (i2c_start(fd, SDP32_ADDR | 0) < 0 || i2c_rdwr(fd, &data, 9) < 0 || i2c_stop(fd) < 0) {
        fprintf(stderr, "Sensor not connected or I2C error\n");
        gpiod_line_unexport(i2c_sdat);
        gpiod_line_unexport(i2c_scl);
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        data = read_sdp32(fd);

        if (crc8(&data.pressure_msb, 2) != data.pressure_crc8 ||
            crc8(&data.temperature_msb, 2) != data.temperature_crc8 ||
            crc8(&data.scale_factor_msb, 2) != data.scale_factor_crc8) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        printf("Timestamp: %lu, Pressure: %04X%04X (%d Pa), Temperature: %04X%04X (%d °C), Scale Factor: %04X%04X\n",
                time(NULL), data.pressure_msb, data.pressure_lsb, data.pressure_msb << 8 | data.pressure_lsb,
                data.temperature_msb, data.temperature_lsb, data.temperature_msb << 8 | data.temperature_lsb,
                data.scale_factor_msb, data.scale_factor_lsb, data.scale_factor_msb << 8 | data.scale_factor_lsb);

        sleep_ms(sampling_interval);
    }

    // Clean up
    gpiod_line_unexport(i2c_sdat);
    gpiod_line_unexport(i2c_scl);
    gpiod_chip_close(chip);
    close(fd);

    return 0;
}

struct sdp32_data read_sdp32(int fd) {
    struct sdp32_data data;
    uint8_t buf[9];

    if (i2c_start(fd, SDP32_ADDR | 0) < 0) {
        return (struct sdp32_data) {0};
    }

    if (i2c_rdwr(fd, buf, 9) < 0) {
        return (struct sdp32_data) {0};
    }

    if (i2c_stop(fd) < 0) {
        return (struct sdp32_data) {0};
    }

    memcpy(&data, buf, sizeof(data));
    return data;
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc <<= 1;
            if (crc & 0x80) {
                crc ^= 0x07;
            } else {
                crc++;
            }
        }
    }
    return crc;
}

