#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpio.h>

#define SDP810_I2C_ADDR 0x77
#define CRC_POLYNOMIAL 0x07
#define CRC_INIT_VALUE 0xFF

#define CRC8(data, length, init_value, polynomial) \
    do { \
        unsigned char crc = init_value; \
        for (int i = 0; i < length; i++) { \
            crc ^= (data[i] << 8); \
            for (int j = 0; j < 8; j++) { \
                if (crc & 0x8000) { \
                    crc ^= polynomial; \
                } else { \
                    crc <<= 1; \
                } \
            } \
        } \
    } while(0)

static int i2c_fd = -1;
static struct gpio *sd_scl, *sd_sda;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpio_free();
}

int main() {
    gpio_init();
    sd_scl = gpio_request(3, "GPIO SCL");
    sd_sda = gpio_request(2, "GPIO SDA");
    gpio_set_direction(sd_scl, GPIO_OUTPUT);
    gpio_set_direction(sd_sda, GPIO_OUTPUT);
    gpio_set_value(sd_scl, 0);
    gpio_set_value(sd_sda, 0);

    i2c_fd = i2c_open(0);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (i2c_rdwr_start(i2c_fd) != 0) {
        perror("Failed to start I2C transaction");
        return EXIT_FAILURE;
    }

    unsigned char tx_buf[1] = {0x00};
    unsigned char rx_buf[9];
    int bytes_read = i2c_rdwr(i2c_fd, tx_buf, 1, rx_buf, 9, 1);

    if (bytes_read != 9) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return EXIT_FAILURE;
    }

    CRC8(rx_buf, 9, CRC_INIT_VALUE, CRC_POLYNOMIAL);

    if (crc_match(rx_buf + 8, CRC_INIT_VALUE)) {
        printf("CRC mismatch\n");
        return EXIT_FAILURE;
    }

    int pressure = (rx_buf[1] << 8) | rx_buf[2];
    int temp = (rx_buf[4] << 8) | rx_buf[5];
    printf("Pressure: %d, Temperature: %d\n", pressure, temp);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        usleep(45000);
        i2c_rdwr_restart(i2c_fd);
        i2c_rdwr_buf(i2c_fd, tx_buf, 1, rx_buf, 9, 1);
        CRC8(rx_buf, 9, CRC_INIT_VALUE, CRC_POLYNOMIAL);
        if (crc_match(rx_buf + 8, CRC_INIT_VALUE)) {
            printf("CRC mismatch\n");
            break;
        }
        pressure = (rx_buf[1] << 8) | rx_buf[2];
        temp = (rx_buf[4] << 8) | rx_buf[5];
        printf("Pressure: %d, Temperature: %d\n", pressure, temp);
    }

    i2c_rdwr_stop(i2c_fd);
    i2c_close(i2c_fd);
    gpio_free();

    return EXIT_SUCCESS;
}

