#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define DEVICE "/dev/i2c-1"
#define DRDY_PIN 0
#define CONV_DELAY_MS 20

int main() {
    int i2c_fd = -1;
    struct gpiod_chip chip;
    struct gpiod_line drdy_line;
    struct timespec next_log_time;
    clock_gettime(CLOCK_MONOTONIC, &next_log_time);

    // Initialize GPIO
    if (gpiod_chip_open(&chip, "gpiochip0") < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    if (gpiod_chip_get_line(&chip, DRDY_PIN, &drdy_line) < 0) {
        fprintf(stderr, "Failed to get DRDY line\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    gpiod_line_export(drdy_line, NULL);
    gpiod_line_direction_set(drdy_line, true);

    // Initialize I2C
    i2c_fd = open(DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", DEVICE, strerror(errno));
        gpiod_chip_close(&chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x40) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus\n");
        close(i2c_fd);
        gpiod_chip_close(&chip);
        return 1;
    }

    // Install signal handlers
    struct sigaction sa_int = { .sa_handler = (void (*)(int))handle_sigint };
    sigemptyset(&sa_int.sa_mask);
    sigaction(SIGINT, &sa_int, NULL);

    sa_int.sa_handler = SIG_IGN;
    sigaction(SIGTERM, &sa_int, NULL);

    while (1) {
        // Wait for conversion to complete
        if (gpiod_line_get_value(drdy_line) == true) {
            gpiod_line_trigger(drdy_line);
            clock_gettime(CLOCK_MONOTONIC, &next_log_time);
            while (clock_gettime(CLOCK_MONOTONIC, &next_log_time) - next_log_time < CONV_DELAY_MS * 1e3 / 1000);
        }

        // Read temperature and humidity
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        int16_t temp = (data[1] << 8 | data[0]) * 0.0625 - 4;
        int rh = (data[5] << 8 | data[4]) * 0.1;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, rh);

        // Schedule next log
        clock_gettime(CLOCK_MONOTONIC, &next_log_time);
        next_log_time.tv_sec += 5;
    }

    // Clean up
    close(i2c_fd);
    gpiod_line_unref(drdy_line);
    gpiod_chip_close(&chip);

    return 0;
}

static void handle_sigint(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Received SIGINT, cleaning up...\n");
        close(i2c_fd);
        gpiod_chip_close(&chip);
        exit(0);
    }
}

