    if (ret) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return ret;
    }

    ret = gpiod_chip_get_lines(chip, &info, 2, &scl_info, &sda_info);
    if (ret) {
        fprintf(stderr, "Failed to get I2C lines\n");
        gpiod_chip_close(chip);
        return ret;
    }

    scl_line = gpiod_chip_line_get(chip, scl_info.id);
    sda_line = gpiod_chip_line_get(chip, sda_info.id);

    if (!scl_line || !sda_line) {
        fprintf(stderr, "Failed to get I2C lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_claim_lines(scl_line, sda_line);
    if (ret) {
        fprintf(stderr, "Failed to claim I2C lines\n");
        gpiod_chip_line_free(scl_line);
        gpiod_chip_line_free(sda_line);
        gpiod_chip_close(chip);
        return ret;
    }

    scl = scl_line->line;
    sda = sda_line->line;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

