        ret = gpiod_write(sda, 0);
        if (ret) {
            fprintf(stderr, "Failed to deassert SDA\n");
            break;
        }

        ret = gpiod_read(sda, &data[2], 1);
        if (ret) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        ret = gpiod_write(scl, 0);
        if (ret) {
            fprintf(stderr, "Failed to deassert SCL\n");
            break;
        }

        // Process the temperature data (implementation omitted for brevity)

        usleep(5000000); // Sleep for 5 seconds
    }

    gpiod_unclaim(scl);
    gpiod_unclaim(sda);
    gpiod_drain(chip);
    gpiod_chip_close(chip);

    return 0;
}

