#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define MLX90833_ADDR 0x77

struct sensor_data {
    int fd;
    int i2c_fd;
};

static struct sensor_data sensor;

static int read_pressure(void) {
    uint8_t data[3];
    int ret = ioctl(sensor.i2c_fd, I2C_RDWR, &data[0]);
    if (ret < 0) {
        perror("I2C read error");
        return -1;
    }

    if (ret != 3) {
        fprintf(stderr, "Unexpected I2C read size: %d\n", ret);
        return -1;
    }

    return (data[1] << 8 | data[2]);
}

static void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    close(sensor.fd);
    gpiod_unprepare(sensor.gpio);
    exit(0);
}

static void sigterm_handler(int signum) {
    printf("\nReceived SIGTERM, cleaning up...\n");
    close(sensor.fd);
    gpiod_unprepare(sensor.gpio);
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    sensor.fd = open("/dev/i2c-1", O_RDWR);
    if (sensor.fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    sensor.i2c_fd = ioctl(sensor.fd, I2C_SLAVE, MLX90833_ADDR);
    if (sensor.i2c_fd < 0) {
        close(sensor.fd);
        return 1;
    }

    struct gpiod_chip chip;
    gpiod_chip_init(&chip, "gpio");

    int gpio = gpiod_chip_get_line(&chip, "P1", 12);
    if (gpio < 0) {
        close(sensor.fd);
        return 1;
    }

    sensor.gpio = gpiod_chip_get_line(&chip, "P1", 12);
    if (gpiod_line_prepare_dt(&sensor.gpio, "direction", GPIO_DIR_OUT) < 0) {
        close(sensor.fd);
        return 1;
    }
    gpiod_line_export(&sensor.gpio);

    while (1) {
        if (read_pressure() < 0) {
            break;
        }

        time_t now = time(NULL);
        printf("Pressure: %d, Timestamp: %ld\n", read_pressure(), now);

        usleep(500000);
    }

    gpiod_line_unexport(&sensor.gpio);
    gpiod_chip_unprepare(&chip);
    close(sensor.fd);

    return 0;
}

