#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define I2C_ADDR 0x68 // TDK ICP-10101 I2C address
#define I2C_REG_TEMP 0x01
#define I2C_REG_PRES 0x02
#define I2C_REG_COUNT 0xFE

#define READ_DELAY_US 7
#define LOOP_DELAY_US 5000000

static gpiod_chip *chip;
static gpiod_chip_handle *handle;

void sigint_handler(int signum) {
    if (handle) {
        gpiod_chip_put(handle);
        handle = NULL;
    }
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
    exit(0);
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

    chip = gpiod_chip_open("/dev/i2c-1", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return 1;
    }

    handle = gpiod_chip_get_handle(chip, "I2C", 0);
    if (!handle) {
        fprintf(stderr, "Failed to get I2C handle\n");
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_chip_request_available(chip, handle, 1) < 0) {
        fprintf(stderr, "Failed to request I2C handle\n");
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_chip_enable(handle, 1) < 0) {
        fprintf(stderr, "Failed to enable I2C handle\n");
        gpiod_chip_put(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        uint8_t data[3];
        int r;

        // Write to I2C register
        r = gpiod_bulk_write(handle, I2C_ADDR, &I2C_REG_TEMP, 1);
        if (r < 0) {
            fprintf(stderr, "Error writing to I2C register\n");
            break;
        }

        // Wait for 7 ms
        usleep(READ_DELAY_US);

        // Read from I2C register
        r = gpiod_bulk_read(handle, I2C_ADDR, I2C_REG_TEMP, data, 1);
        if (r < 0 || data[0] == 0x80) { // Sensor absent condition
            fprintf(stderr, "Error reading temperature or sensor absent\n");
            break;
        }

        // Write to I2C register
        r = gpiod_bulk_write(handle, I2C_ADDR, &I2C_REG_PRES, 1);
        if (r < 0) {
            fprintf(stderr, "Error writing to I2C register\n");
            break;
        }

        // Wait for 7 ms
        usleep(READ_DELAY_US);

        // Read from I2C register
        r = gpiod_bulk_read(handle, I2C_ADDR, I2C_REG_PRES, data, 1);
        if (r < 0 || data[0] == 0x80) { // Sensor absent condition
            fprintf(stderr, "Error reading pressure or sensor absent\n");
            break;
        }

        // Convert data to temperature and pressure
        float temp = (float)data[0] * 0.02;
        float pressure = (float)(data[1] << 8 | data[0]) * 0.02;

        // Print results
        printf("%s - Temperature: %.2f C, Pressure: %.0f Pa\n", timestamp, temp, pressure);

        // Wait for 5 seconds
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts);
        ts.tv_sec += LOOP_DELAY_US / 1000000;
    }

    gpiod_chip_put(chip);
    return 0;
}

