#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>

#define DEVICE_FILE "/dev/i2c-1"
#define MLX90819_ADDR 0x68
#define MLX90819_REG_PRESSURE 0x00

static int i2c_fd = -1;
static struct gpiod_chip chip;

static int
i2c_open(void)
{
    i2c_fd = open(DEVICE_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return 0;
}

static void
i2c_close(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int
i2c_read(uint8_t reg, uint16_t *pressure)
{
    if (i2c_fd < 0)
        return -1;

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, reg) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    if (read(i2c_fd, pressure, 2) != 2) {
        perror("Failed to read from I2C register");
        return -1;
    }

    return 0;
}

static void
sigint_handler(int signum)
{
    i2c_close();
    exit(0);
}

int
main(int argc, char *argv[])
{
    struct timespec ts;
    uint16_t pressure;
    int ret;

    gpiod_init();
    chip.dev = gpiod_chip_register_get(gpiod_chip_find("i2c-1"));
    if (!chip.dev) {
        fprintf(stderr, "Failed to get I2C chip\n");
        return -1;
    }

    gpiod_chip_add_listener(chip.dev, &sigint_handler, NULL);

    if (i2c_open() < 0)
        return -1;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("%ld.%09ld: ", (long)(ts.tv_sec), (long)(ts.tv_nsec / 1000));

        if (i2c_read(MLX90819_REG_PRESSURE, &pressure) < 0) {
            fprintf(stderr, "Error reading pressure sensor\n");
        } else {
            printf("Pressure: %u hPa\n", pressure);
        }

        sleep(1);
    }

    i2c_close();
    gpiod_cleanup();

    return 0;
}

