    gpiod_chip_add_listener(chip.dev, &sigint_handler, NULL);

    if (i2c_open() < 0)
        return -1;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("%ld.%09ld: ", (long)(ts.tv_sec), (long)(ts.tv_nsec / 1000));

        if (i2c_read(MLX90819_REG_PRESSURE, &pressure) < 0) {
            fprintf(stderr, "Error reading pressure sensor\n");
        } else {
            printf("Pressure: %u hPa\n", pressure);
        }

        sleep(1);
    }

    i2c_close();
    gpiod_cleanup();

    return 0;
}
