#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>

#define SDA_GPIO 2
#define SCL_GPIO 3
#define SENSOR_ADDR 0x44
#define CRC_POLY 0x07
#define CRC_INIT 0xFF

struct sensor_sample {
    time_t timestamp;
    uint16_t pressure_high;
    uint16_t pressure_low;
    uint8_t temperature;
};

static int sensor_crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x83;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line sda_line;
    struct gpiod_line scl_line;
    struct i2c_inst *i2c;
    struct sensor_sample sample;
    FILE *log_file = fopen("pressure_log.txt", "a");

    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    gpiod_chip_init(&chip);
    gpiod_chip_register_file(&chip, "/dev/gpiod");

    sda_line = gpiod_chip_get_line(&chip, SDA_GPIO);
    scl_line = gpiod_chip_get_line(&chip, SCL_GPIO);

    if (gpiod_line_export(&sda_line, "sda") < 0 || gpiod_line_export(&scl_line, "scl") < 0) {
        fprintf(stderr, "Failed to export GPIOs\n");
        return 1;
    }

    gpiod_line_set_dir(&sda_line, GPIO_DIR_OUT);
    gpiod_line_set_dir(&scl_line, GPIO_DIR_OUT);

    i2c = i2c_open(SENSOR_ADDR, 1);
    if (!i2c) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    while (1) {
        // Trigger measurement
        i2c_write(i2c, 0x2C);
        usleep(45000);

        uint8_t buffer[11];
        int bytes_read = i2c_read(i2c, buffer, 9);
        if (bytes_read != 9) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        buffer[9] = sensor_crc8(buffer, 8);

        if (buffer[0] == buffer[2] && buffer[1] == buffer[3] && buffer[3] == sensor_crc8((uint8_t *)&buffer[0], 8)) {
            sample.timestamp = time(NULL);
            sample.pressure_high = (uint16_t)(buffer[0] << 8 | buffer[1]);
            sample.pressure_low = (uint16_t)(buffer[2] << 8 | buffer[3]);
            sample.temperature = buffer[8];

            fprintf(log_file, "%ld,%d,%d\n", (long)sample.timestamp, sample.pressure_high, sample.temperature);
            fflush(log_file);
        } else {
            fprintf(stderr, "CRC mismatch\n");
            break;
        }
    }

    i2c_close(i2c);
    gpiod_line_unexport(&sda_line);
    gpiod_line_unexport(&scl_line);
    gpiod_chip_unregister(&chip);
    fclose(log_file);

    return 0;
}

