#include <libgpiod.h>

#define SENS_ADDR 0x18
#define CRC_POLY 0x07
#define CRC_INIT 0xFF

static gpiod_chip *chip;
static gpiod_context *ctx;
static int fd;

static int i2c_read(uint8_t reg, uint8_t *data, int len) {
    int ret;
    struct i2c_rdwr_ioctl_data rdwr;

    rdwr.addr = SENS_ADDR;
    rdwr.flags = 0;
    rdwr.len = len;
    rdwr.buffer = (unsigned char *)data;

    ret = ioctl(fd, I2C_RDWR, &rdwr);
    if (ret < 0) {
        perror("I2C read error");
        return ret;
    }

    return 0;
}

static uint8_t crc8(uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    uint8_t i;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x83;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

int main() {
    int ret;
    int i2c_fd;
    char filename[] = "airflow_log.csv";
    FILE *file;
    char timestamp[20];

    // Initialize GPIO
    ret = gpiod_new(&ctx);
    if (ret < 0) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return ret;
    }

    chip = gpiod_chip_open(ctx, "I2C-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        gpiod_free(ctx);
        return -1;
    }

    // Get I2C file descriptor
    i2c_fd = gpiod_chip_get_fd(chip);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to get I2C file descriptor\n");
        gpiod_put(chip);
        gpiod_free(ctx);
        return -1;
    }
    fd = i2c_fd;

    // Check if file exists
    if (access(filename, F_OK) == 0) {
        file = fopen(filename, "r");
        if (file) {
            fseek(file, -1, SEEK_END);
            if (feof(file)) {
                fclose(file);
                fprintf(stderr, "File is empty, adding header\n");
            } else {
                rewind(file);
            }
            fclose(file);
        }
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        uint8_t data[3];
        ret = i2c_read(0x00, data, 3);
        if (ret < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        uint8_t crc = data[2];
        data[2] = crc8(data, 2);

        if (crc != crc8(data, 2)) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        file = fopen(filename, "a");
        if (!file) {
            fprintf(stderr, "Failed to open file for writing\n");
            break;
        }

        if (access(filename, F_OK) == -1 && errno == ENOENT) {
            fprintf(file, "Timestamp,Pressure\n");
        }
        fprintf(file, "%s,%d\n", timestamp, (int)data[0]);

        fclose(file);

        sleep(1);
    }

    gpiod_put(chip);
    gpiod_free(ctx);
    close(fd);

    return 0;
}

