#include <libmlx90821.h>

#define SAFE_PRESSURE_RANGE_MIN 200.0
#define SAFE_PRESSURE_RANGE_MAX 250.0

static int i2c_fd = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    mlx90821_exit();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    struct gpiod_chip_params chip_params =GPIOD_CHIP_PARAMS_INITIALIZER;
    struct gpiod_chip *chip;
    struct gpiod_line *i2c_line;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO
    ret = gpiod_chip_init("i2c-1", &chip_params, &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return ret;
    }

    i2c_line = gpiod_chip_get_line(chip, "i2c-1", 0);
    if (!i2c_line) {
        fprintf(stderr, "Failed to get I2C line\n");
        gpiod_chip_exit(chip);
        return -1;
    }

    i2c_fd = i2c_open(i2c_line->line_name);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_put(i2c_line);
        gpiod_chip_exit(chip);
        return -1;
    }

    // Initialize MLX90821 sensor
    if (mlx90821_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MLX90821 sensor\n");
        close(i2c_fd);
        gpiod_chip_put(i2c_line);
        gpiod_chip_exit(chip);
        return -1;
    }

    log_file = fopen("pressure_log.csv", "a");
    if (!log_file && fopen_mode == "w") {
        log_file = fopen("pressure_log.csv", "w");
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    if (!log_file) {
        fprintf(stderr, "Failed to open pressure_log.csv\n");
        mlx90821_exit();
        close(i2c_fd);
        gpiod_chip_put(i2c_line);
        gpiod_chip_exit(chip);
        return -1;
    }

    while (1) {
        double pressure_kPa;
        time_t now;
        struct tm *time_info;

        time(&now);
        time_info = localtime(&now);

        pressure_kPa = mlx90821_read_pressure(i2c_fd);

        if (pressure_kPa < SAFE_PRESSURE_RANGE_MIN || pressure_kPa > SAFE_PRESSURE_RANGE_MAX) {
            fprintf(stderr, "Warning: Pressure %f kPa is outside safe range\n", pressure_kPa);
        }

        fprintf(log_file, "%ld,%f\n", (long)(time_info->tm_hour * 3600 + time_info->tm_min * 60 + time_info->tm_sec), pressure_kPa);

        fflush(log_file);

        sleep(1);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_put(i2c_line);
    gpiod_chip_exit(chip);
    mlx90821_exit();

    return 0;
}

