#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_SIZE (1024 * 1024) // 1 MB

struct hih6130_data {
    uint8_t humidity;
    uint8_t temperature;
    uint8_t status;
};

int log_file_open = 0;
FILE *log_fp = NULL;

void roll_log_file() {
    if (log_fp && fclose(log_fp) && (log_fp = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open or create log file");
        exit(EXIT_FAILURE);
    }
}

int read_hih6130(struct hih6130_data *data) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (gpiod_export(&gpio_chip, "i2c-bus") < 0) {
        perror("Failed to export I2C bus");
        close(fd);
        return -1;
    }

    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.u8 = HIH6130_ADDR;
    rdwr.u8len = 1;
    rdwr.u8buf = NULL;
    rdwr.u8buf_len = 0;

    if (ioctl(fd, I2C_SLAVE, &rdwr) < 0) {
        perror("Failed to acquire I2C bus");
        gpiod_unexport(&gpio_chip);
        close(fd);
        return -1;
    }

    rdwr.u8 = 0x00; // Start condition
    rdwr.u8len = 1;
    rdwr.u8buf = data;
