#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>

#define DEVICE_ID 0x48
#define TEMP_FILE "greenhouse_temps.dat"
#define LOG_INTERVAL 60

int main() {
    int fd;
    gpiod_chip_reg_handle *chip;
    int ret;
    float temp;
    FILE *log_file;

    // Initialize libgpiod
    ret = gpiod_new(&chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open I2C bus
    fd = wiringPiI2CSetup(0x48);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_free(chip);
        return EXIT_FAILURE;
    }

    // Verify device ID
    if (wiringPiI2CReadReg8(fd, 0x00) != DEVICE_ID) {
        fprintf(stderr, "Invalid device ID\n");
        close(fd);
        gpiod_free(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(TEMP_FILE, "ab");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(fd);
        gpiod_free(chip);
        return EXIT_FAILURE;
    }

    // Read temperature
    ret = wiringPiI2CReadReg16(fd, 0x02);
    if (ret < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        fclose(log_file);
        close(fd);
        gpiod_free(chip);
        return EXIT_FAILURE;
    }
    temp = (float)ret / 100.0;

    // Log temperature
    fwrite(&temp, sizeof(float), 1, log_file);
    fflush(log_file);

    // Main loop
    while (1) {
        sleep(LOG_INTERVAL);

        // Read temperature
        ret = wiringPiI2CReadReg16(fd, 0x02);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            break;
        }
        temp = (float)ret / 100.0;

        // Log temperature
        fwrite(&temp, sizeof(float), 1, log_file);
        fflush(log_file);
    }

    // Close log file
    fclose(log_file);

    // Release resources
    gpiod_free(chip);
    close(fd);

    return EXIT_SUCCESS;
}

