#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define SHT40_ADDR 0x44
#define CRC_POLY 0x05
#define CRC_INIT 0xFFFF

struct sht40_data {
    int fd;
    int i2c_handle;
};

static int sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sht40_read(struct sht40_data *sht40, uint8_t *buf, size_t len) {
    if (!gpiod_in_export(sht40->i2c_handle, "i2c")) {
        perror("Failed to export I2C bus");
        return -1;
    }

    if (gpiod_in_get_value(sht40->i2c_handle, "i2c", 1) != 1) {
        perror("Failed to assert I2C bus");
        return -1;
    }

    if (write(sht40->fd, SHT40_ADDR, 1) != 1) {
        perror("Failed to write to SHT40 address");
        return -1;
    }

    if (ntohs(gpiod_in_get_value_timeout(sht40->i2c_handle, "i2c", 1, 10000)) != 1) {
        perror("Timeout waiting for SHT40 conversion");
        return -1;
    }

    if (read(sht40->fd, buf, len) != len) {
        perror("Failed to read from SHT40");
        return -1;
    }

    return 0;
}

static int sht40_write(struct sht40_data *sht40, const uint8_t *buf, size_t len) {
    if (write(sht40->fd, buf, len) != len) {
        perror("Failed to write to SHT40");
        return -1;
    }
    return 0;
}

static void sigint_handler(int signum) {
    struct sht40_data *sht40 = (struct sht40_data *)g_context;
    gpiod_out_unexport(sht40->i2c_handle, "i2c");
    sht40_close(sht40);
    exit(0);
}

static void sht40_close(struct sht40_data *sht40) {
    close(sht40->fd);
    gpiod_out_unexport(sht40->i2c_handle, "i2c");
    sht40_deinit();
}

static int sht40_init() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    struct sht40_data *sht40 = malloc(sizeof(struct sht40_data));
    if (!sht40) {
        close(fd);
        return -1;
    }

    sht40->fd = fd;
    sht40->i2c_handle = gpiod_in_export(NULL, "i2c");
    if (!sht40->i2c_handle) {
        close(fd);
        free(sht40);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        gpiod_out_unexport(sht40->i2c_handle, "i2c");
        close(fd);
        free(sht40);
        return -1;
    }

    sht40->fd = fd;
    return 0;
}

int main() {
    struct sht40_data *sht40;
    int ret;

    signal(SIGINT, sigint_handler);

    if ((ret = sht40_init()) < 0) {
        fprintf(stderr, "Error initializing SHT40 sensor\n");
        return 1;
    }

    g_context = (void *)sht40;
    gpiod_in_line_init("i2c");

    while (1) {
        uint8_t buf[8];
        if (ret = sht40_read(sht40, buf, 8)) {
            fprintf(stderr, "Error reading from SHT40: %s\n", strerror(errno));
            break;
        }

        if (buf[2] != sht40_crc8(&buf[0], 4) || buf[4] != sht40_crc8(&buf[1], 3)) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        FILE *log_file = fopen("environmental_data.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            break;
        }

        fprintf(log_file, "%s, Temperature: %d.%01d, Humidity: %d.%01d\n",
                timestamp,
                (int)(buf[0] * 1000 + buf[1] / 2),
                (buf[1] % 2) * 50,
                (int)(buf[3] * 1000 + buf[4] / 2),
                (buf[4] % 2) * 50);

        fflush(log_file);
        fclose(log_file);
    }

    sht40_close(sht40);
    return 0;
}

