    sht40_deinit();
}

static int sht40_init() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    struct sht40_data *sht40 = malloc(sizeof(struct sht40_data));
    if (!sht40) {
        close(fd);
        return -1;
    }

    sht40->fd = fd;
    sht40->i2c_handle = gpiod_in_export(NULL, "i2c");
    if (!sht40->i2c_handle) {
        close(fd);
        free(sht40);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        gpiod_out_unexport(sht40->i2c_handle, "i2c");
        close(fd);
        free(sht40);
        return -1;
    }

    sht40->fd = fd;
    return 0;
}

int main() {
    struct sht40_data *sht40;
    int ret;

    signal(SIGINT, sigint_handler);

    if ((ret = sht40_init()) < 0) {
        fprintf(stderr, "Error initializing SHT40 sensor\n");
        return 1;
    }

    g_context = (void *)sht40;
    gpiod_in_line_init("i2c");

    while (1) {
        uint8_t buf[8];
        if (ret = sht40_read(sht40, buf, 8)) {
            fprintf(stderr, "Error reading from SHT40: %s\n", strerror(errno));
            break;
        }

        if (buf[2] != sht40_crc8(&buf[0], 4) || buf[4] != sht40_crc8(&buf[1], 3)) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        FILE *log_file = fopen("environmental_data.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            break;
        }

        fprintf(log_file, "%s, Temperature: %d.%01d, Humidity: %d.%01d\n",
                timestamp,
                (int)(buf[0] * 1000 + buf[1] / 2),
                (buf[1] % 2) * 50,
                (int)(buf[3] * 1000 + buf[4] / 2),
                (buf[4] % 2) * 50);

        fflush(log_file);
        fclose(log_file);
    }

    sht40_close(sht40);
    return 0;
}
```

This code initializes the I2C bus, exports the I2C pins, asserts the I2C bus, writes to the SHT40 sensor address, waits for conversion, reads the data, validates the CRC, and writes the timestamped values to a file. It also handles SIGINT to cleanly close resources and terminate the program.

