#include <signal.h>
#include <string.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>

#define BUFFER_SIZE 100
#define I2C_ADDR 0x44 // TMP117 I2C address

typedef struct {
    float buffer[BUFFER_SIZE];
    int head, tail;
} CircularBuffer;

void sigint_handler(int signum) {
    gpiod_uninit();
    free(buffer);
    write_buffer_to_file();
    exit(0);
}

void write_buffer_to_file() {
    FILE *file = fopen("temperature_log.dat", "ab");
    if (!file) {
        perror("Failed to open file for appending");
        return;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (fwrite(&buffer.buffer[i], sizeof(float), 1, file) != 1) {
            perror("Failed to write to file");
            break;
        }
    }

    fclose(file);
}

int main() {
    struct gpiod_chip chip;
    gpiod_chip_init(&chip);
    gpiod_chip_register_notify(&chip, sigint_handler);

    int fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd < 0) {
        perror("Failed to initialize I2C");
        return 1;
    }

    CircularBuffer buffer;
    buffer.head = buffer.tail = 0;

    while (true) {
        float temp;
        if (wiringPiI2CReadReg8(fd, 0x01) == 16) { // Read MSB
            if (wiringPiI2CReadReg8(fd, 0x02) == 0x40) { // Check for temperature data ready
                temp = (wiringPiI2CReadReg16(fd, 0x03) << 8) | wiringPiI2CReadReg8(fd, 0x04);
                temp /= 100.0; // Convert raw data to Celsius

                if (buffer.head == BUFFER_SIZE) {
                    buffer.tail++;
                    buffer.head++;
                }
                buffer.buffer[buffer.head] = temp;
                buffer.head = (buffer.head + 1) % BUFFER_SIZE;
            } else {
                fprintf(stderr, "Error: Temperature data not ready\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read from I2C\n");
        }

        usleep(5000000); // Sleep for 5 seconds
    }

    gpiod_uninit();
    free(buffer.buffer);
    write_buffer_to_file();
    return 0;
}

