#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define SI7202_ADDR 0x1D
#define LOG_FILE "mag_temp_log.csv"

struct sensor_data {
    float speed;
    float temp;
};

static int i2c_fd = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        gpiod_unrequest_devices(i2c_fd);
        i2c_fd = -1;
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    exit(0);
}

int init_i2c() {
    int ret;
    struct gpiod_chip_params params = {
        .gpio_chip_class = "i2c",
        .gpio_chip_id = "i2c-1",
    };

    ret = gpiod_chip_open(&params, 0);
    if (ret < 0) {
        perror("Failed to open I2C chip");
        return ret;
    }

    i2c_fd = gpiod_chip_get_fd(params.chip_id);
    if (i2c_fd < 0) {
        perror("Failed to get I2C file descriptor");
        gpiod_chip_close(params.chip_id);
        return i2c_fd;
    }

    return 0;
}

void cleanup_i2c() {
    if (i2c_fd != -1) {
        gpiod_unrequest_devices(i2c_fd);
        i2c_fd = -1;
    }
}

int read_sensor_data(struct sensor_data *data) {
    uint8_t buf[6];
    int ret;

    ret = ioctl(i2c_fd, I2C_RDWR, buf);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
        data->speed = NAN;
        data->temp = NAN;
        return ret;
    }

    data->speed = (float)((buf[0] << 8) | buf[1]) * 0.0256;
    data->temp = (float)((buf[4] << 8) | buf[5]) / 100.0;

    return 0;
}

int init_log_file() {
    if (log_file != NULL) {
        return 0;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(log_file, "Speed,Temperature\n");

    return 0;
}

void close_log_file() {
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    struct sensor_data data;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return 1;
    }

    if (init_i2c() < 0) {
        return 1;
    }

    if (init_log_file() < 0) {
        cleanup_i2c();
        return 1;
    }

    while (1) {
        read_sensor_data(&data);

        if (isnan(data.speed) || isnan(data.temp)) {
            fprintf(stderr, "Skipping invalid sensor data\n");
            continue;
        }

        fprintf(log_file, "%.6f,%.2f\n", data.speed, data.temp);
        usleep(1000000);
    }

    cleanup_i2c();
    close_log_file();

    return 0;
}

