#define TMP117_ADDR 0x48
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3

int i2c_fd = -1;
int file_fd = -1;

void log_temperature(int temp_c) {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %d C\n", timestamp, temp_c);
