#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <honeywell_haf.h> // Include the Honeywell HAF sensor library

#define SENSOR_ADDR 0x44 // HAFUHH0025PA3 I2C address
#define SAMPLE_INTERVAL 1
#define LOG_FILE "flow_log.txt"

struct i2c_dev i2c;
FILE *log_file;

void log_measurement(uint16_t flow, float temp) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    fprintf(log_file, "%02d:%02d:%02d, Flow: %.2f SLPM, Temp: %.2f °C\n",
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec,
            flow * 1.45037738, temp);
    fflush(log_file);
}

int main() {
    int ret;
    struct gpiod_chip_params params =GPIOD_CHIP_PARAMS_DEFAULT;
    struct gpiod_chip *chip;
    struct gpiod_line *i2c_sd_a_line;
    struct gpiod_line *i2c_sd_m_line;

    ret = gpiod_chip_init(0, &params);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return ret;
    }

    chip = gpiod_chip_find("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to find i2c-1 chip\n");
        gpiod_chip_exit(0, &params);
        return -1;
    }

    i2c_sd_a_line = gpiod_chip_get_line(chip, "sda");
    i2c_sd_m_line = gpiod_chip_get_line(chip, "scl");

    if (!i2c_sd_a_line || !i2c_sd_m_line) {
        fprintf(stderr, "Failed to get i2c lines\n");
        gpiod_chip_exit(0, &params);
        return -1;
    }

    ret = i2c_open(&i2c, i2c_sd_a_line, i2c_sd_m_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpiod_line_free(i2c_sd_a_line);
        gpiod_line_free(i2c_sd_m_line);
        gpiod_chip_exit(0, &params);
        return ret;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(&i2c);
        gpiod_line_free(i2c_sd_a_line);
        gpiod_line_free(i2c_sd_m_line);
        gpiod_chip_exit(0, &params);
        return -1;
    }

    while (1) {
        uint16_t flow;
        float temp;
        int retries = 2;

        for (int i = 0; i < retries; i++) {
            ret = honeywell_haf_read(&i2c, SENSOR_ADDR, (uint8_t *)&flow, (uint8_t *)&temp);
            if (ret == 0) {
                break;
            }
            delay_ms(100); // Wait before retrying
        }

        if (ret != 0) {
            fprintf(stderr, "Error reading sensor data after %d retries\n", retries);
            continue;
        }

        log_measurement(flow, temp);
        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2c_close(&i2c);
    gpiod_line_free(i2c_sd_a_line);
    gpiod_line_free(i2c_sd_m_line);
    gpiod_chip_exit(0, &params);

    return 0;
}

