#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define DHT11_GPIO 4
#define START_SIGNAL_US 18000
#define BIT_DURATION_US 50
#define HIGH_DURATION_US_0 26
#define HIGH_DURATION_US_1 70
#define CHECKSUM_THRESHOLD 10
#define SAMPLE_INTERVAL_US 2000000
#define TIMEOUT_US 10000

enum dht11_status {
    DHT11_OK,
    DHT11_TIMEOUT_START,
    DHT11_TIMEOUT_RESPONSE,
    DHT11_TIMEOUT_BIT,
    DHT11_CHECKSUM_FAIL,
    DHT11_SENSOR_ABSENT,
};

struct dht11_reading {
    time_t timestamp;
    enum dht11_status status;
    uint8_t humidity_byte_0;
    uint8_t humidity_byte_1;
    uint8_t temperature_byte_2;
    uint8_t temperature_byte_3;
};

static FILE *file = NULL;

static int dht11_init(void) {
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return ret;
    }

    ret = gpiod_request_create_from_desc(NULL, "GPIO%d", DHT11_GPIO, GPIOD_OUT_OPEN_DRAIN, NULL, NULL, &chip, NULL);
    if (ret < 0) {
        gpiod_exit(NULL);
        return ret;
    }

    ret = gpiod_export(chip);
    if (ret < 0) {
        gpiod_request_free(chip);
        gpiod_exit(NULL);
        return ret;
    }

    return 0;
}

static void dht11_cleanup(void) {
    gpiod_unexport(chip);
    gpiod_request_free(chip);
    gpiod_exit(NULL);
}

static int dht11_send_start_signal(void) {
    uint64_t start_time = gpiod_get_current_time_us();
    while (gpiod_get_current_time_us() - start_time < START_SIGNAL_US) {
        if (gpiod_write(chip, 0) < 0) {
            fprintf(stderr, "Failed to write to GPIO\n");
            return -1;
        }
        usleep(1000);
    }
    gpiod_write(chip, 1);
    return 0;
}

static int dht11_read_response_bit(void) {
    uint64_t start_time = gpiod_get_current_time_us();
    int bit_value = 0;

    while (gpiod_get_current_time_us() - start_time < BIT_DURATION_US) {
        if (gpiod_read(chip) == 0) {
            bit_value = 1;
            break;
        }
        usleep(1000);
    }

    if (bit_value == 0) {
        return -1; // Timeout
    }

    return bit_value;
}

static enum dht11_status dht11_read(struct dht11_reading *reading) {
    int ret;
    uint8_t bits[40];
    uint8_t checksum = 0;
    int i;

    ret = dht11_send_start_signal();
    if (ret < 0) {
        reading->status = DHT11_TIMEOUT_START;
        return DHT11_TIMEOUT_START;
    }

    for (i = 0; i < 40; i++) {
        bits[i] = dht11_read_response_bit();
        if (bits[i] < 0) {
            reading->status = DHT11_TIMEOUT_BIT;
            return DHT11_TIMEOUT_BIT;
        }
        checksum ^= bits[i];
    }

    reading->humidity_byte_0 = bits[0];
    reading->humidity_byte_1 = bits[1];
    reading->temperature_byte_2 = bits[2];
    reading->temperature_byte_3 = bits[3];

    if (checksum > CHECKSUM_THRESHOLD) {
        reading->status = DHT11_CHECKSUM_FAIL;
        return DHT11_CHECKSUM_FAIL;
    }

    reading->status = DHT11_OK;
    return DHT11_OK;
}

static void dht11_log_reading(const struct dht11_reading *reading) {
    char timestamp_str[32];
    time_t rawtime;
    struct tm *timeinfo;

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (file == NULL) {
        file = fopen("dht11_readings.txt", "w");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file for writing\n");
            return;
        }
    }

    fprintf(file, "%s, %d, %d, %d, %d, %d\n", timestamp_str,
            reading->humidity_byte_0, reading->humidity_byte_1,
            reading->temperature_byte_2, reading->temperature_byte_3,
            reading->status);
    fflush(file);
}

int main(void) {
    struct dht11_reading reading;
    int ret;

    ret = dht11_init();
    if (ret < 0) {
        return ret;
    }

    signal(SIGINT, [](int) {
        dht11_cleanup();
        exit(0);
    });

    signal(SIGTERM, [](int) {
        dht11_cleanup();
        exit(0);
    });

    while (1) {
        ret = dht11_read(&reading);
        dht11_log_reading(&reading);

        if (ret != DHT11_OK) {
            fprintf(stderr, "Error reading DHT11: %d\n", ret);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    dht11_cleanup();
    fclose(file);
    return 0;
}

