        .flags = 0,
        .len = 2,
        .buf = &data1,
    };
    ret = ioctl(fd, I2C_RDWR(1), &rdwr);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from sensor 1\n");
        close(fd);
        gpiod_chip_remove(&chip);
        return 1;
    }
