#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <libiio/iio.h>
#include <libiio/context.h>
#include <libiio/device.h>
#include <libiio/channel.h>
#include <libiio/buffer.h>

#define DEVICE_PATH "/dev/iio/iio:device0"
#define SENSOR_NAME "mlx90824"
#define LOG_FILE "pressure_log.txt"

struct iio_device *dev;
struct iio_context *ctx;
struct iio_dev *iio;
struct iio_channel *ch;
FILE *log_file;

void cleanup(void) {
    iio_context_destroy(ctx);
    iio_device_put(iio);
    fclose(log_file);
}

int read_sensor_data(void) {
    int ret;
    struct iio_buf buf;
    double pressure, temp;

    ret = iio_buf_init(&buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize buffer\n");
        return ret;
    }

    ret = iio_read_channels(iio, &buf, 2, (const char *const []){
        iio_get_channel_name(iio, "pressure_out_abs", SENSOR_NAME),
        iio_get_channel_name(iio, "temp_out", SENSOR_NAME)
    });
    if (ret < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        iio_buf_free(&buf);
        return ret;
    }

    pressure = buf.values[0];
    temp = buf.values[1];

    iio_buf_free(&buf);

    return 0;
}

void log_data(double pressure, double temp) {
    time_t now;
    struct tm *time_struct;
    char timestamp[64];

    now = time(NULL);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_struct);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "%s: pressure=%.2f, temperature=%.2f\n", timestamp, pressure, temp);
    fclose(log_file);
}

int main(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    ctx = iio_context_create();
    if (!ctx) {
        fprintf(stderr, "Failed to create IIO context\n");
        return 1;
    }

    dev = iio_device_find(ctx, DEVICE_PATH);
    if (!dev) {
        fprintf(stderr, "Failed to find IIO device\n");
        iio_context_destroy(ctx);
        return 1;
    }

    iio = iio_device_get(dev);
    ch = iio_find_channel(iio, SENSOR_NAME, "pressure_out_abs");
    if (!ch) {
        fprintf(stderr, "Failed to find pressure channel\n");
        iio_device_put(iio);
        iio_context_destroy(ctx);
        return 1;
    }

    ch = iio_find_channel(iio, SENSOR_NAME, "temp_out");
    if (!ch) {
        fprintf(stderr, "Failed to find temperature channel\n");
        iio_device_put(iio);
        iio_context_destroy(ctx);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        iio_context_destroy(ctx);
        return 1;
    }

    chip = gpiod_chip_open(&gpiod_chip_default, "i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        iio_context_destroy(ctx);
        fclose(log_file);
        return 1;
    }

    line = gpiod_chip_get_line(chip, "enable");
    if (!line) {
        fprintf(stderr, "Failed to get enable line\n");
        gpiod_chip_close(chip);
        iio_context_destroy(ctx);
        fclose(log_file);
        return 1;
    }

    gpiod_line_export(line, NULL);
    gpiod_line_set_value(line, 1);

    while (1) {
        ret = read_sensor_data();
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor data, retrying in 2 seconds...\n");
            sleep(2);
            continue;
        }

        log_data(pressure, temp);
        sleep(2);
    }

    gpiod_line_unset_value(line, 0);
    gpiod_chip_close(chip);
    iio_context_destroy(ctx);
    fclose(log_file);
    return 0;
}

