#include <lm75/lm75.h>

#define BUFFER_SIZE 60
#define FAN_GPIO 18
#define TURN_ON_THRESHOLD 28.0
#define TURN_OFF_THRESHOLD 26.0

int16_t buffer[BUFFER_SIZE];
size_t head = 0;
size_t tail = 0;

void init_lm75(struct i2c *bus) {
    if (lm75_init(bus) < 0) {
        fprintf(stderr, "Failed to initialize LM75 sensor\n");
        exit(EXIT_FAILURE);
    }
}

int read_temperature(struct i2c *bus) {
    int16_t temp;
    if (lm75_read_temperature(bus, &temp) < 0) {
        fprintf(stderr, "Failed to read temperature from LM75 sensor\n");
        return -1;
    }
    return temp;
}

float compute_average_temperature() {
    if (tail == head)
        return 0.0;

    int sum = 0;
    size_t i;
    for (i = head; i != tail; i++) {
        sum += buffer[i % BUFFER_SIZE];
    }

    return (float)sum / (tail - head);
}

void update_buffer(int16_t temp) {
    buffer[head] = temp;
    head = (head + 1) % BUFFER_SIZE;
}

void drive_fan(float avg_temp) {
    if (avg_temp > TURN_ON_THRESHOLD) {
        gpiod_trigger(FAN_GPIO, 1);
    } else if (avg_temp < TURN_OFF_THRESHOLD) {
        gpiod_trigger(FAN_GPIO, 0);
    }
}

int main() {
    struct i2c *bus;
    int ret;

    bus = i2c_open_device(0x48); // LM75 I2C address
    if (!bus) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    ret = i2c_set_baudrate(bus, 100000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C baudrate\n");
        i2c_close(bus);
        return EXIT_FAILURE;
    }

    init_lm75(bus);

    struct gpiod_chip chip;
    ret = gpiod_chip_open(&chip, "GPIO18");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO18\n");
        i2c_close(bus);
        return EXIT_FAILURE;
    }

    gpiod_chip_set_owner(&chip, GET_CURRENT_PID());

    while (1) {
        int16_t temp = read_temperature(bus);
        if (temp >= 0) {
            update_buffer(temp);
            float avg_temp = compute_average_temperature();
            drive_fan(avg_temp);
        }

        usleep(1000000); // Sleep for 1 second
    }

    gpiod_chip_close(&chip);
    i2c_close(bus);

    return 0;
}

