#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpio.h>

#define SENS_ADDR 0x18
#define SENS_REG_PRESS 0x27
#define SENS_REG_TEMP 0x26
#define SENS_CRC_POLY 0x31
#define SENS_CRC_INIT 0xFF
#define SAMPLE_INTERVAL 1000000 // 1 second
#define DELAY_MS 45000
#define LOG_FILE "airflow.log"

struct sensor_data {
    double pressure;
    double temperature;
};

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct gpio_msg msg;
    struct gpio_i2c_master *i2c;

    if (!gpiod_override_get(GPIOD_CHIP_I2C, &msg))
        return -ENODEV;

    i2c = (struct gpio_i2c_master *)msg.data;
    if (gpio_i2c_master_begin(i2c, SENS_ADDR))
        return -EIO;

    if (gpio_i2c_master_write_then_read(i2c, &reg, 1, buf, len))
        return -EIO;

    gpio_i2c_master_end(i2c);
    return 0;
}

uint8_t crc8(uint8_t *data, int len) {
    uint8_t crc = SENS_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SENS_CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    int fd;
    uint8_t buf[9];
    struct sensor_data data;
    FILE *log_file;
    struct sigaction sa;

    fd = gpiod_override_get(GPIOD_CHIP_I2C, NULL);
    if (fd == -ENODEV) {
        fprintf(stderr, "Failed to get I2C override\n");
        return 1;
    }

    if (i2c_read(fd, SENS_REG_PRESS, buf, 9) != 0) {
        fprintf(stderr, "Failed to read from sensor\n");
        return 1;
    }

    if (crc8(buf, 9) != buf[8]) {
        fprintf(stderr, "CRC mismatch\n");
        return 1;
    }

    data.pressure = (float)((buf[0] << 8 | buf[1]) * 0.05);
    data.temperature = (float)((buf[4] << 8 | buf[5]) / 100.0);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    sa.sa_handler = (void *)cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        fprintf(log_file, "%lu,%f,%f\n", time(NULL), data.pressure, data.temperature);
        fflush(log_file);

        if (data.pressure > 5.0)
            fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");

        usleep(DELAY_MS);
        sleep(SAMPLE_INTERVAL / 1000);
    }

    cleanup();
    fclose(log_file);
    return 0;
}

void cleanup(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_override_put(GPIOD_CHIP_I2C);
        fclose(log_file);
        gpio_cleanup();
    }
}

