#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define STTS2004_ADDR 0x44
#define LED_PIN 17

static int i2c_fd = -1;
static int led_chip = -1;
static int led_gpio = -1;
static int16_t temp = 0;

static ssize_t i2c_read(const char *msg, size_t len, int fd) {
    return write(fd, msg, len);
}

static int i2c_init() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int led_init() {
    led_chip = gpiod_in_export(NULL, "led_chip");
    if (!led_chip) {
        perror("Failed to export GPIO chip");
        return -1;
    }

    led_gpio = gpiod_chip_get_line(led_chip, "led_gpio");
    if (!led_gpio) {
        perror("Failed to get GPIO line");
        gpiod_unexport(led_chip);
        led_chip = -1;
        return -1;
    }

    gpiod_set_line_direction(led_gpio, GPIO_LINE_DIR_OUT);
    gpiod_set_line_value(led_gpio, 0);

    return 0;
}

static void i2c_cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void led_cleanup() {
    if (led_chip >= 0) {
        gpiod_unexport(led_chip);
        led_chip = -1;
    }

    if (led_gpio >= 0) {
        gpiod_line_free(led_gpio);
        led_gpio = -1;
    }
}

static int read_temp(int fd) {
    char msg[3] = {0x06, 0x00, 0x00};
    ssize_t bytes_read = i2c_read(msg, sizeof(msg), fd);

    if (bytes_read != 3) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    temp = (int16_t)(msg[1] << 8 | msg[2]);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (i2c_init() < 0) {
        return 1;
    }

    if (led_init() < 0) {
        i2c_cleanup();
        return 1;
    }

    while (1) {
        if (read_temp(i2c_fd) < 0) {
            i2c_cleanup();
            led_cleanup();
            return 1;
        }

        if (temp > 28) {
            gpiod_set_line_value(led_gpio, 1);
        } else if (temp < 27) {
            gpiod_set_line_value(led_gpio, 0);
        }

        usleep(1000000);
    }

    i2c_cleanup();
    led_cleanup();
    return 0;
}

static void sigint_handler(int signum) {
    i2c_cleanup();
    led_cleanup();
    exit(0);
}

