#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpio.h>

#define SDP800_I2C_ADDR 0x77
#define CRC_POLYNOMIAL 0x05
#define CRC_INIT_VALUE 0xFF

struct sensor_data {
    uint16_t pressure_low;
    uint16_t pressure_high;
    int16_t temperature;
    uint8_t pressure_crc;
    uint8_t temperature_crc;
    uint8_scale_factor[3];
};

static volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

uint8_t crc8(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    gpioInit();
    struct sensor_data data;
    FILE *fp = fopen("flow_data.txt", "w");
    if (!fp) {
        perror("Failed to open flow_data.txt");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    gpioSetMode(SDP800_I2C_ADDR, GPIO_OUTPUT_ONLY);
    gpioSetMode(SDP800_I2C_ADDR, GPIO_INPUT);

    gpioSetPull(SDP800_I2C_ADDR, GPIO_PULL_UP);

    signal(SIGINT, sigint_handler);

    while (!sigint_received) {
        // Start measurement
        gpioWrite(SDP800_I2C_ADDR, 1);
        usleep(45000);
        gpioWrite(SDP800_I2C_ADDR, 0);

        // Read data
        if (i2c_read(SDP800_I2C_ADDR, 0x00, (uint8_t *)&data, 9) != 9) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Validate CRC
        if (data.pressure_crc != crc8((uint8_t *)&data, 2) ||
            data.temperature_crc != crc8(&data.pressure_high, 2)) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        // Log data with timestamp
        time_t now = time(NULL);
        struct tm *localtime = localtime(&now);
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %d.%02d, Temperature: %d, Scale Factor: %d.%d.%d\n",
                1900 + localtime->tm_year,
                1 + localtime->tm_mon,
                localtime->tm_mday,
                localtime->tm_hour,
                localtime->tm_min,
                localtime->tm_sec,
                data.pressure_high, data.pressure_low,
                data.temperature,
                data.scale_factor[0], data.scale_factor[1], data.scale_factor[2]);
    }

    gpioTerminate();
    fclose(fp);
    return 0;
}

