#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <si7021.h>

#define I2C_ADDR 0x40
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES 3
#define LOG_FILE "environment.log"

struct si7021_data {
    int fd;
    int retries;
};

static int log_file_fd = -1;
static struct si7021_data si7021;

void cleanup(int sig) {
    if (si7021.fd != -1) {
        close(si7021.fd);
        si7021.fd = -1;
    }
    if (log_file_fd != -1) {
        fclose(log_file_fd);
        log_file_fd = -1;
    }
    exit(0);
}

void sigint_handler(int sig) {
    cleanup(sig);
}

void sigterm_handler(int sig) {
    cleanup(sig);
}

int init_si7021(struct si7021_data *si7021) {
    si7021->fd = gpiod_iomap(NULL, &io, GPIO_IN | GPIO_OPEN_DRAIN);
    if (si7021->fd < 0) {
        perror("Failed to initialize GPIO");
        return -1;
    }

    if (gpiod_add_override_ab(si7021->fd, "i2c-sd-a", 2, GPIO_IN, 0) < 0) {
        perror("Failed to add I2C override");
        return -1;
    }

    if (gpiod_iomap_add_override(si7021->fd, "i2c-sd-s", 2, GPIO_IN, 0) < 0) {
        perror("Failed to add I2C slave override");
        return -1;
    }

    return 0;
}

int read_sensor_data(struct si7021_data *si7021, uint8_t *data, size_t len) {
    int ret;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ret = si7021_read(si7021->fd, I2C_ADDR, data, len);
        if (ret >= 0) {
            return ret;
        }
        retries++;
        delay_ms(10);
    }

    fprintf(stderr, "Error reading sensor data after %d retries\n", MAX_RETRIES);
    return -1;
}

int validate_sensor(struct si7021_data *si7021) {
    uint8_t id[3];
    if (read_sensor_data(si7021, id, 3) < 0) {
        return -1;
    }

    if (id[0] != 0x68 || id[1] != 0x01 || id[2] != 0x2C) {
        fprintf(stderr, "Error: Invalid sensor ID\n");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    if (init_si7021(&si7021) < 0) {
        return 1;
    }

    if (validate_sensor(&si7021) < 0) {
        return 1;
    }

    log_file_fd = fopen(LOG_FILE, "w");
    if (!log_file_fd) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        fprintf(stdout, "%04d-%02d-%02d %02d:%02d:%02d",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1,
                tm_info->tm_mday, tm_info->tm_hour,
                tm_info->tm_min, tm_info->tm_sec);

        uint8_t temp_hum[3];
        if (read_sensor_data(&si7021, temp_hum, 3) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue;
        }

        float temperature_c = (float)temp_hum[1] / 100.0;
        float humidity_pct = (float)temp_hum[0] / 256.0 * 100.0;

        fprintf(stdout, ",%f,%.1f\n", temperature_c, humidity_pct);
        fprintf(log_file_fd, "%ld,%.2f,%.1f\n",
                (int)(now - 946684800), temperature_c, humidity_pct);
        fflush(log_file_fd);

        delay_ms(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

