#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define HDC1080_ADDR 0x40
#define I2C_ADDR_LEN 1
#define LOG_FILE "enviro_log.txt"
#define LOG_LINE_LEN 38

struct timespec ts;
int i2c_fd;

void sigint_handler(int signum) {
    gpio_uninit();
    close(i2c_fd);
    exit(signum == SIGINT ? 0 : 1);
}

int read_hdc1080(uint8_t *temp_bytes, uint8_t *humidity_bytes) {
    if (gpio_request(GPIOD, 0, GPIO_INPUT_OUT_OPEN_DRAIN) < 0)
        return -1;

    gpio_putpins(GPIOD, 0, 1);
    delay_ms(20);
    gpio_putpins(GPIOD, 0, 0);

    if (i2c_xfer(i2c_fd, HDC1080_ADDR | I2C_WRITE, temp_bytes, 2) < 0 ||
        i2c_xfer(i2c_fd, HDC1080_ADDR | I2C_READ, humidity_bytes, 2) < 0) {
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = i2c_open(0, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t temp_bytes[2], humidity_bytes[2];
        uint16_t temp, humidity;

        if (read_hdc100(temp_bytes, humidity_bytes) < 0)
            continue;

        temp = (temp_bytes[1] << 8) | temp_bytes[0];
        humidity = (humidity_bytes[1] << 8) | humidity_bytes[0];

        char line[LOG_LINE_LEN + 1];
        time_t now = time(NULL);
        strftime(line, LOG_LINE_LEN, "%F %T", localtime(&now));
        sprintf(line + strlen(line), ",%d,%d\n", temp / 100.0, humidity);

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            fputs(line, log_file);
            fclose(log_file);
        } else {
            fprintf(stderr, "Failed to open %s for writing\n", LOG_FILE);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        struct timespec remaining;
        remaining.tv_sec = ts.tv_sec + 5;
        remaining.tv_nsec = ts.tv_nsec - ts.tv_sec * 1000000000;
        if (remaining.tv_nsec < 0) {
            remaining.tv_sec--;
            nanosleep(&remaining, NULL);
        }
    }

    gpio_uninit();
    close(i2c_fd);
    return 0;
}

