#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define SENS_ADDR 0x44
#define CRC_POLY 0x31

static int i2c_fd = -1;
static FILE *log_file = NULL;

static ssize_t read_i2c(uint8_t *buf, size_t len) {
    return read(i2c_fd, buf, len);
}

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void log_temperature(double temp) {
    static char timestamp[32];
    time_t t = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%T", localtime(&t));

    if (log_file == NULL)
        return;

    fprintf(log_file, "%s: %.2f\n", timestamp, temp);
    fflush(log_file);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    struct gpiod_chip_data chip_data;
    int ret;

    ret = gpiod_chip_open(&chip, "i2c-0");
    if (ret) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return ret;
    }

    ret = gpiod_chip_get_lines(&chip, &line, 1);
    if (ret) {
        fprintf(stderr, "Failed to get I2C lines\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_line_prepare_for_reuse(&line);
    if (ret) {
        fprintf(stderr, "Failed to prepare I2C line for reuse\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_line_set_config(&line, 0, GPIOD_CONFIG_INPUT);
    if (ret) {
        fprintf(stderr, "Failed to set I2C line configuration\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    i2c_fd = open("/dev/i2c-0", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(&chip);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENS_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpiod_chip_close(&chip);
        return -1;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpiod_chip_close(&chip);
        return -1;
    }

    while (1) {
        uint8_t data[3];
        double temp;

        if (read_i2c(data, 3) != 3) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        uint8_t crc = data[2];
        uint8_t calculated_crc = crc8(data, 2);

        if (crc != calculated_crc) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        temp = (data[0] << 8 | data[1]) * 0.0625;
        log_temperature(temp);

        usleep(10000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(&chip);

    return 0;
}

