        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpiod_chip_close(&chip);
        return -1;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpiod_chip_close(&chip);
        return -1;
    }

    while (1) {
        uint8_t data[3];
        double temp;

        if (read_i2c(data, 3) != 3) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        uint8_t crc = data[2];
        uint8_t calculated_crc = crc8(data, 2);

        if (crc != calculated_crc) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        temp = (data[0] << 8 | data[1]) * 0.0625;
        log_temperature(temp);

        usleep(10000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(&chip);

    return 0;
}
