void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_chip != NULL) {
        gpiod_chip_unbind(i2c_chip);
        gpiod_chip_free(i2c_chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

uint8_t crc8(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_chip = gpiod_chip_open("I2C", "0-0");
    if (!i2c_chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return 1;
    }

    log_file = fopen("hvac_pressure_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        gpiod_chip_drain(i2c_chip);
        gpiod_chip_write(i2c_chip, SDP810_ADDR, 0x00);
        gpiod_chip_write(i2c_chip, SDP810_ADDR, 0x20);
        uint8_t data[9];
        int i;
        for (i = 0; i < 9; i++) {
            data[i] = gpiod_chip_read(i2c_chip, SDP810_ADDR + i);
            if (data[i] == GPIOD_READ_ERROR) {
                fprintf(stderr, "I2C read error\n");
                break;
            }
        }
        if (i != 9) {
            continue;
        }

        uint16_t pressure = (data[0] << 8) | data[1];
        uint8_t temp_crc = (data[3] << 8) | data[4];
        uint8_t scale_factor_crc = (data[6] << 8) | data[7];
        if (crc8(data, 9) != data[2] || crc8(&temp_crc, 1) != temp_crc || crc8(&scale_factor_crc, 3) != scale_factor_crc) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d,%d\n", now, pressure, data[5]);
    }

    fclose(log_file);
    gpiod_chip_unbind(i2c_chip);
    gpiod_chip_free(i2c_chip);

    return 0;
}

