#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>

#define BUFFER_CAPACITY 100
#define I2C_ADDR 0x60
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFFFF

typedef struct {
    uint8_t co2;
    uint16_t temperature;
    uint16_t humidity;
    uint8_t crc;
} SCD40_Reading;

SCD40_Reading buffer[BUFFER_CAPACITY];
int buffer_head = 0;
int buffer_tail = 0;
volatile sig_atomic_t running = 1;

void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);
    fprintf(stderr, "%s: ", timestamp);
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");
    va_end(args);
}

void init_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to acquire I2C bus: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }
}

uint8_t scd40_read(uint8_t reg) {
    uint8_t data;
    int ret = ioctl(fd, I2C_RDWR, &reg | 0x01);
    if (ret < 0) {
        log_error("I2C read error: %s\n", strerror(errno));
        return 0;
    }

    ret = read(fd, &data, 1);
    if (ret < 0) {
        log_error("I2C read error: %s\n", strerror(errno));
        return 0;
    }

    return data;
}

uint8_t scd40_write(uint8_t reg, uint8_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;

    int ret = ioctl(fd, I2C_RDWR, &data[0] | 0x02);
    if (ret < 0) {
        log_error("I2C write error: %s\n", strerror(errno));
        return 0;
    }

    ret = write(fd, &data[1], 1);
    if (ret < 0) {
        log_error("I2C write error: %s\n", strerror(errno));
        return 0;
    }

    return 1;
}

uint8_t calculate_crc(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc ^= CRC_POLYNOMIAL;
            }
            crc >>= 1;
        }
    }
    return crc;
}

