    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        if (buffer_tail != buffer_head) {
            SCD40_Reading *reading = &buffer[buffer_head];
            buffer_head = (buffer_head + 1) % BUFFER_CAPACITY;

            char filename[64];
            snprintf(filename, sizeof(filename), "/var/log/scd40_data/scd40_data_%04d.csv", (int)time(NULL));
            FILE *file = fopen(filename, "a");
            if (file) {
                if (fputs("[", file); fputs(strftime(reading->timestamp, 20), file); fputs("],", file)) {
