static int read_sdp810(uint8_t *buffer, size_t length) {
    int ret;
    ret = gpiod_dmamaster_start(SDP810_I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to start I2C transaction: %s\n", strerror(errno));
        return ret;
    }

    ret = gpiod_dmamaster_write_u8(SDP810_I2C_ADDR, 0x00);
    if (ret < 0) {
        gpiod_dmamaster_stop();
        return ret;
    }

    ret = gpiod_dmamaster_read(SDP810_I2C_ADDR, buffer, length);
    if (ret < 0) {
        gpiod_dmamaster_stop();
        return ret;
    }

    gpiod_dmamaster_stop();
    return ret;
}

static void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_dmamaster_stop();
    exit(0);
}

int main() {
    struct sigaction sa;
    struct sdp810_sample sample;
    uint8_t buffer[9];
    int ret;

    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen("sdp810_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    if ((ret = gpiod_dmamaster_init()) < 0) {
        fprintf(stderr, "Failed to initialize I2C DMA master: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    sample.timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

        if ((ret = read_sdp810(buffer, 9)) < 0) {
            fprintf(stderr, "Failed to read from SDP810: %s\n", strerror(errno));
            continue;
        }

        if (crc8(buffer, 7) != (buffer[7] << 8 | buffer[8])) {
            fprintf(stderr, "CRC error in pressure data\n");
        }

        if (crc8(buffer + 2, 7) != (buffer[9] << 8 | buffer[10])) {
            fprintf(stderr, "CRC error in temperature data\n");
        }

        if (crc8(buffer + 4, 7) != (buffer[11] << 8 | buffer[12])) {
            fprintf(stderr, "CRC error in scale factor data\n");
        }

        sample.pressure_Pa = (int32_t)((buffer[0] << 8 | buffer[1]) | (buffer[2] << 16 | buffer[3] << 8 | buffer[4] << 24));
        sample.temperature_C = ((float)(buffer[5] << 8 | buffer[6]) / 100.0);

        fprintf(log_file, "%f,%d,%f\n", sample.timestamp, sample.pressure_Pa, sample.temperature_C);

        usleep(50000);
    }

    gpiod_dmamaster_stop();
    gpiod_dmamaster_uninit();
    fclose(log_file);
    return 0;
}
