#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <icp10110.h>

#define I2C_BUS 2
#define I2C_ADDR 0x68
#define SAMPLE_INTERVAL_SEC 5
#define WAIT_TIME_MS 10
#define FILE_NAME "environmental_data.txt"

volatile sig_atomic_t sigint_received = 0;

static int file_descriptor = -1;
static struct icp10110 *icp10110 = NULL;

void sigint_handler(int signum) {
    sigint_received = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return EXIT_FAILURE;
    }

    if (icp10110_init() < 0) {
        fprintf(stderr, "Failed to initialize ICP-10110 driver\n");
        return EXIT_FAILURE;
    }

    file_descriptor = fopen(FILE_NAME, "a");
    if (!file_descriptor) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        return EXIT_FAILURE;
    }

    if (i2c_open(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return EXIT_FAILURE;
    }

    while (!sigint_received) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        int pressure_raw, temperature_raw;
        int ret = icp10110_read(icp10110, &pressure_raw, &temperature_raw);
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue;
        }

        double pressure = pressure_raw / 10.0;
        double temperature = temperature_raw / 10.0;

        fprintf(stdout, "%s: Pressure = %.2f hPa, Temperature = %.2f °C\n",
                timestamp, pressure, temperature);

        fprintf(file_descriptor, "%s: Pressure = %.2f hPa, Temperature = %.2f °C\n",
                timestamp, pressure, temperature);
        fflush(file_descriptor);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(file_descriptor);
    i2c_close();
    icp10110_cleanup();
    gpiod_uninit();

    return EXIT_SUCCESS;
}

