#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_ADDR 0x68 // TDK ICP-10125 I2C address
#define LED_GPIO 17    // BCM number for GPIO17

struct sensor_data {
    uint16_t pressure_msb;
    uint16_t pressure_lsb;
    uint16_t temp_msb;
    uint16_t temp_lsb;
    uint16_t crc;
};

static int i2c_fd = -1;
static gpiod_chip *led_chip = NULL;
static gpiod_line *led_line = NULL;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (led_chip != NULL && led_line != NULL) {
        gpiod_line_release(led_line);
        gpiod_chip_release(led_chip);
        led_chip = NULL;
        led_line = NULL;
    }
    exit(signum);
}

int init_i2c() {
    int ret;
    i2c_fd = gpiod_i2c_open("/dev/i2c-1", 0x68);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    ret = gpiod_i2c_set_baudrate(i2c_fd, 100000);
    if (ret < 0) {
        perror("Failed to set I2C baudrate");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int init_led() {
    int ret;
    led_chip = gpiod_chip_open(&gpiod_chip_default, "GPIO17");
    if (!led_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(led_chip, "GPIO17");
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(led_chip);
        led_chip = NULL;
        return -1;
    }

    ret = gpiod_line_request_buffer(led_line, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(led_chip);
        led_chip = NULL;
        return -1;
    }

    gpiod_line_set_direction(led_line, GPIO_DIR_OUT);

    signal(SIGINT, sigint_handler);

    return 0;
}

int read_sensor(struct sensor_data *data) {
    uint8_t buf[6];
    int ret;

    ret = gpiod_i2c_rdwr(i2c_fd, I2C_M_RD, buf, 6, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    data->pressure_msb = (buf[0] << 8) | buf[1];
    data->pressure_lsb = buf[2];
    data->temp_msb = (buf[3] << 8) | buf[4];
    data->temp_lsb = buf[5];
    data->crc = (buf[6] << 8) | buf[7];

    return 0;
}

int main(int argc, char *argv[]) {
    struct sensor_data data;
    struct timespec ts;

    if (init_i2c() < 0) {
        return -1;
    }

    if (init_led() < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    while (1) {
        if (read_sensor(&data) < 0) {
            continue;
        }

        // Verify CRC
        if (data.crc != (data.pressure_msb ^ data.pressure_lsb ^ data.temp_msb ^ data.temp_lsb)) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        // LED control
        usleep(20000); // 20 ms delay

        ts.tv_sec = 0;
        ts.tv_nsec = 1000000000 / 1; // 1 second

        while (ts.tv_sec == 0 || ts.tv_nsec == 0) {
            nanosleep(&ts, NULL);
        }

        if (data.pressure_msb * 1000 < 95000) {
            ts.tv_sec = 0;
            ts.tv_nsec = 100000000 / 5; // 100 ms
        } else {
            ts.tv_sec = 0;
            ts.tv_nsec = 100000000 / 2; // 500 ms
        }

        gpiod_line_set_value(led_line, ts.tv_nsec % (ts.tv_nsec / 2) == 0);
    }

    gpiod_line_release(led_line);
    gpiod_chip_release(led_chip);

    return 0;
}

