#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>

#define FAN_GPIO 18
#define I2C_ADDR 0x5A // MLX90614 default I2C address
#define LOG_FILE "temperature_log.txt"
#define READ_INTERVAL 2000 // 2 seconds
#define HIST_RETRY 3
#define HIST_DELAY 10 // 10 ms
#define TEMP_THRESHOLD_HIGH 30
#define TEMP_THRESHOLD_LOW 28

struct fan_state {
    bool on;
    gpiod_chip *chip;
    gpiod_line *line;
};

void fan_init(struct fan_state *fan) {
    if (gpiod_in_export(NULL, "fan_control") < 0) {
        perror("Failed to export GPIO for fan control");
        exit(EXIT_FAILURE);
    }

    fan->chip = gpiod_chip_open(gpiod_in_get_chip(NULL, "fan_control"));
    if (!fan->chip) {
        fprintf(stderr, "Failed to open fan control chip\n");
        exit(EXIT_FAILURE);
    }

    fan->line = gpiod_chip_get_line(fan->chip, "fan_control");
    if (!fan->line) {
        fprintf(stderr, "Failed to get fan control line\n");
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(fan->line);
    gpiod_set_value(fan->line, 0); // Turn off the fan initially
}

void fan_cleanup(struct fan_state *fan) {
    gpiod_line_unref(fan->line);
    gpiod_chip_unimport(fan->chip);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up and exiting...\n");
    fan_cleanup(&fan_state);
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up and exiting...\n");
    fan_cleanup(&fan_state);
    exit(EXIT_SUCCESS);
}

int read_mlx90614(uint8_t *object_temp, uint8_t *ambient_temp) {
    int ret;
    int retry_count = HIST_RETRY;

    while (retry_count > 0) {
        ret = wiringPiI2C_rdwr(I2C_ADDR, NULL, 0, object_temp, 2, NULL, 0);
        if (ret >= 0) {
            break;
        }

        retry_count--;
        if (retry_count > 0) {
            printf("Failed to read from MLX90614, retrying in %d ms...\n", HIST_DELAY);
            usleep(HIST_DELAY * 1000);
        } else {
            printf("Failed to read from MLX90614 after %d retries, skipping logging\n", HIST_RETRY);
            return -1;
        }
    }

    *object_temp = object_temp[1];
    *ambient_temp = object_temp[0];
    return ret;
}

int main() {
    struct fan_state fan_state;
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) || signal(SIGTERM, sigterm_handler)) {
        fprintf(stderr, "Failed to install signal handlers\n");
        return EXIT_FAILURE;
    }

    fan_init(&fan_state);

    while (true) {
        uint8_t object_temp, ambient_temp;
        time_t now;
        time(&now);

        if (read_mlx90614(&object_temp, &ambient_temp) < 0) {
            continue;
        }

        if (object_temp > TEMP_THRESHOLD_HIGH) {
            gpiod_set_value(fan_state.line, 1);
            fan_state.on = true;
        } else if (object_temp < TEMP_THRESHOLD_LOW) {
            gpiod_set_value(fan_state.line, 0);
            fan_state.on = false;
        }

        fprintf(log_file, "%ld,%d,%d\n", now, object_temp, ambient_temp);
        fflush(log_file);

        sleep(READ_INTERVAL / 1000);
    }

    fclose(log_file);
    fan_cleanup(&fan_state);
    return EXIT_SUCCESS;
}

