void *read_sensor(void *arg) {
    int retries = RETRY_COUNT;
    int fd = wiringPiI2C_rmio(SHT40_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return NULL;
    }

    while (server_running) {
        for (int i = 0; i < retries; ++i) {
            // Issue measurement command
            write(fd, "0x2C 0x06\r\n", 8);

            // Wait at least 10 ms
            usleep(10000);

            // Read exactly six bytes
            char response[6];
            int bytes_read = read(fd, response, 6);
            if (bytes_read != 6) {
                fprintf(stderr, "Failed to read from sensor\n");
                break;
            }

            // Process the response
            uint16_t temp_lsb = (response[1] << 8) | response[2];
            uint16_t temp_msb = (response[3] << 8) | response[4];
            float temperature = (float)(temp_msb << 8 | temp_lsb) * 0.01 - 45.0;

            uint16_t hum_lsb = (response[5] << 8) | response[6];
            uint16_t hum_msb = (response[7] << 8) | response[8];
            uint16_t humidity = (uint16_t)((hum_msb << 8 | hum_lsb) * 100.0);
            humidity = humidity > 100 ? 100 : humidity;

            SensorData data = {temperature, humidity};
            char buffer[100];
            snprintf(buffer, sizeof(buffer), "Temperature: %.2f C, Humidity: %u%%", temperature, humidity);

            // Send the data to the HTTP server
            http_server_send_response(server, buffer, strlen(buffer));
        }

        if (!server_running) {
            break;
        }
    }

    close(fd);
    return NULL;
}

void response_handler(void *arg) {
    // Handle HTTP requests
}

int main(int argc, char *argv[]) {
    const gpiod_chip_params_t chip_params = {
        .gpio_chip_class = "wiringPiI2C",
        .gpios = {GPIO_I2C_SDA, GPIO_I2C_SCL},
    };

    int ret = gpiod_chip_init(&chip_params);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip\n");
        return ret;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t thread;
    ret = pthread_create(&thread, NULL, read_sensor, NULL);
    if (ret != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return ret;
    }

    start_server();

    pthread_join(thread, NULL);
    stop_server();

    gpiod_chip_uninit();
    return 0;
}

