#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>
#include <gpiod.h>

#define TMP102_ADDR 0x48
#define I2C_BUS 1

struct tmp102_data {
    int fd;
    uint8_t reg[2];
};

static int tmp102_read(struct tmp102_data *data, int16_t *temp)
{
    uint8_t buf[2];

    if (gpiod_iomap(data->fd)) {
        fprintf(stderr, "Failed to map GPIO\n");
        return -errno;
    }

    buf[0] = 0x01; // Read temp register
    if (write(data->fd, &buf[0], 1) != 1) {
        fprintf(stderr, "Failed to write to I2C\n");
        return -errno;
    }

    if (read(data->fd, &buf[1], 1) != 1) {
        fprintf(stderr, "Failed to read from I2C\n");
        return -errno;
    }

    *temp = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void sigint_handler(int signum)
{
    printf("Ctrl+C detected, cleaning up...\n");
    gpiod_unmap(data->fd);
    close(data->fd);
    pigpio_terminate();
    exit(0);
}

int main()
{
    struct tmp102_data data;
    int ret;
    int16_t temp;
    char timestamp[20];
    FILE *fp;

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return 1;
    }

    data.fd = open("/dev/i2c-1", O_RDWR);
    if (data.fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    data.reg[0] = TMP102_ADDR;
    data.reg[1] = 0x00; // Configuration register

    if (io_mapping_setup(&data, data.fd) < 0) {
        close(data.fd);
        return 1;
    }

    fp = fopen("temperature_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open CSV file\n");
        close(data.fd);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        ret = tmp102_read(&data, &temp);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            continue;
        }

        fprintf(fp, "%s, %.2f\n", timestamp, (double)temp / 100);
        fprintf(stdout, "%s, %.2f\n", timestamp, (double)temp / 100);
        sleep(5);
    }

    fclose(fp);
    gpiod_unmap(data.fd);
    close(data.fd);
    pigpio_terminate();
    return 0;
}

