#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define MAX_RETRIES 5
#define MEASUREMENT_CONFIG_REG 0x00
#define BIT_0 0x01
#define TIMEOUT_MS 500

volatile sig_atomic_t shutdown_flag = 0;

static int i2c_fd = -1;
static struct pigio *pio = NULL;

static void signal_handler(int signum) {
    shutdown_flag = 1;
}

static int i2c_read_bit(int fd, uint8_t reg_addr) {
    uint8_t data;
    int ret;

    ret = pigio_i2c_read_byte(pio, i2c_fd, reg_addr, &data);
    if (ret < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    return (data & BIT_0) ? 1 : 0;
}

static uint16_t i2c_read_temperature_humidity(int fd) {
    uint16_t value = 0;
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (i2c_read_bit(fd, MEASUREMENT_CONFIG_REG) == 1) {
            value = pigio_i2c_read_word(pio, i2c_fd, 0x01);
            break;
        }

        retries--;
        if (retries > 0) {
            // Retry after a short delay
            usleep(100000);
        } else {
            fprintf(stderr, "Timeout waiting for sensor ready\n");
            return -1;
        }
    }

    return value;
}

int main() {
    struct sigaction sa;
    int ret;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret == -1) {
        fprintf(stderr, "Error setting signal handler\n");
        return 1;
    }

    pio = pigpio(0, 0);
    if (!pio) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = gpiod_i2c_open(1, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C open failed\n");
        return 1;
    }

    while (!shutdown_flag) {
        uint16_t temp_humidity = i2c_read_temperature_humidity(i2c_fd);
        if (temp_humidity != -1) {
            printf("Temperature: %u, Humidity: %u\n", temp_humidity & 0x3FF, (temp_humidity >> 10) & 0x3FF);
        }

        sleep(5);
    }

    gpiod_i2c_close(i2c_fd);
    pigpio_terminate(pio);

    return 0;
}

