#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>

#define SDP800_I2C_ADDR 0x48
#define SDP800_CRC_POLY 0x31
#define SDP800_CRC_INIT 0xFFFF

typedef struct {
    int fd;
    gpiod_chip *chip;
} sdp800_context;

static int sdp800_read(sdp800_context *ctx, uint8_t *data, size_t len) {
    int ret;
    ret = ioctl(ctx->fd, I2C_SLAVE, SDP800_I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to acquire I2C bus\n");
        return ret;
    }

    ret = i2c_rdwr_start(ctx->fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to start I2C transaction\n");
        return ret;
    }

    ret = i2c_write(ctx->fd, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return ret;
    }

    ret = i2c_rdwr(ctx->fd, data, len);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return ret;
    }

    i2c_rdwr_stop(ctx->fd);
    return ret;
}

static int sdp800_crc8(uint8_t *data, size_t len, uint8_t init_value, uint8_t poly) {
    uint8_t crc = init_value;
    for (size_t i = 0; i < len; i++) {
        for (int j = 0; j < 8; j++) {
            crc ^= data[i] << j;
            if (crc & 0x80) {
                crc ^= poly;
            }
        }
    }
    return crc;
}

static int sdp800_validate_crc(uint8_t *data, size_t len) {
    uint8_t crc_calc = sdp800_crc8(data, len - 2, SDP800_CRC_INIT, SDP800_CRC_POLY);
    for (size_t i = 0; i < len - 1; i += 2) {
        if (data[i + 1] != (crc_calc >> 8) || data[i + 2] != (crc_calc & 0xFF)) {
            return 0;
        }
    }
    return 1;
}

static void sdp800_cleanup(sdp800_context *ctx) {
    close(ctx->fd);
    gpiod_chip_put(ctx->chip);
}

static void sigint_handler(int signum) {
    sdp800_cleanup(ctx);
    exit(0);
}

int main() {
    sdp800_context ctx;
    ctx.fd = open("/dev/i2c-1", O_RDWR);
    if (ctx.fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    ctx.chip = gpiod_chip_open(wiringPiI2CGetBus(1), 0);
    if (!ctx.chip) {
        fprintf(stderr, "Failed to initialize driver library\n");
        close(ctx.fd);
        return 1;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        sdp800_cleanup(&ctx);
        return 1;
    }

    uint8_t data[6];
    while (1) {
        if (sdp800_read(&ctx, data, 6) < 0) {
            fprintf(stderr, "Error during I2C read\n");
            break;
        }

        if (!sdp800_validate_crc(data, 6)) {
            fprintf(stderr, "CRC mismatch\n");
            break;
        }

        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[3] << 8) | data[4];

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
        usleep(45 * 1000);
    }

    sdp800_cleanup(&ctx);
    return 0;
}
