#include <wiringPiI2C.h>
#include <pigpio.h>

#define DS18X_BUS 4
#define RELAY_PIN 11
#define PWM_PIN 12
#define SETPOINT_FILE "/sys/bus/w1/devices/28-0x5b/temperature"
#define LOG_FILE "greenhouse.log"

float Kp, Ki, Kd;
float setpoint, prev_error, integral;
float output;

void sigint_handler(int signum) {
    // Clean up resources here
}

void setup() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to initialize wiringPi: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_errorString(pigpio_terminate()));
        exit(EXIT_FAILURE);
    }

    if (wiringPiI2CSetup(0x28) == -1) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetMode(DS18X_BUS, PI_OUTPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    if (gpioSetPWMfrequency(PWM_PIN) < 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", pigpio_errorString(pigpio_terminate()));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMdutycycle(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set initial PWM duty cycle: %s\n", pigpio_errorString(pigpio_terminate()));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(RELAY_PIN, 0);

    if (setvbuf(stdout, NULL, _IONBF, 0) == ferror(stdout)) {
        fprintf(stderr, "Failed to set unbuffered stdout: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (setvbuf(stderr, NULL, _IONBF, 0) == ferror(stdout)) {
        fprintf(stderr, "Failed to set unbuffered stderr: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((log_fd = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
}

float read_temperature() {
    char path[256];
    FILE *fp;
    float temp;

    snprintf(path, sizeof(path), SETPOINT_FILE);
    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(path, sizeof(path), fp)) {
        sscanf(path, "%*s %f", &temp);
        fclose(fp);
        return temp;
    }

    fclose(fp);
    return -1;
}

void pid_control() {
    float current_temp = read_temperature();

    if (current_temp < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }

    prev_error = output;
    integral += current_temp - setpoint;
    float error = current_temp - setpoint;

    output = Kp * error + Ki * integral + Kd * (error - prev_error);

    gpioWrite(RELAY_PIN, (output > 0) ? HIGH : LOW);
    gpioSetPWMdutycycle(PWM_PIN, abs(output));
}

int main(int argc, char *argv[]) {
    int opt;
    struct tm tm;
    time_t now;

    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    setup();

    while (1) {
        pid_control();

        now = time(NULL);
        localtime_r(&now, &tm);

        fprintf(log_fd, "%02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                current_temp, setpoint, output);

        fflush(log_fd);

        sleep(5);
    }

    gpioTerminate();
    fclose(log_fd);
    return EXIT_SUCCESS;
}

