#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <syslog.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>

#define HTU21D_ADDR 0x76
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60

struct humidity_data {
    int humidity;
};

void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_ERR, format, args);
    va_end(args);
}

int i2c_read(uint8_t reg, char *buf, int len) {
    int ret;
    ret = wiringPiI2C_rdwr(HTU21D_ADDR, 0x00, len);
    if (ret < 0) {
        log_error("I2C read error: %s\n", strerror(errno));
        return -1;
    }
    memcpy(buf, (void *)i2c_rdwr.data, len);
    return 0;
}

int http_post(const struct humidity_data *data) {
    int sockfd, ret;
    struct sockaddr_in serv_addr;
    char *http_post_data;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        log_error("Socket creation failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, API_ENDPOINT + ":80", &serv_addr.sin_addr) <= 0) {
        log_error("Invalid address/ Address not supported\n");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        log_error("Connection failed: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    http_post_data = malloc(100);
    sprintf(http_post_data, "POST /humidity HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %d\r\n\r\n%d",
            API_ENDPOINT, strlen(json_data), data->humidity);

    ret = write(sockfd, http_post_data, strlen(http_post_data));
    close(sockfd);
    free(http_post_data);

    if (ret < 0) {
        log_error("HTTP POST failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    gpiod_context ctx;
    gpiod_chip chip;
    int ret;
    struct humidity_data humidity_data;
    char buf[3];
    char json_data[100];

    if (gpiod_new(&ctx) < 0) {
        log_error("Failed to create gpiod context\n");
        return EXIT_FAILURE;
    }

    ret = gpiod_enumerate(ctx, &chip);
    if (ret < 0) {
        log_error("Failed to enumerate GPIOs\n");
        goto out_ctx;
    }

    if (gpiod_chip_get_line(chip, "i2c-1", 0, &ctx->dev) < 0) {
        log_error("Failed to get i2c-1 line\n");
        goto out_chip;
    }

    if (i2c_read(0x06, buf, 2) < 0) {
        goto out_dev;
    }

    humidity_data.humidity = (buf[1] << 8) | buf[0];

    sprintf(json_data, "{\"humidity\": %d}", humidity_data.humidity);

    while (1) {
        if (http_post(&humidity_data) < 0) {
            log_error("HTTP POST error, retrying in 60 seconds...\n");
            sleep(POLL_INTERVAL);
            continue;
        }

        syslog(LOG_INFO, "Humidity data posted: %d\n", humidity_data.humidity);
        sleep(POLL_INTERVAL);
    }

out_dev:
    gpiod_drain_delete(ctx->dev);
out_chip:
    gpiod_chip_put(chip);
out_ctx:
    gpiod_context_destroy(ctx);

    return EXIT_SUCCESS;
}

