#include <signal.h>
#include <gpio.h>

#define BMP280_ADDR 0x77
#define CHIP_ID_BMP280 0x60
#define MAX_RETRIES 3

static volatile sig_atomic_t sigint_received = 0;
static gpio_context i2c_sda, i2c_scl;
static gpiod_chip chip;
static gpiod_pull pulls[] = {GPIOD_PULL_UP, GPIOD_PULL_DOWN};

void sigint_handler(int signum) {
    sigint_received = 1;
}

void setup_i2c() {
    if (gpiod_chip_open(&chip, "gpio-i2c-sda") < 0 ||
        gpiod_chip_open(&chip, "gpio-i2c-scl") < 0) {
            fprintf(stderr, "Failed to open I2C GPIO chip\n");
            exit(EXIT_FAILURE);
    }

    if (gpiod_chip_export(&chip, NULL) < 0) {
        fprintf(stderr, "Failed to export I2C GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_set_pull(&chip, &i2c_sda, pulls[0]) < 0 ||
        gpiod_chip_set_pull(&chip, &i2c_scl, pulls[1]) < 0) {
            fprintf(stderr, "Failed to set pull-up/pull-down resistors\n");
            exit(EXIT_FAILURE);
    }

    i2c_sda = gpiod_chip_get_context(&chip, "gpio-i2c-sda");
    i2c_scl = gpiod_chip_get_context(&chip, "gpio-i2c-scl");
}

bool read_bmp280(uint8_t *data, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_master_start(&i2c_sda, &i2c_scl) < 0 ||
            i2c_write_byte(&i2c_sda, &i2c_scl, BMP280_ADDR | 0) < 0 ||
            i2c_read_bytes(&i2c_sda, &i2c_scl, data, len) < 0) {
                retries++;
                sleep(1);
                continue;
        }

        if (data[0] == CHIP_ID_BMP280) {
            return true;
        } else {
            i2c_master_stop(&i2c_sda, &i2c_scl);
            return false;
        }
    }

    fprintf(stderr, "Failed to read from BMP280 after %d retries\n", MAX_RETRIES);
    return false;
}

float apply_compensation(uint16_t p) {
    // Implement Bosch compensation formulas here
    return (float)p / 100.0;
}

void log_pressure(float pressure) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open pressure_log.txt\n");
        return;
    }

    fprintf(fp, "%s: %f hPa\n", timestamp, pressure);
    fclose(fp);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_i2c();

    uint8_t data[6];
    float pressure;

    while (1) {
        if (!read_bmp280(data, 6)) {
            continue;
        }

        pressure = apply_compensation(data[1] << 8 | data[0]);

        if (pressure > 1020 || pressure < 980) {
            log_pressure(pressure);
        }

        sleep(2);
    }

    gpio_free(&i2c_sda);
    gpio_free(&i2c_scl);
    gpiod_chip_unexport(&chip);

    return 0;
}

