#include <i2c/client.h>

#define TMP117_ADDR 0x44
#define AHT20_ADDR 0x28
#define PIR_GPIO 17

struct sensor_data {
    char timestamp[20];
    float temperature;
    int humidity;
    int motion_detected;
};

static int i2c_fd;
static struct gpiod_chip *pir_chip;
static struct gpiod_chip_cq *pir_cq;
static struct i2c_client *tmp117_client;
static struct i2c_client *aht20_client;

void init_pir_sensor() {
    pir_chip = gpiod_chip_open(PIR_GPIO, "pir-sensor");
    if (!pir_chip) {
        fprintf(stderr, "Failed to initialize PIR sensor\n");
        exit(EXIT_FAILURE);
    }
    pir_cq = gpiod_chip_alloc_cq(pir_chip);
    if (!pir_cq) {
        fprintf(stderr, "Failed to allocate PIR sensor CQ\n");
        exit(EXIT_FAILURE);
    }
    gpiod_chip_add_cq(pir_chip, pir_cq);
    gpiod_chip_enable_line(pir_chip, 0, true);
}

void init_i2c_sensors() {
    i2c_fd = i2c_open(0, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    tmp117_client = i2c_get_client(TMP117_ADDR);
    if (!tmp117_client) {
        fprintf(stderr, "Failed to find TMP117 sensor\n");
    }

    aht20_client = i2c_get_client(AHT20_ADDR);
    if (!aht20_client) {
        fprintf(stderr, "Failed to find AHT20 sensor\n");
    }
}

float read_tmp117_temp() {
    float temp;
    int retries = 3;
    for (; retries > 0; --retries) {
        int ret = i2c_rdwr(i2c_fd, &tmp117_client->user_data, 2, &temp, sizeof(temp), 0);
        if (ret >= 0) {
            return temp;
        }
        usleep(10 * 1000);
    }
    fprintf(stderr, "Failed to read TMP117 temperature after %d retries\n", retries);
    exit(EXIT_FAILURE);
}

int read_aht20_humidity() {
    int8_t data[3];
    int ret = i2c_rdwr(i2c_fd, &aht20_client->user_data, 3, data, sizeof(data), 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to read AHT20 humidity\n");
        return -1;
    }
    // Process data[0] and data[1] to get humidity value
    return (int)data[0];
}

int read_pir_motion() {
    int value;
    ret = gpiod_batch_start(pir_cq);
    if (ret < 0) {
        fprintf(stderr, "Failed to start PIR motion detection\n");
        return -1;
    }
    gpiod_chip_get_value(pir_chip, 0, &value);
    gpiod_batch_submit(pir_cq);
    return value;
}

void log_sensor_data(const struct sensor_data *data) {
    char filename[30];
    time_t now = time(NULL);
    strftime(data->timestamp, sizeof(data->timestamp), "%Y-%m-%d", localtime(&now));
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(fp, "%s,%.1f,%d,%d\n", data->timestamp, data->temperature, data->humidity, data->motion_detected);
    fclose(fp);
}

int main() {
    init_pir_sensor();
    init_i2c_sensors();

    while (1) {
        struct sensor_data data;

        data.temperature = read_tmp117_temp();
        data.humidity = read_aht20_humidity();
        if (data.humidity < 0) {
            fprintf(stderr, "Error reading AHT20 humidity, continuing...\n");
        }
        data.motion_detected = read_pir_motion();

