#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_GPIO 17
#define ENA_GPIO 22
#define IN1_GPIO 23
#define IN2_GPIO 24
#define POLL_INTERVAL 2

static struct gpiod_chip *chip;
static struct gpiod_line *rain_sensor_line;
static struct gpiod_line *ena_line;
static struct gpiod_line *in1_line;
static struct gpiod_line *in2_line;

void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args);
    va_end(args);
}

void timestamp_log(const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    vfprintf(stdout, "%s: ", timestamp);
    vfprintf(stdout, format, args);
    va_end(args);
}

void motor_control(int rain_detected) {
    if (rain_detected) {
        timestamp_log("Motor started due to rain detection.\n");
        gpiod_trigger(ena_line, 1);
        gpiod_trigger(in1_line, 1);
        gpiod_trigger(in2_line, 0);
        sleep(5);
        gpiod_trigger(ena_line, 0);
        gpiod_trigger(in1_line, 0);
        gpiod_trigger(in2_line, 0);
        timestamp_log("Motor stopped after 5 seconds.\n");
    }
}

int main() {
    chip = gpiod_chip_open(NULL, "GPIO");
    if (!chip) {
        log_error("Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    rain_sensor_line = gpiod_chip_get_line(chip, "GPIO17");
    if (!rain_sensor_line) {
        log_error("Failed to get rain sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ena_line = gpiod_chip_get_line(chip, "GPIO22");
    if (!ena_line) {
        log_error("Failed to get ENA line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    in1_line = gpiod_chip_get_line(chip, "GPIO23");
    if (!in1_line) {
        log_error("Failed to get IN1 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    in2_line = gpiod_chip_get_line(chip, "GPIO24");
    if (!in2_line) {
        log_error("Failed to get IN2 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_export(rain_sensor_line, "rain_sensor");
    gpiod_export(ena_line, "ena");
    gpiod_export(in1_line, "in1");
    gpiod_export(in2_line, "in2");

    gpiod_set_value(rain_sensor_line, 1); // Active-low sensor, pull-up resistor
    gpiod_set_value(ena_line, 0);
    gpiod_set_value(in1_line, 0);
    gpiod_set_value(in2_line, 1);

    struct sigaction sa;
    sa.sa_handler = motor_stop;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_error("Failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to install SIGTERM handler\n");
    }

    while (1) {
        int rain_detected = gpiod_get_value(rain_sensor_line);
        motor_control(rain_detected);
        sleep(POLL_INTERVAL);
    }

    gpiod_unexport(rain_sensor_line);
    gpiod_unexport(ena_line);
    gpiod_unexport(in1_line);
    gpiod_unexport(in2_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

void motor_stop() {
    gpiod_trigger(ena_line, 0);
    gpiod_trigger(in1_line, 0);
    gpiod_trigger(in2_line, 0);
}

