#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27

#define PWM_FREQ 800
#define PWM_RANGE 255

struct cpu_load {
    unsigned long prev_load[2];
    unsigned long cur_load;
};

static struct cpu_load cpu_load_data;
static int red_chip, green_chip, blue_chip;
static int pwm_red, pwm_green, pwm_blue;

void cpu_load_sample() {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Failed to open /proc/stat");
        exit(1);
    }

    fscanf(fp, "%*s");
    cpu_load_data.prev_load[0] = strtoul(fscanf(fp, "%*s").buffer, NULL, 0);
    fscanf(fp, "%*s");
    cpu_load_data.prev_load[1] = strtoul(fscanf(fp, "%*s").buffer, NULL, 0);
    cpu_load_data.cur_load = strtoul(fscanf(fp, "%*s").buffer, NULL, 0);
    fclose(fp);
}

unsigned int cpu_load_percent() {
    unsigned long delta_load = cpu_load_data.cur_load - cpu_load_data.prev_load[1];
    cpu_load_data.prev_load[0] = cpu_load_data.prev_load[1];
    cpu_load_data.prev_load[1] = cpu_load_data.cur_load;
    return (unsigned int)((delta_load * 100) / (sysconf(_SC_CLK_TCK)));
}

void init_gpio() {
    int ret;

    ret = gpiod_in_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(1);
    }

    red_chip = gpiod_chip_open(gpiod_in_get_chip(RED_GPIO), "RGB-Red");
    if (!red_chip) {
        fprintf(stderr, "Failed to open GPIO%d\n", RED_GPIO);
        gpiod_in_exit();
        exit(1);
    }

    green_chip = gpiod_chip_open(gpiod_in_get_chip(GREEN_GPIO), "RGB-Green");
    if (!green_chip) {
        fprintf(stderr, "Failed to open GPIO%d\n", GREEN_GPIO);
        gpiod_in_exit();
        exit(1);
    }

    blue_chip = gpiod_chip_open(gpiod_in_get_chip(BLUE_GPIO), "RGB-Blue");
    if (!blue_chip) {
        fprintf(stderr, "Failed to open GPIO%d\n", BLUE_GPIO);
        gpiod_in_exit();
        exit(1);
    }

    pwm_red = gpiod_chip_get_line(red_chip, "PWM");
    pwm_green = gpiod_chip_get_line(green_chip, "PWM");
    pwm_blue = gpiod_chip_get_line(blue_chip, "PWM");

    if (!pwm_red || !pwm_green || !pwm_blue) {
        fprintf(stderr, "Failed to get PWM lines\n");
        gpiod_in_exit();
        exit(1);
    }

    gpiod_chip_enable_output_signals(red_chip);
    gpiod_chip_enable_output_signals(green_chip);
    gpiod_chip_enable_output_signals(blue_chip);

    gpiod_set_value(pwm_red, 0);
    gpiod_set_value(pwm_green, 0);
    gpiod_set_value(pwm_blue, 0);
}

void cleanup_gpio() {
    gpiod_chip_disable_output_signals(red_chip);
    gpiod_chip_disable_output_signals(green_chip);
    gpiod_chip_disable_output_signals(blue_chip);
    gpiod_chip_close(red_chip);
    gpiod_chip_close(green_chip);
    gpiod_chip_close(blue_chip);
    gpiod_in_exit();
}

void signal_handler(int signum) {
    (void)signum;
    gpiod_set_value(pwm_red, 0);
    gpiod_set_value(pwm_green, 0);
    gpiod_set_value(pwm_blue, 0);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_gpio();

    cpu_load_sample();

    while (1) {
        unsigned int load_percent = cpu_load_percent();

        if (load_percent < 25) {
            gpiod_set_value(pwm_red, 0);
            gpiod_set_value(pwm_green, PWM_RANGE);
            gpiod_set_value(pwm_blue, 0);
        } else if (load_percent < 75) {
            gpiod_set_value(pwm_red, 0);
            gpiod_set_value(pwm_green, PWM_RANGE - (load_percent - 25) * (PWM_RANGE / 50));
            gpiod_set_value(pwm_blue, 0);
        } else {
            gpiod_set_value(pwm_red, PWM_RANGE - (load_percent - 50) * (PWM_RANGE / 50));
            gpiod_set_value(pwm_green, 0);
            gpiod_set_value(pwm_blue, PWM_RANGE);
        }

        sleep(0.5);
    }

    cleanup_gpio();
    return 0;
}

