int bme280_read(int fd, struct bme280_data *data) {
    uint8_t buf[7];
    int ret;

    if ((ret = pioctl(fd, I2C_RDWR, I2C_RD(BME280_REG_TEMPMSPS, 2), buf, 2)) < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return ret;
    }

    data->temp = (int16_t)((buf[1] << 8) | buf[0]);

    if ((ret = pioctl(fd, I2C_RDWR, I2C_RD(BME280_REG_HUM, 2), buf, 2)) < 0) {
        fprintf(stderr, "Failed to read humidity: %s\n", strerror(errno));
        return ret;
    }

    data->humidity = (int16_t)((buf[1] << 8) | buf[0]);

    if ((ret = pioctl(fd, I2C_RDWR, I2C_RD(BME280_REG_PRESS, 2), buf, 2)) < 0) {
        fprintf(stderr, "Failed to read pressure: %s\n", strerror(errno));
        return ret;
    }

    data->pressure = (int16_t)((buf[1] << 8) | buf[0]);

    return 0;
}

int bme280_init(int *fd) {
    int ret;
    struct i2c_rdwr_ioctl_data rdwr;

    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    rdwr.flags = 0;
    rdwr.nbytes = 1;
    rdwr.i2c_addr = BME280_ADDR;
    rdwr.buf = &ret;
    rdwr.buf[0] = BME280_REG_ID;
    ret = ioctl(*fd, I2C_RDWR, &rdwr);
    if (ret < 0) {
        fprintf(stderr, "Failed to read BME280 chip ID: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (ret != 0x58) {
        fprintf(stderr, "BME280 chip ID mismatch: 0x%02x\n", ret);
        close(*fd);
        return -1;
    }

    close(*fd);
    return 0;
}

int log_bme280_data(FILE *fp, struct bme280_data *data) {
    char timestamp[20];
    time_t now;
    struct tm *timeinfo;

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%F %T", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data->temp, data->humidity, data->pressure);
    return 0;
}

int main() {
    int fd;
    struct bme280_data data;
    FILE *log_file;

    if (bme280_init(&fd) < 0) {
        fprintf(stderr, "Failed to initialize BME280 sensor\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (1) {
        if (bme280_read(fd, &data) < 0) {
            break;
        }

        if (log_bme280_data(log_file, &data) < 0) {
            break;
        }

        usleep(5000000);
    }

    fclose(log_file);
    close(fd);

    return 0;
}

