#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define BUFFER_SIZE (60 * 50 / 1000) // 60 seconds at 50ms intervals
#define DEV_BMP180 "bmp180"
#define I2C_ADDR_BMP180 0x77
#define GPIO_ALERT 24

typedef struct {
    float pressure;
    time_t timestamp;
} PressureSample;

PressureSample buffer[BUFFER_SIZE];
int buffer_index = 0;
float rolling_average = 0;

void signal_handler(int signum) {
    gpiod_unclaim(gpio);
    close(i2c_fd);
    exit(signum);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    int i2c_fd;
    struct i2c_client *client;
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_msg messages[1];
    int ret;

    // Initialize GPIO for alert
    ret = gpiod_chip_open(&chip, "gpioexpander");
    if (ret) {
        fprintf(stderr, "Failed to open gpioexpander chip: %d\n", ret);
        return 1;
    }

    ret = gpiod_chip_get_line(&line, &chip, GPIO_ALERT, gpiod_line_in);
    if (ret) {
        fprintf(stderr, "Failed to get line for GPIO%d: %d\n", GPIO_ALERT, ret);
        return 1;
    }

    ret = gpiod_line_export(&line);
    if (ret) {
        fprintf(stderr, "Failed to export line for GPIO%d: %d\n", GPIO_ALERT, ret);
        return 1;
    }

    ret = gpiod_line_request_set(&line, true);
    if (ret) {
        fprintf(stderr, "Failed to request line for GPIO%d: %d\n", GPIO_ALERT, ret);
        return 1;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    client = i2c_get_client(i2c_fd);
    if (!client) {
        close(i2c_fd);
        perror("Failed to get I2C client");
        return 1;
    }

    messages[0].len = 2;
    messages[0].addr = I2C_ADDR_BMP180;
    messages[0].flags = 0;
    messages[0].data = (uint8_t *) &rdwr;

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (1) {
        rdwr.buf = (unsigned char *) &buffer[buffer_index];
        rdwr.len = sizeof(PressureSample);
        rdwr.flags = I2C_M_RD;

        ret = ioctl(i2c_fd, I2C_RDWR, &rdwr);
        if (ret < 0) {
            fprintf(stderr, "I2C read failed: %d\n", ret);
            break;
        }

        if (ret != 2) {
            fprintf(stderr, "I2C transfer error: expected 2 bytes, got %d\n", ret);
            break;
        }

        buffer[buffer_index].pressure = (float)((rdwr.buf[1] << 8) | rdwr.buf[0]);
        buffer[buffer_index].timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Compute rolling average
        rolling_average = (rolling_average * (BUFFER_SIZE - 1) + buffer[buffer_index].pressure) / BUFFER_SIZE;

        // Check for alert condition
        if (abs(buffer[buffer_index].pressure - rolling_average) > 5) {
            fprintf(stderr, "Pressure alert: %f hPa\n", buffer[buffer_index].pressure);
            gpiod_line_trigger(&line, true);
        }

        // Sleep for 50ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 50 * 1000 * 1000;
        nanosleep(&ts, NULL);
    }

    // Clean up
    gpiod_line_unref(&line);
    gpiod_chip_close(&chip);
    close(i2c_fd);

    return 0;
}

