#define BMP280_ADDR_DEFAULT  0x77
#define BMP280_ADDR_ALT      0x76
#define CTRL_MEAS_REG       0xF4
#define TEMP_MSB_REG        0xF6
#define TEMP_LSB_REG        0xF7
#define TEMP_UNC_REG        0xF8
#define PRESS_MSB_REG       0xF0
#define PRESS_LSB_REG       0xF1
#define PRESS_UNC_REG       0xF2
#define CHIP_ID_REG         0xD0

#define I2C_BUS "/dev/i2c-1"
#define WEATHER_DATA_FILE "weather_data.txt"

static int i2c_fd = -1;
static int bmp280_addr = BMP280_ADDR_DEFAULT;

static int bmp280_read(uint8_t reg, uint8_t *buf, int len) {
    if (len != 1 && len != 2 && len != 3) {
        errno = EINVAL;
        return -1;
    }

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int bmp280_write(uint8_t reg, uint8_t val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (write(i2c_fd, &val, 1) != 1) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int bmp280_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_export(&bmp280_gpio, "bmp280-sda") < 0 ||
        gpiod_export(&bmp280_gpio, "bmp280-scl") < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    bmp280_gpio.direction = GPIO_DIR_OUT;
    bmp280_gpio.value[0] = 0;
    bmp280_gpio.value[1] = 0;

    return 0;
}

static void bmp280_cleanup() {
    close(i2c_fd);
    gpiod_unexport(&bmp280_gpio);
}

int main() {
    struct bmp280_data data;
    FILE *fp;
    char timestamp[20];
    int ret;

    bmp280_gpio = gpiod_chip_create_from_index(0);

    if (bmp280_init() < 0) {
        bmp280_cleanup();
        return -1;
    }

    while (1) {
        ret = bmp280_read(CHIP_ID_REG, &data.chip_id, 1);
        if (ret < 0) {
            break;
        }

        ret = bmp280_read(CTRL_MEAS_REG, &data.ctrl_meas, 1);
        if (ret < 0) {
            break;
        }

        data.ctrl_meas |= 0x80; // Force mode
        ret = bmp280_write(CTRL_MEAS_REG, data.ctrl_meas);
        if (ret < 0) {
            break;
        }

        ret = bmp280_read(TEMP_MSB_REG, &data.temp_msb, 3);
        if (ret < 0) {
            break;
        }

        ret = bmp280_read(TEMP_LSB_REG, &data.temp_lsb, 2);
        if (ret < 0) {
            break;
        }

        ret = bmp280_read(TEMP_UNC_REG, &data.temp_unc, 1);
        if (ret < 0) {
            break;
        }

        ret = bmp280_read(PRESS_MSB_REG, &data.press_msb, 3);
        if (ret < 0) {
            break;
        }

        ret = bmp280_read(PRESS_LSB_REG, &data.press_lsb, 2);
        if (ret < 0) {
            break;
        }

        ret = bmp280_read(PRESS_UNC_REG, &data.press_unc, 1);
        if (ret < 0) {
            break;
        }

        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fp = fopen(WEATHER_DATA_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening weather_data.txt: %s\n", strerror(errno));
            break;
        }

        if (fputs(timestamp, fp) < 0) {
            fprintf(stderr, "Error writing to weather_data.txt: %s\n", strerror(errno));
            fclose(fp);
            break;
        }

        if (fprintf(fp, ", Temperature: %d.%02d °C, Pressure: %d.%02d hPa\n",
            data.temperature, data.temperature_uncertainty,
            data.pressure, data.pressure_uncertainty) < 0) {
            fprintf(stderr, "Error writing to weather_data.txt: %s\n", strerror(errno));
            fclose(fp);
            break;
        }

        fclose(fp);

        sleep(5);
    }

    bmp280_cleanup();
    return 0;
}

