This code initializes the I2C bus and GPIO pins, reads temperature and pressure from the Bosch BMP280 sensor, applies the 64-bit compensation formulas, and appends the data to `weather_data.txt` every five seconds. It handles errors for I/O operations and exits gracefully on SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define LM75_ADDR 0x48
#define BUFFER_SIZE 60
#define LED_GPIO 18
#define CHECK_INTERVAL_MS 1000

int i2c_fd = -1;
int gpio_chip = -1;
int gpio_line = -1;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
int buffer[BUFFER_SIZE];
int buffer_index = 0;
float running_avg = 0.0;
unsigned int sample_count = 0;

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    const char *led_gpio_path = "/sys/class/gpio/gpio%d";
    char path[32];

    gpio_chip = gpiod_find_chip(NULL, "gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to find GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, "gpio18");
    if (!gpio_line) {
        fprintf(stderr, "Failed to find GPIO line\n");
        exit(EXIT_FAILURE);
    }

    snprintf(path, sizeof(path), led_gpio_path, LED_GPIO);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open GPIO export file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(fp, "out\n");
    fclose(fp);

    if (gpiod_export(gpio_line) < 0) {
        fprintf(stderr, "Failed to export GPIO\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpiod_unexport(gpio_line);
    remove(path);
}

void *read_temperature(void *arg) {
    while (1) {
        int r;
        struct i2c_rdwr_ioctl_data rd_data;
        rd_data.u8 = &r;
        rd_data.len = 1;
        rd_data.addr = LM75_ADDR;

        r = ioctl(i2c_fd, I2C_MASTER_RDWR(1, true), &rd_data);
        if (r < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        if (r == 0) {
            fprintf(stderr, "Sensor absent\n");
            r = ioctl(i2c_fd, I2C_SLAVE(LM75_ADDR), NULL);
            if (r < 0) {
                fprintf(stderr, "Failed to release I2C bus\n");
                exit(EXIT_FAILURE);
            }
            continue;
        }

        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_index] = r;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        sample_count = (sample_count + 1) % BUFFER_SIZE;
        running_avg = (running_avg * sample_count + r) / (float)sample_count;
        pthread_mutex_unlock(&buffer_mutex);

        if (r > 28.0) {
            gpiod_trigger(gpio_line, NULL, true);
        } else {
            gpiod_trigger(gpio_line, NULL, false);
        }

        usleep(CHECK_INTERVAL_MS * 1000);
    }
}

int main(int argc, char *argv[]) {
    init_i2c();
    init_gpio();

    pthread_t thread;
    pthread_create(&thread, NULL, read_temperature, NULL);

    while (1) {
        pthread_mutex_lock(&buffer_mutex);
        printf("Temperature: %.2f C, Avg: %.2f C\n", buffer[buffer_index], running_avg);
        pthread_mutex_unlock(&buffer_mutex);
        sleep(1);

        if (kill(getppid(), SIGINT) != 0) {
            break;
        }
    }

    cleanup_gpio();
    close(i2c_fd);
    pthread_join(thread, NULL);

    return 0;
}

