        printf("Temperature: %.2f C, Avg: %.2f C\n", buffer[buffer_index], running_avg);
        pthread_mutex_unlock(&buffer_mutex);
        sleep(1);

        if (kill(getppid(), SIGINT) != 0) {
            break;
        }
    }

    cleanup_gpio();
    close(i2c_fd);
    pthread_join(thread, NULL);

    return 0;
