    double input;
    double output;
    double error;
    double last_error;
    double integral;
    double derivative;
};

struct pid_data pid_data;
struct pid_config pid_config;

void sigint_handler(int signum) {
    gpiod_unbind(pwm_chip);
    spi_close(spi);
    pigpio_terminate();
    exit(0);
}

int init_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    spi_open(fd, 500000);
    spi_mode = 1;

    return 0;
}

double read_pt100(int spi_fd) {
    uint8_t tx_buf[2] = {0x01, 0x00};
    uint8_t rx_buf[3];
    ssize_t bytes_read;

    bytes_read = spi_transfer(spi_fd, tx_buf, rx_buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_resistance = (rx_buf[0] << 8) | rx_buf[1];
    double resistance = (raw_resistance * 430.0) / (100.0 - raw_resistance);

    return resistance;
}

