    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    ret = init_spi(SPI_DEVICE);
    if (ret) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_open(&pwm_chip, GPIO_PWM);
    if (ret) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_PWM);
        return EXIT_FAILURE;
    }

    pwm_line = gpiod_chip_get_line(&pwm_chip, "pwm");
    if (!pwm_line) {
        fprintf(stderr, "Failed to get GPIO %d line\n", GPIO_PWM);
        return EXIT_FAILURE;
    }

    gpiod_chip_set_owner(pwm_chip, PWM_LINE);
    gpiod_line_export(pwm_line, NULL);
    gpiod_line_set_dir(pwm_line, GPIO_OUTPUT);

    ret = pigpio_initialise();
    if (ret) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    init_pid("config.json");

    while (1) {
        pid_data.input = read_pt100(spi_fd);

        if (pid_data.input > MAX_TEMP) {
            gpiod_line_stop(pwm_line);
            spi_close(spi_fd);
            pigpio_terminate();
            fprintf(stderr, "Temperature exceeds maximum limit\n");
            return EXIT_FAILURE;
        }

        pid_data.error = pid_data.setpoint - pid_data.input;
        pid_data.integral += pid_data.error;
        pid_data.derivative = pid_data.error - pid_data.last_error;

        pid_data.output = (pid_config.kp * pid_data.error) + (pid_config.ki * pid_data.integral) + (pid_config.kd * pid_data.derivative);

        if (pid_data.output > 100.0)
            pid_data.output = 100.0;
        else if (pid_data.output < 0.0)
            pid_data.output = 0.0;

        pigpio_set_PWM_dutycycle(get_pigpio_handle(), pwm_line->user_data, (uint32_t)pid_data.output);

        usleep(PID_PERIOD_MS * 1000);

        pid_data.last_error = pid_data.error;
    }

    gpiod_line_stop(pwm_line);
    gpiod_chip_close(&pwm_chip);
    spi_close(spi_fd);
    pigpio_terminate();

    return EXIT_SUCCESS;
}

