    ret = vsnprintf(timestamp + strlen(timestamp), 20 - strlen(timestamp), "%s ", args);
    va_end(args);

    if (ret < 0) {
        perror("vsnprintf failed");
        close(fileno(stdout));
        return -1;
    }

