    if (ret < 0) {
        perror("Failed to write newline to log file");
        close(fileno(stdout));
        return -1;
    }

    return 0;
}

int main() {
    int ret;
    int i2c_fd;
    gpiod_chip_reg_desc_t *reg;
    struct bmp180_data data;
    FILE *log_file;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    reg = gpiod_chip_get_reg_by_name(i2c_fd, "bmp180");
    if (!reg) {
        close(i2c_fd);
        perror("Failed to find BMP180 I2C register");
        return -1;
    }

    if (gpiod_chip_enable(reg) < 0) {
        close(i2c_fd);
        perror("Failed to enable BMP180 I2C chip");
        return -1;
    }

    if (bmp180_init(i2c_fd) < 0) {
        close(i2c_fd);
        perror("Failed to initialize BMP180");
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        close(i2c_fd);
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        ret = bmp180_read(i2c_fd, &data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from BMP180\n");
            break;
        }

        if (data.temp > TEMP_THRESHOLD || data.pressure < PRESS_THRESHOLD) {
            char message[256];
            snprintf(message, sizeof(message), "Temperature: %.2f °C, Pressure: %.2f hPa\n",
                     data.temp / 100.0, data.pressure / 1000.0);
            if (log_breach(message)) {
                fprintf(stderr, "Failed to log breach\n");
                break;
            }
        }
    }

    fclose(log_file);
    gpiod_chip_disable(reg);
    close(i2c_fd);

    return 0;
}

