void init_bmp180() {
    if (gpiod_chip_open(&chip, "GPIO18") < 0) {
        fprintf(stderr, "Failed to open GPIO18\n");
        exit(EXIT_FAILURE);
    }
    gpiod_trigger_setup(&chip.fan_gpio, "active-high");

    i2c_handle = i2c_open(1, 0x77);
    if (!i2c_handle) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(EXIT_FAILURE);
    }

    if (bmp180_read_calibration(i2c_handle, &bmp) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        exit(EXIT_FAILURE);
    }

    cb.head = cb.tail = 0;
}

void sample_bmp180() {
    uint8_t acq;
    int16_t temp, pres;

    if (bmp180_get_temperature(&bmp, &temp) < 0 || bmp180_get_pressure(&bmp, &pres) < 0) {
        fprintf(stderr, "Failed to read temperature or pressure\n");
        return;
    }

    if (temp > TEMP_THRESHOLD) {
        gpiod_trigger(chip.fan_gpio);
    }

    cb.data[cb.tail] = (float)(time(NULL) - (float)cb.tail * 1000.0 / BUFFER_SIZE);
    cb.data[cb.tail++] = (float)temp;
    cb.data[cb.tail++] = (float)pres;

    if (cb.tail == BUFFER_SIZE) {
        cb.tail = 0;
    }
}

void timer_callback() {
    sample_bmp180();

    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%.2f ", cb.data[(cb.head + i) % BUFFER_SIZE]);
