#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <bmp180.h>

#define BMP180_ADDR 0x77
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_TIME 200000L // 200 ms in µs
#define LOGGING_INTERVAL 2000000L // 2 seconds in µs

bool logging_enabled = false;
FILE *log_file = NULL;

void toggle_logging(int gpio, gpiod_chip *chip, gpiod_line *line, uint value) {
    logging_enabled = value == 0;
    if (value == 0) {
        if (log_file != NULL) {
            fclose(log_file);
            log_file = NULL;
        }
    }
}

void sigint_handler(int signum) {
    toggle_logging(27, NULL, NULL, 0);
}

void setup_gpio_interrupt(int gpio) {
    int ret;
    gpiod_chip *chip;
    gpiod_line *line;

    ret = gpiod_in_setup(&chip, gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to setup GPIO interrupt: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_add_listener(chip, &line,
        GPIO_EVENT_FALLING_EDGE,
        toggle_logging,
        NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to add GPIO interrupt listener: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void setup_logging() {
    int ret;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    ret = fopen(LOG_FILE, "a");
    if (ret != NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "Pressure: %ld, Timestamp: %ld.%09ld\n", 0, ts.tv_sec, ts.tv_nsec);
    }
}

int main() {
    int ret;
    bmp180_context ctx;
    bmp180_calibration cal;
    uint8_t buf[6];

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    ret = bmp180_init(&ctx, BMP180_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize BMP180 driver: %s\n", bmp180_strerror(ret));
        return EXIT_FAILURE;
    }

    ret = bmp180_read_calib(&ctx, buf);
    if (ret < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", bmp180_strerror(ret));
        bmp180_exit(&ctx);
        return EXIT_FAILURE;
    }

    bmp180_apply_comp(&ctx, &cal, buf);

    setup_gpio_interrupt(27);

    while (true) {
        if (logging_enabled) {
            setup_logging();

            while (true) {
                ret = bmp180_read(&ctx, buf);
                if (ret < 0) {
                    fprintf(stderr, "Failed to read pressure data: %s\n", bmp180_strerror(ret));
                    break;
                }

                clock_gettime(CLOCK_REALTIME, &ts);
                fprintf(log_file, "Pressure: %ld, Timestamp: %ld.%09ld\n", bmp180_pressure(&cal), ts.tv_sec, ts.tv_nsec);

                usleep(LOGGING_INTERVAL);
            }

            fclose(log_file);
            log_file = NULL;
        }

        usleep(DEBOUNCE_TIME);
    }

    bmp180_exit(&ctx);
    return EXIT_SUCCESS;
}

