#define MAX_TEMP 100.0
#define MIN_TEMP -50.0
#define SAFE_DUTY_CYCLE 0.8
#define MAX31855_REG_SCK 0x01
#define MAX31855_REG_SIO 0x02
#define MAX31855_REG_DO 0x04
#define MAX31855_REG_AGC 0x08
#define MAX31855_REG_CONFIG 0x10
#define MAX31855_REG_STATUS 0x20
#define MAX31855_REG_THERM1 0x40
#define MAX31855_REG_THERM2 0x80

#define CHIP_SEL GPIO_PIN_8
#define MISO GPIO_PIN_9
#define MOSI GPIO_PIN_10
#define SCLK GPIO_PIN_11
#define RELAY_PIN GPIO_PIN_17

struct spi_dev spi;
struct gpiod_chip chip;
FILE *log_file = NULL;

void spi_init() {
    spi.spi_fd = spi_open(&spi, "spi0.0", SPI_MODE_0, 2000000);
    if (spi.spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void gpiod_init() {
    int ret = gpiod_chip_open(&chip, "gpio");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_export(&chip, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpiod_chip_set_owner(&chip, __FILE__, __LINE__);
    gpio_init_chip(&chip);
}

void setup_relay() {
    int relay_pin = gpiod_chip_get_pin(&chip, RELAY_PIN, "relay-out");
    gpiod_chip_set_value_direction(&chip, relay_pin, GPIO_DIR_OUT);
    gpiod_chip_set_value(&chip, relay_pin, 0);
}

void pwm_init() {
    int pwm_pin = gpiod_chip_get_pin(&chip, RELAY_PIN, "pwm");
    gpiod_chip_set_value_direction(&chip, pwm_pin, GPIO_DIR_OUT);
    gpiod_chip_set_value(&chip, pwm_pin, 0);
}

void spi_read(uint8_t *data, int len) {
    int ret = spi_transfer(&spi, data, data, len);
    if (ret < 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        gpiod_chip_set_value(&chip, RELAY_PIN, 0);
        return;
    }
}

