    if (log_file == NULL)
        return;

    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fflush(log_file);
}

void sigint_handler(int signum) {
    log_message("Received SIGINT, shutting down...\n");
    gpiod_chip_set_value(&chip, RELAY_PIN, 0);
    spi_close(&spi);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    log_message("Received SIGTERM, shutting down...\n");
    gpiod_chip_set_value(&chip, RELAY_PIN, 0);
    spi_close(&spi);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    spi_init();
    gpiod_init();
    setup_relay();
    pwm_init();

    if (!(log_file = fopen("heater_log.csv", "w"))) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data[3];
        spi_read(data, 3);

        if ((data[0] & 0x80) == 0x80) {
            log_message("MAX31855 fault condition detected, turning off heater...\n");
            gpiod_chip_set_value(&chip, RELAY_PIN, 0);
            continue;
        }

        float temp = (float)((data[1] << 8) | data[2]);
        temp = (temp - 500) / 10.0;

        double error = 25.0 - temp;
        double integral = 0.0;
        double previous_error = 0.0;

        if (abs(error) < 0.1) {
            integral += error;
            if (integral > 10.0)
                integral = 10.0;
            else if (integral < -10.0)
                integral = -10.0;
        } else {
            integral = 0.0;
        }

        double new_duty_cycle = Kp * error + Ki * integral;

        if (new_duty_cycle > SAFE_DUTY_CYCLE)
            new_duty_cycle = SAFE_DUTY_CYCLE;
        else if (new_duty_cycle < 0.0)
            new_duty_cycle = 0.0;

        gpiod_chip_set_value(&chip, RELAY_PIN, (int)(new_duty_cycle * 100));

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f,%.2f%%\n", timestamp, temp, new_duty_cycle);
    }

    return EXIT_SUCCESS;
}

