#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <curl/curl.h>
#include <gpiod.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define CHECKSUM_MASK 0x0F

struct sensor_data {
    float humidity;
    float temperature;
};

static int retries = 0;
static struct sensor_data data;

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct sensor_data *json = (struct sensor_data *)userp;

    char *buffer = realloc(json->buffer, json->len + realsize + 1);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    json->buffer = buffer;
    strncat(json->buffer, ptr, realsize);
    json->len += realsize;

    return realsize;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Signal %d received, cleaning up and exiting\n", signum);
        gpiod_unprepare(chip);
        curl_easy_cleanup(curl);
        exit(0);
    }
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    struct gpiod_trigger trigger;
    struct gpiod_buffer buf;
    char *json_payload = NULL;
    size_t json_payload_len = 0;
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data);

        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);
    }

    gpiod_chip_open(&chip, "gpiochip0");
    gpiod_chip_get_line(&chip, DHT22_GPIO, &line);
    gpiod_line_export(&line, NULL);
    gpiod_line_request(&line, GPIO_PUD_UP);

    gpiod_trigger_setup(&trigger, &line, NULL, GPIO_FALLING_EDGE);
    gpiod_trigger_add(&trigger);

    gpiod_buffer_init(&buf, 40);
    gpiod_line_read(&line, &buf);

    if (buf.value == 0) {
        fprintf(stderr, "DHT22 sensor not detected\n");
        gpiod_unprepare(&line);
        gpiod_chip_close(&chip);
        if (curl) {
            curl_easy_cleanup(curl);
        }
        return 1;
    }

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        data.humidity = (float)(buf.value >> 24) / 10.0;
        data.temperature = (float)(buf.value >> 16) / 10.0;

        uint8_t checksum = buf.value & CHECKSUM_MASK;
        uint8_t calculated_checksum = 0;
        for (int i = 0; i < 32; i++) {
            calculated_checksum += (buf.value >> (i * 8)) & 0x01;
        }

        if (checksum != calculated_checksum) {
            fprintf(stderr, "Checksum mismatch, retrying...\n");
            continue;
        }

        json_payload = malloc(json_payload_len + 64);
        sprintf(json_payload, "{\"humidity\": %f, \"temperature\": %f}", data.humidity, data.temperature);
        json_payload_len = strlen(json_payload);

        curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
        curl_easy_perform(curl);

        if (curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE) == 200) {
            break;
        } else {
            fprintf(stderr, "Network error, retrying...\n");
            free(json_payload);
        }
    }

    gpiod_unprepare(&line);
    gpiod_chip_close(&chip);
    free(json_payload);
    curl_easy_cleanup(curl);

    return 0;
}

