#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>

#define BMP180_ADDR 0x77
#define LOG_FILE "pressure_log.txt"
#define OSS 3
#define CONV_DELAY_MS 26
#define DEBOUNE_TIME_US 200000

typedef struct {
    gpiod_chip *chip;
    gpiod_line *button;
} Button;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    int pa1, pa2;
} BMP180_Calibration;

Button button;
BMP180_Calibration bmp_cal;
FILE *log_file;
bool logging_enabled = false;

void button_callback(const struct gpiod_line *line, uint32_t flags) {
    if (flags & GPIO_EVENT_FALLING_EDGE) {
        button.last_tick = gpiod_get_timestamp(line);
        if (gpiod_get_timestamp(line) - button.last_tick > DEBOUNE_TIME_US * 1000) {
            logging_enabled = !logging_enabled;
            if (logging_enabled) {
                log_file = fopen(LOG_FILE, "a");
                if (!log_file) {
                    fprintf(stderr, "Error: Unable to open log file.\n");
                    exit(EXIT_FAILURE);
                }
            } else {
                fclose(log_file);
                log_file = NULL;
            }
        }
    }
}

void sigint_handler(int signum) {
    gpiod_unbind(button.chip);
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

void configure_i2c() {
    int fd = gpiod_open();
    if (fd < 0) {
        perror("Failed to open gpiod");
        exit(EXIT_FAILURE);
    }

    button.chip = gpiod_chip_open(fd, "GPIO4");
    if (!button.chip) {
        perror("Failed to open GPIO4");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    button.button = gpiod_chip_get_line(button.chip, "GPIO4_7");
    if (!button.button) {
        perror("Failed to get GPIO4_7 line");
        gpiod_chip_close(button.chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_add_callback(button.button, GPIO_EVENT_FALLING_EDGE, button_callback);

    if (gpiod_export(button.chip) < 0) {
        perror("Failed to export GPIO4");
        gpiod_chip_close(button.chip);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
}

void configure_bmp180(int i2c_fd) {
    if (i2c_write(i2c_fd, BMP180_ADDR << 1, &OSS, 1) != 1) {
        fprintf(stderr, "Failed to set oversampling to %d\n", OSS);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1, &bmp_cal.ac1, 2) != 2) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x06, &bmp_cal.ac2, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x07, &bmp_cal.ac3, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x09, &bmp_cal.b1, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0A, &bmp_cal.b2, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0B, &bmp_cal.mb, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0C, &bmp_cal.mc, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0D, &bmp_cal.md, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x1E, &bmp_cal.pa1, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x1F, &bmp_cal.pa2, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    close(i2c_fd);
}

int main() {
    configure_i2c();
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus 1");
        gpiod_close(button.chip);
        exit(EXIT_FAILURE);
    }

    configure_bmp180(i2c_fd);
    close(i2c_fd);

    while (true) {
        if (logging_enabled) {
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus 1");
                gpiod_unbind(button.chip);
                gpiod_close(button.chip);
                exit(EXIT_FAILURE);
            }

            int16_t x, y;
            if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0xF7, &x, 2) != 2) {
                fprintf(stderr, "Failed to read pressure data\n");
                close(i2c_fd);
                continue;
            }

            double pressure = (x * bmp_cal.pa2) / (x - bmp_cal.pa1);
            time_t now = time(NULL);
            fprintf(log_file, "%ld: %.2f hPa\n", now, pressure);
            fclose(log_file);
            fflush(log_file);

            close(i2c_fd);
            sleep(2);
        } else {
            printf("Data logging is disabled.\n");
            sleep(2);
        }
    }

    return 0;
}

