    if (i2c_write(i2c_fd, BMP180_ADDR << 1, &OSS, 1) != 1) {
        fprintf(stderr, "Failed to set oversampling to %d\n", OSS);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1, &bmp_cal.ac1, 2) != 2) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x06, &bmp_cal.ac2, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x07, &bmp_cal.ac3, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x09, &bmp_cal.b1, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0A, &bmp_cal.b2, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0B, &bmp_cal.mb, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0C, &bmp_cal.mc, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x0D, &bmp_cal.md, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x1E, &bmp_cal.pa1, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0x1F, &bmp_cal.pa2, 1) != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    close(i2c_fd);
}

int main() {
    configure_i2c();
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus 1");
        gpiod_close(button.chip);
        exit(EXIT_FAILURE);
    }

    configure_bmp180(i2c_fd);
    close(i2c_fd);

    while (true) {
        if (logging_enabled) {
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus 1");
                gpiod_unbind(button.chip);
                gpiod_close(button.chip);
                exit(EXIT_FAILURE);
            }

            int16_t x, y;
            if (i2c_read(i2c_fd, BMP180_ADDR << 1 | 0xF7, &x, 2) != 2) {
                fprintf(stderr, "Failed to read pressure data\n");
                close(i2c_fd);
                continue;
            }

            double pressure = (x * bmp_cal.pa2) / (x - bmp_cal.pa1);
            time_t now = time(NULL);
            fprintf(log_file, "%ld: %.2f hPa\n", now, pressure);
            fclose(log_file);
            fflush(log_file);

            close(i2c_fd);
            sleep(2);
        } else {
            printf("Data logging is disabled.\n");
            sleep(2);
        }
    }

    return 0;
}
