#include <fcntl.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/inotify.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 5
#define POLL_INTERVAL 5

enum {
    STATE_OFF = 0,
    STATE_LOW = 1,
    STATE_MEDIUM = 2,
    STATE_HIGH = 3
};

int get_cpu_temp() {
    int fd, ret;
    char temp_str[32];

    fd = open(TEMP_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Error opening temperature file");
        return -1;
    }

    ret = read(fd, temp_str, sizeof(temp_str));
    close(fd);

    if (ret < 0) {
        if (errno == EINTR) {
            // Retry on EINTR (interrupt)
            return get_cpu_temp();
        }
        perror("Error reading temperature");
        return -1;
    }

    return atoi(temp_str);
}

int get_current_state() {
    int fd, state;
    char state_str[32];

    fd = open(STATE_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Error opening state file");
        return -1;
    }

    ret = read(fd, state_str, sizeof(state_str));
    close(fd);

    if (ret < 0) {
        if (errno == EINTR) {
            // Retry on EINTR (interrupt)
            return get_current_state();
        }
        perror("Error reading current state");
        return -1;
    }

    state = atoi(state_str);
    return state;
}

int set_fan_state(int new_state) {
    int fd, ret;
    char new_state_str[32];

    if (new_state < 0 || new_state > 3) {
        fprintf(stderr, "Invalid fan state: %d\n", new_state);
        return -1;
    }

    snprintf(new_state_str, sizeof(new_state_str), "%d", new_state);

    fd = open(STATE_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Error opening state file for writing");
        return -1;
    }

    ret = write(fd, new_state_str, strlen(new_state_str) + 1);
    close(fd);

    if (ret < 0) {
        perror("Error writing new fan state");
        return -1;
    }

    return 0;
}

void log_event(const char *event) {
    time_t now;
    struct tm *time_struct;
    char timestamp[32];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fclose(log_file);
    } else {
        perror("Error opening log file");
    }
}

int main() {
    int temp, current_state, new_state, max_state;
    int fd, retries = 0;

    while (1) {
        temp = get_cpu_temp();
        if (temp < 0) {
            break;
        }

        current_state = get_current_state();
        if (current_state < 0) {
            break;
        }

        fd = open("/sys/class/thermal/cooling_device0/max_state", O_RDONLY);
        if (fd < 0) {
            perror("Error opening max_state file");
            break;
        }

        if (read(fd, &max_state, sizeof(max_state)) != sizeof(max_state)) {
            perror("Error reading max_state");
            close(fd);
            break;
        }

        close(fd);

        if (temp < 45) {
            new_state = STATE_OFF;
        } else if (temp < 55) {
            new_state = STATE_LOW;
        } else if (temp < 65) {
            new_state = STATE_MEDIUM;
        } else {
            new_state = STATE_HIGH;
        }

        if (new_state != current_state) {
            if (set_fan_state(new_state) < 0) {
                log_event("Failed to set fan state");
            } else {
                log_event("Changed fan state to");
                log_event(new_state == STATE_OFF ? "OFF" :
                         new_state == STATE_LOW ? "LOW" :
                         new_state == STATE_MEDIUM ? "MEDIUM" : "HIGH");
            }
        }

        usleep(POLL_INTERVAL * 1000000);
        retries++;
        if (retries > MAX_RETRIES) {
            break;
        }
    }

    // Handle graceful shutdown
    set_fan_state(STATE_OFF);
    log_event("Shutdown initiated");

    return 0;
}

