#define TARGET_TEMP 50
#define FAULT_THRESHOLD 100
#define MIN_TEMP 0

#define SPI_DEVICE 0
#define SPI_CLK GPIO_11
#define SPI_CS GPIO_8
#define SPI_DO GPIO_9

struct pid_data {
    float kp;
    float ki;
    float kd;
    float prev_error;
    float sample_time;
    float state;
    float set_point;
};

struct pid_data pid = {1.0, 0.1, 0.01, 0.0, 1.0, TARGET_TEMP, TARGET_TEMP};

FILE *log_file;

void sigint_handler(int signum) {
    gpiod_unbind(pwm_chip);
    spi_close(spi);
    fclose(log_file);
    exit(0);
}

int main() {
    log_file = fopen("heater_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    spi_fd_t spi;
    if (spi_open(&spi, SPI_DEVICE) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (spi_set_mode(spi, 0) < 0) {
        perror("Failed to set SPI mode");
        spi_close(spi);
        return EXIT_FAILURE;
    }

    if (spi_set_bits_per_word(spi, 8) < 0) {
        perror("Failed to set SPI bits per word");
        spi_close(spi);
        return EXIT_FAILURE;
    }

    if (spi_set_speed(spi, 500000) < 0) {
        perror("Failed to set SPI speed");
        spi_close(spi);
        return EXIT_FAILURE;
    }

    if (spi_chip_select(spi, SPI_CS) < 0) {
        perror("Failed to select SPI chip");
        spi_close(spi);
        return EXIT_FAILURE;
    }

    gpiod_chip_handle pwm_chip;
    if (gpiod_chip_get_from_number(SPI_CLK, &pwm_chip) < 0) {
        perror("Failed to get PWM chip");
        spi_close(spi);
        return EXIT_FAILURE;
    }

    gpiod_chip_add_listener(pwm_chip, NULL);
    gpiod_chip_enable(pwm_chip, true);

    pwm_params_t pwm_params = {
        .base.dev.id = pwm_chip.id,
        .base.dev.direction = GPIO_OUTPUT,
        .base.dev.flags = 0,
        .base.dev.pin = SPI_CLK,
        .freq = PWM_FREQ,
        .range = PWM_RANGE,
    };

    if (gpiod_chip_set_params(pwm_chip.id, &pwm_params) < 0) {
        perror("Failed to set PWM parameters");
        spi_close(spi);
        gpiod_chip_remove_listener(pwm_chip);
        gpiod_chip_disable(pwm_chip.id, true);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (true) {
        uint8_t data[4];
        if (spi_transfer(spi, data, 4) != 4) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        float temp = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
        temp /= 10.0;

        if (temp > FAULT_THRESHOLD || temp < MIN_TEMP) {
            fprintf(log_file, "Temperature fault: %f\n", temp);
            gpiod_unbind(pwm_chip);
            spi_close(spi);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        pid.state = temp;
        pid.sample_time = 1.0;
        pid.prev_error = pid.error;
        pid.error = pid.set_point - pid.state;
        pid.integral += pid.error * pid.sample_time;
        pid.derivative = pid.error - pid.prev_error;
        pid.output = pid.kp * pid.error + pid.ki * pid.integral + pid.kd * pid.derivative;

        int duty = (int)(pid.output + 0.5);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        gpiod_trigger_delay(pwm_chip.id, duty);

        fprintf(log_file, "%f %d %f\n", temp, duty, pid.output);

        sleep(1);
    }

    gpiod_unbind(pwm_chip);
    spi_close(spi);
    fclose(log_file);
    return EXIT_SUCCESS;
}
