    gpio_context *i2c_sd;
    gpio_context *i2c_da;
    gpio_context *i2c_clk;
    int retries;
} sensor_t;

static int read_i2c_byte(sensor_t *sensor, uint8_t ack) {
    int ret;
    uint8_t data;

    for (sensor->retries = 0; sensor->retries < MAX_RETRIES; sensor->retries++) {
        ret = gpiod_transfer(sensor->i2c_sd, &data, 1, ack);
        if (ret == 1) {
            return data;
        }
        if (ret < 0) {
            fprintf(stderr, "I2C error, retrying...\n");
        }
    }
    fprintf(stderr, "I2C error after %d retries, giving up.\n", MAX_RETRIES);
    return 0;
}

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    uint8_t i;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 4; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x07;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

static int validate_crc(uint8_t *data, size_t len) {
    return crc8(data, len) == data[len - 1];
}

static void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up and exiting...\n");
    exit(0);
}

