        gpio_unexport(GPIOD, sensor2.i2c_clk);
        return 1;
    }

    // Read and log data
    while (1) {
        time_t now_time = time(NULL);
        struct tm *local_time = localtime(&now_time);

        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d",
                1900 + local_time->tm_year,
                1 + local_time->tm_mon,
                local_time->tm_mday,
                local_time->tm_hour,
                local_time->tm_min,
                local_time->tm_sec);

        uint8_t data1[3], data2[3];

        // Read from sensor 1
        data1[0] = read_i2c_byte(&sensor1, 1);
        data1[1] = read_i2c_byte(&sensor1, 0);
        data1[2] = read_i2c_byte(&sensor1, 1);

        if (validate_crc(data1, 3)) {
            fprintf(fp, ",%llu", (long long unsigned) (data1[0] << 16 | data1[1] << 8 | data1[2]));
        }

        // Read from sensor 2
        data2[0] = read_i2c_byte(&sensor2, 1);
        data2[1] = read_i2c_byte(&sensor2, 0);
        data2[2] = read_i2c_byte(&sensor2, 1);

        if (validate_crc(data2, 3)) {
            fprintf(fp, ",%llu\n", (long long unsigned) (data2[0] << 16 | data2[1] << 8 | data2[2]));
        }

        fflush(fp);
        sleep(1);
    }

    // Clean up
    fclose(fp);
    gpio_unexport(GPIOD, sensor1.i2c_sd);
    gpio_unexport(GPIOD, sensor1.i2c_da);
    gpio_unexport(GPIOD, sensor1.i2c_clk);
    gpio_unexport(GPIOD, sensor2.i2c_sd);
    gpio_unexport(GPIOD, sensor2.i2c_da);
    gpio_unexport(GPIOD, sensor2.i2c_clk);
    gpio_exit();

    return 0;
