#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define CHANNEL_A 17
#define CHANNEL_B 18
#define ENCODER_LOG "encoder_log.txt"

enum encoder_state {
    STATE_IDLE,
    STATE_A_HIGH,
    STATE_B_HIGH,
    STATE_A_LOW,
    STATE_B_LOW
};

enum {
    MAX_LOG_ENTRIES = 100
};

struct encoder_data {
    int fd;
    gpiod_chip *chip;
    gpiod_line *line_a;
    gpiod_line *line_b;
    enum encoder_state state;
    int position;
    time_t last_update;
    FILE *log_file;
};

static struct encoder_data encoder_data;

static void encoder_callback(const struct gpiod_line *line, uint32_t events) {
    struct encoder_data *data = (struct encoder_data *)gpiod_line_get_user_data(line);

    if (events & (1 << gpiod_line_get_direction(line))) {
        // Handle rising edge
        switch (data->state) {
            case STATE_IDLE:
                data->state = STATE_A_HIGH;
                break;
            case STATE_A_HIGH:
                data->state = STATE_A_LOW;
                break;
            case STATE_B_HIGH:
                data->state = STATE_IDLE;
                break;
            case STATE_A_LOW:
                data->state = STATE_B_HIGH;
                break;
            case STATE_B_LOW:
                data->state = STATE_IDLE;
                break;
        }
    } else {
        // Handle falling edge
        switch (data->state) {
            case STATE_IDLE:
                break;
            case STATE_A_HIGH:
                data->state = STATE_A_LOW;
                break;
            case STATE_B_HIGH:
                data->state = STATE_IDLE;
                break;
            case STATE_A_LOW:
                data->state = STATE_B_HIGH;
                break;
            case STATE_B_LOW:
                data->state = STATE_IDLE;
                break;
        }
    }

    update_position(data);
}

static void update_position(struct encoder_data *data) {
    time_t current_time = time(NULL);

    if (data->last_update + 1 != current_time) {
        fprintf(data->log_file, "ERROR: Time skew detected.\n");
        return;
    }

    // Implement your 2-bit quadrature state machine here
    // ...

    data->last_update = current_time;
}

static int init_encoder(struct encoder_data *data) {
    int ret;

    data->fd = gpiod_chip_open(NULL);
    if (data->fd < 0) {
        fprintf(stderr, "ERROR: Failed to open GPIO chip\n");
        return data->fd;
    }

    data->chip = gpiod_chip_get(data->fd, "GPIO17");
    if (!data->chip) {
        gpiod_chip_close(data->fd);
        return -ENOMEM;
    }

    data->line_a = gpiod_chip_get_line(data->chip, CHANNEL_A);
    if (!data->line_a) {
        gpiod_chip_put(data->chip);
        gpiod_chip_close(data->fd);
        return -ENOMEM;
    }

    data->line_b = gpiod_chip_get_line(data->chip, CHANNEL_B);
    if (!data->line_b) {
        gpiod_chip_put(data->line_a);
        gpiod_chip_close(data->fd);
        return -ENOMEM;
    }

    gpiod_line_export(data->line_a, "Encoder A");
    gpiod_line_export(data->line_b, "Encoder B");

    gpiod_line_set_direction(data->line_a, GPIO_OUT);
    gpiod_line_set_pull(data->line_a, GPIO_PULL_UP);

    gpiod_line_set_direction(data->line_b, GPIO_OUT);
    gpiod_line_set_pull(data->line_b, GPIO_PULL_UP);

    gpiod_line_set_active_high(data->line_a);
    gpiod_line_set_active_high(data->line_b);

    gpiod_line_set_callback(data->line_a, &encoder_callback, data);
    gpiod_line_set_callback(data->line_b, &encoder_callback, data);

    data->state = STATE_IDLE;
    data->position = 0.0;
    data->last_update = time(NULL);

    data->log_file = fopen(ENCODER_LOG, "a");
    if (!data->log_file) {
        fprintf(stderr, "ERROR: Failed to open log file %s\n", ENCODER_LOG);
        return -errno;
    }

    return 0;
}

static void cleanup_encoder(struct encoder_data *data) {
    fclose(data->log_file);
    gpiod_line_unset_callback(data->line_a, &encoder_callback);
    gpiod_line_unset_callback(data->line_b, &encoder_callback);
    gpiod_line_free(data->line_b);
    gpiod_line_free(data->line_a);
    gpiod_chip_put(data->chip);
    gpiod_chip_close(data->fd);
}

static void signal_handler(int signum) {
    (void)signum;
    cleanup_encoder(&encoder_data);
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_encoder(&encoder_data) < 0) {
        fprintf(stderr, "Failed to initialize encoder. Exiting.\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Your main loop logic here
    }

    cleanup_encoder(&encoder_data);
    return 0;
}

