    // ...

    data->last_update = current_time;
}

static int init_encoder(struct encoder_data *data) {
    int ret;

    data->fd = gpiod_chip_open(NULL);
    if (data->fd < 0) {
        fprintf(stderr, "ERROR: Failed to open GPIO chip\n");
        return data->fd;
    }

    data->chip = gpiod_chip_get(data->fd, "GPIO17");
    if (!data->chip) {
        gpiod_chip_close(data->fd);
        return -ENOMEM;
    }

    data->line_a = gpiod_chip_get_line(data->chip, CHANNEL_A);
    if (!data->line_a) {
        gpiod_chip_put(data->chip);
        gpiod_chip_close(data->fd);
        return -ENOMEM;
    }

    data->line_b = gpiod_chip_get_line(data->chip, CHANNEL_B);
    if (!data->line_b) {
        gpiod_chip_put(data->line_a);
        gpiod_chip_close(data->fd);
        return -ENOMEM;
    }

    gpiod_line_export(data->line_a, "Encoder A");
    gpiod_line_export(data->line_b, "Encoder B");

    gpiod_line_set_direction(data->line_a, GPIO_OUT);
    gpiod_line_set_pull(data->line_a, GPIO_PULL_UP);

    gpiod_line_set_direction(data->line_b, GPIO_OUT);
    gpiod_line_set_pull(data->line_b, GPIO_PULL_UP);

    gpiod_line_set_active_high(data->line_a);
    gpiod_line_set_active_high(data->line_b);

    gpiod_line_set_callback(data->line_a, &encoder_callback, data);
    gpiod_line_set_callback(data->line_b, &encoder_callback, data);

    data->state = STATE_IDLE;
    data->position = 0.0;
    data->last_update = time(NULL);

    data->log_file = fopen(ENCODER_LOG, "a");
    if (!data->log_file) {
        fprintf(stderr, "ERROR: Failed to open log file %s\n", ENCODER_LOG);
        return -errno;
    }

    return 0;
}

static void cleanup_encoder(struct encoder_data *data) {
    fclose(data->log_file);
    gpiod_line_unset_callback(data->line_a, &encoder_callback);
    gpiod_line_unset_callback(data->line_b, &encoder_callback);
    gpiod_line_free(data->line_b);
    gpiod_line_free(data->line_a);
    gpiod_chip_put(data->chip);
    gpiod_chip_close(data->fd);
}

static void signal_handler(int signum) {
    (void)signum;
    cleanup_encoder(&encoder_data);
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_encoder(&encoder_data) < 0) {
        fprintf(stderr, "Failed to initialize encoder. Exiting.\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Your main loop logic here
    }

    cleanup_encoder(&encoder_data);
    return 0;
}
