static int sensor_read(int fd, struct sensor_data *data) {
    uint8_t buffer[2];
    int ret;

    buffer[0] = 0x00; // Register address for red value
    ret = ioctl(fd, I2C_RDWR, buffer);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    ret = read(fd, buffer + 1, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    data->red = (buffer[1] << 8) | buffer[0];
    buffer[0] = 0x01; // Register address for ir value
    ret = ioctl(fd, I2C_RDWR, buffer);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    ret = read(fd, buffer + 1, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    data->ir = (buffer[1] << 8) | buffer[0];
    return 0;
}

