        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(&gpiod_chip_default, "GPIO");
    line = gpiod_chip_get_line(chip, gpio);
    gpiod_line_free(line);
    gpiod_chip_put(chip);
}

