    int fd;
    struct sensor_data data;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    int ret;

    chip = gpiod_chip_open(&gpiod_chip_default, "GPIO");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_put(chip);
        return -1;
    }

    ret = setup_gpio(GPIO_LED);
    if (ret < 0) {
        fprintf(stderr, "Failed to setup GPIO\n");
        gpiod_chip_put(chip);
        return -1;
    }

    fd = i2c_open(1);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        cleanup_gpio(GPIO_LED);
        gpiod_chip_put(chip);
        return -1;
    }

    ret = setup_i2c(1);
    if (ret < 0) {
        fprintf(stderr, "Failed to setup I2C bus 1\n");
        i2c_close(fd);
        cleanup_gpio(GPIO_LED);
        gpiod_chip_put(chip);
        return -1;
    }

    while (1) {
        if (sensor_read(fd, &data) < 0) {
            break;
        }

        log_data(&data);

        if (data.ir > IR_THRESHOLD) {
            gpiod_trigger(led_line, 1);
        } else {
            gpiod_trigger(led_line, 0);
        }

        usleep(100000); // 100 ms
    }

    cleanup_gpio(GPIO_LED);
    cleanup_i2c(1);
    i2c_close(fd);
    gpiod_chip_put(chip);

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

