#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <gpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define COUNT_INTERVAL (1 * 1000) // 1 second

static pthread_mutex_t pulse_counter_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile unsigned long pulse_count = 0;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    (void)signum;
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpio_stop();
    pthread_mutex_destroy(&pulse_counter_mutex);
    exit(0);
}

static void init_logging() {
    if (log_file != NULL) {
        return;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);

    fprintf(log_file, "%02d:%02d:%02d ", tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(log_file);
}

static void log_rpm(double rpm) {
    init_logging();
    fprintf(log_file, "%.2f RPM\n", rpm);
    fflush(log_file);
}

static void gpio_setup() {
    int ret = gpio_init();
    if (ret < 0) {
        perror("Failed to initialize GPIO library");
        exit(EXIT_FAILURE);
    }

    ret = gpio_request_line(GPIO_PIN, GPIO_DIR_IN, GPIO_PUD_DOWN);
    if (ret < 0) {
        perror("Failed to configure GPIO pin");
        gpio_exit();
        exit(EXIT_FAILURE);
    }
}

static void gpio_cleanup() {
    gpio_free();
}

static void* pulse_counter_thread(void *arg) {
    while (true) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double elapsed_seconds = (ts.tv_sec - start_time.tv_sec) + (ts.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_seconds >= COUNT_INTERVAL) {
            double rpm = (pulse_count * 60.0) / elapsed_seconds;
            log_rpm(rpm);
            pulse_count = 0;
            ts.tv_sec -= COUNT_INTERVAL;
            if (ts.tv_nsec < 0) {
                ts.tv_sec--;
                ts.tv_nsec += 1e9;
            }
            nanosleep(&ts, NULL);
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_setup();
    pthread_t pulse_counter_tid;
    pthread_mutex_init(&pulse_counter_mutex, NULL);

    if (gpio_enable_irq(GPIO_PIN, GPIO_RISING_EDGE, pulse_counter_isr) < 0) {
        perror("Failed to register ISR");
        gpio_disable_irq(GPIO_PIN);
        gpio_cleanup();
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&pulse_counter_tid, NULL, pulse_counter_thread, NULL) != 0) {
        perror("Failed to create pulse counter thread");
        gpio_disable_irq(GPIO_PIN);
        gpio_cleanup();
        exit(EXIT_FAILURE_NUM);
    }

    pthread_join(pulse_counter_tid, NULL);

    gpio_disable_irq(GPIO_PIN);
    gpio_cleanup();
    pthread_mutex_destroy(&pulse_counter_mutex);

    return 0;
}

static void pulse_counter_isr(uint pulse_num) {
    pthread_mutex_lock(&pulse_counter_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_counter_mutex);
}

