#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADPD144RI_ADDR 0x29
#define IR_THRESHOLD 2000
#define LED_GPIO 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "adpd144ri_log.txt"

struct sensor_data {
    time_t timestamp;
    uint16_t red;
    uint16_t ir;
};

FILE *log_file = NULL;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_unbind(led_chip, led_gpio);
    gpiod_unbind_subsystem(&led_chip);
    gpiod_device_release(led_chip);
    close(i2c_fd);
    munmap(i2c_addr, 4);
    i2c_fd = -1;
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
