#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define AUDIO_GPIO 17
#define GAIN_GPIO 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL (10 * 1000) // 10 ms

struct gpiod_chip *chip;
struct gpiod_line *audio_line;
struct gpiod_line *gain_line;
FILE *log_file = NULL;

void log_event(const char *level) {
    if (log_file == NULL) {
        return;
    }

    time_t now;
    struct tm *time_info;
    char timestamp[20];

    time(&now);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s %s\n", timestamp, level);
    fflush(log_file);
}

void setup_gpio(int audio_gpio, int gain_gpio) {
    int ret;

    ret = gpiod_in_setup(&chip, audio_gpio, GPIO_FLAG_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to setup audio GPIO: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    audio_line = gpiod_line_get(chip, audio_gpio);
    ret = gpiod_line_export(audio_line, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export audio GPIO: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_in_setup(&chip, gain_gpio, GPIO_FLAG_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to setup gain GPIO: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    gain_line = gpiod_line_get(chip, gain_gpio);
    ret = gpiod_line_export(gain_line, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export gain GPIO: %s\n", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(gain_line, 0); // Set gain GPIO LOW
}

void cleanup_gpio() {
    if (gain_line) {
        gpiod_line_unset(gain_line);
    }

    if (audio_line) {
        gpiod_line_unset(audio_line);
    }

    gpiod_chip_unref(chip);
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, cleaning up and exiting...\n");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    int ret;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiod chip: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    setup_gpio(AUDIO_GPIO, GAIN_GPIO);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    fprintf(stdout, "Audio peak detector started.\n");

    while (1) {
        uint32_t audio_value = gpiod_line_get_value(audio_line);
        uint32_t last_audio_value = gpiod_line_get_value(audio_line);

        if (audio_value != last_audio_value && audio_value == 1) {
            log_event("1");
        }

        usleep(POLL_INTERVAL);
    }

    cleanup_gpio();
    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

