#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define SENSOR_ADDR 0x48
#define CRC_POLYNOMIAL 0x05
#define CRC_INIT_VALUE 0xFF

static FILE *log_file = NULL;

void signal_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct gpio_dev *i2c_dev;
    int ret;

    signal(SIGINT, signal_handler);

    i2c_dev = gpioSetup(0, GPIOD_IN, GPIOF_OUT);
    if (!i2c_dev) {
        fprintf(stderr, "Failed to initialize I2C driver\n");
        return 1;
    }

    if (gpioSetMode(i2c_dev, GPIOD_SCL, GP_MODE_OUTPUT) ||
        gpioSetMode(i2c_dev, GPIOD_SDA, GP_MODE_OUTPUT) ||
        gpioSetMode(i2c_dev, GPIOF_CS, GP_MODE_OUTPUT) ||
        gpioWrite(i2c_dev, GPIOF_CS, 0) ||
        gpioWrite(i2c_dev, GPIOD_SCL, 0) ||
        gpioWrite(i2c_dev, GPIOD_SDA, 0)) {
        fprintf(stderr, "Failed to configure I2C pins\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        time_t now_time = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now_time));

        uint16_t msb, lsb;
        uint8_t crc;

        if (gpioWrite(i2c_dev, GPIOF_CS, 0) &&
            gpioI2CWrite(i2c_dev, SENSOR_ADDR, &msb, 2) &&
            gpioI2CWrite(i2c_dev, SENSOR_ADDR, &lsb, 1) &&
            gpioI2CRead(i2c_dev, SENSOR_ADDR, &crc, 1)) {
            fprintf(stderr, "I2C read/write error\n");
            continue;
        }

        if (crc != calculateCRC(msb, lsb)) {
            fprintf(stderr, "CRC error, skipping reading\n");
            continue;
        }

        double flow_rate_ul_min = (msb << 8 | lsb) * 0.0024; // Conversion factor from datasheet
        fprintf(log_file, "%s,%.6f\n", timestamp, flow_rate_ul_min);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

uint8_t calculateCRC(uint16_t msb, uint8_t lsb) {
    uint8_t crc = CRC_INIT_VALUE;
    for (int i = 0; i < 2; i++) {
        crc ^= (msb >> (i * 8));
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

