    log_file = fopen("air_quality_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        struct sensor_data data;
        int rd_tvoc = i2c_read(I2C_BUS, SENSOR_ADDR, &data.tvoc, sizeof(data.tvoc));
        int rd_eco2 = i2c_read(I2C_BUS, SENSOR_ADDR, &data.eco2, sizeof(data.eco2));
        int rd_iaq = i2c_read(I2C_BUS, SENSOR_ADDR, &data.iaq, sizeof(data.iaq));

        if (rd_tvoc < 0 || rd_eco2 < 0 || rd_iaq < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", now, data.tvoc, data.eco2, data.iaq);
        fflush(log_file);

        sleep(5);
    }

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

int i2c_read(int bus, int addr, void *buf, size_t len) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[len];

    tx_buf[0] = addr | (bus >> 2);
    tx_buf[1] = 0x00;
    tx_buf[2] = len | (bus & 0x03);

    int ret = gpioI2CWrite(bus, tx_buf, sizeof(tx_buf));
    if (ret < 0) {
        return ret;
    }

    ret = gpioI2CRead(bus, rx_buf, len);
    if (ret < 0) {
        return ret;
    }

    memcpy(buf, rx_buf, len);
    return 0;
}
