#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_GPIO 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_S 5

struct chip_data {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    clock_t start_time;
    int touched;
};

static int chip_open(struct chip_data *data) {
    data->fd = gpiod_chip_open(TOUCH_GPIO);
    if (data->fd < 0) {
        perror("Failed to open GPIO chip");
        return data->fd;
    }

    data->chip = gpiod_chip_get(data->fd);
    if (!data->chip) {
        perror("Failed to get GPIO chip");
        return data->fd;
    }

    data->line = gpiod_chip_get_line(data->chip, "ttp223_tamper");
    if (!data->line) {
        perror("Failed to get line");
        gpiod_chip_close(data->fd);
        return data->fd;
    }

    if (gpiod_line_request_output(data->line, 1000) < 0) {
        perror("Failed to request output");
        gpiod_line_release(data->line);
        gpiod_chip_close(data->fd);
        return data->fd;
    }

    data->touched = 0;
    return 0;
}

static void chip_close(struct chip_data *data) {
    gpiod_line_release(data->line);
    gpiod_chip_close(data->fd);
}

static int chip_poll(struct chip_data *data) {
    clock_t current_time;
    int ret;

    current_time = clock();
    if (current_time - data->start_time > INTRUSION_THRESHOLD_S * CLOCKS_PER_SEC) {
        if (data->touched) {
            printf("Intrusion alert!\n");
            data->touched = 0;
        }
    }

    ret = gpiod_line_read(data->line);
    if (ret < 0) {
        perror("Failed to read line");
        return ret;
    }

    data->touched = ret;
    data->start_time = current_time;
    return 0;
}

static void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    chip_close(&chip_data);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct chip_data chip_data;
    int ret;

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return EXIT_FAILURE;
    }

    ret = chip_open(&chip_data);
    if (ret < 0) {
        return ret;
    }

    chip_data.start_time = clock();

    while (1) {
        ret = chip_poll(&chip_data);
        if (ret < 0) {
            fprintf(stderr, "Error in chip_poll: %s\n", strerror(errno));
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    chip_close(&chip_data);
    return EXIT_SUCCESS;
}

