#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_PIN 17
#define BUFFER_SIZE 2048
#define SAMPLE_WIDTH 2

int main() {
    int fd, samples_read;
    snd_pcm_t *handle;
    int err;
    struct gpiod_chip chip;
    struct gpiod_line line;
    void *user_data = NULL;

    // Initialize GPIO
    err = gpiod_chip_open(&chip, GPIO_PIN);
    if (err) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        return EXIT_FAILURE;
    }
    err = gpiod_chip_set_owner(&chip, __FILE__, __LINE__);
    if (err) {
        fprintf(stderr, "Failed to claim GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(&chip);
        return EXIT_FAILURE;
    }
    err = gpiod_chip_get_line(&chip, &line, "GPIO%d", GPIO_PIN);
    if (err) {
        fprintf(stderr, "Failed to get GPIO %d line: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(&chip);
        return EXIT_FAILURE;
    }
    gpiod_line_export(&line, NULL);
    gpiod_line_direction_input(&line);

    // Initialize ALSA PCM
    snd_pcm_open(&handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    snd_pcm_hw_params_malloc(&handle);
    snd_pcm_hw_params_any(handle, handle->hw_params);
    snd_pcm_hw_params_set_access(handle, handle->hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(handle, handle->hw_params, SND_PCM_FORMAT_S16_LE);
    snd_pcm_hw_params_set_rate_near(handle, handle->hw_params, 44100, &err);
    snd_pcm_hw_params_set_channels(handle, handle->hw_params, 1);
    snd_pcm_hw_params_set_buffer_size_near(handle, handle->hw_params, BUFFER_SIZE * SAMPLE_WIDTH / 8);
    snd_pcm_hw_params(handle, handle->hw_params);

    // Prepare ALSA PCM
    if (snd_pcm_prepare(handle) < 0) {
        fprintf(stderr, "Failed to prepare ALSA PCM: %s\n", snd_strerror(err));
        gpiod_line_unref(&line);
        gpiod_chip_close(&chip);
        return EXIT_FAILURE;
    }

    // Start ALSA PCM
    if (snd_pcm_start(handle) < 0) {
        fprintf(stderr, "Failed to start ALSA PCM: %s\n", snd_strerror(err));
        snd_pcm_prepare(handle);
        gpiod_line_unref(&line);
        gpiod_chip_close(&chip);
        return EXIT_FAILURE;
    }

    // Open raw file for writing
    fd = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open audio_capture.pcm: %s\n", strerror(errno));
        snd_pcm_close(handle);
        gpiod_line_unref(&line);
        gpiod_chip_close(&chip);
        return EXIT_FAILURE;
    }

    // Read and write audio samples
    while (1) {
        err = snd_pcm_readi(handle, (char *)user_data, BUFFER_SIZE * SAMPLE_WIDTH / 2);
        if (err < 0) {
            fprintf(stderr, "Failed to read audio samples: %s\n", snd_strerror(err));
            break;
        }

        // Drive L/R channel-select line
        gpiod_line_set_value(&line, 1);
        write(fd, user_data, err);
        gpiod_line_set_value(&line, 0);
    }

    // Stop and close ALSA PCM
    snd_pcm_stop(handle);
    snd_pcm_close(handle);

    // Unprepare and close GPIO
    gpiod_line_unref(&line);
    gpiod_chip_close(&chip);

    // Close raw file
    close(fd);

    return EXIT_SUCCESS;
}

