#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define DEBOUNCE_DELAY 50000 // 50 ms
#define PWM_FREQ 100
#define TIMEOUT_DELAY 5000000 // 5 seconds

gpio_context ctx;
FILE *log_file = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        exit(0);
    }
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpiod_uninit();
}

bool init_driver() {
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return false;
    }

    ctx = gpiod_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create gpiod context\n");
        gpiod_exit();
        return false;
    }

    ret = gpiod_add_override(ctx, "IR Flame Sensor", FLAME_SENSOR_GPIO,
                           GPIOD_FLAG_INPUT, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to add IR Flame Sensor GPIO override\n");
        gpiod_exit();
        return false;
    }

    ret = gpiod_add_override(ctx, "Cooling Fan", FAN_GPIO,
                           GPIOD_FLAG_OUTPUT | GPIOD_FLAG_OPEN_DRAIN, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to add Cooling Fan GPIO override\n");
        gpiod_exit();
        return false;
    }

    return true;
}

int read_sensor() {
    int value;
    gpiod_get_value(ctx, FLAME_SENSOR_GPIO, &value);
    if (value < 0) {
        fprintf(stderr, "Failed to read IR Flame Sensor GPIO\n");
        return -1;
    }
    return value;
}

void start_pwm() {
    // PWM implementation is omitted as it requires additional libraries
    // (e.g., wiringPi, pigpio) which are not allowed in this request.
    // You would need to use an appropriate library to generate a 100 Hz PWM signal
    // on GPIO18 when the flame is detected.
}

int main() {
    struct timespec start_time, flame_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    fprintf(log_file, "System start: %ld.%09ld\n",
            start_time.tv_sec, start_time.tv_nsec);

    if (!init_driver()) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (true) {
        int value = read_sensor();
        if (value == 0) { // Flame detected (LOW)
            clock_gettime(CLOCK_MONOTONIC, &flame_time);
            fprintf(log_file, "Flame detected: %ld.%09ld\n",
                    flame_time.tv_sec, flame_time.tv_nsec);
            start_pwm(); // Start PWM to drive the fan
        } else if (value == 1) { // No flame (HIGH)
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            fprintf(log_file, "Flame ended: %ld.%09ld\n",
                    end_time.tv_sec, end_time.tv_nsec);
            // Stop PWM here
        }

        clock_nanosleep(CLOCK_MONOTONIC, 0, &DEBOUNCE_DELAY, NULL);
    }

    cleanup();
    fprintf(log_file, "Program shutdown: %ld.%09ld\n",
            (long)clock()->tv_sec, (long)clock()->tv_nsec);
    fclose(log_file);

    return 0;
}

