#define SPI_CHANNEL 0
#define CE0_GPIO 8
#define TRIG_GPIO 23
#define DRDY_GPIO 24
#define FRAME_DURATION_MS 100
#define SPI_BAUD_RATE (1000000)
#define FRAME_SIZE (32768)
#define MAGIC_NUMBER 0x444144

struct config {
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
};

struct frame_header {
    uint32_t magic_number;
    uint64_t timestamp;
    struct config config;
};

struct frame {
    struct frame_header header;
    uint64_t frame_number;
    uint8_t data[FRAME_SIZE];
};

