#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 20
#define POLL_INTERVAL_MS 100

static int gpio_chip_fd = -1;
static int flame_state = 0;
static FILE *flame_log_file = NULL;

static ssize_t log_state(const char *state) {
    static char timestamp[64];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

    if (flame_log_file != NULL) {
        return fprintf(flame_log_file, "%s %s\n", timestamp, state);
    }

    return -1;
}

static int setup_gpio(int gpio_num) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    gpio_chip_fd = gpiod_chip_open(gpio_num);
    if (gpio_chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return gpio_chip_fd;
    }

    chip = gpiod_chip_get(gpio_chip_fd);
    if (!chip) {
        goto err_chip_open;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        goto err_chip_get;
    }

    ret = gpiod_line_export(line, "KY-026 Flame Sensor");
    if (ret < 0) {
        goto err_line_export;
    }

    return 0;

err_line_export:
    gpiod_line_free(line);
err_chip_get:
    gpiod_chip_put(chip);
err_chip_open:
    gpiod_chip_close(gpio_chip_fd);
    return gpio_chip_fd;
}

static void cleanup_gpio() {
    if (gpio_chip_fd >= 0) {
        gpiod_chip_put(gpiod_chip_get(gpio_chip_fd));
        gpiod_chip_close(gpio_chip_fd);
        gpio_chip_fd = -1;
    }
}

static void signal_handler(int signum) {
    (void)signum;
    cleanup_gpio();
    exit(signum == SIGINT ? 0 : 1);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    struct gpiod_line *line;
    int ret;

    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_gpio(FLAME_SENSOR_GPIO) < 0) {
        cleanup_gpio();
        return 1;
    }

    line = gpiod_chip_get_line(gpiod_chip_get(gpio_chip_fd), 0);
    if (!line) {
        cleanup_gpio();
        return 1;
    }

    flame_log_file = fopen("flame_log.txt", "a");
    if (!flame_log_file) {
        gpiod_line_free(line);
        cleanup_gpio();
        return 1;
    }

    while (1) {
        ret = gpiod_line_read(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO line: %s\n", gpiod_strerror(ret));
            break;
        }

        if (ret != flame_state) {
            if (log_state(ret ? "FLAME DETECTED" : "FLAME CLEARED")) {
                fprintf(stderr, "Logged state transition to file\n");
            }
            flame_state = ret;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_free(line);
    fclose(flame_log_file);
    cleanup_gpio();

    return 0;
}

