#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define OPT3001_ADDR 0x44
#define MAX_RETRIES 3

struct opt3001_data {
    int fd;
    char filename[32];
    FILE *fp;
};

static int opt3001_read(struct i2c_client *client, uint8_t *buf, size_t len)
{
    struct opt3001_data *data = (struct opt3001_data *)client->private_data;

    if (i2c_xfer(data->fd, &I2C_RDWR | I2C_M_RD, OPT3001_ADDR, NULL, 0, buf, len) < 0) {
        fprintf(stderr, "I2C transfer failed\n");
        return -1;
    }

    return 0;
}

static int opt3001_init(struct i2c_client *client, const char *filename)
{
    struct opt3001_data *data = (struct opt3001_data *)client->private_data;
    int retries = 0;
    int ret;

    data->fd = i2c_open(OPT3001_ADDR);
    if (IS_ERR(data->fd)) {
        fprintf(stderr, "Failed to open I2C device\n");
        return PTR_ERR(data->fd);
    }

    snprintf(data->filename, sizeof(data->filename), "%s", filename);
    data->fp = fopen(data->filename, "a");
    if (!data->fp) {
        fprintf(stderr, "Failed to open file\n");
        i2c_close(data->fd);
        return -ENOMEM;
    }

    ret = i2c_set_pd(data->fd, true);
    if (ret) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        i2c_close(data->fd);
        return ret;
    }

    ret = i2c_set_drvdata(data->fd, client);
    if (ret) {
        fprintf(stderr, "Failed to set driver data\n");
        i2c_close(data->fd);
        return ret;
    }

    ret = i2c_set_read(data->fd, opt3001_read);
    if (ret) {
        fprintf(stderr, "Failed to set read function\n");
        i2c_close(data->fd);
        return ret;
    }

    // Configure OPT3001 for continuous conversion mode with automatic full-scale range
    uint8_t config[2] = {0x20, 0x00};
    if (i2c_xfer(data->fd, I2C_RDWR | I2C_M_RD, OPT3001_ADDR, config, 2, NULL, 0) < 0) {
        retries++;
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to configure OPT3001 after %d retries\n", MAX_RETRIES);
            i2c_close(data->fd);
            return -1;
        }
            // Retry configuration
            goto retry_config;
    }

    return 0;

retry_config:
    msleep(100); // Wait for 100 ms before retrying
    return 0;
}

static void opt3001_cleanup(struct i2c_client *client)
{
    struct opt3001_data *data = (struct opt3001_data *)client->private_data;

    fclose(data->fp);
    i2c_close(data->fd);
}

static const struct i2c_device_id opt3001_id[] = {
    { "opt3001", 0 },
    { }
};
I2C_DRIVER_REGISTER(opt3001, opt3001_id, opt3001_init, NULL, NULL, opt3001_cleanup);

void sigint_handler(int signum) {
    i2c_unregister(&i2c_opt3001);
    exit(0);
}

int main(int argc, char *argv[])
{
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_register(&i2c_opt3001, "opt3001", NULL, 0, 1, I2C_AMBIENT);

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        char timestamp[24];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        fprintf(data->fp, "%s ", timestamp);
        fflush(data->fp);

        msleep(100); // Wait for 100 ms between readings
    }

    return 0;
}

