#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.hpp>

#define GPIO_LINE_17 17

volatile sig_atomic_t sigint_flag = 0;

static void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main() {
    gpiod_context ctx;
    gpiod_chip chip;
    gpiod_line line;
    struct timespec ts;

    if (gpiod_new(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize gpiod\n");
        return EXIT_FAILURE;
    }

    if (gpiod_enumerate(&chip) < 0) {
        fprintf(stderr, "Failed to enumerate chips\n");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_open(chip, "ir_sensor") < 0) {
        fprintf(stderr, "Failed to open ir_sensor chip\n");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_line(chip, "ir_sensor.17", &line) < 0) {
        fprintf(stderr, "Failed to get line 17\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_get(line, "input", GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to request line 17 as input with pull-up\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!sigint_flag) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint32_t value = gpiod_line_get_value(line);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (value == 0) {
            fprintf(stdout, "%s Flame Detected: YES\n", timestamp);
        } else {
            fprintf(stdout, "%s Flame Detected: NO\n", timestamp);
        }

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_context_destroy(ctx);

    return EXIT_SUCCESS;
}

