    gpio_stop_output(chip);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpio_free(lines[i]);
    }
    gpio_free(chip);
    exit(0);
}

int main() {
    gpiochip_setup(0, "TTP226", GPIO_OUTPUT, NUM_CHANNELS);
    gpiochip_handle *chip = gpiochip_get(0);

    if (!chip) {
        fprintf(stderr, "Failed to get GPIO chip handle\n");
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpio_request(chip->num, i, GPIO_OUTPUT);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request line %d\n", i);
            gpio_free(chip);
            return 1;
        }
        gpio_set_value(lines[i], 1);
    }

    signal(SIGINT, sigint_handler);

    while (true) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpio_get_value(lines[i]);
            printf("%s Channel %d: %d\n", timestamp, i + 1, value);
