#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpio.h>

#define NUM_CHANNELS 8
#define SAMPLING_INTERVAL (100 * 1000) // 100 ms

// Signal handlers
void sigint_handler(int signum) {
    printf("Received SIGINT, exiting...\n");
    gpio_stop();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, exiting...\n");
    gpio_stop();
    exit(0);
}

int main() {
    struct gpio_config config;
    struct gpio_data data;
    int ret;

    // Initialize GPIO driver
    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver: %s\n", gpio_strerror(-ret));
        return EXIT_FAILURE;
    }

    // Configure GPIO pins
    for (int i = 0; i < NUM_CHANNELS; ++i) {
        config.line = i + 2; // GPIO2 to GPIO9
        config.pull = GPIO_PULL_DOWN;
        config.debounce = 0;
        config.input = true;
        ret = gpio_configure(&config);
        if (ret < 0) {
            fprintf(stderr, "Failed to configure GPIO %d: %s\n", config.line, gpio_strerror(-ret));
            gpio_stop();
            return EXIT_FAILURE;
        }
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Start sampling
    while (true) {
        ret = gpio_sample(&data, NUM_CHANNELS);
        if (ret < 0) {
            fprintf(stderr, "Failed to sample GPIOs: %s\n", gpio_strerror(-ret));
            break;
        }

        // Print the current state of all channels
        for (int i = 0; i < NUM_CHANNELS; ++i) {
            printf("CH%d=%d", i + 1, data.lines[i]);
        }
        printf(" [");
        printf("%ldms", (long)(clock() / CLOCKS_PER_SEC * 1000));
        printf("]\n");
    }

    // Stop GPIO driver
    gpio_stop();

    return EXIT_SUCCESS;
}

