#define SENSOR2_GPIO 5
#define LOG_INTERVAL_MS 500

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_release(chip);
    exit(0);
}

int main() {
    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get sensor1 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get sensor2 line\n");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_cooked(sensor1_line, 1) < 0 ||
        gpiod_line_request_cooked(sensor2_line, 1) < 0) {
        fprintf(stderr, "Failed to request cooked lines\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        uint32_t sensor1_state = gpiod_line_get_value(sensor1_line);
        uint32_t sensor2_state = gpiod_line_get_value(sensor2_line);

        if (sensor1_state == 0)
            printf("Sensor 1: LOW\n");
        else
            printf("Sensor 1: HIGH\n");

        if (sensor2_state == 0)
            printf("Sensor 2: LOW\n");
        else
            printf("Sensor 2: HIGH\n");

        sleep(LOG_INTERVAL_MS / 1000);
    }

    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

