#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

gpio_context *ctx;

void sigint_handler(int signum) {
    printf("\nInterrupted. Cleaning up...\n");
    gpio_terminate(ctx);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    ctx = gpio_init();
    if (!ctx) {
        fprintf(stderr, "Failed to initialize GPIO library.\n");
        return 1;
    }

    const int pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
    for (size_t i = 0; i < NUM_CHANNELS; i++) {
        if (gpio_request(ctx, pins[i], GPIO_INPUT, GPIO_BIAS_DISABLE) < 0) {
            fprintf(stderr, "Failed to request pin %d.\n", pins[i]);
            gpio_terminate(ctx);
            return 1;
        }
    }

    while (1) {
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        for (size_t i = 0; i < NUM_CHANNELS; i++) {
            int state;
            if (gpio_get(ctx, pins[i]) < 0) {
                fprintf(stderr, "Failed to read pin %d.\n", pins[i]);
                gpio_terminate(ctx);
                return 1;
            }
            state = gpio_get(ctx, pins[i]) == GPIO_HIGH;
            printf("%s,%d", timestamp, state);

            if (i < NUM_CHANNELs - 1) {
                printf(",");
            }
        }
        printf("\n");

        gpio_sleep(ctx, POLL_INTERVAL_MS);
    }

    gpio_terminate(ctx);
    return 0;
}

