#include <fcntl.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "0"
#define CSV_FILE "uv_als_log.csv"

struct si1145_data {
    uint8_t uv_index;
    uint8_t visible_light;
};

int main() {
    int fd;
    struct si1145_data data;
    FILE *log_file;
    char timestamp[20];
    int ret;

    // Initialize I2C file descriptor
    fd = i2c_open(I2C_BUS);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // I2C address of the sensor
    if (i2c_transfer(fd, 0x60, &data, 2) < 0) {
        fprintf(stderr, "Failed to read from sensor\n");
        i2c_close(fd);
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2c_close(fd);
        return 1;
    }

    // Signal handler setup
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Get current timestamp
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        // Print sensor readings to console
        printf("UV Index: %d, Visible Light: %d\n", data.uv_index, data.visible_light);

        // Append to CSV file
        fprintf(log_file, "%s,%d,%d\n", timestamp, data.uv_index, data.visible_light);

        // Wait for 1 second
        sleep(1);

        // I2C read operation
        if (i2c_transfer(fd, 0x60, &data, 2) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }
    }

    // Close log file
    fclose(log_file);

    // Close I2C file descriptor
    i2c_close(fd);

    return 0;
}

void signal_handler(int signum) {
    printf("Signal %d received, cleaning up and exiting...\n", signum);
    // Perform any necessary cleanup here before exiting
    exit(signum);
}

