#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <stdbool.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define SENSOR_ADDR_1 0x48
#define SENSOR_ADDR_2 0x49
#define CRC_POLYNOMIAL 0x1021
#define CRC_INIT_VALUE 0xFFFF

#define I2C_FILE "/dev/i2c-1"
#define GPIO_PIN 17
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL 1
#define WAIT_TIME 0.1

int i2c_fd;
int gpio_fd;
FILE *log_file;

void start_sensors() {
    write(i2c_fd, "START\0", 5);
    lseek(i2c_fd, 0, SEEK_SET);
    read(i2c_fd, NULL, 1);
}

uint16_t read_sensor(uint8_t addr, uint16_t *crc) {
    uint8_t buf[2];
    uint16_t data;

    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error\n");
        *crc = 0xFFFF;
        return 0;
    }

    data = (buf[1] << 8) | buf[0];
    *crc = crc_calculate(data, *crc);

    if (*crc != 0) {
        fprintf(stderr, "CRC error\n");
        return 0;
    }

    return data;
}

uint16_t crc_calculate(uint16_t data, uint16_t crc) {
    uint8_t i;
    for (i = 0; i < 8; i++) {
        if (crc & 0x8000) {
            crc = (crc << 1) ^ CRC_POLYNOMIAL;
        } else {
            crc <<= 1;
        }
        if (data & 0x8000) {
            crc ^= 0x1021;
        }
        data <<= 1;
    }
    return crc;
}

void setup_gpio() {
    gpiod_chip_handle chip;
    gpiod_chip_handle_create(GPIO_PIN, &chip);
    gpiod_chip_set_owner(chip, "flow_alarm");

    gpiod_chip_get_line(chip, 0, &gpio_fd);
    gpiod_chip_set_direction(gpio_fd, GPIO_OUTPUT);
    gpiod_chip_set_value(gpio_fd, 0);
}

void cleanup_gpio() {
    gpiod_chip_put(gpio_fd);
    gpiod_chip_release(chip);
}

void setup_i2c() {
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR_1) < 0) {
        perror("Failed to acquire bus for sensor 1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR_2) < 0) {
        perror("Failed to acquire bus for sensor 2");
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
    close(i2c_fd);
}

void log_flow_rate(uint16_t flow_rate_1, uint16_t flow_rate_2) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%d,%d\n", flow_rate_1, flow_rate_2);
    ff lush(log_file);
}

void alarm_trigger(uint16_t avg_flow) {
    if (avg_flow < 0.5) {
        gpiod_chip_set_value(gpio_fd, 1);
    } else {
        gpiod_chip_set_value(gpio_fd, 0);
    }
}

void signal_handler(int signum) {
    cleanup_i2c();
    cleanup_gpio();
    fclose(log_file);
    exit(0);
}

int main() {
    struct gpiod_chip_params chip_params = {
        .gpio_pin = GPIO_PIN,
        .flags = 0,
    };

    struct gpiod_chip_handle *chip;
    gpiod_chip_handle_create(GPIO_PIN, &chip);
    gpiod_chip_set_owner(chip, "flow_alarm");

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR_1) < 0) {
        perror("Failed to acquire bus for sensor 1");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR_2) < 0) {
        perror("Failed to acquire bus for sensor 2");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_i2c();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t flow_rate_1 = 0, flow_rate_2 = 0;
    uint16_t crc_1 = 0, crc_2 = 0;
    uint32_t total_flow_rate = 0;
    int sample_count = 0;

    start_sensors();
    usleep(WAIT_TIME * 1000000);

    while (1) {
        flow_rate_1 = read_sensor(SENSOR_ADDR_1, &crc_1);
        flow_rate_2 = read_sensor(SENSOR_ADDR_2, &crc_2);

        total_flow_rate += flow_rate_1 + flow_rate_2;
        sample_count++;

        alarm_trigger((total_flow_rate / sample_count));

        log_flow_rate(flow_rate_1, flow_rate_2);

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    cleanup_i2c();
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

