code:
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define BUFFER_SIZE 100
#define GPIO_SENSOR 7
#define SAMPLE_INTERVAL_MS 50

typedef struct {
    time_t timestamp;
    bool detected;
} Detection;

Detection buffer[BUFFER_SIZE];
int buffer_index = 0;

void print_detection(Detection det) {
    printf("%ld: Detected\n", det.timestamp);
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer_index + i >= BUFFER_SIZE) {
            i -= BUFFER_SIZE;
        }
        Detection det = buffer[i];
        printf("%ld: Detected\n", det.timestamp);
    }
}

int main() {
    struct gpiod_chip_params params;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    gpiod_chip_init();

    if (gpiod_chip_register_get("gpiochip0", &params) < 0) {
        fprintf(stderr, "Failed to get gpiochip0\n");
        return 1;
    }

    chip = gpiod_chip_new_from_params(params);
    if (!chip) {
        fprintf(stderr, "Failed to create gpiochip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 7);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO7\n");
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_request_get(line, "input") < 0) {
        fprintf(stderr, "Failed to request input for GPIO7\n");
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_set_pull(line, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up resistor for GPIO7\n");
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (true) {
        struct gpiod_line_event event;
        int r = gpiod_line_read(line, &event);
        if (r < 0) {
            fprintf(stderr, "Failed to read from GPIO7\n");
            break;
        }

        if (event.value == 0) { // LOW (obstacle detected)
            buffer[buffer_index] = (Detection){time(NULL), true};
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            print_detection(buffer[buffer_index - 1]);
        } else { // HIGH (no obstacle)
            buffer[buffer_index] = (Detection){time(NULL), false};
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    print_buffer();

    gpiod_line_free(line);
    gpiod_chip_put(chip);
    gpiod_chip_uninit();

    return 0;
}

