int d7s_z_reg = -1;
int d7s_status_reg = -1;
FILE *csv_file = NULL;

void init_i2c() {
    i2c_fd = i2c_open(0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    struct gpiod_chip_params params = {};
    params.gpio_chip_id = 0;

    struct gpiod_chip *chip = gpiod_chip_open(&params);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *sda = gpiod_chip_get_line(chip, 2);
    struct gpiod_line *scl = gpiod_chip_get_line(chip, 3);

    if (!sda || !scl) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(sda, "GPIO2");
    gpiod_line_export(scl, "GPIO3");
    gpiod_line_direction_input(sda);
    gpiod_line_direction_input(scl);
    gpiod_chip_close(chip);
}

void init_d7s() {
    if (i2c_master_init(i2c_fd, D7S_I2C_ADDR) < 0) {
        perror("Failed to initialize I2C communication");
        exit(EXIT_FAILURE);
    }

    if (i2c_master_write_byte_data(i2c_fd, D7S_MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to set D7S mode, retrying...\n");
        return;
    }

    if (i2c_master_read_byte_data(i2c_fd, D7S_STATUS_REG) < 0) {
        fprintf(stderr, "Failed to read D7S status, retrying...\n");
        return;
    }

    d7s_mode_reg = i2c_master_read_byte_data(i2c_fd, D7S_MODE_REG);
    d7s_x_reg = i2c_master_read_byte_data(i2c_fd, D7S_X_REG);
    d7s_y_reg = i2c_master_read_byte_data(i2c_fd, D7S_Y_REG);
    d7s_z_reg = i2c_master_read_byte_data(i2c_fd, D7S_Z_REG);
    d7s_status_reg = i2c_master_read_byte_data(i2c_fd, D7S_STATUS_REG);
}

