    if (csv_file) {
        if (fputs("[", csv_file) < 0) {
            fprintf(stderr, "Failed to write CSV header, retrying...\n");
            fclose(csv_file);
            csv_file = NULL;
        }
        fputs("Time,X,Y,Z\n", csv_file);
    }
}

void write_sample(int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);

    if (fputs(timestamp, csv_file) < 0) {
        fprintf(stderr, "Failed to write timestamp, retrying...\n");
        return;
    }

    if (fputs(",%d,%d,%d\n", x, y, z, csv_file) < 0) {
        fprintf(stderr, "Failed to write sample, retrying...\n");
    }
}

int main() {
    signal(SIGINT, [](int) {
        i2c_close(i2c_fd);
        fclose(csv_file);
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int) {
        i2c_close(i2c_fd);
        fclose(csv_file);
        exit(EXIT_SUCCESS);
    });

    init_i2c();
    init_gpio();
    init_d7s();
    open_csv_file();

    bool sensor_active = false;
    time_t start_time = 0;

    while (1) {
        if (!sensor_active && time(NULL) - start_time > ACTIVATION_TIMEOUT_S) {
            fprintf(stderr, "Error: D7S sensor did not become active within the timeout period.\n");
            i2c_close(i2c_fd);
            fclose(csv_file);
            return EXIT_FAILURE;
        }

        if (i2c_master_read_byte_data(i2c_fd, D7S_STATUS_REG) != 0x01) {
            sensor_active = true;
        }

        if (sensor_active) {
            int x = i2c_master_read_byte_data(i2c_fd, d7s_x_reg);
            int y = i2c_master_read_byte_data(i2c_fd, d7s_y_reg);
            int z = i2c_master_read_byte_data(i2c_fd, d7s_z_reg);
            write_sample(x, y, z);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2c_close(i2c_fd);
    fclose(csv_file);
    return EXIT_SUCCESS;
}

