#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define LED_GPIO 25

static volatile sig_atomic_t sigint_received = 0;

static int sensor_callback(const struct gpiod_chip *chip,
                           const struct gpiod_line *line, uint32_t events) {
    if (events & (1 << GPIOD_LINE_DIR_IN)) {
        if ((line->line & 0x1) && !gpiod_read(line)) {
            sigint_received = 1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    struct gpiod_chipchip *chip;
    struct gpiod_line *sensor1, *sensor2, *led;
    int ret;

    // Initialize libgpiod
    ret = gpiod_new(&chip);
    if (ret) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return ret;
    }

    // Find GPIOs
    ret = gpiod_chip_find_physical(chip, "GPIO23", &sensor1);
    if (ret) {
        fprintf(stderr, "Failed to find GPIO23\n");
        goto chip_destroy;
    }
    ret = gpiod_chip_find_physical(chip, "GPIO24", &sensor2);
    if (ret) {
        fprintf(stderr, "Failed to find GPIO24\n");
        goto sensor1_release;
    }
    ret = gpiod_chip_find_physical(chip, "GPIO25", &led);
    if (ret) {
        fprintf(stderr, "Failed to find GPIO25\n");
        goto sensor2_release;
    }

    // Set direction
    gpiod_line_set_dir(sensor1, GPIOD_LINE_IN);
    gpiod_line_set_dir(sensor2, GPIOD_LINE_IN);
    gpiod_line_set_dir(led, GPIOD_LINE_OUT);

    // Export GPIOs
    ret = gpiod_export(sensor1);
    if (ret) {
        fprintf(stderr, "Failed to export GPIO23\n");
        goto chip_destroy;
    }
    ret = gpiod_export(sensor2);
    if (ret) {
        fprintf(stderr, "Failed to export GPIO24\n");
        goto chip_destroy;
    }
    ret = gpiod_export(led);
    if (ret) {
        fprintf(stderr, "Failed to export GPIO25\n");
        goto chip_destroy;
    }

    // Setup callbacks
    gpiod_line_set_callback(sensor1, sensor_callback);
    gpiod_line_set_callback(sensor2, sensor_callback);

    // Wait for signals
    sigint_received = 0;
    while (!sigint_received) {
        gpiod_poll(sensor1, 100 * 1000);
        gpiod_poll(sensor2, 100 * 1000);

        if (gpiod_read(sensor1) && gpiod_read(sensor2)) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }
    }

    // Clean up
    gpiod_unexport(led);
    gpiod_unexport(sensor2);
    gpiod_unexport(sensor1);
    gpiod_chip_free(chip);

chip_destroy:
    gpiod_line_release(sensor1);
sensor1_release:
    gpiod_line_release(sensor2);
sensor2_release:
    gpiod_chip_free(chip);

    return sigint_received ? EXIT_SUCCESS : EXIT_FAILURE;
}

// Handle SIGINT and SIGTERM
void sigint_handler(int signum) {
    sigint_received = 1;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    return main(argc, argv);
}

