#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define STALL_THRESHOLD_SEC 2
#define STALL_LOG_FILE "stall_log.txt"

struct stall_entry {
    time_t timestamp;
    bool confirmed;
};

static bool file_write_stall(const char *filename, struct stall_entry entry) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file %s for writing\n", filename);
        return false;
    }

    if (fprintf(file, "%ld\n", entry.timestamp) < 0) {
        fclose(file);
        return false;
    }

    fclose(file);
    return true;
}

int main() {
    struct gpiod_chipchip *chi;
    struct gpiod_chip_line *line1, *line2;
    struct stall_entry last_stall = {0, false};
    time_t last_timestamp = 0;

    if (gpiod_chip_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize gpiod library\n");
        return EXIT_FAILURE;
    }

    chi = gpiod_chip_find("GPIO17");
    if (!chi) {
        fprintf(stderr, "Error: Could not find GPIO17\n");
        gpiod_chip_exit();
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chi, 17);
    if (!line1) {
        fprintf(stderr, "Error: Could not get line for GPIO17\n");
        gpiod_chip_exit();
        return EXIT_FAILURE;
    }

    chi = gpiod_chip_find("GPIO18");
    if (!chi) {
        fprintf(stderr, "Error: Could not find GPIO18\n");
        gpiod_chip_exit();
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chi, 18);
    if (!line2) {
        fprintf(stderr, "Error: Could not get line for GPIO18\n");
        gpiod_chip_exit();
        return EXIT_FAILURE;
    }

    gpiod_line_export(line1, true);
    gpiod_line_export(line2, true);

    gpiod_line_set_direction(line1, GPIO_OUT);
    gpiod_line_set_direction(line2, GPIO_OUT);

    while (true) {
        time_t current_time = time(NULL);

        if (current_time - last_timestamp >= STALL_THRESHOLD_SEC) {
            bool sensor1_low = gpiod_line_get_value(line1) == 0;
            bool sensor2_low = gpiod_line_get_value(line2) == 0;

            if (sensor1_low && sensor2_low && !last_stall.confirmed) {
                struct stall_entry new_stall = {current_time, true};

                if (!file_write_stall(STALL_LOG_FILE, new_stall)) {
                    fprintf(stderr, "Error: Failed to write stall entry to file\n");
                }

                last_stall = new_stall;
                last_timestamp = current_time;
            }
        }

        usleep(1000000); // Sleep for 1 second
    }

    gpiod_line_unset(line1, true);
    gpiod_line_unset(line2, true);

    gpiod_chip_exit();
    return EXIT_SUCCESS;
}

