#include <libgpiod.h>

#define I2C_BUS 1
#define TMAG5170_ADDR 0x20
#define SAMPLE_INTERVAL_MS 100

struct tmag5170_data {
    gpiod_chip chip;
    gpiod_line mag_x;
    gpiod_line mag_y;
    gpiod_line mag_z;
};

static void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    tmag5170_cleanup(&tmag5170);
    gpiod_unclaim(&tmag5170.chip);
    fclose(fp);
    exit(0);
}

static int tmag5170_init(struct tmag5170_data *tmag5170) {
    int ret;

    ret = gpiod_in_claim(&tmag5170->chip, TMAG5170_ADDR,
                        "TMAG5170_ADDR",
                        GPIOD_IN_ACTIVE_LOW,
                        &tmag5170->mag_x,
                        &tmag5170->mag_y,
                        &tmag5170->mag_z);
    if (ret < 0) {
        fprintf(stderr, "Failed to claim GPIO pins\n");
        return ret;
    }

    ret = gpiod_chip_set_owner(&tmag5170->chip, __RUN_IN_INTERPRETER);
    if (ret < 0) {
        fprintf(stderr, "Failed to set chip owner\n");
        return ret;
    }

    return 0;
}

static void tmag5170_cleanup(struct tmag5170_data *tmag5170) {
    gpiod_chip_put(&tmag5170->chip);
}

static int tmag5170_read(struct tmag5170_data *tmag5170, int16_t *x, int16_t *y, int16_t *z) {
    *x = gpiod_get_value(&tmag5170->mag_x);
    *y = gpiod_get_value(&tmag5170->mag_y);
    *z = gpiod_get_value(&tmag5170->mag_z);

    if (*x == -1 || *y == -1 || *z == -1) {
        fprintf(stderr, "Error reading from TMAG5170\n");
        return -1;
    }

    return 0;
}

int main() {
    struct tmag5170_data tmag5170;
    FILE *fp = NULL;
    char timestamp[32];

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (tmag5170_init(&tmag5170) < 0) {
        return 1;
    }

    if (fpopen_noblock("magnetic_log.csv", "w") == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.csv for writing\n");
        return 1;
    }

    while (true) {
        time_t now;
        struct tm *time_struct;
        char *format = "%Y-%m-%dT%H:%M:%S";

        time(&now);
        time_struct = localtime(&now);
        strftime(timestamp, sizeof(timestamp), format, time_struct);

        if (fp == NULL || fseek(fp, 0, SEEK_SET) < 0) {
            fprintf(stderr, "Error seeking to beginning of CSV file\n");
            return 1;
        }

        if (fputs(timestamp, fp) == EOF) {
            fprintf(stderr, "Error writing timestamp to CSV file\n");
            return 1;
        }

        if (fputc('\n', fp) == EOF) {
            fprintf(stderr, "Error writing newline to CSV file\n");
            return 1;
        }

        int16_t x, y, z;
        if (tmag5170_read(&tmag5170, &x, &y, &z) < 0) {
            continue;
        }

        if (fputs(",\"%d\",%d,%d,%d\n", x, y, z, ferror(fp)) == EOF) {
            fprintf(stderr, "Error writing magnetic field values to CSV file\n");
            return 1;
        }

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    fclose(fp);
    tmag5170_cleanup(&tmag5170);
    return 0;
}

