#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define CHECK_INTERVAL 60

static FILE *log_file;
static gpiod_chip *chip;
static gpiod_line *line;

void init_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line(chip, SENSOR_PIN, &line);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO line %d\n", SENSOR_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_export(line, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO line %d\n", SENSOR_PIN);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_direction(line, GPIO_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line %d direction to input\n", SENSOR_PIN);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpiod_line_free(line);
    gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup_gpio();
        exit(0);
    }
}

void read_sensor() {
    int value;

    value = gpiod_line_read(line);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO line %d\n", SENSOR_PIN);
        log_error();
        schedule_reinit();
        return;
    }

    if (value == 1) {
        print_alert();
        log_alert();
    }
}

void print_alert() {
    fprintf(stdout, "ALERT: Water detected\n");
    fflush(stdout);
}

void log_alert() {
    time_t now;
    struct tm *time_struct;
    char date_time[64];

    now = time(NULL);
    time_struct = localtime(&now);
    strftime(date_time, sizeof(date_time), "%Y-%m-%d %H:%M:%S", time_struct);

    fprintf(log_file, "%s ALERT: Water detected\n", date_time);
    fflush(log_file);
}

void log_error() {
    fprintf(log_file, "%s ERROR: GPIO read failed\n", time_str());
    fflush(log_file);
}

void schedule_reinit() {
    struct itimerval timer;
    fd_set set;
    int ret;

    timer.it_value.tv_sec = CHECK_INTERVAL;
    timer.it_value.tv_usec = 0;
    timer.it_interval.tv_sec = CHECK_INTERVAL;
    timer.it_interval.tv_usec = 0;

    ret = ioctl(STDIN_FILENO, I_SRVCNT, &timer);
    if (ret < 0) {
        fprintf(stderr, "Failed to set timer\n");
        exit(EXIT_FAILURE);
    }

    FD_ZERO(&set);
    FD_SET(STDIN_FILENO, &set);

    ret = select(STDIN_FILENO + 1, NULL, &set, NULL, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to wait for timer\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct sigaction sa;
    int ret;

    sa.sa_handler = signal_handler;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        exit(EXIT_FAILURE);
    }

    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGTERM\n");
        exit(EXIT_FAILURE);
    }

    init_gpio();
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_sensor();
        sleep(2);
    }

    cleanup_gpio();
    fclose(log_file);
    return 0;
}

