#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define SAMPLE_INTERVAL_SEC 1

static int sensor_fd;
static int pulse_count;
static FILE *log_file;

static void timer_callback(const struct gpiod_trigger_handle *handle, uint64_t flags) {
    static struct timespec last_sample_time;
    static int samples_since_last_sample;

    if (samples_since_last_sample == 0) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (now.tv_sec != last_sample_time.tv_sec || now.tv_nsec != last_sample_time.tv_nsec) {
            last_sample_time = now;
            samples_since_last_sample = 0;
        }

        samples_since_last_sample++;
    }

    if (samples_since_last_sample >= 1000) { // Approximate 1-second interval
        samples_since_last_sample = 0;

        double rpm = (pulse_count * 60.0) / SAMPLE_INTERVAL_SEC;
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));

        fprintf(log_file, "%s %f\n", timestamp, rpm);
        fflush(log_file);
        printf("%s %f\n", timestamp, rpm);
        pulse_count = 0;
    }
}

static void signal_handler(int signum) {
    gpiod_trigger_stop(sensor_fd, NULL);
    fclose(log_file);
    gpiod_cleanup();
    exit(signum);
}

int main() {
    struct gpiod_chipchip *chip;
    struct gpiod_lineline *line;
    struct gpiod_trigger_config trigger_config;
    struct gpiod_trigger_handle *handle;

    if (gpiod_chip_open(&chip, "gpiochip0") < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO%d\n", SENSOR_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_add(line, GPIO_DIR_IN) < 0) {
        fprintf(stderr, "Failed to request input line GPIO%d\n", SENSOR_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_get_value(line) < 0) {
        fprintf(stderr, "Failed to get pull-up value for GPIO%d\n", SENSOR_PIN);
        gpiod_line_request_free(line->request);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_trigger_setup(&trigger_config, line, GPIO_FALLING_EDGE, 0);
    handle = gpiod_trigger_create(line, &trigger_config);
    if (!handle) {
        fprintf(stderr, "Failed to create trigger for GPIO%d\n", SENSOR_PIN);
        gpiod_line_request_free(line->request);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_trigger_add_handler(handle, timer_callback);

    if ((log_file = fopen("rpm_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file rpm_log.txt\n");
        gpiod_trigger_free(handle);
        gpiod_line_request_free(line->request);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpiod_trigger_start(handle);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &last_sample_time);
        usleep(SAMPLE_INTERVAL_SEC * 1e6);
    }

    gpiod_trigger_free(handle);
    gpiod_line_request_free(line->request);
    gpiod_chip_close(chip);

    return 0;
}

