#include <fcntl.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <syslog.h>
#include <signal.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t sigint_received = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *led_line;

static void touch_callback(struct gpiod_line *line, uint32_t events) {
    if (events & (1 << GPIODO_EVENT_FALLING_EDGE)) {
        syslog(LOG_INFO, "Touch sensor activated");
    }
}

static int init_gpio(void) {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %d", ret);
        return ret;
    }

    ret = gpiod_chip_request_lines(chip, &touch_line, &led_line, TOUCH_SENSOR_GPIO, LED_GPIO);
    if (ret < 0) {
        gpiod_chip_close(chip);
        return ret;
    }

    if (ret != 1) {
        syslog(LOG_ERR, "Failed to request GPIO lines: %d", ret);
        gpiod_chip_close(chip);
        return ret;
    }

    touch_line->events = GPIOC_FALLING_EDGE;
    touch_line->debounce_timeout_us = 0;
    touch_line->user_data = NULL;
    touch_line->callback = touch_callback;

    led_line->direction = GPIO_DIR_OUT;

    return 0;
}

static void cleanup_gpio(void) {
    if (touch_line) {
        gpiod_line_unregister(touch_line);
    }

    if (led_line) {
        gpiod_line_unregister(led_line);
    }

    gpiod_chip_close(chip);
}

static void sigint_handler(int signum) {
    sigint_received = 1;
}

int main(int argc, char *argv[]) {
    struct timespec poll_interval;
    int ret;

    ret = openlog("touch_led_control", LOG_PID | LOG_PERROR, LOG_DAEMON);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize syslog");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    ret = init_gpio();
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        openlog("touch_led_control", LOG_PID | LOG_PERROR, LOG_DAEMON);
        return ret;
    }

    syslog(LOG_INFO, "GPIO initialized successfully");

    while (!sigint_received) {
        poll_interval.tv_sec = 0;
        poll_interval.tv_nsec = POLL_INTERVAL_MS * 1000000 / 2;

        ret = gpiod_batch();
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to batch GPIO operations: %d", ret);
            break;
        }

        if (touch_line->value) {
            gpiod_line_write(led_line, 1);
        } else {
            gpiod_line_write(led_line, 0);
        }

        nanosleep(&poll_interval, NULL);
    }

    cleanup_gpio();
    syslog(LOG_INFO, "GPIO cleanup and shutdown completed");
    closelog();

    return 0;
}

