#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpio.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_TIME 50000 // 50 ms in microseconds

struct gpio_line *touch_line = NULL;
struct gpio_line *led_line = NULL;
bool last_touch_state = false;
bool current_touch_state = false;

void signal_handler(int signum) {
    gpio_free(touch_line);
    gpio_free(led_line);
    exit(signum);
}

void init_gpio() {
    int ret;

    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    touch_line = gpio_request(TOUCH_PIN, "input", &last_touch_state);
    if (!touch_line) {
        fprintf(stderr, "Failed to request touch line\n");
        gpio_free();
        exit(EXIT_FAILURE);
    }

    led_line = gpio_request(LED_PIN, "output", NULL);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED line\n");
        gpio_free(touch_line);
        gpio_free();
        exit(EXIT_FAILURE);
    }

    gpio_set_value(led_line, 0); // Set LED to LOW
}

void wait_for_touch() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_TIME;

    while (true) {
        ret = gpio_eve_wait(touch_line, GPIO_FALLING_EDGE, ts);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for touch event\n");
            break;
        }

        current_touch_state = gpio_get_value(touch_line);
        if (current_touch_state != last_touch_state) {
            // Debounce
            if (current_touch_state) {
                gpio_set_value(led_line, 1); // Turn on LED
            } else {
                gpio_set_value(led_line, 0); // Turn off LED
            }
            last_touch_state = current_touch_state;
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();

    while (true) {
        wait_for_touch();
    }

    gpio_free(touch_line);
    gpio_free(led_line);
    return 0;
}

