#include <gpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

static FILE *log_file = NULL;
static bool last_state = false;

void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpio_uninit();
    exit(0);
}

void setup_gpio() {
    int ret;

    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(EXIT_FAILURE);
    }

    ret = gpio_request_available(GPIO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d\n", GPIO_PIN);
        gpio_uninit();
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_mode(GPIO_PIN, GPIO_MODE_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpio_release(GPIO_PIN);
        gpio_uninit();
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_pull(GPIO_PIN, GPIO_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable pull-up resistor on GPIO %d\n", GPIO_PIN);
        gpio_set_mode(GPIO_PIN, GPIO_MODE_INPUT);
        gpio_release(GPIO_PIN);
        gpio_uninit();
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_edge_detect(GPIO_PIN, GPIO_EDGE_FALLING);
    if (ret < 0) {
        fprintf(stderr, "Failed to set edge detection on GPIO %d\n", GPIO_PIN);
        gpio_set_pull(GPIO_PIN, GPIO_PULL_UP);
        gpio_set_mode(GPIO_PIN, GPIO_MODE_INPUT);
        gpio_release(GPIO_PIN);
        gpio_uninit();
        exit(EXIT_FAILURE);
    }
}

void setup_logging() {
    if (log_file != NULL) {
        fclose(log_file);
    }

    log_file = fopen("/var/log/rain_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void check_rain_state() {
    int state;
    time_t now;
    struct tm *time_struct;

    state = gpio_get_level(GPIO_PIN);
    now = time(NULL);
    time_struct = localtime(&now);

    if (state == 0 && last_state == 1) {
        fprintf(log_file, "%ld Rain Detected\n", (long)now);
    } else if (state == 1 && last_state == 0) {
        fprintf(log_file, "%ld No Rain\n", (long)now);
    }

    last_state = state;
}

int main() {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = sigint_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_logging();

    while (true) {
        check_rain_state();
        sleep(5);
    }

    return 0;
}

