#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <gpio.h>

#define DEBOUNCE_DELAY 5000  // 5 ms
#define SENSORS_COUNT 2
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

gpio_context ctx;
FILE *log_file = NULL;

void cleanup() {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpio_free(&ctx);
}

void sigint_handler(int signum) {
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec timestamp;
    int sensor_states[SENSORS_COUNT] = {0};
    int prev_states[SENSORS_COUNT] = {0};
    int rpm = 0;
    int transitions = 0;

    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("shaft_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    gpio_output_request_t req1 = GPIOF_OUT_LOW | GPIOF_OUTPUT(SENSOR1_GPIO);
    gpio_output_request_t req2 = GPIOF_OUT_LOW | GPIOF_OUTPUT(SENSOR2_GPIO);

    if (gpio_request(&ctx, SENSOR1_GPIO, &req1) < 0 || gpio_request(&ctx, SENSOR2_GPIO, &req2) < 0) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        return EXIT_FAILURE;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &timestamp);
        char time_str[64];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp.tv_sec));

        int current_state[SENSORS_COUNT];
        current_state[0] = gpio_input(&ctx, SENSOR1_GPIO);
        current_state[1] = gpio_input(&ctx, SENSOR2_GPIO);

        if (current_state[0] != prev_states[0] || current_state[1] != prev_states[1]) {
            transitions++;
            prev_states[0] = current_state[0];
            prev_states[1] = current_state[1];

            if (transitions >= 2) {
                int delta_time = (int)(timestamp.tv_sec - (timestamp.tv_sec / 60) * 60) * 1000000 + timestamp.tv_nsec;
                rpm = 60 * 1000000 / (delta_time / (transitions - 1));
                printf("Current RPM: %.2f\n", rpm);

                fprintf(log_file, "%s,%d,%d\n", time_str, current_state[0], current_state[1]);

                transitions = 0;
            }
        }

        usleep(DEBOUNCE_DELAY);
    }

    cleanup();
    fclose(log_file);
    return EXIT_SUCCESS;
}

