#include <unistd.h>
#include <gpio.h>

#define SI1182_ADDR 0x60

struct si1182_data {
    int fd;
    int i2c_bus;
};

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    si1182_cleanup(&data);
    exit(0);
}

int si1182_init(struct si1182_data *data) {
    int ret;

    data->fd = gpiod_open();
    if (!data->fd) {
        perror("Failed to open GPIO library");
        return -1;
    }

    ret = gpiod_add_dev(data->fd, "i2c-1");
    if (ret < 0) {
        perror("Failed to add I2C device");
        gpiod_free(data->fd);
        return -1;
    }

    return 0;
}

void si1182_cleanup(struct si1182_data *data) {
    gpiod_free(data->fd);
}

int si1182_read(struct si1182_data *data, uint8_t *buffer, size_t length) {
    int ret;

    ret = gpiod_iomap(data->fd, SI1182_ADDR);
    if (ret < 0) {
        perror("Failed to I/O map I2C address");
        return -1;
    }

    ret = gpiod_bulk_read(data->fd, SI1182_ADDR, buffer, length);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        gpiod_iomap_unset(data->fd, SI1182_ADDR);
        return -1;
    }

    gpiod_iomap_unset(data->fd, SI1182_ADDR);
    return ret;
}

int main() {
    struct si1182_data data;
    FILE *log_file;
    char timestamp[20];
    uint8_t buffer[6];
    int ret;

    signal(SIGINT, sigint_handler);

    if (si1182_init(&data) < 0) {
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        si1182_cleanup(&data);
        return 1;
    }

    while (1) {
        time_t now;
        struct tm *time_struct;
        char date_str[20];

        time(&now);
        time_struct = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

        if (si1182_read(&data, buffer, 6) < 0) {
            continue;
        }

        sprintf(date_str, "%s", timestamp);
        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", date_str,
                (int)(buffer[0] * 10), (int)(buffer[1] * 10));
        fflush(log_file);

        sleep(1);
    }

    si1182_cleanup(&data);
    fclose(log_file);
    return 0;
