    struct si1182_data data;
    FILE *log_file;
    char timestamp[20];
    uint8_t buffer[6];
    int ret;

    signal(SIGINT, sigint_handler);

    if (si1182_init(&data) < 0) {
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        si1182_cleanup(&data);
        return 1;
    }

    while (1) {
        time_t now;
        struct tm *time_struct;
        char date_str[20];

        time(&now);
        time_struct = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

        if (si1182_read(&data, buffer, 6) < 0) {
            continue;
        }

        sprintf(date_str, "%s", timestamp);
        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", date_str,
                (int)(buffer[0] * 10), (int)(buffer[1] * 10));
        fflush(log_file);

        sleep(1);
    }

    si1182_cleanup(&data);
    fclose(log_file);
    return 0;
}
```

This code initializes the I2C communication with the Si1182 sensor, reads heart rate and SpO2 data, and appends the measurements to a file named "biometric_log.txt". It also handles SIGINT to perform a graceful shutdown. Make sure to install the pigpio library before compiling the code.

To compile the code, use the following command:

```bash
gcc -o biometric_log biometric_log.c -lpigpio -lrt -lgpiod -lrt
```

Run the compiled program with:

```bash
sudo ./biometric_log
```

Don't forget to replace the I2C bus number (0x60) with the correct address of your Si1182 sensor if it differs.

