    if (!chip) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, TILT_SENSOR_1_GPIO);
    line2 = gpiod_chip_get_line(chip, TILT_SENSOR_2_GPIO);
    alarm = gpiod_chip_get_line(chip, ALARM_GPIO);

    if (!gpiod_line_export(line1, "Tilt Sensor 1") ||
        !gpiod_line_export(line2, "Tilt Sensor 2") ||
        !gpiod_line_export(alarm, "Alarm")) {
        fprintf(stderr, "Failed to export GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_set_direction(line1, GPIO_IN);
    gpiod_line_set_pull(line1, GPIO_PULL_DOWN);
    gpiod_line_set_direction(line2, GPIO_IN);
    gpiod_line_set_pull(line2, GPIO_PULL_DOWN);
    gpiod_line_set_direction(alarm, GPIO_OUT);
    gpiod_line_set_value(alarm, 0);

    sensor1.gpio = TILT_SENSOR_1_GPIO;
    sensor2.gpio = TILT_SENSOR_2_GPIO;
    alarm_data.gpio = ALARM_GPIO;

    sensor1.state = LOW;
    sensor2.state = LOW;
    alarm_data.state = OFF;

    while (1) {
        gpiod_line_read(line1, &sensor1.state);
        gpiod_line_read(line2, &sensor2.state);

        if (sensor1.state == HIGH && sensor2.state == HIGH) {
            if (time(NULL) - sensor1.last_state_change > TILT_THRESHOLD_SECONDS) {
                log_event("Tilt-start event");
                gpiod_line_set_value(alarm, 1);
                alarm_data.state = ON;
            }
        } else {
            alarm_data.state = OFF;
            gpiod_line_set_value(alarm, 0);
        }

        sensor1.last_state_change = time(NULL);
        sensor2.last_state_change = time(NULL);

        usleep(100000);
    }

    gpiod_line_set_value(alarm, 0);
    alarm_data.state = OFF;
    fclose(stdout);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

