#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <libgpiod.h>

#define D7S_A0011_ADDR 0x6B
#define RETRY_COUNT 3
#define THRESHOLD 500
#define LED_GPIO 17
#define I2C_BUS 1

struct sensor_data {
    int16_t x, y, z;
};

FILE *log_file = NULL;

void signal_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpiod_unprepare(led_chip);
    libgpiod_drain_all();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    struct gpiod_chip *chip;
    int ret = gpiod_chip_open(&chip, "GPIO17");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO17\n");
        return ret;
    }
    gpiod_chip_set_owner(chip);

    struct sensor_data data;
    int i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    if (i2c_rdwr_ioctl(i2c_fd, 0, NULL, 0, 0) < 0) {
        fprintf(stderr, "Failed to perform I2C rdwr ioctl\n");
        i2c_close(i2c_fd);
        return -1;
    }

    uint8_t addr[2] = {0x6B, 0};
    uint8_t buf[3];
    int retries = RETRY_COUNT;

    while (1) {
        for (int i = 0; i < retries; ++i) {
            if (i2c_rdwr(i2c_fd, addr, 2, buf, 3) < 0) {
                fprintf(stderr, "I2C read/write failed, retrying...\n");
                continue;
            }

            // Process sensor data
            data.x = (int16_t)((buf[0] << 8) | buf[1]);
            data.y = (int16_t)((buf[2] << 8));
            int magnitude = (int)sqrt(data.x * data.x + data.y * data.y);

            if (magnitude > THRESHOLD) {
                if (log_file != NULL) {
                    fprintf(log_file, "%s: Peak vibration magnitude %d\n", 
                                  ctime_r(&time(NULL), &localtime_r), magnitude);
                } else {
                    log_file = fopen("seismic_events.log", "a");
                    if (log_file == NULL) {
                        fprintf(stderr, "Failed to open log file\n");
                        continue;
                    }
                    fprintf(log_file, "%s: Peak vibration magnitude %d\n", 
                                  ctime_r(&time(NULL), &localtime_r), magnitude);
                    fclose(log_file);
                    log_file = fopen("seismic_events.log", "a");
                }

                gpiod_trigger_delay(chip, LED_GPIO, 1000000); // 1 second
            }
        }

        delay(100000); // 100 ms
    }

    gpiod_unprepare(chip);
    i2c_close(i2c_fd);
    return 0;
}

