#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.hpp>

#define SENSOR_PINS {4, 17, 27, 22}
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

int main() {
    gpiod_context ctx;
    gpiod_chip chip;
    gpiod_line *sensor_lines[4];
    gpiod_line *led_line;
    struct timespec poll_timeout;

    if (gpiod_new(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return EXIT_FAILURE;
    }

    if (gpiod_request_lines(ctx, &chip, SENSOR_PINS, LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_free(ctx);
        return EXIT_FAILURE;
    }

    sensor_lines[0] = chip.lines[SENSOR_PINS[0]];
    sensor_lines[1] = chip.lines[SENSOR_PINS[1]];
    sensor_lines[2] = chip.lines[SENSOR_PINS[2]];
    sensor_lines[3] = chip.lines[SENSOR_PINS[3]];
    led_line = chip.lines[LED_PIN];

    if (gpiod_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Failed to set initial LED value\n");
        gpiod_free(ctx);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!sigint_received) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        poll_timeout.tv_sec = now.tv_sec;
        poll_timeout.tv_nsec = now.tv_nsec + (POLL_INTERVAL_MS * 1000000) / 1000;

        for (int i = 0; i < 4; i++) {
            if (gpiod_get_value(sensor_lines[i]) == 0) {
                if (gpiod_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Failed to set LED value\n");
                    gpiod_free(ctx);
                    return EXIT_FAILURE;
                }
                break;
            }
        }

        if (gpiod_poll(ctx, &poll_timeout) < 0) {
            fprintf(stderr, "Failed to poll GPIO lines\n");
            gpiod_free(ctx);
            return EXIT_FAILURE;
        }
    }

    gpiod_free(ctx);

    // Clean up LED line
    if (gpiod_set_value(led_line, 1) < 0) {
        fprintf(stderr, "Failed to set final LED value\n");
    }

    return EXIT_SUCCESS;
}

