code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <syslog.h>
#include <stdatomic.h>
#include <signal.h>

#define NUM_SENSORS 5
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "/var/log/flame_events.log"

enum SensorID { SENSOR_1 = 2, SENSOR_2 = 3, SENSOR_3 = 4, SENSOR_4 = 17, SENSOR_5 = 27 };

volatile sig_atomic_t sigint_received = 0;

static int chip_fds[NUM_SENSORS];
static GPioChip *chips[NUM_SENSORS];
FILE *log_file = NULL;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static void setup_logging() {
    openlog("flame_monitor", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Flame monitor started.");
}

static void teardown_logging() {
    closelog();
    syslog(LOG_INFO, "Flame monitor shutting down.");
}

static void initialize_chip(int sensor_id, GPioChip **chip) {
    int chip_fd = gpiod_chip_open(sensor_id);
    if (chip_fd < 0) {
        syslog(LOG_ERR, "Failed to open chip for sensor %d: %s", sensor_id, strerror(errno));
        exit(EXIT_FAILURE);
    }
    *chip = gpiod_chip_new_from_fd(chip_fd);
    if (!*chip) {
        syslog(LOG_ERR, "Failed to create chip object for sensor %d: %s", sensor_id, strerror(errno));
        close(chip_fd);
        exit(EXIT_FAILURE);
    }
    chip_fds[sensor_id - SENSOR_1] = chip_fd;
}

static int acquire_line(GPioChip *chip, int line, int *line_fd) {
    int ret = gpiod_line_request(chip, line, GPIO_DIR_IN, "flame_sensor");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to acquire line for sensor %d: %s", line, strerror(errno));
        return ret;
    }
    *line_fd = gpiod_line_get_fd(chip, line);
    return 0;
}

static void release_line(int line_fd) {
    gpiod_line_release(line_fd);
    close(line_fd);
}

static int read_line(int line_fd) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint32_t value = 0;
    int ret = read(line_fd, &value, sizeof(value));
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read line for sensor: %s", strerror(errno));
        return ret;
    }
    return value;
}

static void log_flame_event(int sensor_id) {
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(time(NULL)));

    fprintf(log_file, "%s - Sensor %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id - SENSOR_1 + 1, NUM_SENSORS > sensor_id ? sensor_id : 0);
}

static void debounce_read(int line_fd) {
    int value = read_line(line_fd);
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint32_t last_value = value;
    while ((value = read_line(line_fd)) == 0 && (uint32_t)(ts.tv_sec - last_value_ts.tv_sec) < DEBOUNCE_DELAY_MS / 1000000) {
        usleep(1000);
        clock_gettime(CLOCK_MONOTONIC, &ts);
    }
    last_value = value;
    last_value_ts = ts;
}

int main(int argc, char *argv[]) {
    setup_logging();
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

