#define POLL_INTERVAL_MS 50

struct gpiod_chip *chip;
struct gpiod_line *lines[TTP226_ARRAY_LEN];
int previous_states[TTP226_ARRAY_LEN] = {0};

void log_state_change(int index, int state) {
    time_t now = time(NULL);
    printf("%04d-%02d-%02dT%02d:%02d:%02d,%d, GPIO%d: %s\n",
           1900 + (now / 31536000),
           (now / 86400) % 12, (now / 31) % 30,
           (now / 24) % 60, (now / 60) % 60, (now % 60),
           TTP226_PINS[index], state ? "TOUCHED" : "RELEASED");
}

void init_gpio() {
    int r;

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    r = gpiod_chip_set_owner(chip);
    if (r < 0) {
        fprintf(stderr, "Failed to set GPIO chip owner: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < TTP226_ARRAY_LEN; i++) {
        lines[i] = gpiod_line_alloc(chip, TTP226_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to allocate line for GPIO%d: %s\n", TTP226_PINS[i], strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        r = gpiod_line_request_add(lines[i], "user");
        if (r < 0) {
            fprintf(stderr, "Failed to request line GPIO%d: %s\n", TTP226_PINS[i], strerror(errno));
            gpiod_line_free(lines[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }
}

void poll_touch_sensors() {
    int r;
    struct gpiod_bulk_line_state state;

    while (1) {
        for (int i = 0; i < TTP226_ARRAY_LEN; i++) {
            r = gpiod_bulk_read(lines[i], &state, 1);
            if (r < 0) {
                fprintf(stderr, "Failed to read line GPIO%d: %s\n", TTP226_PINS[i], strerror(errno));
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }

            if (state.value[0] && !previous_states[i]) {
                log_state_change(i, 1);
                previous_states[i] = 1;
            } else if (!state.value[0] && previous_states[i]) {
                log_state_change(i, 0);
                previous_states[i] = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }
}

void handle_sigint(int signum) {
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_gpio();
    poll_touch_sensors();

    return 0;
}

