#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define LED_GPIO 18
#define I2C_BUS 1
#define SAMPLE_INTERVAL 1
#define PWM_FREQ 1000
#define PWM_RANGE 100

struct pwm_info {
    int fd;
    int chip;
    int pwm;
    int duty_cycle;
};

struct sensor_data {
    int16_t lux;
    int brightness;
};

static int i2c_open(const char *bus, int *fd) {
    *fd = open("/dev/i2c-1", O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

static void i2c_close(int fd) {
    close(fd);
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("Failed to write to I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_RDWR, &len) != len) {
        perror("Failed to perform I2C transaction");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return 0;
}

static int veml7700_read(int fd, struct sensor_data *data) {
    uint8_t buf[2];
    buf[0] = 0x0F; // Start condition
    buf[1] = 0x00; // Register address

    if (i2c_read(fd, buf, 2) < 0)
        return -1;

    data->lux = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int pwm_init(struct pwm_info *pwm) {
    pwm->fd = open("/dev/gpiod/gpio18", O_RDWR);
    if (pwm->fd < 0) {
        perror("Failed to open GPIO");
        return -1;
    }

    gpiod_chip_config chip_cfg = {
        .gid = 0,
        .direction = GPIO_DIR_OUT,
        .sense = GPIO_FALLING_EDGE,
    };

    int ret = gpiod_chip_apply_config(pwm->fd, &chip_cfg);
    if (ret < 0) {
        perror("Failed to configure GPIO");
        close(pwm->fd);
        return -1;
    }

    pwm->pwm = gpiod_chip_get_line(pwm->fd);
    pwm->duty_cycle = 0;

    return 0;
}

static void pwm_write(struct pwm_info *pwm) {
    gpiod_line_set_value(pwm->pwm, pwm->duty_cycle);
}

static void pwm_cleanup(struct pwm_info *pwm) {
    gpiod_line_release(pwm->pwm);
    close(pwm->fd);
}

static void log_data(const char *filename, const struct sensor_data *data) {
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));

    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, Lux: %d, Brightness: %d\n", timestamp, data->lux, data->brightness);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    struct pwm_info pwm;
    struct sensor_data sensor;

    if (i2c_open("/dev/i2c-1", &i2c_fd) < 0)
        return 1;

    if (pwm_init(&pwm) < 0) {
        i2c_close(i2c_fd);
        return 1;
    }

    while (1) {
        if (veml7700_read(i2c_fd, &sensor) < 0) {
            fprintf(stderr, "Failed to read from VEML7700\n");
            break;
        }

        int brightness = 0;
        if (sensor.lux < 100)
            brightness = PWM_RANGE;
        else if (sensor.lux < 500)
            brightness = PWM_RANGE * 75 / 100;
        else if (sensor.lux < 1000)
            brightness = PWM_RANGE * 50 / 100;
        else
            brightness = PWM_RANGE * 25 / 100;

        pwm_write(&pwm);
        log_data("grow_log.txt", &sensor);

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    pwm_cleanup(&pwm);
    i2c_close(i2c_fd);

    return 0;
}

