#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LED_GPIO 17
#define SENSOR_PINS {2, 3, 4, 5, 12, 16, 20, 21}
#define SENSOR_PIN_COUNT (sizeof(SENSOR_PINS) / sizeof(SENSOR_PINS[0]))

struct sensor_data {
    int touched;
    unsigned long last_touch_time;
};

static int sensor_init(struct sensor_data *sensor_data, int num_channels) {
    for (int i = 0; i < num_channels; i++) {
        char path[32];
        snprintf(path, sizeof(path), "GPIO%d", SENSOR_PINS[i]);
        int ret = gpiod_in(path, &sensor_data[i].line);
        if (ret < 0) {
            fprintf(stderr, "Failed to initialize GPIO %d\n", SENSOR_PINS[i]);
            return ret;
        }
        sensor_data[i].touched = 0;
        sensor_data[i].last_touch_time = 0;
        gpiod_add_edge_event(sensor_data[i].line, true, -1, -1, sensor_callback, &sensor_data[i]);
    }
    return 0;
}

static void sensor_callback(const struct gi18n_context *ctx, struct gpiod_line *line, uint64_t events, void *user_data) {
    struct sensor_data *sensor_data = user_data;
    if (events & GPIO_EVENT_FALLING_EDGE) {
        sensor_data->touched = 1;
        sensor_data->last_touch_time = time(NULL);
    }
}

static void log_touch_event(const struct sensor_data *sensor_data, int channel_num) {
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(time(NULL)));
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open touch_log.txt for writing\n");
        return;
    }
    fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel_num);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    struct sensor_data sensor_data[NUM_CHANNELS];
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
