#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x00
#define SAMPLE_REG 0x01
#define DATA_REG 0x02
#define I2C_BUS "i2c-1"
#define LOG_FILE "light_data.txt"
#define DELAY_MS 100
#define SAMPLE_INTERVAL_MS 1000

static struct i2c *bus;
static struct i2c_client *client;
static uint16_t config, sample, data;

static int log_file_opened = 0;
static FILE *log_fp = NULL;

void sigint_handler(int signum) {
    if (log_fp) {
        fclose(log_fp);
        log_file_opened = 0;
    }
    gpiod_unreg_device(gpio);
    i2c_free_client(client);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    bus = i2c_open(I2C_BUS);
    if (!bus) {
        fprintf(stderr, "Failed to open I2C bus %s\n", I2C_BUS);
        return 1;
    }

    client = i2c_new_device(bus, OPT3001_ADDR);
    if (!client) {
        i2c_close(bus);
        return 1;
    }

    gpio = gpiod_in_extract(gpiod_get_controller(0), "opt3001-cs", "opt3001-cs");
    if (!gpio) {
        i2c_free_client(client);
        i2c_close(bus);
        return 1;
    }
    gpiod_export(gpio);
    gpiod_set_value(gpio, 1);

    if (i2c_slave_address_width(client) != 7) {
        i2c_free_client(client);
        i2c_close(bus);
        gpiod_unexport(gpio);
        return 1;
    }

    config = 0x06; // Set to 16-bit mode, 1x sampling rate
    if (i2c_write_byte_data(client, CONFIG_REG, config)) {
        fprintf(stderr, "Failed to write configuration register\n");
        i2c_free_client(client);
        i2c_close(bus);
        gpiod_unexport(gpio);
        return 1;
    }
    usleep(DELAY_MS * 1000);

    while (1) {
        if (!log_file_opened) {
            log_fp = fopen(LOG_FILE, "w");
            if (!log_fp) {
                fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
                i2c_free_client(client);
                i2c_close(bus);
                gpiod_unexport(gpio);
                return 1;
            }
            log_file_opened = 1;
        }

        sample = 0;
        if (i2c_write_byte_data(client, SAMPLE_REG, 0)) {
            fprintf(stderr, "Failed to write sample register\n");
            sleep(SAMPLE_INTERVAL_MS / 1000);
            continue;
        }
        usleep(DELAY_MS * 1000);

        if (i2c_read_word_data(client, DATA_REG, &data)) {
            fprintf(stderr, "Failed to read data register\n");
            sleep(SAMPLE_INTERVAL_MS / 1000);
            continue;
        }

        // Byte swap from little-endian to big-endian
        data = (data >> 8) | ((data & 0x00FF) << 8);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_fp, "%s, %.2f\n", timestamp, (double)data / 4096.0);
        printf("%s, %.2f\n", timestamp, (double)data / 4096.0);

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    fclose(log_fp);
    i2c_free_client(client);
    i2c_close(bus);
    gpiod_unexport(gpio);

    return 0;
}

