#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define TOUCH_PIN 4
#define DEBOUNCE_INTERVAL (50 * 1000 / 10) // 50 ms

static volatile sig_atomic_t sigint_received = 0;

static void signal_handler(int signum) {
    sigint_received = signum;
}

static int touch_state = 0;
static FILE *log_file = NULL;

static void init_gpio() {
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_create_from_device("/dev/gpiochip0", "GPIO%d", TOUCH_PIN,
        GPIOD_IN | GPIOD_ACTIVE_LOW, &touch_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d\n", TOUCH_PIN);
        gpiod_exit(ret);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_value(touch_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO%d value to 0\n", TOUCH_PIN);
        gpiod_request_free(touch_line);
        gpiod_exit(ret);
        exit(EXIT_FAILURE);
    }
}

static void cleanup_gpio() {
    gpiod_request_free(touch_line);
    gpiod_exit(0);
}

static void touch_callback(const struct gi18n *category,
        const struct gi18n_msg *msg, int arg) {
    if (arg) {
        touch_state = 1;
        fprintf(log_file, "%s: Touch Detected\n", time_str);
        fflush(log_file);
    } else {
        touch_state = 0;
        fprintf(log_file, "%s: Touch Released\n", time_str);
        fflush(log_file);
    }
}

int main() {
    struct timespec ts;
    char time_str[32];
    sigset_t sigset;

    init_gpio();

    if (!(log_file = fopen("touch_log.txt", "a"))) {
        fprintf(stderr, "Failed to open touch_log.txt\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    if (sigint_received) {
        cleanup_gpio();
        fclose(log_file);
        return 0;
    }

    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &sigset, NULL) == -1) {
        perror("sigprocmask");
        cleanup_gpio();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpiod_add_callback(touch_line, GPIOD_CALLBACK_FALLING | GPIOD_CALLBACK_RISING,
            touch_callback, NULL);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec - time_sec >= DEBOUNCE_INTERVAL / 1000) {
            time_sec = ts.tv_sec;
            if (touch_state) {
                touch_callback(NULL, 0);
            }
        }
        usleep(DEBOUNCE_INTERVAL - (ts.tv_sec - time_sec) * 1000000);
    }

    cleanup_gpio();
    fclose(log_file);
    return 0;
}

