}

int main() {
    struct timespec ts;
    char time_str[32];
    sigset_t sigset;

    init_gpio();

    if (!(log_file = fopen("touch_log.txt", "a"))) {
        fprintf(stderr, "Failed to open touch_log.txt\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    if (sigint_received) {
        cleanup_gpio();
        fclose(log_file);
        return 0;
    }

    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &sigset, NULL) == -1) {
        perror("sigprocmask");
        cleanup_gpio();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpiod_add_callback(touch_line, GPIOD_CALLBACK_FALLING | GPIOD_CALLBACK_RISING,
            touch_callback, NULL);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec - time_sec >= DEBOUNCE_INTERVAL / 1000) {
            time_sec = ts.tv_sec;
            if (touch_state) {
                touch_callback(NULL, 0);
            }
        }
        usleep(DEBOUNCE_INTERVAL - (ts.tv_sec - time_sec) * 1000000);
    }

    cleanup_gpio();
    fclose(log_file);
    return 0;
}
```

This code initializes the GPIO pin as an input with a pull-down bias, sets up a callback function for detecting both rising and falling edges (touch press and release), and continuously polls the pin with a debounce interval of approximately 50 ms. It appends log entries to `touch_log.txt` and handles SIGINT and SIGTERM signals by cleaning up resources and exiting gracefully.

