void log_entry(double flow_rate, unsigned int flags) {
    static int header_written = 0;
    char status[20];

    if (flow_rate == INVALID) {
        status[0] = 'E';
        status[1] = '\0';
    } else {
        sprintf(status, "VALID");
    }

    if (!header_written) {
        csv_file = fopen(filename, "w");
        if (!csv_file) {
            perror("Failed to open CSV file");
            exit(EXIT_FAILURE);
        }
        fprintf(csv_file, "Timestamp,Flow Rate (ml/min),Status,Flags\n");
        header_written = 1;
    }

