    struct tm *time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(csv_file, "%s,%.3f,%s,%u\n", timestamp, flow_rate, status, flags);
    fflush(csv_file);
}

unsigned int calculate_crc(unsigned short *data, int len) {
    unsigned int crc = CRC_INIT_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc >>= 1;
                crc ^= CRC_POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int main() {
    int ret;
    char i2c_path[32];
    sprintf(i2c_path, "/dev/i2c-1");

    i2c_fd = open(i2c_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    ioctl(i2c_fd, I2C_SLAVE, SENSIRON_I2C_ADDR);

    rdwr_data.ifs = I2C_M_RD;
    rdwr_data.len = 3;
    rdwr_data.addr = SENSIRON_I2C_ADDR;
    rdwr_data.data = (unsigned char *)malloc(rdwr_data.len);

    ret = ioctl(i2c_fd, I2C_MASTER_TX_DATA, &rdwr_data);
    if (ret < 0) {
        perror("Failed to issue sensor command");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    usleep(2000);

    while (1) {
        ret = ioctl(i2c_fd, I2C_MASTER_RX_DATA, &rdwr_data);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        unsigned short flow_value = (rdwr_data.data[0] << 8) | rdwr_data.data[1];
        unsigned char crc = rdwr_data.data[2];

        if (crc != calculate_crc((unsigned short *)&flow_value, 2)) {
            fprintf(stderr, "CRC error\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        double flow_rate = flow_value * 0.0254; // Convert from LPM to mL/min
        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            log_entry(INVALID, 0);
            continue;
        }

        log_entry(flow_rate, 0);
    }

    fclose(csv_file);
    free(rdwr_data.data);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

