#define LEFT_GPIO 17
#define MIDDLE_GPIO 27
#define RIGHT_GPIO 22
#define SAMPLE_INTERVAL 50000 // 50 ms
#define LOG_FILE "path_log.csv"

struct sensor_data {
    time_t timestamp;
    int left;
    int middle;
    int right;
};

FILE *log_file = NULL;

void cleanup(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpio_close();
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpiochip_handle_t chip;
    if (gpiochip_open(&chip) < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiochip_request_available(chip, LEFT_GPIO) < 0 ||
        gpiochip_request_available(chip, MIDDLE_GPIO) < 0 ||
        gpiochip_request_available(chip, RIGHT_GPIO) < 0) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpio_direction_input(chip, LEFT_GPIO) < 0 ||
        gpio_direction_input(chip, MIDDLE_GPIO) < 0 ||
        gpio_direction_input(chip, RIGHT_GPIO) < 0) {
        fprintf(stderr, "Failed to set GPIO pins as input\n");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,left,middle,right\n");

    while (1) {
        struct sensor_data data;
        data.timestamp = time(NULL);

        data.left = gpio_get(chip, LEFT_GPIO);
        data.middle = gpio_get(chip, MIDDLE_GPIO);
        data.right = gpio_get(chip, RIGHT_GPIO);

        char timestamp_str[22];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", localtime(&data.timestamp));

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, data.left, data.middle, data.right);

        sleep(SAMPLE_INTERVAL / 1000);
    }

    gpiochip_close(chip);
    fclose(log_file);
    return EXIT_SUCCESS;
}

