#define FLAME_SENSOR_GPIO 4
#define FLAME_SENSOR_FALLING_EDGE 1

static int flame_detected = 0;
static FILE *flame_events_file = NULL;

static void log_event(const char *event) {
    time_t now;
    struct tm *time_struct;
    char timestamp[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_struct);

    fprintf(stdout, "%s: %s\n", timestamp, event);
    if (flame_events_file != NULL) {
        fputs(timestamp, flame_events_file);
        fputs(" Flame detected\n", flame_events_file);
        fputc('\n', flame_events_file);
    }
}

static void cleanup(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Program terminated by user");
        if (flame_events_file != NULL) {
            fclose(flame_events_file);
            flame_events_file = NULL;
        }
        gpiod_unprepare(chip);
        exit(0);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int r;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO bus\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get line %d\n", FLAME_SENSOR_GPIO);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_add(line, "input", FLAME_SENSOR_FALLING_EDGE) < 0) {
        fprintf(stderr, "Failed to request line %d\n", FLAME_SENSOR_GPIO);
        gpiod_chip_close(chip);
        return 1;
    }

    flame_events_file = fopen("flame_events.txt", "a");
    if (!flame_events_file) {
        fprintf(stderr, "Failed to open flame_events.txt\n");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        r = gpiod_line_read(line);
        if (r < 0) {
            fprintf(stderr, "Failed to read line %d, error: %d\n", FLAME_SENSOR_GPIO, r);
            break;
        }

        if ((r & FLAME_SENSOR_FALLING_EDGE) && !flame_detected) {
            log_event("Flame detected");
            flame_detected = 1;
        } else if (!(r & FLAME_SENSOR_FALLING_EDGE)) {
            flame_detected = 0;
        }
    }

    gpiod_line_drain(line);
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

