#define LED_GPIO 24
#define TOUCH_GPIO 23
#define CHIP_NUMBER 4
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT 1

bool led_state = false;

void log_touch_event(const char *timestamp, bool new_state) {
    time_t now;
    struct tm *time_struct;
    char buffer[20];

    time(&now);
    time_struct = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", time_struct);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Unable to open log file '%s'\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    if (new_state) {
        fprintf(log_file, "[NEW] %s LED ON\n", buffer);
    } else {
        fprintf(log_file, "[OLD] %s LED OFF\n", buffer);
    }

    fclose(log_file);
}

void toggle_led() {
    led_state = !led_state;

    if (led_state) {
        printf("LED ON\n");
        log_touch_event(asctime(localtime(&now)), true);
    } else {
        printf("LED OFF\n");
        log_touch_event(asctime(localtime(&now)), false);
    }
}

void cleanup() {
    gpiod_unrequest_all(chip);
    close(fd);
}

int main() {
    struct gpiod_chip *chip;
    int fd;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(CHIP_NUMBER, NULL);
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip %d\n", CHIP_NUMBER);
        return EXIT_FAILURE;
    }

    fd = gpiod_chip_fd(chip);
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to get file descriptor for GPIO chip %d\n", CHIP_NUMBER);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!line) {
        fprintf(stderr, "Error: Unable to get touch sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_line(line, "input") < 0) {
        fprintf(stderr, "Error: Unable to request touch sensor line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!line) {
        fprintf(stderr, "Error: Unable to get LED line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_line(line, "output") < 0) {
        fprintf(stderr, "Error: Unable to request LED line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    gpiod_line_set_value(line, 0);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (true) {
        ret = gpiod_poll(fd, POLL_TIMEOUT, line);
        if (ret < 0) {
            fprintf(stderr, "Error: gpiod_poll failed\n");
            break;
        }

        if (gpiod_line_get_value(line)) {
            toggle_led();
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}
