        return ret;
    }

    ret = gpiod_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set initial buzzer value: %s\n", strerror(errno));
        return ret;
    }

    return 0;
}

static void cleanup_gpio() {
    gpiod_unexport(chip);
    fclose(log_file);
}

static void log_flame_detection(const char *timestamp) {
    fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
    fflush(log_file);
