#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define LED_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_MS 10

struct debounce_state {
    bool last_state;
    bool current_state;
    time_t last_toggle;
};

static int setup_gpio(struct gpiod_chip *chip, struct debounce_state *debounce_state) {
    int ret;

    ret = gpiod_chip_find("gpio");
    if (ret < 0) {
        fprintf(stderr, "Failed to find GPIO chip\n");
        return ret;
    }

    chip = gpiod_chip_get(ret);
    if (!chip) {
        fprintf(stderr, "Failed to get GPIO chip\n");
        return -1;
    }

    debounce_state->last_state = false;
    debounce_state->current_state = false;
    debounce_state->last_toggle = 0;

    ret = gpiod_chip_export(chip, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO chip\n");
        return ret;
    }

    gpiod_chip_get_line(chip, SENSOR_GPIO, &debounce_state->sensor_line);
    gpiod_chip_get_line(chip, LED_GPIO, &debounce_state->led_line);

    if (gpiod_line_request_get(debounce_state->sensor_line, "input") < 0) {
        fprintf(stderr, "Failed to request input on sensor line\n");
        return -1;
    }

    if (gpiod_line_request_get(debounce_state->led_line, "output") < 0) {
        fprintf(stderr, "Failed to request output on LED line\n");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct debounce_state *debounce_state) {
    gpiod_line_release(debounce_state->sensor_line);
    gpiod_line_release(debounce_state->led_line);
    gpiod_chip_unexport(chip);
}

static int handle_touch(struct gpiod_chip *chip, struct debounce_state *debounce_state) {
    time_t now;
    struct tm *time_info;
    char timestamp[64];

    now = time(NULL);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

    if (debounce_state->current_state &&
        (time(NULL) - debounce_state->last_toggle) > DEBOUNCE_MS) {
        FILE *log_file = fopen("touch_log.txt", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }

        if (fputs(timestamp, log_file) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        } else {
            fputc('\n', log_file);
        }

        fclose(log_file);
    }

    debounce_state->last_state = debounce_state->current_state;
    debounce_state->current_state = gpiod_line_get_value(debounce_state->sensor_line);
    debounce_state->last_toggle = time(NULL);

    return 0;
}

static int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct debounce_state debounce_state;
    int ret;

    ret = setup_gpio(chip, &debounce_state);
    if (ret < 0) {
        return ret;
    }

    gpiod_line_set_value(debounce_state.led_line, 0);

    while (1) {
        ret = gpiod_line_get_value_cb(debounce_state.sensor_line, &debounce_state.current_state,
                                      handle_touch, &debounce_state);
        if (ret < 0) {
            fprintf(stderr, "Failed to get sensor value\n");
            break;
        }

        if (debounce_state.current_state) {
            gpiod_line_set_value(debounce_state.led_line, 1);
        } else {
            gpiod_line_set_value(debounce_state.led_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(chip, &debounce_state);
    return 0;
}

