#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27
#define LOG_FILE "magnet_log.txt"

void sigint_handler(int signum) {
    gpio_stop();
    printf("Received SIGINT, cleaning up...\n");
    fclose(log_file);
}

void sigterm_handler(int signum) {
    gpio_stop();
    printf("Received SIGTERM, cleaning up...\n");
    fclose(log_file);
    exit(0);
}

int main() {
    gpio_context ctx;
    int ret;
    FILE *log_file;

    // Initialize GPIO
    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return ret;
    }

    // Set up GPIO pins
    ret = gpio_request_available(&ctx, SENSOR_1_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d\n", SENSOR_1_GPIO);
        gpio_exit();
        return ret;
    }
    ret = gpio_set_fd_input(&ctx, SENSOR_1_GPIO, GPIOD_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure GPIO %d as input with pull-up\n", SENSOR_1_GPIO);
        gpio_release(&ctx, SENSOR_1_GPIO);
        gpio_exit();
        return ret;
    }

    ret = gpio_request_available(&ctx, SENSOR_2_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d\n", SENSOR_2_GPIO);
        gpio_release(&ctx, SENSOR_1_GPIO);
        gpio_exit();
        return ret;
    }
    ret = gpio_set_fd_input(&ctx, SENSOR_2_GPIO, GPIOD_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure GPIO %d as input with pull-up\n", SENSOR_2_GPIO);
        gpio_release(&ctx, SENSOR_2_GPIO);
        gpio_exit();
        return ret;
    }

    ret = gpio_request_available(&ctx, SENSOR_3_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d\n", SENSOR_3_GPIO);
        gpio_release(&ctx, SENSOR_1_GPIO);
        gpio_release(&ctx, SENSOR_2_GPIO);
        gpio_exit();
        return ret;
    }
    ret = gpio_set_fd_input(&ctx, SENSOR_3_GPIO, GPIOD_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure GPIO %d as input with pull-up\n", SENSOR_3_GPIO);
        gpio_release(&ctx, SENSOR_3_GPIO);
        gpio_exit();
        return ret;
    }

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpio_exit();
        return -1;
    }

    // Read initial states
    uint32_t sensor_states = 0;
    uint32_t prev_states = 0;
    uint32_t sensor_mask = (1 << SENSOR_1_GPIO) | (1 << SENSOR_2_GPIO) | (1 << SENSOR_3_GPIO);

    // Read initial states without generating false transitions
    prev_states = gpio_get_value(&ctx, sensor_mask);

    while (1) {
        // Read current states
        sensor_states = gpio_get_value(&ctx, sensor_mask);

        // Check for state changes
        if ((sensor_states & sensor_mask) != prev_states) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

            // Log state changes
            fprintf(log_file, "%s: ", timestamp);
            if (sensor_states & (1 << SENSOR_1_GPIO)) {
                fprintf(log_file, "Sensor 1: Magnet present\n");
            } else {
                fprintf(log_file, "Sensor 1: Magnet removed\n");
            }

            if (sensor_states & (1 << SENSOR_2_GPIO)) {
                fprintf(log_file, "Sensor 2: Magnet present\n");
            } else {
                fprintf(log_file, "Sensor 2: Magnet removed\n");
            }

            if (sensor_states & (1 << SENSOR_3_GPIO)) {
                fprintf(log_file, "Sensor 3: Magnet present\n");
            } else {
                fprintf(log_file, "Sensor 3: Magnet removed\n");
            }
            fflush(log_file);
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    gpio_exit();
    fclose(log_file);
    return 0;
}

