#define PART_ID 0x1234
#define HW_REV 0x5678
#define MOVING_AVG_SIZE 5

struct sensor_data {
    unsigned int bpm;
    unsigned int count;
};

static struct i2c_client *si1182_i2c;
static struct gpiod_chip *gpio;

static int si1182_read_reg(struct i2c_client *client, uint8_t reg_addr, uint8_t *data, size_t len) {
    if (I2C_INTF(client)->adapter->flags & I2C_ADPT_FLAGS_MMASTER) {
        return i2c_smbus_read_i2c_block_data(I2C_INTF(client)->adapter, SENSOR_ADDR, reg_addr, len, data);
    }
    return -EINVAL;
}

static int si1182_write_reg(struct i2c_client *client, uint8_t reg_addr, const uint8_t *data, size_t len) {
    if (I2C_INTF(client)->adapter->flags & I2C_ADPT_FLAGS_MMASTER) {
        return i2c_smbus_write_i2c_block_data(I2C_INTF(client)->adapter, SENSOR_ADDR, reg_addr, len, data);
    }
    return -EINVAL;
}

static int check_sensor_id(struct i2c_client *client) {
    uint8_t part_id, hw_rev;
    if (si1182_read_reg(client, 0x0A, &part_id, 1) < 0 ||
        si1182_read_reg(client, 0x0B, &hw_rev, 1) < 0) {
        return -1;
    }
    if (part_id != PART_ID || hw_rev != HW_REV) {
        return -EINVAL;
    }
    return 0;
}

static int moving_avg_filter(struct sensor_data *data, unsigned int new_bpm) {
    data->bpm = (data->bpm * MOVING_AVG_SIZE - data->count + new_bpm) / MOVING_AVG_SIZE;
    data->count = new_bpm;
    return 0;
}

static int validate_bpm(unsigned int bpm) {
    return (bpm >= 30 && bpm <= 220);
}

static void log_heart_rate(const char *format, ...) {
    static FILE *log_file = NULL;
    va_list args;
    va_start(args, format);
    if (log_file == NULL) {
        log_file = fopen("heart_rate.csv", "a");
        if (!log_file) {
            perror("Failed to open log file");
            va_end(args);
            return;
        }
    }
    vfprintf(log_file, format, args);
    fflush(log_file);
    va_end(args);
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    gpio = gpiod_chip_new("si1182-gpio", "GPIO pins for Si1182");
    if (!gpio) {
        perror("Failed to create GPIO chip");
        return 1;
    }

    if (gpiod_chip_add_lines(gpio, &si1182_i2c_lines, 1) < 0) {
        perror("Failed to add I2C lines to GPIO chip");
        gpiod_chip_free(gpio);
        return 1;
    }

    if (gpiod_chip_enable_output(gpio, 0) < 0) {
        perror("Failed to enable I2C output");
        gpiod_chip_free(gpio);
        return 1;
    }

    if (i2c_client_register(&si1182_i2c, "si1182", 0, NULL, NULL, I2C_ADPT_DEV(i2c_dev_get_default())) < 0) {
        perror("Failed to register I2C client");
        gpiod_chip_free(gpio);
        return 1;
    }

    if (check_sensor_id(si1182_i2c) < 0) {
        fprintf(stderr, "Invalid sensor ID, aborting.\n");
        gpiod_chip_free(gpio);
        i2c_client_unregister(si1182_i2c);
        return 1;
    }

    struct sensor_data sensor_data = {0};
    for (;;) {
        if (si1182_read_reg(si1182_i2c, 0x28, &sensor_data.raw_bpm, 2) < 0) {
            fprintf(stderr, "Failed to read raw BPM, retrying...\n");
            continue;
        }
        sensor_data.bpm = ntohs(sensor_data.raw_bpm);

        if (sensor_data.count == 0) {
            fprintf(stderr, "No valid data, retrying...\n");
            continue;
        }

        moving_avg_filter(&sensor_data, sensor_data.bpm);

        if (validate_bpm(sensor_data.bpm)) {
            log_heart_rate("%s,%u\n", time_str, sensor_data.bpm);
        } else {
            fprintf(stderr, "Invalid BPM value, ignoring...\n");
        }

        sensor_data.count = 0;

        clock_nanosleep(CLOCK_MONOTONIC, 0, 1000000000 / 1, NULL);
    }

    gpiod_chip_free(gpio);
    i2c_client_unregister(si1182_i2c);
    fclose(log_file);

    return 0;
}

