#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define FLAME_SENSOR_GPIO 17
#define POLL_INTERVAL_MS 100
#define LOG_FILE "flame_log.txt"

volatile bool last_state = false;

void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    gpio_stop_output(FLAME_SENSOR_GPIO);
    gpio_close();
    fclose(log_file);
    exit(0);
}

void setup_gpio() {
    struct gpio_chip *chip = gpio_get_chip(0);
    if (!chip) {
        fprintf(stderr, "Failed to get GPIO chip\n");
        exit(1);
    }

    if (gpio_chip_open(chip, GPIOF_OUT_LOW) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    if (gpio_pin_take(chip, FLAME_SENSOR_GPIO) < 0) {
        fprintf(stderr, "Failed to take GPIO pin %d\n", FLAME_SENSOR_GPIO);
        exit(1);
    }

    if (gpio_pin_set_config(chip, FLAME_SENSOR_GPIO, GPIO_PIN_INPUT | GPIO_PIN_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d configuration\n", FLAME_SENSOR_GPIO);
        exit(1);
    }
}

void setup_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(1);
    }
}

void poll_flame_sensor() {
    struct timespec poll_ts;
    poll_ts.tv_sec = 0;
    poll_ts.tv_nsec = POLL_INTERVAL_MS * 1000000 / 2;

    while (true) {
        bool current_state = gpio_pin_get(FLAME_SENSOR_GPIO);

        if (current_state != last_state) {
            last_state = current_state;

            if (current_state == false && !last_state) {
                time_t now = time(NULL);
                fprintf(log_file, "%ld FLAME DETECTED\n", now);
                fflush(log_file);
                printf("FLAME DETECTED\n");
            }
        }

        nanosleep(&poll_ts, NULL);
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_gpio();
    setup_log_file();

    poll_flame_sensor();

    gpio_stop_output(FLAME_SENSOR_GPIO);
    gpio_close();
    fclose(log_file);

    return 0;
}

