#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define OUTPUT_PINS {17, 18, 19, 20, 21, 22, 23, 24}
#define OUTPUT_BITS {0, 1, 4, 8, 16, 32, 64, 128}

struct touch_data {
    int channel;
    int counter;
};

static int touch_callback(struct gpiod_chip *chip, struct gpiod_line *line, uint gpiod_line_flags) {
    struct touch_data data;
    data.channel = line->line_num - 5;

    if (gpiod_line_get_value(line)) {
        data.counter = (data.counter + 1) % 256;
        update_output_pins(data.counter);
        log_event(data);
    }

    return 0;
}

static void update_output_pins(int counter) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = OUTPUT_PINS[i];
        int bit = OUTPUT_BITS[i];

        gpiod_line_set_value(gpiochip, pin, (counter & bit) ? 1 : 0);
    }
}

static void log_event(struct touch_data data) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%T%z", gmtime(&now));

    FILE *log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file. Continuing with stdout output.\n");
        return;
    }

    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, data.channel + 1, data.counter);
    fprintf(log_file, "Touch on channel %d | Counter: %d\n", data.channel + 1, data.counter);
    fclose(log_file);

    printf("Touch on channel %d | Counter: %d\n", data.channel + 1, data.counter);
}

int main() {
    struct gpiod_chip *gpiochip;
    int ret;

    gpiochip = gpiod_chip_open(0, "TTP226_Sensor");
    if (!gpiochip) {
        fprintf(stderr, "Error: Failed to open GPIO chip. Exiting.\n");
        return 1;
    }

    ret = gpiod_chip_add_listener(gpiochip, &line_listener, touch_callback);
    if (ret) {
        fprintf(stderr, "Error: Failed to add line listener. Exiting.\n");
        gpiod_chip_free(gpiochip);
        return 1;
    }

    // Configure sensor lines as input
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = 5 + i;
        ret = gpiod_line_request_add(gpiochip, &line, gpiod_line_flags_input);
        if (ret) {
            fprintf(stderr, "Error: Failed to request input line %d. Exiting.\n", pin);
            gpiod_chip_free(gpiochip);
            return 1;
        }
    }

    // Configure output pins
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = OUTPUT_PINS[i];
        ret = gpiod_line_request_add(gpiochip, &line, 0);
        if (ret) {
            fprintf(stderr, "Error: Failed to request output line %d. Exiting.\n", pin);
            gpiod_chip_free(gpiochip);
            return 1;
        }
        gpiod_line_set_direction(line, GPIO_DIR_OUT);
    }

    // Wait for stabilization
    sleep(2);

    // Start polling
    while (1) {
        gpiod_batch_process(gpiochip, 10 * MS_TO_NC());
        usleep(10 * NC_TO_US);
    }

    // Clean up
    gpiod_chip_free(gpiochip);
    return 0;
}

