gpio_context *g_gpio_ctx;
FILE *g_csv_file = NULL;

void sigint_handler(int signum) {
    gpio_free(g_gpio_ctx);
    if (g_csv_file != NULL) {
        fclose(g_csv_file);
    }
    exit(0);
}

void init_gpio() {
    g_gpio_ctx = gpio_init();
    if (g_gpio_ctx == NULL) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }

    const int sensor_pins[] = {17, 18, 27, 22};
    for (int i = 0; i < SENSOR_PINS; i++) {
        int rc = gpio_request(g_gpio_ctx, sensor_pins[i], GPIO_DIR_IN, "KY-033 Sensor");
        if (rc < 0) {
            fprintf(stderr, "Failed to request GPIO %d\n", sensor_pins[i]);
            gpio_free(g_gpio_ctx);
            exit(1);
        }
        gpio_set_value(g_gpio_ctx, sensor_pins[i], 1);
    }
}

void write_to_csv(const char *timestamp, const int *sensor_values) {
    if (g_csv_file == NULL) {
        g_csv_file = fopen("tracking_log.csv", "w");
        if (g_csv_file == NULL) {
            fprintf(stderr, "Failed to open tracking_log.csv for writing\n");
            exit(1);
        }
        fprintf(g_csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    char timestamp_str[64];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));

    fprintf(g_csv_file, "%s,%d,%d,%d,%d\n", timestamp_str, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3]);

    fflush(g_csv_file);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_gpio();

    int sensor_values[SENSOR_PINS] = {0};
    while (1) {
        for (int i = 0; i < SENSOR_PINS; i++) {
            int rc = gpio_get_value(g_gpio_ctx, i, &sensor_values[i]);
            if (rc < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", i);
                continue;
            }
        }

        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));

        write_to_csv(timestamp, sensor_values);

        sleep(POLL_INTERVAL_MS / 1000);
    }

    gpio_free(g_gpio_ctx);
    fclose(g_csv_file);

    return 0;
}

