#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define DEBOUNCE_WINDOW_MS 50
#define POLL_INTERVAL_MS 100

#define GPIO17 17
#define GPIO18 18

struct sensor_data {
    int gpio;
    int state;
    time_t last_state_change;
};

void signal_handler(int signum) {
    printf("Signal %d received, cleaning up and exiting.\n", signum);
    gpio_cleanup();
    exit(0);
}

int main() {
    struct sensor_data sensors[2] = {
        {GPIO17, 1, 0},
        {GPIO18, 1, 0}
    };

    gpio_context chip;
    gpio_init(&chip);

    if (gpio_request(&chip, GPIO_IN, GPIO17) < 0 || gpio_request(&chip, GPIO_IN, GPIO18) < 0) {
        fprintf(stderr, "Failed to request GPIO lines.\n");
        gpio_cleanup();
        return 1;
    }

    if (gpio_set_bias_input(&chip, GPIO17) < 0 || gpio_set_bias_input(&chip, GPIO18) < 0) {
        fprintf(stderr, "Failed to set GPIO bias.\n");
        gpio_cleanup();
        return 1;
    }

    FILE *log_file = fopen("/var/log/tilt_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpio_cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        time_t now = time(NULL);
        for (int i = 0; i < 2; i++) {
            int value;
            if (gpio_get_level(&chip, sensors[i].gpio, &value) < 0) {
                fprintf(stderr, "Failed to read GPIO %d.\n", sensors[i].gpio);
                continue;
            }

            if (value == 0 && (now - sensors[i].last_state_change) > DEBOUNCE_WINDOW_MS) {
                sensors[i].state = 0;
                sensors[i].last_state_change = now;
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Sensor %d tilted\n",
                        S_ISDIR(log_file) ? 0 : (time_t)localtime(&now)->tm_year + 1900,
                        (time_t)localtime(&now)->tm_mon + 1,
                        (time_t)localtime(&now)->tm_mday,
                        (time_t)localtime(&now)->tm_hour,
                        (time_t)localtime(&now)->tm_min,
                        (time_t)localtime(&now)->tm_sec,
                        i + 1);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000 - DEBOUNCE_WINDOW_MS);
    }

    gpio_cleanup();
    fclose(log_file);
    return 0;
}

