#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LED_GPIO 22

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    struct gpio_setup gpio_setup;
    gpio_init();

    gpio_setup.gpio = SENSOR1_GPIO;
    gpio_setup.direction = GPIO_OUT;
    gpio_setup.initial_value = 1;
    gpio_setup.pull_up_down = GPIO_PUD_OFF;
    gpio_setup.open_drain = 0;
    gpio_setup.speed = GPIO_SPEED_FAST;

    if (gpioSetup(&gpio_setup) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d\n", SENSOR1_GPIO);
        return EXIT_FAILURE;
    }

    gpio_setup.gpio = SENSOR2_GPIO;
    gpio_setup.direction = GPIO_OUT;
    gpio_setup.initial_value = 1;
    gpio_setup.pull_up_down = GPIO_PUD_OFF;
    gpio_setup.open_drain = 0;
    gpio_setup.speed = GPIO_SPEED_FAST;

    if (gpioSetup(&gpio_setup) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d\n", SENSOR2_GPIO);
        return EXIT_FAILURE;
    }

    gpio_setup.gpio = LED_GPIO;
    gpio_setup.direction = GPIO_OUT;
    gpio_setup.initial_value = 0;
    gpio_setup.pull_up_down = GPIO_PUD_OFF;
    gpio_setup.open_drain = 0;
    gpio_setup.speed = GPIO_SPEED_FAST;

    if (gpioSetup(&gpio_setup) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d\n", LED_GPIO);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("obstacle_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (true) {
        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);

        int sensor1 = gpioGet(SENSOR1_GPIO);
        int sensor2 = gpioGet(SENSOR2_GPIO);
        int led_state = gpioGet(LED_GPIO);

        fprintf(log_file, "%ld,%d,%d,%d\n",
            mktime(local_time),
            sensor1,
            sensor2,
            led_state
        );

        fflush(log_file);

        if (sensor1 == 0 || sensor2 == 0) {
            gpioSet(LED_GPIO, 0);
        } else {
            gpioSet(LED_GPIO, 1);
        }

        usleep(100000);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

