#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define PEAK_DURATION_MS 100

volatile sig_atomic_t stop_sampling = 0;

void sigint_handler(int signum) {
    stop_sampling = 1;
}

int main() {
    gpioInit();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetDirection(MIC_GPIO, GPIO_OUT) < 0 || gpioSetDirection(LED_GPIO, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction\n");
        gpioShutdown();
        return 1;
    }

    gpioSetLow(LED_GPIO);

    if (gpioSetPull(MIC_GPIO, PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on MIC_GPIO\n");
        gpioShutdown();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop_sampling) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        unsigned long long microseconds = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        gpioHigh(LED_GPIO);
        delayMicroseconds(1);
        gpioLow(LED_GPIO);

        if (gpioGet(MIC_GPIO) == 1) {
            printf("%llu\n", microseconds);
            gpioHigh(LED_GPIO);
            delayMicroseconds(PEAK_DURATION_MS * 1000);
        }

        int r = gpioDelayMicroseconds(125);
        if (r < 0) {
            fprintf(stderr, "Failed to delay: %s\n", gpioGetError());
            break;
        }
    }

    gpioShutdown();
    return 0;
}

