#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.hpp>

#define LEFT_GPIO 17
#define CENTER_GPIO 27
#define RIGHT_GPIO 22

#define READ_INTERVAL 100000 // 100 ms in microseconds

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static int read_sensors(gpiod_chip *chip, uint *left, uint *center, uint *right) {
    *left = gpiod_get_value(chip, LEFT_GPIO);
    *center = gpiod_get_value(chip, CENTER_GPIO);
    *right = gpiod_get_value(chip, RIGHT_GPIO);

    if (*left == 0 || *center == 0 || *right == 0) {
        fprintf(stderr, "Error reading IR sensor values.\n");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    gpiod_chip chip;
    uint left, center, right;
    int ret;

    // Initialize GPIO
    ret = gpiod_chip_open(&chip, LEFT_GPIO, gpiod_export);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip for export.\n");
        return ret;
    }

    ret = gpiod_chip_set_owner(chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO chip owner.\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_direction(chip, LEFT_GPIO, GPIO_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction for left sensor.\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_direction(chip, CENTER_GPIO, GPIO_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction for center sensor.\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_direction(chip, RIGHT_GPIO, GPIO_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction for right sensor.\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_pull(chip, LEFT_GPIO, GPIO_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for left sensor.\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_pull(chip, CENTER_GPIO, GPIO_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for center sensor.\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    ret = gpiod_chip_set_pull(chip, RIGHT_GPIO, GPIO_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for right sensor.\n");
        gpiod_chip_close(&chip);
        return ret;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
