#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <termios.h>
#include <gpiod.h>

#define SI1175_ADDR 0x60
#define I2C_BUS 1

typedef struct {
    int fd;
    gpiod_chip *chip;
} si1175_context;

static int si1175_read(si1175_context *ctx, uint16_t *data) {
    int r;
    uint8_t reg_addr = 0x00;
    uint16_t data_msb, data_lsb;

    r = ioctl(ctx->fd, I2C_RDWR, &reg_addr);
    if (r < 0) {
        perror("I2C read error");
        return -1;
    }

    r = read(ctx->fd, &data_msb, 2);
    if (r != 2) {
        perror("Failed to read data from sensor");
        return -1;
    }

    *data = (data_msb << 8) | data_lsb;
    return 0;
}

static int si1175_init(si1175_context *ctx) {
    int r;

    ctx->fd = open("/dev/i2c-1", O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    r = gpiod_chip_new(&ctx->chip, "ALS-Sensor", 0);
    if (!r) {
        gpiod_chip_set_owner(ctx->chip, __RUNLEVEL__, 0);
        r = gpiod_chip_add_lines(ctx->chip, &gpiod_line_specs[0], 1);
        if (r) {
            fprintf(stderr, "Failed to add GPIO lines\n");
            goto err_chip_free;
        }
    } else {
        fprintf(stderr, "Failed to create gpiod chip\n");
        goto err_fd_close;
    }

    return 0;

err_fd_close:
    close(ctx->fd);
err_chip_free:
    gpiod_chip_free(ctx->chip);
    ctx->chip = NULL;
    return -1;
}

static void si1175_cleanup(si1175_context *ctx) {
    if (ctx->chip) {
        gpiod_chip_free(ctx->chip);
        ctx->chip = NULL;
    }

    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

int main() {
    si1175_context ctx;
    uint16_t raw_data;
    struct termios term;
    int fd_status;

    si1175_init(&ctx);
    if (!si1175_init(&ctx)) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return 1;
    }

    tcgetattr(STDIN_FILENO, &term);
    term.c_lflag &= ~ICANON;
    tcsetattr(STDIN_FILENO, TCSANOW, &term);

    while (1) {
        if (si1175_read(&ctx, &raw_data) < 0) {
            si1175_cleanup(&ctx);
            return 1;
        }

        printf("Raw ALS data: %u\n", raw_data);
        sleep(0.1);
    }

    si1175_cleanup(&ctx);
    return 0;
}

