#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <gpiod.h>

#define LEFT_GPIO 2
#define MIDDLE_GPIO 3
#define RIGHT_GPIO 4

static int gpio_fd = -1;

void sigint_handler(int signum) {
    gpiod_request_release_all(gpio_fd);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpio_fd = gpiod_request_open(NULL, "IR_SENSOR");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        return EXIT_FAILURE;
    }

    while (1) {
        int left_value = -1, middle_value = -1, right_value = -1;

        if (gpiod_request_get_value(gpio_fd, LEFT_GPIO) < 0) {
            fprintf(stderr, "Error getting value for left sensor\n");
            goto exit_cleanup;
        }
        left_value = gpiod_request_get_value(gpio_fd, LEFT_GPIO);

        if (gpiod_request_get_value(gpio_fd, MIDDLE_GPIO) < 0) {
            fprintf(stderr, "Error getting value for middle sensor\n");
            goto exit_cleanup;
        }
        middle_value = gpiod_request_get_value(gpio_fd, MIDDLE_GPIO);

        if (gpiod_request_get_value(gpio_fd, RIGHT_GPIO) < 0) {
            fprintf(stderr, "Error getting value for right sensor\n");
            goto exit_cleanup;
        }
        right_value = gpiod_request_get_value(gpio_fd, RIGHT_GPIO);

        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        usleep(100000);
    }

exit_cleanup:
    gpiod_request_release_all(gpio_fd);
    return EXIT_SUCCESS;
}

