#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TTP226_GPIO_MAP \
    {5, 6, 13, 19, 26, 12, 16, 20}

#define TTP226_CH_MAP \
    {0, 1, 2, 3, 4, 5, 6, 7}

#define POLL_INTERVAL_MS 200

static volatile sig_atomic_t sigint_received = 0;

static int
signal_handler(int signum)
{
    sigint_received = 1;
}

static int
read_ttp226(gpiod_chip *chip)
{
    int i;
    uint32_t values[8];

    for (i = 0; i < 8; i++) {
        gpiod_line_request lines[2];
        lines[0] = gpiod_line_request_add(chip, TTP226_GPIO_MAP[i]);
        lines[1] = gpiod_line_request_add(chip, lines[0].line);

        if (lines[0].line_request < 0 || lines[1].line_request < 0) {
            fprintf(stderr, "Failed to request lines for TP%d\n", i + 1);
            return -1;
        }

        if (gpiod_line_get_value_cb(lines[0].line, 0, value_cb, &values[i]) < 0) {
            fprintf(stderr, "Failed to read TP%d\n", i + 1);
            return -1;
        }

        gpiod_line_request_free(lines);
    }

    return 0;
}

static int
value_cb(const uint32_t value, void *user_data)
{
    uint32_t *val = user_data;
    *val = value;
    return 0;
}

int
main(int argc, char *argv[])
{
    struct timespec poll_ts, last_poll_ts;
    gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiod-ttp226", O_RDONLY);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open TTP226 chip\n");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_poll_ts);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!sigint_received) {
        clock_gettime(CLOCK_MONOTONIC, &poll_ts);
        if (poll_ts.tv_sec > last_poll_ts.tv_sec ||
            (poll_ts.tv_sec == last_poll_ts.tv_sec &&
             poll_ts.tv_nsec >= last_poll_ts.tv_nsec)) {
            ret = read_ttp226(chip);
            if (ret < 0) {
                fprintf(stderr, "Error reading TTP226\n");
                break;
            }

            last_poll_ts = poll_ts;
            usleep(POLL_INTERVAL_MS * 1000 - (poll_ts.tv_nsec - last_poll_ts.tv_nsec) / 1000);
        }
    }

    gpiod_chip_close(chip);

    return sigint_received;
}

