#include <stdio.h>
#include <stdlib.#include <unistd.h>
#include <fcntl.h>
#include <sys/syslog.h>
#include <gpiod.h>
#include <time.h>
#include <random>

#define LED_RED  17
#define LED_GREEN 18
#define LED_BLUE  27
#define STEPS 50
#define INTERVAL (1000000 / 1000) // 1000 Hz

static int led_r_fd, led_g_fd, led_b_fd;
static GPioDevice *led_r, *led_g, *led_b;
static uint8_t r, g, b;
static uint32_t hue = 0;
static uint8_t step = 0;

void sigint_handler(int signum) {
    syslog(LOG_INFO, "Received SIGINT, shutting down...");
    cleanup();
    exit(0);
}

void sigterm_handler(int signum) {
    syslog(LOG_INFO, "Received SIGTERM, shutting down...");
    cleanup();
    exit(0);
}

void cleanup() {
    if (led_r) {
        gpiod_device_release(led_r);
        gpiod_device_release(led_g);
        gpiod_device_release(led_b);
    }
    closelog();
}

int main() {
    syslog_open();
    syslog(LOG_NOTICE, "Starting RGB LED fader...");

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    int rfd = gpiod_open();
    if (rfd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO bus, error: %m");
        return 1;
    }

    led_r = gpiod_in_get(rfd, LED_RED);
    if (!led_r) {
        syslog(LOG_ERR, "Failed to get LED red GPIO, error: %m");
        gpiod_close(rfd);
        return 1;
    }

    led_g = gpiod_in_get(rfd, LED_GREEN);
    if (!led_g) {
        syslog(LOG_ERR, "Failed to get LED green GPIO, error: %m");
        gpiod_close(rfd);
        return 1;
    }

    led_b = gpiod_in_get(rfd, LED_BLUE);
    if (!led_b) {
        syslog(LOG_ERR, "Failed to get LED blue GPIO, error: %m");
        gpiod_close(rfd);
        return 1;
    }

    if (gpiod_export(led_r, NULL) < 0 || gpiod_export(led_g, NULL) < 0 || gpiod_export(led_b, NULL) < 0) {
        syslog(LOG_ERR, "Failed to export GPIOs, error: %m");
        cleanup();
        return 1;
    }

    srand(time(NULL));

    while (1) {
        hue = rand() % 0x10000;
        r = (hue & 0xFF00) >> 8;
        g = (hue & 0x00FF);
        b = (hue & 0xFF0000) >> 16;

        for (uint8_t i = 0; i < STEPS; i++) {
            r = clamp(r + (255 - r) * i / STEPS, 0, 255);
            g = clamp(g + (255 - g) * i / STEPS, 0, 255);
            b = clamp(b + (255 - b) * i / STEPS, 0, 255);

            gpiod_set_value(led_r, r);
            gpiod_set_value(led_g, g);
            gpiod_set_value(led_b, b);

            usleep(INTERVAL);
            step++;
        }
    }

    cleanup();
    return 0;
}

uint8_t clamp(uint8_t val, uint8_t min, uint8_t max) {
    return val < min ? min : (val > max ? max : val);
}

