        fprintf(stderr, "Failed to reset BH1750: %s\n", strerror(errno));
        close(bh1750_fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_rdwr(bh1750_fd, 0x2C, NULL, 0, &light_level, 2) < 0) {
        fprintf(stderr, "Failed to read from BH1750: %s\n", strerror(errno));
        close(bh1750_fd);
        exit(EXIT_FAILURE);
    }

    i2c_close(bh1750_fd);
}

void init_apai102() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART_CONTROL, &led_count) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_WRITER_DUART_CONTROL, &led_count | SPI_CS_HIGH) < 0) {
        fprintf(stderr, "Failed to set SPI CS high: %s\n", strerror(errno));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void update_led_brightness() {
    uint32_t brightness = (light_level * 255) / 65535;
    for (int i = 0; i < LED_COUNT; ++i) {
        led_data[i + 1] = (brightness << 16) | (brightness << 8) | brightness;
    }
    led_data[0] = APA102_ZERO_FRAME;
    led_data[LED_COUNT + 1] = APA102_END_FRAME;
}

void transmit_led_data() {
    uint8_t buffer[4];
    for (int i = 0; i < LED_COUNT + 2; ++i) {
        memcpy(buffer, &led_data[i], 4);
        if (write(spi_fd, buffer, 4) != 4) {
            fprintf(stderr, "Failed to transmit LED data: %s\n", strerror(errno));
            break;
        }
        usleep(1000000 / 1000); // 1 MHz SPI clock
    }
}

int main() {
    struct gpiod_chip chip;
    int ret;

    gpiod_chip_init(&chip, "gpiochip0");

    ret = gpiod_chip_add_override(&chip, "gpio0", "gpio", 0, GPIO_DIR_OUT, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO0 as output: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    init_bh1750();
    init_apai102();

    while (1) {
        update_led_brightness();
        transmit_led_data();

        usleep(CONVERSION_DELAY_MS * 1000);
    }

    close(spi_fd);
    return 0;
}
