#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <gpio.h>

#define BH1750_ADDR_1  0x23
#define BH1750_ADDR_2  0x24
#define BH1750_ADDR_3  0x25

#define APA102_GPIO_MOSI 10
#define APA102_GPIO_SCLK 11
#define APA102_CHIP_COUNT 1

#define BRIGHTNESS_FADE_TIME 500
#define LIGHT_READ_DELAY 180
#define LOOP_DELAY 100

struct bh1750_sensor {
    int fd;
    int addr;
};

struct apa102_strip {
    int spi_fd;
    uint8_t *buffer;
    uint16_t brightness;
};

static struct bh1750_sensor sensors[3];
static struct apa102_strip strip;

static void sigint_handler(int signum) {
    gpio_stop(&spi);
    for (int i = 0; i < 3; i++) {
        if (sensors[i].fd != -1) {
            close(sensors[i].fd);
        }
    }
    gpio_uninit();
    exit(0);
}

static int bh1750_init(int addr, int bus_num, struct bh1750_sensor *sensor) {
    sensor->fd = gpiod_open(&bus_num, &addr, GPIOD_IN);
    if (sensor->fd < 0) {
        fprintf(stderr, "Failed to open BH1750 sensor at address 0x%02x\n", addr);
        return -1;
    }
    return 0;
}

static uint16_t bh1750_read(struct bh1750_sensor *sensor) {
    uint8_t data[2];
    gpio_wait_interrupt(sensor->fd);
    gpio_read(sensor->fd, data, 2);
    int16_t raw_value = (data[0] << 8) | data[1];
    return (uint16_t)round((76.7 - raw_value * 1.296) * 100);
}

static int apa102_init(struct apa102_strip *strip) {
    strip->spi_fd = spi_open(APA102_CHIP_COUNT, APA102_GPIO_MOSI, APA102_GPIO_SCLK);
    if (strip->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    strip->buffer = malloc(APA102_LED_COUNT * 3);
    if (!strip->buffer) {
        spi_close(strip->spi_fd);
        return -1;
    }

    return 0;
}

static void apa102_fade(struct apa102_strip *strip, uint16_t target_brightness) {
    uint16_t step = (target_brightness - strip->brightness) / BRIGHTNESS_FADE_TIME;
    if (step > 0) {
        for (int i = 0; i < BRIGHTNESS_FADE_TIME; i++) {
            strip->brightness += step;
            apa102_set_brightness(strip, strip->brightness);
            usleep(1000000 / BRIGHTNESS_FADE_TIME);
        }
    }
}

static void apa102_set_brightness(struct apa102_strip *strip, uint16_t brightness) {
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        strip->buffer[i * 3] = 255;
        strip->buffer[i * 3 + 1] = brightness;
        strip->buffer[i * 3 + 2] = 255;
    }

    spi_transfer(strip->spi_fd, strip->buffer, APA102_LED_COUNT * 3);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpio_init();
    gpio_set_mode(APA102_GPIO_MOSI, GPIOD_OUT);
    gpio_set_mode(APA102_GPIO_SCLK, GPIOD_OUT);

    if (apa102_init(&strip) < 0) {
        fprintf(stderr, "Failed to initialize APA102 strip\n");
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        if (bh1750_init(BH1750_ADDR_1, 1, &sensors[i]) < 0) {
            if (bh1750_init(BH1750_ADDR_2, 1, &sensors[i]) < 0) {
                if (bh1750_init(BH1750_ADDR_3, 1, &sensors[i]) < 0) {
                    fprintf(stderr, "Failed to initialize BH1750 sensor\n");
                    return 1;
                }
            }
        }
    }

    uint16_t total_brightness = 0;
    uint32_t total_count = 0;
    while (1) {
        strip.brightness = 0;
        for (int i = 0; i < 3; i++) {
            if (sensors[i].fd != -1) {
                uint16_t light_level = bh1750_read(&sensors[i]);
                total_brightness += light_level;
                total_count++;
            }
        }

        if (total_count > 0) {
            uint16_t avg_brightness = total_brightness / total_count;
            apa102_fade(&strip, avg_brightness);
        }

        usleep(LOOP_DELAY * 1000);
    }

    return 0;
}

