int init_i2c() {
    int ret;
    i2c_fd = open("/dev/i2c-0", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

