    close(i2c_fd);
}

int init_led() {
    int ret;
    const char *led_gpio_str = "GPIO18";
    struct gpiod_chip_params params = {
        .gpio_num = gpiod_chip_param_find(led_gpio_str),
        .direction_out = true,
        .flags = 0,
    };

    ret = gpiod_chip_get(chip, &params);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO %s\n", led_gpio_str);
        return ret;
    }

    return 0;
}

void cleanup_led() {
    gpiod_chip_put(chip);
}

uint16_t read_veml7700(int retries) {
    uint16_t raw_data = 0;
    int ret;

    for (int i = 0; i < retries; ++i) {
        ret = read(i2c_fd, &raw_data, sizeof(raw_data));
        if (ret > 0) {
            return raw_data;
        } else if (errno == EINTR) {
            continue;
        }

        if (i < MAX_RETRIES - 1) {
            usleep(DELAY_MS * 1000);
        } else {
            fprintf(stderr, "Error reading from VEML7700 after %d retries\n", MAX_RETRIES);
        }
    }

    return 0;
}

