    uint8_t data[3];
    data[0] = (brightness >> 8) & 0xFF;
    data[1] = (brightness >> 0) & 0xFF;
    data[2] = 0; // No color info

    for (int i = 0; i < 3; ++i) {
        gpiod_batch_add(led_fd, data[i]);
    }
    gpiod_batch_submit();
}

