        return -1;
    }

    if (init_i2c() < 0) {
        return -1;
    }

    if (init_led() < 0) {
        cleanup_i2c();
        return -1;
    }

    led_fd = gpiod_chip_get_fd(chip);

    while (1) {
        sensor_data.raw_data = read_veml7700(MAX_RETRIES);
