#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define SAMPLING_INTERVAL 50
#define FLAME_DETECTED_INTERVAL 500
#define RAPID_BLINK_INTERVAL 100
#define ERROR_BELL_PATTERN_DURATION 200
#define ERROR_BELL_REPEAT 3
#define ERROR_BELL_SHORT 200
#define ERROR_BELL_LONG 600

gpio_init();
gpio_set_direction(FLAME_SENSOR_PIN, GPIO_OUT);
gpio_set_direction(BUZZER_PIN, GPIO_OUT);
gpio_set_direction(LED_PIN, GPIO_OUT);

gpio_pin flame_sensor = gpio_claim(FLAME_SENSOR_PIN);
gpio_pin buzzer = gpio_claim(BUZZER_PIN);
gpio_pin led = gpio_claim(LED_PIN);

void self_test() {
    gpio_set_value(led, 1);
    usleep(FLAME_DETECTED_INTERVAL * 1000);
    gpio_set_value(led, 0);
    usleep(FLAME_DETECTED_INTERVAL * 1000);

    for (int i = 0; i < 5; i++) {
        int flame_detected = gpio_get_value(flame_sensor);
        if (flame_detected == 0) {
            gpio_set_value(led, 1);
            usleep(RAPID_BLINK_INTERVAL * 1000);
            gpio_set_value(led, 0);
            usleep(RAPID_BLINK_INTERVAL * 1000);
            break;
        } else {
            usleep(FLAME_DETECTED_INTERVAL * 1000);
        }
    }

    if (flame_detected == 0) {
        gpio_set_value(buzzer, 1);
        usleep(ERROR_BELL_PATTERN_DURATION * 1000);
        gpio_set_value(buzzer, 0);
        usleep(ERROR_BELL_LONG * 1000);
        for (int i = 0; i < ERROR_BELL_REPEAT - 1; i++) {
            gpio_set_value(buzzer, 1);
            usleep(ERROR_BELL_SHORT * 1000);
            gpio_set_value(buzzer, 0);
            usleep(ERROR_BELL_SHORT * 1000);
            usleep(ERROR_BELL_LONG * 1000);
        }
        gpio_set_value(buzer, 1);
        usleep(ERROR_BELL_SHORT * 1000);
        gpio_set_value(buzzer, 0);
        exit(1);
    }
}

void signal_handler(int sig) {
    gpio_free(flame_sensor);
    gpio_free(buzzer);
    gpio_free(led);
    gpio_deinit();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    self_test();

    while (true) {
        int flame_detected = gpio_get_value(flame_sensor);
        if (flame_detected == 0) {
            gpio_set_value(buzzer, 1);
            gpio_set_value(led, 1);
            while (gpio_get_value(flame_sensor) == 0) {
                // Wait for flame to clear
            }
            gpio_set_value(buzzer, 0);
            gpio_set_value(led, 0);
        }

        // Log events with timestamps (implementation omitted for brevity)

        usleep(SAMPLING_INTERVAL * 1000);
    }

    return 0;
}

