        usleep(ERROR_BELL_PATTERN_DURATION * 1000);
        gpio_set_value(buzzer, 0);
        usleep(ERROR_BELL_LONG * 1000);
        for (int i = 0; i < ERROR_BELL_REPEAT - 1; i++) {
