#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <wiringPiI2C.h>

#define BH1750_ADDR 0x23
#define BUFFER_SIZE 60
#define LED_GPIO 17

typedef struct {
    int16_t lux;
    int timestamp;
} LuxSample;

LuxSample buffer[BUFFER_SIZE];
int front = 0;
int rear = 0;

void init_gpio() {
    wiringPiSetup();
    pinMode(LED_GPIO, OUTPUT);
}

int i2c_read(int file, int reg_addr, uint8_t *data, int len) {
    if (ioctl(file, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus");
        return -1;
    }

    if (len == 2) {
        if (ioctl(file, I2C_MASTER_TX_DATA, &reg_addr) < 0) {
            perror("Failed to send address");
            return -1;
        }
        if (read(file, data, len) < 0) {
            perror("Failed to read data");
            return -1;
        }
    }
    return 0;
}

int2_t compute_frequency(int2_t lux) {
    int2_t freq = 0.5;
    if (lux > 1000) {
        freq = 5.0;
    }
    return freq;
}

int main(int argc, char **argv) {
    int fd;
    int ret;

    init_gpio();

    fd = i2c_open("/dev/i2c-1");
    if (fd < 0) {
        fprintf(stderr, "Failed to open i2c bus\n");
        return 1;
    }

    if (wiringPiI2CSetup(fd) < 0) {
        perror("Failed to setup i2c");
        close(fd);
        return 1;
    }

    while (1) {
        LuxSample sample;
        ret = i2c_read(fd, 0x00, &sample.lux, sizeof(sample.lux));
        if (ret < 0) {
            fprintf(stderr, "Error reading from sensor, trying again...\n");
            continue;
        }

        sample.timestamp = (int)time(NULL);

        if (front == rear && rear == BUFFER_SIZE) {
            // Buffer is full, overwrite oldest sample
            front = (front + 1) % BUFFER_SIZE;
        }

        buffer[front] = sample;
        front = (front + 1) % BUFFER_SIZE;

        int sum = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i].lux;
        }
        double avg_lux = (double)sum / BUFFER_SIZE;

        int freq = compute_frequency(avg_lux);

        int duty = (int)(50.0 * (freq / 1.0));
        int period = 1000000 / freq;

        // Blink LED
        ioctl(gpio, IO, LED_GPIO);
        usleep(period / 2);
        ioctl(gpio, IO, ~LED_GPIO);
        usleep(period / 2);
    }

    i2c_close(fd);
    wiringPiI2CTerminated(fd);
    close(fd);
    gpioClose();

    return 0;
}

