#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define SEGMENT_MAP {1, 2, 4, 8, 16, 32, 64, 0}

int main(int argc, char *argv[]) {
    struct gpiod_chip chip;
    struct gpiod_line *data_line, *clock_line, *latch_line;
    uint32_t pattern = SEGMENT_MAP[5]; // Pattern for digit '5'
    int on_period = 500000; // 500 ms in microseconds
    int off_period = 500000;

    if (gpiod_chip_open(&chip, "GPIO17", "GPIO18", "GPIO27") < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip\n");
        return 1;
    }

    data_line = gpiod_chip_get_line(&chip, "GPIO17");
    clock_line = gpiod_chip_get_line(&chip, "GPIO18");
    latch_line = gpiod_chip_get_line(&chip, "GPIO27");

    if (!data_line || !clock_line || !latch_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    if (gpiod_line_export(data_line, "user") < 0 ||
        gpiod_line_export(clock_line, "user") < 0 ||
        gpiod_line_export(latch_line, "user") < 0) {
        fprintf(stderr, "Failed to export GPIO lines\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    gpiod_line_set_dir(data_line, GPIO_DIR_OUT);
    gpiod_line_set_dir(clock_line, GPIO_DIR_OUT);
    gpiod_line_set_dir(latch_line, GPIO_DIR_OUT);

    while (1) {
        // Shift out the pattern for digit '5'
        gpiod_line_write(data_line, pattern & 0x80 ? 1 : 0);
        gpiod_line_write(clock_line, 1);
        gpiod_line_write(data_line, pattern & 0x40 ? 1 : 0);
        gpiod_line_write(clock_line, 1);
        gpiod_line_write(data_line, pattern & 0x20 ? 1 : 0);
        gpiod_line_write(clock_line, 1);
        gpiod_line_write(data_line, pattern & 0x10 ? 1 : 0);
        gpiod_line_write(clock_line, 1);
        gpiod_line_write(latch_line, 1);
        gpiod_line_write(latch_line, 0);

        usleep(on_period);

        usleep(off_period);
    }

    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(&chip);

    return 0;
}

