#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define LED_GPIO 17
#define BUTTON_GPIO 18
#define CHIP_NUMBER 0

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;

static void blink_led(struct gpiod_line *line) {
    bool state = gpiod_get_value(line);
    gpiod_set_value(line, state ? 0 : 1);
    sleep(1);
    gpiod_set_value(line, !state);
    sleep(1);
}

static void handle_button_event(struct gpiod_line *line, uint64_t flags) {
    gpiod_set_value(line, 0);
    printf("Button pressed, stopping LED blinking and exiting.\n");
    exit(0);
}

static void signal_handler(int signum) {
    printf("Received SIGINT, stopping LED blinking and exiting.\n");
    gpiod_set_value(led_line, 0);
    exit(0);
}

int main() {
    chip = gpiod_chip_open(CHIP_NUMBER, "GPIO LED/Button");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_cooked(led_line, "output") < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(button_line) < 0) {
        fprintf(stderr, "Failed to request button line as input\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_pull(button_line, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on button line\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_event(button_line, GPIO_FALLING_EDGE, handle_button_event, NULL) < 0) {
        fprintf(stderr, "Failed to set falling-edge event on button line\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Failed to set initial LED value\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (true) {
        blink_led(led_line);
        if (gpiod_line_get_value(button_line)) {
            handle_button_event(button_line, 0);
        }
    }

    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

