        sleep_ms(OFF_TIME);
    }

    gpio_set_value(LED_PIN, 0);
    printf("LED OFF (graceful exit)\n");
    fflush(stdout);

    gpio_cleanup();
    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (gpio_fsel(LED_PIN) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpio_cleanup();
        return 1;
    }

    gpio_set_value(LED_PIN, 1);
    printf("LED ON\n");
    fflush(stdout);

    while (!sigint_received) {
        gpio_set_value(LED_PIN, 1);
        printf("LED ON\n");
        fflush(stdout);
        sleep_ms(ON_TIME);

        gpio_set_value(LED_PIN, 0);
        printf("LED OFF\n");
        fflush(stdout);
        sleep_ms(OFF_TIME);
    }

    gpio_set_value(LED_PIN, 0);
    printf("LED OFF (graceful exit)\n");
    fflush(stdout);

    gpio_cleanup();
    return 0;
}
