#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define GPIO_PIN 17
#define SAMPLE_INTERVAL_SEC 0.1
#define PULSE_DURATION_MS 50
#define LOG_FILE "impact_log.txt"
#define DEFAULT_THRESHOLD 2.0

float threshold;
int gpiofd;
int i2c_fd;

void sigint_handler(int signum) {
    gpiod_unrequest_all(gpiofd);
    close(i2c_fd);
    exit(signum == SIGINT ? 0 : 1);
}

int init_i2c() {
    int ret;
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_gpio() {
    int ret;
    gpiofd = gpiod_open();
    if (!gpiofd) {
        perror("Failed to open GPIO");
        return -1;
    }

    ret = gpiod_request_available(gpiofd, GPIO_PIN, GPIO_DIR_OUT);
    if (ret < 0) {
        gpiod_close(gpiofd);
        return -1;
    }

    return 0;
}

void cleanup() {
    gpiod_unrequest(gpiofd, GPIO_PIN);
    gpiod_close(gpiofd);
    close(i2c_fd);
}

int read_accel_data(int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    int ret;

    ret = read(i2c_fd, buf, 6);
    if (ret != 6) {
        fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
        return -1;
    }

    *ax = (int16_t)(buf[0] << 8 | buf[1]);
    *ay = (int16_t)(buf[2] << 8 | buf[3]);
    *az = (int16_t)(buf[4] << 8 | buf[5]);

    return 0;
}

float compute_g_force_magnitude(int16_t ax, int16_t ay, int16_t az) {
    return sqrt(ax * ax + ay * ay + az * az);
}

int main(int argc, char *argv[]) {
    int ret;
    struct timespec ts;
    FILE *log_file = fopen(LOG_FILE, "a");

    signal(SIGINT, sigint_handler);

    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default (2.0 G).\n");
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        int16_t ax, ay, az;

        ret = read_accel_data(&ax, &ay, &az);
        if (ret < 0) {
            continue;
        }

        float g_force_mag = compute_g_force_magnitude(ax, ay, az);

        if (g_force_mag > threshold) {
            gpiod_set_value(gpiofd, GPIO_PIN, 1);
            sleep(PULSE_DURATION_MS / 1000);
            gpiod_set_value(gpiofd, GPIO_PIN, 0);

            fprintf(log_file, "%ld.%06ld %d %d %d\n",
                    ts.tv_sec, ts.tv_nsec, ax, ay, az);
        }

        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup();
    fclose(log_file);
    return 0;
}

