    uint8_t green;
    uint8_t blue;
};

static FILE *csv_file = NULL;
static gpiod_chip *chip;
static gpiod_line *led_line;
static struct sensor_data sensor_data;

void sigint_handler(int signum) {
    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int init_i2c() {
    int ret;
    ret = gpiod_in_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize gpiod\n");
        return ret;
    }

    chip = gpiod_chip_find("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to find i2c-1 chip\n");
        return -ENODEV;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to find LED line on i2c-1\n");
        return -ENOENT;
    }

    ret = gpiod_line_export(led_line, "user/led");
    if (ret < 0) {
        fprintf(stderr, "Failed to export LED line\n");
        return ret;
    }

    ret = gpiod_line_request_slave(led_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request slave access for LED line\n");
        return ret;
    }

    ret = gpiod_line_set_direction(led_line, GPIOD_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set LED line direction\n");
        return ret;
    }

    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set initial LED value\n");
        return ret;
    }

    return 0;
}

void cleanup_i2c() {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_unexport(chip);
        chip = NULL;
    }
    gpiod_in_exit();
}

int read_adpd188bi(uint8_t *buffer) {
    int ret;
    ret = gpiod_line_get_value(led_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to get LED line value\n");
        return ret;
    }

    ret = i2c_rdwr_start(ADPD188BI_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to start i2c transaction\n");
        return ret;
    }

    ret = i2c_rdwr(ADPD188BI_ADDR, 0x00, 2, buffer);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from ADPD188BI\n");
        return ret;
    }

    ret = i2c_rdwr_stop();
    if (ret < 0) {
        fprintf(stderr, "Failed to stop i2c transaction\n");
        return ret;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa.handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        return 1;
    }

    csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        cleanup_i2c();
        return 1;
    }

    fprintf(csv_file, "Time,ALS,Red,Green,Blue\n");

