        sensor_data.red = buffer[2];
        sensor_data.green = 0;
        sensor_data.blue = 0;

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup_i2c();
    fclose(csv_file);
    return 0;
}
