#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/dev.h>

#define I2C_BUS 1
#define FXOS8700CQ_ADDR 0x68
#define STANDBY 0x00
#define ACTIVE 0x01
#define RANGE_2G 0x00
#define OUTPUT_DATA_RATE_200HZ 0x00
#define WHO_AM_I_REG 0x0F
#define IMPACT_THRESHOLD 5.0

static struct i2c_dev *dev;
static struct gpiod_chip *chip;

void log_impact(double timestamp, int16_t x, int16_t y, int16_t z, double magnitude) {
    char timestamp_str[20];
    snprintf(timestamp_str, sizeof(timestamp_str), "%04d-%02d-%02d %02d:%02d:%02d",
             1900 + (time(NULL) / 31536000),
             (time(NULL) / 86400) % 12, (time(NULL) / 86400) % 31,
             (time(NULL) / 3600) % 24, (time(NULL) / 60) % 60, (time(NULL) / 60) % 60);

    FILE *log_file = fopen("impact_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp_str, x, y, z, magnitude);
        fclose(log_file);
    }
}

int main() {
    dev = i2c_open_device(I2C_BUS);
    if (!dev) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (i2c_xfer(dev, FXOS8700CQ_ADDR, NULL, 0, NULL, 1) < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        i2c_close(dev);
        return 1;
    }

    uint8_t reg_data[2];
    if (i2c_xfer(dev, FXOS8700CQ_ADDR, WHO_AM_I_REG, 1, reg_data, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2c_close(dev);
        return 1;
    }

    if (reg_data[0] != 0x46) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02x\n", reg_data[0]);
        i2c_close(dev);
        return 1;
    }

    if (i2c_write_byte(dev, FXOS8700CQ_ADDR, STANDBY) < 0) {
        fprintf(stderr, "Failed to put device in standby\n");
        i2c_close(dev);
        return 1;
    }

    if (i2c_write_byte(dev, FXOS8700CQ_ADDR, RANGE_2G) < 0) {
        fprintf(stderr, "Failed to set range to 2g\n");
        i2c_close(dev);
        return 1;
    }

    if (i2c_write_byte(dev, FXOS8700CQ_ADDR, OUTPUT_DATA_RATE_200HZ) < 0) {
        fprintf(stderr, "Failed to set output data rate to 200Hz\n");
        i2c_close(dev);
        return 1;
    }

    if (i2c_write_byte(dev, FXOS8700CQ_ADDR, ACTIVE) < 0) {
        fprintf(stderr, "Failed to activate device\n");
        i2c_close(dev);
        return 1;
    }

    chip = gpiod_chip_open(GPIOD_CHIP_I2C_1, "i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO controller\n");
        i2c_close(dev);
        return 1;
    }

    gpiod_chip_add_listener(chip, NULL, NULL, NULL, i2c_interrupt_handler);

    while (1) {
        int16_t accel_x, accel_y, accel_z;
        double magnitude;

        if (i2c_read_word_data(dev, FXOS8700CQ_ADDR, 0x02, &accel_x) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        if (i2c_read_word_data(dev, FXOS8700CQ_ADDR, 0x04, &accel_y) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        if (i2c_read_word_data(dev, FXOS8700CQ_ADDR, 0x06, &accel_z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(time(NULL), accel_x, accel_y, accel_z, magnitude);
        }

        usleep(50000);
    }

    gpiod_chip_remove_listener(chip);
    gpiod_chip_close(chip);
    i2c_close(dev);

    return 0;
}

static int i2c_interrupt_handler(const struct gpiod_chip *chip,
                                 struct gpiod_line *line, uint32_t event, void *user_data) {
    (void)chip;
    (void)event;
    (void)user_data;

    return 0;
}

