#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define DEVICE_ADDR 0x19
#define CALIBRATION_SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define LOG_INTERVAL_MS 50
#define ALERT_THRESHOLD 50

struct gyro_data {
    int16_t x_offset;
    int16_t y_offset;
    int16_t z_offset;
};

struct gyro_data gyro_offsets;
FILE *log_file = NULL;

void calibrate(int fd) {
    uint8_t buf[6];
    for (int i = 0; i < CALIBRATION_SAMPLES; ++i) {
        if (gpiod_iomap(NULL)) {
            fprintf(stderr, "Failed to initialize GPIO\n");
            exit(EXIT_FAILURE);
        }

        if (ioctl(fd, I2C_SLAVE, DEVICE_ADDR) < 0) {
            fprintf(stderr, "Failed to acquire bus access and/or talk to slave\n");
            exit(EXIT_FAILURE);
        }

        if (read(fd, buf, 6) != 6) {
            fprintf(stderr, "Failed to read from gyro\n");
            exit(EXIT_FAILURE);
        }

        // Process buf to compute offsets
    }

    // Save computed offsets to gyro_offsets
}

void log_data(struct gyro_data offsets) {
    static char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    if (fprintf(log_file, "%s,x=%d,y=%d,z=%d\n", timestamp, offsets.x_offset, offsets.y_offset, offsets.z_offset) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    }
}

void check_and_log_alert(struct gyro_data offsets, int16_t x, int16_t y, int16_t z) {
    if (abs(x) > ALERT_THRESHOLD || abs(y) > ALERT_THRESHOLD || abs(z) > ALERT_THRESHOLD) {
        fprintf(stderr, "Warning: Axis exceeded threshold!\n");
        fprintf(log_file, "ALERT:%s,x=%d,y=%d,z=%d\n", timestamp, x, y, z);
    }
}

void signal_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main() {
    struct gpiod_chipchip *chi;
    int fd;
    struct gyro_data offsets;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (gpiod_iomap(NULL)) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, DEVICE_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (calibrate(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buf[6];
        if (read(fd, buf, 6) != 6) {
            fprintf(stderr, "Failed to read from gyro\n");
            break;
        }

        int16_t x = (buf[0] << 8 | buf[1]);
        int16_t y = (buf[2] << 8 | buf[3]);
        int16_t z = (buf[4] << 8 | buf[5]);

        check_and_log_alert(offsets, x, y, z);
        log_data(offsets);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

