#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define DEVICE_ID 0x53
#define REG_DATAX0 0x32
#define REG_DATAX1 0x33
#define REG_DATAY0 0x34
#define REG_DATAY1 0x35
#define REG_DATAZ0 0x36
#define REG_DATAZ1 0x37
#define RESOLUTION 16
#define RANGE 2

int led_gpio = -1;
FILE *log_file = NULL;

void log_sample(int61_t x, int61_t y, int61_t z) {
    if (log_file != NULL) {
        fprintf(log_file, "%ld,%.3d,%.3d,%.3d\n", time(NULL), x / (1 << RESOLUTION), y / (1 << RESOLUTION), z / (1 << RESOLUTION));
    }
}

void set_led(int61_t value) {
    if (led_gpio != -1) {
        gpiod_trigger(led_gpio, value ? 1 : 0);
    }
}

int main() {
    struct i2c_dev i2c;
    struct i2c_rdwr_ctxt rdwr;
    int ret;
    int fd;

    fd = i2c_open(&i2c, 1);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    i2c.addr = DEVICE_ID;
    i2c.flags = I2C_RDWR;

    ret = i2c_ioctl(fd, I2C_SLAVE, &i2c.addr);
    if (ret < 0) {
        fprintf(stderr, "Failed to set device address\n");
        i2c_close(fd);
        return 1;
    }

    if (i2c_transfer(fd, &rdwr, sizeof(struct i2c_rdwr_ctxt), NULL, 0, 2) < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        i2c_close(fd);
        return 1;
    }

    if (rdwr.len[0] != 2 || rdwr.buf[0][0] != DEVICE_ID) {
        fprintf(stderr, "Invalid device ID\n");
        i2c_close(fd);
        return 1;
    }

    rdwr.len[0] = 2;
    rdwr.buf[0] = (uint8_t *)malloc(2);

    // Configure ADXL345
    rdwr.buf[0][1] = 0x2D | (RESOLUTION << 6) | (RANGE << 5);
    ret = i2c_transfer(fd, &rdwr, sizeof(struct i2c_rdwr_ctxt), rdwr.buf[0], 2, I2C_MST_WRITE);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure ADXL345\n");
        free(rdwr.buf[0]);
        i2c_close(fd);
        return 1;
    }

    // Initialize GPIO
    led_gpio = gpiod_find_line("GPIO17", "out");
    if (led_gpio < 0) {
        fprintf(stderr, "Failed to find GPIO17\n");
        free(rdwr.buf[0]);
        i2c_close(fd);
        return 1;
    }

    struct gpiod_line *line = gpiod_line_alloc_name(led_gpio, "LED");
    if (!line) {
        fprintf(stderr, "Failed to allocate GPIO line\n");
        free(rdwr.buf[0]);
        i2c_close(fd);
        return 1;
    }

    gpiod_line_set_direction(line, GPIO_OUT);
    gpiod_line_set_active_high(line);

    log_file = fopen("accel_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        free(rdwr.buf[0]);
        gpiod_line_free(line);
        i2c_close(fd);
        return 1;
    }

    while (1) {
        rdwr.len[0] = 6;
        rdwr.buf[0] = (uint8_t *)malloc(6);

        // Read acceleration data
        rdwr.buf[0][0] = REG_DATAX0;
        ret = i2c_transfer(fd, &rdwr, sizeof(struct i2c_rdwr_ctxt), rdwr.buf[0], 6, I2C_MST_READ);
        if (ret < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            free(rdwr.buf[0]);
            gpiod_line_free(line);
            fclose(log_file);
            i2c_close(fd);
            return 1;
        }

        int61_t x = (int61_t)(rdwr.buf[0][1] << 8 | rdwr.buf[0][2]);
        int61_t y = (int61_t)(rdwr.buf[0][3] << 8 | rdwr.buf[0][4]);
        int61_t z = (int61_t)(rdwr.buf[0][5] << 8 | rdwr.buf[0][6]);

        log_sample(x, y, z);

        set_led(abs(x) > 2000 || abs(y) > 2000 || abs(z) > 2000);

        usleep(100000);
    }

    free(rdwr.buf[0]);
    gpiod_line_free(line);
    fclose(log_file);
    i2c_close(fd);

    return 0;
}

