#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <wiringPiI2C.h>
#include <lsm303.h>

#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 100

static struct lsm303_context *lsm303;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    lsm303_exit(lsm303);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    struct gpiod_chip_params params;
    struct gpiod_chip *chip;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize I2C
    wiringPiI2CSetup(I2C_BUS);
    if (!(chip = gpiod_chip_open(I2C_BUS, "i2c-1", &params))) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Initialize LSM303
    lsm303 = lsm303_new_i2c(I2C_BUS, 0x19);
    if (!lsm303) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    if (!(log_file = fopen("compass_log.txt", "w"))) {
        fprintf(stderr, "Failed to open log file\n");
        lsm303_exit(lsm303);
        gpiod_chip_close(chip);
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,heading,ax,ay,az,mx,my,mz\n");

    while (1) {
        // Read sensor data
        struct lsm303_data data;
        if (lsm303_read(&data) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Compute tilt-compensated heading
        float heading = lsm303_heading(&data);

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        // Log data
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, heading, data.accel.x, data.accel.y, data.accel.z,
                data.mag.x, data.mag.y, data.mag.z);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    lsm303_exit(lsm303);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

