#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define VL6180X_ADDR 0x29
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define MIN_DISTANCE 100

static int file_fd = -1;
static FILE *log_file = NULL;

static int sensor_init(void) {
    int ret;
    ret = i2c_open(0, &file_fd);
    if (ret < 0) {
        perror("Failed to open I2C bus");
        return ret;
    }

    ret = i2c_xfer(file_fd, VL6180X_ADDR, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to access sensor\n");
        i2c_close(file_fd);
        file_fd = -1;
        return ret;
    }

    // Perform mandatory initialization sequence here
    // ...

    return 0;
}

static int sensor_read(uint8_t *data, size_t len) {
    int ret;
    ret = i2c_xfer(file_fd, VL6180X_ADDR, data, len);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from sensor\n");
        return -1;
    }
    return 0;
}

static void sensor_cleanup(void) {
    if (file_fd != -1) {
        i2c_close(file_fd);
        file_fd = -1;
    }
}

static void sigint_handler(int signum) {
    sensor_cleanup();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

int main(void) {
    struct timespec ts;
    struct timespec last_ts;
    uint8_t data[12];
    char state[20];

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return 1;
    }

    if (sensor_init() < 0) {
        return 1;
    }

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        sensor_cleanup();
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_ts);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if ((ts.tv_sec - last_ts.tv_sec) * 1000000 + (ts.tv_nsec - last_ts.tv_nsec) >= SAMPLE_INTERVAL) {
            last_ts = ts;

            if (sensor_read(data) < 0) {
                // Attempt to re-initialize the sensor
                sensor_cleanup();
                sensor_init();
                if (sensor_init() < 0) {
                    break;
                }
                continue;
            }

            int range = (data[0] << 8) | data[1];
            char *state_str;
            if (range < MIN_DISTANCE) {
                state_str = "DOOR_OPEN";
            } else {
                state_str = "DOOR_CLOSED";
            }

            fprintf(log_file, "%lu %s\n", (unsigned long)ts.tv_sec, state_str);
        }
    }

    sensor_cleanup();
    fclose(log_file);
    return 0;
}

