#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR_IMP23A 0x1D
#define I2C_ADDR_IMP23B 0x1E
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.dat"

struct sensor_data {
    struct timespec timestamp;
    int16_t sensor1;
    int16_t sensor2;
    int32_t tdoa;
};

FILE *log_file = NULL;

static int sensor_read(int fd, uint8_t *buffer, size_t length) {
    if (length != 2)
        return -1;

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR_IMP23A) < 0)
        return -1;

    if (read(fd, buffer, length) != length)
        return -1;

    return 0;
}

static int compute_tdoa(int16_t sensor1, int16_t sensor2) {
    struct timespec timestamp;
    clock_gettime(CLOCK_REALTIME, &timestamp);

    int32_t tdoa = (int32_t)(timestamp.tv_sec * 1000000 + timestamp.tv_nsec) -
                   ((int32_t)(timestamp.tv_sec * 1000000 + timestamp.tv_nsec) -
                     (int32_t)(timestamp.tv_sec * 1000000 + timestamp.tv_nsec) +
                     sensor1 - sensor2);

    return tdoa;
}

static void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpiod_unbind(chip);
    close(fd);
    free(chip);
}

int main() {
    struct gpiod_chip chip;
    int fd;
    uint8_t buffer[2];
    struct sensor_data data;

    if (gpiod_chip_open(&chip, "i2c-1") < 0) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return 1;
    }

    if (gpiod_chip_add_lines(&chip, "IMP23A", 1) < 0 ||
        gpiod_chip_add_lines(&chip, "IMP23B", 1) < 0) {
        fprintf(stderr, "Failed to add lines to I2C chip\n");
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

