#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>
#include <gpiod.h>

#define SPI_PORT 0
#define SPI_DEVICE 7
#define SPI_CE0_GPIO 8
#define SAMPLING_INTERVAL 100
#define STALL_TIME_US 40
#define SPI_CLOCK_HZ 1000000
#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

struct imu_data {
    double timestamp;
    int16_t gyro_x, gyro_y, gyro_z;
    int16_t accel_x, accel_y, accel_z;
};

static FILE *fp = NULL;
static gpiod_chip *chip;
static gpiod_line *ce0_line;
static spi_dev spi;

void cleanup() {
    spi_close(&spi);
    gpiod_line_free(ce0_line);
    gpiod_chip_free(chip);
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
}

static void sigint_handler(int signum) {
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    exit(0);
}

static void sigterm_handler(int signum) {
    sigint_handler(signum);
}

static void sample_imu() {
    struct imu_data data;
    uint16_t cmd_word, data_word_high, data_word_low;

    cmd_word = 0x0000; // Set MSB to 0, followed by 7-bit register address
    cmd_word |= (register_address & 0x7F) << 1;

    // Wait for stall time
    usleep(STALL_TIME_US * 1000);

    if (gpiod_trigger_output(ce0_line, 1) < 0) {
        fprintf(stderr, "Error triggering CE0 line\n");
        return;
    }

    // Perform SPI transfer
    if (spi_transfer(&spi, &cmd_word, 1, &data_word_high, 1) < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return;
    }

    if (gpiod_trigger_output(ce0_line, 0) < 0) {
        fprintf(stderr, "Error deactivating CE0 line\n");
        return;
    }

    if (spi_transfer(&spi, NULL, 0, &data_word_low, 1) < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return;
    }

    data.timestamp = (double)microsec_clock() / 1000.0;
    data.gyro_x = (data_word_high << 8 | data_word_low) * GYRO_SENSITIVITY;
    data.gyro_y = (data_word_high << 8 | data_word_low) * GYRO_SENSITIVITY;
    data.gyro_z = (data_word_high << 8 | data_word_low) * GYRO_SENSITIVITY;
    data.accel_x = (data_word_high << 8 | data_word_low) * ACCEL_SENSITIVITY;
    data.accel_y = (data_word_high << 8 | data_word_low) * ACCEL_SENSITIVITY;
    data.accel_z = (data_word_high << 8 | data_word_low) * ACCEL_SENSITIVITY;

    if (fp == NULL) {
        fp = fopen("imu_data.csv", "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file imu_data.csv\n");
            return;
        }
        fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    }

    fprintf(fp, "%f,%f,%f,%f,%f,%f,%f\n",
            data.timestamp,
            data.gyro_x, data.gyro_y, data.gyro_z,
            data.accel_x, data.accel_y, data.accel_z);
}

int main() {
    int ret;
    struct sigaction sa;

    // Initialize signal handlers
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO and SPI
    chip = gpiod_chip_open(SPI_CE0_GPIO);
    ce0_line = gpiod_chip_get_line(chip, "CE0");
    gpiod_line_export(ce0_line, "user");
    gpiod_line_set_direction(ce0_line, GPIO_OUT);

    spi = spi_open(SPI_PORT, SPI_DEVICE);
    if (spi_set_mode(spi, SPI_MODE3) < 0) {
        fprintf(stderr, "Error setting SPI mode\n");
        return 1;
    }
    if (spi_set_clock_hz(spi, SPI_CLOCK_HZ) < 0) {
        fprintf(stderr, "Error setting SPI clock frequency\n");
        return 1;
    }

    // Register cleanup function
    atexit(cleanup);

    // Start non-blocking delay loop
    while (true) {
        sample_imu();

        ret = nonblock_delay(SAMPLING_INTERVAL);
        if (ret < 0) {
            fprintf(stderr, "Error in non-block delay\n");
            break;
        }
    }

    return 0;
}

