    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_chip_export(chip, CS_GPIO, GPIOD_FLAG_OUTPUT);
    if (gpiod_chip_get_line(chip, CS_GPIO) < 0) {
        perror("Failed to export GPIO for CS");
        return EXIT_FAILURE;
    }
    gpiod_chip_set_value(chip, CS_GPIO, 0);

    spi_fd = spi_open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    spi_ioctl(spi_fd, SPI_WRITER_DUART, NULL);
    spi_ioctl(spi_fd, SPI_MODF_BITORDER, &SPI_MODE);
    spi_ioctl(spi_fd, SPI_MAXSPEED_HZ, &SPI_CLOCK);

