#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <gpiod.h>

#define ADIS16448_SPI_CHANNEL 0
#define ADIS16448_CE0_GPIO  8
#define ADIS16448_SPI_MODE  0
#define ADIS16448_STALL_TIME_US 40

#define GYRO_SCALE_FACTOR 0.05
#define ACCEL_SCALE_FACTOR 0.00025

static struct gpiod_chip *chip;
static struct gpiod_chip_cq *cq;
static int spi_fd;

void spi_transfer(uint16_t read_cmd, uint16_t dummy_val) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)(void *)&read_cmd;
    tr.rx_buf = (unsigned long)(void *)&dummy_val;
    tr.len = 2;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 16;
    tr.delay_usecs = ADIS16448_STALL_TIME_US;
    tr.cs_change = 0;

    if (write(spi_fd, &tr, sizeof(tr)) != sizeof(tr)) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
}

float read_gyro_deg_sec(uint16_t data) {
    return (float)data * GYRO_SCALE_FACTOR;
}

float read_accel_g(uint16_t data) {
    return (float)data * ACCEL_SCALE_FACTOR;
}

void sigint_handler(int signum) {
    gpiod_chip_put(chip);
    close(spi_fd);
    exit(0);
}

int main() {
    chip = gpiod_chip_open(&gpiod_chip_default_params);
    if (!chip) {
        perror("Failed to open gpiod chip");
        return EXIT_FAILURE;
    }

    cq = gpiod_chip_get_cq(chip);
    if (!cq) {
        perror("Failed to get gpiod chip CQ");
        return EXIT_FAILURE;
    }

