#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define ADXL_I2C_ADDR 0x53
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"
#define THRESHOLD 2.5
#define POLL_INTERVAL_MS 10

struct accel_data {
    float x, y, z;
    float mag;
};

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    struct i2c_client *client;
    struct i2c_rdwr_ioctl_data rdwr;
    struct accel_data accel_data;
    FILE *log_file = NULL;
    char timestamp[32];
    int ret;

    // Initialize GPIO for LED
    ret = gpiod_chip_open(&chip, "GPIO17");
    if (ret) {
        fprintf(stderr, "Failed to open GPIO17\n");
        return ret;
    }
    gpiod_chip_set_owner(&chip, getpid());
    ret = gpiod_chip_set_direction(&chip, 17, GPIO_DIR_OUT);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO17 direction\n");
        return ret;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return -1;
    }

    // Initialize I2C
    client = devm_i2c_get_client_pos(I2C_BOARD_NUMBER, ADXL_I2C_ADDR);
    if (!client) {
        fprintf(stderr, "Failed to get I2C client\n");
        return -1;
    }
    ret = i2c_master_init(client);
    if (ret) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return ret;
    }

    // Verify device ID
    uint8_t device_id;
    ret = i2c_transfer(client, 0x00, NULL, 0, &device_id, 1);
    if (ret || device_id != 0x53) {
        fprintf(stderr, "Invalid device ID: 0x%02X\n", device_id);
        return -1;
    }

    while (1) {
        // Read accelerometer data
        rdwr.buf = &accel_data;
        rdwr.len = sizeof(accel_data);
        ret = i2c_transfer_device(client, ADXL_I2C_ADDR, &rdwr);
        if (ret || rdwr.len != sizeof(accel_data)) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        // Calculate magnitude
        accel_data.mag = sqrt(accel_data.x * accel_data.x + accel_data.y * accel_data.y + accel_data.z * accel_data.z);

        // Check for impact
        if (accel_data.mag > THRESHOLD) {
            // Turn on LED
            gpiod_trigger_set_value(line, 1);
            fprintf(log_file, "Impact detected: %f g\n", accel_data.mag);
            fflush(log_file);

            // Wait for 500 ms
            sleep(0.5);

            // Turn off LED
            gpiod_trigger_set_value(line, 0);
        }

        // Write timestamp to log file
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s: %f g, %f %f %f g\n", timestamp, accel_data.mag, accel_data.x, accel_data.y, accel_data.z);
        fflush(log_file);

        // Sleep for POLL_INTERVAL_MS ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_close(&chip);
    i2c_master_deinit(client);

    return 0;
}

