#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <gpio.h>

#define LED_GPIO 17
#define I2C_BUS 1
#define ID_REG 0x00
#define X_L_REG 0x32
#define X_H_REG 0x33
#define Y_L_REG 0x34
#define Y_H_REG 0x35
#define Z_L_REG 0x36
#define Z_H_REG 0x37
#define POWER_CTRL_REG 0x2D
#define DATA_READY_REG 0x32

#define MAX_LOG_SIZE 1024

FILE *log_file = NULL;

void signal_handler(int signum) {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

void init_i2c(void) {
    int ret = gpiod_in_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_i2c_init(I2C_BUS);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize I2C bus %d\n", I2C_BUS);
        gpiod_terminate();
        exit(EXIT_FAILURE);
    }
}

void init_gpio(void) {
    int ret = gpioInitialize();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        gpiod_terminate();
        exit(EXIT_FAILURE);
    }

    ret = gpioSetDirection(LED_GPIO, GPIO_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO%d direction\n", LED_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetLow(LED_GPIO);
}

void init_log_file(void) {
    log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        gpiod_terminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup(void) {
    gpioTerminate();
    gpiod_terminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_i2c();
    init_gpio();
    init_log_file();

    uint8_t id = read_id_register();
    if (id != 0x45) {
        fprintf(stderr, "Invalid sensor ID\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint16_t x, y, z;
        read_accel_data(&x, &y, &z);

        float mag = (float)sqrt(x * x + y * y + z * z);
        if (mag > 2.0) {
            gpioSetHigh(LED_GPIO);
            sleep(0.5);
            gpioSetLow(LED_GPIO);
        }

        char timestamp[20];
        time_t t = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

        fprintf(log_file, "%s: x=%d, y=%d, z=%d, mag=%.2f\n", timestamp, x, y, z, mag);

        sleep(0.1);
    }

    cleanup();
    return 0;
}

uint8_t read_id_register(void) {
    uint8_t id;
    int ret = gpiod_i2c_write_read(I2C_BUS, ID_REG, NULL, 0, &id, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        exit(EXIT_FAILURE);
    }
    return id;
}

void read_accel_data(uint16_t *x, uint16_t *y, uint16_t *z) {
    uint16_t data[3];
    int ret = gpiod_i2c_write_read(I2C_BUS, DATA_READY_REG, NULL, 0, data, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to read accel data\n");
        exit(EXIT_FAILURE);
    }

    *x = (data[1] << 8) | data[0];
    *y = (data[3] << 8) | data[2];
    *z = (data[5] << 8) | data[4];
}

