#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMAG5273_ADDR 0x1E
#define SAMPLE_INTERVAL 1

int i2c_fd = -1;
char *filename = "magnetic_field_log.csv";
FILE *fp = NULL;

void sigint_handler(int signum, siginfo_t *info, void *context) {
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_magnetic_data(uint8_t *data, int len) {
    if (len != 6) {
        fprintf(stderr, "Error: Incorrect data length\n");
        return -1;
    }

    if (read(i2c_fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C bus\n");
        return -1;
    }

    return 0;
}

int setup_csv_file() {
    if (fp) {
        fclose(fp);
        fp = NULL;
    }

    fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open CSV file");
        return -1;
    }

    if (fprintf(fp, "Time,X,Y,Z\n") < 0) {
        perror("Failed to write header to CSV file");
        fclose(fp);
        fp = NULL;
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_sigaction = sigint_handler;
    sa.sa_flags = SA_SIGINFO;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handlers");
        return 1;
    }

    if (setup_i2c() < 0) {
        return 1;
    }

    if (setup_csv_file() < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    while (1) {
        uint8_t data[6];
        if (read_magnetic_data(data, 6) < 0)
            continue;

        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);

        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,",
                ltm->tm_year + 1900, ltm->tm_mon + 1, ltm->tm_mday,
                ltm->tm_hour, ltm->tm_min, ltm->tm_sec);
        fprintf(fp, "%d, %d, %d, %d\n",
                data[1] >> 4, data[1] & 0x0F, data[3] >> 4, data[3] & 0x0F);
        fflush(fp);

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    return 0;
}

