#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <pigpio.h>

#define ADIS16266_ADDR 0x1E
#define WHO_AM_I_REG 0x0D
#define ANG_RATE_X_L_REG 0x08
#define ANG_RATE_X_H_REG 0x09
#define ANG_RATE_Y_L_REG 0x0A
#define ANG_RATE_Y_H_REG 0x0B
#define ANG_RATE_Z_L_REG 0x0C
#define ANG_RATE_Z_H_REG 0x0D

#define SPI_MODE 3
#define CPOL 1
#define CPHA 1
#define SPI_CLOCK_HZ 1000000

static gpiod_context ctx;
static pi_channel spi_cs;
static FILE *log_file;

void spi_cleanup(int signum) {
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_exit(ctx);
    exit(signum);
}

void init_spi() {
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    spi_cs = gpiod_claim_single(&ctx, "SPI_CS", GPIO_IN, 8);
    if (!spi_cs) {
        fprintf(stderr, "Failed to claim SPI_CS\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(spi_cs->v, PI_OUTPUT);
    gpioSetPullUpDown(spi_cs->v, PI_PULL_UP);
    gpioWrite(spi_cs->v, 1);
}

void spi_read_reg(uint8_t reg_addr) {
    uint8_t read_addr = (reg_addr & 0x80) | 0x01;

    spiTransfer(ADIS16266_ADDR, &read_addr, 1, NULL, 1);
    spiTransfer(ADIS16266_ADDR, NULL, 0, (uint8_t *)&read_addr, 1);
}

double spi_read_angular_rate(uint8_t reg_addr) {
    uint16_t raw_value;
    spi_read_reg(reg_addr);
    raw_value = (uint16_t)((read_addr & 0x03) << 8) | read_addr;

    return raw_value * 0.0305;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = spi_cleanup;
    sigaction(SIGINT, &sa, NULL);

    init_spi();

    if (!(log_file = fopen("gyro_log.csv", "w"))) {
        fprintf(stderr, "Failed to open gyro_log.csv\n");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp,Ax,Ay,Az\n");

    while (1) {
        double ax, ay, az;

        ax = spi_read_angular_rate(ANG_RATE_X_L_REG);
        ay = spi_read_angular_rate(ANG_RATE_Y_L_REG);
        az = spi_read_angular_rate(ANG_RATE_Z_L_REG);

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);

        fprintf(log_file, "%ld,%.6f,%.6f,%.6f\n",
                mktime(&tm), ax, ay, az);

        usleep(10000);
    }

    return 0;
}

