int init_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    int addr_width = 7;
    int flags = 0;
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access and/or perform I2C bus transaction");
        close(fd);
        return -1;
    }

    struct gpiod_chip_params params = {
        .fd = fileno(stdout),
        .name = "l3gd20_i2c",
        .flags = 0,
    };

    chip = gpiod_chip_new(&params);
    if (!chip) {
        perror("Failed to create GPIO chip");
        close(fd);
        return -1;
    }

    return fd;
}

bool check_sensor_id(int fd) {
    uint8_t data[2];
    if (i2c_rdwr(fd, &data, 1, &data, 1) != 1) {
        return false;
