struct sensor_data {
    char timestamp[BUFFER_SIZE];
    int16_t x, y, z;
};

int main() {
    int fd;
    struct sensor_data data;
    FILE *fp;
    char buf[BUFFER_SIZE];
    struct gpiod_chip chip;
    struct gpiod_line line;

    // Initialize GPIO
    if (gpiod_chip_open(&chip, "gpiochip0") < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    // Register SIGINT handler
    if (signal(SIGINT, (void (*)(int))cleanup) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return 1;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1\n");
        return 1;
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(fd);
        return 1;
    }

    // Open CSV file
    fp = fopen(FILENAME, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s for writing\n", FILENAME);
        close(fd);
        return 1;
    }

    // Write header
    time_t t = time(NULL);
    strftime(data.timestamp, BUFFER_SIZE, "%Y-%m-%dT%H:%M:%S", localtime(t));
    fprintf(fp, "Timestamp,X,Y,Z\n");

    while (1) {
        // Read sensor data
        if (i2c_rdwr(fd, &line, BUFFER_SIZE, buf) < 0) {
            fprintf(stderr, "Failed to read from I2C sensor\n");
            usleep(100000); // Sleep for 100ms
            continue;
        }

        // Parse data
        sscanf(buf, "%d,%d,%d", &data.x, &data.y, &data.z);

        // Write data to CSV
        t = time(NULL);
        strftime(data.timestamp, BUFFER_SIZE, "%Y-%m-%dT%H:%M:%S", localtime(t));
        fprintf(fp, "%s,%d,%d,%d\n", data.timestamp, data.x, data.y, data.z);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(fp);
    close(fd);
    gpiod_chip_close(chip);

    return 0;
}

void cleanup(int signo) {
    if (signo == SIGINT) {
        fprintf(stderr, "Ctrl+C detected, cleaning up...\n");
        // Close I2C file descriptor and CSV file
        fclose(fp);
        close(fd);
        gpiod_chip_close(chip);
        exit(0);
    }
}

