        fprintf(stderr, "Failed to request GPIO %d\n", SENSOR2_GPIO);
        gpio_close(gpio_ctx);
        exit(1);
    }

    if (gpio_set_wd_out(gpio_ctx, SENSOR1_GPIO, true) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output with pull-up\n", SENSOR1_GPIO);
        gpio_close(gpio_ctx);
        exit(1);
    }

    if (gpio_set_wd_out(gpio_ctx, SENSOR2_GPIO, true) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output with pull-up\n", SENSOR2_GPIO);
