    if (gpio_get_level(gpio_ctx, SENSOR2_GPIO) == 1) {
        fprintf(log_file, "%s Sensor 2: HIGH\n", timestamp);
    } else {
        fprintf(log_file, "%s Sensor 2: LOW\n", timestamp);
    }

    fflush(log_file);
}

