    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_gpio();

    while (true) {
        log_sensor_states();
        sleep(CHECK_INTERVAL_MS / 1000);
    }

    gpio_close(gpio_ctx);
