#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define DEVICE_ADDR 0x1C
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x21
#define STANDBY_COUNT 0x01
#define DATA_RATE_100HZ 0x02
#define DATA_FORMAT_12BIT 0x00
#define X_OUT_L_REG 0x01
#define X_OUT_H_REG 0x02
#define Y_OUT_L_REG 0x03
#define Y_OUT_H_REG 0x04
#define Z_OUT_L_REG 0x05
#define Z_OUT_H_REG 0x06
#define TILT_THRES 45

int i2c_fd;
FILE *log_file;

void sigint_handler(int signum) {
    gpioInterruptAcknowledge(signum);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

void init_i2c() {
    i2c_fd = gpioOpen(DEVICE_ADDR, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, DEVICE_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        gpioClose(i2c_fd);
        exit(1);
    }
}

void verify_sensor_identity() {
    uint8_t who_am_i;
    if (gpioWrite(i2c_fd, WHO_AM_I_REG) < 0) {
        perror("Failed to write to WHO_AM_I register");
        gpioClose(i2c_fd);
        exit(1);
    }

    if (gpioRead(i2c_fd, &who_am_i, 1) < 0) {
        perror("Failed to read from WHO_AM_I register");
        gpioClose(i2c_fd);
        exit(1);
    }

    if (who_am_i != 0x45) {
