#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define MAG_OFFSET 1000
#define MAG_SCALE 1000
#define MAG_SENSITIVITY 0.146
#define MAG_THRESHOLD 800
#define I2C_ADDR 0x1E
#define SAMPLE_RATE 10
#define RETRY_LIMIT 3

int fd;
int log_fd;
FILE *log_file;

void sigint_handler(int signum) {
    gpiod_request_release(gpio);
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int init_i2c() {
    int ret;
    ret = gpiod_in_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", strerror(errno));
        return ret;
    }

    gpio = gpiod_in_export(NULL, "i2c-sensor");
    if (!gpio) {
        fprintf(stderr, "Failed to export GPIO for I2C: %s\n", strerror(errno));
        gpiod_exit(ret);
        return -1;
    }

    ret = gpiod_add_request(gpio, "i2c-sd-a", GPIOD_IN_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to add I2C request: %s\n", strerror(errno));
        gpiod_unexport(gpio);
        gpiod_exit(ret);
        return -1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpiod_request_free(gpio);
        gpiod_exit(ret);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus: %s\n", strerror(errno));
        close(fd);
        gpiod_request_free(gpio);
        gpiod_exit(ret);
        return -1;
    }

    return 0;
}

int read_magnetometer() {
    uint8_t data[6];
    int ret;

    for (int i = 0; i < 6; i++) {
        ret = read(fd, &data[i], 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
            return -1;
        }
    }

    int16_t x = (data[1] << 8 | data[0]) - MAG_OFFSET;
    int16_t y = (data[3] << 8 | data[2]) - MAG_OFFSET;
    int16_t z = (data[5] << 8 | data[4]) - MAG_OFFSET;

    x *= MAG_SCALE;
    y *= MAG_SCALE;
    z *= MAG_SCALE;

    double magnitude = sqrt(x * x + y * y + z * z) * MAG_SENSITIVITY;

    if (magnitude > MAG_THRESHOLD) {
        fprintf(stderr, "Metal-detector alert: %f mG\n", magnitude);
    }

    return fprintf(log_file, "%d,%d,%d\n", x, y, z);
}

int main() {
    int ret;
    gpio_context *gpio;
    int retry_count = RETRY_LIMIT;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (retry_count > 0) {
        if ((ret = init_i2c()) >= 0) {
            break;
        }
        retry_count--;
    }

    if (retry_count == 0) {
        fprintf(stderr, "Failed to initialize I2C after %d attempts.\n", RETRY_LIMIT);
        return 1;
    }

    log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        if (read_magnetometer() < 0) {
            break;
        }
        usleep(1000000 / SAMPLE_RATE);
    }

    fclose(log_file);
    gpiod_request_release(gpio);
    close(fd);
    return 0;
}

