#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define ADXL354_RESET 0x2D
#define ADXL354_STATUS 0x1D
#define ADXL354_DATAX0 0x32
#define ADXL354_DATAX1 0x33
#define ADXL354_DATAY0 0x34
#define ADXL354_DATAY1 0x35
#define ADXL364_DATAZ0 0x36
#define ADXL364_DATAZ1 0x37
#define PARTID_ADXL354 0x34

#define SPI_CLOCK 1000000
#define READ_DELAY_US 1000
#define LOG_INTERVAL_MS 100

static FILE *log_file = NULL;

void spi_init() {
    int ret;
    ret = gpiod_chip_open(&dev, "spi0");
    if (ret < 0) {
        perror("Failed to open SPI0");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_owner(dev, "spi0-ce0", "r");
    if (ret < 0) {
        perror("Failed to claim SPI0 CE0");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_value(dev, "spi0-ce0", 0);
    if (ret < 0) {
        perror("Failed to set SPI0 CE0 low");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_value(dev, "spi0-sclk", 0);
    if (ret < 0) {
        perror("Failed to set SPI0 SCLK low");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_value(dev, "spi0-mosi", 0);
    if (ret < 0) {
        perror("Failed to set SPI0 MOSI low");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_value(dev, "spi0-miso", 1);
    if (ret < 0) {
        perror("Failed to set SPI0 MISO high");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_value(dev, "spi0-cs0", 1);
    if (ret < 0) {
        perror("Failed to set SPI0 CS0 high");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_value(dev, "spi0-sclk", 1);
    if (ret < 0) {
        perror("Failed to set SPI0 SCLK high");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_set_value(dev, "spi0-mosi", 1);
    if (ret < 0) {
        perror("Failed to set SPI0 MOSI high");
        exit(EXIT_FAILURE);
    }
}

void spi_deinit() {
    gpiod_chip_set_value(dev, "spi0-ce0", 0);
    gpiod_chip_close(dev);
}

void reset_adxl354() {
    gpiod_chip_set_value(dev, "spi0-mosi", (ADXL354_RESET & 0x80));
    gpiod_chip_set_value(dev, "spi0-sclk", 1);
    gpiod_chip_set_value(dev, "spi0-sclk", 0);
    gpiod_chip_set_value(dev, "spi0-sclk", 1);
}

uint16_t read_adxl354_register(uint8_t reg) {
    uint16_t data = 0;
    gpiod_chip_set_value(dev, "spi0-mosi", (reg | 0x80));
    gpiod_chip_set_value(dev, "spi0-sclk", 1);
    gpiod_chip_set_value(dev, "spi0-sclk", 0);

    for (int i = 0; i < 8; i++) {
        gpiod_chip_set_value(dev, "spi0-sclk", 1);
        if (gpiod_chip_get_value(dev, "spi0-miso")) {
            data <<= 1;
            data |= 1;
        } else {
            data <<= 1;
        }
    }

    gpiod_chip_set_value(dev, "spi0-sclk", 1);

    return data;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = graceful_shutdown;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_init();
    log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        spi_deinit();
        return EXIT_FAILURE;
    }

    reset_adxl354();
    // Wait 1 ms
    usleep(READ_DELAY_US);

    // Clear RUN bit
    gpiod_chip_set_value(dev, "spi0-power-control", (READ_ADXL354_POWER_CONTROL & ~0x02));

    // Wait until STABLE bit is set
    while (!(READ_ADXL354_STATUS & 0x01)) {
        // Wait
    }

    // Set RUN bit
    gpiod_chip_set_value(dev, "spi0-power-control", (READ_ADXL354_POWER_CONTROL | 0x02));

    // Verify sensor presence
    uint16_t partid = read_adxl354_register(ADXL354_PARTID);
    if (partid != PARTID_ADXL354) {
        fprintf(stderr, "Invalid sensor part ID\n");
        spi_deinit();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (true) {
        int x_high = read_adxl354_register(ADXL354_DATAX0);
        int x_low = read_adxl354_register(ADXL354_DATAX1);
        int x = (x_high << 8) | x_low;

        int y_high = read_adxl354_register(ADXL354_DATAY0);
        int y_low = read_adxl354_register(ADXL354_DATAY1);
        int y = (y_high << 8) | y_low;

        int z_high = read_adxl354_register(ADXL354_DATAZ0);
        int z_low = read_adxl354_register(ADXL354_DATAZ1);
        int z = (z_high << 8) | z_low;

        int64_t acceleration[3] = {(int32_t)x, (int32_t)y, (int32_t)z};

        time_t now = time(NULL);
        struct tm tm;
        localtime_r(&now, &tm);

        fprintf(log_file, "%02d:%02d:%02d,%ld,%ld,%ld\n", tm.tm_hour, tm.tm_min, tm.tm_sec, acceleration[0], acceleration[1], acceleration[2]);

        fflush(log_file);

        sleep(LOG_INTERVAL_MS / 1000);
    }

    spi_deinit();
    fclose(log_file);
    return EXIT_SUCCESS;
}

void graceful_shutdown() {
    fprintf(stderr, "Shutting down...\n");
    spi_deinit();
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

