#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;

static void poll_sensors(void) {
    uint32_t value;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    if (gpiod_batch_process(chip) < 0) {
        fprintf(stderr, "Failed to process GPIO batch\n");
        return;
    }

    if (gpiod_in_read(sensor1_line, &value) < 0) {
        fprintf(stderr, "Failed to read sensor1\n");
        return;
    }

    if (gpiod_in_read(sensor2_line, &value) < 0) {
        fprintf(stderr, "Failed to read sensor2\n");
        return;
    }

    printf("Timestamp: %ld.%09ld, Sensor1: %d, Sensor2: %d\n",
           ts.tv_sec, ts.tv_nsec, !value, !value);
}

int main(void) {
    int ret;

    chip = gpiod_chip_open("/dev/gpiod", NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get sensor1 line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get sensor2 line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_cooked_value(sensor1_line, 0) < 0 ||
        gpiod_line_request_cooked_value(sensor2_line, 0) < 0) {
        fprintf(stderr, "Failed to request cooked value\n");
        gpiod_chip_close(chip);
        return 1;
    }

    while (true) {
        poll_sensors();
        sleep(POLL_INTERVAL_MS / 1000);
    }

    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_close(chip);

    return 0;
}

