#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <gpio.h>
#include <spidev.h>

#define ADIS16266_ADDR 0x1E
#define SPI_MODE 3
#define MSB_FIRST 1
#define CLK_DIV 8
#define READ_DELAY_MS 100000 // 100 ms

static int spi_fd;
static int chip_select;

void spi_cleanup() {
    close(spi_fd);
    gpio_free(chip_select);
}

void sigint_handler(int signum) {
    spi_cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct spi_device spi_dev;
    int ret;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    spi_dev.speed_hz = 1000000;
    spi_dev.bits_per_word = 8;
    spi_dev.mode = SPI_MODE;
    spi_dev.delay_usecs = 0;

    if ((ret = ioctl(spi_fd, SPI_IOC_WR_FRAMES, &spi_dev)) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return 1;
    }

    chip_select = gpio_request(8);
    if (chip_select < 0) {
        fprintf(stderr, "Failed to request GPIO8: %s\n", strerror(errno));
        return 1;
    }
    gpio_direction_output(chip_select, 0);

    signal(SIGINT, sigint_handler);

    while (1) {
        uint8_t addr_byte = ADIS16266_ADDR | (1 << (spi_dev.bits_per_word - 1));
        uint16_t data[2];

        gpio_write(chip_select, 0);
        if (write(spi_fd, &addr_byte, 1) != 1) {
            fprintf(stderr, "Failed to write address byte: %s\n", strerror(errno));
            break;
        }

        if (write(spi_fd, NULL, 0) != 0) {
            fprintf(stderr, "Failed to initiate SPI transfer: %s\n", strerror(errno));
            break;
        }

        if (read(spi_fd, data, 2) != 2) {
            fprintf(stderr, "Failed to read SPI data: %s\n", strerror(errno));
            break;
        }

        gpio_write(chip_select, 1);

        float x_rate = (float)data[1] << 8 | data[0];
        float y_rate = (float)(data[3] << 8 | data[2]);
        float z_rate = (float)(data[5] << 8 | data[4]);

        x_rate /= 100.0;
        y_rate /= 100.0;
        z_rate /= 100.0;

        printf("X: %.2f, Y: %.2f, Z: %.2f deg/s\n", x_rate * 0.02, y_rate * 0.02, z_rate * 0.02);

        usleep(READ_DELAY_MS);
    }

    spi_cleanup();
    return 0;
}

