    struct i2c_rdwr_ioctl_data rdwr = {
        .dx = buf,
        .nbytes = len,
    };

    if (i2c_transfer(master, &rdwr) < 0) {
        fprintf(stderr, "Failed to read LSM6DSR register\n");
        return -1;
    }

    return 0;
}

static int lsm6dsr_write_reg(struct i2c_master *master, uint8_t reg, const uint8_t *buf, size_t len) {
    struct i2c_rdwr_ioctl_data rdwr = {
        .dx = buf,
        .nbytes = len,
    };

    if (i2c_transfer(master, &rdwr) < 0) {
        fprintf(stderr, "Failed to write to LSM6DSR register\n");
        return -1;
    }

    return 0;
}

static int lsm6dsr_check_device(struct i2c_master *master, uint8_t addr) {
    uint8_t who_am_i;
    if (lsm6dsr_read_reg(master, LSM6DSR_WHO_AM_I, &who_am_i, 1) != 0) {
        return -1;
    }

    if (who_am_i != 0x53) {
        fprintf(stderr, "LSM6DSR device mismatch\n");
        return -1;
    }

    return 0;
}

static void sigint_handler(int signum) {
    printf("\nInterrupted. Cleaning up...\n");
    i2c_put(master);
    exit(0);
}

int main() {
    struct gpiod_chip chip;
    struct i2c_master *master;
    struct lsm6dsr_data data;
    int ret;

    // Initialize GPIO for I2C
    ret = gpiod_chip_load_using_name(&chip, "i2c-1");
    if (ret) {
        fprintf(stderr, "Failed to initialize I2C GPIO\n");
        return 1;
    }

    master = i2c_open_device(&chip, LSM6DSR_ADDR_ACCEL);
    if (!master) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (lsm6dsr_check_device(master, LSM6DSR_ADDR_ACCEL) != 0) {
        i2c_close(master);
        return 1;
    }

    if (lsm6dsr_check_device(master, LSM6DSR_ADDR_GYRO) != 0) {
        i2c_close(master);
        return 1;
