        // Read gyroscope data
        if (lsm6dsr_read_reg(master, 0x38, &data.gx, 1) != 0 ||
            lsm6dsr_read_reg(master, 0x3A, &data.gy, 1) != 0 ||
            lsm6dsr_read_reg(master, 0x3C, &data.gz, 1) != 0) {
            break;
        }

        printf("%d %d %d %d %d %d\n", data.ax, data.ay, data.az, data.gx, data.gy, data.gz);

        // Sleep for 100ms
        struct timespec ts = {0, 0.1 * 1000000000};
        nanosleep(&ts, NULL);
    }

    i2c_close(master);
    gpiod_chip_unload(&chip);

    return 0;
