#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>

#define FXOS8700_ADDR 0x19
#define RETRY_COUNT 3

typedef struct {
    gpiod_chip *chip;
    gpiod_context *ctx;
    gpiod_line *sda;
    gpiod_line *scl;
    uint8_t *buffer;
} i2c_context;

static int i2c_read(i2c_context *ctx, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_rdwr_ioctl_data rd_wr;
    rd_wr.dx = reg;
    rd_wr.flags = 0;
    rd_wr.len = len;
    rd_wr.buffer = (unsigned long)buf;

    int r = ioctl(ctx->fd, GPIO_I2C_RDWR, &rd_wr);
    if (r < 0) {
        if (errno == EAGAIN || errno == EINTR)
            return -1; // Retry on transient errors
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write(i2c_context *ctx, uint8_t reg, const uint8_t *buf, size_t len) {
    struct i2c_rdwr_ioctl_data rd_wr;
    rd_wr.dx = reg;
    rd_wr.flags = I2C_M_RD;
    rd_wr.len = len;
    rd_wr.buffer = (unsigned long)buf;

    int r = ioctl(ctx->fd, GPIO_I2C_RDWR, &rd_wr);
    if (r < 0) {
        if (errno == EAGAIN || errno == EINTR)
            return -1; // Retry on transient errors
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(i2c_context *ctx, int bus, int sda, int scl) {
    ctx->chip = gpiod_chip_open(NULL, "i2c-" STR(bus));
    if (!ctx->chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return -1;
    }

    ctx->ctx = gpiod_chip_get_context(ctx->chip);
    if (!ctx->ctx) {
        fprintf(stderr, "Failed to get context\n");
        gpiod_chip_put(ctx->chip);
        return -1;
    }

    ctx->sda = gpiod_chip_get_line(ctx->chip, sda);
    if (!ctx->sda) {
        fprintf(stderr, "Failed to get SDA line\n");
        gpiod_chip_put(ctx->chip);
        return -1;
    }

    ctx->scl = gpiod_chip_get_line(ctx->chip, scl);
    if (!ctx->scl) {
        fprintf(stderr, "Failed to get SCL line\n");
        gpiod_chip_put(ctx->chip);
        return -1;
    }

    ctx->buffer = malloc(6);
    if (!ctx->buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        gpiod_chip_put(ctx->chip);
        return -1;
    }

    int fd = gpiod_line_get_fd(ctx->sda);
    if (fd < 0) {
        fprintf(stderr, "Failed to get file descriptor\n");
        free(ctx->buffer);
        gpiod_chip_put(ctx->chip);
        return -1;
    }
    ctx->fd = fd;

    return 0;
}

static void cleanup_i2c(i2c_context *ctx) {
    free(ctx->buffer);
    gpiod_line_put(ctx->sda);
    gpiod_line_put(ctx->scl);
    gpiod_chip_put(ctx->chip);
    close(ctx->fd);
    gpiod_context_put(ctx->ctx);
}

static uint8_t i2c_read_reg(i2c_context *ctx, uint8_t reg) {
    uint8_t buf[1];
    if (i2c_read(ctx, reg, buf, 1) < 0)
        return 0;
    return buf[0];
}

static void i2c_print_data(i2c_context *ctx, uint8_t *data) {
    printf("Accelerometer: X=%d, Y=%d, Z=%d\n", data[0], data[1], data[2]);
    printf("Accelerometer: X=%d, Y=%d, Z=%d\n", data[3], data[4], data[5]);
    printf("Magnetometer: X=%d, Y=%d, Z=%d\n", data[6], data[7], data[8]);
    printf("Magnetometer: X=%d, Y=%d, Z=%d\n", data[9], data[10], data[11]);
}

static void sigint_handler(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    cleanup_i2c(&i2c_ctx);
    exit(0);
}

int main() {
    i2c_context i2c_ctx;

    if (init_i2c(&i2c_ctx, 1, 2, 3)) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    if (i2c_read(&i2c_ctx, 0x00, i2c_ctx.buffer, 1) < 0) {
        fprintf(stderr, "Device not found or ID mismatch\n");
        cleanup_i2c(&i2c_ctx);
        return 1;
    }

    // Initialize sensor (if needed)

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (i2c_read(&i2c_ctx, 0x28, i2c_ctx.buffer, 12) < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            for (int i = 0; i < RETRY_COUNT; i++) {
                if (i2c_read(&i2c_ctx, 0x28, i2c_ctx.buffer, 12) >= 0)
                    break;
                sleep(1);
            }
            if (i2c_read(&i2c_ctx, 0x28, i2c_ctx.buffer, 12) < 0) {
                fprintf(stderr, "Failed to read after retries\n");
                break;
            }
        }

        i2c_print_data(&i2c_ctx, i2c_ctx.buffer);
        usleep(100000);
    }

    cleanup_i2c(&i2c_ctx);
    return 0;
}

