#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <wiringPiI2C.h>

#define ADXL345_ADDR 0x53
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_MS 100

struct tilt_event {
    time_t timestamp;
    float tilt_angle;
};

static FILE *log_file = NULL;

static int log_tilt_event(const struct tilt_event *event) {
    if (log_file == NULL) {
        return -1;
    }

    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%F %T", localtime(&event->timestamp));

    if (fprintf(log_file, "%s, Tilt Angle: %.2f degrees\n", timestamp_str, event->tilt_angle) < 0) {
        return -1;
    }

    return 0;
}

static float read_tilt_angle(int fd) {
    uint8_t data[6];
    if (wiringPiI2C_rdwr(fd, true, (void *)data, 6) < 0) {
        return NAN;
    }

    float x = (float)((data[0] << 8 | data[1]) & 0x0FFF);
    float y = (float)((data[2] << 8 | data[3]) & 0x0FFF);
    float z = (float)((data[4] << 8 | data[5]) & 0x0FFF);

    float angle = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;

    return (x == 0 && z == 0) ? 0 : angle;
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    int adxl_fd = -1;
    struct tilt_event event;

    if (gpiod_chip_open(&chip, "i2c-0") < 0) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return 1;
    }

    adxl_fd = wiringPiI2CSetup(ADXL345_ADDR);
    if (adxl_fd < 0) {
        fprintf(stderr, "Failed to initialize ADXL345 sensor\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    if (log_file != NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            close(adxl_fd);
            gpiod_chip_close(&chip);
            return 1;
        }
    }

    while (true) {
        event.tilt_angle = read_tilt_angle(adxl_fd);

        if (event.tilt_angle != NAN && fabs(event.tilt_angle) > TILT_THRESHOLD) {
            event.timestamp = time(NULL);
            if (log_tilt_event(&event) < 0) {
                fprintf(stderr, "Failed to log tilt event\n");
            }
        }

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    fclose(log_file);
    close(adxl_fd);
    gpiod_chip_close(&chip);

    return 0;
}

