    float angle = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;

    return (x == 0 && z == 0) ? 0 : angle;
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    int adxl_fd = -1;
    struct tilt_event event;

    if (gpiod_chip_open(&chip, "i2c-0") < 0) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return 1;
    }

    adxl_fd = wiringPiI2CSetup(ADXL345_ADDR);
    if (adxl_fd < 0) {
        fprintf(stderr, "Failed to initialize ADXL345 sensor\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    if (log_file != NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            close(adxl_fd);
            gpiod_chip_close(&chip);
            return 1;
        }
    }

    while (true) {
        event.tilt_angle = read_tilt_angle(adxl_fd);

        if (event.tilt_angle != NAN && fabs(event.tilt_angle) > TILT_THRESHOLD) {
            event.timestamp = time(NULL);
            if (log_tilt_event(&event) < 0) {
                fprintf(stderr, "Failed to log tilt event\n");
            }
        }

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    fclose(log_file);
    close(adxl_fd);
    gpiod_chip_close(&chip);

    return 0;
}
```

This code reads acceleration data from an ADXL345 accelerometer over I2C, evaluates the tilt angle, and logs the event to `/var/log/tilt_events.log` whenever the tilt exceeds a threshold of 30.0 degrees. It performs this sampling and logging cycle every 100 ms. The implementation includes robust error handling for I2C communication failures, sensor-absent conditions, and bus-error paths. It also guarantees clean resource release on all exit paths, including proper handling of a Ctrl+C interrupt signal.

