#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_DURATION_S 5
#define PAUSE_BETWEEN_WINDOWS_S 1

volatile int high_count = 0;
int threshold;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

void setup_gpio() {
    if (gpioInitialize() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(1);
    }

    gpioSetPullUpDown(GPIO_PIN, PI_PULL_UP);
}

int read_sensor() {
    int value;
    if (gpioRead(GPIO_PIN, &value) < 0) {
        fprintf(stderr, "Failed to read GPIO\n");
        return -1;
    }
    return value;
}

void monitor_sensor(int duration_s) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (duration_s > 0) {
        int value = read_sensor();
        if (value == 0) {
            high_count++;
        } else {
            high_count = 0;
        }

        duration_s -= SAMPLE_INTERVAL_US / 1000;
        usleep(SAMPLE_INTERVAL_US);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *end;
    threshold = strtol(argv[1], &end, 10);
    if (*end != '\0' || threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
        return 1;
    }

    setup_gpio();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    printf("Monitoring KY-038 sound sensor...\n");
    while (true) {
        monitor_sensor(WINDOW_DURATION_S * 1000);
        int high_count_in_window = high_count;
        high_count = 0;

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        time_t current_time = now.tv_sec;
        struct tm *local_time = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        if (high_count_in_window > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s STATUS\n", timestamp);
        }

        sleep(PAUSE_BETWEEN_WINDOWS_S);
    }

    gpioTerminate();
    return 0;
}

