#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27
#define MAX_ATTEMPTS 3
#define CODE_LENGTH 6
#define MIN_CODE 100000
#define MAX_CODE 999999

volatile sig_atomic_t sigint_flag = 0;

int main(int argc, char *argv[]) {
    struct gpiod_chip chip;
    struct gpiod_line line_a, line_b;
    FILE *log_file;
    char input[CODE_LENGTH + 1];
    char generated_code[CODE_LENGTH + 1];
    int attempt = 0;

    if (gpiod_chip_open(&chip, "GPIO17") || gpiod_chip_open(&chip, "GPIO27")) {
        fprintf(stderr, "Failed to initialize GPIO chips\n");
        return 1;
    }

    if (gpiod_chip_get_line(&chip, "GPIO17", 0, &line_a) || gpiod_chip_get_line(&chip, "GPIO27", 0, &line_b)) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(&chip);
        return 1;
    }

    gpiod_line_export(line_a, NULL);
    gpiod_line_export(line_b, NULL);

    gpiod_line_set_direction(line_a, GPIO_DIR_OUT);
    gpiod_line_set_direction(line_b, GPIO_DIR_OUT);

    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);

    if (!(log_file = fopen("access_log.txt", "a"))) {
        fprintf(stderr, "Failed to open access_log.txt\n");
        gpiod_line_unexport(line_a);
        gpiod_line_unexport(line_b);
        gpiod_chip_close(&chip);
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < CODE_LENGTH; ++i) {
        generated_code[i] = '0' + rand() % 10;
    }
    generated_code[CODE_LENGTH] = '\0';
    printf("Security code: %s\n", generated_code);
    fflush(stdout);

    while (1) {
        if (sigint_flag) {
            break;
        }

        if (fgets(input, CODE_LENGTH + 1, stdin)) {
            if (sscanf(input, "%*s%d", &attempt) != 1) {
                fprintf(stderr, "Invalid input, please enter a number\n");
                continue;
            }

            if (attempt > MAX_ATTEMPTS) {
                printf("Access denied\n");
                break;
            }

            if (strcmp(input + 2, generated_code) == 0) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(input, CODE_LENGTH + 1, "%Y-%m-%d %H:%M:%S", tm_info);
                fprintf(log_file, "%s,%s\n", input, generated_code);
                printf("Access granted\n");
                attempt = 0;
            } else {
                printf("Access denied\n");
            }
        }
    }

    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);
    gpiod_line_unexport(line_a);
    gpiod_line_unexport(line_b);
    gpiod_chip_close(&chip);
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Rest of the main function remains the same

    return 0;
}

