#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>
#include <i2c/client.h>

#define DEV_NAME "i2c-1"
#define BH1750_ADDR 0x23
#define LOG_FILE "light_log.txt"
#define MAX_READ_TIME 180000 // 180 ms

struct i2c_client *client;
int fd;

static int bh1750_read(uint8_t reg, uint16_t *data) {
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_msg messages[] = {
        { .addr = BH1750_ADDR, .flags = 0, .len = 1, .buf = reg },
        { .addr = BH1750_ADDR, .flags = I2C_M_RD, .len = 2, .buf = data }
    };

    rdwr.msgs = messages;
    rdwr.nmsgs = 2;

    return ioctl(fd, I2C_RDWR, &rdwr);
}

static void cleanup() {
    close(fd);
    i2c_release(client);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    int ret;

    gpiod_chip_init();
    ret = gpiod_chip_get_by_label(&chip, DEV_NAME, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to get chip %s\n", DEV_NAME);
        return ret;
    }

    ret = gpiod_chip_get_line(&line, &chip, "open-drain", 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to get line %d\n", 2);
        return ret;
    }

    ret = gpiod_line_export(&line, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export line %d\n", 2);
        return ret;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    client = i2c_new_device();
    i2c_set_hdwr_addr(client, BH1750_ADDR);
    i2c_open(client);

    while (1) {
        uint16_t lux_value;
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        if (bh1750_read(0x00, &lux_value) < 0) {
            fprintf(stderr, "Failed to read from BH1750\n");
            break;
        }

        FILE *file = fopen(LOG_FILE, "a");
        if (!file) {
            fprintf(stderr, "Failed to open log file\n");
            break;
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(file, "Timestamp: %s, Lux: %u\n", timestamp, lux_value);
        fclose(file);

        usleep(5000000); // 5 seconds
    }

    cleanup();
    gpiod_line_unexport(&line);
    gpiod_chip_put(&chip);
    return 0;
}

static void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, cleaning up...\n");
    cleanup();
    exit(signum);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    return main();
}

