#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <wiringPiI2C.h>
#include <wiringPiSetup.h>
#include <wiringPiI2C.c>

#define MPR121_ADDR  0x5A
#define PWM_PIN     18
#define I2C_BUS     1
#define PORT        12345
#define SECRET      "MySecretKey"
#define SAMPLE_RATE 20
#define PLAY_DURATION 5

int i2c_fd;
int socket_fd;
int pwm_freq;
int touch_values[12];
FILE *log_file;

void play_tone() {
    while (1) {
        if (pwm_freq > 0) {
            gpioSetMode(PWM_PIN, GPIO_OUTPUT);
            gpioWrite(PWM_PIN, 1);
            usleep(1000000 / (2 * pwm_freq));
            gpioWrite(PWM_PIN, 0);
            usleep(1000000 / (2 * pwm_freq));
        }
        if (--PLAY_DURATION == 0)
            break;
        sleep(SAMPLE_RATE);
    }
}

void log_frequency(int freq) {
    if (fprintf(log_file, "%d\n", freq) < 0) {
        perror("Error writing to log file");
        exit(EXIT_FAILURE);
    }
}

void handle_command(char *cmd) {
    if (strncmp(cmd, "MOTION_DETECTED:", 16) != 0 || strstr(cmd, SECRET) == NULL)
        return;

    pwm_freq = atoi(strchr(cmd, ':') + 1);
    log_frequency(pwm_freq);
    play_tone();
}

int main() {
    gpiod_context ctx;
    int r;

    // Initialize GPIO
    if (r != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return r;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    // Initialize MPR121
    wireI2CBus(I2C_BUS);
    if (wiringPiI2CSetup(MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        close(i2c_fd);
        return -1;
    }
    wiringPiI2CReset(MPR121_ADDR);
    wiringPiI2CWriteReg8(MPR121_ADDR, 0x00, 0x06); // Electrode config

    // Initialize PWM
    gpioSetMode(PWM_PIN, GPIO_OUTPUT);

    // Open socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Failed to create socket\n");
        close(i2c_fd);
        return -1;
    }

    // Bind and listen
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(PORT);

