void play_tone() {
    while (1) {
        if (pwm_freq > 0) {
            gpioSetMode(PWM_PIN, GPIO_OUTPUT);
            gpioWrite(PWM_PIN, 1);
            usleep(1000000 / (2 * pwm_freq));
            gpioWrite(PWM_PIN, 0);
            usleep(1000000 / (2 * pwm_freq));
        }
        if (--PLAY_DURATION == 0)
            break;
        sleep(SAMPLE_RATE);
    }
}

