#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c/i2c.h>

#define LSM303_ADDR  0x18
#define SAMPLING_INTERVAL 100000 // 100 ms in microseconds
#define LED_GPIO  17

struct lsm303_data {
    int16_t x, y, z;
};

static int led_fd = -1;
static int i2c_fd = -1;
static gpiod_chip *chip;

void handle_sigint_sigterm(int signum) {
    if (led_fd >= 0) {
        gpiod_bulk_stop(led_fd);
        close(led_fd);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    exit(signum == SIGINT ? 0 : 1);
}

int init_i2c(void) {
    int ret;
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    ret = i2c_write(i2c_fd, LSM303_ADDR, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to LSM303, error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int read_lsm303(struct lsm303_data *data) {
    int ret;
    uint8_t buf[6];

    ret = i2c_read(i2c_fd, LSM303_ADDR, buf, 6);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from LSM303, error: %s\n", strerror(errno));
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int init_led(void) {
    int ret;

    ret = gpiod_in_create_from_line("GPIO17", "PIO17", LED_GPIO, GP_DIR_OUT, &led_fd);
    if (ret < 0) {
        perror("Failed to create GPIO line for LED");
        return -1;
    }

    ret = gpiod_bulk_set(led_fd, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set initial LED state, error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    struct lsm303_data data;
    int ret;

    sa.sa_handler = handle_sigint_sigterm;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    if (init_i2c() < 0) {
        return -1;
    }

    if (init_led() < 0) {
        return -1;
    }

    while (1) {
        ret = read_lsm303(&data);
        if (ret < 0) {
            continue;
        }

        int brightness = abs(data.z);
        brightness = (brightness > 2047) ? 2047 : brightness;
        brightness = (brightness * 10) / 2047; // Scale brightness to 0-100

        ret = gpiod_bulk_write(led_fd, brightness);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED brightness, error: %s\n", strerror(errno));
            break;
        }

        usleep(SAMPLING_INTERVAL);
    }

    gpiod_bulk_stop(led_fd);
    close(led_fd);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

