#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define NUM_SAMPLES 100
#define SAMPLES_PER_SEC 10
#define PRINT_INTERVAL_MS 500

struct sample {
    int16_t x, y, z;
};

struct sample samples[NUM_SAMPLES];
int sample_index = 0;
uint16_t x_offset = 0, y_offset = 0, z_offset = 0;
uint16_t sample_count = 0;

void signal_handler(int signum) {
    printf("\nReceived signal %d, cleaning up...\n", signum);
    gpiod_wm_stop(i2c_dev);
    gpiod_destroy(i2c_dev);
    exit(signum);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line i2c_sda;
    struct gpiod_line i2c_scl;
    struct gpiod_dev i2c_dev;

    gpiod_chip_init(&chip);
    gpiod_chip_register_offset(&chip, I2C_BUS);

    i2c_sda = gpiod_chip_get_line(&chip, "sda");
    i2c_scl = gpiod_chip_get_line(&chip, "scl");

    if (gpiod_line_request_cooked(&i2c_sda, &i2c_scl) < 0 ||
        gpiod_line_request_cooked(&i2c_scl, &i2c_sda) < 0) {
        fprintf(stderr, "Failed to request I2C lines\n");
        return 1;
    }

    i2c_dev.chip = &chip;
    i2c_dev.lines = &i2c_sda;
    i2c_dev.devm = NULL;
    i2c_dev.flags = 0;

    if (gpiod_dev_create(&i2c_dev) < 0) {
        fprintf(stderr, "Failed to create I2C device\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpiod_dev_start(i2c_dev) < 0) {
        fprintf(stderr, "Failed to start I2C device\n");
        return 1;
    }

    // Initialize HMC5883L
    uint8_t data[6] = {0};
    data[0] = 0x00; // Mode
    data[1] = 0x00; // Data length
    data[2] = 0x00; // Continuous measurement mode
    data[3] = 0x00; // Rate
    data[4] = 0x00; // Filter
    data[5] = 0x00; // End

    if (gpiod_write(i2c_dev, data, 6) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return 1;
    }

    while (1) {
        data[0] = 0x08; // Read data
        if (gpiod_write(i2c_dev, data, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            break;
        }

        uint8_t len = 6;
        if (gpiod_read(i2c_dev, data, len) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        samples[sample_index].x = (int16_t)((data[1] << 8) | data[0]);
        samples[sample_index].y = (int16_t)((data[3] << 8) | data[2]);
        samples[sample_index].z = (int16_t)((data[5] << 8) | data[4]);

        sample_count++;
        x_offset += samples[sample_index].x;
        y_offset += samples[sample_index].y;
        z_offset += samples[sample_index].z;

        if (sample_count >= NUM_SAMPLES) {
            x_offset /= sample_count;
            y_offset /= sample_count;
            z_offset /= sample_count;
            sample_count = 0;
        }

        sample_index = (sample_index + 1) % NUM_SAMPLES;

        if (sample_index == 0) {
            printf("X: %d, Y: %d, Z: %d\n",
                   samples[(sample_index + NUM_SAMPLES - 1) % NUM_SAMPLES].x - x_offset,
                   samples[(sample_index + NUM_SAMPLES - 1) % NUM_SAMPLES].y - y_offset,
                   samples[(sample_index + NUM_SAMPLES - 1) % NUM_SAMPLES].z - z_offset);
        }

        usleep(PRINT_INTERVAL_MS * 1000);
    }

    gpiod_dev_stop(i2c_dev);
    gpiod_dev_free(i2c_dev);
    gpiod_chip_unregister_offset(&chip);
    gpiod_chip_free(&chip);

    return 0;
}

