#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c.h>

#define BUFFER_SIZE 64
#define INT1_GPIO 23
#define INT1_PIN 16
#define LSM303D_ADDR 0x19
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1 0x20
#define LSM303D_INT_CONFIG 0x21
#define LSM303D_INT_SOURCE 0x07
#define LSM303D_THS_L 0x03
#define LSM303D_THS_H 0x02
#define LSM303D_DURATION 0x00
#define LSM303D_LSB_TO_MG 0.061

int buffer[BUFFER_SIZE][3];
int buffer_head = 0;

void init_i2c() {
    int fd = i2c_open(LSM303D_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(1);
    }

    if (i2c_rdwr(fd, &LSM303D_WHO_AM_I, 1, NULL, 0, I2C_RDWR) != 1) {
        fprintf(stderr, "Failed to read device identity register\n");
        i2c_close(fd);
        exit(1);
    }

    i2c_close(fd);
}

void init_gpio() {
    struct gpiod_chip chip;
    struct gpiod_line line;

    if (gpiod_chip_open(&chip, INT1_GPIO) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
