#include <unistd.h>
#include <signal.h>
#include <gpio.h>

#define SOLENOID1_GPIO 17
#define SOLENOID2_GPIO 27
#define ACTIVE_SOLENOID 1
#define DELAY_MS 500

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

int main(void) {
    struct gpio_target target1, target2;
    struct gpio_context *ctx1, *ctx2;
    int ret;

    // Initialize GPIO context
    ctx1 = gpio_context_new();
    if (!ctx1) {
        fprintf(stderr, "Failed to create GPIO context\n");
        return 1;
    }

    ret = gpio_request_available(ctx1, SOLENOID1_GPIO, GPIOD_OUT_PP);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO%d\n", SOLENOID1_GPIO);
        gpio_context_free(ctx1);
        return 1;
    }

    ret = gpio_set_func(ctx1, SOLENOID1_GPIO, GPIOD_ACTIVE_HIGH);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO%d function\n", SOLENOID1_GPIO);
        gpio_release(ctx1, SOLENOID1_GPIO);
        gpio_context_free(ctx1);
        return 1;
    }

    // Initialize GPIO context for the second solenoid
    ctx2 = gpio_context_new();
    if (!ctx2) {
        fprintf(stderr, "Failed to create GPIO context\n");
        gpio_release(ctx1, SOLENOID1_GPIO);
        gpio_context_free(ctx1);
        return 1;
    }

    ret = gpio_request_available(ctx2, SOLENOID2_GPIO, GPIOD_OUT_PP);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO%d\n", SOLENOID2_GPIO);
        gpio_context_free(ctx1);
        gpio_context_free(ctx2);
        return 1;
    }

    ret = gpio_set_func(ctx2, SOLENOID2_GPIO, GPIOD_ACTIVE_HIGH);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO%d function\n", SOLENOID2_GPIO);
        gpio_release(ctx2, SOLENOID2_GPIO);
        gpio_context_free(ctx1);
        gpio_context_free(ctx2);
        return 1;
    }

    // Set both lines LOW before entering the main loop
    gpio_put(ctx1, SOLENOID1_GPIO, 0);
    gpio_put(ctx2, SOLENOID2_GPIO, 0);

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (!sigint_received) {
        // Activate the current solenoid and switch to the other
        gpio_put(ctx1, SOLENOID1_GPIO, ACTIVE_SOLENOID);
        gpio_put(ctx2, SOLENOID2_GPIO, 0);
        ACTIVE_SOLENOID = 2 - ACTIVE_SOLENOID;

        nanosleep(&delay, NULL);
    }

    // Clean up and exit
    gpio_put(ctx1, SOLENOID1_GPIO, 0);
    gpio_put(ctx2, SOLENOID2_GPIO, 0);
    gpio_release(ctx1, SOLENOID1_GPIO);
    gpio_release(ctx2, SOLENOID2_GPIO);
    gpio_context_free(ctx1);
    gpio_context_free(ctx2);

    return 0;
}

