#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SERIAL0 "/dev/serial0"
#define SERIAL1 "/dev/serial1"
#define GPIO_LOCK1 17
#define GPIO_LOCK2 27
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"

static const struct gpiod_chip_spec gpiod_chip_specs[] = {
    {GPIO_LOCK1, "lock1"},
    {GPIO_LOCK2, "lock2"},
};

static int gpio_init(void) {
    struct gpiod_chip *chip;
    int ret;

    ret = gpiod_chip_open(&chip, gpiod_chip_specs, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library: %s\n", strerror(errno));
        return ret;
    }

    return 0;
}

static void gpio_cleanup(void) {
    struct gpiod_chip *chip;

    gpiod_chip_close(chip);
}

static int uart_open(const char *path, int *fd) {
    *fd = open(path, O_RDONLY | O_NOCTTY | O_NDELAY);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open UART %s: %s\n", path, strerror(errno));
        return -1;
    }

    struct fcntl fh;
    fh.val = 0;
    fh.cmd = F_SETFL;
    fh.flags = O_NONBLOCK;
    fcntl(*fd, fh.cmd, &fh.val);

    return 0;
}

static void uart_close(int fd) {
    close(fd);
}

static int uart_read(int fd, char *buf, size_t len) {
    struct timeval tv;
    fd_set rfds;

    tv.tv_sec = 5;
    tv.tv_usec = 0;

    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    if (select(fd + 1, &rfds, NULL, NULL, &tv) > 0 && FD_ISSET(fd, &rfds)) {
        return read(fd, buf, len);
    }

    return -1;
}

static void sigint_handler(int signum) {
    (void)signum;
    gpio_cleanup();
    exit(0);
}

static void sigterm_handler(int signum) {
    (void)signum;
    gpio_cleanup();
    exit(0);
}

static int constant_time_strcmp(const char *s1, const char *s2) {
    int result = 1;

    while (result && *s1 && *s2) {
        result = (*s1++) == (*s2++);
    }

    return !result;
}

int main(void) {
    int serial0_fd, serial1_fd;
    char code0[CODE_LENGTH + 1], code1[CODE_LENGTH + 1];
    int ret;

    if (gpio_init() < 0) {
        return 1;
    }

    if (uart_open(SERIAL0, &serial0_fd) < 0) {
        return 1;
    }

    if (uart_open(SERIAL1, &serial1_fd) < 0) {
        uart_close(serial0_fd);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        memset(code0, 0, CODE_LENGTH + 1);
        memset(code1, 0, CODE_LENGTH + 1);

        int r0 = uart_read(serial0_fd, code0, CODE_LENGTH);
        int r1 = uart_read(serial1_fd, code1, CODE_LENGTH);

        if (r0 < 0) {
            continue;
        } else if (r1 < 0) {
            uart_close(serial0_fd);
            return 1;
        }

        if (!constant_time_strcmp(code0, EXPECTED_CODE) || !constant_time_strcmp(code1, EXPECTED_CODE)) {
            continue;
        }

        if (constant_time_strcmp(code0, EXPECTED_CODE) == 0 && constant_time_strcmp(code1, EXPECTED_CODE) == 0) {
            gpiod_chip_set(gpiod_chip_specs[0], "lock1", 1);
            gpiod_chip_set(gpiod_chip_specs[1], "lock2", 1);
            sleep(2);
            gpiod_chip_set(gpiod_chip_specs[0], "lock1", 0);
            gpiod_chip_set(gpiod_chip_specs[1], "lock2", 0);
        }
    }

    gpio_cleanup();
    uart_close(serial0_fd);
    uart_close(serial1_fd);
    return 0;
}

