static bool relay_on = false;
static bool continuous_motion = false;
static time_t motion_start_time = 0;

void sigint_handler(int signum) {
    syslog(LOG_INFO, "Received SIGINT, initiating clean shutdown...");
    clean_shutdown();
    exit(0);
}

void sigterm_handler(int signum) {
    syslog(LOG_INFO, "Received SIGTERM, initiating clean shutdown...");
    clean_shutdown();
    exit(0);
}

void clean_shutdown() {
    if (relay_on) {
        turn_off_relay();
    }
    gpiod_chip_unrequest(chip);
    gpiod_close(chip);
    closelog();
}

void setup_gpio() {
    int ret;

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO bus");
        goto error;
    }

    ret = gpiod_chip_request_lines(chip, &pir_line_spec, &relay_line_spec, NULL);
    if (ret) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        goto error;
    }

    pir_line = gpiod_line_get(pir_line_spec);
    relay_line = gpiod_line_get(relay_line_spec);

    if (gpiod_line_get_value(pir_line) == 1) {
        motion_detected = true;
    }

    syslog(LOG_INFO, "GPIO setup completed");

error:
    if (ret < 0) {
        syslog(LOG_ERR, "Error during GPIO setup");
        clean_shutdown();
        exit(EXIT_FAILURE);
    }
}

void poll_pir_sensor() {
    int ret;
    struct timespec next_poll;

    clock_gettime(CLOCK_MONOTONIC, &next_poll);
    next_poll.tv_sec += POLL_INTERVAL_MS / 1000;

    while (true) {
        ret = gpiod_line_read(pir_line);
        if (ret < 0) {
            syslog(LOG_ERR, "Error reading PIR sensor");
            break;
        }

        if (gpiod_line_get_value(pir_line) == 1) {
            if (!motion_detected) {
                syslog(LOG_INFO, "Motion detected");
                motion_detected = true;
                continuous_motion = false;
                motion_start_time = time(NULL);
            }

            if (continuous_motion) {
                time_t current_time = time(NULL);
                if (difftime(current_time, motion_start_time) > MOTION_THRESHOLD_S) {
                    syslog(LOG_WARNING, "Potential malfunction: Continuous motion detected for more than 10 seconds");
                    trigger_failsafe();
                }
            }
        } else {
            if (motion_detected) {
                continuous_motion = true;
                motion_detected = false;
            }
        }

        if (!relay_on) {
            turn_on_relay();
        }

        if (relay_on) {
            turn_off_relay();
        }

        if (next_poll.tv_sec <= time(NULL)) {
            break;
        }

        nanosleep(&next_poll, NULL);
    }
}

void turn_on_relay() {
    if (gpiod_line_write(relay_line, 1) < 0) {
        syslog(LOG_ERR, "Error turning on relay");
    }
    relay_on = true;
}

void turn_off_relay() {
    if (gpiod_line_write(relay_line, 0) < 0) {
        syslog(LOG_ERR, "Error turning off relay");
    }
    relay_on = false;
}

void trigger_failsafe() {
    turn_off_relay();
    syslog(LOG_WARNING, "Triggering failsafe: De-energizing relay");
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    setup_gpio();
    poll_pir_sensor();

    return 0;
}

