#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <libgpio.h>

#define RELAY_PINS {4, 17, 27, 22}
#define CYCLE_DURATION_SEC 300
#define PAUSE_DURATION_SEC 60
#define TIMER_INTERVAL_SEC 60

volatile sig_atomic_t stop_irrigation = 0;

void sigint_handler(int signum) {
    stop_irrigation = 1;
}

void setup_relays(gpiod_chip *chip) {
    for (size_t i = 0; i < ARRAY_SIZE(RELAY_PINS); i++) {
        int pin = RELAY_PINS[i];
        gpiod_line_request_each(&chip->chip, &pin, "irrigation_relay", GPIOD_INOUT, NULL);
        if (gpiod_line_get_value(&chip->chip, &pin) == -1) {
            syslog(LOG_ERR, "Failed to initialize relay %d", pin);
            exit(EXIT_FAILURE);
        }
        gpiod_line_set_value(&chip->chip, &pin, 1); // Set relay to OFF (HIGH)
    }
}

void activate_relay(gpiod_chip *chip, int relay_num) {
    int pin = RELAY_PINS[relay_num];
    gpiod_line_set_value(&chip->chip, &pin, 0); // Set relay to ON (LOW)
    syslog(LOG_INFO, "irrigation_system: Relay %d activated", pin);
}

void deactivate_relay(gpiod_chip *chip, int relay_num) {
    int pin = RELAY_PINS[relay_num];
    gpiod_line_set_value(&chip->chip, &pin, 1); // Set relay to OFF (HIGH)
    syslog(LOG_INFO, "irrigation_system: Relay %d deactivated", pin);
}

int main(int argc, char *argv[]) {
    gpiod_chip *chip;
    struct timespec timer_interval, remaining_time;
    int relay_index = 0;

    // Initialize syslog
    openlog("irrigation_system", LOG_PID, LOG_DAEMON);

    // Initialize GPIO
    if (gpiod_chip_open(&chip, "GPIO") == -1) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    if (setup_relays(chip) == -1) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up timer
    clock_gettime(CLOCK_MONOTONIC, &timer_interval);
    timer_interval.tv_sec -= timer_interval.tv_sec % TIMER_INTERVAL_SEC;

    while (!stop_irrigation) {
        clock_gettime(CLOCK_MONOTONIC, &remaining_time);
        if (remaining_time.tv_sec < timer_interval.tv_sec) {
            nanosleep(&remaining_time, NULL);
            continue;
        }

        activate_relay(chip, relay_index);
        syslog(LOG_INFO, "irrigation_system: Starting irrigation cycle for Relay %d", RELAY_PINS[relay_index]);

        // Wait for 5 minutes
        for (int i = 0; i < CYCLE_DURATION_SEC; i += TIMER_INTERVAL_SEC) {
            if (i % TIMER_INTERVAL_SEC == 0) {
                syslog(LOG_INFO, "irrigation_system: %d seconds remaining", CYCLE_DURATION_SEC - i);
            }
            nanosleep(&timer_interval, NULL);
        }

        deactivate_relay(chip, relay_index);
        syslog(LOG_INFO, "irrigation_system: Finished irrigation cycle for Relay %d", RELAY_PINS[relay_index]);

        relay_index = (relay_index + 1) % ARRAY_SIZE(RELAY_PINS);
        if (relay_index == 0) {
            // Wait for 1 minute before activating the next relay
            nanosleep(&timer_interval, NULL);
        }
    }

    // Deactivate all relays
    for (size_t i = 0; i < ARRAY_SIZE(RELAY_PINS); i++) {
        deactivate_relay(chip, i);
    }

    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

