#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <stdbool.h>
#include <string.h>

#define BUFFER_SIZE 1024
#define I2C_ADDR 0x68
#define SAMPLE_RATE 100
#define SYSFS_PATH "/sys/kernel/mpu6050_accel/latest"

typedef struct {
    int16_t accel_x[BUFFER_SIZE];
    int16_t accel_y[BUFFER_SIZE];
    int16_t accel_z[BUFFER_SIZE];
    int head;
    int tail;
} AccelBuffer;

AccelBuffer buffer;
int i2c_fd;
char *sysfs_file;

void init_buffer() {
    buffer.head = buffer.tail = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer.accel_x[i] = 0;
        buffer.accel_y[i] = 0;
        buffer.accel_z[i] = 0;
    }
}

int read_accel(int16_t *ax, int16_t *ay, int16_t *az) {
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C file descriptor is not initialized.\n");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and claim dynamic device address");
        return -1;
    }

    uint8_t buf[14];
    if (read(i2c_fd, buf, 14) != 14) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *ax = (buf[1] << 8) | buf[2];
    *ay = (buf[3] << 8) | buf[4];
    *az = (buf[5] << 8) | buf[6];

    return 0;
}

void write_sysfs(int16_t ax, int16_t ay, int16_t az) {
    if (sysfs_file == NULL) {
        return;
    }

    char str[32];
    snprintf(str, sizeof(str), "%d %d %d", ax, ay, az);
    if (write(fileno(fopen(SYSFS_PATH, "w")), str, strlen(str) + 1) != (ssize_t)strlen(str) + 1) {
        perror("Failed to write to sysfs file");
    }
}

void *timer_callback(void *arg) {
    AccelBuffer *b = (AccelBuffer *)arg;
    int16_t ax, ay, az;

    while (1) {
        if (read_accel(&ax, &ay, &az) < 0) {
            break;
        }

        b->accel_x[b.head] = ax;
        b->accel_y[b.head] = ay;
        b->accel_z[b.head] = az;

        b->head = (b->head + 1) % BUFFER_SIZE;

        write_sysfs(ax, ay, az);

        usleep(10000000 / SAMPLE_RATE);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    init_buffer();

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (gpiod_export(NULL) < 0) {
        perror("Failed to export GPIOs");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    if (gpiod_chip_from_devno(0, &chip) < 0) {
        perror("Failed to find GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line line;
    gpiod_chip_get_line(chip, 17, &line); // Assuming SIGINT is connected to GPIO 17
    gpiod_add_event(&line, &ev, SIGEV_SIGNAL, timer_callback, &buffer);

    if (timer_create(CLOCK_MONOTONIC, timer_callback, &buffer, NULL) == -1) {
        perror("Failed to create timer");
        return EXIT_FAILURE;
    }

    sysfs_file = fopen(SYSFS_PATH, "w");
    if (!sysfs_file) {
        perror("Failed to open sysfs file");
        return EXIT_FAILURE;
    }

    struct itimerspec it;
    itimerspec_set(&it, IT_REAL, 0, NULL, NULL);
    timer_settime(0, 0, &it, NULL);

    while (1) {
        sleep(1);
    }

    gpiod_unexport(NULL);
    fclose(sysfs_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

