#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <stdint.h>
#include <time.h>
#include <gpiod.h>

#define RELAY_GPIO_MAP {25, 24, 23, 18}
#define RELAY_PRIMES {7, 5, 3, 2}
#define DEFAULT_OFF gpiod_direction_out

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];

static void toggle_relay(int relay_num) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = RELAY_PRIMES[relay_num - 1] * 1000000000 / 2;

    if (gpiod_delay_pulse(lines[relay_num - 1], ts) < 0) {
        fprintf(stderr, "Error: Failed to toggle relay %d\n", relay_num);
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    int ret;
    uint relay_num;

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (relay_num = 0; relay_num < 4; relay_num++) {
        lines[relay_num] = gpiod_chip_get_line(chip, RELAY_GPIO_MAP[relay_num]);
        if (!lines[relay_num]) {
            fprintf(stderr, "Error: Failed to get line for GPIO %d\n", RELAY_GPIO_MAP[relay_num]);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_export(lines[relay_num], &gpiod_flags_t{ .direction = DEFAULT_OFF });
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to export line for GPIO %d\n", RELAY_GPIO_MAP[relay_num]);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (relay_num = 0; relay_num < 4; relay_num++) {
            toggle_relay(relay_num + 1);
            clock_gettime(CLOCK_MONOTONIC, &ts);
            while ((ts.tv_sec * 1000000000 + ts.tv_nsec) < RELAY_PRIMES[relay_num] * 1000000000) {
                usleep(500000);
            }
        }
    }

    for (relay_num = 0; relay_num < 4; relay_num++) {
        gpiod_line_unexport(lines[relay_num]);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

