#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPU6050_ADDR  0x68
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

typedef struct {
    float buffer[BUFFER_SIZE];
    int head, tail;
} CircularBuffer;

void callback(float mag) {
    printf("Angular velocity exceeded threshold: %f deg/s\n", mag);
}

int main() {
    int fd, res;
    CircularBuffer cb;
    struct gi10 gpiod;
    struct gpiod_chip_params params;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    ioctl(fd, I2C_SLAVE, MPU6050_ADDR);

    memset(&params, 0, sizeof(params));
    params.gpio.direction = GPIO_DIR_OUT;
    params.gpio.pin = 2; // SDA
    gpiod_chip_add(fd, &params);
    gpiod_chip_add(fd, &params);
    params.gpio.pin = 3; // SCL
    gpiod_chip_add(fd, &params);

    cb.head = cb.tail = 0;

    while (1) {
        float x, y, z;
        res = read(fd, &x, sizeof(x));
        if (res < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }
        res = read(fd, &y, sizeof(y));
        if (res < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }
        res = read(fd, &z, sizeof(z));
        if (res < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        float mag = sqrt(x * x + y * y + z * z);
        cb.buffer[cb.head] = mag;
        cb.head = (cb.head + 1) % BUFFER_SIZE;

        if (mag > THRESHOLD) {
            callback(mag);
        }
    }

    close(fd);
    gpiod_remove_chip(fd);

    return 0;
}

