        gpiod_chip_close(uart_fd);
        uart_fd = -1;
    }
}

int open_log_file() {
    log_file = open("co2_log.json", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_file == -1) {
        perror("Failed to open co2_log.json");
        return -1;
    }

    return 0;
}

void close_log_file() {
    if (log_file != -1) {
        close(log_file);
        log_file = -1;
    }
}

int open_error_file() {
    error_file = open("co2_error.log", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (error_file == -1) {
        perror("Failed to open co2_error.log");
        return -1;
    }

    return 0;
}

void close_error_file() {
    if (error_file != -1) {
        close(error_file);
        error_file = -1;
    }
}

int send_command(int fd) {
    char command[COMMAND_LENGTH] = {0x01};
    write(fd, command, COMMAND_LENGTH);
    return 0;
}

int read_response(int fd, unsigned char *response, int retries) {
    unsigned int timeout_us = READ_TIMEOUT;
    unsigned int read_us = 0;
    int bytes_read = 0;

    while (retries > 0 && (bytes_read < RESPONSE_LENGTH || read_us < timeout_us)) {
        bytes_read = read(fd, response + bytes_read, RESPONSE_LENGTH - bytes_read);
        if (bytes_read > 0) {
            read_us += bytes_read;
        } else if (bytes_read == -1 && errno == EAGAIN) {
            usleep(10000); // Yield to other processes
            continue;
        } else {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        retries--;
    }

    if (bytes_read != RESPONSE_LENGTH) {
        fprintf(stderr, "Incomplete response or timeout\n");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (open_uart() < 0) {
        return 1;
    }

    if (open_log_file() < 0) {
        return 1;
    }
    if (open_error_file() < 0) {
        return 1;
    }

    while (1) {
        char timestamp[25];
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        timestamp[strlen(timestamp)] = '.';
        strncat(timestamp, "%06u", (unsigned int)ts.tv_nsec / 1000);

        unsigned char response[RESPONSE_LENGTH];
        if (send_command(uart_fd) < 0 || read_response(uart_fd, response, MAX_RETRIES) < 0) {
            fprintf(stderr, "Checksum mismatch or other error\n");
            fprintf(error_file, "%s - Checksum mismatch or other error\n", timestamp);
            continue;
        }

        int ppm = (response[0] << 8) | response[1];
        int error_flag = (response[2] & 0x80) >> 7;

        char json[100];
        snprintf(json, sizeof(json), "{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %d}\n", timestamp, ppm, error_flag);

        if (write(log_file, json, strlen(json)) != strlen(json)) {
            perror("Failed to write to co2_log.json");
            return 1;
        }

        if (write(STDOUT_FILENO, json, strlen(json)) != strlen(json)) {
            perror("Failed to print to stdout");
            return 1;
        }

        usleep(SAMPLE_INTERVAL);
    }

    close_uart();
    close_log_file();
    close_error_file();

    return 0;
}
