#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <wiringPiI2C.h>
#include <hmc5883_lsm303.h>

#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define I2C_ADDR 0x1E

int16_t buffer[BUFFER_SIZE];
int buffer_index = 0;

void signum_handler(int signum) {
    gpioInterruptCancel(gpio);
    gpioFree();
    exit(signum);
}

int main() {
    struct gpiod_chip chip;
    struct gpiod_line line;
    int ret;

    // Initialize GPIO interrupt
    gpioInterruptInit();
    gpioInterruptSetup(gpio, &line, GPIO_INT_EDGE_ANY, GPIO_INT_ACTIVE_LOW, signum_handler);

    // Initialize I2C
    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Initialize HMC5883L
    if (!(hmc = hmc5883_lsm303_init(I2C_ADDR))) {
        fprintf(stderr, "Failed to initialize HMC5883L\n");
        return 1;
    }

    // Create GPIO
    gpio = gpiod_chip_open(wiringPiPinToGpio(17), "GPIO17");
    if (!gpio) {
        fprintf(stderr, "Failed to open GPIO17\n");
        return 1;
    }

    gpioInterruptConfigure(&line, GPIO_INT_EDGE_ANY);
    gpioInterruptEnable(&line);

    while (1) {
        int raw_x, raw_y;
        float compensated_heading;

        // Read raw data from HMC5883L
        if (hmc5883_lsm303_read_raw(hmc, &raw_x, &raw_y) < 0) {
            fprintf(stderr, "Failed to read raw data from HMC5883L\n");
            continue;
        }

        // Apply hard-iron compensation
        compensated_heading = (float)raw_x * 57.29578 + (float)raw_y * 57.29578 + TARGET_HEADING;

        // Store in circular buffer
        buffer[buffer_index] = (int16_t)compensated_heading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Check deviation and set GPIO state
        if (fabs(compensated_heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
            gpioInterruptSetValue(gpio, 1);
        } else {
            gpioInterruptSetValue(gpio, 0);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpioInterruptFree(&line);
    gpiod_chip_put(gpio);
    hmc5883_lsm303_free(hmc);
    wiringPiI2CClose(wiringPiI2C);

    return 0;
}

