#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define BH1750_ADDR 0x23
#define LOG_FILE "lighting_log.txt"
#define I2C_DELAY_MS 120

int main() {
    int fd, res;
    gpiod_chip_reg_desc_t *chip;
    gpiod_chip_reg_t *reg;
    gpiod_context *ctx;
    gpiod_chip *chip_obj;
    gpiod_line *red, *green, *blue;
    int i2c_fd;
    int lux_value;
    FILE *log_file;
    char timestamp[20];

    ctx = gpiod_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create gpiod context\n");
        return 1;
    }

    chip = gpiod_chip_open(ctx, "GPIO1");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO1 chip\n");
        gpiod_free(ctx);
        return 1;
    }

    reg = gpiod_chip_get_reg(chip, 0, "GPIO17", 0);
    if (!reg) {
        fprintf(stderr, "Failed to get GPIO17 register\n");
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }
    red = gpiod_reg_get_line(reg, 0);
    if (!red) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }

    reg = gpiod_chip_get_reg(chip, 0, "GPIO27", 0);
    if (!reg) {
        fprintf(stderr, "Failed to get GPIO27 register\n");
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }
    green = gpiod_reg_get_line(reg, 0);
    if (!green) {
        fprintf(stderr, "Failed to get GPIO27 line\n");
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }

    reg = gpiod_chip_get_reg(chip, 0, "GPIO22", 0);
    if (!reg) {
        fprintf(stderr, "Failed to get GPIO22 register\n");
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }
    blue = gpiod_reg_get_line(reg, 0);
    if (!blue) {
        fprintf(stderr, "Failed to get GPIO22 line\n");
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }

    i2c_fd = fd;

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus for BH1750");
        close(fd);
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_put(chip);
        gpiod_free(ctx);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        res = ioctl(i2c_fd, I2C_MASTER_TX_DATA, &lux_value, 1);
        if (res < 0) {
            fprintf(stderr, "Failed to read from BH1750\n");
            sleep(I2C_DELAY_MS / 1000);
            continue;
        }

        if (res != 1) {
            fprintf(stderr, "Failed to receive data from BH1750\n");
            sleep(I2C_DELAY_MS / 1000);
            continue;
        }

        fprintf(log_file, "%s, Lux: %d\n", timestamp, lux_value);

        if (lux_value < 50)
            gpiod_trigger(red, 1);
        else if (lux_value < 150)
            gpiod_trigger(green, 1);
        else if (lux_value < 300)
            gpiod_trigger(blue, 1);
        else
            gpiod_trigger(red, 1), gpiod_trigger(green, 1), gpiod_trigger(blue, 1);

        sleep(1);
    }

    gpiod_trigger(red, 0);
    gpiod_trigger(green, 0);
    gpiod_trigger(blue, 0);
    close(i2c_fd);
    gpiod_chip_put(chip);
    gpiod_free(ctx);
    fclose(log_file);

    return 0;
}

