#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define MOTOR_A_IN1_GPIO 17
#define MOTOR_A_IN2_GPIO 18
#define MOTOR_B_IN3_GPIO 22
#define MOTOR_B_IN4_GPIO 23

#define PWM_FREQ 1000
#define PWM_RANGE 255

struct motor {
    int in1;
    int in2;
    int pwm;
};

struct motor motors[2];

void cleanup(int signum) {
    for (int i = 0; i < 2; i++) {
        gpiod_chip_put(motors[i].in1_chip, motors[i].in1);
        gpiod_chip_put(motors[i].in2_chip, motors[i].in2);
        gpiod_chip_put(motors[i].pwm_chip, motors[i].pwm);
    }
    exit(signum);
}

int init_motor(struct motor *motor, int in1, int in2, int pwm) {
    struct gpiod_chip *chip;
    int fd;

    chip = gpiod_chip_find("GPIO");
    if (!chip) {
        fprintf(stderr, "Failed to find GPIO chip\n");
        return -1;
    }

    fd = gpiod_chip_fd(chip);
    if (fd < 0) {
        fprintf(stderr, "Failed to get file descriptor for GPIO chip\n");
        return -1;
    }

    motor->in1_chip = chip;
    motor->in2_chip = chip;
    motor->pwm_chip = gpiod_chip_find("PWM");

    if (!motor->in1_chip || !motor->in2_chip || !motor->pwm_chip) {
        fprintf(stderr, "Failed to find required GPIO pins\n");
        return -1;
    }

    motor->in1 = gpiod_chip_get_pin(motor->in1_chip, in1);
    motor->in2 = gpiod_chip_get_pin(motor->in2_chip, in2);
    motor->pwm = gpiod_chip_get_pin(motor->pwm_chip, pwm);

    if (!motor->in1 || !motor->in2 || !motor->pwm) {
        fprintf(stderr, "Failed to find required pins on the chip\n");
        return -1;
    }

    gpiod_chip_set_owner(motor->in1_chip, motor->in1, FD_CLOEXEC);
    gpiod_chip_set_owner(motor->in1_chip, motor->in2, FD_CLOEXEC);
    gpiod_chip_set_owner(motor->pwm_chip, motor->pwm, FD_CLOEXEC);

    if (gpiod_export(fd, motor->in1) || gpiod_export(fd, motor->in2) || gpiod_export(fd, motor->pwm)) {
        fprintf(stderr, "Failed to export pins\n");
        return -1;
    }

    gpiod_set_value(motor->in1, 0);
    gpiod_set_value(motor->in2, 0);
    gpiod_set_value(motor->pwm, 0);

    return 0;
}

void set_pwm(struct motor *motor, int duty) {
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Invalid PWM duty cycle value: %d\n", duty);
        return;
    }

    if (gpiod_set_value_direction(motor->pwm_chip, motor->pwm, GPIO_DIR_OUT)) {
        fprintf(stderr, "Failed to set PWM pin direction\n");
        return;
    }

    if (gpiod_set_value(motor->pwm, duty)) {
        fprintf(stderr, "Failed to set PWM value\n");
        return;
    }
}

void drive_motor(struct motor *motor, bool forward, int distance) {
    if (distance < 50) {
        gpiod_set_value(motor->in1, forward);
        gpiod_set_value(motor->in3, forward);
        set_pwm(motor, distance * PWM_RANGE / 50);
    } else {
        gpiod_set_value(motor->in1, !forward);
        gpiod_set_value(motor->in3, !forward);
        set_pwm(motor, (100 - distance) * PWM_RANGE / 50);
    }
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    struct sigeset ss;
    sigset_t set;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_for_motor_a> <distance_for_motor_b>\n", argv[0]);
        return 1;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Invalid distance values\n");
        return 1;
    }

    motors[0].in1 = MOTOR_A_IN1_GPIO;
    motors[0].in2 = MOTOR_A_IN2_GPIO;
    motors[0].pwm = PWM_FREQ;

    motors[1].in1 = MOTOR_B_IN3_GPIO;
    motors[1].in2 = MOTOR_B_IN4_GPIO;
    motors[1].pwm = PWM_FREQ;

    if (init_motor(&motors[0], motors[0].in1, motors[0].in2, motors[0].pwm) ||
        init_motor(&motors[1], motors[1].in1, motors[1].in2, motors[1].pwm)) {
        fprintf(stderr, "Failed to initialize motors\n");
        return 1;
    }

    sigemptyset(&set);
    sigaddset(&set, SIGINT);
    sigaddset(&set, SIGTERM);
    sigprocmask(SIG_BLOCK, &set, &ss);

    ts.tv_sec = 0;
    ts.tv_nsec = 100 * 1000 * 1000;

    while (true) {
        drive_motor(&motors[0], distance_a < 50, distance_a);
        drive_motor(&motors[1], distance_b < 50, distance_b);

        nanosleep(&ts, NULL);
    }

    cleanup(SIGINT);
    cleanup(SIGTERM);

    return 0;
}

