        gpio_set_value(GPIO_OUT, GPIO17, !direction);
        gpio_set_value(GPIO_OUT, GPIO18, direction);
        gpio_set_value(GPIO_OUT, GPIO27, !direction);
        gpio_set_value(GPIO_OUT, GPIO22, direction);
        usleep(INTER_STEP_DELAY_MS * 1000);
    }
