        unlock_pressed = gpio_get_value(GPIO_IN, GPIO23) == 0;

        if (lock_pressed && !unlock_pressed) {
            stepper_move(1, STEPPER_STEPS);
            printf("Locked\n");
        } else if (!lock_pressed && unlock_pressed) {
            stepper_move(0, STEPPER_STEPS);
            printf("Unlocked\n");
        }

        if (lock_pressed || unlock_pressed) {
            gpio_set_value(GPIO_IN, GPIO24, GPIO_PUD_UP);
            gpio_set_value(GPIO_IN, GPIO23, GPIO_PUD_UP);
        }
    }

    gpio_free();
    return 0;
