#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPiI2C.h>
#include <pwm.h>

#define MPU_ADDR 0x68
#define SERVO_PWM_FREQ 50
#define SERVO_PWM_RANGE 1000
#define SERVO_PIN 18
#define MAX_RETRIES 10
#define BACKOFF_FACTOR 2

int i2c_fd = -1;
int servo_pwm_fd = -1;

void init_i2c() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU_ADDR) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        perror("Failed to acquire bus access and/or talk to slave");
        exit(EXIT_FAILURE);
    }
}

void init_servo_pwm() {
    char filename[20];
    snprintf(filename, sizeof(filename), "/sys/class/pwm/pwmchip2/pwm%d", 0);
    servo_pwm_fd = open(filename, O_RDWR);

    if (servo_pwm_fd < 0) {
        perror("Failed to open servo PWM interface");
        exit(EXIT_FAILURE);
    }

    struct pwm_info info;
    if (pwm_get_info(servo_pwm_fd, &info) < 0) {
        close(servo_pwm_fd);
        servo_pwm_fd = -1;
        perror("Failed to get PWM info");
        exit(EXIT_FAILURE);
    }

    if (info.range != SERVO_PWM_RANGE) {
        fprintf(stderr, "Invalid PWM range. Expected %d, got %d\n", SERVO_PWM_RANGE, info.range);
        exit(EXIT_FAILURE);
    }

    if (info.freq != SERVO_PWM_FREQ) {
        fprintf(stderr, "Invalid PWM frequency. Expected %d, got %d\n", SERVO_PWM_FREQ, info.freq);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (servo_pwm_fd >= 0) {
        close(servo_pwm_fd);
        servo_pwm_fd = -1;
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int read_mpu_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    if (write(i2c_fd, MPU_REG_PWR_MGMT_1, 1) != 1) {
        return -1;
    }

    // Wait for the MPU to be ready
    while (read(i2c_fd, NULL, 1) && (B01010000 & read(i2c_fd, NULL, 1))) {
        // Busy wait
    }

    *accel_x = read_reg16(MPU_REG_ACCEL_XOUT_H);
    *accel_y = read_reg16(MPU_REG_ACCEL_YOUT_H);
    *accel_z = read_reg16(MPU_REG_ACCEL_ZOUT_H);

    *gyro_x = read_reg16(MPU_REG_GYRO_XOUT_H);
    *gyro_y = read_reg16(MPU_REG_GYRO_YOUT_H);
    *gyro_z = read_reg16(MPU_REG_GYRO_ZOUT_H);

    return 0;
}

double compute_pitch_roll(int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz) {
    // Simplified pitch and roll calculation
    double pitch = atan2(ay, sqrt(ax * ax + az * az)) * 180 / M_PI;
    double roll = atan2(ax, sqrt(ay * ay + az * az)) * 180 / M_PI;

    return pitch, roll;
}

int main() {
    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    init_i2c();
    init_servo_pwm();

    int retries = 0;
    int ret;
    while (1) {
        int16_t ax, ay, az, gx, gy, gz;
        ret = read_mpu_data(&ax, &ay, &az, &gx, &gy, &gz);
        if (ret < 0) {
            if (retries < MAX_RETRIES) {
                retries++;
                sleep(BACKOFF_FACTOR ** retries);
                continue;
            } else {
                fprintf(stderr, "Failed to read MPU data after %d retries\n", MAX_RETRIES);
                break;
            }
        }

        double pitch, roll;
        pitch, roll = compute_pitch_roll(ax, ay, az, gx, gy, gz);

        int pos = (SERVO_PWM_RANGE / 2) + (pitch * (SERVO_PWM_RANGE / 180));
        write(servo_pwm_fd, &pos, sizeof(pos));

        time_t now = time(NULL);
        printf("%ld,%f,%f,%d\n", now, pitch, roll, pos);

        fflush(stdout);
    }

    cleanup();
    return 0;
}

static void cleanup_handler(int signum) {
    cleanup();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

