#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800 // seconds
#define PWM_FREQ 100 // Hz

gpio_context g_gpio_ctx;

void fade_init(int relay_num, int pin, int is_on) {
    char pwm_name[32];
    snprintf(pwm_name, sizeof(pwm_name), "PWM%d", relay_num);
    if (gpio_request(g_gpio_ctx, pin, GPIOF_INOUT, pwm_name) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", pin);
        exit(EXIT_FAILURE);
    }
    gpio_set_func(g_gpio_ctx, pin, GPIOF_PWM_OUT);
}

void fade_update(int relay_num, int pin, int is_on, uint32_t timestamp) {
    uint64_t period = (uint64_t)(1000 / PWM_FREQ);
    uint32_t duty_cycle = (uint32_t)((double)timestamp / FADE_DURATION * 100);
    gpio_set_pwm_duty(g_gpio_ctx, pin, duty_cycle);
}

void fade_cleanup(int relay_num, int pin) {
    gpio_free(g_gpio_ctx, pin);
}

void sigint_handler(int signum) {
    (void)signum;
    for (int i = 0; i < NUM_RELAYS; i++) {
        fade_cleanup(i, i + 4); // GPIO4, GPIO17, GPIO27, GPIO22
    }
    gpio_free(g_gpio_ctx, -1);
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    (void)signum;
    sigint_handler(signum);
}

int main() {
    struct sigaction sa_int, sa_term;
    memset(&sa_int, 0, sizeof(sa_int));
    sa_int.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa_int, NULL);

    memset(&sa_term, 0, sizeof(sa_term));
    sa_term.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa_term, NULL);

    if (gpio_init(&g_gpio_ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        fade_init(i, i + 4, 1); // Initialize relays as ON
    }

