#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MAX_DISTANCE 200
#define MIN_DISTANCE 3
#define FREQ_MIN 1000
#define FREQ_MAX 20000
#define MEAS_INTERVAL 60000 // 60 ms
#define TRIG_PULSE 10000 // 10 µs

static volatile bool running = true;
static struct gpio *trig_gpio, *echo_gpio, *buzzer_gpio;

void sigint_handler(int signum) {
    running = false;
}

uint32_t get_distance_us(struct gpio *echo) {
    uint32_t r = gpio_get_level(echo);
    uint32_t t1 = gpio_get_level_now(echo);
    uint32_t t2 = 0;
    uint32_t elapsed_time = 0;
    uint32_t distance = 0;

    gpio_set_level(echo, 0);
    while ((t1 ^ gpio_get_level(echo)) == t1) {
        t2 = gpio_get_level_now(echo);
        elapsed_time = t2 - t1;
    }

    gpio_set_level(echo, 1);
    if (elapsed_time > 0) {
        distance = elapsed_time * 17150; // Speed of sound is 17150 cm/s
    }

    return distance;
}

void set_buzzer_freq(int freq) {
    if (freq < FREQ_MIN || freq > FREQ_MAX) {
        freq = (freq > FREQ_MIN) ? FREQ_MIN : FREQ_MAX;
    }

    // Apply frequency to buzzer (implementation depends on your buzzer hardware)
    // Example: pwm_set_freq(buzzer_gpio, freq);
}

int main() {
    struct signal sigIntSig;
    struct sigaction sigIntAction;

    gpio_init();

    sigIntSig.sa_flags = 0;
    sigIntAction.sa_handler = sigint_handler;
    sigIntAction.sa_flags = SA_RESETHAND;
    sigIntAction.sa_mask = {0};

    if (sigaction(SIGINT, &sigIntAction, &sigIntSig) == -1) {
        perror("sigaction");
        goto cleanup;
    }

    trig_gpio = gpio_request(TRIG_PIN);
    if (!trig_gpio) {
        perror("gpio_request (trigger)");
        goto cleanup;
    }
    echo_gpio = gpio_request(ECHO_PIN);
    if (!echo_gpio) {
        perror("gpio_request (echo)");
        goto cleanup;
    }
    buzzer_gpio = gpio_request(BUZZER_PIN);
    if (!buzzer_gpio) {
        perror("gpio_request (buzzer)");
        goto cleanup;
    }

    gpio_set_direction(trig_gpio, GPIO_OUT);
    gpio_set_direction(echo_gpio, GPIO_IN);
    gpio_set_direction(buzzer_gpio, GPIO_OUT);

    if (gpio_export(trig_gpio) < 0 || gpio_export(echo_gpio) < 0 || gpio_export(buzzer_gpio) < 0) {
        perror("gpio_export");
        goto cleanup;
    }

    while (running) {
        uint32_t distance = get_distance_us(echo_gpio);

        if (distance == 0) {
            fprintf(stderr, "Error: Missing or disconnected sensor detected.\n");
            break;
        }

        int freq = map(distance, MIN_DISTANCE, MAX_DISTANCE, FREQ_MIN, FREQ_MAX);
        set_buzzer_freq(freq);

        // Enforce minimum gap between measurements
        struct timespec ts = {0};
        ts.tv_sec = 0;
        ts.tv_nsec = MEAS_INTERVAL;
        nanosleep(&ts, NULL);
    }

cleanup:
    gpio_unref(buzzer_gpio);
    gpio_unref(echo_gpio);
    gpio_unref(trig_gpio);
    gpio_uninit();

    return 0;
}

