#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27
#define PWM_FREQ 1000

typedef struct {
    int red;
    int green;
    int blue;
} Color;

Color color;

void sine_wave(float t) {
    color.red = (int)(127.5 + 127.5 * (float)sin(t * 2 * M_PI));
    color.green = (int)(127.5 + 127.5 * (float)sin(t * 2 * M_PI + M_PI / 2));
    color.blue = (int)(127.5 + 127.5 * (float)sin(t * 2 * M_PI + M_PI));
}

int main() {
    int ret;
    float t = 0;

    gpiod_context dev;
    ret = gpiod_new(&dev);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return ret;
    }

    struct gpiod_chip *chip;
    ret = gpiod_chip_open(dev, "BCM2835-GPIO", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_free(dev);
        return ret;
    }

    struct gpiod_line line;
    line.chip = chip;
    line.line = RED_GPIO;
    color.red = gpiod_line_request_add(&line, "red");
    if (color.red < 0) {
        fprintf(stderr, "Failed to request red GPIO\n");
        gpiod_chip_close(chip);
        gpiod_free(dev);
        return color.red;
    }

    line.line = GREEN_GPIO;
    color.green = gpiod_line_request_add(&line, "green");
    if (color.green < 0) {
        fprintf(stderr, "Failed to request green GPIO\n");
        gpiod_line_free(color.red);
        gpiod_chip_close(chip);
        gpiod_free(dev);
        return color.green;
    }

    line.line = BLUE_GPIO;
    color.blue = gpiod_line_request_add(&line, "blue");
    if (color.blue < 0) {
        fprintf(stderr, "Failed to request blue GPIO\n");
        gpiod_line_free(color.green);
        gpiod_chip_close(chip);
        gpiod_free(dev);
        return color.blue;
    }

    struct gpiod_pwm_params params = {
        .freq = PWM_FREQ,
        .enable_noise_filter = false,
    };

    ret = gpiod_pwm_enable(color.red, &params);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable PWM on red GPIO\n");
        gpiod_line_free(color.blue);
        gpiod_line_free(color.green);
        gpiod_chip_close(chip);
        gpiod_free(dev);
        return ret;
    }

    ret = gpiod_pwm_enable(color.green, &params);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable PWM on green GPIO\n");
        gpiod_line_free(color.blue);
        gpiod_line_free(color.red);
        gpiod_chip_close(chip);
        gpiod_free(dev);
        return ret;
    }

    ret = gpiod_pwm_enable(color.blue, &params);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable PWM on blue GPIO\n");
        gpiod_line_free(color.green);
        gpiod_line_free(color.red);
        gpiod_chip_close(chip);
        gpiod_free(dev);
        return ret;
    }

    while (1) {
        sine_wave(t);
        gpiod_pwm_set_vals(color.red, color.red);
        gpiod_pwm_set_vals(color.green, color.green);
        gpiod_pwm_set_vals(color.blue, color.blue);
        t += 0.01;
        usleep(16666); // 1 kHz frequency
    }

    gpiod_pwm_disable(color.red);
    gpiod_pwm_disable(color.green);
    gpiod_pwm_disable(color.blue);
    gpiod_line_free(color.blue);
    gpiod_line_free(color.green);
    gpiod_line_free(color.red);
    gpiod_chip_close(chip);
    gpiod_free(dev);

    return 0;
}

