#include <gpiod.h>

#define MPU6050_ADDR  0x68
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define FILENAME "gyro_log.txt"

struct gyro_data {
    double x;
    double y;
    double z;
};

int main() {
    int fd;
    char *dev_name = I2C_BUS;
    struct gyro_data data;
    FILE *log_file;

    gpiod_chip_chip_remove(gpiod_chip_get_chip_from_number(2));
    gpiod_chip_chip_remove(gpiod_chip_get_chip_from_number(3));

    fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        close(fd);
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if (gpiod_in_create(&dev_name[4], "GPIO2", GPIO_IN, gpiod_chip_get_chip_from_number(2)) < 0) {
        close(fd);
        perror("Failed to initialize GPIO2");
        return 1;
    }

    if (gpiod_in_create(&dev_name[4], "GPIO3", GPIO_IN, gpiod_chip_get_chip_from_number(3)) < 0) {
        close(fd);
        perror("Failed to initialize GPIO3");
        return 1;
    }

    log_file = fopen(FILENAME, "a");
    if (!log_file) {
        close(fd);
        return 1;
    }

    while (1) {
        // Wait for sensor data
        usleep(SAMPLE_INTERVAL);

        // Read gyro data
        if (read(fd, &data, sizeof(struct gyro_data)) != sizeof(struct gyro_data)) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        // Check if the sensor is present
        if (gpiod_in_get_value(&dev_name[4], GPIO_IN, gpiod_chip_get_chip_from_number(2)) == 0) {
            fprintf(stderr, "MPU-6050 sensor not detected\n");
            break;
        }

        // Convert raw data to degrees per second (assuming raw values are in mg/º/s)
        data.x = (double)data.x / 131.0;
        data.y = (double)data.y / 131.0;
        data.z = (double)data.z / 131.0;

        // Write to log file
        time_t now = time(NULL);
        fprintf(log_file, "%ld %f %f %f\n", now, data.x, data.y, data.z);
        fflush(log_file);
    }

    fclose(log_file);
    close(fd);

    return 0;
}
