#define PWM_FREQ 1000  // PWM frequency in Hz
#define DUTY_CYCLE 50  // Duty cycle for PWM

const uint16_t melody[] = {440, 493, 440, 349, 392, 0, 349, 392, 440, 493, 440, 0};

volatile bool button_pressed = false;
bool playing_melody = false;
uint16_t melody_index = 0;
uint32_t melody_duration = 0;

void sigint_handler(int signum) {
    gpiod_unrequest_all();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

void setup_gpio(void) {
    int ret;

    ret = gpiod_request_add(&button_dev, "button", &button_chip, 17, GPIO_DIR_IN, GPIO_EV_RISING_FALLING, NULL, "button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO17 as input\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_add(&buzzer_dev, "buzzer", &buzzer_chip, 18, GPIO_DIR_OUT, 0, NULL, "buzzer");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO18 as output\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_set_value(buzzer_dev.dev, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set initial PWM value\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_set_config(buzzer_dev.dev, 0, PWM_FREQ, DUTY_CYCLE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM configuration\n");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
}

void cleanup_gpio(void) {
    gpiod_unrequest_all();
}

void play_melody(void) {
    playing_melody = true;
    while (melody_duration > 0) {
        uint16_t frequency = melody[melody_index];
        if (frequency) {
            uint32_t pwm_value = (uint32_t)((frequency / PWM_FREQ) * 100);
            gpiod_request_set_value(buzzer_dev.dev, 0, pwm_value);
            melody_index++;
            melody_duration -= 10; // Approximate 10ms delay
            if (melody_index >= sizeof(melody) / sizeof(melody[0])) {
                melody_index = 0;
            }
        } else {
            melody_index++;
            if (melody_index >= sizeof(melody) / sizeof(melody[0])) {
                melody_index = 0;
            }
            melody_duration -= 10; // Approximate 10ms delay
        }
        if (button_pressed) {
            playing_melody = false;
            break;
        }
    }
}

int main(void) {
    int ret;
    gpiod_chip_handle button_chip, buzzer_chip;
    gpiod_chip_register(&button_chip, "button_chip");
    gpiod_chip_register(&buzzer_chip, "buzzer_chip");

    ret = gpiod_chip_get_line(&button_chip, "button", 17, &button_dev);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO17 as input\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line(&buzzer_chip, "buzzer", 18, &buzzer_dev);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO18 as output\n");
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    while (true) {
        ret = gpiod_request_read(&button_dev, 0, &button_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read button value\n");
            exit(EXIT_FAILURE);
        }

        if (button_value & GPIO_EV_RISING_FALLING) {
            if (!button_pressed && time(NULL) - last_button_press >= DEBOUNCE_INTERVAL / 1000.0) {
                button_pressed = true;
                last_button_press = time(NULL);
            }
        } else {
            button_pressed = false;
        }

        if (button_pressed) {
            if (!playing_melody) {
                play_melody();
            }
        }

        if (playing_melody) {
            ret = gpiod_request_read(&buzzer_dev, 0, &buzzer_value);
            if (ret < 0) {
                fprintf(stderr, "Failed to read buzzer value\n");
                exit(EXIT_FAILURE);
            }

            if (!(buzzer_value & GPIO_EV_RISING_FALLING)) {
                playing_melody = false;
                break;
            }
        }

        usleep(10000); // 10ms loop delay
    }

    cleanup_gpio();
    return 0;
}

