#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define GPIO_PIN 17
#define EVENT_WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000

volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

int main(int argc, char *argv[]) {
    struct gpio_target target;
    struct gpio_event event;
    FILE *log_file = NULL;
    char timestamp[24];
    int event_count = 0;
    int last_event;
    int timeout;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (argc > 1) {
        timeout = atoi(argv[1]);
    } else {
        timeout = DEFAULT_TIMEOUT;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (gpio_open(GPIO_PIN, &target) < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_PIN);
        gpio_close(&target);
        return 1;
    }

    target.edge_trigger = GPIOT_EDGE_BOTH;
    if (gpio_set_target(&target) < 0) {
        fprintf(stderr, "Failed to set GPIO %d edge trigger\n", GPIO_PIN);
        gpio_close(&target);
        return 1;
    }

    if ((log_file = fopen("vibration_events.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file vibration_events.log\n");
        gpio_close(&target);
        return 1;
    }

    while (!sigint_received) {
        if (gpio_poll(&target, &event, timeout * 1000) < 0) {
            fprintf(stderr, "Failed to poll GPIO %d\n", GPIO_PIN);
            break;
        }

        if (event.type == GPIOT_EVENT_RISING || event.type == GPIOT_EVENT_FALLING) {
            last_event = event.value ? 1 : 0;

            if (event_count < EVENT_WINDOW_SIZE) {
                event_count++;
            } else {
                if (last_event) {
                    event_count++;
                } else {
                    event_count--;
                }
                if (event_count >= 3) {
                        time_t now = time(NULL);
                        struct tm *tm_info = localtime(&now);
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
                        fprintf(stdout, "EARTHQUAKE ALERT: %s\n", timestamp);
                    }
            }

            if (fputs(timestamp, log_file) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                break;
            }
            if (fprintf(log_file, " %d", last_event) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                break;
            }
            fflush(log_file);
        }
    }

    fclose(log_file);
    gpio_close(&target);
    gpio_cleanup();

    return 0;
}

