#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c_dev.h>
#include <linux/i2c-dev.h>

#define LSM303_ADDR 0x19
#define SAMPLE_INTERVAL 1
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

struct sensor_data {
    double calibrated_x;
    double calibrated_y;
    double calibrated_z;
    int heading;
};

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void sigint_handler(int signum, siginfo_t *info, void *context) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(0);
}

static int init_i2c(const char *dev) {
    i2c_fd = open(dev, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (gpiod_export(&gpiochip, "i2c-bus") < 0) {
        perror("Failed to export i2c-bus");
        close(i2c_fd);
        return -1;
    }

    struct i2c_rdwr_ioctl_data rdwr_data;
    rdwr_data.u8 = &LSM303_ADDR;
    rdwr_data.u32len = 1;
    rdwr_data.u32reg = 0x06; // Who am I register

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr_data) < 0) {
        perror("Failed to perform I2C read");
        gpiod_unexport(&gpiochip);
        close(i2c_fd);
        return -1;
    }

    return 0;
}

static int read_magnetometer_data(struct sensor_data *data) {
    uint8_t buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    data->calibrated_x = (buf[0] << 8 | buf[1]) * 0.0156 - X_OFFSET;
    data->calibrated_y = (buf[2] << 8 | buf[3]) * 0.0156 - Y_OFFSET;
    data->calibrated_z = (buf[4] << 8 | buf[5]) * 0.0156 - Z_OFFSET;

    return 0;
}

static int compute_heading(struct sensor_data *data) {
    double mag_norm = sqrt(data->calibrated_x * data->calibrated_x + data->calibrated_y * data->calibrated_y + data->calibrated_z * data->calibrated_z);
    if (mag_norm == 0) {
        return -1;
    }

    data->heading = (int)((atan2(data->calibrated_y, data->calibrated_x) / M_PI * 180) + 360) % 360;

    if (data->heading < 45) {
        return 0; // N
    } else if (data->heading < 135) {
        return 1; // NE
    } else if (data->heading < 225) {
        return 2; // S
    } else if (data->heading < 315) {
        return 3; // SW
    } else {
        return 4; // W
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_sigaction = sigint_handler;
    sa.sa_flags = SA_SIGINFO;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    const char *i2c_dev = "/dev/i2c-1";
    struct sensor_data data;
    time_t timestamp;

    if (init_i2c(i2c_dev) < 0) {
        return EXIT_FAILURE;
    }

    if ((csv_file = fopen("mag_log.csv", "a")) == NULL) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    if (fputs("Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n", csv_file) < 1) {
        fclose(csv_file);
        csv_file = NULL;
        return EXIT_FAILURE;
    }

    while (1) {
        timestamp = time(NULL);
        fputs(ctime(&timestamp), csv_file);
        fputc(',', csv_file);
        fprintf(csv_file, "%.6f", timestamp);
        fputc(',', csv_file);
        fprintf(csv_file, "%.6f", data.calibrated_x);
        fputc(',', csv_file);
        fprintf(csv_file, "%.6f", data.calibrated_y);
        fputc(',', csv_file);
        fprintf(csv_file, "%.6f", data.calibrated_z);
        fputc(',', csv_file);
        fprintf(csv_file, "%d", data.heading);
        fputc('\n', csv_file);

        fputs("\r", stdout);
        fputs(ctime(&timestamp), stdout);
        fflush(stdout);

        if (read_magnetometer_data(&data) < 0) {
            continue;
        }

        if (compute_heading(&data) < 0) {
            continue;
        }

        printf("Heading: %d° (%s)\n", data.heading, (data.heading < 45 ? "N" : (data.heading < 135 ? "NE" : (data.heading < 225 ? "S" : (data.heading < 315 ? "SW" : "W")))));
        fflush(stdout);

        sleep(SAMPLE_INTERVAL);
    }

    close(i2c_fd);
    gpiod_unexport(&gpiochip);
    fclose(csv_file);

    return EXIT_SUCCESS;
}

