#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_TIME 200000 // 200 ms in microseconds

static bool relay_state = false;
static time_t last_touch_time = 0;
static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (signum == SIGINT) {
        relay_state = false;
        fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"OFF\"}\n", time_to_string());
        fflush(log_file);
        gpiod_unclaim(relay_chip, RELAY_PIN);
        close(fileno(log_file));
        exit(0);
    }
}

static char *time_to_string() {
    time_t now = time(NULL);
    char *dt = ctime(&now);
    dt[strlen(dt) - 1] = '\0'; // Remove newline character
    return dt;
}

static int touch_callback(const gpiod_chip *chip, gpiod_line_info *line, uint32_t flags) {
    if (flags & GPIO_EVENT_FALLING_EDGE) {
        time_t current_time = time(NULL);
        if (current_time - last_touch_time >= DEBOUNCE_TIME) {
            relay_state = !relay_state;
            last_touch_time = current_time;

            if (relay_state) {
                gpiod_gpio_set_value(relay_chip, RELAY_PIN, 1);
                fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", time_to_string(), "ON");
            } else {
                gpiod_gpio_set_value(relay_chip, RELAY_PIN, 0);
                fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", time_to_string(), "OFF");
            }
            fflush(log_file);
        }
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip *relay_chip = gpiod_chip_open(0, "GPIO17");
    if (!relay_chip) {
        fprintf(stderr, "Failed to open GPIO17\n");
        return 1;
    }

    gpiod_chip *touch_chip = gpiod_chip_open(0, "GPIO4");
    if (!touch_chip) {
        gpiod_chip_close(relay_chip);
        fprintf(stderr, "Failed to open GPIO4\n");
        return 1;
    }

    gpiod_line *touch_line = gpiod_chip_get_line(touch_chip, 0);
    if (!touch_line) {
        gpiod_chip_close(relay_chip);
        gpiod_chip_close(touch_chip);
        fprintf(stderr, "Failed to get GPIO4 line\n");
        return 1;
    }

    if (gpiod_line_export(touch_line, "touch_input") < 0) {
        gpiod_chip_close(relay_chip);
        gpiod_chip_close(touch_chip);
        fprintf(stderr, "Failed to export GPIO4\n");
        return 1;
    }

    if (gpiod_line_request_callback(touch_line, flags, touch_callback, NULL) < 0) {
        gpiod_line_unexport(touch_line);
        gpiod_chip_close(relay_chip);
        gpiod_chip_close(touch_chip);
        fprintf(stderr, "Failed to set callback for GPIO4\n");
        return 1;
    }

    if (gpiod_gpio_direction_input(relay_chip, RELAY_PIN) < 0) {
        gpiod_line_unexport(touch_line);
        gpiod_chip_close(relay_chip);
        gpiod_chip_close(touch_chip);
        fprintf(stderr, "Failed to set GPIO17 as input\n");
        return 1;
    }

    log_file = fopen("relay_log.json", "a");
    if (!log_file) {
        gpiod_line_unexport(touch_line);
        gpiod_chip_close(relay_chip);
        gpiod_chip_close(touch_chip);
        fprintf(stderr, "Failed to open relay_log.json\n");
        return 1;
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", time_to_string(), relay_state ? "ON" : "OFF");
    fflush(log_file);

    while (1) {
        sleep(1);
    }

    gpiod_line_unexport(touch_line);
    gpiod_chip_close(relay_chip);
    gpiod_chip_close(touch_chip);
    fclose(log_file);

    return 0;
}

