#define RELAY_PINS {17, 23, 24, 25}
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_LOG "irrigation_log.txt"

struct relay_data {
    int pin;
    bool active;
};

void log_irrigation(const char *timestamp, int relay_num, int moisture_level) {
    FILE *log_file = fopen(IRRIGATION_LOG, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Unable to open log file %s for writing.\n", IRRIGATION_LOG);
        return;
    }
    fprintf(log_file, "%s Relay %d: Moisture %d\n", timestamp, relay_num, moisture_line);
    fclose(log_file);
}

void activate_relay(struct relay_data *relay, int duration) {
    if (gpiod_request(relay->pin, "output") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO %d as output.\n", relay->pin);
        return;
    }
    if (gpiod_set(relay->pin, 0) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to low.\n", relay->pin);
        return;
    }
    sleep(duration);
    if (gpiod_set(relay->pin, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to high.\n", relay->pin);
    }
}

int main() {
    struct relay_data relays[4];
    srand(time(NULL));
    gpiod_context *ctx = gpiod_new();
    if (!ctx) {
        fprintf(stderr, "Error: Failed to create gpiod context.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < sizeof(RELAY_PINS) / sizeof(RELAY_PINS[0]); ++i) {
        relays[i].pin = RELAY_PINS[i];
        relays[i].active = false;
    }

    FILE *log_file = fopen(IRRIGATION_LOG, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Unable to open log file %s for writing.\n", IRRIGATION_LOG);
        gpiod_free(ctx);
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Starting irrigation system...\n");
    fclose(log_file);

    while (true) {
        int moisture_level = rand() % 101;
        if (moisture_level < MOISTURE_THRESHOLD) {
            for (size_t i = 0; i < sizeof(RELAY_PINS) / sizeof(RELAY_PINS[0]); ++i) {
                relays[i].active = true;
                activate_relay(&relays[i], 5);
                log_irrigation(asctime(localtime(&time(NULL))), i + 1, moisture_level);
            }
        }

        sleep(10);
    }

    for (size_t i = 0; i < sizeof(RELAY_PINS) / sizeof(RELAY_PINS[0]); ++i) {
        gpiod_unrequest(relays[i].pin);
    }

    gpiod_free(ctx);
    fclose(log_file);
    return EXIT_SUCCESS;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT, deactivating relays and exiting...\n");
    for (size_t i = 0; i < sizeof(RELAY_PINS) / sizeof(RELAY_PINS[0]); ++i) {
        gpiod_unrequest(relays[i].pin);
    }
    gpiod_free(ctx);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

