#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdatomic.h>
#include <time.h>
#include <gpiod.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18
#define MAX_RETRIES 3
#define CYCLE_DELAY 2000000 // 2 seconds
#define SPRAY_DELAY 5000000 // 5 seconds
#define RETRY_BACKOFF 100000 // 100 ms

volatile sig_atomic_t stop_flag = 0;

static int valve_open(int pin, uint32_t us) {
    struct gpiod_chipchip *chip;
    struct gpiod_lineline *line;
    int ret;

    chip = gpiod_chip_open(VALVE_GPIO);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO %d\n", VALVE_GPIO);
        return -1;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to get line for GPIO %d\n", VALVE_GPIO);
        return -1;
    }

    ret = gpiod_line_write(line, us);
    if (ret < 0) {
        if (retry_open(line, us)) {
            gpiod_line_release(line);
            gpiod_chip_put(chip);
            return -1;
        } else {
            fprintf(stderr, "Failed to open valve after retries\n");
            critical_warning("Failed to close valve");
            gpiod_line_release(line);
            gpiod_chip_put(chip);
            return -1;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);
    return 0;
}

static int valve_close(int pin, uint32_t us) {
    return valve_open(pin, us);
}

static int nozzle_move(int pin, uint32_t us, int angle) {
    struct gpiod_chipchip *chip;
    struct gpiod_lineline *line;
    int ret;

    chip = gpiod_chip_open(pin);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO %d\n", pin);
        return -1;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to get line for GPIO %d\n", pin);
        return -1;
    }

    ret = gpiod_line_write(line, us);
    if (ret < 0) {
        if (retry_move(line, us)) {
            gpiod_line_release(line);
            gpiod_chip_put(chip);
            return -1;
        } else {
            fprintf(stderr, "Failed to move nozzle after retries\n");
            gpiod_line_release(line);
            gpiod_chip_put(chip);
            return -1;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);
    return 0;
}

static int retry_open(struct gpiod_line *line, uint32_t us) {
    int retries = MAX_RETRIES;

    while (retries--) {
        if (gpiod_line_write(line, us) >= 0) {
            return 0;
        }
        usleep(RETRY_BACKOFF);
    }

    return 1;
}

static int retry_move(struct gpiod_line *line, uint32_t us) {
    int retries = MAX_RETRIES;

    while (retries--) {
        if (gpiod_line_write(line, us) >= 0) {
            return 0;
        }
        usleep(RETRY_BACKOFF);
    }

    return 1;
}

static void critical_warning(const char *msg) {
    fprintf(stderr, "CRITICAL: %s\n", msg);
}

static void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

