    if (!line) {
        gpiod_chip_put(chip);
        fprintf(stderr, "Failed to get line for nozzle GPIO %d\n", NOZZLE_GPIO);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sig_atomic_t moisture = (sig_atomic_t)((time_t)rand() % 100);

        if (moisture < 50) {
            if (!valve_open(VALVE_GPIO, 1500)) {
                fprintf(stderr, "Failed to open valve\n");
                critical_warning("Failed to close valve");
                break;
            }

            for (int i = 0; i < 5; i++) {
                switch (i) {
                    case 0: nozzle_move(NOZZLE_GPIO, 500, 0); break;
                    case 1: nozzle_move(NOZZLE_GPIO, 1000, 45); break;
                    case 2: nozzle_move(NOZZLE_GPIO, 1500, 90); break;
                    case 3: nozzle_move(NOZZLE_GPIO, 2000, 135); break;
                    case 4: nozzle_move(NOZZLE_GPIO, 2500, 180); break;
                }
                usleep(CYCLE_DELAY * 1000);
            }

            if (!valve_close(VALVE_GPIO, 500)) {
                fprintf(stderr, "Failed to close valve\n");
                critical_warning("Failed to close valve");
                break;
