#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c/i2c_dev.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define SAMPLE_RATE 10
#define SAMPLING_INTERVAL (1000000 / SAMPLE_RATE)

static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    struct gpiod_chip mpu_chip;
    struct gpiod_line sda, scl;
    struct i2c_rdwr_ioctl_data rdwr;
    struct i2c_dev i2c;
    int fd;
    int ret;

    // Register SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO pins for SDA and SCL
    ret = gpiod_chip_new(&mpu_chip, "GPIO2", &sda, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO for SDA\n");
        return ret;
    }
    ret = gpiod_chip_new(&mpu_chip, "GPIO3", &scl, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO for SCL\n");
        gpiod_chip_free(&mpu_chip);
        return ret;
    }

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_free(&mpu_chip);
        return fd;
    }

    // Configure I2C device
    rdwr.u8 = MPU6050_ADDR;
    rdwr.u8len = 1;
    rdwr.u8buf = &rdwr.u8;
    rdwr.u8buflen = 1;
    ioctl(fd, I2C_RDWR, &rdwr);

    // Initialize log file
    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_free(&mpu_chip);
        close(fd);
        return -1;
    }

    // Write header to log file
    time_t now = time(NULL);
    fprintf(log_file, "%ld", (long)now);
    fprintf(log_file, ",");

    // Read gyroscope data
    while (1) {
        // Set up I2C transaction
        rdwr.u8 = 0x3B; // Start reading from PWR_MGMT_1 register
        rdwr.u8len = 1;
        rdwr.u8buf = &rdwr.u8;
        rdwr.u8buflen = 1;

        // Perform I2C transaction
        ret = ioctl(fd, I2C_RDWR, &rdwr);
        if (ret < 0) {
            fprintf(stderr, "I2C transaction failed\n");
            break;
        }

        // Read gyroscope data
        rdwr.u8 = 0x19; // Start reading from GYRO_XOUT_H register
        rdwr.u8len = 6;
        rdwr.u8buf = &rdwr.u8;
        rdwr.u8buflen = 6;

        ret = ioctl(fd, I2C_RDWR, &rdwr);
        if (ret < 0) {
            fprintf(stderr, "I2C transaction failed\n");
            break;
        }

        // Write data to log file
        fprintf(log_file, ",%d,%d,%d", rdwr.u8[1], rdwr.u8[3], rdwr.u8[5]);
        fprintf(log_file, "\n");

        // Sleep for sampling interval
        usleep(SAMPLING_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_free(&mpu_chip);
    close(fd);

    return 0;
}

