#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <gpio.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define TIMEOUT_MS 50000
#define MIN_DISTANCE 0
#define MAX_DISTANCE 200
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MEASUREMENT_DELAY_MS 60

int gpio_init(void) {
    int ret;

    ret = gpio_init();
    if (ret < 0) {
        perror("Failed to initialize GPIO library");
        return ret;
    }

    return 0;
}

void gpio_cleanup(void) {
    gpio_uninit();
}

uint32_t get_distance(void) {
    uint32_t duration, distance;
    struct gpio_trigger trigger;
    struct gpio_edge edge;

    gpio_trigger_init(&trigger);
    gpio_edge_init(&edge);

    trigger.gpio = ECHO_GPIO;
    trigger.value = 1;
    trigger.active_high = 1;
    trigger.delay_us = 10;

    edge.gpio = ECHO_GPIO;
    edge.value = 0;
    edge.active_high = 0;
    edge.edge = GPIO_EDGE_RISING;
    edge.timeout_us = TIMEOUT_MS;

    if (gpio_trigger_start(&trigger) < 0 || gpio_edge_wait(&edge) < 0) {
        fprintf(stderr, "Error waiting for echo edge\n");
        return -1;
    }

    if (gpio_trigger_stop(&trigger) < 0) {
