#include <gpiod.h>
#include <i2c/i2c.h>
#include <vl53l1x.h>

#define RELAY_PIN 18
#define POLL_INTERVAL 100000 // 100 ms in microseconds
#define MAX_DISTANCE 50

struct vl53l1x_context *vl53l1x;
int relay_state = 0;

void sigint_handler(int signum) {
    if (vl53l1x) {
        vl53l1x_shutdown(vl53l1x);
    }
    gpio_unclaim(RELAY_PIN);
    exit(signum);
}

int main() {
    struct gpiod_chip_params params =GPIOD_CHIP_PARAMS_DEFAULT;
    struct gpiod_chip *chip;
    int ret;

    // Initialize GPIO
    ret = gpio_init();
    if (ret < 0) {
        perror("Failed to initialize GPIO");
        return ret;
    }

    // Claim the relay pin
    ret = gpio_claim(RELAY_PIN, &chip);
    if (ret < 0) {
        perror("Failed to claim relay pin");
        gpio_free(RELAY_PIN);
        return ret;
    }
    gpio_set_value(RELAY_PIN, 0);

    // Initialize I2C
    ret = i2c_open(1);
    if (ret < 0) {
        perror("Failed to open I2C bus 1");
        gpio_free(RELAY_PIN);
        return ret;
    }

    // Initialize VL53L1X sensor
    vl53l1x = vl53l1x_initialize(I2C_ADDR_VL53L1_I2C, NULL);
    if (!vl53l1x) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        i2c_close(1);
        gpio_free(RELAY_PIN);
        return -1;
    }

    // Register signal handler
    signal(SIGINT, sigint_handler);

    while (1) {
        uint32_t distance;
        ret = vl53l1x_start_measurement(vl53l1x);
        if (ret != 0) {
            fprintf(stderr, "Error starting measurement: %d\n", ret);
            continue;
        }

        ret = vl53l1x_get_range_data(vl53l1x, &distance);
        if (ret != 0) {
            fprintf(stderr, "Error getting range data: %d\n", ret);
            continue;
        }

        if (distance <= MAX_DISTANCE) {
            gpio_set_value(RELAY_PIN, 1);
        } else {
            gpio_set_value(RELAY_PIN, 0);
        }

        printf("Distance: %d mm\n", distance);

        usleep(POLL_INTERVAL);
    }

    // Clean up
    vl53l1x_shutdown(vl53l1x);
    i2c_close(1);
    gpio_free(RELAY_PIN);
    gpio_uninit();

    return 0;
}

