#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpio.h>

#define MPU6050_ADDR  0x68
#define SDA_GPIO  2
#define SCL_GPIO  3

struct mpu6050_data {
    int fd;
    int sda_gpio;
    int scl_gpio;
};

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpioTerminate();
    close(mpu6050.fd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up...\n");
    gpioTerminate();
    close(mpu6050.fd);
    exit(0);
}

int init_i2c(struct mpu6050_data *mpu6050) {
    mpu6050->fd = open("/dev/i2c-1", O_RDWR);
    if (mpu6050->fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    gpioInitialize();
    mpu6050->sda_gpio = gpioInitialisePin(SDA_GPIO);
    if (mpu6050->sda_gpio < 0) {
        fprintf(stderr, "Failed to initialize SDA GPIO: %s\n", strerror(errno));
        close(mpu6050->fd);
        return -1;
    }

    mpu6050->scl_gpio = gpioInitialisePin(SCL_GPIO);
    if (mpu6050->scl_gpio < 0) {
        fprintf(stderr, "Failed to initialize SCL GPIO: %s\n", strerror(errno));
        gpioTerminate();
        close(mpu6050->fd);
        return -1;
    }

    gpioSetMode(mpu6050->sda_gpio, PI_OUTPUT);
    gpioSetMode(mpu6050->scl_gpio, PI_OUTPUT);

    return 0;
}

void cleanup(struct mpu6050_data *mpu6050) {
    gpioTerminate();
    close(mpu6050->fd);
}

int main() {
    struct mpu6050_data mpu6050;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c(&mpu6050) < 0) {
        fprintf(stderr, "Initialization failed, exiting...\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int x_gyro, y_gyro, z_gyro;
        int res = ioctl(mpu6050.fd, I2C_SLAVE, MPU6050_ADDR);
        if (res < 0) {
            fprintf(stderr, "Failed to address MPU6050, error: %s\n", strerror(errno));
            break;
        }

        res = ioctl(mpu6050.fd, I2C_MSG_PTR_IN, &x_gyro, 1);
        if (res < 0) {
            fprintf(stderr, "Failed to read x-axis gyro, error: %s\n", strerror(errno));
            break;
        }

        res = ioctl(mpu6050.fd, I2C_MSG_PTR_IN, &y_gyro, 1);
        if (res < 0) {
            fprintf(stderr, "Failed to read y-axis gyro, error: %s\n", strerror(errno));
            break;
        }

        res = ioctl(mpu6050.fd, I2C_MSG_PTR_IN, &z_gyro, 1);
        if (res < 0) {
            fprintf(stderr, "Failed to read z-axis gyro, error: %s\n", strerror(errno));
            break;
        }

        printf("X-axis rotation rate: %d\n", x_gyro);
        printf("Y-axis rotation rate: %d\n", y_gyro);
        printf("Z-axis rotation rate: %d\n", z_gyro);
    }

    cleanup(&mpu6050);
    return EXIT_SUCCESS;
}

