#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define RELAY_PINS {11, 12, 13, 15} // BCM numbers
#define CYCLE_SECONDS 86400
#define RELAY_ON_TIME 300
#define POLL_INTERVAL 60

static struct gpiod_chip *chip;
static struct gpiod_line *relay_lines[4];

static void sigint_handler(int signum) {
    gpiod_line_release_all(chip);
    gpiod_chip_close(chip);
    exit(signum);
}

static int setup_gpio(struct gpiod_chip *chip) {
    int i;
    for (i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get line for relay %d\n", RELAY_PINS[i]);
            return -1;
        }
        if (gpiod_line_request_output(relay_lines[i], 0)) {
            fprintf(stderr, "Failed to request output for relay %d\n", RELAY_PINS[i]);
            return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    struct timespec next_cycle, cycle_start;
    time_t current_time;
    struct tm *tm_info;
    char log_msg[20];

    chip = gpiod_chip_open("/dev/gpiod", NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    if (signal(SIGINT, sigint_handler) || signal(SIGTERM, sigint_handler)) {
        fprintf(stderr, "Failed to install signal handlers\n");
        return -1;
    }

    if (setup_gpio(chip)) {
        gpiod_chip_close(chip);
        return -1;
    }

    clock_gettime(CLOCK_REALTIME, &next_cycle);
    next_cycle.tv_sec += RELAY_ON_TIME;

    while (1) {
        clock_gettime(CLOCK_REALTIME, &cycle_start);

        if (cycle_start.tv_sec >= next_cycle.tv_sec) {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(relay_lines[i], 0);
                sleep(RELAY_ON_TIME);
                gpiod_line_set_value(relay_lines[i], 1);
                usleep(POLL_INTERVAL * 1000000 - (1000 / POLL_INTERVAL) * (cycle_start.tv_sec - next_cycle.tv_sec));
            }
            next_cycle.tv_sec += CYCLE_SECONDS;

            time(&current_time);
            tm_info = localtime(&current_time);
            strftime(log_msg, sizeof(log_msg), "%F %T", tm_info);
            FILE *log_file = fopen("watering_log.txt", "a");
            if (log_file) {
                fprintf(log_file, "%s: Cycle started\n", log_msg);
                fclose(log_file);
            }
        }

        usleep(POLL_INTERVAL * 1000000 - (1000 / POLL_INTERVAL) * (cycle_start.tv_sec - next_cycle.tv_sec));
    }

    gpiod_line_release_all(chip);
    gpiod_chip_close(chip);
    return 0;
}

