    while (1) {
        clock_gettime(CLOCK_REALTIME, &cycle_start);

        if (cycle_start.tv_sec >= next_cycle.tv_sec) {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(relay_lines[i], 0);
                sleep(RELAY_ON_TIME);
                gpiod_line_set_value(relay_lines[i], 1);
                usleep(POLL_INTERVAL * 1000000 - (1000 / POLL_INTERVAL) * (cycle_start.tv_sec - next_cycle.tv_sec));
            }
            next_cycle.tv_sec += CYCLE_SECONDS;

            time(&current_time);
            tm_info = localtime(&current_time);
            strftime(log_msg, sizeof(log_msg), "%F %T", tm_info);
            FILE *log_file = fopen("watering_log.txt", "a");
            if (log_file) {
                fprintf(log_file, "%s: Cycle started\n", log_msg);
                fclose(log_file);
            }
        }

        usleep(POLL_INTERVAL * 1000000 - (1000 / POLL_INTERVAL) * (cycle_start.tv_sec - next_cycle.tv_sec));
    }

    gpiod_line_release_all(chip);
    gpiod_chip_close(chip);
    return 0;
}
