#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define GPIO_PINS {17, 18, 27, 22}
#define LOG_FILE "smart_lighting.log"
#define SLEEP_TIME 1000000 // 1 second in microseconds
#define DUTY_CYCLE_INCREASE 1
#define TOTAL_SECONDS 1800 // 30 minutes

struct relay_info {
    int gpio;
    bool initialized;
    bool logging_enabled;
};

struct relay_info relays[NUM_RELAYS];
FILE *log_file = NULL;

void log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    if (log_file) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "[%ld.%09ld] ", ts.tv_sec, ts.tv_nsec);
        vfprintf(log_file, format, args);
        fputc('\n', log_file);
    }
    va_end(args);
}

void init_relay(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(gpio, "user");
    if (!chip) {
        log_event("Failed to open GPIO chip\n");
        return;
    }

    line = gpiod_chip_get_line(chip, GPIO_PINS[gpio]);
    if (!line) {
        log_event("Failed to get GPIO line for %d\n", gpio);
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_export(line, "user");
    if (ret < 0) {
        log_event("Failed to export GPIO line %d\n", gpio);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    relays[gpio].gpio = gpio;
    relays[gpio].initialized = true;
    relays[gpio].logging_enabled = true;

    gpiod_line_set_direction(line, GPIO_OUTPUT);

    log_event("Initialized GPIO %d as output\n", gpio);
}

void setup_pwm() {
    int ret;

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (!relays[i].initialized)
            init_relay(GPIO_PINS[i]);

        ret = gpiod_line_set_drv(relays[i].gpio, "pwm");
        if (ret < 0) {
            log_event("Failed to set PWM driver for GPIO %d\n", GPIO_PINS[i]);
            return;
        }

        ret = gpiod_line_set_value(relays[i].gpio, 0);
        if (ret < 0) {
            log_event("Failed to set initial PWM value for GPIO %d\n", GPIO_PINS[i]);
            return;
        }
    }
}

void cleanup_relay(int gpio) {
    gpiod_line_unexport(relays[gpio].gpio);
    gpiod_chip_close(NULL);
}

void cleanup_all_relays() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relays[i].initialized)
            cleanup_relay(GPIO_PINS[i]);
    }
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_RELAYS];

    log_file = fopen("smart_lighting.log", "w");
    if (!log_file) {
        log_event("Failed to open log file\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    setup_pwm();

    for (int i = 0; i < TOTAL_SECONDS; i++) {
        uint32_t duty_cycle = i * DUTY_CYCLE_INCREASE;

        for (int j = 0; j < NUM_RELAYS; j++) {
            lines[j] = gpiod_line_get(relays[j].gpio);
            ret = gpiod_line_set_value(lines[j], duty_cycle);
            if (ret < 0) {
                log_event("Failed to set PWM value for GPIO %d\n", GPIO_PINS[j]);
                break;
            }
        }

        usleep(SLEEP_TIME);
    }

    cleanup_all_relays();
    fclose(log_file);
    return EXIT_SUCCESS;
}

static void cleanup_handler(int signum) {
    log_event("Received signal %d, cleaning up resources\n", signum);
    cleanup_all_relays();
    fclose(log_file);
    exit(signum);
}

