#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>
#include <gpiod.h>

#define BUFFER_SIZE 100
#define I2C_ADDR 0x68
#define LED_GPIO 17
#define SAMPLING_PERIOD 50000 // 50 ms

typedef struct {
    float buffer[BUFFER_SIZE][3];
    int head, tail;
} CircularBuffer;

CircularBuffer cb;
gpiod_chip_registration *chip;

void init_gpio() {
    gpio_init();
    gpio_set_direction(LED_GPIO, GPIO_OUTPUT);
    gpio_set_value(LED_GPIO, 0);
}

void cleanup_gpio() {
    gpio_set_value(LED_GPIO, 0);
    gpio_free();
}

void signal_handler(int signum) {
    cleanup_gpio();
    gpiod_unregister(chip);
    exit(signum);
}

void init_i2c() {
    chip = gpiod_chip_register_with_name(NULL, "i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_get_line(chip, "sda", &gpiod_line_input) ||
        gpiod_chip_get_line(chip, "scl", &gpiod_line_output)) {
        fprintf(stderr, "Failed to get I2C lines\n");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_direction(gpiod_line_output, GPIO_OUTPUT);
    gpiod_line_set_value(gpiod_line_output, 1);
}

int read_mpu6050_gyro(float *x, float *y, float *z) {
    int ret;
    uint8_t buf[14];
    *x = *y = *z = 0;

    ret = gpiod_line_get_value(gpiod_line_output);
    if (ret < 0) {
        fprintf(stderr, "Failed to start I2C transfer\n");
        return ret;
    }

    ret = gpiod_transfer(gpiod_line_input, buf, sizeof(buf));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C\n");
        return ret;
    }

    *x = (buf[1] << 8) | buf[2];
    *y = (buf[3] << 8) | buf[4];
    *z = (buf[5] << 8) | buf[6];

    ret = gpiod_line_set_value(gpiod_line_output);
    if (ret < 0) {
        fprintf(stderr, "Failed to stop I2C transfer\n");
        return ret;
    }

    return 0;
}

void update_led(float x, float y, float z) {
    if (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) {
        gpio_set_value(LED_GPIO, 1);
    } else {
        gpio_set_value(LED_GPIO, 0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_i2c();

    cb.head = cb.tail = 0;

    while (1) {
        float x, y, z;
        clock_t start = clock();

        while (clock() - start < SAMPLING_PERIOD / 1000) {
            int ret = read_mpu6050_gyro(&x, &y, &z);
            if (ret) {
                if (ret == EINTR) {
                    continue;
                }
                fprintf(stderr, "Failed to read MPU-6050 after 3 attempts, exiting\n");
                cleanup_gpio();
                gpiod_unregister(chip);
                return ret;
            }

            update_led(x, y, z);

            cb.buffer[cb.head][0] = x;
            cb.buffer[cb.head][1] = y;
            cb.buffer[cb.head][2] = z;
            cb.head = (cb.head + 1) % BUFFER_SIZE;
        }

        // Print or process the circular buffer if needed
    }

    cleanup_gpio();
    gpiod_unregister(chip);
    return 0;
}

