#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP 0
#define GPIO_LINE_OFFSET 8
#define SPI_BAUDRATE 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MSB_FIRST true
#define READ_INTERVAL_MS 10000
#define MAX_RETRIES 3

struct spi_device spi;
int spi_fd;
gpiod_chip *gpio_chip;
gpiod_line *gpio_line;
FILE *log_file = NULL;

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_FRAMES, &spi.frames) < 0) {
        perror("Failed to set SPI frame size");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_BAUDRATE) < 0) {
        perror("Failed to set SPI baudrate");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_MSB_FIRST) < 0) {
        perror("Failed to set SPI MSB first");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE_OFFSET);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(gpio_line, NULL);
    gpiod_line_set_value(gpio_line, 0);
}

void log_data(double x_rate, double y_rate, double z_rate) {
    static int retry_count = 0;

    char timestamp[32];
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
    sprintf(timestamp + 19, ".%09lld", ts.tv_nsec);

    if (log_file) {
        fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate);
    } else {
        fprintf(stderr, "Error: log file is not open\n");
    }

    retry_count++;
    if (retry_count > MAX_RETRIES) {
        fprintf(stderr, "Error: SPI communication failed after %d retries\n", MAX_RETRIES);
    }
}

int main() {
    spi_init();
    gpio_init();
    log_file = fopen("gyro_log.txt", "a");

    while (true) {
        // Read data from MPU-9250 and extract x, y, z rates
        // ...

        // Assert chip select
        gpiod_line_set_value(gpio_line, 0);
        // Perform SPI read
        // ...
        // Deassert chip select
        gpiod_line_set_value(gpio_line, 1);

        log_data(x_rate, y_rate, z_rate);

        usleep(READ_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpiod_line_unref(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return 0;
}

