        fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate);
    } else {
        fprintf(stderr, "Error: log file is not open\n");
    }

    retry_count++;
    if (retry_count > MAX_RETRIES) {
        fprintf(stderr, "Error: SPI communication failed after %d retries\n", MAX_RETRIES);
    }
}

int main() {
    spi_init();
    gpio_init();
    log_file = fopen("gyro_log.txt", "a");

    while (true) {
        // Read data from MPU-9250 and extract x, y, z rates
        // ...

        // Assert chip select
        gpiod_line_set_value(gpio_line, 0);
        // Perform SPI read
        // ...
        // Deassert chip select
        gpiod_line_set_value(gpio_line, 1);

        log_data(x_rate, y_rate, z_rate);

        usleep(READ_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpiod_line_unref(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return 0;
}
