#define BUFFER_SIZE 64
#define LED_GPIO 17
#define SPI_BUS 0
#define CE0_GPIO 8
#define THRESHOLD 200

typedef struct {
    double x, y, z;
    uint64_t timestamp;
} Sample;

Sample circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

