    gpio_putv(fd, 1);
    usleep(duration_ms * 1000);
    gpio_putv(fd, 0);
    usleep(duration_ms * 1000);
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nExiting gracefully...\n");
        gpio_free();
        spi_close(spi);
        exit(0);
    }
}

int main() {
    struct spi_dev spi;
    int spi_fd, led_fd;
    gpio_init();

    spi_fd = spi_open(SPI_BUS, 1000000);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI bus\n");
        return 1;
    }

    spi_configure(spi_fd, 8, 0, SPI_MODE0);
    CE0_GPIO_fd = gpiod_open_device(NULL, "gpiochip0");
    if (!CE0_GPIO_fd) {
        fprintf(stderr, "Failed to initialize GPIO CE0\n");
        spi_close(spi_fd);
        return 1;
    }

    CE0_GPIO = gpiod_chip_get_gdio(CE0_GPIO_fd, 0);
    CE0_CHIP_CS = gpiod_chip_get_line(CE0_GPIO, "cs");
    gpiod_trigger_enable_output_signals(CE0_CHIP_CS);
    gpio_set_value(CE0_CHIP_CS, 1);

    led_fd = gpio_init(LED_GPIO);
    if (led_fd < 0) {
        fprintf(stderr, "Failed to initialize LED GPIO\n");
        spi_close(spi_fd);
        gpiod_free(CE0_GPIO_fd);
        return 1;
    }

    gpio_set_value(led_fd, 0);

    signal(SIGINT, signal_handler);

    while (1) {
        Sample sample;
        int ret = spi_transfer(spi_fd, &sample.x, sizeof(sample.x), &sample.y, sizeof(sample.y), &sample.z, sizeof(sample.z));
        if (ret != 3) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        if (abs(sample.x) > THRESHOLD || abs(sample.y) > THRESHOLD || abs(sample.z) > THRESHOLD) {
            gpio_set_value(led_fd, 1);
            blink_led(led_fd, 500);
            gpio_set_value(led_fd, 0);
        }

        sample.timestamp = time(NULL);
        circular_buffer[buffer_index++] = sample;
        if (buffer_index == BUFFER_SIZE) {
            buffer_index = 0;
        }
    }

    printf("\nCircular Buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%llu,%.2f,%.2f,%.2f\n", circular_buffer[i].timestamp, circular_buffer[i].x, circular_buffer[i].y, circular_buffer[i].z);
    }

    spi_close(spi_fd);
    gpiod_free(CE0_GPIO_fd);
    gpio_free();

    return 0;
}

