#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define LED_GPIO 21
#define MPU6050_ADDR 0x68
#define SAMPLE_INTERVAL 100000 // 100 ms

struct mpu_data {
    int16_t ax, ay, az;
    int16_t gx, gy, gz;
};

void signal_handler(int sig) {
    gpioTerminate();
    exit(sig);
}

void init_gpio() {
    gpioInit();
    gpioSetMode(LED_GPIO, GPIO_OUTPUT);
    gpioSet(LED_GPIO, 0);
}

void cleanup_gpio() {
    gpioSet(LED_GPIO, 1); // Turn off LED
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_gpio();

    int fd = gpioOpen(LED_GPIO, O_OUT);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    int mpu_fd = i2cOpen(MPU6050_ADDR);
    if (mpu_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioClose(fd);
        return 1;
    }

    struct mpu_data data;
    char timestamp[20];
    FILE *log_file = fopen("tilt_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(mpu_fd);
        gpioClose(fd);
        return 1;
    }

    while (1) {
        time_t rawtime;
        struct tm * timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%F %T", timeinfo);

        if (i2cWrite(mpu_fd, &data, sizeof(data)) != sizeof(data)) {
            fprintf(stderr, "I2C write failed\n");
            continue;
        }

        if (i2cRead(mpu_fd, (void *)&data, sizeof(data)) != sizeof(data)) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        float roll = atan2(data.ay, data.az) * 180 / M_PI;
        float pitch = atan2(data.ax, sqrt(data.ay * data.ay + data.az * data.az)) * 180 / M_PI;

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, roll, pitch);

        if (fabs(roll) > 45 || fabs(pitch) > 45) {
            gpioSet(LED_GPIO, 1); // Turn on LED
        } else {
            gpioSet(LED_GPIO, 0); // Turn off LED
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(mpu_fd);
    gpioClose(fd);
    cleanup_gpio();

    return 0;
}

