#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define GPIO_LED 17
#define MAX_RETRIES 3
#define DELAY_MS 10

int i2c_fd = -1;
int gpio_led_fd = -1;
FILE *log_file = NULL;

void setup_gpio() {
    const char *led_gpio_path = "/sys/class/gpio/gpio%d/value";
    char gpio_value[10];

    sprintf(gpio_value, "%d", GPIO_LED);
    if (access(led_gpio_path, F_OK) != -1) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            exit(EXIT_FAILURE);
        }

        if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
            perror("Failed to set I2C address");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        log_file = fopen("biometric_log.txt", "w");
        if (!log_file) {
            perror("Failed to open log file");
            close(i2c_fd);
            return;
        }

        gpio_led_fd = open(led_gpio_path, O_WRONLY);
        if (gpio_led_fd < 0) {
            perror("Failed to open GPIO");
            close(i2c_fd);
            fclose(log_file);
            return;
        }

        if (iocp_export(gpio_led_fd, "LED_Control") < 0) {
            perror("Failed to export GPIO");
            close(i2c_fd);
            fclose(log_file);
            return;
        }
    }
}

void cleanup_gpio() {
    if (gpio_led_fd >= 0) {
        iocp_unexport(gpio_led_fd);
        close(gpio_led_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void read_sensor_data(uint8_t *data, int len) {
    if (read(i2c_fd, data, len) != len) {
        fprintf(stderr, "Failed to read sensor data\n");
        // Retry up to 3 times
        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (read(i2c_fd, data, len) == len) {
                return;
            }
            usleep(DELAY_MS * 1000);
        }
        fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }
}

void log_data(uint8_t ambient_light, uint8_t proximity) {
    time_t now;
    struct tm *time_info;
    char timestamp[32];

    time(&now);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);
    fflush(log_file);
}

int main() {
    struct gpiod_chip_params params = {
        .gpio_chip_type = GPIO_CHIP_TYPE_LOCAL,
        .gpio_num_pins = 1,
        .gpio_pins = {GPIO_LED},
    };

    setup_gpio();

    signal(SIGINT, [](int signum) {
        cleanup_gpio();
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        cleanup_gpio();
        exit(0);
    });

    uint8_t data[6];
    while (1) {
        read_sensor_data(data, 6);

        uint8_t ambient_light = data[0];
        uint8_t proximity = data[1];

        if (proximity > 100) {
            if (write(gpio_led_fd, "1", 1) < 0) {
                perror("Failed to turn on LED");
                break;
            }
        } else {
            if (write(gpio_led_fd, "0", 1) < 0) {
                perror("Failed to turn off LED");
                break;
            }
        }

        log_data(ambient_light, proximity);
        usleep(100000);
    }

    cleanup_gpio();
    return 0;
}

