#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <spi.h>
#include <errno.h>

#define DEVICE_FS 1
#define SPI_CHANNEL 0
#define GPIO_CE0 8
#define SAMPLE_DELAY_MS 10
#define SAMPLES_PER_SEC 100
#define REG_ADDR_X 0x00
#define REG_ADDR_Y 0x01
#define READ_BIT 0x80
#define DUMMY_BYTE 0x00

struct spi_dev spi;
struct gpiod_chip chip;
FILE *file;

void spi_init() {
    spi.spi_fd = spi_open(SPI_CHANNEL, 1000000);
    if (spi.spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    spi.cs = gpiod_chip_alloc_name(&chip, "ce0", GPIO_CE0);
    if (!spi.cs) {
        spi_close(spi.spi_fd);
        perror("Failed to allocate GPIO for CE0");
        exit(EXIT_FAILURE);
    }
    gpiod_chip_set_owner(chip.id, GET_CURRENT_PROCESS_ID());
    gpiod_chip_set_direction(chip.id, GPIO_DIRECTION_OUTPUT);
    gpiod_chip_set_value_batch(chip.id, 1, 1);
}

int spi_transfer(uint8_t reg_addr) {
    uint8_t tx_data = reg_addr | READ_BIT;
    uint8_t rx_data;
    spi_transfer_bytes(&spi, &tx_data, 1, &rx_data, 1);
    return rx_data;
}

void sample_and_log() {
    uint16_t x_rate = spi_transfer(REG_ADDR_X);
    uint16_t y_rate = spi_transfer(REG_ADDR_Y);
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%d,%d\n", timestamp, x_rate, y_rate);
}

void sigint_handler(int signum) {
    gpiod_chip_release(chip.id);
    fclose(file);
