#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define ALERT_GPIO 17
#define CHECK_INTERVAL_MS 100
#define HIGH_THRESHOLD 500

static volatile sig_atomic_t sigint_received = 0;
static volatile sig_atomic_t sigterm_received = 0;
static FILE *log_file = NULL;
static gpio_context *ctx = NULL;
static uint32_t high_time = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static void sigterm_handler(int signum) {
    sigterm_received = 1;
}

static void sensor_callback(uint32_t edge, uint32_t pin, void *user_data) {
    if (edge & GPIOD_EDGE_RISE) {
        if (pin == SENSOR1_GPIO && gpio_get_level(ctx, SENSOR1_GPIO) == 1)
            high_time = 0;
        else if (pin == SENSOR2_GPIO && gpio_get_level(ctx, SENSOR2_GPIO) == 1)
            high_time = 0;
    }

    if (edge & GPIOD_EDGE_FALL) {
        if (pin == SENSOR1_GPIO && gpio_get_level(ctx, SENSOR1_GPIO) == 0)
            high_time++;
        else if (pin == SENSOR2_GPIO && gpio_get_level(ctx, SENSOR2_GPIO) == 0)
            high_time++;
    }

    if (high_time >= HIGH_THRESHOLD && gpio_get_level(ctx, SENSOR1_GPIO) == 1 && gpio_get_level(ctx, SENSOR2_GPIO) == 1) {
        log_seismic_event();
        trigger_alert();
        high_time = 0;
    }
}

static void log_seismic_event() {
    if (log_file != NULL) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    }
}

static void trigger_alert() {
    if (gpio_fd(ALERT_GPIO) >= 0) {
        gpio_put_level(ctx, ALERT_GPIO, 1);
        sleep(2);
        gpio_put_level(ctx, ALERT_GPIO, 0);
    }
}

int main() {
    struct sigaction sa_int, sa_term;
    sa_int.sa_handler = sigint_handler;
    sa_term.sa_handler = sigterm_handler;
    sigaction(SIGINT, &sa_int, NULL);
    sigaction(SIGTERM, &sa_term, NULL);

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    ctx = gpio_context_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create gpio context\n");
        gpio_free();
        return 1;
    }

    if ((log_file = fopen("seismic_events.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpio_free();
        return 1;
    }

    if (gpio_request_available(ctx, SENSOR1_GPIO) < 0 || gpio_request_available(ctx, SENSOR2_GPIO) < 0 ||
        gpio_request_available(ctx, ALERT_GPIO) < 0) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        fclose(log_file);
        gpio_free();
        return 1;
    }

    if (gpio_set_mode(ctx, SENSOR1_GPIO, GPIOD_IN) < 0 || gpio_set_mode(ctx, SENSOR2_GPIO, GPIOD_IN) < 0 ||
        gpio_set_mode(ctx, ALERT_GPIO, GPIOD_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpio_free();
        fclose(log_file);
        return 1;
    }

    if (gpio_set_edge_trigger(ctx, SENSOR1_GPIO, GPIOD_EDGE_RISE | GPIOD_EDGE_FALL) < 0 ||
        gpio_set_edge_trigger(ctx, SENSOR2_GPIO, GPIOD_EDGE_RISE | GPIOD_EDGE_FALL) < 0) {
        fprintf(stderr, "Failed to set edge triggers\n");
        gpio_free();
        fclose(log_file);
        return 1;
    }

    if (gpio_add_callback(ctx, SENSOR1_GPIO, GPIOD_EDGE_RISE | GPIOD_EDGE_FALL, sensor_callback, NULL) < 0 ||
        gpio_add_callback(ctx, SENSOR2_GPIO, GPIOD_EDGE_RISE | GPIOD_EDGE_FALL, sensor_callback, NULL)) {
        fprintf(stderr, "Failed to register callbacks\n");
        gpio_free();
        fclose(log_file);
        return 1;
    }

    while (!sigint_received && !sigterm_received) {
        sleep(CHECK_INTERVAL_MS / 1000);
    }

    gpio_free();
    fclose(log_file);
    return 0;
}

