#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <spi.h>

#define BUFFER_SIZE 100
#define THRESHOLD 20.0
#define LED_GPIO 17
#define CE_GPIO 8
#define SCLK_GPIO 11
#define MOSI_GPIO 10
#define MISO_GPIO 9

typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int tail;
} CircularBuffer;

CircularBuffer cb;

void cb_init(CircularBuffer *buf) {
    buf->head = buf->tail = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buf->data[i] = 0.0;
    }
}

bool is_full(CircularBuffer *buf) {
    return ((buf->head + 1) % BUFFER_SIZE) == buf->tail;
}

bool is_empty(CircularBuffer *buf) {
    return buf->head == buf->tail;
}

void cb_add(CircularBuffer *buf, float value) {
    buf->data[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
}

float cb_get(CircularBuffer *buf) {
    if (is_empty(buf)) {
        fprintf(stderr, "Error: Circular buffer is empty\n");
        exit(1);
    }
    float value = buf->data[buf->tail];
    buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    return value;
}

int main() {
    gpiod_chip_handle chip;
    gpiod_chip_handle_init(&chip);
    int ce_gpio = gpiod_chip_get_gpio(&chip, CE_GPIO);
    int sclk_gpio = gpiod_chip_get_gpio(&chip, SCLK_GPIO);
    int mosi_gpio = gpiod_chip_get_gpio(&chip, MOSI_GPIO);
    int miso_gpio = gpiod_chip_get_gpio(&chip, MISO_GPIO);

    if (ce_gpio < 0 || sclk_gpio < 0 || mosi_gpio < 0 || miso_gpio < 0) {
        fprintf(stderr, "Error: Failed to get GPIOs\n");
        return 1;
    }

    cb_init(&cb);

    spi_board_info bi;
    spi_board_info_populate(&bi);

    spi_handle_t spi;
    spi_open(&bi, &spi);
    spi_set_mode(spi, SPI_MODE0);
    spi_set_bits_per_word(spi, 8);
    spi_set_speed(spi, 1000000);

    if (spi_transfer(spi, 0x01 | (1 << 7), NULL, 0, 0) < 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return 1;
    }

    gpiod_trigger_setup(ce_gpio, "output", 0);
    gpiod_trigger_on(ce_gpio);

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        float rate = cb_get(&cb);
        if (rate > THRESHOLD) {
            gpiod_trigger_on(LED_GPIO);
        } else {
            gpiod_trigger_off(LED_GPIO);
        }

        cb_add(&cb, rate);

        spi_transfer(spi, 0x01 | (1 << 7), NULL, 0, 0);
        usleep(1000000); // Delay to control sampling rate
    }

    spi_close(spi);
    gpiod_trigger_off(ce_gpio);
    gpiod_trigger_off(LED_GPIO);
    gpiod_chip_close(chip);

    return 0;
}

