#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define PWM_FREQ 100
#define PWM_RANGE 255

#define GPIO_PINS {11, 12, 13}
#define NUM_LAMPS (sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]))

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_LAMPS];

void cleanup(int signum) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_release(chip);
    exit(signum);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration. Please provide an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        perror("Failed to open gpiod chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO%d\n", GPIO_PINS[i]);
            return EXIT_FAILURE;
        }
        gpiod_line_export(lines[i], "user/lamp%d");
    }

    gpiod_line_request_set(lines[0], PWM_FREQ, GPIOD_LINE_OUTPUT, 0, 0);
    gpiod_line_request_set(lines[1], PWM_FREQ, GPIOD_LINE_OUTPUT, 0, 0);
    gpiod_line_request_set(lines[2], PWM_FREQ, GPIOD_LINE_OUTPUT, 0, 0);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    for (int i = 0; i < NUM_LAMPS; i++) {
        int duty_cycle = PWM_RANGE;
        for (int j = 0; j < duration * PWM_FREQ; j++) {
            gpiod_line_set_value(lines[i], 1);
            usleep(1000000 / PWM_FREQ);
            duty_cycle--;
            if (duty_cycle == 0) {
                break;
            }
        }
        printf("Lamp %d faded out.\n", i + 1);
    }

    printf("All lamps faded out.\n");
    return EXIT_SUCCESS;
}

