#include <gpio.h>

#define RED_GPIO 17
#define RED_YELLOW_GPIO 22
#define GREEN_GPIO 23
#define YELLOW_GPIO 24

enum light_state { RED, RED_YELLOW, GREEN, YELLOW };
enum light_state current_state = RED;

void sigint_handler(int signum) {
    gpioTerminate();
    exit(signum == SIGINT ? 0 : 1);
}

void sigterm_handler(int signum) {
    gpioTerminate();
    exit(signum == SIGTERM ? 0 : 1);
}

void setup_gpio() {
    gpioInit();
    if (gpioRequest(RED_GPIO, "User LED") < 0 ||
        gpioRequest(RED_YELLOW_GPIO, "User LED") < 0 ||
        gpioRequest(GREEN_GPIO, "User LED") < 0 ||
        gpioRequest(YELLOW_GPIO, "User LED") < 0) {
        fprintf(stderr, "Error requesting GPIO pins\n");
        exit(1);
    }
}

void cleanup_gpio() {
    gpioRelease(RED_GPIO);
    gpioRelease(RED_YELLOW_GPIO);
    gpioRelease(GREEN_GPIO);
    gpioRelease(YELLOW_GPIO);
}

void set_light_state(enum light_state state) {
    switch (state) {
        case RED:
            gpioWrite(RED_GPIO, 0);
            gpioWrite(RED_YELLOW_GPIO, 1);
            gpioWrite(GREEN_GPIO, 1);
            gpioWrite(YELLOW_GPIO, 0);
            printf("State: Red\n");
            break;
        case RED_YELLOW:
            gpioWrite(RED_GPIO, 0);
            gpioWrite(RED_YELLOW_GPIO, 0);
            gpioWrite(GREEN_GPIO, 1);
            gpioWrite(YELLOW_GPIO, 1);
            printf("State: Red + Yellow\n");
            break;
        case GREEN:
            gpioWrite(RED_GPIO, 1);
            gpioWrite(RED_YELLOW_GPIO, 1);
            gpioWrite(GREEN_GPIO, 0);
            gpioWrite(YELLOW_GPIO, 0);
            printf("State: Green\n");
            break;
        case YELLOW:
            gpioWrite(RED_GPIO, 1);
            gpioWrite(RED_YELLOW_GPIO, 0);
            gpioWrite(GREEN_GPIO, 1);
            gpioWrite(YELLOW_GPIO, 1);
            printf("State: Yellow\n");
            break;
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    setup_gpio();

    while (1) {
        set_light_state(current_state);

        switch (current_state) {
            case RED:
                current_state = RED_YELLOW;
                break;
            case RED_YELLOW:
                current_state = GREEN;
                break;
            case GREEN:
                current_state = YELLOW;
                break;
            case YELLOW:
                current_state = RED;
                break;
        }

        usleep(1000000); // Sleep for 1 second
    }

    cleanup_gpio();
    return 0;
}

