#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>
#include <gpiod.h>

#define ELECTRODE 0
#define DELAY_MS 10
#define DEBOUNCE_DELAY_MS 100
#define I2C_ADDR 0x5A
#define RELAY_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static FILE *log_file = NULL;

void log_error(const char *format, ...) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        fprintf(log_file, "%s: ", timestamp);
        va_list args;
        va_start(args, format);
        vfprintf(log_file, format, args);
        va_end(args);
        fprintf(log_file, "\n");
    }
}

void init_gpio() {
    int ret = gpioInitialize();
    if (ret < 0) {
        log_error("Failed to initialize GPIO: %s\n", strerror(ret));
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        log_error("Failed to get GPIO line for relay\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_export(relay_line, "user") < 0) {
        log_error("Failed to export GPIO line for relay\n");
        gpiod_chip_free(chip);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetDirection(relay_line, GPIO_OUTPUT);
    gpioSetValue(relay_line, 0);
}

void cleanup_gpio() {
    gpioUnexport(relay_line);
    gpiod_chip_free(chip);
    gpioTerminate();
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup_gpio();
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

void read_touch_and_toggle_relay() {
    int touch_status;
    bool last_touch_state = false;
    bool current_touch_state;

    while (1) {
        if (i2c_read_reg_byte(I2C_ADDR, ELECTRODE) != ELECTRODE) {
            log_error("I2C read error\n");
            break;
        }

        touch_status = (int)i2c_read_reg_byte(I2C_ADDR, ELECTRODE);
        current_touch_state = (touch_status == 1);

        if (current_touch_state && !last_touch_state) {
            gpioSetValue(relay_line, !gpioGetValue(relay_line));
            last_touch_state = true;
        } else if (!current_touch_state && last_touch_state) {
            last_touch_state = false;
        }

        usleep(DELAY_MS * 1000);
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    chip = gpiod_chip_open(NULL);
    if (!chip) {
        log_error("Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        log_error("Failed to open log file\n");
        gpiod_chip_free(chip);
        return EXIT_FAILURE;
    }

    init_gpio();

    read_touch_and_toggle_relay();

    cleanup_gpio();
    fclose(log_file);
    return EXIT_SUCCESS;
}

