#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LED_GPIO 23
#define LOG_FILE "flame_log.txt"
#define CONSECUTIVE_READS 3
#define DELAY_MS 50

gpio_context ctx;
FILE *log_file;

void signal_handler(int signum) {
    gpio_stop(ctx);
    fclose(log_file);
    exit(signum);
}

void init_gpio(void) {
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_request(FLAME_SENSOR_GPIO, "FLAME_SENSOR") < 0 ||
        gpio_request(BUZZER_GPIO, "BUZZER") < 0 ||
        gpio_request(LED_GPIO, "LED") < 0) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        gpio_terminate();
        exit(EXIT_FAILURE);
    }

    gpio_set_direction(FLAME_SENSOR_GPIO, GPIO_OUT);
    gpio_set_direction(BUZZER_GPIO, GPIO_OUT);
    gpio_set_direction(LED_GPIO, GPIO_OUT);
    gpio_set(BUZZER_GPIO, 0);
    gpio_set(LED_GPIO, 0);
}

bool read_flame_sensor(void) {
    bool state;
    if (gpio_get(FLAME_SENSOR_GPIO) < 0) {
        fprintf(stderr, "Failed to read from FLAME_SENSOR GPIO\n");
        exit(EXIT_FAILURE);
    }
    state = gpio_get(FLAME_SENSOR_GPIO) == 0;
    return state;
}

void log_flame_detection(const char *timestamp) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%s - Flame Detected\n", timestamp);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_gpio();

    while (true) {
        int consecutive_low = 0;
        char timestamp[20];
        time_t t;
        time(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

        for (int i = 0; i < CONSECUTIVE_READS; ++i) {
            if (read_flame_sensor()) {
                break;
            }
            consecutive_low++;
            if (consecutive_low == CONSECUTIVE_READS - 1) {
                log_flame_detection(timestamp);
                gpio_set(BUZZER_GPIO, 1);
                gpio_set(LED_GPIO, 1);
                printf("Flame Detected! Buzzer and LED activated.\n");
                break;
            }
            time(NULL);
            sleep(DELAY_MS / 1000);
        }

        if (consecutive_low == CONSECUTIVE_READS) {
            gpio_set(BUZZER_GPIO, 0);
            gpio_set(LED_GPIO, 0);
            printf("Flame condition cleared. Buzzer and LED deactivated.\n");
        }
    }

    gpio_terminate();
    return 0;
}

