#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define DISPENSE_INTERVAL 1000
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27
#define LOG_FILE "dispense_log.txt"

void sigint_handler(int signum) {
    printf("Ctrl+C detected, initiating shutdown...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    gpioInit();
    if (gpioFail()) {
        fprintf(stderr, "Failed to initialize GPIO library.\n");
        return 1;
    }

    FILE *log_file = fopen("dispense_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    struct tm tm;
    time_t now;
    time(&now);
    localtime_r(&now, &tm);

    while (1) {
        gpioSetMode(SOLENOID_1_GPIO, GPIO_OUTPUT);
        gpioSetMode(SOLENOID_2_GPIO, GPIO_OUTPUT);

        gpioWrite(SOLENOID_1_GPIO, 1);
        gpioWrite(SOLENOID_2_GPIO, 0);
        gpiod(SOLENOID_1_GPIO, DISPENSE_INTERVAL / 2);

        gpioWrite(SOLENOID_1_GPIO, 0);
        gpioWrite(SOLENOID_2_GPIO, 1);
        gpiod(SOLENOID_2_GPIO, DISPENSE_INTERVAL / 2);

        fprintf(log_file, "Dispense event at %s, Solenoid 1: GPIO%d, Solenoid 2: GPIO%d, Duration: %d ms\n",
                ctime(&now), SOLENOID_1_GPIO, SOLENOID_2_GPIO, DISPENSE_INTERVAL);

        usleep(5000000); // Sleep for 5 seconds
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

int register_sigint_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    return 0;
}

int main_with_sigint_handler() {
    if (register_sigint_handler()) {
        fprintf(stderr, "Failed to register SIGINT handler.\n");
        return 1;
    }
    return main();
}

