static void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    struct gpio_setup setup;
    gpio_init();

    if (gpio_setup_pin(TOUCH_SENSOR_PIN, &setup) < 0 ||
        gpio_setup_pin(RELAY_PIN, &setup) < 0) {
        fprintf(stderr, "Failed to initialize GPIO pins\n");
        return EXIT_FAILURE;
    }

    gpio_set_direction(TOUCH_SENSOR_PIN, GPIO_OUT);
    gpio_set_direction(RELAY_PIN, GPIO_OUT);

    gpio_set_value(TOUCH_SENSOR_PIN, 0); // Pull-down
    gpio_set_value(RELAY_PIN, 0); // Relay off

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (true) {
        if (gpio_get_value(TOUCH_SENSOR_PIN) == 1) {
            if (!touch_detected) {
                gpio_set_value(RELAY_PIN, 1); // Turn on relay
                touch_detected = true;
                printf("Touch detected, relay ON\n");
            } else {
                // Debounce delay
                if (time(NULL) > last_touch_time + DEBOUNCE_DELAY / 1000000.0) {
                    gpio_set_value(RELAY_PIN, 1); // Turn on relay
                    touch_detected = true;
                    printf("Touch detected, relay ON\n");
                }
            }
        } else {
            touch_detected = false;
            gpio_set_value(RELAY_PIN, 0); // Turn off relay
            printf("No touch, relay OFF\n");
        }

        usleep(100000); // Check every 100 ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

