#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27
#define SENSITIVITY_DEFAULT 1.0
#define BUFFER_SIZE 1024
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define UPDATE_INTERVAL (10 * 1000 / 1000) // 10 ms

#ifdef ALSA_AVAILABLE
static snd_pcm_t *pcm_handle = NULL;
#endif

static struct gpiod_chip chip;
static struct gpiod_line line_red, line_green, line_blue;

void init_led() {
    gpiod_chip_open(&chip, "gpiochip0");
    gpiod_chip_add_line(&chip, &line_red, "GPIO17");
    gpiod_chip_add_line(&chip, &line_green, "GPIO18");
    gpiod_chip_add_line(&chip, &line_blue, "GPIO27");
    gpiod_chip_enable_line(&line_red, true);
    gpiod_chip_enable_line(&line_green, true);
    gpiod_chip_enable_line(&line_blue, true);
}

void cleanup_led() {
    gpiod_chip_disable_line(&line_red, false);
    gpiod_chip_disable_line(&line_green, false);
    gpiod_chip_disable_line(&line_blue, false);
    gpiod_chip_close(&chip);
}

void set_led_color(double r, double g, double b) {
    uint32_t red = (uint32_t)(r * 255);
    uint32_t green = (uint32_t)(g * 255);
    uint32_t blue = (uint32_t)(b * 255);
    gpiod_line_write(&line_red, red);
    gpiod_line_write(&line_green, green);
    gpiod_line_write(&line_blue, blue);
}

double compute_rms(const short *buffer, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i] * buffer[i];
    }
    return sqrt(sum / size);
}

int main(int argc, char *argv[]) {
    const char *device_name = "default";
    double sensitivity = SENSITIVITY_DEFAULT;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
    }

    init_led();

    if (#ifdef ALSA_AVAILABLE
        snd_pcm_open(&pcm_handle, device_name, SND_PCM_STREAM_CAPTURE, 0) < 0) {
        fprintf(stderr, "Failed to open ALSA device: %s\n", snd_pcm_error_string(snd_pcm_error));
        cleanup_led();
        return 1;
    }

    if (snd_pcm_prepare(pcm_handle) < 0) {
        fprintf(stderr, "Failed to prepare ALSA device: %s\n", snd_pcm_error_string(snd_pcm_error));
        goto cleanup;
    }

    snd_pcm_sw_params_t *params = malloc(sizeof(*params));
    if (!params) {
        fprintf(stderr, "Failed to allocate ALSA sw_params\n");
        goto cleanup;
    }

    snd_pcm_sw_params_memset(params);
    snd_pcm_sw_params_set_access(params, pcm_handle, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_sw_params_set_format(params, pcm_handle, SND_PCM_FORMAT_S16_LE);
    snd_pcm_sw_params_set_rate_near(params, pcm_handle, SAMPLE_RATE, 0);
    snd_pcm_sw_params_set_channels(params, pcm_handle, 1);
    snd_pcm_sw_params_set_period_size(params, pcm_handle, PERIOD_SIZE);
    snd_pcm_sw_params_set_start_threshold(params, pcm_handle, PERIOD_SIZE);

    if (snd_pcm_sw_params(pcm_handle, params) < 0) {
        fprintf(stderr, "Failed to set ALSA sw_params: %s\n", snd_pcm_error_string(snd_pcm_error));
        free(params);
        goto cleanup;
    }
    free(params);

    short buffer[BUFFER_SIZE];
    while (1) {
        int ret = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
        if (ret < 0) {
            if (snd_pcm_recover(pcm_handle, ret, snd_pcm_error) < 0) {
                fprintf(stderr, "Failed to recover from ALSA error: %s\n", snd_pcm_error_string(snd_pcm_error));
            }
        } else if (ret != BUFFER_SIZE) {
            fprintf(stderr, "ALSA buffer overrun\n");
            break;
        }

        double rms = compute_rms(buffer, ret);
        uint8_t red = (uint8_t)(rms * sensitivity);
        uint8_t green = (uint8_t)(rms * sensitivity);
        uint8_t blue = (uint8_t)(rms * sensitivity);

        set_led_color(red, green, blue);

        usleep(UPDATE_INTERVAL);
    }

cleanup:
    cleanup_led();
#ifdef ALSA_AVAILABLE
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
#endif
    return 0;
}

