#define I2C_BUS 1
#define I2C_ADDR 0x29
#define INTEGRATION_TIME 154000 // 154 ms

struct sensor_data {
    time_t timestamp;
    uint16_t clear, red, green, blue;
};

FILE *csv_file = NULL;

void sigint_handler(int signum) {
    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    gpioInit();

    int fd = gpioI2COpen(I2C_BUS, I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (gpioI2CWrite(fd, 0x40) < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        gpioClose(fd);
        return 1;
    }

    if (gpioI2CRead(fd, (void*) &struct_data, sizeof(struct_data)) < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        gpioClose(fd);
        return 1;
    }

    csv_file = fopen("color_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        gpioClose(fd);
        return 1;
    }

    fprintf(csv_file, "Timestamp,Clear,Red,Green,Blue\n");

    while (1) {
        struct sensor_data data;
        data.timestamp = time(NULL);

        if (gpioI2CWrite(fd, 0x40) < 0) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            data.clear = data.red = data.green = data.blue = 0;
