#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL_MS 200
#define VIDEO_DURATION_S 5

static volatile sig_atomic_t sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static int sensor_init(void) {
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return -1;
    }

    if (gpio_request_available(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to request GPIO %d\n", GPIO_PIN);
        gpio_exit();
        return -1;
    }

    if (gpio_set_wd(GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpio_release(GPIO_PIN);
        return -1;
    }

    return 0;
}

static void sensor_deinit(void) {
    gpio_release(GPIO_PIN);
    gpio_exit();
}

static int read_sensor(void) {
    uint32_t value;
    if (gpio_get_level(GPIO_PIN, &value) < 0) {
        fprintf(stderr, "Failed to read GPIO %d level\n", GPIO_PIN);
        return -1;
    }

    return value == 0;
}

static void log_motion_event(const char *timestamp) {
    FILE *log_file = fopen("/home/pi/logs/motion_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

static void start_video_capture(const char *timestamp) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -t %d -o /home/pi/videos/%s.h264", VIDEO_DURATION_S, timestamp);
    if (system(command) < 0) {
        perror("Failed to execute video capture command");
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (sensor_init() < 0) {
        return 1;
    }

    while (1) {
        if (sigint_received) {
            break;
        }

        int motion_detected = read_sensor();
        if (motion_detected) {
            time_t now_time = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now_time));

            log_motion_event(timestamp);
            start_video_capture(timestamp);
        }

        usleep(DEBOUNCE_INTERVAL_MS * 1000);
    }

    sensor_deinit();
    return 0;
}

