    if (!log_file_fd) {
        perror("Failed to open log file");
        return 1;
    }

    mpu.fd = gpiod_i2c_open(I2C_BUS, MPU6050_ADDR);
    if (!mpu.fd) {
        perror("Failed to open I2C device");
        return 1;
    }

    mpu.chip = gpiod_chip_get(gpiod_get_chip_by_fd(mpu.fd));
    if (!mpu.chip) {
        gpiod_i2c_close(mpu.fd);
        perror("Failed to get gpiod chip");
        return 1;
    }

    if (gpiod_chip_add_listener(mpu.chip, NULL, 0) < 0) {
        perror("Failed to add chip listener");
        return 1;
    }

    if (gpiod_chip_enable_output(mpu.chip, 0) < 0) {
        perror("Failed to enable output");
        return 1;
    }

    while (1) {
        int retries = MAX_REINIT_ATTEMPTS;
        int16_t data_x, data_y, data_z;

        while (retries > 0) {
            if (read_mpu6050(&mpu, &data_x, &data_y, &data_z) < 0) {
                retries--;
                if (retries > 0) {
                    reinit_mpu6050(&mpu);
                } else {
                    fprintf(stderr, "Error reading MPU6050, giving up.\n");
                }
            } else {
                break;
            }
        }

        if (retries == 0) {
            fprintf(stderr, "Error reading MPU6050 after %d attempts, continuing.\n", MAX_REINIT_ATTEMPTS);
            continue;
        }

        time_t cur_time = time(NULL);
        struct tm *local_time = localtime(&cur_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3N", local_time);

