    gpio_cleanup();
    fclose(log_file);
    exit(signum);
}

void setup() {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO library");
        exit(EXIT_FAILURE);
    }

    if (!(log_file = fopen(LOG_FILE, "w"))) {
        perror("Failed to open log file");
        gpio_cleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
}

void cleanup() {
    gpio_cleanup();
    fclose(log_file);
}

