    setup();

    while (1) {
        int moisture = rand() % 100 + 1;
        srand(time(NULL));

        char *states[ZONES];
        for (int i = 0; i < ZONES; i++) {
            if (moisture < 30) {
                gpio_set(RELAY_PINS[i], 0);
                states[i] = "ON";
