#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <adxl345.h>

#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 5000000 // 0.5 seconds in microseconds
#define ALARM_GPIO 27
#define I2C_ADDR 0x53
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds

struct timespec start_time, end_time;
int freefall_count = 0;
int freefall_duration_counter = 0;
int alarm_active = 0;
int i2c_fd;
int adxl_fd;

void sigint_handler(int signum) {
    if (adxl_fd != -1) {
        adxl345_close(adxl_fd);
        adxl_fd = -1;
    }
    if (gpio_is_available(ALARM_GPIO)) {
        gpiod_set_value(ALARM_GPIO, 0);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = adxl345_open_i2c(I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error opening I2C device\n");
        return 1;
    }

    adxl_fd = adxl345_open(i2c_fd);
    if (adxl_fd == -1) {
        adxl345_close(i2c_fd);
        i2c_fd = -1;
        fprintf(stderr, "Error opening ADXL345 device\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    if (gpiod_export(ALARM_GPIO, "user") < 0) {
        fprintf(stderr, "Error exporting GPIO %d\n", ALARM_GPIO);
        return 1;
    }

    if (gpiod_set_direction(ALARM_GPIO, "out") < 0) {
        fprintf(stderr, "Error setting GPIO %d direction\n", ALARM_GPIO);
        return 1;
    }

    gpiod_set_value(ALARM_GPIO, 0);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        int16_t x, y, z;
        if (adxl345_read_data(adxl_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading data from ADXL345\n");
            continue;
        }

        if (abs(x) < FREEFALL_THRESHOLD && abs(y) < FREEFALL_THRESHOLD && abs(z) < FREEFALL_THRESHOLD) {
            freefall_duration_counter += SAMPLE_INTERVAL;
        } else {
            freefall_duration_counter = 0;
        }

        if (freefall_duration_counter >= FREEFALL_DURATION * 2) {
            if (!alarm_active) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                if ((end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) >= FREEFALL_DURATION) {
                    alarm_active = 1;
                    gpiod_set_value(ALARM_GPIO, 1);
                    clock_gettime(CLOCK_MONOTONIC, &start_time);
                }
            }
        }

        if (alarm_active) {
            if ((clock_gettime(CLOCK_MONOTONIC, &end_time) - start_time).tv_sec * 1000000 + (clock_gettime(CLOCK_MONOTONIC, &end_time).tv_nsec - start_time.tv_nsec) >= 5000000000) {
                alarm_active = 0;
                gpiod_set_value(ALARM_GPIO, 0);
            }
        }

        if (alarm_active) {
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));

            FILE *log_file = fopen("freefall.log", "a");
            if (log_file != NULL) {
                fprintf(log_file, "%s, %d.%03d, %d.%03d, %d.%03d\n", timestamp,
                        (int)(x * 1000), (int)((x * 1000) % 1000),
                        (int)(y * 1000), (int)((y * 1000) % 1000),
                        (int)(z * 1000), (int)((z * 1000) % 1000));
                fclose(log_file);
            }
        }

        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

