#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdatomic.h>
#include <gpiod.h>

#define TRIG_GPIO 4
#define ECHO_GPIO 18
#define MAX_RANGE_CM 23200
#define TIMEOUT_MS 100
#define TRIG_PULSE_US 10000
#define WAIT_BETWEEN_TRIGGERS_MS 200

atomic_uint32_t tick_counter;
FILE *log_file;
gpiod_chip *chip;
gpiod_line *trig_line;
gpiod_line *echo_line;
pthread_mutex_t mutex;

void sigint_handler(int signum) {
    gpiod_drain_delete_group(chip);
    pthread_mutex_destroy(&mutex);
    fclose(log_file);
    exit(0);
}

void init_gpio() {
    int ret;

    ret = gpiod_in_init();
    if (ret) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(1);
    }

    chip = gpiod_chip_open(0, "raspberrypi");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_out_close(0);
        exit(1);
    }

    trig_line = gpiod_chip_get_line(chip, "GPIO" STRINGIFY(TRIG_GPIO));
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(chip);
        gpiod_out_close(0);
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, "GPIO" STRINGIFY(ECHO_GPIO));
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_line_free(trig_line);
        gpiod_chip_close(chip);
        gpiod_out_close(0);
        exit(1);
    }

    gpiod_line_export(trig_line, "user");
    gpiod_line_export(echo_line, "user");

    ret = pthread_mutex_init(&mutex, NULL);
    if (ret) {
        fprintf(stderr, "Failed to initialize mutex\n");
        gpiod_line_free(trig_line);
        gpiod_line_free(echo_line);
        gpiod_chip_close(chip);
        gpiod_out_close(0);
        exit(1);
    }

    ret = pthread_sigmask(SIG_IGN, NULL, &sigint_mask);
    if (ret) {
        fprintf(stderr, "Failed to ignore SIGINT\n");
        pthread_mutex_destroy(&mutex);
        gpiod_line_free(trig_line);
        gpiod_line_free(echo_line);
        gpiod_chip_close(chip);
        gpiod_out_close(0);
        exit(1);
    }
}

void cleanup_gpio() {
    gpiod_line_unexport(trig_line);
    gpiod_line_unexport(echo_line);
    gpiod_line_free(trig_line);
    gpiod_line_free(echo_line);
    gpiod_chip_close(chip);
    gpiod_out_close(0);
    pthread_mutex_destroy(&mutex);
}

void *echo_callback(void *arg) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t timestamp_ns = ts.tv_sec * 1000000000ULL + ts.tv_nsec;

    pthread_mutex_lock(&mutex);
    if (gpiod_line_get_value(echo_line)) {
        uint32_t pulse_width_us = atomic_fetch_add(&tick_counter, TRIG_PULSE_US);
        gpiod_line_set_value(trig_line, 0);

        if (pulse_width_us > MAX_RANGE_CM * 74) { // 74 µs/cm
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        if (timestamp_ns - last_trigger_timestamp_ns > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout error\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        fprintf(log_file, "%llu,%lu\n", timestamp_ns, pulse_width_us / 74);
        pthread_mutex_unlock(&mutex);
    } else {
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int main() {
    struct sigaction sa;
    sigint_mask = 0;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    init_gpio();
    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_gpio();
        return 1;
    }

    fprintf(log_file, "timestamp_ns,distance_cm\n");

    gpiod_line_set_value(trig_line, 1);
    gpiod_line_set_value(trig_line, 0);

    last_trigger_timestamp_ns = tick_counter;

    while (1) {
        gpiod_add_callback(echo_line, GPIOD_EVENT_RISING | GPIOD_EVENT_FALLING, echo_callback, NULL);
        usleep(WAIT_BETWEEN_TRIGGERS_MS * 1000);
    }

    cleanup_gpio();
    fclose(log_file);
    return 0;
}

