    fprintf(log_file, "timestamp_ns,distance_cm\n");

    gpiod_line_set_value(trig_line, 1);
    gpiod_line_set_value(trig_line, 0);

    last_trigger_timestamp_ns = tick_counter;

    while (1) {
        gpiod_add_callback(echo_line, GPIOD_EVENT_RISING | GPIOD_EVENT_FALLING, echo_callback, NULL);
        usleep(WAIT_BETWEEN_TRIGGERS_MS * 1000);
    }

    cleanup_gpio();
    fclose(log_file);
    return 0;
}
