struct sensor_data {
    int16_t ax, ay, az;
};

int freefall_thr = FREEFALL_THR;
int impact_thr = IMPACT_THR;

void sigint_handler(int signum) {
    gpiod_unbind(buzzer_chip, buzzer_gpio);
    exit(0);
}

int read_accel(struct sensor_data *data) {
    int retries = MAX_RETRIES;
    while (retries > 0) {
        if (wiringPiI2CReadReg16(LIS3DH_ADDR, 0x28) == 0x4000) {
            data->ax = (int16_t)((wiringPiI2CReadReg16(LIS3DH_ADDR, 0x2A) << 8) | wiringPiI2CReadReg8(LIS3DH_ADDR, 0x2B));
            data->ay = (int16_t)((wiringPiI2CReadReg16(LIS3DH_ADDR, 0x2C) << 8) | wiringPiI2CReadReg8(LIS3DH_ADDR, 0x2D));
            data->az = (int16_t)((wiringPiI2CReadReg16(LIS3DH_ADDR, 0x2E) << 8) | wiringPiI2CReadReg8(LIS3DH_ADDR, 0x2F));
            return 0;
        }
        retries--;
        delay(100);
    }
    return -1;
}

