    struct sensor_data sensor_data;
    int buzzer_gpio, ret;
    gpiod_chip_reg_desc_t *chip;
    gpiod_chip_reg_t *reg;

    signal(SIGINT, sigint_handler);

    if (argc > 1) {
        freefall_thr = atof(argv[1]);
    }
    if (argc > 2) {
        impact_thr = atof(argv[2]);
    }

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to initialize wiringPi\n");
        return 1;
    }

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    if (wiringPiI2CInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpiod_exit();
        return 1;
    }

    if ((chip = gpiod_chip_find("I2C-1")) == NULL) {
        fprintf(stderr, "Failed to find I2C-1 chip\n");
        gpiod_exit();
        wiringPiI2CClose(NULL);
        return 1;
    }

    if ((reg = gpiod_chip_get_reg_by_name(chip, "gpio0")) == NULL) {
        fprintf(stderr, "Failed to find gpio0 register\n");
        gpiod_exit();
        wiringPiI2CClose(NULL);
        return 1;
    }

    buzzer_gpio = gpiod_reg_get_gpio(reg);
    if (gpiod_export(reg, GPIOD_EXPORT_OTG) < 0) {
        fprintf(stderr, "Failed to export gpio0\n");
        gpiod_unbind(chip, reg);
        gpiod_exit();
        wiringPiI2CClose(NULL);
        return 1;
    }
    gpiod_set_value(reg, 1);

    if (read_accel(&sensor_data) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        gpiod_unexport(reg);
        gpiod_exit();
        wiringPiI2CClose(NULL);
        return 1;
    }

    while (1) {
        int accel_mag = sqrt(sensor_data.ax * sensor_data.ax + sensor_data.ay * sensor_data.ay + sensor_data.az * sensor_data.az);

        if (accel_mag < freefall_thr) {
            printf("Free-fall detected\n");
        }

        if (accel_mag > impact_thr) {
            printf("Impact detected\n");
            gpiod_set_value(reg, 0); // Turn off buzzer
            sleep(1);
            gpiod_set_value(reg, 1); // Turn on buzzer
        }

        delay(100);
    }

    gpiod_unexport(reg);
    gpiod_unbind(chip, reg);
    gpiod_exit();
    wiringPiI2CClose(NULL);

    return 0;
}

