#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEPS_PER_REVOLUTION 2048
#define GEAR_RATIO 64
#define SQUARE_MM 50
#define STEP_DELAY 1000000 // 1000 µs

void stop_motors(int signum) {
    gpio_put(MOTOR1_IN1, 0);
    gpio_put(MOTOR1_IN2, 0);
    gpio_put(MOTOR1_IN3, 0);
    gpio_put(MOTOR1_IN4, 0);

    gpio_put(MOTOR2_IN1, 0);
    gpio_put(MOTOR2_IN2, 0);
    gpio_put(MOTOR2_IN3, 0);
    gpio_put(MOTOR2_IN4, 0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = stop_motors;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
