        gpio_request(MOTOR2_IN2, "MOTOR2_IN2") < 0 ||
        gpio_request(MOTOR2_IN3, "MOTOR2_IN3") < 0 ||
        gpio_request(MOTOR2_IN4, "MOTOR2_IN4") < 0) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        gpio_free();
        return EXIT_FAILURE;
    }

    int steps_per_mm = STEPS_PER_REVOLUTION / (SQUARE_MM * GEAR_RATIO);

    for (int i = 0; i < 4; i++) {
        // Motor1 (X-axis)
        gpio_set(MOTOR1_IN1); gpio_set(MOTOR1_IN2); gpio_clear(MOTOR1_IN3); gpio_clear(MOTOR1_IN4);
