        gpio_set(MOTOR1_IN1); gpio_clear(MOTOR1_IN2); gpio_set(MOTOR1_IN3); gpio_clear(MOTOR1_IN4);
        usleep(STEP_DELAY);

        gpio_clear(MOTOR1_IN1); gpio_set(MOTOR1_IN2); gpio_set(MOTOR1_IN3); gpio_clear(MOTOR1_IN4);
        usleep(STEP_DELAY);

        gpio_clear(MOTOR1_IN1); gpio_clear(MOTOR1_IN2); gpio_clear(MOTOR1_IN3); gpio_set(MOTOR1_IN4);
        usleep(STEP_DELAY);

        // Motor2 (Y-axis)
        gpio_set(MOTOR2_IN1); gpio_set(MOTOR2_IN2); gpio_clear(MOTOR2_IN3); gpio_clear(MOTOR2_IN4);
        usleep(STEP_DELAY);

        gpio_set(MOTOR2_IN1); gpio_clear(MOTOR2_IN2); gpio_set(MOTOR2_IN3); gpio_clear(MOTOR2_IN4);
        usleep(STEP_DELAY);

        gpio_clear(MOTOR2_IN1); gpio_set(MOTOR2_IN2); gpio_set(MOTOR2_IN3); gpio_clear(MOTOR2_IN4);
        usleep(STEP_DELAY);

        gpio_clear(MOTOR2_IN1), gpio_clear(MOTOR2_IN2), gpio_clear(MOTOR2_IN3), gpio_set(MOTOR2_IN4);
        usleep(STEP_DELAY);
    }

    gpio_free();
    return EXIT_SUCCESS;
}

