#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <lis3dh.h>

#define I2C_ADDR_DEFAULT 0x18
#define THRESHOLD_DEFAULT 2.0
#define SAMPLE_INTERVAL_MS 100
#define RESOLUTION_DEFAULT 12
#define ODR_DEFAULT 100

int i2c_fd = -1;
struct lis3dh *lis3dh = NULL;
int threshold = THRESHOLD_DEFAULT;

void sigint_handler(int signum) {
    if (lis3dh) {
        lis3dh_close(lis3dh);
    }
    gpiod_unprepare();
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int addr = I2C_ADDR_DEFAULT;
    if (argc > 1 && strcmp(argv[1], "-a") == 0) {
        addr = strtol(argv[2], NULL, 16);
    }

    if (addr < 0x10 || addr > 0x77) {
        fprintf(stderr, "Invalid I2C address: %x\n", addr);
        return 1;
    }

    i2c_fd = gpiod_i2c_open(addr, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_unprepare();
        return 1;
    }

    lis3dh = lis3dh_open(i2c_fd);
    if (!lis3dh) {
        fprintf(stderr, "Failed to initialize LIS3DH sensor\n");
        gpiod_close(i2c_fd);
        gpiod_unprepare();
        return 1;
    }

    if (argc > 1 && strcmp(argv[1], "-t") == 0) {
        threshold = atof(argv[2]);
        if (threshold <= 0) {
            fprintf(stderr, "Threshold must be greater than 0\n");
            lis3dh_close(lis3dh);
            gpiod_close(i2c_fd);
            gpiod_unprepare();
            return 1;
        }
    }

    while (1) {
        int16_t ax, ay, az;
        if (lis3dh_read_raw(&ax, &ay, &az) != 0) {
            ax = ay = az = 0;
        }

        if (sqrt(ax * ax + ay * ay + az * az) > threshold) {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            FILE *log_file = fopen("/var/log/high_acceleration.log", "a");
            if (log_file) {
                fprintf(log_file, "%s: %f, %f, %f\n", timestamp, ax, ay, az);
                fclose(log_file);
            } else {
                fprintf(stderr, "Failed to open log file\n");
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    lis3dh_close(lis3dh);
    gpiod_close(i2c_fd);
    gpiod_unprepare();
    return 0;
}

