#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>
#include <i2c/i2c.h>

#define SI7210_ADDR 0x1D
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define POLL_ATTEMPTS 50
#define SAMPLE_INTERVAL_MS 100

struct timespec poll_ts;
struct timespec now;

static int i2c_fd;
static GPIODev *relay_chip;
static GpioLine *relay_line;

void sigint_handler(int signum) {
    gpiod_unreg_device(relay_chip);
    i2c_release();
    exit(0);
}

void setup_gpio() {
    relay_chip = gpiod_in_export(NULL, "relay_chip");
    if (!relay_chip) {
        fprintf(stderr, "Failed to export GPIO\n");
        exit(1);
    }

    relay_line = gpiod_chip_get_line(relay_chip, "P1.7");
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        exit(1);
    }

    gpiod_line_export(relay_line);
    gpiod_set_value(relay_line, 0);
}

void setup_i2c() {
    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }

    if (i2c_xfer(i2c_fd, SI7210_ADDR, NULL, 0, NULL, 0) != 0) {
        fprintf(stderr, "Failed to perform I2C transfer\n");
        exit(1);
    }
}

int read_magnetic_field() {
    int ret;
    uint8_t data[2];

    clock_gettime(CLOCK_MONOTONIC, &poll_ts);
    while ((ret = i2c_xfer(i2c_fd, SI7210_ADDR, data, 2, NULL, 0)) != 2) {
        if (ret < 0) {
            fprintf(stderr, "I2C transfer failed\n");
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - poll_ts.tv_sec > 1 / (SAMPLE_INTERVAL_MS / 1000.0)) {
            fprintf(stderr, "Timeout waiting for I2C response\n");
            return -1;
        }
    }

    // Assuming data[0] holds the high byte and data[1] holds the low byte of the magnetic field value
    int16_t field_value = (data[0] << 8) | data[1];
    float field_mt = field_value * 0.125; // Conversion factor from Si7210 datasheet

    clock_gettime(CLOCK_MONOTONIC, &now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));

    FILE *log_file = fopen("magnetic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(log_file, "%s: %f mT\n", timestamp, field_mt);
    fclose(log_file);

    if (field_mt > THRESHOLD_MT) {
        gpiod_set_value(relay_line, 1);
        fprintf(log_file, "%s: Relay activated\n", timestamp);
    } else {
        gpiod_set_value(relay_line, 0);
        fprintf(log_file, "%s: Relay deactivated\n", timestamp);
    }

    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    setup_gpio();
    setup_i2c();

    while (1) {
        read_magnetic_field();
        clock_nanosleep(CLOCK_MONOTONIC, 0, .tv_sec = SAMPLE_INTERVAL_MS / 1000, .tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000);
    }

    return 0;
}

