#include <stdio.h>
#include <stdbool.h>
#include <errno.h>
#include <signal.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 256
#define LOG_FILE "relay_log.txt"

int socket_fd;
struct sockaddr_in server_addr;
int log_fd;

void sigint_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    close(socket_fd);
    close(log_fd);
    gpiod_uninit();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, shutting down...\n");
    close(socket_fd);
    close(log_fd);
    gpiod_uninit();
    exit(0);
}

void init_gpio() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    ret = gpiod_chip_open(&chip, "GPIO1_CM");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO1_CM chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO%d\n", RELAY_GPIO);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_export(line, "Relay");
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO%d: %s\n", RELAY_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_direction(line, GPIO_OUTPUT);
    gpiod_line_set_value(line, 0);

    gpiod_chip_close(chip);
}

void setup_socket() {
    int opt = 1;
    struct sockaddr_in serv_addr;

    if ((socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, '0', sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (setsockopt(socket_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(socket_fd, 5) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
}

void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    char command[10];
    time_t now;

    now = time(NULL);
    struct tm *ltm = localtime(&now);
    strftime(command, sizeof(command), "%Y-%m-%d %H:%M:%S", ltm);

    while (true) {
        int valread = recv(client_socket, buffer, BUFFER_SIZE, 0);
        if (valread <= 0) {
            break;
        }

        buffer[valread] = '\0';
        if (strcasestr(buffer, "ON")) {
            gpiod_line_set_value(line, 1);
            fprintf(stderr, "%s - Relay turned ON\n", command);
        } else if (strcasestr(buffer, "OFF")) {
            gpiod_line_set_value(line, 0);
            fprintf(stderr, "%s - Relay turned OFF\n", command);
        } else {
            fprintf(stderr, "%s - Invalid command\n", command);
        }

        write(log_fd, buffer, strlen(buffer));
    }

    close(client_socket);
}

int main() {
    int client_socket;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    init_gpio();
    setup_socket();

    while (true) {
        if ((client_socket = accept(socket_fd, NULL, NULL)) < 0) {
            perror("accept");
            continue;
        }

        handle_client(client_socket);
    }

    close(socket_fd);
    close(log_fd);
    gpiod_uninit();

    return 0;
}

