    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(MOTOR_ENA_GPIO);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open motor ENA GPIO chip");
        return;
    }

    line = gpiod_chip_get_line(chip, "GPIO" STRINGIFY(MOTOR_ENA_GPIO));
    if (!line) {
        syslog(LOG_ERR, "Failed to get motor ENA line");
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_write(line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set motor ENA low");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    chip = gpiod_chip_open(MOTOR_IN1_GPIO);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open motor IN1 GPIO chip");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    line = gpiod_chip_get_line(chip, "GPIO" STRINGIFY(MOTOR_IN1_GPIO));
    if (!line) {
        syslog(LOG_ERR, "Failed to get motor IN1 line");
        gpiod_chip_close(chip);
        gpiod_line_free(line);
        return;
    }

    ret = gpiod_line_write(line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 low");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    chip = gpiod_chip_open(MOTOR_IN2_GPIO);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open motor IN2 GPIO chip");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    line = gpiod_chip_get_line(chip, "GPIO" STRINGIFY(MOTOR_IN2_GPIO));
    if (!line) {
        syslog(LOG_ERR, "Failed to get motor IN2 line");
        gpiod_chip_close(chip);
        gpiod_line_free(line);
        return;
    }

    ret = gpiod_line_write(line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 low");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return;
    }

    motor_running = false;
    syslog(LOG_INFO, "Motor stopped");
}

int main(void) {
    struct sigaction sa;
    int ret;

    openlog("rain_window", LOG_PID, LOG_USER);

    sa.sa_handler = sigint_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        return 1;
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        return 1;
    }

    if (gpiod_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize gpiod");
        return 1;
    }

    ret = gpiod_chip_add_override_simple(MOTOR_ENA_GPIO, "Motor ENA", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to add motor ENA override");
        goto cleanup;
    }

    ret = gpiod_chip_add_override_simple(MOTOR_IN1_GPIO, "Motor IN1", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to add motor IN1 override");
        goto cleanup;
    }

    ret = gpiod_chip_add_override_simple(MOTOR_IN2_GPIO, "Motor IN2", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to add motor IN2 override");
        goto cleanup;
    }

    ret = gpiod_chip_add_override_simple(RAIN_SENSOR_GPIO, "Rain Sensor", GPIO_PULL_UP);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to add rain sensor override");
        goto cleanup;
    }

    while (1) {
        ret = rain_sensor_poll();
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to poll rain sensor");
            break;
        }

        if (sensor_state && !last_sensor_state) {
            consecutive_dry_polls = 0;

            start_motor();
            usleep(MOTOR_ON_TIME_S * 1000000);
            stop_motor();
        }

        last_sensor_state = sensor_state;
        consecutive_dry_polls += sensor_state;

        if (consecutive_dry_polls >= CONSECUTIVE_DRY_POLLS_FOR_RESET) {
            consecutive_dry_polls = 0;
        }

        usleep(RAIN_SENSOR_POLLING_INTERVAL_MS * 1000);
    }

cleanup:
    if (gpiod_chip_remove_overrides(MOTOR_ENA_GPIO) < 0) {
        syslog(LOG_ERR, "Failed to remove motor ENA overrides");
    }

    if (gpiod_chip_remove_overrides(MOTOR_IN1_GPIO) < 0) {
        syslog(LOG_ERR, "Failed to remove motor IN1 overrides");
    }

    if (gpiod_chip_remove_overrides(MOTOR_IN2_GPIO) < 0) {
        syslog(LOG_ERR, "Failed to remove motor IN2 overrides");
    }

    if (gpiod_chip_remove_overrides(RAIN_SENSOR_GPIO) < 0) {
        syslog(LOG_ERR, "Failed to remove rain sensor overrides");
    }

    gpiod_free();
    syslog(LOG_INFO, "Exiting...");
    closelog();
    return 0;
}
