#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define PIR_GPIO 4
#define LED_GPIO 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL 100000 // 100 ms in microseconds

struct timespec poll_timeout;

void sigint_handler(int signum) {
    gpio_stop_output(LED_GPIO);
    fclose(log_file);
    exit(0);
}

int main() {
    gpio_init();
    if (gpio_fsel(PIR_GPIO) == -1 || gpio_dir(PIR_GPIO) == -1 || gpio_export(PIR_GPIO) == -1 ||
        gpio_fsel(LED_GPIO) == -1 || gpio_dir(LED_GPIO) == -1 || gpio_export(LED_GPIO) == -1) {
        fprintf(stderr, "Failed to initialize GPIOs\n");
        return 1;
    }

    GPIO_PIN pir_pin = gpio_get_pin(PIR_GPIO);
    GPIO_PIN led_pin = gpio_get_pin(LED_GPIO);

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (true) {
        clock_gettime(CLOCK_MONOTONIC, &poll_timeout);
        poll_timeout.tv_sec += POLL_INTERVAL / 1000000;

        int pir_state = gpio_input(pir_pin);
        if (pir_state == 1 && !gpio_get_level(LED_GPIO)) {
            gpio_set_level(LED_GPIO, 1);
            fprintf(log_file, "Activation: %s\n", ctime(&poll_timeout));

            // Wait for 60 seconds
            struct timespec req_timeout;
            req_timeout.tv_sec = 60;
            req_timeout.tv_nsec = 0;

            while (clock_nanosleep(CLOCK_MONOTONIC, 0, &req_timeout, NULL) && gpio_get_level(LED_GPIO)) {
                // Wait for 60 seconds or until PIR sensor detects another motion
            }

            if (gpio_get_level(LED_GPIO)) {
                fprintf(log_file, "Deactivation: %s, Duration: %ld seconds\n",
                        ctime(&time(NULL)), time(NULL) - (long)poll_timeout.tv_sec);
            } else {
                fprintf(log_file, "Deactivation: %s, Duration: %ld seconds (failed to turn off)\n",
                        ctime(&time(NULL)), time(NULL) - (long)poll_timeout.tv_sec);
            }
        }

        if (gpio_input(pir_pin) == 0) {
            gpio_set_level(LED_GPIO, 0);
        }

        // Sleep for the remaining time to reach the next polling interval
        nanosleep(&poll_timeout, NULL);
    }

    gpio_unexport(PIR_GPIO);
    gpio_unexport(LED_GPIO);
    gpio_cleanup();

    fclose(log_file);
    return 0;
}

