#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <i2c.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_TIME 200000 // 200 ms in µs
#define ELECTRODE_0 0

struct gpiod_chip_params chip_params = {
    .gpio_chip_label = "MPR121",
    .gpios = {
        { .index = RELAY_GPIO, .flags = GPIO_OUTPUT_ACTIVE_HIGH },
    },
};

struct gpiod_chip *chip;
int fd;

void relay_state_handler(struct gpiod_chip *chip, struct gpiod_trigger *trigger, uint dummy) {
    bool state = gpiod_get_value(chip, trigger->line);
    if (state) {
        printf("Relay is ON\n");
    } else {
        printf("Relay is OFF\n");
    }
}

void init_relay() {
    int ret;
    ret = gpiod_chip_init(&chip_params, &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(ret);
    }

    ret = gpiod_add_override(chip, RELAY_GPIO, gpiod_override_options_t{ .direction = GPIO_OUTPUT }, relay_state_handler);
    if (ret < 0) {
        fprintf(stderr, "Failed to add GPIO override\n");
        gpiod_chip_free(chip);
        exit(ret);
    }
}

void cleanup_relay() {
    gpiod_remove_override(chip, RELAY_GPIO);
    gpiod_chip_free(chip);
}

void i2c_init() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
}

void i2c_cleanup() {
    close(fd);
}

void mpr121_init(void) {
    uint8_t data[6] = {0x06, 0x00, 0x00, 0x00, 0x00, 0x00};

    if (i2c_xfer(fd, MPR121_ADDR | 0x00, NULL, 1) != 1) {
        fprintf(stderr, "Failed to perform soft reset\n");
        i2c_cleanup();
        exit(1);
    }

    if (i2c_xfer(fd, MPR121_ADDR | 0x01, data, 6) != 6) {
        fprintf(stderr, "Failed to configure MPR121\n");
        i2c_cleanup();
        exit(1);
    }
}

void mpr121_handle_touch(uint8_t *touch_data) {
    uint8_t electrodes[12];
    memset(electrodes, 0, 12);

    if (i2c_xfer(fd, MPR121_ADDR | 0x02, NULL, 0) != 0) {
        fprintf(stderr, "Failed to read touch data\n");
        return;
    }

    memcpy(electrodes, touch_data, 12);

    if (electrodes[ELECTRODE_0]) {
        if (!touch_debounce[ELECTRODE_0]) {
            touch_debounce[ELECTRODE_0] = time(NULL) + DEBOUNCE_TIME / 1000000;
            gpiod_trigger_enable(chip, RELAY_GPIO, GPIO_EVENT_RISING);
        }
    } else {
        touch_debounce[ELECTRODE_0] = 0;
    }
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100 ms

    init_relay();
    i2c_init();
    mpr121_init();

    while (true) {
        uint8_t touch_data[12];
        if (i2c_xfer(fd, MPR121_ADDR | 0x03, touch_data, 12) != 12) {
            fprintf(stderr, "Failed to read touch data\n");
            break;
        }

        mpr121_handle_touch(touch_data);

        nanosleep(&ts, NULL);
    }

    cleanup_relay();
    i2c_cleanup();
    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    cleanup_relay();
    i2c_cleanup();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up...\n");
    cleanup_relay();
    i2c_cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_relay();
    i2c_init();
    mpr121_init();

    while (true) {
        uint8_t touch_data[12];
        if (i2c_xfer(fd, MPR121_ADDR | 0x03, touch_data, 12) != 12) {
            fprintf(stderr, "Failed to read touch data\n");
            break;
        }

        mpr121_handle_touch(touch_data);

        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 ms
        nanosleep(&ts, NULL);
    }

    cleanup_relay();
    i2c_cleanup();
    return 0;
}

