#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <stdarg.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <net/if.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQ 50
#define PULSE_WIDTH 1500 // 1.5ms

int socket_fd = -1;
int servo_pin;
int pir_pin;

void log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    vsyslog(LOG_USER | LOG_INFO, "%s: %s", timestamp, format);
    FILE *log_file = fopen("security.log", "a");
    if (log_file != NULL) {
        vfprintf(log_file, format, args);
        fclose(log_file);
    }
    va_end(args);
}

void init_gpio() {
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        log_event("Failed to initialize libgpiod, exiting.");
        exit(EXIT_FAILURE);
    }

    servo_pin = gpiod_request_available(17);
    if (servo_pin < 0) {
        log_event("Failed to get GPIO%d, libgpiod error: %s", 17, gpiod_get_error());
        gpiod_exit();
        exit(EXIT_FAILURE);
    }

    pir_pin = gpiod_request_available(4);
    if (pir_pin < 0) {
        log_event("Failed to get GPIO%d, libgpiod error: %s", 4, gpiod_get_error());
        gpiod_exit();
        exit(EXIT_FAILURE);
    }

    gpiod_export(servo_pin, "Servo");
    gpiod_export(pir_pin, "PIR");

    gpio_set_mode(servo_pin, PI_OUTPUT);
    gpio_set_value(servo_pin, 0);

    gpio_set_mode(pir_pin, PI_INPUT);
    gpio_set_pull_up_down(pir_pin, PI_PUD_OFF);

    log_event("GPIO initialization successful.");
}

void setup_tcp_server() {
    struct sockaddr_in addr;
    int sockopt;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_event("Failed to create socket, syscall error: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (setsockopt(socket_fd, SOL_SOCKET, SO_REUSEADDR, &sockopt, sizeof(sockopt)) < 0) {
        log_event("Failed to set SO_REUSEADDR, syscall error: %s", strerror(errno));
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    if (bind(socket_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_event("Failed to bind socket, syscall error: %s", strerror(errno));
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(socket_fd, 5) < 0) {
        log_event("Failed to listen on socket, syscall error: %s", strerror(errno));
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    log_event("TCP server setup successful.");
}

void handle_servo_command(int client_fd, int servo_angle) {
    if (servo_angle < 0 || servo_angle > 180) {
        send(client_fd, "Invalid angle, must be between 0 and 180.\n", 37, 0);
        return;
    }

    int pulse_width_us = PULSE_WIDTH + (servo_angle * 10);
    gpio_set_servo_pulsewidth(servo_pin, pulse_width_us);
}

void handle_pir_command(int client_fd, int *pir_state) {
    *pir_state = gpio_ethersense_read(pir_pin);
    send(client_fd, "PIR:", 4, 0);
    if (*pir_state) {
        send(client_fd, "1\n", 2, 0);
    } else {
        send(client_fd, "0\n", 2, 0);
    }
}

void cleanup() {
    gpio_terminate();
    close(socket_fd);
    gpiod_unexport(servo_pin);
    gpiod_unexport(pir_pin);
    gpiod_exit();
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    init_gpio();
    setup_tcp_server();

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            log_event("Failed to accept connection, syscall error: %s", strerror(errno));
            continue;
        }

        char buffer[1024];
        int rc;

        while ((rc = read(client_fd, buffer, sizeof(buffer))) > 0) {
            buffer[rc] = '\0';

            if (strncmp(buffer, "servo ", 6) == 0) {
                int servo_angle = atoi(buffer + 6);
                handle_servo_command(client_fd, servo_angle);
            } else if (strncmp(buffer, "pir", 3) == 0) {
                int pir_state;
                handle_pir_command(client_fd, &pir_state);
            } else {
                send(client_fd, "Unknown command, try 'servo <angle>' or 'pir'.\n", 47, 0);
            }
        }

        close(client_fd);
    }

    cleanup();
    return 0;
}

