#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <gpio.h>

#define BH1750_ADDR 0x23
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define RETRY_DELAY 120000 // 120 ms in microseconds
#define SAMPLE_INTERVAL 2000000 // 2 seconds in microseconds
#define MIN_LUX 150

gpio_context gpio;
int i2c_fd;
FILE *log_file;

void signal_handler(int signum) {
    gpio_close(&gpio);
    fclose(log_file);
    exit(signum);
}

int i2c_read_lux(int fd, uint8_t addr, uint16_t *lux) {
    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.fds = &fd;
    rdwr.len = 2;
    rdwr.buf = (unsigned char *)lux;
    rdwr.count = 1;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpio = gpio_init();
    if (!gpio) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpio_close(&gpio);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        close(i2c_fd);
        gpio_close(&gpio);
        return 1;
    }

    while (1) {
        uint16_t lux;
        if (i2c_read_lux(i2c_fd, BH1750_ADDR, &lux) < 0) {
            fprintf(stderr, "Sensor absent or bus error, retrying...\n");
            continue;
        }

        if (lux < MIN_LUX) {
            gpio_set_value(gpio, RELAY_PIN, 1);
        } else {
            gpio_set_value(gpio, RELAY_PIN, 0);
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld: %u lux\n", now, lux);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

    gpio_close(&gpio);
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

