#define READ_ATTEMPTS 3
#define DEFAULT_THRESHOLD 1000
#define CHANNEL_A_GAIN 128

uint32_t read_hx711(uint32_t *do_out, uint32_t *sc_out, uint32_t *error) {
    uint32_t value = 0;
    uint32_t attempt = 0;
    uint32_t timeout = POLL_INTERVAL * 1000;

    while (attempt < READ_ATTEMPTS) {
        if (*do_out == 0) {
            *sc_out = 0;
            for (uint32_t i = 0; i < 24; i++) {
                (*sc_out) <<= 1;
                *do_out = gpiod_get_value(*do_out);
                if (*do_out == 0) {
                    (*sc_out) |= 1;
                } else {
                    break;
                }
            }

            if (*do_out == 0) {
                (*sc_out) <<= 1;
                *do_out = gpiod_get_value(*do_out);
                if (*do_out == 0) {
                    *error = 1;
                    return 0;
                }
            }

            value = (*sc_out << 8) | gpiod_get_value(*do_out);
            if (clock_gettime(CLOCK_MONOTONIC, &timeout) - start_time > timeout) {
                *error = 2;
                return 0;
            }
            attempt++;
        } else {
            usleep(100000);
        }
    }

    *error = 3;
    return 0;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip chip;
    struct gpiod_line line_do;
    struct gpiod_line line_sc;
    struct gpiod_context *ctx;
    uint32_t do_out = 23, sc_out = 24, error = 0;
    uint32_t tare_values[TARE_READS] = {0};
    uint32_t tare_sum = 0;
    uint32_t threshold = DEFAULT_THRESHOLD;
    uint32_t scale_factor = 1;
    uint32_t duration = 200;
    bool running = true;

    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "--threshold") == 0) {
                threshold = atoi(argv[i + 1]);
                i++;
            } else if (strcmp(argv[i], "--scale") == 0) {
                scale_factor = atoi(argv[i + 1]);
                i++;
            } else if (strcmp(argv[i], "--duration") == 0) {
                duration = atoi(argv[i + 1]);
                i++;
            }
        }
    }

    gpiod_chip_register_new(&chip, "HX711");
    gpiod_line_register_new(&line_do, &chip, "DOUT", GPIO_LINE_INPUT, 23);
    gpiod_line_register_new(&line_sc, &chip, "SCK", GPIO_LINE_OUTPUT, 24);

    ctx = gpiod_new();
    gpiod_chip_set_owner(ctx, &chip, GP_LINE_OPEN_DRAIN | GP_LINE_NO_PULL);
    gpiod_line_export(ctx, &line_do, "DOUT");
    gpiod_line_export(ctx, &line_sc, "SCK");

    gpiod_line_set_value(&line_sc, 1);
    usleep(100);
    gpiod_line_set_value(&line_sc, 0);

    for (uint32_t i = 0; i < TARE_READS; i++) {
        tare_values[i] = read_hx711(&do_out, &sc_out, &error);
        if (error) {
            syslog(LOG_ERR, "Error reading HX711: %d", error);
            running = false;
            break;
        }
        tare_sum += tare_values[i];
    }

    if (!running) {
        gpiod_line_unset(ctx, &line_do);
        gpiod_line_unset(ctx, &line_sc);
        gpiod_chip_unregister(&chip);
        gpiod_free(ctx);
        return 1;
    }

    uint32_t tare_avg = tare_sum / TARE_READS;
    syslog(LOG_INFO, "Tare weight: %u", tare_avg);

    while (running) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint32_t start_time = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        uint32_t read_values[5] = {0};
        uint32_t read_sum = 0;

        for (uint32_t i = 0; i < 5; i++) {
            read_values[i] = read_hx711(&do_out, &sc_out, &error);
            if (error) {
                syslog(LOG_ERR, "Error reading HX711: %d", error);
                running = false;
                break;
            }
            read_sum += read_values[i];
        }

        if (!running) {
            break;
        }

        uint32_t weight = (read_sum / 5) - tare_avg;
        weight *= scale_factor;

        syslog(LOG_INFO, "Weight: %u", weight);

        if (weight > threshold) {
            gpiod_line_set_value(ctx, &line_do, 1);
            usleep(duration * 1000);
            gpiod_line_set_value(ctx, &line_do, 0);
        }

        usleep(POLL_INTERVAL * 1000 - (clock_gettime(CLOCK_MONOTONIC, &ts) - start_time));
    }

    gpiod_line_unset(ctx, &line_do);
    gpiod_line_unset(ctx, &line_sc);
    gpiod_chip_unregister(&chip);
    gpiod_free(ctx);

    return 0;
}

