#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <mqtt.h>

#define TOPIC "home/lights/control"
#define QOS 0
#define KEEP_ALIVE 60
#define BROKER "localhost"
#define BROKER_PORT 1883
#define CLIENT_ID "relay_controller_1"
#define GPIO_PIN 17

static gpiod_chip *chip;
static gpiod_line *line;
static mqtt_client *client;

void sigint_handler(int signum) {
    syslog(LOG_INFO, "Received SIGINT, cleaning up and exiting...");
    cleanup();
    exit(0);
}

void sigterm_handler(int signum) {
    syslog(LOG_INFO, "Received SIGTERM, cleaning up and exiting...");
    cleanup();
    exit(0);
}

void cleanup() {
    if (client) {
        mqtt_client_disconnect(client);
        mqtt_client_destroy(client);
        client = NULL;
    }

    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }

    if (chip) {
        gpiod_chip_unref(chip);
        chip = NULL;
    }

    closelog();
}

int init_gpio() {
    int ret;

    ret = gpiod_chip_open(&chip, "gpiochip0");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_strerror(ret));
        return ret;
    }

    ret = gpiod_chip_get_line(chip, "GPIO%d", GPIO_PIN);
    if (ret < 0) {
        gpiod_chip_close(chip);
        return ret;
    }

    line = gpiod_line_alloc(ret);
    if (!line) {
        gpiod_chip_close(chip);
        return -ENOMEM;
    }

    ret = gpiod_line_set_direction(line, GPIO_OUTPUT);
    if (ret < 0) {
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return ret;
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return ret;
    }

    return 0;
}

int init_mqtt() {
    int ret;

    client = mqtt_client_new(MQTT_CLIENT_VERSION_3_1_1);
    if (!client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return -ENOMEM;
    }

    ret = mqtt_client_connect(client, BROKER, BROKER_PORT, CLIENT_ID);
    if (ret < 0) {
        mqtt_client_destroy(client);
        client = NULL;
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mqtt_strerror(ret));
        return ret;
    }

    mqtt_client_set_keepalive(client, KEEP_ALIVE);
    mqtt_client_set_cleansession(client, 1);
    mqtt_client_set_qos(client, QOS);

    ret = mqtt_client_subscribe(client, TOPIC, 0);
    if (ret < 0) {
        mqtt_client_disconnect(client);
        mqtt_client_destroy(client);
        client = NULL;
        syslog(LOG_ERR, "Failed to subscribe to topic %s: %s", TOPIC, mqtt_strerror(ret));
        return ret;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    int ret;

    sa.sa_handler = sigint_handler;
    sigeset(&sa.sa_mask, SIGINT);
    sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGINT handler");
        return 1;
    }

    sa.sa_handler = sigterm_handler;
    sigeset(&sa.sa_mask, SIGTERM);
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler");
        return 1;
    }

    openlog("relay_controller", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting relay_controller...");

    ret = init_gpio();
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        cleanup();
        return ret;
    }

    ret = init_mqtt();
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize MQTT");
        cleanup_gpio();
        cleanup();
        return ret;
    }

    mqtt_client_loop(client, 5000);

    cleanup();
    closelog();
    return 0;
}

