#define SERVO_PINS {7, 8, 9, 10, 11}
#define SERVO_DURATION 3000000 // 3 seconds in microseconds
#define PWM_FREQ 50 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQ) // 20 ms in microseconds
#define PWM_MARK (PWM_PERIOD / 2) // 10 ms mark
#define PWM_RANGE (2500 - 500) // 2000 us

int main() {
    struct gpiod_chipchip *chi;
    struct gpiod_chip_line *lines[5];
    int i;

    // Initialize the library
    if (gpiod_new() < 0) {
        fprintf(stderr, "Failed to initialize gpiod library\n");
        return 1;
    }

    // Find the GPIO chip
    chi = gpiod_chip_find("gpio");
    if (!chi) {
        fprintf(stderr, "Failed to find GPIO chip\n");
        gpiod_free();
        return 1;
    }

    // Configure servo pins as output
    for (i = 0; i < 5; i++) {
        lines[i] = gpiod_chip_get_line(chi, SERVO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", SERVO_PINS[i]);
            gpiod_free();
            return 1;
        }

        if (gpiod_line_request_cooked(lines[i], "pwm") < 0) {
            fprintf(stderr, "Failed to request PWM line for GPIO %d\n", SERVO_PINS[i]);
            gpiod_free();
            return 1;
        }
    }

    // PWM configuration
    uint64_t duty_cycle[5] = {1000, 1500, 2000, 500, 2500};
    for (i = 0; i < 5; i++) {
        uint32_t freq = PWM_FREQ;
        uint32_t period = PWM_PERIOD;
        uint32_t mark = PWM_MARK;

        // Set PWM parameters
        if (gpiod_line_cooked_set_drvdata(lines[i], (void *)(&freq)) < 0) {
