        // Calculate and set duty cycle
        uint32_t pulse_width = (uint32_t)((duty_cycle[i] - 500) * period / PWM_RANGE + mark);
        if (gpiod_line_cooked_prepare_value(lines[i], pulse_width) < 0) {
            fprintf(stderr, "Failed to set pulse width for GPIO %d\n", SERVO_PINS[i]);
            gpiod_free();
            return 1;
        }
    }

    // Wait for the specified duration
    for (i = 0; i < 5; i++) {
        if (usleep(SERVO_DURATION * 1000) < 0) {
            fprintf(stderr, "Failed to sleep for %d us\n", SERVO_DURATION);
            gpiod_free();
            return 1;
        }
    }

    // Stop PWM and release resources
