#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define PWM_FREQ 10000
#define TICKS_PER_REV 64
#define TARGET_RPM 50
#define STALL_TIMEOUT_S 2

typedef struct {
    uint32_t ticks;
    uint32_t last_tick_time;
} Encoder;

typedef struct {
    float kp;
    float ki;
    float kd;
    float error;
    float integral;
    float previous_error;
    uint32_t pwm_value;
} PID;

Encoder encoder_a = {0, 0};
Encoder encoder_b = {0, 0};
PID pid_a = {1.0, 0.0, 0.0, 0, 0, 0, 128};
PID pid_b = {1.0, 0.0, 0.0, 0, 0, 0, 128};

void encoder_callback(const struct gpiod_chip *chip, const struct gpiod_line *line, uint32_t flags, void *user_data) {
    Encoder *enc = (Encoder *)user_data;
    if (gpiod_line_get_value(line)) {
        enc->ticks++;
    }
}

void pwm_callback(const struct gpiod_chip *chip, const struct gpiod_line *line, uint32_t flags, void *user_data) {
    PID *pid = (PID *)user_data;
    gpiod_set_value(line, pid->pwm_value);
}

void pid_control(Encoder *enc, PID *pid) {
    uint32_t dt = (uint32_t)(time(NULL) - enc->last_tick_time);
    if (dt == 0) {
        return;
    }
    enc->last_tick_time = time(NULL);

    float rpm = (dt * TICKS_PER_REV * pid->kp * pid->error) / 60;
    pid->integral += pid->error;
    pid->pwm_value = pid->kp * pid->error + pid->ki * pid->integral + pid->kd * (pid->error - pid->previous_error) / dt;

    if (pid->pwm_value < 0) {
        pid->pwm_value = 0;
    } else if (pid->pwm_value > 255) {
        pid->pwm_value = 255;
    }

    pid->previous_error = pid->error;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip chip;
    struct gpiod_line_request qr_a_phase_a = GPIO_PIGO_LINE_REQUEST(4, GPIO_PIGO_DIR_OUT);
    struct gpiod_line_request qr_a_phase_b = GPIO_PIGO_LINE_REQUEST(5, GPIO_PIGO_DIR_OUT);
    struct gpiod_line_request qr_b_phase_a = GPIO_PIGO_LINE_REQUEST(6, GPIO_PIGO_DIR_OUT);
    struct gpiod_line_request qr_b_phase_b = GPIO_PIGO_LINE_REQUEST(12, GPIO_PIGO_DIR_OUT);
    struct gpiod_line_request qr_a_in1 = GPIO_PIGO_LINE_REQUEST(17, GPIO_PIGO_DIR_OUT, "Motor A IN1");
    struct gpiod_line_request qr_a_in2 = GPIO_PIGO_LINE_REQUEST(18, GPIO_PIGO_DIR_OUT, "Motor A IN2");
    struct gpiod_line_request qr_b_in3 = GPIO_PIGO_LINE_REQUEST(22, GPIO_PIGO_DIR_OUT, "Motor B IN3");
    struct gpiod_line_request qr_b_in4 = GPIO_PIGO_LINE_REQUEST(23, GPIO_PIGO_DIR_OUT, "Motor B IN4");
    struct gpiod_chip_request cqr;

    gpiod_chip_register_request(&chip, &cqr, "motor_control");
    gpiod_add_request_set(&chip, &qr_a_phase_a, &qr_a_phase_b, &qr_b_phase_a, &qr_b_phase_b, &qr_a_in1, &qr_a_in2, &qr_b_in3, &qr_b_in4);

    gpiod_line_request_add_request(&qr_a_phase_a, &qr_a_phase_b, &qr_b_phase_a, &qr_b_phase_b);
    gpiod_line_request_add_request(&qr_a_in1, &qr_a_in2);
    gpiod_line_request_add_request(&qr_b_in3, &qr_b_in4);

    gpiod_chip_start(&chip);

    gpiod_line_request_add_callback(&qr_a_phase_a, gpiod_line_request_get_line(&qr_a_phase_a), encoder_callback, &encoder_a);
    gpiod_line_request_add_callback(&qr_a_phase_b, gpiod_line_request_get_line(&qr_a_phase_b), encoder_callback, &encoder_a);
    gpiod_line_request_add_callback(&qr_b_phase_a, gpiod_line_request_get_line(&qr_b_phase_a), encoder_callback, &encoder_b);
    gpiod_line_request_add_callback(&qr_b_phase_b, gpiod_line_request_get_line(&qr_b_phase_b), encoder_callback, &encoder_b);

    gpiod_line_request_add_callback(&qr_a_in1, gpiod_line_request_get_line(&qr_a_in1), pwm_callback, &pid_a);
    gpiod_line_request_add_callback(&qr_a_in2, gpiod_line_request_get_line(&qr_a_in2), pwm_callback, &pid_a);
    gpiod_line_request_add_callback(&qr_b_in3, gpiod_line_request_get_line(&qr_b_in3), pwm_callback, &pid_b);
    gpiod_line_request_add_callback(&qr_b_in4, gpiod_line_request_get_line(&qr_b_in4), pwm_callback, &pid_b);

    while (1) {
        pid_control(&encoder_a, &pid_a);
        pid_control(&encoder_b, &pid_b);

        if (encoder_a.ticks == 0) {
            if (time(NULL) - encoder_a.last_tick_time > STALL_TIMEOUT_S) {
                printf("Warning: Motor A stalled\n");
            }
        } else {
            encoder_a.last_tick_time = time(NULL);
        }

        if (encoder_b.ticks == 0) {
            if (time(NULL) - encoder_b.last_tick_time > STALL_TIMEOUT_S) {
                printf("Warning: Motor B stalled\n");
            }
        } else {
            encoder_b.last_tick_time = time(NULL);
        }

        printf("Motor A RPM: %f, PWM: %d\n", (float)encoder_a.ticks * TICKS_PER_REV / 60, pid_a.pwm_value);
        printf("Motor B RPM: %f, PWM: %d\n", (float)encoder_b.ticks * TICKS_PER_REV / 60, pid_b.pwm_value);

        usleep(100000);
    }

    gpiod_chip_stop(&chip);
    gpiod_chip_free(&chip);

    return 0;
}

