#define LED_GPIO 17
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define MIN_WAIT_MS 180
#define LOG_FILE "chicken_coop_log.txt"

struct sensor_data {
    int lux;
    bool relay_state;
};

static FILE *log_file = NULL;
static gpiod_chip *chip = NULL;
static gpiod_line *led_line = NULL;
static struct sensor_data sensor_data;

void log_sensor_data(const char *format, ...) {
    va_list args;
    va_start(args, format);
    if (log_file != NULL) {
        vfprintf(log_file, format, args);
        fflush(log_file);
    }
    va_end(args);
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void init_gpio() {
    int ret;

    ret = gpiod_in_init();
    if (ret < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_open(gpiod_chip_register_get_by_name("gpiochip0"), "user");
    if (ret < 0) {
        perror("Failed to open gpiochip0");
        gpiod_in_exit();
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_get(gpiod_chip_open(gpiod_chip_register_get_by_name("gpiochip0"), "user"));
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", LED_GPIO);
        gpiod_chip_close(chip);
        gpiod_in_exit();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_export(led_line, "user") < 0) {
        perror("Failed to export GPIO");
        gpiod_chip_close(chip);
        gpiod_in_exit();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_buffers(led_line, 1) < 0) {
        perror("Failed to request buffers");
        gpiod_line_unexport(led_line);
        gpiod_chip_close(chip);
        gpiod_in_exit();
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpiod_line_release_buffers(led_line);
    gpiod_line_unexport(led_line);
    gpiod_chip_close(chip);
    gpiod_in_exit();
}

int main() {
    struct timespec poll_interval;
    clock_gettime(CLOCK_REALTIME, &poll_interval);
    poll_interval.tv_sec += POLL_INTERVAL_SEC;
    poll_interval.tv_nsec = 0;

    init_log_file();
    init_gpio();

    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    while (true) {
        clock_gettime(CLOCK_REALTIME, &poll_interval);

        sensor_data.lux = read_bh1750(BH1750_ADDR);
        if (sensor_data.lux < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            close_log_file();
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }

        log_sensor_data("%s: Lux = %d, Relay = %s\n",
                         get_current_time(), sensor_data.lux,
                         sensor_data.relay_state ? "ON" : "OFF");

        if (sensor_data.lux < LUX_THRESHOLD_DUSK && !sensor_data.relay_state) {
            control_relay(true);
        } else if (sensor_data.lux > LUX_THRESHOLD_DAWN && sensor_data.relay_state) {
            control_relay(false);
        }

        nanosleep(&poll_interval, NULL);
    }

    close_log_file();
    cleanup_gpio();
    return 0;
}

void control_relay(bool state) {
    if (state) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
    sensor_data.relay_state = state;
}

int read_bh1750(uint8_t addr) {
