    // Return lux value or -1 on error
}

char *get_current_time() {
    time_t now;
    struct tm *time_info;
    char buffer[20];

    time(&now);
    time_info = localtime(&now);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
    return buffer;
}

void cleanup_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received SIGINT or SIGTERM, cleaning up and exiting...\n");
    }
    close_log_file();
    cleanup_gpio();
    exit(EXIT_SUCCESS);
}

