#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define DEBOUNCE_DELAY_MS 50

gpio_init();
gpio_set_mode(4, GPIO_INPUT);
gpio_set_mode(17, GPIO_OUTPUT);
gpio_pullup(4);

int touch_state = 0;
bool touch_pressed = false;
bool touch_debounced = false;

void sigint_handler(int signum) {
    gpio_uninit();
    printf("Exiting on SIGINT\n");
    exit(0);
}

void toggle_relay() {
    if (touch_pressed && !touch_debounced) {
        gpio_write(17, !touch_state);
        touch_debounced = true;
        touch_state = !touch_state;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
        printf("%s, Relay: %s\n", timestamp, touch_state ? "ON" : "OFF");
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    while (true) {
        int touch_value = gpio_get(4);
        if (touch_value == 0) {
            if (!touch_pressed) {
                touch_pressed = true;
            }
        } else {
            if (touch_pressed) {
                toggle_relay();
                touch_pressed = false;
            }
        }

        if (touch_debounced) {
            touch_debounced = false;
        }

        usleep(10 * 1000);
    }

    gpio_uninit();
    return 0;
}

