        exit(EXIT_FAILURE);
    }

    relay_gpio = gpiod_line_get(relay_gpio, "relay");
    touch_gpio = gpiod_line_get(touch_gpio, "touch");

    while (1) {
        check_touch(debounce_interval);
        usleep(debounce_interval * 1000 / 2);
    }

    return 0;
