#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define DEFAULT_ANGLE 90
#define ANGLE_STEP 10
#define PWM_FREQ 50
#define PWM_PERIOD (1000000 / PWM_FREQ)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

struct termios original_termios;

void handle_sigint(int sig) {
    gpiod_unregister_callback(servo_cb);
    termios_restore(original_termios);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_callback servo_cb;
    int fd;
    long pulse_width;
    int angle = DEFAULT_ANGLE;

    if (termios_get_attributes(STDIN_FILENO, &original_termios) != 0) {
        fprintf(stderr, "Failed to save terminal attributes\n");
        return EXIT_FAILURE;
    }

    fd = termios_open(STDIN_FILENO, O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Failed to open stdin\n");
        return EXIT_FAILURE;
    }
    termios_store(original_termios);

    if (gpiod_chip_open(&chip, "gpiochip0") < 0) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO%d\n", SERVO_PIN);
        return EXIT_FAILURE;
    }

    if (gpiod_line_export(line, "servo_pwm") < 0) {
        fprintf(stderr, "Failed to export GPIO%d\n", SERVO_PIN);
        return EXIT_FAILURE;
    }

    gpiod_line_set_direction(line, GPIO_OUTPUT);

    memset(&servo_cb, 0, sizeof(servo_cb));
    servo_cb.trigger_type = GPIO_TRIGGER_FALLING_EDGE;
    servo_cb.user_data = NULL;
    servo_cb.handler = servo_pwm;

    if (gpiod_add_callback(line, &servo_cb) < 0) {
        fprintf(stderr, "Failed to add callback\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        char key;
        fd_set rfds;
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 10000;

        while (1) {
            FD_ZERO(&rfds);
            FD_SET(fd, &rfds);
            select(fd + 1, &rfds, NULL, NULL, &tv);

            if (FD_ISSET(fd, &rfds)) {
                if (read(fd, &key, 1) == 1) {
                    switch (key) {
                        case '+':
                            angle = (angle + ANGLE_STEP > 180) ? 180 : angle + ANGLE_STEP;
                            break;
                        case '-':
                            angle = (angle - ANGLE_STEP < 0) ? 0 : angle - ANGLE_STEP;
                            break;
                        case 'q':
                            goto exit_servo;
                        default:
                            break;
                    }
                    printf("Angle: %d\n", angle);
                    pulse_width = (angle * 10 + 1500) / 360 * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH;
                    if (gpiod_call(line, pulse_width) < 0) {
                        fprintf(stderr, "Failed to set pulse width\n");
                        return EXIT_FAILURE;
                    }
                    break;
                }
            }
        }
    }

exit_servo:
    gpiod_unregister_callback(servo_cb);
    termios_restore(original_termios);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(fd);
    return EXIT_SUCCESS;
}

static int servo_pwm(struct gpiod_line *line, long args) {
    long pulse_width;

    pulse_width = (args * 10 + 1500) / 360 * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH;
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Pulse width out of range\n");
        return -EINVAL;
    }

    if (gpiod_call(line, pulse_width) < 0) {
        fprintf(stderr, "Failed to set pulse width\n");
        return -EIO;
    }

    return 0;
}

