#include <stdbool.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define DEBOUNCE_WINDOW_US (2000)
#define GPIO_LINE (17)
#define RPM_INTERVAL_S (5)
#define LOG_FILE "motor_rpm.log"

struct context {
    gpiod_chip *chip;
    gpiod_line *line;
    struct timespec last_update;
    long pulse_count;
};

static void handle_sigint_sigterm(int signum, siginfo_t *info, void *context) {
    printf("\nReceived signal %d, cleaning up and exiting...\n", signum);
    gpiod_drain_delete(line->deqd);
    gpiod_line_drain_free(line);
    gpiod_chip_free(chip);
    fclose(log_file);
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct context ctx;
    FILE *log_file;
    int ret;

    ctx.pulse_count = 0;
    ctx.last_update = (struct timespec){-.MAXTIMEVAL, .tv_nsec = 0};

    ctx.chip = gpiod_chip_open(NULL);
    if (!ctx.chip) {
        fprintf(stderr, "Failed to open gpiod chip, %s\n", gpiod_strerror(errno));
        return 1;
    }

    ctx.line = gpiod_chip_get_line(ctx.chip, "GPIO17");
    if (!ctx.line) {
        fprintf(stderr, "Failed to get line GPIO17, %s\n", gpiod_strerror(errno));
        gpiod_chip_close(ctx.chip);
        return 1;
