#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define TOUCH_DURATION_SEC 10

volatile sig_atomic_t cleanup_flag = 0;

static int touch_state = 0;
static clock_t touch_start_time = 0;

static void cleanup_handler(int signum) {
    cleanup_flag = 1;
}

int main(void) {
    gpioInit();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TOUCH_PIN, PI_OUTPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    if (gpioSetOutput(TOLAY_PIN) < 0 || gpioSetOutput(RELAY_PIN) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO direction\n");
        gpioCleanup();
        return EXIT_FAILURE;
    }

    gpioSetOutput(TOLAY_PIN, 0); // Pull-up

    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    while (!cleanup_flag) {
        if (gpioGetInput(TOUCH_PIN) == 0) {
            touch_state = 1;
            touch_start_time = clock();
        }

        if (touch_state && (clock() - touch_start_time) > CLOCKS_PER_SEC * TOUCH_DURATION_SEC) {
            gpioSetOutput(RELAY_PIN, 0); // Turn off relay
            touch_state = 0;
            touch_start_time = 0;
        }

        gpioWaitInput(TOUCH_PIN, PI_LOW);
        gpioSetOutput(RELAY_PIN, !gpioGetOutput(RELAY_PIN));

        usleep(50000);
    }

    gpioSetOutput(RELAY_PIN, 0); // Ensure relay is OFF

    gpioCleanup();
    return EXIT_SUCCESS;
}

