    gpiod_line_unexport(ctx->pwm_line);
    gpiod_line_free_buffers(ctx->enable_line);
    gpiod_line_unexport(ctx->enable_line);
    gpiod_line_free_buffers(ctx->flow_line);
    gpiod_line_unexport(ctx->flow_line);
    gpiod_chip_free(ctx->chip);
    fclose(ctx->log_file);
}

static void flow_control_isr(struct gpiod_line *line, uint32_t flags) {
    struct flow_control_ctx *ctx = (struct flow_control_ctx *)line->user_data;
