#define RFID_SPI_CHANNEL 0
#define RFID_SPI_MODE 0
#define RFID_SPI_SPEED_HZ 100000
#define RFID_TAG_VALUE "1234567890"
#define BUTTON_GPIO 22
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

static FILE *log_file = NULL;
static int spi_fd = -1;

void sigint_handler(int signum) {
    gpioTerminate();
    spiClose(spi_fd);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioInit();
    spi_fd = spiOpen(RFID_SPI_CHANNEL, RFID_SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI interface: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    spiSetMode(spi_fd, RFID_SPI_SPEED_HZ);

    if ((log_file = fopen("/var/log/door_access.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpioSetMode(BUTTON_GPIO, GPIO_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, GPIO_PUD_UP);
    gpioSetWDone(BUTTON_GPIO);

    gpioSetMode(LOCK1_GPIO, GPIO_OUTPUT);
    gpioSetMode(LOCK2_GPIO, GPIO_OUTPUT);
    gpioWrite(LOCK1_GPIO, 1);
    gpioWrite(LOCK2_GPIO, 1);

    while (true) {
        char tag[11];
        int rd_len;

        if (spiCall(spi_fd, RFID_TAG_VALUE, strlen(RFID_TAG_VALUE), tag, sizeof(tag), &rd_len) < 0) {
            fprintf(stderr, "RFID read failure\n");
            log_access_attempt("RFID read failure");
            continue;
        }

        if (rd_len == 0) {
            fprintf(stderr, "No tag present\n");
            log_access_attempt("No tag present");
            continue;
        }

        if (memcmp(tag, RFID_TAG_VALUE, 10) != 0) {
            fprintf(stderr, "Invalid tag\n");
            log_access_attempt("Invalid tag");
            continue;
        }

        if (gpioRead(BUTTON_GPIO) == 0) {
            fprintf(stderr, "Button pressed\n");
            log_access_attempt("Button pressed");

            gpioWrite(LOCK1_GPIO, 0);
            gpioWrite(LOCK2_GPIO, 0);
            sleep(5);
            gpioWrite(LOCK1_GPIO, 1);
            gpioWrite(LOCK2_GPIO, 1);
        }
    }

    return EXIT_SUCCESS;
}

void log_access_attempt(const char *message) {
    time_t now;
    struct tm *time_struct;
    char timestamp[64];

    time(&now);
    time_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_struct);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

