    ret = mpr_init(&mpr_ctx, MPR121_ADDR);
    if (ret) {
        fprintf(stderr, "Failed to initialize MPR121 sensor\n");
        exit(EXIT_FAILURE);
    }
}

void configure_mpr121(void) {
    int ret;

    ret = mpr_soft_reset(&mpr_ctx);
    if (ret) {
        fprintf(stderr, "Failed to perform soft reset on MPR121\n");
        exit(EXIT_FAILURE);
    }

    ret = mpr_set_filter(&mpr_ctx, MPR_FILTER_ENABLE);
    if (ret) {
        fprintf(stderr, "Failed to enable filtering on MPR121\n");
        exit(EXIT_FAILURE);
    }

    ret = mpr_set_threshold(&mpr_ctx, MPR_THRESHOLD_RELEASE, 10);
    if (ret) {
        fprintf(stderr, "Failed to set release threshold on MPR121\n");
        exit(EXIT_FAILURE);
    }

    ret = mpr_set_threshold(&mpr_ctx, MPR_THRESHOLD_TOUCH, 10);
    if (ret) {
        fprintf(stderr, "Failed to set touch threshold on MPR121\n");
        exit(EXIT_FAILURE);
    }

    ret = mpr_set_runmode(&mpr_ctx, MPR_RUNMODE_REGULAR);
    if (ret) {
        fprintf(stderr, "Failed to enable run mode on MPR121\n");
        exit(EXIT_FAILURE);
    }
}

void open_relay_gpio(void) {
    int ret;

    ret = gpiod_init();
    if (ret) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(EXIT_FAILURE);
    }

    relay_chip = gpiod_chip_open(gpio_to_chip(RELAY_GPIO), "relay");
    if (!relay_chip) {
        fprintf(stderr, "Failed to open GPIO %d\n", RELAY_GPIO);
        gpiod_exit(ret);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(relay_chip, "relay_line");
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_chip_close(relay_chip);
        gpiod_exit(ret);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(relay_line, "user");
}

void open_i2c_bus(void) {
    int ret;

    ret = i2c_open(I2C_BUS);
    if (ret) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }
}

void close_i2c_bus(void) {
    i2c_close();
}

void open_log_file(void) {
    relay_log = fopen("relay_log.txt", "a");
    if (!relay_log) {
        fprintf(stderr, "Failed to open relay_log.txt\n");
        exit(EXIT_FAILURE);
    }
}

void close_log_file(void) {
    if (relay_log) {
        fclose(relay_log);
    }
}

void handle_sigint(int signum) {
    fprintf(stderr, "SIGINT received, shutting down...\n");
    close_log_file();
    gpiod_line_unset(relay_line);
    gpiod_exit(0);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    int ret;

    sa.sa_handler = handle_sigint;
    sigeset(&sa.sa_mask, signum(SIGINT));
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    mpr_init_error_check();
    configure_mpr121();
    open_relay_gpio();
    open_i2c_bus();
    open_log_file();

    while (1) {
        uint8_t touch_data[16];
        int touched_electrodes = 0;

        ret = mpr_read_touch_register(&mpr_ctx, MPR_REG_TOUCH_STATUS, touch_data, 12);
        if (ret) {
            fprintf(stderr, "Failed to read touch status register\n");
            break;
        }

        for (int i = 0; i < 12; i++) {
            if (touch_data[i] & MPR_REG_TOUCH_STATUS_TOUCH) {
                touched_electrodes++;
            }
        }

        if (touched_electrodes > 0) {
            gpiod_line_set_value(relay_line, 1);
            fprintf(relay_log, "%lu: Relay HIGH\n", time(NULL));
        } else {
            gpiod_line_set_value(relay_line, 0);
            fprintf(relay_log, "%lu: Relay LOW\n", time(NULL));
        }

        usleep(POLL_INTERVAL);
    }

    close_log_file();
    close_i2c_bus();
    gpiod_line_unset(relay_line);
    gpiod_exit(0);
    return 0;
}
```

This code initializes the MPR121 capacitive touch sensor, configures its filtering parameters, sets touch and release thresholds, and enables run mode. It also initializes the relay GPIO, opens the I2C bus, and opens a log file for recording relay state changes with timestamps. The program continuously polls the MPR121 sensor every 50 ms, updating the relay state based on the touched electrodes, and appends the relay state changes with timestamps to the relay_log.txt file. The program handles SIGINT (Ctrl+C) to shut down gracefully, releasing all resources and closing the I2C handle and log file.

