#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <gpio.h>
#include <gpiod.h>

#define MPR121_I2C_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define STABILIZATION_DELAY 100000 // 100 ms in microseconds
#define FILTER 10
#define CHARGE_TIME 10
#define ELECTRODE_CURRENT 1

struct gpio_dev *relay_gpio;

void sigint_handler(int signum) {
    gpio_put(relay_gpio, 0);
    exit(0);
}

void sigterm_handler(int signum) {
    gpio_put(relay_gpio, 0);
    exit(0);
}

int main() {
    gpio_init();
    relay_gpio = gpio_init_output(RELAY_GPIO);
    if (!relay_gpio) {
        fprintf(stderr, "Failed to initialize GPIO %d, error %d: %s\n", RELAY_GPIO, errno, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    int ret = gpiod_chip_open(&chip, I2C_BUS);
    if (ret) {
        fprintf(stderr, "Failed to open I2C bus %d, error %d: %s\n", I2C_BUS, errno, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *i2c_line;
    ret = gpiod_chip_get_line(chip, "sda", &i2c_line);
    if (ret) {
        fprintf(stderr, "Failed to get SDA line, error %d: %s\n", ret, strerror(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_add(i2c_line, GPIO_DIR_OUT);
    if (ret) {
        fprintf(stderr, "Failed to request SDA line, error %d: %s\n", ret, strerror(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_add(i2c_line, GPIO_DIR_OUT);
    if (ret) {
        fprintf(stderr, "Failed to request SCL line, error %d: %s\n", ret, strerror(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t stop_mode_cmd[] = {0x00, 0x01};
    ret = gpiod_drain_send(i2c_line, stop_mode_cmd, sizeof(stop_mode_cmd));
    if (ret) {
        fprintf(stderr, "Failed to send stop mode command, error %d: %s\n", ret, strerror(ret));
        gpiod_line_free(i2c_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    usleep(STABILIZATION_DELAY);

    uint8_t config_cmd[] = {
        0x06, // Filter: 10
        0x0A, // Charge Time: 10
        0x01, // Electrode Current: 1
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // Touch Threshold: All 0
        0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, // Release Threshold: All FF
    };
    ret = gpiod_drain_send(i2c_line, config_cmd, sizeof(config_cmd));
    if (ret) {
        fprintf(stderr, "Failed to send configuration command, error %d: %s\n", ret, strerror(ret));
        gpiod_line_free(i2c_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_add(i2c_line, GPIO_DIR_IN);
    if (ret) {
        fprintf(stderr, "Failed to request I2C lines as input, error %d: %s\n", ret, strerror(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_chip_event ev;
    gpiod_chip_event_init(&ev);
    ev.type = GPIO_EVENT_IN;
    ev.line = i2c_line;
    gpiod_add_event(chip, &ev);

    while (1) {
        usleep(STABILIZATION_DELAY);

        ret = gpiod_event_get(chip, &ev);
        if (ret) {
            fprintf(stderr, "Failed to get I2C event, error %d: %s\n", ret, strerror(ret));
            break;
        }

        if (ev.value) {
            gpio_put(relay_gpio, 1);
            printf("Relay toggled (touch detected)\n");
        } else {
            gpio_put(relay_gpio, 0);
            printf("Relay deactivated (no touch)\n");
        }
    }

    gpiod_event_remove(&ev);
    gpiod_line_free(i2c_line);
    gpiod_chip_close(chip);
    gpio_free();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}

