#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define LOG_FILE "door_events.log"
#define RATE_LIMIT_DURATION_MS 2000
#define RELAY_ACTIVATION_MS 500
#define POLLING_INTERVAL_MS 50

struct context {
    GPioDevice *pir_gpio;
    GPioDevice *relay_gpio;
    FILE *log_file;
    bool rate_limit_active;
    time_t last_rate_limit_reset;
};

static int log_event(const struct context *ctx, const char *event_type) {
    if (ctx->log_file == NULL) return -1;

    time_t now = time(NULL);
    fprintf(ctx->log_file, "%ld %s\n", now, event_type);
    fflush(ctx->log_file);
    return 0;
}

static int init_gpio(struct context *ctx) {
    int ret;

    ret = gpiod_in_setup(&ctx->pir_gpio, "GPIO17", GPIOD_IN_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize PIR sensor GPIO\n");
        return ret;
    }

    ret = gpiod_out_setup(&ctx->relay_gpio, "GPIO18", 0);
    if (ret < 0) {
        gpiod_in_teardown(ctx->pir_gpio);
        fprintf(stderr, "Failed to initialize relay GPIO\n");
        return ret;
    }

    ctx->log_file = fopen("door_events.log", "w");
    if (!ctx->log_file) {
        gpiod_out_teardown(ctx->relay_gpio);
        gpiod_in_teardown(ctx->pir_gpio);
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    ctx->rate_limit_active = false;
    ctx->last_rate_limit_reset = 0;

    return 0;
}

static void cleanup_gpio(struct context *ctx) {
    if (ctx->log_file) {
        fclose(ctx->log_file);
        ctx->log_file = NULL;
    }

    gpiod_out_teardown(ctx->relay_gpio);
    gpiod_in_teardown(ctx->pir_gpio);
    gpiod_uninit();
}

static bool is_rate_limited(const struct context *ctx) {
    time_t now = time(NULL);
    if (ctx->rate_limit_active && now - ctx->last_rate_limit_reset < RATE_LIMIT_DURATION_MS) {
        return true;
    }

    return false;
}

int main(int argc, char *argv[]) {
    struct context ctx;
    int ret;

    ret = init_gpio(&ctx);
    if (ret < 0) {
        cleanup_gpio(&ctx);
        return 1;
    }

    while (true) {
        uint64_t timestamp = gpiod_timestamp();
        bool pir_active = gpiod_read(&ctx->pir_gpio) == 1;

        if (pir_active && !is_rate_limited(&ctx)) {
            gpiod_write(&ctx->relay_gpio, 1);
            log_event(&ctx, "Door unlocked");
            sleep_ms(RELAY_ACTIVATION_MS);
            gpiod_write(&ctx->relay_gpio, 0);
            log_event(&ctx, "Door locked");
            ctx.last_rate_limit_reset = time(NULL);
            ctx.rate_limit_active = true;
        }

        if (pir_active && is_rate_limited(&ctx)) {
            log_event(&ctx, "Rate limit: Ignoring motion event");
        } else {
            log_event(&ctx, "Motion detected");
        }

        sleep_ms(POLLING_INTERVAL_MS);
    }

    cleanup_gpio(&ctx);
    return 0;
}

