            gpiod_write(&ctx->relay_gpio, 1);
            log_event(&ctx, "Door unlocked");
            sleep_ms(RELAY_ACTIVATION_MS);
            gpiod_write(&ctx->relay_gpio, 0);
            log_event(&ctx, "Door locked");
            ctx.last_rate_limit_reset = time(NULL);
            ctx.rate_limit_active = true;
        }

        if (pir_active && is_rate_limited(&ctx)) {
            log_event(&ctx, "Rate limit: Ignoring motion event");
        } else {
            log_event(&ctx, "Motion detected");
        }

        sleep_ms(POLLING_INTERVAL_MS);
    }

    cleanup_gpio(&ctx);
    return 0;
}
