        fprintf(stderr, "Failed to set GPIO %d mode\n", MOTOR2_GPIO);
        return -1;
    }

    signal(SIGINT, [](int) { shutdown = 1; });

    while (!shutdown) {
        size_t steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
        uint8_t pattern[steps * 2];

        for (size_t i = 0; i < steps; i++) {
            generate_random_pattern(&pattern[i * 2], 1);
            generate_random_pattern(&pattern[i * 2 + 1], 1);
        }

        for (size_t i = 0; i < steps; i++) {
            uint16_t duration_ms = rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1) + MIN_DURATION_MS;

            gpiod_set_value(ch, pattern[i * 2]);
            usleep(duration_ms * 1000 / 256);
            gpiod_set_value(ch, 0);

            gpiod_set_value(ch, pattern[i * 2 + 1]);
            usleep(duration_ms * 1000 / 256);
            gpiod_set_value(ch, 0);
        }
    }

    gpiod_chip_unload(&chip_data);
    return 0;
}

