#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define HX711_DAT_GPIO 4
#define HX711_CLK_GPIO 17
#define SOLENOID_GPIO 27
#define READ_TIMEOUT_MS 500
#define ZERO_LOAD_READS 100
#define CALIBRATION_FILE "calibration.txt"
#define THRESHOLD_KG 10.0

float scale_factor = 1.0;
float offset = 0.0;

int init_gpio() {
    int ret;
    ret = gpiod_in_init();
    if (ret < 0) {
        perror("Failed to initialize GPIO driver");
        return ret;
    }
    return 0;
}

void cleanup_gpio() {
    gpiod_out_release(SOLENOID_GPIO);
    gpiod_in_release();
}

float read_hx711(int dat_gpio, int clk_gpio) {
    struct gpiod_chip chip;
    struct gpiod_line *line;
    uint64_t ts;
    int ret;
    uint32_t data_left = 1;
    uint32_t data_right = 0;

    ret = gpiod_chip_get_from_number(HX711_DAT_GPIO, &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to get chip for HX711 data line\n");
        return -1;
    }

    line = gpiod_chip_get_line(&chip, 0);
    if (!line) {
        fprintf(stderr, "Failed to get line for HX711 data line\n");
        return -1;
    }

    ret = gpiod_line_start_drain(line, &ts);
    if (ret < 0) {
        fprintf(stderr, "Failed to start draining data line\n");
        return -1;
    }

    ret = gpiod_line_get_value(line, &data_left);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data left\n");
        return -1;
    }

    ret = gpiod_line_get_value(line, &data_right);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data right\n");
        return -1;
    }

    gpiod_line_stop_drain(line);

    return (float)(data_left - data_right) / 16;
}

float calibrate_offset() {
    int i;
    float sum = 0.0;
    for (i = 0; i < ZERO_LOAD_READS; i++) {
        sum += read_hx711(HX711_DAT_GPIO, HX711_CLK_GPIO);
        usleep(READ_TIMEOUT_MS * 1000);
    }
    return sum / ZERO_LOAD_READS;
}

int load_calibration(const char *filename) {
    FILE *fp;
    char line[256];
    if ((fp = fopen(filename, "r")) == NULL) {
        fprintf(stderr, "Failed to open calibration file: %s\n", filename);
        return -1;
    }

    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "scale=%f offset=%f", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Invalid format in calibration file\n");
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

void save_calibration(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open calibration file for writing: %s\n", filename);
        return;
    }

    fprintf(fp, "scale=%f offset=%f\n", scale_factor, offset);
    fclose(fp);
}

int main() {
    int ret;
    struct timespec ts;
    pid_t pid;

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    pid = getpid();

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        struct timespec timeout = {ts.tv_sec + READ_TIMEOUT_MS / 1000, ts.tv_nsec};

        ret = gpiod_in_wait_for_zero(SOLENOID_GPIO, &timeout, 0);
        if (ret < 0 && ret != ETIMEDOUT) {
            fprintf(stderr, "Error waiting for solenoid GPIO\n");
            cleanup_gpio();
            return ret;
        }

        if (ret == ETIMEDOUT) {
            continue;
        }

        float reading = read_hx711(HX711_DAT_GPIO, HX711_CLK_GPIO);
        if (reading < 0) {
            fprintf(stderr, "Error reading HX711 sensor\n");
            cleanup_gpio();
            return -1;
        }

        float weight = scale_factor * reading + offset;

        if (weight > THRESHOLD_KG) {
            gpiod_out_high(SOLENOID_GPIO);
        } else {
            gpiod_out_low(SOLENOID_GPIO);
        }

        FILE *log_file = fopen("weight_log.txt", "a");
        if (log_file != NULL) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld\t%f\n", now, weight);
            fclose(log_file);
        }

        usleep(READ_TIMEOUT_MS * 1000);
    }

    cleanup_gpio();
    return 0;
}

