#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <gpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define READINGS_COUNT 5
#define READING_INTERVAL_MS 50
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define CHECK_INTERVAL_MS 60
#define WAIT_AFTER_CLOSE_MS 60

void setup_gpio() {
    if (gpioInitialize() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpioTerminate();
}

int read_rain_sensor(int pin) {
    int readings[READINGS_COUNT];
    int low_count = 0;

    for (int i = 0; i < READINGS_COUNT; ++i) {
        readings[i] = gpioRead(pin);
        if (readings[i] == 0) {
            low_count++;
        }
        usleep(READING_INTERVAL_MS * 1000);
    }

    int is_raining = low_count >= 3;
    if (is_raining) {
        syslog(LOG_INFO, "Rain detected at %s", ctime(localtime(NULL)));
    }

    return is_raining;
}

void control_motor(int in1_pin, int in2_pin, int pwm_pin) {
    gpioSetMode(in1_pin, PI_OUTPUT);
    gpioSetMode(in2_pin, PI_OUTPUT);
    gpioSetMode(pwm_pin, PI_OUTPUT);

    gpioWrite(in1_pin, 1);
    gpioWrite(in2_pin, 0);
    gpioWrite(pwm_pin, 1);

    for (int i = 0; i < 5 * PWM_FREQUENCY / 1000; ++i) {
        gpioWrite(pwm_pin, 1);
        usleep(PWM_FREQUENCY * 1000 / 1000);
        gpioWrite(pwm_pin, 0);
        usleep(PWM_FREQUENCY * 1000 / 1000);
    }

    gpioWrite(in1_pin, 0);
    gpioWrite(in2_pin, 0);
    gpioWrite(pwm_pin, 0);
}

int main(int argc, char *argv[]) {
    setup_gpio();

    signal(SIGINT, cleanup_gpio);
    signal(SIGTERM, cleanup_gpio);

    while (true) {
        if (read_rain_sensor(RAIN_SENSOR_PIN)) {
            control_motor(MOTOR_IN1_PIN, MOTOR_IN2_PIN, MOTOR_PWM_PIN);
            sleep(WAIT_AFTER_CLOSE_MS / 1000);
        }

        sleep(CHECK_INTERVAL_MS / 1000);
    }

    cleanup_gpio();
    return 0;
}

