    if (gpioInitialize() < 0) {
        log_error("GPIO initialization failed.");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(config.dt_pin, GPIO_OUTPUT);
    gpioSetMode(config.sck_pin, GPIO_OUTPUT);
    gpioSetMode(config.solenoid_pin, GPIO_OUTPUT);

