#define HX711_DATA_PIN 4
#define HX711_CLK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define TIMEOUT_MS 100
#define THRESHOLD_KG 5.0

typedef struct {
    int calibration_factor;
    int calibration_weight;
} Calibration;

static Calibration calibration;
static FILE *calibration_file;
static FILE *security_log_file;
static gpio_context *gpio_ctx;

void hx711_init(void) {
    int ret;

    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(EXIT_FAILURE);
    }

    gpio_ctx = gpio_request(2);
    if (!gpio_ctx) {
        fprintf(stderr, "Failed to request GPIO context\n");
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    gpio_set_mode(gpio_ctx, HX711_DATA_PIN, GPIOD_IN);
    gpio_set_mode(gpio_ctx, HX711_CLK_PIN, GPIOD_OUT);

    if (gpio_export(gpio_ctx, HX711_DATA_PIN) < 0 || gpio_export(gpio_ctx, HX711_CLK_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO pins\n");
        gpio_unrequest(gpio_ctx);
        gpio_exit();
        exit(EXIT_FAILURE);
    }
}

void hx711_read(int16_t *raw_value) {
    uint32_t data = 0;
    int i;

    gpio_set_high(gpio_ctx, HX711_CLK_PIN);
    delay_us(1);
    gpio_set_low(gpio_ctx, HX711_CLK_PIN);
    delay_us(1);

    for (i = 0; i < 24; i++) {
        gpio_set_high(gpio_ctx, HX711_CLK_PIN);
        delay_us(1);
        data <<= 1;
        if (gpio_get_level(gpio_ctx, HX711_DATA_PIN))
            data |= 1;
        delay_us(1);
        gpio_set_low(gpio_ctx, HX711_CLK_PIN);
        delay_us(1);
    }

    *raw_value = data;
}

void calibrate(void) {
    int ret;
    int16_t raw_value;

    printf("Please place a known weight on the load cell.\n");
    fflush(stdout);

    ret = fopen(CALIBRATION_FILE, "r");
    if (ret == NULL) {
        ret = fopen(CALIBRATION_FILE, "w");
        if (ret == NULL) {
            fprintf(stderr, "Failed to open calibration file\n");
            exit(EXIT_FAILURE);
        }

        calibration.calibration_factor = 0;
        calibration.calibration_weight = 0;

        while (1) {
            hx711_read(&raw_value);
            calibration.calibration_factor += raw_value;

            char buffer[256];
            ret = fgets(buffer, sizeof(buffer), stdin);
            if (strcmp(buffer, "done\n") == 0)
                break;
        }

        calibration.calibration_weight = calibration.calibration_factor / 10;
        ret = fclose(calibration_file);

        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file == NULL) {
            fprintf(stderr, "Failed to write calibration data\n");
            exit(EXIT_FAILURE);
        }

        fprintf(calibration_file, "%d\n", calibration.calibration_weight);
        ret = fclose(calibration_file);
    } else {
        ret = fscanf(calibration_file, "%d", &calibration.calibration_weight);
        if (ret != 1) {
            fprintf(stderr, "Failed to read calibration data\n");
            exit(EXIT_FAILURE);
        }

        fclose(calibration_file);
        calibration_file = fopen(CALIBRATION_FILE, "r");
    }
}

int main(int argc, char *argv[]) {
    struct timespec timestamp;
    int16_t raw_value;
    int timeout_count = 0;
    int last_timeout = 0;
    int solenoid_state = 0;

    signal(SIGINT, sigint_handler);

    hx711_init();
    calibrate();

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Failed to open calibration file\n");
        exit(EXIT_FAILURE);
    }

    ret = fscanf(calibration_file, "%d", &calibration.calibration_weight);
    if (ret != 1) {
        fprintf(stderr, "Failed to read calibration data\n");
        exit(EXIT_FAILURE);
    }

    fclose(calibration_file);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &timestamp);

        hx711_read(&raw_value);
        int weight = calibration.calibration_weight * raw_value;

        if (timeout_count > 0 && (timestamp.tv_sec - last_timeout) > TIMEOUT_MS / 1000) {
            printf("Communication timeout detected\n");
            timeout_count = 0;
        }

        timeout_count++;

        if (weight > THRESHOLD_KG) {
            if (solenoid_state == 0) {
                solenoid_state = 1;
                printf("Engaging solenoid...\n");
                fflush(stdout);

                security_log_file = fopen(SECURITY_LOG_FILE, "a");
                if (security_log_file == NULL) {
                    fprintf(stderr, "Failed to open security log file\n");
                    exit(EXIT_FAILURE);
                }

                struct tm *tm_info = localtime(&timestamp.tv_sec);
                char timestamp_str[20];
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(security_log_file, "%s, Weight: %.2f kg\n", timestamp_str, weight);
                fclose(security_log_file);
            }

            gpio_set_high(gpio_ctx, SOLENOID_PIN);
            delay_s(5);
            gpio_set_low(gpio_ctx, SOLENOID_PIN);
            solenoid_state = 0;
        }

        last_timeout = timestamp.tv_sec;
        delay_ms(100);
    }

    return 0;
}

void sigint_handler(int signum) {
    printf("SIGINT received, unlocking solenoid and exiting...\n");
    fflush(stdout);

    if (solenoid_state == 1) {
        gpio_set_low(gpio_ctx, SOLENOID_PIN);
        solenoid_state = 0;
    }

    gpio_unrequest(gpio_ctx);
    gpio_exit();
    exit(EXIT_SUCCESS);
}

