#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

enum RelayState { RELAY_OFF, RELAY_ON };
enum SensorState { SENSOR_NO_OBSTACLE, SENSOR_OBSTACLE };

enum RelayState get_relay_state() { return RELAY_OFF; }
enum SensorState get_sensor_state() { return SENSOR_NO_OBSTACLE; }

void toggle_relay(enum RelayState *state) {
    if (*state == RELAY_OFF) {
        gpiod_trigger(RELAY_GPIO, NULL, 1);
        *state = RELAY_ON;
    } else {
        gpiod_trigger(RELAY_GPIO, NULL, 0);
        *state = RELAY_OFF;
    }
}

int log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    char log_msg[256];
    vsnprintf(log_msg, sizeof(log_msg), format, args);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, log_msg);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
        return -1;
    }

    va_end(args);
    return 0;
}

int main() {
    struct gpiod_chipchip *chi;
    struct gpiod_line *line;
    enum RelayState relay_state = RELAY_OFF;

    if (gpiod_chip_open(&chi, "GPIO") < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chi, SENSOR_GPIO);
    if (line == NULL) {
        fprintf(stderr, "Failed to get sensor GPIO line\n");
        gpiod_chip_close(chi);
        return -1;
    }

    if (gpiod_line_request_lines(line, 1) < 0) {
        fprintf(stderr, "Failed to request sensor GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chi);
        return -1;
    }

    line = gpiod_chip_get_line(chi, RELAY_GPIO);
    if (line == NULL) {
        fprintf(stderr, "Failed to get relay GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chi);
        return -1;
    }

    if (gpiod_line_request_lines(line, 1) < 0) {
        fprintf(stderr, "Failed to request relay GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chi);
        return -1;
    }

    gpiod_line_export(line);

    while (1) {
        enum SensorState sensor_state = get_sensor_state();
        if (sensor_state == SENSOR_OBSTACLE) {
            toggle_relay(&relay_state);
            log_event("Obstacle detected, relay switched ON\n");
        } else {
            log_event("No obstacle, relay state: %s\n", relay_state == RELAY_ON ? "ON" : "OFF");
        }

        sleep(1);
    }

    gpiod_line_unref(line);
    gpiod_chip_close(chi);
    return 0;
}

