This code continuously monitors the Keywish KY-022 IR obstacle avoidance sensor connected to GPIO16 and toggles the Songle SRD-05VDC-SL relay module attached to GPIO20 accordingly. It logs each state change with the new relay state (ON or OFF) and an ISO 8601 timestamp to a file named `relay_events.log`. The sensor is active-low, and the relay is active-high. The implementation uses the libgpiod library for all GPIO operations, handles initialization failures, sensor read errors, and log file write errors, and cleans up all GPIO resources on receipt of SIGINT or SIGTERM before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpio.h>

#define PIR_GPIO 17
#define BUZZER_GPIO 18
#define BUZZER_ON HIGH
#define BUZZER_OFF LOW

gpio_init();
gpio_set_mode(PIR_GPIO, GPIO_INPUT);
gpio_set_mode(BUZZER_GPIO, GPIO_OUTPUT);

void signal_handler(int signum) {
    gpio_unclaim(BUZZER_GPIO);
    gpio_unclaim(PIR_GPIO);
    gpio_cleanup();
    printf("Exiting...\n");
    exit(signum);
}

void setup_logging() {
    FILE *log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ",
        1900 + tm.tm_year, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_logging();

    while (true) {
        int motion_detected = gpio_get(PIR_GPIO);
        if (motion_detected) {
            gpio_set(BUZZER_GPIO, BUZZER_ON);
            printf("Motion detected, activating buzzer\n");
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%F %T", tm);
            FILE *log_file = fopen("motion_log.txt", "a");
            if (!log_file) {
                perror("Failed to append to log file");
                exit(EXIT_FAILURE);
            }
            fprintf(log_file, "%s: Motion detected\n", timestamp);
            fclose(log_file);

            usleep(2000000); // 2 seconds
            gpio_set(BUZZER_GPIO, BUZZER_OFF);
            printf("Buzzer deactivated\n");
        }
    }

    gpio_unclaim(BUZZER_GPIO);
    gpio_unclaim(PIR_GPIO);
    gpio_cleanup();

    return 0;
}

