    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d ",
        1900 + tm.tm_year, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_logging();

    while (true) {
        int motion_detected = gpio_get(PIR_GPIO);
        if (motion_detected) {
            gpio_set(BUZZER_GPIO, BUZZER_ON);
            printf("Motion detected, activating buzzer\n");
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%F %T", tm);
            FILE *log_file = fopen("motion_log.txt", "a");
            if (!log_file) {
                perror("Failed to append to log file");
                exit(EXIT_FAILURE);
            }
            fprintf(log_file, "%s: Motion detected\n", timestamp);
            fclose(log_file);

            usleep(2000000); // 2 seconds
            gpio_set(BUZZER_GPIO, BUZZER_OFF);
            printf("Buzzer deactivated\n");
        }
    }

    gpio_unclaim(BUZZER_GPIO);
    gpio_unclaim(PIR_GPIO);
    gpio_cleanup();

    return 0;
}
