    struct gpio_output output;
    int duration;
    FILE *fp;
    char line[256];

    gpio_init();
    if (gpio_request(GPIO_PIN, &target) < 0) {
        fprintf(stderr, "Failed to claim GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        return 1;
    }

    target.direction = GPIOD_OUT;
    target.active_low = 1;
    if (gpio_set(GPIO_PIN, &target) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", GPIO_PIN, strerror(errno));
        return 1;
    }

    output.gpio = GPIO_PIN;
    output.value = 0;
    if (gpio_output_init(&output) < 0) {
        fprintf(stderr, "Failed to initialize GPIO output: %s\n", strerror(errno));
        return 1;
    }

    fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", CONFIG_FILE, strerror(errno));
        return 1;
    }

    if (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "duration=%d", &duration) != 1) {
            fprintf(stderr, "Malformed duration in %s\n", CONFIG_FILE);
            fclose(fp);
            return 1;
        }

        if (duration < MIN_DURATION || duration > MAX_DURATION) {
            fprintf(stderr, "Duration %d out of range\n", duration);
            fclose(fp);
            return 1;
        }

        printf("Watering for %d seconds\n", duration);
        gpio_output_set(&output, 1); // Turn valve on
        sleep_ms(duration * 1000);
        gpio_output_set(&output, 0); // Turn valve off
        printf("Valve turned off\n");

    } else {
        printf("No watering duration specified in %s\n", CONFIG_FILE);
        fclose(fp);
        return 1;
    }

    fclose(fp);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (!sig_flag) {
        gpio_output_set(&output, 0); // Ensure valve is off when checking flag
        sleep(1);
    }

    gpio_output_set(&output, 0); // Ensure valve is off on exit

    gpio_free();
    return 0;
}

