#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define BASE_SPEED 150
#define LEFT_MOTOR_GPIO 22
#define RIGHT_MOTOR_GPIO 23
#define LEFT_MOTOR_PWM_FREQ 1000
#define RIGHT_MOTOR_PWM_FREQ 1000
#define SENSOR_GPIO_LEFT 4
#define SENSOR_GPIO_MIDDLE 17
#define SENSOR_GPIO_RIGHT 27
#define LOG_FILE "trace_log.txt"

struct motor_speeds {
    int left;
    int right;
};

struct sensor_states {
    bool left;
    bool middle;
    bool right;
};

struct motor_control_data {
    struct sensor_states sensor_states;
    struct motor_speeds motor_speeds;
    time_t last_timestamp;
};

static struct motor_control_data control_data;
static FILE *log_file;

static void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpiod_uninit();
    exit(0);
}

static int init_gpio(void) {
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return ret;
    }

    control_data.last_timestamp = time(NULL);

    ret = gpiod_export(NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIOs\n");
        gpiod_uninit();
        return ret;
    }

    control_data.sensor_states.left_gpio = gpiod_in(SENSOR_GPIO_LEFT);
    control_data.sensor_states.middle_gpio = gpiod_in(SENSOR_GPIO_MIDDLE);
    control_data.sensor_states.right_gpio = gpiod_in(SENSOR_GPIO_RIGHT);

    if (!control_data.sensor_states.left_gpio || !control_data.sensor_states.middle_gpio || !control_data.sensor_states.right_gpio) {
        fprintf(stderr, "Failed to initialize sensor GPIOs\n");
        gpiod_unexport(NULL);
        gpiod_uninit();
        return -1;
    }

    control_data.motor_speeds.left_gpio = gpiod_out(LEFT_MOTOR_GPIO, NULL);
    control_data.motor_speeds.right_gpio = gpiod_out(RIGHT_MOTOR_GPIO, NULL);

    if (!control_data.motor_speeds.left_gpio || !control_data.motor_speeds.right_gpio) {
        fprintf(stderr, "Failed to initialize motor GPIOs\n");
        gpiod_unexport(NULL);
        gpiod_uninit();
        return -1;
    }

    control_data.motor_speeds.left = 0;
    control_data.motor_speeds.right = 0;

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_unexport(NULL);
        gpiod_uninit();
        return -1;
    }

    signal(SIGINT, sigint_handler);

    return 0;
}

static void update_motor_speeds(void) {
    bool left_low, right_low;
    struct sensor_states *sensor_states = &control_data.sensor_states;
    struct motor_speeds *motor_speeds = &control_data.motor_speeds;

    gpiod_trigger(sensor_states->left_gpio, true);
    gpiod_trigger(sensor_states->middle_gpio, true);
    gpiod_trigger(sensor_states->right_gpio, true);

    left_low = !gpiod_get_value(sensor_states->left_gpio);
    right_low = !gpiod_get_value(sensor_states->right_gpio);

    if (left_low && !right_low) {
        motor_speeds->left = BASE_SPEED / 2;
        motor_speeds->right = BASE_SPEED;
    } else if (!left_low && right_low) {
        motor_speeds->left = BASE_SPEED;
        motor_speeds->right = BASE_SPEED / 2;
    } else if (!left_low && !right_low) {
        motor_speeds->left = 0;
        motor_speeds->right = 0;
    } else {
        motor_speeds->left = BASE_SPEED;
        motor_speeds->right = BASE_SPEED;
    }

    gpiod_trigger(sensor_states->left_gpio, false);
    gpiod_trigger(sensor_states->middle_gpio, false);
    gpiod_trigger(sensor_states->right_gpio, false);
}

static void update_log(void) {
    time_t current_time = time(NULL);
    if (difftime(current_time, control_data.last_timestamp) >= 10) {
        control_data.last_timestamp = current_time;

        fprintf(log_file, "%s,%d,%d,%d,%d,%d\n",
                ctime(&current_time),
                gpiod_get_value(control_data.sensor_states.left_gpio),
                gpiod_get_value(control_data.sensor_states.middle_gpio),
                gpiod_get_value(control_data.sensor_states.right_gpio),
                control_data.motor_speeds.left,
                control_data.motor_speeds.right);
    }
}

static void set_pwm(void) {
    int ret;
    struct motor_speeds *motor_speeds = &control_data.motor_speeds;

    ret = gpiod_pwm_setup(motor_speeds->left_gpio, LEFT_MOTOR_PWM_FREQ, motor_speeds->left);
    if (ret < 0) {
        fprintf(stderr, "Failed to set left motor PWM frequency or duty cycle\n");
    }

    ret = gpiod_pwm_setup(motor_speeds->right_gpio, RIGHT_MOTOR_PWM_FREQ, motor_speeds->right);
    if (ret < 0) {
        fprintf(stderr, "Failed to set right motor PWM frequency or duty cycle\n");
    }
}

int main(void) {
    int ret;

    ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    while (1) {
        update_motor_speeds();
        update_log();
        set_pwm();
    }

    return 0;
}

