    struct timespec last_press_time;
};

static struct servo_state servo;
static struct button_state lock_button;
static struct button_state unlock_button;

static void servo_init(struct servo_state *servo)
{
    int ret;

    servo->fd = gpiod_in_export(NULL, "servo_pwm", &ret);
    if (ret) {
        fprintf(stderr, "Failed to export servo PWM pin: %d\n", ret);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_fm_set_min_pulse_width(servo->fd, 500);
    if (ret) {
        fprintf(stderr, "Failed to set min pulse width: %d\n", ret);
        goto servo_export_fail;
    }

    ret = gpiod_fm_set_max_pulse_width(servo->fd, 2500);
    if (ret) {
        fprintf(stderr, "Failed to set max pulse width: %d\n", ret);
        goto servo_export_fail;
    }

servo_export_fail:
    gpiod_in_unexport(servo->fd);
    exit(EXIT_FAILURE);
}

static void button_init(struct button_state *button)
{
    int ret;

    button->fd = gpiod_in_export(NULL, "button_" STR(button->fd), &ret);
    if (ret) {
        fprintf(stderr, "Failed to export button pin: %d\n", ret);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_fm_set_pull_up(button->fd, true);
    if (ret) {
        fprintf(stderr, "Failed to enable pull-up resistor: %d\n", ret);
        goto button_export_fail;
    }

button_export_fail:
    gpiod_in_unexport(button->fd);
}

static bool is_button_pressed(struct button_state *button)
{
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (now.tv_sec != button->last_press_time.tv_sec) {
        button->last_press_time = now;
        return false;
    }

    if ((now.tv_nsec - button->last_press_time.tv_nsec) < DEBOUNCE_DELAY_MS * 1000000 / 1000) {
        return false;
    }

    return true;
}

static void handle_lock_button(struct button_state *button)
{
    if (is_button_pressed(button)) {
        printf("Lock button pressed\n");
        servo.pulse_width = 1000;
        gpiod_fm_set_pulse_width(servo.fd, servo.pulse_width);
    }
}

static void handle_unlock_button(struct button_state *button)
{
    if (is_button_pressed(button)) {
        printf("Unlock button pressed\n");
        servo.pulse_width = 2000;
        gpiod_fm_set_pulse_width(servo.fd, servo.pulse_width);
    }
}

static void sigint_handler(int signum)
{
    printf("\nCleaning up and exiting...\n");
    gpiod_in_unexport(servo.fd);
    gpiod_in_unexport(lock_button.fd);
    gpiod_in_unexport(unlock_button.fd);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, sigint_handler);

    servo.fd = gpiod_in_export(&chip, "servo_pwm", NULL);
    if (!servo.fd) {
        fprintf(stderr, "Failed to export servo PWM pin\n");
        return EXIT_FAILURE;
    }

    ret = gpiod_fm_set_min_pulse_width(servo.fd, 500);
    if (ret) {
        fprintf(stderr, "Failed to set min pulse width: %d\n", ret);
        goto servo_export_fail;
    }

    ret = gpiod_fm_set_max_pulse_width(servo.fd, 2500);
    if (ret) {
        fprintf(stderr, "Failed to set max pulse width: %d\n", ret);
        goto servo_export_fail;
    }

servo_export_fail:
    gpiod_in_unexport(servo.fd);
    return EXIT_FAILURE;

button_init(&lock_button, LOCK_BUTTON_PIN);
button_init(&unlock_button, UNLOCK_BUTTON_PIN);

while (true) {
    handle_lock_button(&lock_button);
    handle_unlock_button(&unlock_button);
    sleep(1);
}

return EXIT_SUCCESS;
}

