#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

void stop_motors(gpio_context ctx) {
    gpiod_chip_remove_line(ctx, MOTOR1_GPIO);
    gpiod_chip_remove_line(ctx, MOTOR2_GPIO);
}

void signal_handler(int signum) {
    switch (signum) {
        case SIGINT:
        case SIGTERM:
            stop_motors(gpio_get_default_context());
            exit(0);
    }
}

int main() {
    gpio_context ctx;
    int ret;

    // Initialize GPIO library
    ret = gpio_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return ret;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Get default GPIO context
    ret = gpio_get_default_context(&ctx);
    if (ret < 0) {
        fprintf(stderr, "Failed to get default GPIO context\n");
        gpio_exit();
        return ret;
    }

    // Configure GPIO pins for output
    ret = gpiod_chip_request_line(ctx, "GPIO", MOTOR1_GPIO, GPIOD_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d line\n", MOTOR1_GPIO);
        stop_motors(ctx);
        gpio_exit();
        return ret;
    }

    ret = gpiod_chip_request_line(ctx, "GPIO", MOTOR2_GPIO, GPIOD_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO%d line\n", MOTOR2_GPIO);
        stop_motors(ctx);
        gpio_exit();
        return ret;
    }

    // Set initial motor states (off)
    gpiod_set_value(ctx, MOTOR1_GPIO, 0);
    gpiod_set_value(ctx, MOTOR2_GPIO, 0);

    while (1) {
        // Motor 1 on for 200 ms
        gpiod_set_value(ctx, MOTOR1_GPIO, 1);
        usleep(200000);
        gpiod_set_value(ctx, MOTOR1_GPIO, 0);

        // Motor 2 on for 300 ms
        gpiod_set_value(ctx, MOTOR2_GPIO, 1);
        usleep(300000);
        gpiod_set_value(ctx, MOTOR2_GPIO, 0);
    }

    // Release GPIO lines and exit
    stop_motors(ctx);
    gpio_exit();

    return 0;
}

