#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define SOUND_SENSOR_PIN 0
#define SOUND_ALERT_TOPIC "SOUND_ALERTS"

void sigint_handler(int signum) {
    printf("Received SIGINT, initiating clean shutdown...\n");
    clean_shutdown();
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, initiating clean shutdown...\n");
    clean_shutdown();
    exit(0);
}

void clean_shutdown() {
    zmq_ctx_t *ctx = zmq_ctx_new();
    void *socket = zmq_socket(ctx, ZMQ_SUB);
    int rc = zmq_connect(socket, "tcp://localhost:5555");
    if (rc < 0) {
        fprintf(stderr, "Error connecting to ZeroMQ socket: %s\n", strerror(errno));
        zmq_ctx_destroy(&ctx);
        return;
    }

    zmq_setsockopt(socket, ZMQ_SUBSCRIBE, SOUND_ALERT_TOPIC, strlen(SOUND_ALERT_TOPIC));

    while (1) {
        if (zmq_msg_t *msg = (zmq_msg_t *)zmq_recv(socket, NULL, 0, 0, &rc)) {
            printf("Received message on topic %s\n", SOUND_ALERT_TOPIC);
            zmq_msg_close(&msg);
        }
        sleep(1);
    }

    zmq_close(socket);
    zmq_ctx_destroy(&ctx);

    gpiod_chip_release(chip);
    gpiod_line_release(line);
}

