    zmq_ctx_t *ctx = zmq_ctx_new();
    void *socket = zmq_socket(ctx, ZMQ_PUB);
    int rc = zmq_bind(socket, "tcp://*:5555");
    if (rc < 0) {
        fprintf(stderr, "Error binding to ZeroMQ socket: %s\n", strerror(errno));
        zmq_ctx_destroy(&ctx);
        return 1;
    }

    gpiod_chip_t *chip = gpiod_chip_open(0, "GPIO");
    gpiod_line_t *line = gpiod_chip_get_line(chip, SOUND_SENSOR_GPIO);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", SOUND_SENSOR_GPIO);
        zmq_close(socket);
        zmq_ctx_destroy(&ctx);
        return 1;
    }

    gpiod_line_export(line, true);
    gpiod_line_set_direction(line, GPIO_IN);
    gpiod_line_set_pull(line, GPIO_PULL_DOWN);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    if (argc != 2 || (strcmp(argv[1], "sound_sensor") != 0 && strcmp(argv[1], "alarm_node") != 0)) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return 1;
    }

    while (1) {
        if (strcmp(argv[1], "sound_sensor") == 0) {
            uint32_t value;
            rc = gpiod_line_read(line, &value);
            if (rc < 0) {
                fprintf(stderr, "Error reading GPIO line %d: %s\n", SOUND_SENSOR_GPIO, strerror(errno));
                break;
            }

            if (!(value & (1 << SOUND_SENSOR_PIN))) {
                zmq_msg_t msg;
                zmq_msg_init(&msg);
                zmq_msg_copy(&msg, SOUND_ALERT_TOPIC, strlen(SOUND_ALERT_TOPIC));
                rc = zmq_send(socket, &msg, ZMQ_SNDMORE);
                if (rc < 0) {
                    fprintf(stderr, "Error publishing to ZeroMQ socket: %s\n", strerror(errno));
                    break;
                }
                zmq_msg_close(&msg);
            }
            usleep(10 * 1000);
        } else if (strcmp(argv[1], "alarm_node") == 0) {
            // Subscribe to SOUND_ALERT_TOPIC and handle LED control
            // ...
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    zmq_ctx_destroy(&ctx);

    return 0;
}

