#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/syslog.h>
#include <gpiod.h>
#include <json-c/json.h>
#include <arpa/inet.h>
#include <mqtt.h>

#define IR_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

struct ir_frame {
    uint8_t address[8];
    uint8_t bits[8];
    uint16_t crc;
};

static int ir_callback(struct gpiod_chip *chip,
                        const struct gpiod_line_info *line,
                        uint32_t events,
                        void *user_data) {
    struct ir_frame frame;
    memset(&frame, 0, sizeof(struct ir_frame));

    if (events & GPIOD_EVENT_FALLING_EDGE) {
        static uint64_t pulse_time = 0;
        uint64_t now = gpiod_get_timestamp();

        if (now - pulse_time > 1000000000ULL) { // 1 second
            syslog(LOG_INFO, "Pulse buffer overflow, discarding data");
            return 0;
        }

