#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BH1750_ADDR 0x23
#define I2C_SLAVE 0x27
#define BUF_SIZE 256
#define DELAY_MS 180
#define PORT 5005
#define GROUP 239.255.255.250

int i2c_fd;
int udp_sock;
volatile int terminate = 0;

float read_lux(int addr) {
    struct i2c_rdwr_ioctl_data rdwr;
    float lux;

    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        return NAN;
    }

    rdwr.fds = &i2c_fd;
    rdwr.buf = &lux;
    rdwr.len = sizeof(lux);
    rdwr.flags = 0;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        return NAN;
    }

    return lux;
}

void broadcast_lux(float lux_values[], int sensor_ids[]) {
    char buf[BUF_SIZE];
    int i, j;
    for (i = 0; i < 4; i++) {
        if (!isnan(lux_values[i])) {
            snprintf((char *)&buf[j], BUF_SIZE - j, "%d,%f;", sensor_ids[i], lux_values[i]);
            j += strlen((char *)&buf[j]) + 1;
        }
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(GROUP);
    address.sin_port = htons(PORT);

    if (sendto(udp_sock, buf, j, 0, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("sendto");
    }
}

int main() {
    int i;
    float lux_values[4];
    int sensor_ids[4] = {BH1750_ADDR, BH1750_ADDR, BH1750_ADDR, BH1750_ADDR};

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("i2c-1 open");
        return 1;
    }

    udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sock < 0) {
        perror("socket");
        close(i2c_fd);
        return 1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(udp_sock, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, [](int) { terminate = 1; });
    signal(SIGTERM, [](int) { terminate = 1; });

    while (!terminate) {
        for (i = 0; i < 4; i++) {
            lux_values[i] = read_lux(sensor_ids[i]);
            if (isnan(lux_values[i])) {
                printf("Failed to read from sensor %d\n", sensor_ids[i]);
            }
            usleep(DELAY_MS * 1000);
        }

        broadcast_lux(lux_values, sensor_ids);
    }

    close(i2c_fd);
    close(udp_sock);

    return 0;
}

