#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <time.h>

#define HONEYWELL_AWM7300V_ADDR 0x18
#define MAX_RETRIES 3
#define DELAY_MS 100

int i2c_fd = -1;
FILE *log_file = NULL;

static int i2c_write(int fd, unsigned char reg, unsigned int len, unsigned char *data) {
    if (len != 0) {
        return write(fd, data, len);
    } else {
        unsigned char start_cond = 0x00;
        return write(fd, &start_cond, 1);
    }
}

static int i2c_read(int fd, unsigned char reg, unsigned char *data, unsigned int len) {
    return read(fd, data, len);
}

static int extract_flow_value(unsigned char *bytes, unsigned char *flow_value) {
    *flow_value = (bytes[0] << 8) | bytes[1];
    return 0;
}

static float convert_to_slpm(unsigned int flow_value) {
    // Implement conversion logic based on sensor documentation
    return (float)flow_value / 1000.0;
}

static void log_airflow_entry(const char *timestamp, float flow_rate) {
    if (log_file != NULL) {
        fprintf(log_file, "%s - Flow Rate: %.2f SLPM\n", timestamp, flow_rate);
        fflush(log_file);
    }
}

static void sigint_handler(int signum, gpiod_chip *chip, uint value, uint edge, uint edge_glitch, uint seq, void *user_data) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_chip chip;
    gpiod_chip_init(&chip, "GPIO0");
    chip.trigger_type = GPIO_TRIGGER_FALLING_EDGE;
    chip.user_data = NULL;
    chip.handler = sigint_handler;
    gpiod_chip_add(&chip, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HONEYWELL_AWM7300V_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("airflow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        unsigned char bytes[2];
        int retries = MAX_RETRIES;

        while (retries > 0) {
            int ret = i2c_read(i2c_fd, 0x00, bytes, 2);
            if (ret == 2) {
                unsigned char flow_value;
                if (extract_flow_value(bytes, &flow_value) == 0) {
                    float flow_rate = convert_to_slpm(flow_value);
                    char timestamp[20];
                    time_t now = time(NULL);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                    log_airflow_entry(timestamp, flow_rate);
                    break;
                } else {
                    retries--;
                    sleep(DELAY_MS / 1000);
                }
            } else if (ret < 0) {
                if (errno == EIO) {
                    fprintf(stderr, "I2C bus error, retrying...\n");
                    retries--;
                    sleep(DELAY_MS / 1000);
                } else {
                    close(i2c_fd);
                    return 1;
                }
            }
        }

        if (retries == 0) {
            fprintf(stderr, "Failed to read from sensor after %d retries, exiting...\n", MAX_RETRIES);
            break;
        }
    }

    gpiod_chip_remove(&chip);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

