#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <gpiod.h>

#define DEVICE_PATH "/dev/i2c-1"
#define ADV_AS7341_ID 0x39
#define CFG6_SMUX_CONFIG 0x00
#define ENABLE_PON 0x01
#define SP_EN 0x02
#define SPECTRAL_CHANNELS 10

int main() {
    int fd;
    gpiod_chip_reg_desc_t *chip;
    gpiod_chip_reg_t *reg;
    int ret;
    char timestamp[20];
    char spectral_data[SPECTRAL_CHANNELS * 3 + 1];
    FILE *log_file;

    fd = open(DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    chip = gpiod_chip_open("/dev/i2c-1", O_RDWR);
    if (!chip) {
        close(fd);
        perror("Failed to open I2C chip");
        return 1;
    }

    reg = gpiod_chip_get_reg(chip, 0);
    if (!reg) {
        gpiod_chip_close(chip);
        close(fd);
        perror("Failed to get I2C register");
        return 1;
    }

    // Verify sensor ID
    if (gpiod_i2c_read_byte_data(reg, ADV_AS7341_ID, NULL) != ADV_AS7341_ID) {
        gpiod_chip_close(chip);
        close(fd);
        fprintf(stderr, "Sensor ID mismatch\n");
        return 1;
    }

    // Power on sensor
    gpiod_i2c_write_byte_data(reg, ENABLE_PON, ENABLE_PON);

    // Configure SMUX
    gpiod_i2c_write_byte_data(reg, CFG6_SMUX_CONFIG, CFG6_SMUX_CONFIG);

    // Enable spectral measurement
    gpiod_i2c_write_byte_data(reg, SP_EN, SP_EN);

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (!log_file) {
        gpiod_chip_close(chip);
        close(fd);
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        // Acquire spectral data
        for (int i = 0; i < SPECTRAL_CHANNELS; i++) {
            spectral_data[i * 3] = (char)gpiod_i2c_read_byte_data(reg, i + 1, NULL);
            spectral_data[i * 3 + 1] = (char)gpiod_i2c_read_byte_data(reg, i + 1, 1);
            spectral_data[i * 3 + 2] = ',';
        }
        spectral_data[SPECTRAL_CHANNELS * 3] = '\n';

        // Get timestamp
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        // Write to log file
        fprintf(log_file, "%s, %s", timestamp, spectral_data);

        // Sleep for 5 seconds
        sleep(5);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    close(fd);

    return 0;
}

