        data.timestamp = time(NULL);

        fprintf(csv_file, "%lu,%d,%d,%d\n", data.timestamp, data.x_g, data.y_g, data.z_g);
        fflush(csv_file);

        sleep((long)interval);
    }

    i2c_close(fd);
    fclose(csv_file);
    fclose(error_file);

    gpiod_uninit();

    return 0;
}

