#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_IP "239.255.255.250"
#define MULTICAST_PORT 5000
#define RETRY_DELAY 1

int i2c_fd = -1;
int udp_socket = -1;

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    close(i2c_fd);
    close(udp_socket);
    exit(0);
}

void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or perform I2C bus transaction");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

uint16_t read_light_level(void) {
    uint8_t reg;
    uint16_t raw_value = 0;

    if (ioctl(i2c_fd, I2C_RDWR, &reg) < 0) {
        perror("Failed to read from BH1750 register");
        return 0;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &raw_value) < 0) {
        perror("Failed to read raw light value");
        return 0;
    }

    return raw_value;
}

float lux_from_raw(uint16_t raw_value) {
    return (float)raw_value / 1048576.0;
}

void setup_udp() {
    struct sockaddr_in addr;
    int opt = 1;

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_IP);
    addr.sin_port = htons(MULTICAST_PORT);
    addr.sin_len = sizeof(addr);

    if (setsockopt(udp_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("Failed to set socket option");
        close(udp_socket);
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_i2c();
    setup_udp();

    while (1) {
        uint16_t raw_value = read_light_level();
        float lux = lux_from_raw(raw_value);

        char lux_str[20];
        snprintf(lux_str, sizeof(lux_str), "%.2f", lux);

        struct sockaddr_in dest_addr;
        dest_addr.sin_family = AF_INET;
        dest_addr.sin_addr.s_addr = inet_addr(MULTICAST_IP);
        dest_addr.sin_port = htons(MULTICAST_PORT);

        if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        sleep(1);
    }

    close(i2c_fd);
    close(udp_socket);
    return 0;
}

