#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <unistd.h>

#define MAGIC_WORD 0x54575241 // 'TRAW'
#define TLV_TYPE_LEN 1
#define TLV_VALUE_LEN 2
#define TLV_PAYLOAD_LEN (TLV_TYPE_LEN + TLV_VALUE_LEN)
#define MAX_BUFFER_SIZE 1024

struct tlv_payload {
    uint8_t type;
    uint16_t value;
};

FILE *csv_file = NULL;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int read_uart(uint8_t *buffer, size_t buffer_size) {
    int bytes_read = read(STDIN_FILENO, buffer, buffer_size);
    if (bytes_read < 0) {
        log_error("Failed to read from UART: ");
        return -1;
    }
    return bytes_read;
}

int write_uart(const uint8_t *buffer, size_t buffer_size) {
    return write(STDOUT_FILENO, buffer, buffer_size);
}

int validate_magic_word(const uint8_t *data) {
    return memcmp(data, &MAGIC_WORD, 4) == 0;
}

int extract_range_velocity(const uint8_t *data, uint16_t *range, uint16_t *velocity) {
    if (data[1] != 2) {
        log_error("Invalid TLV payload length\n");
        return -1;
    }

    *range = (uint16_t)data[2] << 8 | data[3];
    *velocity = (uint16_t)data[4] << 8 | data[5];
    return 0;
}

void append_to_csv(const struct timespec *timestamp, int object_index, float range_m, float velocity_mps) {
    if (!csv_file) {
        csv_file = fopen("radar_data.csv", "a");
        if (!csv_file) {
            log_error("Failed to open radar_data.csv for appending\n");
            return;
        }
    }

    fprintf(csv_file, "%ld,%d,%f,%f\n",
            (long)timestamp->tv_sec,
            object_index,
            range_m,
            velocity_mps);

    fflush(csv_file);
}

int main() {
    struct gpiod_chipchip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip\n");
        return -1;
    }

    struct gpiod_line line = gpiod_chip_get_line(chip, 8); // Assuming TX is on pin 8
    if (gpiod_line_export(line, "tx_export")) {
        log_error("Failed to export TX pin\n");
        gpiod_chip_close(chip);
        return -1;
    }
    gpiod_line_direction_set(line, GPIO_DIR_OUT);

    struct termios tty;
    int uart_fd = open("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        log_error("Failed to open UART\n");
        gpiod_chip_close(chip);
        return -1;
    }

    tcgetattr(uart_fd, &tty);
    cfsetispeed(&tty, B921600);
    cfsetospeed(&tty, B921600);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; // Adjust timeout as needed
    if (tcsetattr(uart_fd, TCSANOW, &tty) < 0) {
        log_error("Failed to set UART attributes\n");
        close(uart_fd);
        gpiod_chip_close(chip);
        return -1;
    }

    uint8_t buffer[MAX_BUFFER_SIZE];
    uint8_t magic_word[4];
    uint16_t range, velocity;
    char timestamp_str[64];
    struct timespec timestamp;
    clock_gettime(CLOCK_MONOTONIC, &timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp.tv_sec));

    while (1) {
        size_t bytes_read = read_uart(buffer, sizeof(buffer));
        if (bytes_read < 0) {
            break;
        }

        if (bytes_read < 4 || memcmp(buffer, magic_word, 4) != 0) {
            continue; // Skip non-matching or incomplete magic words
        }

        int object_index = 0;
        while (bytes_read >= TLV_PAYLOAD_LEN) {
            struct tlv_payload payload;
            if (extract_range_velocity(buffer + TLV_TYPE_LEN, &payload.type, &payload.value)) {
                range = payload.value;
                velocity = payload.type;

                append_to_csv(&timestamp, object_index++, range / 100.0f, velocity / 100.0f);
            } else {
                log_error("Failed to extract range/velocity\n");
            }

            bytes_read -= TLV_PAYLOAD_LEN;
            memcpy(buffer, buffer + TLV_PAYLOAD_LEN, bytes_read);
        }
    }

    fclose(csv_file);
    gpiod_line_unexport(line);
    gpiod_chip_close(chip);
    close(uart_fd);

    return 0;
}

