        if (bytes_read < 0) {
            break;
        }

        if (bytes_read < 4 || memcmp(buffer, magic_word, 4) != 0) {
            continue; // Skip non-matching or incomplete magic words
        }

        int object_index = 0;
        while (bytes_read >= TLV_PAYLOAD_LEN) {
            struct tlv_payload payload;
            if (extract_range_velocity(buffer + TLV_TYPE_LEN, &payload.type, &payload.value)) {
                range = payload.value;
                velocity = payload.type;

                append_to_csv(&timestamp, object_index++, range / 100.0f, velocity / 100.0f);
            } else {
                log_error("Failed to extract range/velocity\n");
            }

            bytes_read -= TLV_PAYLOAD_LEN;
            memcpy(buffer, buffer + TLV_PAYLOAD_LEN, bytes_read);
        }
    }

    fclose(csv_file);
    gpiod_line_unexport(line);
    gpiod_chip_close(chip);
    close(uart_fd);

    return 0;
}
