#define UART_DEV "/dev/serial0"
#define BAUD 115200
#define TIMEOUT_INTERVAL 0.5
#define SELECT_TIMEOUT 2
#define LINE_BUFFER_SIZE 256

int uart_fd = -1;
struct termios termios_original, termios_modified;
char line_buffer[LINE_BUFFER_SIZE];

void handle_sigint(int signum) {
    printf("Received SIGINT, closing UART...\n");
    if (uart_fd != -1) {
        close(uart_fd);
        uart_fd = -1;
    }
}

void handle_sigterm(int signum) {
    printf("Received SIGTERM, closing UART...\n");
    if (uart_fd != -1) {
        close(uart_fd);
        uart_fd = -1;
    }
}

int configure_uart(int fd) {
    if (fd < 0) {
        return -1;
    }

    if (tcgetattr(fd, &termios_original) != 0) {
        perror("tcgetattr");
        return -1;
    }

    memset(&termios_modified, 0, sizeof(termios_modified));
    termios_modified.c_cflag = BAUD | CS8 | CLOCAL | CREAD;
    termios_modified.c_iflag = IGNPAR;
    termios_modified.c_oflag = 0;
    termios_modified.c_lflag = 0;

    if (tcsetattr(fd, TCSANOW, &termios_modified) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

int read_uart(int fd) {
    fd_set read_fds;
    struct timeval tv;
    int valread;

    if (fd < 0) {
        return -1;
    }

    TVINIT(&tv, NULL);
    tv.tv_sec = SELECT_TIMEOUT;
    tv.tv_usec = 0;

    FD_ZERO(&read_fds);
    FD_SET(fd, &read_fds);

    valread = select(fd + 1, &read_fds, NULL, NULL, &tv);

    if (valread <= 0) {
        if (valread == 0) {
            fprintf(stderr, "Timeout waiting for data on UART\n");
        } else {
            perror("select");
        }
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &termios_original) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return read(fd, line_buffer, LINE_BUFFER_SIZE - 1);
}

int main() {
    int ret;
    struct sigaction sa_int, sa_term;

    sa_int.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa_int, NULL);

    sa_term.sa_handler = handle_sigterm;
    sigaction(SIGTERM, &sa_term, NULL);

    uart_fd = open(UART_DEV, O_RDONLY | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("open");
        return 1;
    }

    if (configure_uart(uart_fd) < 0) {
        close(uart_fd);
        return 1;
    }

    while (1) {
        ret = read_uart(uart_fd);
        if (ret < 0) {
            continue;
        }

        line_buffer[ret] = '\0';

        char *token = strtok(line_buffer, ",");
        if (token == NULL || sscanf(token, "%*d,%lf") != 1) {
            fprintf(stderr, "Invalid line format: %s\n", line_buffer);
            continue;
        }

        token = strtok(NULL, "\n");
        if (token == NULL) {
            fprintf(stderr, "Unexpected end of line\n");
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char date_str[32];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(date_str, sizeof(date_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("Timestamp: %s, Range: %s meters\n", date_str, token);
    }

    close(uart_fd);
    return 0;
}

