#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define LEFT_PIN 4
#define MIDDLE_PIN 17
#define RIGHT_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

struct gpiod_chip *chip;
struct gpiod_line *left_line;
struct gpiod_line *middle_line;
struct gpiod_line *right_line;
int uart_fd;

void read_sensor_states(int *left, int *middle, int *right) {
    *left = gpiod_get_value(left_line);
    *middle = gpiod_get_value(middle_line);
    *right = gpiod_get_value(right_line);
}

void log_sensor_states() {
    int left, middle, right;
    read_sensor_states(&left, &middle, &right);

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    printf("%ld.%09ld: Left=%d, Middle=%d, Right=%d\n",
           ts.tv_sec, ts.tv_nsec, left, middle, right);

    if (left == 0 && middle == 0 && right == 0) {
        fprintf(stderr, "EMERGENCY STOP!\n");
    }
}

void init_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("Failed to open UART");
        exit(1);
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(uart_fd, TCIFLUSH);
    tcsetattr(uart_fd, TCSANOW, &options);
}

void cleanup_uart() {
    close(uart_fd);
}

void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiod", O_RDWR);
    if (!chip) {
        fprintf(stderr, "Failed to initialize gpiod\n");
        exit(1);
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
        fprintf(stderr, "Failed to get left sensor line\n");
        gpiod_chip_close(chip);
        exit(1);
    }
    gpiod_line_export(left_line, "left_sensor");
    gpiod_line_set_direction(left_line, GPIO_IN);
    gpiod_line_set_pull(left_line, GPIO_PULL_UP);

    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (!middle_line) {
        fprintf(stderr, "Failed to get middle sensor line\n");
        gpiod_chip_close(chip);
        exit(1);
    }
    gpiod_line_export(middle_line, "middle_sensor");
    gpiod_line_set_direction(middle_line, GPIO_IN);
    gpiod_line_set_pull(middle_line, GPIO_PULL_UP);

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        fprintf(stderr, "Failed to get right sensor line\n");
        gpiod_chip_close(chip);
        exit(1);
    }
    gpiod_line_export(right_line, "right_sensor");
    gpiod_line_set_direction(right_line, GPIO_IN);
    gpiod_line_set_pull(right_line, GPIO_PULL_UP);
}

void cleanup_gpio() {
    gpiod_line_unset_pull(right_line, GPIO_PULL_UP);
    gpiod_line_unset_pull(middle_line, GPIO_PULL_UP);
    gpiod_line_unset_pull(left_line, GPIO_PULL_UP);
    gpiod_line_free(right_line);
    gpiod_line_free(middle_line);
    gpiod_line_free(left_line);
    gpiod_chip_close(chip);
}

void send_emergency_stop() {
    const char *msg = "EMERGENCY STOP!\n";
    ssize_t bytes_written;

    while (1) {
        bytes_written = write(uart_fd, msg, strlen(msg));
        if (bytes_written < 0) {
            perror("Failed to write to UART");
            break;
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, [](int) {
        cleanup_uart();
        gpiod_chip_close(chip);
        exit(0);
    });

    signal(SIGTERM, [](int) {
        cleanup_uart();
        gpiod_chip_close(chip);
        exit(0);
    });

    init_uart();
    init_gpio();

    while (1) {
        log_sensor_states();
        sleep(0.1);
    }

    cleanup_gpio();
    cleanup_uart();

    return 0;
}

